CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_cancel_core(o text, w text, e text, r text, expected_version bigint, worker_value text, lease_value bytea, input_value bytea)
 RETURNS public.zasp_red_team_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;link_row public.zasp_security_agent_test_links%ROWTYPE;linked boolean;outcome_value text;checksum_value text;fingerprint_value text;original_lease_expires_at timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked cancellation input rejected';END IF;
 IF worker_value IS NULL THEN
  IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api') AND expected_version BETWEEN 1 AND 999999 AND lease_value IS NULL AND input_value IS NULL,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked cancellation principal rejected';END IF;
 ELSE
  IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker') AND worker_value~'^[a-z][a-z0-9.-]{2,127}$' AND octet_length(lease_value)=32 AND octet_length(input_value)=32 AND expected_version IS NULL,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked cancellation principal rejected';END IF;
 END IF;
 SELECT value INTO checksum_value FROM public.zasp_schema_metadata WHERE key='production_security_agent_existing_tests_checksum';
 SELECT value INTO fingerprint_value FROM public.zasp_schema_metadata WHERE key='production_security_agent_existing_tests_fingerprint';
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked cancellation release unavailable';END IF;
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r);
 linked:=FOUND;
 IF linked THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
  PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
  PERFORM 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link_row.run_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation parent unavailable';END IF;
  SELECT * INTO STRICT link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id,run_id,step_id)=(o,w,e,r,link_row.run_id,link_row.step_id) FOR UPDATE;
 ELSIF worker_value IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation association unavailable';
 END IF;
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='red team run not found';END IF;
 IF run_row.state IN('complete','failed','cancelled') OR worker_value IS NULL AND run_row.version IS DISTINCT FROM expected_version
  OR worker_value IS NOT NULL AND (run_row.state<>'leased' OR run_row.worker_id IS DISTINCT FROM worker_value OR run_row.lease_token IS DISTINCT FROM lease_value OR run_row.input_digest IS DISTINCT FROM input_value OR NOT run_row.cancel_requested OR run_row.lease_expires_at<=clock_timestamp()) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation authority changed';
 END IF;
 original_lease_expires_at:=run_row.lease_expires_at;
 IF linked THEN
  SELECT * INTO STRICT run_row FROM public.zasp_production_security_agent_existing_tests_cancel_transition(o,w,e,r);
 ELSE
  -- Preserve the legacy human API's queued/retryable versus leased behavior.
  UPDATE public.zasp_red_team_runs SET version=version+1,cancel_requested=true,state=CASE WHEN state IN('queued','retryable') THEN 'cancelled' ELSE state END,completed_at=CASE WHEN state IN('queued','retryable') THEN transaction_timestamp() ELSE completed_at END,error_code=CASE WHEN state IN('queued','retryable') THEN 'cancelled' ELSE error_code END,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO run_row;
 END IF;
 IF NOT COALESCE(public.zasp_production_security_agent_existing_tests_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked cancellation release unavailable';END IF;
 IF worker_value IS NOT NULL AND (original_lease_expires_at IS NULL OR original_lease_expires_at<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation lease expired';END IF;
 RETURN run_row;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_cancel_transition(o text, w text, e text, r text)
 RETURNS public.zasp_red_team_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;outcome_value text;
BEGIN
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR run_row.state IN('complete','failed','cancelled') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation state changed';END IF;
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,state)=(o,w,e,r,'started')) THEN outcome_value:='outcome_unknown';
 ELSIF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r)) THEN outcome_value:='cancelled_after_partial_execution';
 ELSE outcome_value:='cancelled_before_execution';END IF;
 UPDATE public.zasp_red_team_runs SET version=version+1,cancel_requested=true,state=CASE WHEN outcome_value='outcome_unknown' THEN 'failed' ELSE 'cancelled' END,error_code=CASE WHEN outcome_value='outcome_unknown' THEN 'outcome_unknown' ELSE 'cancelled' END,completed_at=clock_timestamp(),worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=clock_timestamp()
 WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO run_row;
 UPDATE public.zasp_security_agent_test_links SET cancellation_outcome=outcome_value,cancellation_recorded_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r) AND cancellation_outcome IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation receipt conflict';END IF;
 RETURN run_row;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_control_core(organization_value text, workspace_value text, environment_value text, actor_value text, idempotency_value text, target_value text, action_value text, enabled_value boolean, expected_version bigint, fresh_auth_expires_value timestamp with time zone, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE row_organization text;row_workspace text;row_environment text;row_action text;intent_value jsonb;intent_digest_value bytea;receipt_row zasp_security_agent_request_receipts%ROWTYPE;result_value jsonb;response_value jsonb;resource_value text;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR NOT zasp_valid_product_id(receipt_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' OR target_value NOT IN('environment','action') OR expected_version<0 OR fresh_auth_expires_value IS NULL OR fresh_auth_expires_value<=clock_timestamp() OR fresh_auth_expires_value>clock_timestamp()+interval '5 minutes 5 seconds' OR (target_value='action' AND action_value NOT IN('create_temporary_policy','isolate_session','rerun_test','revoke_integration_connection','run_test','start_attack_lab','update_finding_response')) OR (target_value<>'action' AND action_value<>'*') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent execution control mutation rejected';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_environments environment WHERE (environment.organization_id,environment.workspace_id,environment.id)=(organization_value,workspace_value,environment_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='security agent execution control scope not found';END IF;
  IF target_value='environment' THEN row_organization:=organization_value;row_workspace:=workspace_value;row_environment:=environment_value;row_action:='*';ELSE row_organization:=organization_value;row_workspace:=workspace_value;row_environment:=environment_value;row_action:=action_value;END IF;
  resource_value:=target_value||':'||row_action;intent_value:=jsonb_build_object('target',target_value,'action_key',row_action,'enabled',enabled_value,'expected_version',expected_version);intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'setSecurityAgentExecutionControl',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'setSecurityAgentExecutionControl',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>resource_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=clock_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch_row WHERE (switch_row.organization_id,switch_row.workspace_id,switch_row.environment_id,switch_row.action_key,switch_row.execution_enabled,switch_row.version)=(row_organization,row_workspace,row_environment,row_action,enabled_value,(receipt_row.response->>'version')::bigint)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent execution control replay conflict';END IF;
    RETURN receipt_row.response||jsonb_build_object('replayed',true);
  END IF;
  IF enabled_value AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent global execution disabled';END IF;
  IF enabled_value AND target_value='action' AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent environment execution disabled';END IF;
  result_value:=zasp_security_agent_set_kill_switch(row_organization,row_workspace,row_environment,row_action,enabled_value,expected_version,actor_value,audit_value,correlation_value);
  response_value:=result_value||jsonb_build_object('target',target_value,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
  INSERT INTO zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(organization_value,workspace_value,environment_value,actor_value,'setSecurityAgentExecutionControl',idempotency_value,resource_value,expected_version,intent_value,intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_controls(o text, w text, e text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent principal unavailable';END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test controls release unavailable';END IF;
 result_value:=public.zasp_security_agent_execution_control_detail(o,w,e);
 RETURN jsonb_set(result_value,'{actions}',(SELECT jsonb_agg(jsonb_build_object('target','action','action_key',k.key,'enabled',coalesce(s.execution_enabled,false),'version',coalesce(s.version,0)) ORDER BY k.key)
 FROM unnest(ARRAY['create_temporary_policy','isolate_session','rerun_test','revoke_integration_connection','run_test','start_attack_lab','update_finding_response']) k(key)
 LEFT JOIN public.zasp_security_agent_kill_switches s ON (s.organization_id,s.workspace_id,s.environment_id,s.action_key)=(o,w,e,k.key)));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_decide_approval(o text, w text, e text, a text, actor_value text, key_value text, expected_version bigint, decision_value text, fresh_auth_value timestamp with time zone, audit_value text, correlation_value text, receipt_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response_value jsonb;action_value text;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent principal unavailable';
 END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test approval release unavailable';
 END IF;
 SELECT s.action_key INTO action_value FROM public.zasp_security_agent_approvals p
 JOIN public.zasp_security_agent_steps s USING(organization_id,workspace_id,environment_id,run_id,step_id)
 WHERE (p.organization_id,p.workspace_id,p.environment_id,p.approval_id)=(o,w,e,a);
 IF action_value='start_attack_lab' THEN RETURN public.zasp_sa_attack_lab_decide_approval(o,w,e,a,actor_value,key_value,expected_version,decision_value,fresh_auth_value,audit_value,correlation_value,receipt_value,(SELECT value FROM public.zasp_schema_metadata WHERE key='production_security_agent_attack_lab_checksum'),(SELECT value FROM public.zasp_schema_metadata WHERE key='production_security_agent_attack_lab_fingerprint'));END IF;
 IF action_value IS DISTINCT FROM 'run_test' AND action_value IS DISTINCT FROM 'rerun_test' AND action_value IS DISTINCT FROM 'create_evidence_export' AND action_value IS DISTINCT FROM 'send_response_webhook' THEN
  response_value:=public.zasp_security_agent_decide_approval_v24(o,w,e,a,actor_value,key_value,expected_version,
   decision_value,fresh_auth_value,audit_value,correlation_value,receipt_value);
 ELSE
 -- Preserve the original principal/fresh-auth/requester/CAS/idempotency checks.
 -- Do not call v24: its projection rejects test actions after the mutation.
 response_value:=public.zasp_security_agent_decide_approval(o,w,e,a,actor_value,key_value,expected_version,
  decision_value,fresh_auth_value,audit_value,correlation_value,receipt_value);
 IF response_value->>'replayed' IS DISTINCT FROM 'true' THEN
 IF action_value='send_response_webhook' AND decision_value='approved' THEN PERFORM public.zasp_sa_webhook_approved(o,w,e,a);END IF;
 response_value:=response_value||public.zasp_production_security_agent_existing_tests_approval_value(o,w,e,a);
 -- Persist the displayed result in the same statement as the decision. Replay
 -- must return that receipt, not project mutable current approval state.
 UPDATE public.zasp_security_agent_request_receipts SET response=response_value
 WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,receipt_id)=
  (o,w,e,actor_value,'decideSecurityAgentApproval',key_value,a,receipt_value);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test approval receipt unavailable';END IF;
 END IF;
 END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test approval release unavailable';
 END IF;
 RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_evidence_snapshot(o text, w text, e text, r text, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE link_row public.zasp_security_agent_test_links%ROWTYPE;run_row public.zasp_red_team_runs%ROWTYPE;
 attempt_row public.zasp_red_team_attempts%ROWTYPE;candidate record;value jsonb;receipt jsonb;observations_value jsonb;
 before_value jsonb:='null'::jsonb;after_value jsonb:='null'::jsonb;unknown_value boolean;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(s),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test evidence scope rejected';END IF;
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test evidence link unavailable';END IF;
 FOR candidate IN SELECT 'after'::text side,link_row.test_run_id id,NULL::integer attempt
  UNION ALL SELECT 'before',link_row.baseline->>'run_id',(link_row.baseline->>'attempt')::integer WHERE link_row.baseline IS NOT NULL LOOP
  SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version)=(o,w,e,candidate.id,link_row.test_definition_id,link_row.test_definition_version);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test evidence run changed';END IF;
  value:=jsonb_build_object('run_id',run_row.run_id,'state',run_row.state,'attempt',run_row.attempt,'input_digest',encode(run_row.input_digest,'hex'),'verdict',run_row.verdict,'error_code',run_row.error_code,'completed_at',to_char(run_row.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'input_artifact',NULL,'output_artifact',NULL);
  IF candidate.side='before' AND (run_row.state<>'complete' OR run_row.verdict IS DISTINCT FROM 'fail' OR run_row.attempt IS DISTINCT FROM candidate.attempt OR run_row.completed_at IS NULL OR run_row.completed_at>=link_row.created_at) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test baseline completion changed';END IF;
  IF run_row.state='complete' THEN
   SELECT * INTO attempt_row FROM public.zasp_red_team_attempts WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,run_row.run_id,run_row.attempt);
   IF NOT FOUND OR run_row.completed_at IS NULL OR run_row.verdict IS NULL
    OR (attempt_row.input_digest,attempt_row.verdict,attempt_row.error_code,attempt_row.completed_at,attempt_row.evidence_reference,attempt_row.evidence_key,attempt_row.evidence_version_id,attempt_row.evidence_checksum,attempt_row.evidence_size)
     IS DISTINCT FROM (run_row.input_digest,run_row.verdict,run_row.error_code,run_row.completed_at,run_row.evidence_reference,run_row.evidence_key,run_row.evidence_version_id,run_row.evidence_checksum,run_row.evidence_size)
    OR NOT public.zasp_red_team_valid_input_artifact(o,w,e,attempt_row.input_artifact)
    OR attempt_row.evidence_checksum=decode(repeat('00',32),'hex')
    OR NOT public.zasp_discovery_s3_object_reference(attempt_row.evidence_reference)
    OR attempt_row.evidence_key IS DISTINCT FROM 'organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||run_row.run_id
    OR substring(attempt_row.evidence_reference FROM '^s3://[^/]+/(.+)$') IS DISTINCT FROM attempt_row.evidence_key
    OR length(attempt_row.evidence_version_id) NOT BETWEEN 1 AND 512 OR attempt_row.evidence_version_id~'[[:space:][:cntrl:]]'
    OR attempt_row.input_artifact->>'reference'=attempt_row.evidence_reference THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test evidence attempt changed';END IF;
   receipt:=jsonb_build_object('reference',attempt_row.evidence_reference,'key',attempt_row.evidence_key,'version_id',attempt_row.evidence_version_id,'sha256',encode(attempt_row.evidence_checksum,'hex'),'size_bytes',attempt_row.evidence_size);
   IF candidate.side='before' AND link_row.baseline IS DISTINCT FROM jsonb_build_object('schema_version','security-agent-test-baseline-v1','run_id',attempt_row.run_id,'attempt',attempt_row.attempt,'input_digest',encode(attempt_row.input_digest,'hex'),'completed_at',to_char(attempt_row.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'input_artifact',attempt_row.input_artifact,'output_artifact',receipt) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test baseline receipt changed';END IF;
   value:=value||jsonb_build_object('input_artifact',attempt_row.input_artifact,'output_artifact',receipt);
  END IF;
  IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations j WHERE (j.organization_id,j.workspace_id,j.environment_id,j.test_run_id)=(o,w,e,run_row.run_id)
   AND (j.attempt IS DISTINCT FROM run_row.attempt OR j.input_digest IS DISTINCT FROM run_row.input_digest OR NOT link_row.test_categories ? j.category
    OR (j.target_resolution->'comparison'->>'organization_id',j.target_resolution->'comparison'->>'workspace_id',j.target_resolution->'comparison'->>'environment_id',j.target_resolution->'comparison'->>'test_definition_id',j.target_resolution->'comparison'->>'test_definition_version',j.target_resolution->'comparison'->>'target_id',j.target_resolution->'comparison'->>'target_kind')
     IS DISTINCT FROM (o,w,e,link_row.test_definition_id,link_row.test_definition_version::text,link_row.target_id,link_row.target_kind)
    OR j.target_resolution->'comparison'->'categories' IS DISTINCT FROM link_row.test_categories)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test evidence invocation changed';END IF;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('schema_version','red-team-linked-observation-v1','run_id',j.test_run_id,'category',j.category,'credential_version_digest',encode(j.credential_version_digest,'hex'),'target_comparison',j.target_resolution->'comparison','observation',jsonb_build_object('http_status',j.http_status,'response_digest',encode(j.response_digest,'hex'),'protected',j.protected)) ORDER BY j.category),'[]'::jsonb)
   INTO observations_value FROM public.zasp_security_agent_test_invocations j WHERE (j.organization_id,j.workspace_id,j.environment_id,j.test_run_id,j.attempt,j.input_digest,j.state,j.http_status)=(o,w,e,run_row.run_id,run_row.attempt,run_row.input_digest,'completed',200);
  SELECT EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations j WHERE (j.organization_id,j.workspace_id,j.environment_id,j.test_run_id,j.state)=(o,w,e,run_row.run_id,'started')) INTO unknown_value;
  value:=value||jsonb_build_object('observations',observations_value,'outcome_unknown',unknown_value);
  IF candidate.side='after' THEN after_value:=value;ELSE before_value:=value;END IF;
 END LOOP;
 RETURN jsonb_build_object('schema_version','security-agent-test-evidence-snapshot-v1','organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'step_id',s,
  'definition_id',link_row.test_definition_id,'definition_version',link_row.test_definition_version,'target_id',link_row.target_id,'target_kind',link_row.target_kind,'categories',link_row.test_categories,'before',before_value,'after',after_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_execute_run(o text, w text, e text, r text, worker_value text, lease_value text, audit_value text, correlation_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_security_agent_runs%ROWTYPE;plan_row public.zasp_security_agent_plans%ROWTYPE;
 definition_row public.zasp_security_agent_definitions%ROWTYPE;step_row public.zasp_security_agent_steps%ROWTYPE;
 test_count integer:=0;test_step text;test_intent boolean;result_value jsonb;
 deadline_value timestamptz;budget_deadline timestamptz;target_deadline timestamptz;credential_deadline timestamptz;runtime_deadline timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker'),false) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='existing test execution principal rejected';
 END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test execution release unavailable';
 END IF;
 IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN
  result_value:=public.zasp_security_agent_budget_stop_result(o,w,e,r,'execute');
 ELSE
  SELECT * INTO STRICT run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  SELECT deadline_at INTO STRICT budget_deadline FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  deadline_value:=LEAST(run_row.lease_expires_at,budget_deadline);
  SELECT * INTO plan_row FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR SHARE;
  FOR step_row IN SELECT * FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) ORDER BY step_index FOR UPDATE LOOP
   IF step_row.action_key IN('run_test','rerun_test') THEN test_count:=test_count+1;test_step:=step_row.step_id;END IF;
  END LOOP;
  SELECT * INTO definition_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,run_row.definition_id,run_row.definition_version) AND deleted_at IS NULL FOR SHARE;
  deadline_value:=LEAST(deadline_value,plan_row.expires_at,
   (SELECT min(a.expires_at) FROM public.zasp_security_agent_approvals a JOIN public.zasp_security_agent_steps s USING(organization_id,workspace_id,environment_id,run_id,step_id)
    WHERE (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.state,s.state)=(o,w,e,r,'approved','authorized')));
  IF definition_row.body->>'trigger_kind'='runtime_decision' THEN
   SELECT credential.expires_at INTO STRICT runtime_deadline FROM public.zasp_runtime_gateway_events event
    JOIN public.zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.credential_id)
    JOIN public.zasp_security_agent_trigger_receipts trigger ON (trigger.organization_id,trigger.workspace_id,trigger.environment_id,trigger.trigger_id,trigger.trigger_version)=(event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id',event.sequence)
    WHERE (trigger.organization_id,trigger.workspace_id,trigger.environment_id,trigger.run_id)=(o,w,e,r);
   deadline_value:=LEAST(deadline_value,runtime_deadline);
  END IF;
  test_intent:=COALESCE(definition_row.body ? 'existing_test' OR definition_row.body->'allowed_actions' ?| ARRAY['run_test','rerun_test'],false)
   OR test_count>0 OR EXISTS(SELECT 1 FROM jsonb_array_elements(CASE WHEN jsonb_typeof(plan_row.plan->'steps')='array' THEN plan_row.plan->'steps' ELSE '[]'::jsonb END) item WHERE item->>'action' IN('run_test','rerun_test'));
  IF test_intent THEN
   IF test_count<>1 OR budget_deadline IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test execution intent changed';END IF;
   PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,test_step);
   PERFORM public.zasp_production_security_agent_run_context_test_binding(o,w,e,run_row.definition_id,run_row.definition_version);
   SELECT target.fresh_until,credential.valid_until INTO STRICT target_deadline,credential_deadline
    FROM public.zasp_red_team_definitions test
    JOIN public.zasp_inventory_entities target ON (target.organization_id,target.workspace_id,target.environment_id,target.id)=(test.organization_id,test.workspace_id,test.environment_id,test.target_id)
    JOIN public.zasp_attack_lab_credential_bindings credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.target_id,credential.credential_reference,credential.state)=(target.organization_id,target.workspace_id,target.environment_id,target.id,target.winning_attributes->'red_team'->>'credential_reference','active')
    WHERE (test.organization_id,test.workspace_id,test.environment_id,test.definition_id)=(o,w,e,definition_row.body->'existing_test'->>'definition_id');
   deadline_value:=LEAST(deadline_value,plan_row.expires_at,target_deadline,credential_deadline,
    (SELECT min(expires_at) FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,test_step)));
   result_value:=public.zasp_security_agent_test_dispatch(o,w,e,r,worker_value,lease_value,audit_value,correlation_value);
   IF result_value->>'state'='running' THEN
    PERFORM public.zasp_production_security_agent_existing_tests_authorize_invocation(o,w,e,r,test_step);
    PERFORM public.zasp_production_security_agent_run_context_test_binding(o,w,e,run_row.definition_id,run_row.definition_version);
   END IF;
  ELSE
   result_value:=public.zasp_security_agent_execute_run_v24(o,w,e,r,worker_value,lease_value,audit_value,correlation_value);
  END IF;
 END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test execution release unavailable';
 END IF;
 -- Dispatch clears the lease. Validate the captured authority after its final
 -- writes and our final readiness work, without relying on cleared columns.
 IF result_value->>'state'<>'needs_human' AND (deadline_value IS NULL OR deadline_value<=clock_timestamp()) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test execution authority expired';
 END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_finish_prepare(o text, w text, e text, r text, worker_value text, lease_value text, prepared_value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE context_value jsonb;result_value jsonb:=prepared_value->'result';
BEGIN
 context_value:=public.zasp_production_security_agent_existing_tests_recheck_context(o,w,e,r,worker_value,lease_value);
 IF context_value ? 'budget_stop' THEN RAISE EXCEPTION USING ERRCODE='PZ001',MESSAGE='existing test preparation stopped';END IF;
 IF context_value->>'input_digest' IS DISTINCT FROM prepared_value->>'input_digest'
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND expires_at>clock_timestamp()) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test preparation authority changed';
 END IF;
 UPDATE public.zasp_security_agent_runs SET state=result_value->>'state',plan_hash=decode(substring(result_value->>'plan_hash' FROM 8),'hex'),
  available_at=CASE WHEN result_value->>'state'='queued' THEN clock_timestamp() ELSE available_at END,
  lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=clock_timestamp()
 WHERE (organization_id,workspace_id,environment_id,run_id,state,lease_owner,lease_token)=(o,w,e,r,'planning',worker_value,lease_value)
  AND lease_expires_at>clock_timestamp() AND version=(result_value->>'version')::bigint-1;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test preparation lease lost';END IF;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_global_read(expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 LOCK TABLE public.zasp_security_agent_global_control_receipts,public.zasp_security_agent_kill_switches,public.zasp_security_agent_audit IN ACCESS SHARE MODE;
 IF NOT public.zasp_production_security_agent_existing_tests_global_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='global operator authority unavailable';END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='global operator release unavailable';END IF;
 SELECT jsonb_build_object('enabled',execution_enabled,'version',version,'replayed',false) INTO result_value
 FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*');
 IF result_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='global control missing';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_global_set(expected_checksum text, expected_fingerprint text, enabled_value boolean, expected_version bigint, request_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE control_row public.zasp_security_agent_kill_switches%ROWTYPE; receipt_row public.zasp_security_agent_global_control_receipts%ROWTYPE; result_value jsonb; body_value jsonb;
BEGIN
 LOCK TABLE public.zasp_security_agent_global_control_receipts IN ROW EXCLUSIVE MODE;
 LOCK TABLE public.zasp_security_agent_kill_switches IN ACCESS SHARE MODE;
 LOCK TABLE public.zasp_security_agent_audit IN ROW EXCLUSIVE MODE;
 IF NOT public.zasp_production_security_agent_existing_tests_global_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='global operator authority unavailable';END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='global operator release unavailable';END IF;
 IF NOT COALESCE(enabled_value IS NOT NULL AND expected_version>0 AND expected_version<9223372036854775807
  AND public.zasp_valid_product_id(request_value) AND octet_length(correlation_value) BETWEEN 1 AND 128 AND correlation_value COLLATE "C" ~ '^[!-~]+$',false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='global operator intent rejected';
 END IF;
 SELECT * INTO control_row FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='global control missing';END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_global_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='global operator authority unavailable';END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='global operator release unavailable';END IF;
 SELECT * INTO receipt_row FROM public.zasp_security_agent_global_control_receipts WHERE request_id=request_value;
 IF FOUND THEN
  IF (receipt_row.caller_session,receipt_row.enabled,receipt_row.expected_version,receipt_row.correlation_id) IS DISTINCT FROM (session_user::text,enabled_value,expected_version,correlation_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='global operator replay intent conflict';END IF;
  RETURN receipt_row.result||jsonb_build_object('replayed',true);
 END IF;
 IF control_row.version<>expected_version THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='global operator version conflict';END IF;
 result_value:=jsonb_build_object('enabled',enabled_value,'version',control_row.version+1,'replayed',false);
 INSERT INTO public.zasp_security_agent_global_control_receipts(request_id,caller_session,enabled,expected_version,correlation_id,resulting_version,result)
 VALUES(request_value,session_user,enabled_value,expected_version,correlation_value,control_row.version+1,result_value) RETURNING * INTO receipt_row;
 UPDATE public.zasp_security_agent_kill_switches SET execution_enabled=enabled_value,version=control_row.version+1,updated_by=session_user,updated_at=transaction_timestamp()
 WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*');
 body_value:=public.zasp_production_security_agent_existing_tests_global_intent(receipt_row);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,actor_id,event_kind,event_digest,body)
 VALUES('*','*','*',request_value,correlation_value,session_user,'kill_switch_changed',digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
 IF NOT public.zasp_production_security_agent_existing_tests_global_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='global operator authority unavailable';END IF;
 IF NOT public.zasp_production_security_agent_existing_tests_readiness(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='global operator release unavailable';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_invocation_comple(o text, w text, e text, r text, attempt_value integer, lease_value bytea, category_value text, request_digest_value bytea, status_value integer, response_digest_value bytea, protected_value boolean, credential_version_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;prior public.zasp_security_agent_test_invocations%ROWTYPE;
BEGIN
 IF NOT public.zasp_red_team_principal_ready('zasp_red_team_adapter') OR NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND attempt_value BETWEEN 1 AND 5 AND octet_length(lease_value)=32 AND octet_length(request_digest_value)=32 AND octet_length(response_digest_value)=32 AND octet_length(credential_version_value)=32 AND credential_version_value<>decode(repeat('00',32),'hex')
  AND category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information')
  AND status_value BETWEEN 200 AND 599 AND (status_value=200 AND protected_value IS NOT NULL OR status_value<>200 AND protected_value IS NULL),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked invocation response rejected';
 END IF;
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation run unavailable';END IF;
 SELECT * INTO prior FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,attempt,category)=(o,w,e,r,attempt_value,category_value) FOR UPDATE;
 IF NOT FOUND OR prior.input_digest IS DISTINCT FROM run_row.input_digest OR prior.request_digest IS DISTINCT FROM request_digest_value OR prior.lease_digest IS DISTINCT FROM digest(lease_value,'sha256') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation response association rejected';
 END IF;
 IF prior.state='completed' THEN
  IF prior.http_status IS DISTINCT FROM status_value OR prior.response_digest IS DISTINCT FROM response_digest_value OR prior.protected IS DISTINCT FROM protected_value OR prior.credential_version_digest IS DISTINCT FROM credential_version_value THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation response conflict';
  END IF;
 ELSE
  -- This records a known response, including one arriving after cancellation or
  -- lease expiry. It grants no new execution authority and changes no run state.
  UPDATE public.zasp_security_agent_test_invocations SET state='completed',completed_at=clock_timestamp(),http_status=status_value,response_digest=response_digest_value,protected=protected_value,credential_version_digest=credential_version_value
  WHERE (organization_id,workspace_id,environment_id,test_run_id,attempt,category,state)=(o,w,e,r,attempt_value,category_value,'started');
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation response changed';END IF;
 END IF;
 RETURN public.zasp_production_security_agent_existing_tests_invocation_receipt(o,w,e,r,attempt_value,category_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_production_security_agent_existing_tests_invocation_comple(o text, w text, e text, r text, attempt_value integer, lease_value bytea, category_value text, request_digest_value bytea, status_value integer, response_digest_value bytea, protected_value boolean, credential_version_value bytea, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
