CREATE OR REPLACE FUNCTION public.zasp_red_team_list_definitions(organization_value text, workspace_value text, environment_value text, after_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR limit_value NOT BETWEEN 1 AND 100 OR after_value IS NOT NULL AND NOT zasp_valid_product_id(after_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team list rejected';END IF;
 SELECT jsonb_build_object('items',COALESCE(jsonb_agg(zasp_red_team_definition_json(definition_row) ORDER BY definition_id),'[]'::jsonb),'next_cursor',CASE WHEN count(*)=limit_value THEN max(definition_id) END) INTO result_value FROM (SELECT * FROM zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND (after_value IS NULL OR definition_id>after_value) ORDER BY definition_id LIMIT limit_value) definition_row;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_list_runs(organization_value text, workspace_value text, environment_value text, before_value timestamp with time zone, before_id_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR limit_value NOT BETWEEN 1 AND 100 OR before_value IS NULL AND before_id_value IS NOT NULL OR before_value IS NOT NULL AND NOT zasp_valid_product_id(before_id_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team run list rejected';END IF;
 WITH visible AS (
   SELECT * FROM zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND (before_value IS NULL OR (queued_at,run_id)<(before_value,before_id_value)) ORDER BY queued_at DESC,run_id DESC LIMIT limit_value
 ), cursor_row AS (
   SELECT queued_at,run_id FROM visible ORDER BY queued_at,run_id LIMIT 1
 ) SELECT jsonb_build_object('items',COALESCE((SELECT jsonb_agg(zasp_red_team_run_json(run_row) ORDER BY queued_at DESC,run_id DESC) FROM visible run_row),'[]'::jsonb),'next_cursor',CASE WHEN (SELECT count(*) FROM visible)=limit_value THEN (SELECT jsonb_build_object('queued_at',to_char(queued_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'id',run_id) FROM cursor_row) END) INTO result_value;
 RETURN result_value;END
$function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_mutation_result(organization_value text, workspace_value text, environment_value text, actor_value text, operation_value text, resource_value text, correlation_value text, idempotency_value text, body_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE audit_value text;receipt_value text;event_value text;result_value jsonb;
BEGIN
 IF operation_value NOT IN('createTest','updateTest','runTest','cancelTestRun') OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(resource_value) OR NOT zasp_valid_product_id(correlation_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR jsonb_typeof(body_value)<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team mutation result rejected';END IF;
 audit_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'red_team_audit',actor_value||chr(31)||operation_value||chr(31)||idempotency_value);
 receipt_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'red_team_receipt',actor_value||chr(31)||operation_value||chr(31)||idempotency_value);
 event_value:=CASE operation_value WHEN 'createTest' THEN 'red_team_definition_created' WHEN 'updateTest' THEN 'red_team_definition_updated' WHEN 'runTest' THEN 'red_team_run_queued' ELSE 'red_team_run_cancelled' END;
 result_value:=jsonb_build_object('body',body_value,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
 INSERT INTO zasp_red_team_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,receipt_id,actor_id,event_kind,resource_id,event_digest,body) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,receipt_value,actor_value,event_value,resource_value,digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_register_principals(migration_principal text, worker_principal text, outbox_principal text, adapter_principal text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE principals text[]:=ARRAY[worker_principal,outbox_principal,adapter_principal];authorities text[]:=ARRAY['zasp_red_team_worker','zasp_red_team_outbox_worker','zasp_red_team_adapter'];index_value integer;role_value record;
BEGIN
  IF migration_principal<>session_user OR cardinality(ARRAY(SELECT DISTINCT unnest(ARRAY[migration_principal,worker_principal,outbox_principal,adapter_principal])))<>4 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team principals rejected';END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('zasp-red-team-principal-registration',0));
  FOR index_value IN 1..3 LOOP
    SELECT role_row.oid,role_row.rolcanlogin,role_row.rolsuper,role_row.rolcreatedb,role_row.rolcreaterole,role_row.rolreplication,role_row.rolinherit,role_row.rolbypassrls INTO role_value FROM pg_roles role_row WHERE role_row.rolname=principals[index_value];
    IF NOT FOUND OR NOT role_value.rolcanlogin OR role_value.rolsuper OR role_value.rolcreatedb OR role_value.rolcreaterole OR role_value.rolreplication OR NOT role_value.rolinherit OR role_value.rolbypassrls OR EXISTS(SELECT 1 FROM pg_auth_members membership JOIN pg_roles granted ON granted.oid=membership.roleid WHERE membership.member=role_value.oid AND granted.rolname LIKE 'zasp_%' AND granted.rolname<>authorities[index_value]) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='red team principal rejected';END IF;
    EXECUTE format('GRANT %I TO %I',authorities[index_value],principals[index_value]);
    INSERT INTO zasp_red_team_principal_bindings(principal_name,authority_role) VALUES(principals[index_value],authorities[index_value]) ON CONFLICT(principal_name) DO UPDATE SET authority_role=excluded.authority_role WHERE zasp_red_team_principal_bindings.authority_role=excluded.authority_role;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='red team principal conflict';END IF;
  END LOOP;
  RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_update_definition(organization_value text, workspace_value text, environment_value text, actor_value text, idempotency_value text, definition_value text, expected_version bigint, name_value text, target_value text, target_kind_value text, categories_value jsonb, safety_value jsonb, enabled_value boolean, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE intent_value jsonb;digest_value bytea;receipt_row zasp_red_team_request_receipts%ROWTYPE;updated_row zasp_red_team_definitions%ROWTYPE;result_value jsonb;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR expected_version NOT BETWEEN 1 AND 999999 OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(definition_value) OR NOT zasp_valid_product_id(correlation_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' OR NOT zasp_red_team_definition_valid(name_value,target_value,target_kind_value,categories_value,safety_value) OR NOT zasp_red_team_safety_authorized(organization_value,workspace_value,environment_value,target_value,target_kind_value,safety_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team definition rejected';END IF;
 intent_value:=jsonb_build_object('definition_id',definition_value,'expected_version',expected_version,'name',name_value,'target_id',target_value,'target_kind',target_kind_value,'categories',categories_value,'safety',safety_value,'enabled',enabled_value);digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'updateTest',idempotency_value),0));
 SELECT * INTO receipt_row FROM zasp_red_team_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'updateTest',idempotency_value);IF FOUND THEN IF receipt_row.resource_id<>definition_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>digest_value OR receipt_row.expires_at<=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='red team definition replay rejected';END IF;RETURN receipt_row.result||jsonb_build_object('replayed',true);END IF;
 UPDATE zasp_red_team_definitions SET version=version+1,name=name_value,target_id=target_value,target_kind=target_kind_value,categories=categories_value,safety=safety_value,enabled=enabled_value,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(organization_value,workspace_value,environment_value,definition_value,expected_version) RETURNING * INTO updated_row;IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='red team definition version conflict';END IF;result_value:=zasp_red_team_mutation_result(organization_value,workspace_value,environment_value,actor_value,'updateTest',definition_value,correlation_value,idempotency_value,zasp_red_team_definition_json(updated_row));
 INSERT INTO zasp_red_team_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent_digest,audit_id,correlation_id,receipt_id,result) VALUES(organization_value,workspace_value,environment_value,actor_value,'updateTest',idempotency_value,definition_value,expected_version,digest_value,result_value->>'audit_id',result_value->>'correlation_id',result_value->>'receipt_id',result_value);RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_red_team_valid_input_artifact(organization_value text, workspace_value text, environment_value text, input_value jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE reference_value text; key_value text; prefix_value text;
BEGIN
 IF input_value IS NULL OR jsonb_typeof(input_value)<>'object' THEN RETURN false;END IF;
 IF (SELECT count(*) FROM jsonb_object_keys(input_value))<>4 OR NOT input_value ?& ARRAY['reference','version_id','sha256','size_bytes']
 OR jsonb_typeof(input_value->'reference')<>'string' OR jsonb_typeof(input_value->'version_id')<>'string' OR jsonb_typeof(input_value->'sha256')<>'string' OR jsonb_typeof(input_value->'size_bytes')<>'number'
 OR input_value->>'sha256' !~ '^[a-f0-9]{64}$' OR input_value->>'sha256'=repeat('0',64)
 OR length(input_value->>'version_id') NOT BETWEEN 1 AND 512 OR input_value->>'version_id' ~ '[[:space:][:cntrl:]]'
 OR input_value->>'size_bytes' !~ '^[1-9][0-9]{0,4}$' THEN RETURN false;END IF;
 IF (input_value->>'size_bytes')::bigint>65536 THEN RETURN false;END IF;
 reference_value:=input_value->>'reference';
 IF NOT zasp_discovery_s3_object_reference(reference_value) THEN RETURN false;END IF;
 key_value:=substring(reference_value FROM '^s3://[^/]+/(.+)$');
 prefix_value:='organizations/'||organization_value||'/workspaces/'||workspace_value||'/environments/'||environment_value||'/artifacts/';
 RETURN COALESCE(zasp_valid_product_id(organization_value) AND zasp_valid_product_id(workspace_value) AND zasp_valid_product_id(environment_value) AND left(key_value,length(prefix_value))=prefix_value AND zasp_valid_product_id(substring(key_value FROM length(prefix_value)+1)),false);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_reference_authorization_exact_replay(organization_value text, workspace_value text, environment_value text, principal_value text, integration_value text, idempotency_value text, intent_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_digest bytea; prior_response jsonb; requested_digest bytea;
BEGIN
  requested_digest:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  SELECT request_digest,response INTO prior_digest,prior_response FROM zasp_workflow_idempotency
   WHERE organization_id=organization_value AND workspace_id=workspace_value AND environment_id=environment_value
     AND principal_id=principal_value AND operation='completeIntegrationReferenceAuthorization' AND idempotency_key=idempotency_value;
  IF NOT FOUND THEN RETURN jsonb_build_object('found',false,'result',NULL); END IF;
  IF prior_digest<>requested_digest OR prior_response->'body'->>'id'<>integration_value THEN
    RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='reference authorization replay conflict';
  END IF;
  RETURN jsonb_build_object('found',true,'result',prior_response||jsonb_build_object('replayed',true));
END $function$

CREATE OR REPLACE FUNCTION public.zasp_reference_authorization_replay(organization_value text, workspace_value text, environment_value text, principal_value text, integration_value text, idempotency_value text, expected_version_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_response jsonb;
BEGIN
  IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value)
    OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(integration_value) OR NOT zasp_valid_product_id(principal_value)
    OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR expected_version_value NOT BETWEEN 1 AND 1000000 THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid reference authorization replay';
  END IF;
  SELECT response INTO prior_response FROM zasp_workflow_idempotency
   WHERE organization_id=organization_value AND workspace_id=workspace_value AND environment_id=environment_value
     AND principal_id=principal_value AND operation='completeIntegrationReferenceAuthorization' AND idempotency_key=idempotency_value;
  IF NOT FOUND THEN RETURN jsonb_build_object('found',false,'result',NULL); END IF;
  IF prior_response->'body'->>'id'<>integration_value OR (prior_response->>'version')::bigint<>expected_version_value+1 THEN
    RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='reference authorization replay conflict';
  END IF;
  RETURN jsonb_build_object('found',true,'result',prior_response||jsonb_build_object('replayed',true));
END $function$

CREATE OR REPLACE FUNCTION public.zasp_risk_attack_path_get(requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    path "public"."zasp_risk_attack_paths"%ROWTYPE;
    nodes jsonb;
    evidence jsonb;
    node_count integer;
    evidence_count integer;
    first_node text;
    last_node text;
BEGIN
    SELECT * INTO path FROM "public"."zasp_risk_attack_paths" AS candidate
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id
       AND "environment_id"=requested_environment_id AND "id"=requested_id
       AND "public"."zasp_risk_attack_path_valid"(candidate);
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk path missing'; END IF;
    SELECT count(*), COALESCE(jsonb_agg("node_id" ORDER BY "position"),'[]'::jsonb),
           (array_agg("node_id" ORDER BY "position"))[1], (array_agg("node_id" ORDER BY "position" DESC))[1]
      INTO node_count,nodes,first_node,last_node FROM "public"."zasp_risk_attack_path_nodes"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id
       AND "environment_id"=requested_environment_id AND "path_id"=requested_id;
    SELECT count(*), COALESCE(jsonb_agg("evidence_id" ORDER BY "position"),'[]'::jsonb)
      INTO evidence_count,evidence FROM "public"."zasp_risk_attack_path_evidence"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id
       AND "environment_id"=requested_environment_id AND "path_id"=requested_id;
    RETURN jsonb_build_object('id',path."id",'entry_id',path."entry_id",'sink_id',path."sink_id",'node_ids',nodes,
        'state',path."state",'evidence_ids',evidence,'blocked_edge',path."blocked_edge",'version',path."version",
        'created_at',path."created_at",'updated_at',path."updated_at");
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_risk_break_options_get(requested_path_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE option_count integer; response jsonb; path_exists boolean;
BEGIN
    SELECT EXISTS(SELECT 1 FROM "public"."zasp_risk_attack_paths" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_path_id AND "public"."zasp_risk_attack_path_valid"(candidate)) INTO path_exists;
    IF NOT path_exists THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk path missing'; END IF;
    SELECT count(*), jsonb_build_object('items',COALESCE(jsonb_agg(jsonb_build_object('path_id',"path_id",'target_id',"target_id",'evidence_id',"evidence_id",'kind',"kind",'rank',"rank") ORDER BY "rank"),'[]'::jsonb))
      INTO option_count,response FROM "public"."zasp_risk_break_options"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "path_id"=requested_path_id;
    IF option_count>8
       OR EXISTS (SELECT 1 FROM "public"."zasp_risk_break_options" WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "path_id"=requested_path_id HAVING count(*)>0 AND (min("rank")<>1 OR max("rank")<>count(*)))
       OR EXISTS (SELECT 1 FROM "public"."zasp_risk_break_options" AS option WHERE option."organization_id"=requested_organization_id AND option."workspace_id"=requested_workspace_id AND option."environment_id"=requested_environment_id AND option."path_id"=requested_path_id AND option."kind"='remove_node' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_attack_path_nodes" AS node WHERE node."organization_id"=option."organization_id" AND node."workspace_id"=option."workspace_id" AND node."environment_id"=option."environment_id" AND node."path_id"=option."path_id" AND node."node_id"=option."target_id"))
       OR EXISTS (SELECT 1 FROM "public"."zasp_risk_break_options" AS option WHERE option."organization_id"=requested_organization_id AND option."workspace_id"=requested_workspace_id AND option."environment_id"=requested_environment_id AND option."path_id"=requested_path_id AND NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_attack_path_evidence" AS parent_evidence WHERE parent_evidence."organization_id"=option."organization_id" AND parent_evidence."workspace_id"=option."workspace_id" AND parent_evidence."environment_id"=option."environment_id" AND parent_evidence."path_id"=option."path_id" AND parent_evidence."evidence_id"=option."evidence_id")) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid stored break options';
    END IF;
    RETURN response;
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_risk_finding_get(requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
AS $function$
DECLARE
    finding "public"."zasp_risk_findings"%ROWTYPE;
    evidence jsonb;
    factors jsonb;
    evidence_count integer;
    factor_count integer;
BEGIN
    SELECT * INTO finding FROM "public"."zasp_risk_findings" AS candidate
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id
       AND "environment_id"=requested_environment_id AND "id"=requested_id
       AND "public"."zasp_risk_finding_visible"(candidate);
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing'; END IF;
    SELECT count(*), COALESCE(jsonb_agg("evidence_id" ORDER BY "position"),'[]'::jsonb)
      INTO evidence_count, evidence
      FROM "public"."zasp_risk_finding_evidence"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id
       AND "environment_id"=requested_environment_id AND "finding_id"=requested_id;
    SELECT count(*), COALESCE(jsonb_agg(jsonb_build_object('name',"name",'evidence_id',"evidence_id") ORDER BY "position"),'[]'::jsonb)
      INTO factor_count, factors
      FROM "public"."zasp_risk_finding_factors"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id
       AND "environment_id"=requested_environment_id AND "finding_id"=requested_id;
    IF evidence_count NOT BETWEEN 1 AND 64 OR factor_count NOT BETWEEN 0 AND 16
       OR EXISTS (SELECT 1 FROM "public"."zasp_risk_finding_evidence" WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "finding_id"=requested_id HAVING min("position")<>1 OR max("position")<>count(*))
       OR EXISTS (SELECT 1 FROM "public"."zasp_risk_finding_factors" WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "finding_id"=requested_id HAVING min("position")<>1 OR max("position")<>count(*))
       OR EXISTS (SELECT 1 FROM "public"."zasp_risk_finding_factors" AS factor WHERE factor."organization_id"=requested_organization_id AND factor."workspace_id"=requested_workspace_id AND factor."environment_id"=requested_environment_id AND factor."finding_id"=requested_id AND NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_finding_evidence" AS parent_evidence WHERE parent_evidence."organization_id"=factor."organization_id" AND parent_evidence."workspace_id"=factor."workspace_id" AND parent_evidence."environment_id"=factor."environment_id" AND parent_evidence."finding_id"=factor."finding_id" AND parent_evidence."evidence_id"=factor."evidence_id")) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid stored risk finding projection';
    END IF;
    RETURN jsonb_strip_nulls(jsonb_build_object(
        'id',finding."id",'source',finding."source",'rule',finding."rule",'title',finding."title",
        'severity',finding."severity",'status',finding."status",'agent_id',finding."agent_id",'path_id',finding."path_id",
        'compliance_context',finding."compliance_context",'evidence_ids',evidence,'risk_factors',factors,
        'acceptance_reason',finding."acceptance_reason",'version',finding."version",
        'created_at',finding."created_at",'updated_at',finding."updated_at"));
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">60)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_ack_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, provider_ack_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE delivery_row zasp_runtime_deliveries%ROWTYPE;result_value jsonb;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR octet_length(provider_ack_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id,existing.batch_generation,existing.message_id,existing.message_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value) FOR UPDATE;
 IF FOUND AND delivery_row.disposition='acked' AND delivery_row.provider_ack_digest=provider_ack_digest_value THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',true);END IF;
 IF NOT FOUND OR delivery_row.disposition<>'ack_pending' OR delivery_row.lease_owner<>worker_value OR delivery_row.lease_token<>lease_token_value OR delivery_row.lease_expires_at<=transaction_timestamp() OR delivery_row.visibility_deadline<=transaction_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) AND authority_row.state IN('succeeded','failed','quarantined') AND authority_row.completion_digest IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 UPDATE zasp_runtime_deliveries existing SET disposition='acked',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,provider_ack_digest=provider_ack_digest_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_ack_outbox(topic_value text, organization_value text, workspace_value text, environment_value text, outbox_value text, worker_value text, lease_token_value text, provider_ack_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;remaining_count integer;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF topic_value<>'runtime-events' OR provider_ack_value !~ '^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox acknowledgement';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox WHERE (organization_id,workspace_id,environment_id,id,topic)=(organization_value,workspace_value,environment_value,outbox_value,topic_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease missing';END IF;
 result:=zasp_discovery_ack_outbox(organization_value,workspace_value,environment_value,outbox_value,worker_value,lease_token_value,provider_ack_value);
 SELECT count(*) INTO remaining_count FROM zasp_discovery_outbox WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN result||jsonb_build_object('remaining_count',remaining_count);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_authenticate_gateway_enrollment(locator_value bytea, secret_value bytea, audience_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE locator_hash bytea;candidate_scope record;token_row zasp_gateway_enrollment_tokens%ROWTYPE;device_row zasp_gateway_devices%ROWTYPE;computed_hash bytea;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_gateway_control') OR octet_length(locator_value)<>16 OR octet_length(secret_value)<>32 OR audience_value<>'runtime-gateway-enroll' THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='gateway authentication rejected';END IF;
 locator_hash:=digest(locator_value,'sha256');
 SELECT token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.device_id INTO candidate_scope FROM zasp_gateway_enrollment_tokens token_value WHERE token_value.locator_digest=locator_hash;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='gateway authentication rejected';END IF;
 PERFORM zasp_authorization80_worker.gateway_organization_lock(candidate_scope.organization_id);
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate_scope.organization_id,candidate_scope.workspace_id,candidate_scope.environment_id,candidate_scope.device_id),0));
 PERFORM zasp_authorization80_worker.gateway_organization_lock(candidate_scope.organization_id);
 SELECT token_value.* INTO token_row FROM zasp_gateway_enrollment_tokens token_value WHERE token_value.locator_digest=locator_hash FOR UPDATE;
 SELECT device_value.* INTO device_row FROM zasp_gateway_devices device_value WHERE (device_value.organization_id,device_value.workspace_id,device_value.environment_id,device_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.device_id) FOR UPDATE;
 computed_hash:=zasp_runtime_gateway_enrollment_secret_hash(audience_value,token_row.id,token_row.token_generation,token_row.salt,secret_value);
 IF token_row.format_version<>1 OR token_row.audience<>audience_value OR token_row.revoked_at IS NOT NULL OR token_row.expires_at<=clock_timestamp() OR device_row.state NOT IN('pending','active') OR digest(token_row.token_hash||computed_hash,'sha256')<>digest(token_row.token_hash||token_row.token_hash,'sha256') OR EXISTS(SELECT 1 FROM zasp_gateway_enrollment_tokens newer WHERE (newer.organization_id,newer.workspace_id,newer.environment_id,newer.device_id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.device_id) AND newer.token_generation>token_row.token_generation) THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='gateway authentication rejected';END IF;
 RETURN jsonb_build_object('organization_id',token_row.organization_id,'workspace_id',token_row.workspace_id,'environment_id',token_row.environment_id,'device_id',token_row.device_id,'device_version',device_row.version,'enrollment_id',token_row.id,'token_generation',token_row.token_generation,'consumed',token_row.consumed_at IS NOT NULL,'audience',token_row.audience);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_authenticate_sensor(locator_value bytea, secret_value bytea, audience_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE locator_hash bytea;candidate_scope record;token_row zasp_sensor_tokens%ROWTYPE;sensor_row zasp_sensors%ROWTYPE;computed_hash bytea;
BEGIN
 IF octet_length(locator_value)<>16 OR octet_length(secret_value)<>32 OR audience_value<>'event-ingest' THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 locator_hash:=digest(locator_value,'sha256');
 SELECT token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.sensor_id INTO candidate_scope FROM zasp_sensor_tokens token_value WHERE token_value.locator_digest=locator_hash;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate_scope.organization_id,candidate_scope.workspace_id,candidate_scope.environment_id,candidate_scope.sensor_id),0));
 SELECT token_value.* INTO token_row FROM zasp_sensor_tokens token_value WHERE token_value.locator_digest=locator_hash FOR UPDATE;
 SELECT sensor_value.* INTO sensor_row FROM zasp_sensors sensor_value WHERE (sensor_value.organization_id,sensor_value.workspace_id,sensor_value.environment_id,sensor_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id) FOR UPDATE;
 computed_hash:=zasp_runtime_sensor_secret_hash(audience_value,token_row.id,token_row.token_generation,token_row.salt,secret_value);
 IF token_row.format_version<>1 OR token_row.audience<>audience_value OR token_row.revoked_at IS NOT NULL OR token_row.expires_at<=transaction_timestamp()
  OR token_row.sensor_version_at_issue<>sensor_row.version OR sensor_row.state NOT IN('pending','active','degraded')
  OR digest(token_row.token_hash||computed_hash,'sha256')<>digest(token_row.token_hash||token_row.token_hash,'sha256')
  OR EXISTS(SELECT 1 FROM zasp_sensor_tokens newer WHERE (newer.organization_id,newer.workspace_id,newer.environment_id,newer.sensor_id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id) AND newer.token_generation>token_row.token_generation)
 THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 UPDATE zasp_sensor_tokens token_value SET last_authenticated_at=transaction_timestamp() WHERE (token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.id);
 PERFORM zasp_runtime_mark_used();
 RETURN jsonb_build_object('organization_id',token_row.organization_id,'workspace_id',token_row.workspace_id,'environment_id',token_row.environment_id,'sensor_id',token_row.sensor_id,'sensor_kind',sensor_row.kind,'sensor_mode',sensor_row.mode,'sensor_version',sensor_row.version,'token_id',token_row.id,'token_generation',token_row.token_generation,'audience',token_row.audience);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_bind_batch_domain()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE runtime_value text;
BEGIN
 IF NEW.source_kind='tetragon' THEN runtime_value:=NEW.sensor_id;
 ELSIF NEW.source_kind='otlp' THEN
  SELECT runtime_sensor_id INTO runtime_value FROM zasp_runtime_sensor_pairings WHERE (organization_id,workspace_id,environment_id,sensor_id)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.sensor_id);
 ELSE RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch source rejected';END IF;
 INSERT INTO zasp_runtime_batch_domains(organization_id,workspace_id,environment_id,batch_id,generation,source_sensor_id,source_kind,runtime_sensor_id)
 VALUES(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.batch_id,NEW.batch_generation,NEW.sensor_id,NEW.source_kind,runtime_value);
 RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_candidate_lineage_valid(value jsonb, event_time_value timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE identifier text;key_value text;start_value timestamptz;
BEGIN
 IF value IS NULL OR jsonb_typeof(value)<>'object' OR event_time_value IS NULL OR value->>'profile' IS DISTINCT FROM 'kubernetes-container-v1' OR octet_length(value::text)>1024 THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(value) member WHERE member.key NOT IN('profile','cluster_uid','node_uid','boot_id','pod_uid','container_id','process_id','process_start_time','cgroup_id') OR jsonb_typeof(member.value)<>'string' OR member.value='""'::jsonb) THEN RETURN false;END IF;
 FOREACH key_value IN ARRAY ARRAY['cluster_uid','node_uid','boot_id','pod_uid'] LOOP
  identifier:=value->>key_value;
  IF NOT COALESCE(identifier ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' AND identifier<>'00000000-0000-0000-0000-000000000000',false) THEN RETURN false;END IF;
 END LOOP;
 IF NOT COALESCE(value->>'container_id' ~ '^(containerd|docker|cri-o)://[0-9a-f]{64}$' AND right(value->>'container_id',64)<>repeat('0',64),false) THEN RETURN false;END IF;
 IF (value ? 'process_id') IS DISTINCT FROM (value ? 'process_start_time') THEN RETURN false;END IF;
 IF value ? 'process_id' THEN
  IF value->>'process_id' !~ '^[1-9][0-9]{0,9}$' OR (value->>'process_id')::numeric>4294967295 THEN RETURN false;END IF;
  IF value->>'process_start_time' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$' THEN RETURN false;END IF;
  start_value:=(value->>'process_start_time')::timestamptz;
  IF start_value<='1970-01-01T00:00:00Z'::timestamptz OR start_value>event_time_value THEN RETURN false;END IF;
 END IF;
 IF value ? 'cgroup_id' AND (value->>'cgroup_id' !~ '^[1-9][0-9]{0,19}$' OR (value->>'cgroup_id')::numeric>18446744073709551615) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN invalid_datetime_format OR datetime_field_overflow OR invalid_text_representation OR numeric_value_out_of_range THEN RETURN false;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_claim_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, receive_count_value integer, worker_value text, lease_token_value text, lease_seconds integer, visibility_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;delivery_row zasp_runtime_deliveries%ROWTYPE;outbox_digest bytea;disposition_value text;replayed_value boolean:=false;lease_expires_value timestamptz;visibility_deadline_value timestamptz;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR message_value !~ '^[A-Za-z0-9_-]{1,128}$' OR octet_length(message_digest_value)<>32 OR receive_count_value NOT BETWEEN 1 AND 100 OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR visibility_seconds<lease_seconds OR visibility_seconds>43200 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-runtime-delivery',organization_value,workspace_value,environment_value,batch_value),0));
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR batch_row.state='uploading' THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery missing';END IF;
 SELECT outbox.payload_digest INTO outbox_digest FROM zasp_discovery_outbox outbox WHERE (outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.topic,outbox.deterministic_key,outbox.payload_version)=(organization_value,workspace_value,environment_value,'runtime-events','runtime:'||batch_value,15);
 IF NOT FOUND OR outbox_digest IS DISTINCT FROM message_digest_value THEN
  IF batch_row.state NOT IN('succeeded','failed','unknown','quarantined') THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);END IF;
  PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value) FOR UPDATE;
 -- v36: exact durable outbox identity permits at-least-once publication.
 IF FOUND AND delivery_row.batch_generation=generation_value AND delivery_row.message_digest=message_digest_value AND delivery_row.message_id<>message_value THEN
  IF batch_row.state='unknown' OR delivery_row.disposition='unknown' THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF batch_row.state IN('succeeded','failed','quarantined') THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);
  END IF;
  IF delivery_row.disposition NOT IN('held','ack_pending') THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp() THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_duplicate','replayed',true);
  END IF;
  UPDATE zasp_runtime_deliveries existing SET message_id=message_value,receive_count=receive_count_value,provider_ack_digest=NULL,lease_expires_at=transaction_timestamp()
   WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  delivery_row.message_id:=message_value;delivery_row.receive_count:=receive_count_value;delivery_row.lease_expires_at:=transaction_timestamp();
 END IF;
 IF FOUND AND (delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest) IS DISTINCT FROM (generation_value,message_value,message_digest_value) THEN
  UPDATE zasp_runtime_deliveries existing SET disposition='quarantined',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value) AND authority_row.state NOT IN('succeeded','failed','unknown','quarantined');
  PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 IF FOUND AND receive_count_value<delivery_row.receive_count THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime delivery conflict';END IF;
 IF FOUND AND delivery_row.disposition='acked' THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);END IF;
 IF batch_row.state='unknown' OR FOUND AND delivery_row.disposition='unknown' THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',FOUND);END IF;
 IF FOUND AND delivery_row.disposition IN('held','ack_pending') AND delivery_row.lease_expires_at>transaction_timestamp() AND (delivery_row.lease_owner,delivery_row.lease_token) IS DISTINCT FROM (worker_value,lease_token_value) THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false,'lease_expires_at',delivery_row.lease_expires_at);END IF;
 IF EXISTS(SELECT 1 FROM zasp_runtime_deliveries other WHERE other.organization_id=organization_value AND other.batch_id<>batch_value AND other.disposition IN('held','ack_pending') AND other.lease_expires_at>transaction_timestamp()) THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false);END IF;
 disposition_value:=CASE WHEN batch_row.state IN('succeeded','failed','quarantined') THEN 'ack_pending' ELSE 'held' END;
 lease_expires_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);visibility_deadline_value:=transaction_timestamp()+make_interval(secs=>visibility_seconds);
 IF FOUND THEN
  replayed_value:=delivery_row.receive_count=receive_count_value AND delivery_row.disposition=disposition_value AND (delivery_row.lease_owner,delivery_row.lease_token) IS NOT DISTINCT FROM (worker_value,lease_token_value);
  UPDATE zasp_runtime_deliveries existing SET receive_count=GREATEST(existing.receive_count,receive_count_value),disposition=disposition_value,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=lease_expires_value,visibility_deadline=visibility_deadline_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 ELSE
  INSERT INTO zasp_runtime_deliveries(organization_id,workspace_id,environment_id,batch_id,batch_generation,message_id,message_digest,receive_count,disposition,lease_owner,lease_token,lease_expires_at,visibility_deadline) VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,receive_count_value,disposition_value,worker_value,lease_token_value,lease_expires_value,visibility_deadline_value);
 END IF;
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition',CASE WHEN disposition_value='held' THEN 'claimed' ELSE disposition_value END,'replayed',replayed_value,'lease_expires_at',lease_expires_value,'visibility_deadline',visibility_deadline_value,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'artifact_kms_key',batch_row.raw_artifact_kms_key,'request_digest',encode(batch_row.request_digest,'hex'));
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_claim_session_stage_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v2 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v2 IS NULL OR (stage_value NOT IN('project','complete')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_session_claim_version',true),'');
 PERFORM set_config('zasp.runtime_session_claim_version',CASE WHEN stage_value='project' THEN CASE WHEN allow_v2 THEN 'runtime-projection-v2' ELSE 'runtime-projection-v1' END ELSE CASE WHEN allow_v2 THEN 'runtime-complete-v2' ELSE 'runtime-complete-v1' END END,true);
 IF NOT COALESCE(zasp_production_runtime_sandbox_binding_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=50),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_sandbox_binding_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
  WHERE stage_row.stage=stage_value AND (stage_value='project' AND (stage_row.implementation_version='runtime-projection-v1' OR allow_v2 AND stage_row.implementation_version='runtime-projection-v2') OR stage_value='complete' AND (stage_row.implementation_version='runtime-complete-v1' OR allow_v2 AND stage_row.implementation_version='runtime-complete-v2')) AND stage_row.attempt>=100 AND stage_row.state IN('pending','retryable','leased') AND (stage_row.state<>'leased' OR stage_row.lease_expires_at<=transaction_timestamp())
  RETURNING stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.completion_digest,stage_row.completion_result
 ),failed_batches AS (
  UPDATE zasp_runtime_batch_authorities authority_row SET state='failed',completed_at=transaction_timestamp(),completion_digest=exhausted.completion_digest,completion_result=exhausted.completion_result
  FROM exhausted WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id)
  RETURNING authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.completion_digest,authority_row.completion_result
 ),failed_legacy_batches AS (
  UPDATE zasp_runtime_batches batch_row SET state='failed',completed_at=transaction_timestamp()
  FROM failed_batches WHERE (batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id)
  RETURNING batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id
 ),failed_jobs AS (
  UPDATE zasp_discovery_jobs job_row SET state='failed',last_error='exhausted',completed_at=transaction_timestamp(),updated_at=transaction_timestamp(),completion_digest=failed_batches.completion_digest,completion_result=failed_batches.completion_result
  FROM failed_batches WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.kind,job_row.authority_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,'runtime',failed_batches.batch_id)
  RETURNING job_row.organization_id
 )
 UPDATE zasp_runtime_deliveries delivery_row SET disposition='ack_pending',updated_at=transaction_timestamp()
 FROM failed_batches WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id) AND delivery_row.disposition='held';
 WITH eligible AS (
  SELECT stage_row.ctid row_id,stage_row.*,row_number() OVER(PARTITION BY stage_row.organization_id ORDER BY stage_row.available_at,stage_row.batch_id) organization_rank
  FROM zasp_runtime_stage_work stage_row
  WHERE stage_row.stage=stage_value AND (stage_value='project' AND (stage_row.implementation_version='runtime-projection-v1' OR allow_v2 AND stage_row.implementation_version='runtime-projection-v2') OR stage_value='complete' AND (stage_row.implementation_version='runtime-complete-v1' OR allow_v2 AND stage_row.implementation_version='runtime-complete-v2')) AND stage_row.attempt<100 AND stage_row.available_at<=transaction_timestamp() AND (stage_row.state IN('pending','retryable') OR stage_row.state='leased' AND stage_row.lease_expires_at<=transaction_timestamp())
   AND stage_row.input_digest IS NOT NULL
   AND EXISTS(SELECT 1 FROM zasp_runtime_deliveries delivery_row WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.disposition)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,'held') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp())
   AND (stage_row.stage_order=1 OR EXISTS(SELECT 1 FROM zasp_runtime_stage_work predecessor WHERE (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order,predecessor.state,predecessor.effect_digest)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage_order-1,'succeeded',stage_row.predecessor_digest)))
   AND NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work live_row WHERE live_row.stage=stage_value AND live_row.organization_id=stage_row.organization_id AND live_row.state='leased' AND live_row.lease_expires_at>transaction_timestamp())
 ),organizations AS (
  SELECT eligible.organization_id,min(eligible.available_at) first_available,MAX(fairness.last_claimed_at) last_claimed_at
  FROM eligible LEFT JOIN zasp_runtime_stage_fairness fairness ON (fairness.stage,fairness.organization_id)=(stage_value,eligible.organization_id)
  WHERE eligible.organization_rank=1 GROUP BY eligible.organization_id
  ORDER BY MAX(fairness.last_claimed_at) NULLS FIRST,min(eligible.available_at),eligible.organization_id LIMIT claim_limit
 ),candidates AS (
  SELECT stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage
  FROM zasp_runtime_stage_work stage_row JOIN eligible ON stage_row.ctid=eligible.row_id JOIN organizations ON organizations.organization_id=eligible.organization_id
  WHERE eligible.organization_rank=1 ORDER BY organizations.last_claimed_at NULLS FIRST,organizations.first_available,stage_row.organization_id,stage_row.batch_id FOR UPDATE OF stage_row SKIP LOCKED
 ),claimed AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='leased',attempt=stage_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp(),last_error_class=NULL
  FROM candidates WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage)=(candidates.organization_id,candidates.workspace_id,candidates.environment_id,candidates.batch_id,candidates.stage)
  RETURNING stage_row.*
 ),fairness AS (
  INSERT INTO zasp_runtime_stage_fairness(stage,organization_id,last_claimed_at) SELECT stage_value,claimed.organization_id,transaction_timestamp() FROM claimed
  ON CONFLICT(stage,organization_id) DO UPDATE SET last_claimed_at=excluded.last_claimed_at RETURNING organization_id
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'stage',claimed.stage,'attempt',claimed.attempt,'implementation_version',claimed.implementation_version,'predecessor_digest',CASE WHEN claimed.predecessor_digest IS NULL THEN NULL ELSE encode(claimed.predecessor_digest,'hex') END,'input_digest',encode(claimed.input_digest,'hex'),'input_reference',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_reference ELSE predecessor.result_reference END,'input_version_id',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_version_id ELSE predecessor.result_version_id END,'lease_expires_at',claimed.lease_expires_at) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO result_value
 FROM claimed JOIN zasp_runtime_batch_authorities authority_row ON (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.batch_generation)
 LEFT JOIN zasp_runtime_stage_work predecessor ON (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.stage_order-1);
 IF stage_value='archive' AND jsonb_array_length(result_value)>0 THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='processing' WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(item->>'organization_id',item->>'workspace_id',item->>'environment_id',item->>'batch_id'));END IF;
 PERFORM set_config('zasp.runtime_session_claim_version',prior_capability,true);
 IF NOT COALESCE(zasp_production_runtime_sandbox_binding_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=50),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_sandbox_binding_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_claim_stage_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v2 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v2 IS NULL OR (allow_v2 AND stage_value<>'correlate') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_correlation_claim_version',true),'');
 PERFORM set_config('zasp.runtime_correlation_claim_version',CASE WHEN allow_v2 THEN 'runtime-correlation-v2' ELSE 'runtime-correlation-v1' END,true);
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
