onnection.workspace_id,connection.environment_id,connection.integration_id,connection.provider,connection.connection_reference,'active') AND (connection.provider='github' AND credential.credential_class='github_installation_reference' AND CASE WHEN connection.connection_reference ~ '^ref:github/installation/[1-9][0-9]{0,19}$' THEN substring(connection.connection_reference FROM 25)::numeric<=9223372036854775807 ELSE false END OR connection.provider='okta' AND credential.credential_class='okta_refresh_reference' AND connection.connection_reference LIKE 'ref:okta/refresh/%' AND length(connection.connection_reference)>17));
