 IF NOT public.zasp_security_agent_budget_can_start(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value) THEN RETURN public.zasp_security_agent_budget_stop_result(organization_value,workspace_value,environment_value,run_value,'prepare');END IF;
  SELECT * INTO STRICT trigger_row FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.run_id)=(organization_value,workspace_value,environment_value,run_value);
  IF trigger_row.trigger_kind='finding' THEN RETURN zasp_security_agent_prepare_temporary_policy_run(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value,approval_value,approval_expires_value,audit_value,correlation_value);END IF;
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_worker') OR trigger_row.trigger_kind<>'attack_path' OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(approval_value) OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR approval_expires_value<=transaction_timestamp() OR approval_expires_value>transaction_timestamp()+interval '16 minutes' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='temporary policy plan rejected';END IF;
  SELECT * INTO run_row FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id,run.state,run.lease_owner,run.lease_token)=(organization_value,workspace_value,environment_value,run_value,'planning',worker_value,lease_token_value) AND run.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent lease lost';END IF;
  SELECT * INTO STRICT definition_row FROM zasp_security_agent_definitions definition WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(organization_value,workspace_value,environment_value,run_row.definition_id,run_row.definition_version) AND definition.activation='supervised' AND definition.deleted_at IS NULL AND definition.body->>'trigger_kind'='attack_path' AND definition.body->'allowed_actions'=jsonb_build_array('create_temporary_policy') AND definition.body->>'verification_kind'='policy_state' AND (definition.body->>'temporary_policy_seconds')::integer BETWEEN 60 AND 3600 FOR SHARE;
  PERFORM 1 FROM zasp_risk_attack_paths path WHERE (path.organization_id,path.workspace_id,path.environment_id,path.id)=(organization_value,workspace_value,environment_value,trigger_row.trigger_id) AND path.version=trigger_row.trigger_version AND path.state=definition_row.body->>'trigger_source' AND path.state IN('observed','verified') AND zasp_risk_attack_path_valid(path) FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent evidence changed';END IF;
  step_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'security_agent_step',run_value||chr(31)||'0');
  plan_value:=jsonb_build_object('definition_id',run_row.definition_id,'definition_version',run_row.definition_version,'catalog_version','security-agent-actions-v1','evidence_ids',jsonb_build_array(trigger_row.trigger_id),'steps',jsonb_build_array(jsonb_build_object('index',0,'step_id',step_value,'action','create_temporary_policy','target_id',environment_value,'mode','block','scope',environment_value,'ttl_seconds',(definition_row.body->>'temporary_policy_seconds')::integer,'authorization','approval_required')),'verification',jsonb_build_object('kind','policy_state','expected_state','active'),'expires_at',to_char(approval_expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  plan_digest:=digest(convert_to(plan_value::text,'UTF8'),'sha256');
 IF NOT public.zasp_security_agent_budget_can_start(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value) THEN RETURN public.zasp_security_agent_budget_stop_result(organization_value,workspace_value,environment_value,run_value,'prepare');END IF;
  INSERT INTO zasp_security_agent_plans(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_digest,catalog_version,plan,plan_hash,expires_at) VALUES(organization_value,workspace_value,environment_value,run_value,run_row.definition_id,run_row.definition_version,trigger_row.trigger_digest,'security-agent-actions-v1',plan_value,plan_digest,approval_expires_value);
  INSERT INTO zasp_security_agent_steps(organization_id,workspace_id,environment_id,run_id,step_id,step_index,action_key,input_digest,authorization_result,state) VALUES(organization_value,workspace_value,environment_value,run_value,step_value,0,'create_temporary_policy',digest(convert_to((plan_value->'steps'->0)::text,'UTF8'),'sha256'),'approval_required','waiting_approval');
  INSERT INTO zasp_security_agent_approvals(organization_id,workspace_id,environment_id,approval_id,run_id,step_id,plan_hash,state,requester_id,expires_at) VALUES(organization_value,workspace_value,environment_value,approval_value,run_value,step_value,plan_digest,'pending',run_row.requested_by,approval_expires_value);
  UPDATE zasp_security_agent_runs run SET state='waiting_approval',plan_hash=plan_digest,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=run.version+1,updated_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,approval_id,actor_id,event_kind,event_digest,body) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,run_value,step_value,approval_value,worker_value,'approval_requested',plan_digest,jsonb_build_object('run_id',run_value,'step_id',step_value,'action','create_temporary_policy','trigger_kind','attack_path','approval_id',approval_value,'plan_hash','sha256:'||encode(plan_digest,'hex')));
  RETURN jsonb_build_object('run_id',run_value,'state','waiting_approval','version',run_row.version+1,'approval_id',approval_value,'step_id',step_value,'plan_hash','sha256:'||encode(plan_digest,'hex'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_read_session_policy_target(organization_value text, workspace_value text, environment_value text, run_value text, step_value text, phase_value text, device_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='session policy target denied';END IF;
  SELECT jsonb_build_object('device_id',target.device_id,'credential_id',target.credential_id,'phase',target.phase,'state',target.state,'sequence',target.sequence,'policy_version',target.policy_version,'key_id',target.key_id,'issued_at',to_char(target.issued_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'expires_at',to_char(target.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'failure_mode',target.failure_mode,'payload_digest','sha256:'||encode(target.payload_digest,'hex'),'policies',target.policies,'signature',encode(target.signature,'base64'),'envelope_digest','sha256:'||encode(target.envelope_digest,'hex')) INTO result_value FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value) AND target.action_key IN('create_temporary_policy','isolate_session') AND target.state IN('stored','verified');
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='session policy target missing';END IF;RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_read_temporary_policy_target(organization_value text, workspace_value text, environment_value text, run_value text, step_value text, phase_value text, device_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='temporary policy target denied';END IF;
  SELECT jsonb_build_object('device_id',target.device_id,'credential_id',target.credential_id,'phase',target.phase,'state',target.state,'sequence',target.sequence,'policy_version',target.policy_version,'key_id',target.key_id,'issued_at',to_char(target.issued_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'expires_at',to_char(target.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'failure_mode',target.failure_mode,'payload_digest','sha256:'||encode(target.payload_digest,'hex'),'policies',target.policies,'signature',encode(target.signature,'base64'),'envelope_digest','sha256:'||encode(target.envelope_digest,'hex')) INTO result_value
  FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value) AND target.state IN('stored','verified');
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='temporary policy target missing';END IF;
  RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_reconcile_connector_revocations(worker_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item record;count_value integer:=0;outcome_value text;result_digest_value bytea;audit_value text;correlation_value text;verification_drift boolean;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() OR length(worker_value) NOT BETWEEN 1 AND 128 OR limit_value NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='connector revocation verification rejected';END IF;
  FOR item IN SELECT link.*,connector.status connector_status,connector.last_error_code FROM zasp_security_agent_connector_revocations link JOIN zasp_connector_effects connector ON (connector.organization_id,connector.workspace_id,connector.environment_id,connector.id)=(link.organization_id,link.workspace_id,link.environment_id,link.connector_effect_id) WHERE link.state='pending' AND (connector.status='reconciled' OR connector.status='failed' OR connector.status='unknown' AND connector.attempt=100 AND connector.last_error_code='provider_revocation_ambiguous') ORDER BY connector.updated_at,link.organization_id,link.workspace_id,link.environment_id,link.run_id FOR UPDATE OF link SKIP LOCKED LIMIT limit_value
  LOOP
    verification_drift:=false;
    IF item.connector_status='reconciled' THEN
      PERFORM 1 FROM zasp_workflow_records workflow WHERE (workflow.organization_id,workflow.workspace_id,workflow.environment_id,workflow.kind,workflow.id)=(item.organization_id,item.workspace_id,item.environment_id,'integration',item.integration_id) FOR UPDATE;
      verification_drift:=NOT FOUND OR NOT EXISTS(SELECT 1 FROM zasp_workflow_records workflow WHERE (workflow.organization_id,workflow.workspace_id,workflow.environment_id,workflow.kind,workflow.id)=(item.organization_id,item.workspace_id,item.environment_id,'integration',item.integration_id) AND workflow.deleted_at IS NULL AND workflow.body->>'status'='pending_authorization') OR NOT EXISTS(SELECT 1 FROM zasp_integration_connections connection WHERE (connection.organization_id,connection.workspace_id,connection.environment_id,connection.id,connection.integration_id,connection.state)=(item.organization_id,item.workspace_id,item.environment_id,item.connection_id,item.integration_id,'revoked')) OR EXISTS(SELECT 1 FROM zasp_connector_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.integration_id,credential.status)=(item.organization_id,item.workspace_id,item.environment_id,item.integration_id,'active'));
    END IF;
    IF item.connector_status='reconciled' AND NOT verification_drift THEN
      outcome_value:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_effect',item.run_id||chr(31)||item.step_id||chr(31)||'revoke_integration_connection');result_digest_value:=digest(convert_to(jsonb_build_object('integration_id',item.integration_id,'connection_id',item.connection_id,'state','revoked','connector_effect_id',item.connector_effect_id)::text,'UTF8'),'sha256');
      UPDATE zasp_security_agent_connector_revocations SET state='verified',completed_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id);
      UPDATE zasp_security_agent_effects SET state='verified',outcome_id=outcome_value,result_digest=result_digest_value,version=version+1,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,'revoke_integration_connection','pending');
      UPDATE zasp_security_agent_steps SET state='succeeded',version=version+1,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,'executing');
      UPDATE zasp_security_agent_runs SET state='remediated',version=version+1,updated_at=transaction_timestamp(),completed_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,'running');
      audit_value:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_audit',item.run_id||chr(31)||'connector-revocation-verified');correlation_value:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_correlation',item.run_id||chr(31)||'connector-revocation-verified');
      INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(item.organization_id,item.workspace_id,item.environment_id,audit_value,correlation_value,item.run_id,item.step_id,worker_value,'effect_verified',result_digest_value,jsonb_build_object('run_id',item.run_id,'step_id',item.step_id,'action','revoke_integration_connection','integration_id',item.integration_id,'connection_id',item.connection_id,'outcome_id',outcome_value,'result_digest','sha256:'||encode(result_digest_value,'hex')));
    ELSE
      UPDATE zasp_security_agent_connector_revocations SET state='needs_human',completed_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id);
      UPDATE zasp_security_agent_effects SET state='unknown_outcome',version=version+1,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,'revoke_integration_connection','pending');
      UPDATE zasp_security_agent_steps SET state='inconclusive',version=version+1,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,'executing');
      UPDATE zasp_security_agent_runs SET state='needs_human',version=version+1,updated_at=transaction_timestamp(),completed_at=transaction_timestamp(),last_error_code=CASE WHEN verification_drift THEN 'connector_state_drift' ELSE 'provider_revocation_ambiguous' END WHERE (organization_id,workspace_id,environment_id,run_id,state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,'running');
    END IF;
    count_value:=count_value+1;
  END LOOP;
  RETURN jsonb_build_object('reconciled',count_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_register_action_principal(migration_principal text, action_principal text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE principal record;
BEGIN
  IF migration_principal<>session_user OR action_principal=migration_principal OR action_principal!~'^[a-z][a-z0-9_]{2,62}$' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid security agent action principal';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('zasp-security-agent-action-principal-registration',0));
  SELECT * INTO principal FROM pg_roles WHERE rolname=action_principal;
  IF NOT FOUND OR NOT principal.rolcanlogin OR NOT principal.rolinherit OR principal.rolsuper OR principal.rolcreatedb OR principal.rolcreaterole OR principal.rolreplication OR principal.rolbypassrls
     OR EXISTS(SELECT 1 FROM pg_auth_members membership JOIN pg_roles granted ON granted.oid=membership.roleid WHERE membership.member=principal.oid AND granted.rolname LIKE 'zasp_%' AND granted.rolname<>'zasp_security_agent_action_worker') THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='unsafe security agent action principal';
  END IF;
  EXECUTE format('GRANT zasp_security_agent_action_worker TO %I',action_principal);
  INSERT INTO zasp_security_agent_action_principal_bindings(principal_name) VALUES(action_principal)
  ON CONFLICT(principal_name) DO UPDATE SET authority_role=excluded.authority_role WHERE zasp_security_agent_action_principal_bindings.authority_role=excluded.authority_role;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent action principal conflict';END IF;
  RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_register_principals(migration_principal text, api_principal text, worker_principal text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE principals text[]:=ARRAY[api_principal,worker_principal];authorities text[]:=ARRAY['zasp_security_agent_api','zasp_security_agent_worker'];index_value integer;role_value record;
BEGIN
  IF migration_principal<>session_user OR cardinality(ARRAY(SELECT DISTINCT unnest(ARRAY[migration_principal,api_principal,worker_principal])))<>3
     OR EXISTS(SELECT 1 FROM unnest(principals) principal_value WHERE principal_value!~'^[a-z][a-z0-9_]{2,62}$') THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid security agent principals';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended('zasp-security-agent-principal-registration',0));
  FOR index_value IN 1..2 LOOP
    SELECT role_row.oid,role_row.rolcanlogin,role_row.rolinherit,role_row.rolsuper,role_row.rolcreatedb,role_row.rolcreaterole,role_row.rolreplication,role_row.rolbypassrls INTO role_value FROM pg_roles role_row WHERE role_row.rolname=principals[index_value];
    IF NOT FOUND OR NOT role_value.rolcanlogin OR NOT role_value.rolinherit OR role_value.rolsuper OR role_value.rolcreatedb OR role_value.rolcreaterole OR role_value.rolreplication OR role_value.rolbypassrls
       OR EXISTS(SELECT 1 FROM pg_auth_members membership JOIN pg_roles granted ON granted.oid=membership.roleid WHERE membership.member=role_value.oid AND granted.rolname LIKE 'zasp_%' AND granted.rolname<>authorities[index_value]) THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='unsafe security agent principal';
    END IF;
    EXECUTE format('GRANT %I TO %I',authorities[index_value],principals[index_value]);
    INSERT INTO zasp_security_agent_principal_bindings(principal_name,authority_role) VALUES(principals[index_value],authorities[index_value])
    ON CONFLICT(principal_name) DO UPDATE SET authority_role=excluded.authority_role WHERE zasp_security_agent_principal_bindings.authority_role=excluded.authority_role;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent principal conflict';END IF;
  END LOOP;
  RETURN true;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_run(organization_value text, workspace_value text, environment_value text, definition_value text, actor_value text, idempotency_value text, expected_version bigint, run_value text, trigger_kind_value text, trigger_value text, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row zasp_security_agent_definitions%ROWTYPE; finding_version bigint; trigger_digest_value bytea; intent_value jsonb; intent_digest_value bytea; receipt_row zasp_security_agent_request_receipts%ROWTYPE; prior_run text; prior_state text; prior_version bigint; response_value jsonb;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR expected_version<=0 OR trigger_kind_value<>'finding'
     OR NOT zasp_valid_product_id(definition_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(trigger_value)
     OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR NOT zasp_valid_product_id(receipt_value)
     OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent run rejected';
  END IF;
  intent_value:=jsonb_build_object('definition_id',definition_value,'expected_version',expected_version,'trigger_kind',trigger_kind_value,'trigger_id',trigger_value);
  intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'runSecurityAgent',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt
  WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'runSecurityAgent',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>definition_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=transaction_timestamp()
       OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_definitions definition WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version) AND definition.deleted_at IS NULL)
       OR NOT EXISTS(SELECT 1 FROM zasp_risk_findings finding WHERE (finding.organization_id,finding.workspace_id,finding.environment_id,finding.id)=(organization_value,workspace_value,environment_value,trigger_value) AND finding.status IN('open','under_review')) THEN
      RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent run replay conflict';
    END IF;
    RETURN receipt_row.response||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO definition_row FROM zasp_security_agent_definitions definition
  WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version)
    AND definition.deleted_at IS NULL AND definition.activation='supervised' AND definition.body->'environment_ids' ? environment_value
    AND definition.body->>'autonomy'='supervised' AND definition.body->'allowed_actions'=jsonb_build_array('update_finding_response') AND definition.body->>'verification_kind'='finding_state' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent run definition rejected';END IF;
  SELECT finding.version INTO finding_version FROM zasp_risk_findings finding
  WHERE (finding.organization_id,finding.workspace_id,finding.environment_id,finding.id)=(organization_value,workspace_value,environment_value,trigger_value) AND finding.status='open' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent run trigger denied';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true))
     OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true))
     OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'update_finding_response',true)) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent execution disabled';
  END IF;
  trigger_digest_value:=digest(convert_to(jsonb_build_object('kind','finding','id',trigger_value,'version',finding_version)::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,definition_value,trigger_value,finding_version),0));
  SELECT receipt.run_id INTO prior_run FROM zasp_security_agent_trigger_receipts receipt
  WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(organization_value,workspace_value,environment_value,definition_value,trigger_value,finding_version);
  IF FOUND THEN
    SELECT state,version INTO STRICT prior_state,prior_version FROM zasp_security_agent_runs existing
    WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.run_id)=(organization_value,workspace_value,environment_value,prior_run);
    response_value:=jsonb_build_object('id',prior_run,'agent_id',definition_value,'state',prior_state,'evidence_ids',jsonb_build_array(trigger_value),'definition_version',expected_version,'version',prior_version,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',true);
  ELSE
    INSERT INTO zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id)
    VALUES(organization_value,workspace_value,environment_value,definition_value,trigger_value,'finding',finding_version,trigger_digest_value,run_value);
    INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state)
    VALUES(organization_value,workspace_value,environment_value,run_value,definition_value,expected_version,trigger_value,actor_value,'queued');
    response_value:=jsonb_build_object('id',run_value,'agent_id',definition_value,'state','queued','evidence_ids',jsonb_build_array(trigger_value),'definition_version',expected_version,'version',1,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
  END IF;
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
  VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,response_value->>'id',actor_value,CASE WHEN prior_run IS NULL THEN 'run_queued' ELSE 'run_deduplicated' END,trigger_digest_value,jsonb_build_object('run_id',response_value->>'id','definition_id',definition_value,'definition_version',expected_version,'trigger_kind','finding','trigger_id',trigger_value));
  INSERT INTO zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id)
  VALUES(organization_value,workspace_value,environment_value,actor_value,'runSecurityAgent',idempotency_value,definition_value,expected_version,intent_value,intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_run_context_v54(organization_value text, workspace_value text, environment_value text, run_value text)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE detail_value jsonb;trigger_value jsonb;receipt_value jsonb;receipt_count bigint;
 plan_value jsonb;step_value jsonb;planned_step jsonb;arguments_value jsonb;
 actions_value jsonb:='[]'::jsonb;effect_value jsonb;control_count bigint;expiry_value timestamptz;
 apply_value jsonb;cleanup_value jsonb;step_id_value text;action_value text;index_value integer;
BEGIN
 -- Reuse the existing principal-authorized scoped read before inspecting any
 -- private receipt. Missing/foreign/invisible runs return no private envelope.
 SELECT value INTO detail_value
 FROM public.zasp_security_agent_run_detail_v24(organization_value,workspace_value,environment_value,run_value) detail(value);
 IF NOT FOUND THEN RETURN;END IF;

 SELECT jsonb_build_object('kind',receipt.trigger_kind,'id',receipt.trigger_id,'version',receipt.trigger_version)
 INTO trigger_value FROM public.zasp_security_agent_trigger_receipts receipt
 WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.run_id)=
       (organization_value,workspace_value,environment_value,run_value);

 -- Bind to the plan being displayed, never the most recent attempt. Execution
 -- retries can advance run.attempt after the accepted planner receipt exists.
 SELECT count(*),(jsonb_agg(jsonb_build_object(
   'run_id',receipt.response->'run_id','plan_hash',receipt.response->'plan_hash',
   'outcome',receipt.outcome,'summary',receipt.response->'planner_summary')))->0
 INTO receipt_count,receipt_value
 FROM public.zasp_security_agent_planner_receipts receipt
 WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.run_id)=
       (organization_value,workspace_value,environment_value,run_value)
   AND receipt.outcome='accepted'
   AND receipt.response->>'run_id'=run_value
   AND receipt.response->>'plan_hash'=detail_value->'plan'->>'plan_hash';
 IF receipt_count>1 THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent run context authority unavailable';
 END IF;

 IF detail_value->'plan'<>'null'::jsonb THEN
  SELECT plan.plan INTO plan_value FROM public.zasp_security_agent_plans plan
  JOIN public.zasp_security_agent_runs run USING(organization_id,workspace_id,environment_id,run_id)
  WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=
        (organization_value,workspace_value,environment_value,run_value)
    AND 'sha256:'||encode(plan.plan_hash,'hex')=detail_value->'plan'->>'plan_hash'
    AND run.plan_hash=plan.plan_hash;
  IF NOT FOUND THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent action detail authority unavailable';
  END IF;
  -- Old stored plans without argument-bearing steps remain explicitly unknown.
  -- Once steps exist, require their exact content hash and displayed bindings.
  IF plan_value ? 'steps' THEN
   IF jsonb_typeof(plan_value->'steps') IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent action detail authority unavailable';
   END IF;
   IF jsonb_array_length(plan_value->'steps')<>jsonb_array_length(detail_value->'plan'->'steps')
      OR 'sha256:'||encode(digest(convert_to(plan_value::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM detail_value->'plan'->>'plan_hash' THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent action detail authority unavailable';
   END IF;
  END IF;
  FOR step_value IN SELECT value FROM jsonb_array_elements(detail_value->'plan'->'steps') LOOP
   step_id_value:=step_value->>'id';action_value:=step_value->>'action';index_value:=(step_value->>'index')::integer;
   IF action_value NOT IN('update_finding_response','create_temporary_policy','isolate_session','revoke_integration_connection') THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent action detail authority unavailable';
   END IF;
   arguments_value:=NULL;
   IF plan_value ? 'steps' THEN
    planned_step:=plan_value->'steps'->index_value;
    IF planned_step->>'step_id' IS DISTINCT FROM step_id_value OR planned_step->'index' IS DISTINCT FROM to_jsonb(index_value)
       OR planned_step->>'action' IS DISTINCT FROM action_value THEN
     RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent action detail authority unavailable';
    END IF;
    IF action_value IN('create_temporary_policy','isolate_session') AND planned_step->>'scope' IS DISTINCT FROM environment_value THEN
     RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent action detail authority unavailable';
    END IF;
    -- Never return the original plan step. Unknown keys can contain credentials.
    arguments_value:=CASE action_value
     WHEN 'update_finding_response' THEN jsonb_build_object('target_id',planned_step->'target_id','expected_version',planned_step->'expected_version','target_status',planned_step->'target_status')
     WHEN 'create_temporary_policy' THEN jsonb_build_object('target_id',planned_step->'target_id','mode',planned_step->'mode','scope',planned_step->'scope','ttl_seconds',planned_step->'ttl_seconds')
     WHEN 'isolate_session' THEN jsonb_build_object('target_id',planned_step->'target_id','session_id',planned_step->'session_id','device_id',planned_step->'device_id','scope',planned_step->'scope','ttl_seconds',planned_step->'ttl_seconds')
     WHEN 'revoke_integration_connection' THEN jsonb_build_object('target_id',planned_step->'target_id','integration_id',planned_step->'integration_id') END;
   END IF;
   SELECT jsonb_build_object('step_id',effect.step_id,'action',effect.action_key,'state',effect.state,'outcome_id',effect.outcome_id,
      'result_digest',CASE WHEN effect.result_digest IS NULL THEN NULL ELSE 'sha256:'||encode(effect.result_digest,'hex') END)
   INTO effect_value FROM public.zasp_security_agent_effects effect
   WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key)=
         (organization_value,workspace_value,environment_value,run_value,step_id_value,action_value);
   SELECT count(*),max(control.expires_at) INTO control_count,expiry_value FROM public.zasp_security_agent_controls control
   WHERE (control.organization_id,control.workspace_id,control.environment_id,control.run_id,control.step_id,control.action_key)=
         (organization_value,workspace_value,environment_value,run_value,step_id_value,action_value);
   IF control_count>1 THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent action detail authority unavailable';
   END IF;
   SELECT jsonb_build_object('total',count(*) FILTER(WHERE target.phase='apply'),'verified',count(*) FILTER(WHERE target.phase='apply' AND target.state='verified')),
          jsonb_build_object('total',count(*) FILTER(WHERE target.phase='cleanup'),'verified',count(*) FILTER(WHERE target.phase='cleanup' AND target.state='verified'))
   INTO apply_value,cleanup_value FROM public.zasp_security_agent_temporary_policy_targets target
   WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key)=
         (organization_value,workspace_value,environment_value,run_value,step_id_value,action_value);
   actions_value:=actions_value||jsonb_build_array(jsonb_build_object('step_id',step_id_value,'index',index_value,'action',action_value,
    'arguments',arguments_value,'effect',effect_value,'control_expires_at',CASE WHEN expiry_value IS NULL THEN NULL ELSE to_char(expiry_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,
    'apply_targets',apply_value,'cleanup_targets',cleanup_value));
  END LOOP;
 END IF;
 RETURN NEXT jsonb_build_object('detail',detail_value,'context',jsonb_build_object(
   'trigger',trigger_value,'planner_receipt',receipt_value),'action_details',jsonb_build_object(
   'run_id',run_value,'plan_hash',detail_value->'plan'->'plan_hash','steps',actions_value));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_run_v24(organization_value text, workspace_value text, environment_value text, definition_value text, actor_value text, idempotency_value text, expected_version bigint, run_value text, trigger_kind_value text, trigger_value text, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row zasp_security_agent_definitions%ROWTYPE;event_row zasp_runtime_gateway_events%ROWTYPE;trigger_digest_value bytea;intent_value jsonb;intent_digest_value bytea;receipt_row zasp_security_agent_request_receipts%ROWTYPE;prior_run text;prior_state text;prior_version bigint;response_value jsonb;
BEGIN
  IF trigger_kind_value='finding' THEN RETURN zasp_security_agent_run(organization_value,workspace_value,environment_value,definition_value,actor_value,idempotency_value,expected_version,run_value,trigger_kind_value,trigger_value,audit_value,correlation_value,receipt_value);END IF;
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR expected_version<=0 OR trigger_kind_value<>'session' OR NOT zasp_valid_product_id(definition_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(trigger_value) OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR NOT zasp_valid_product_id(receipt_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent run rejected';END IF;
  intent_value:=jsonb_build_object('definition_id',definition_value,'expected_version',expected_version,'trigger_kind',trigger_kind_value,'trigger_id',trigger_value);intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'runSecurityAgent',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'runSecurityAgent',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>definition_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=transaction_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_definitions definition WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version) AND definition.deleted_at IS NULL) OR NOT EXISTS(SELECT 1 FROM zasp_runtime_gateway_events event WHERE (event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id')=(organization_value,workspace_value,environment_value,trigger_value)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent run replay conflict';END IF;
    RETURN receipt_row.response||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO definition_row FROM zasp_security_agent_definitions definition WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version) AND definition.deleted_at IS NULL AND definition.activation='supervised' AND definition.body->'environment_ids' ? environment_value AND definition.body->>'trigger_kind'='runtime_decision' AND definition.body->>'autonomy'='supervised' AND definition.body->'allowed_actions'=jsonb_build_array('isolate_session') AND definition.body->>'verification_kind'='gateway_decision' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent run definition rejected';END IF;
  SELECT event.* INTO event_row FROM zasp_runtime_gateway_events event JOIN zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,'active') JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.credential_id) WHERE (event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id')=(organization_value,workspace_value,environment_value,trigger_value) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() AND credential.id=(SELECT current_credential.id FROM zasp_gateway_credentials current_credential WHERE (current_credential.organization_id,current_credential.workspace_id,current_credential.environment_id,current_credential.device_id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id) AND current_credential.revoked_at IS NULL AND current_credential.expires_at>transaction_timestamp() ORDER BY current_credential.issued_at DESC,current_credential.id DESC LIMIT 1) ORDER BY event.sequence DESC,event.event_id DESC LIMIT 1 FOR SHARE OF device,credential;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent run trigger denied';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'isolate_session',true)) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent execution disabled';END IF;
  trigger_digest_value:=digest(convert_to(jsonb_build_object('kind','runtime_decision','session_id',trigger_value,'device_id',event_row.device_id,'event_id',event_row.event_id,'sequence',event_row.sequence,'request_digest','sha256:'||encode(event_row.request_digest,'hex'))::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,definition_value,trigger_value,event_row.sequence),0));
  SELECT receipt.run_id INTO prior_run FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(organization_value,workspace_value,environment_value,definition_value,trigger_value,event_row.sequence);
  IF FOUND THEN
    SELECT state,version INTO STRICT prior_state,prior_version FROM zasp_security_agent_runs existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.run_id)=(organization_value,workspace_value,environment_value,prior_run);
    response_value:=jsonb_build_object('id',prior_run,'agent_id',definition_value,'state',prior_state,'evidence_ids',jsonb_build_array(trigger_value),'definition_version',expected_version,'version',prior_version,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',true);
  ELSE
    INSERT INTO zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(organization_value,workspace_value,environment_value,definition_value,trigger_value,'runtime_decision',event_row.sequence,trigger_digest_value,run_value);
    INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(organization_value,workspace_value,environment_value,run_value,definition_value,expected_version,trigger_value,actor_value,'queued');
    response_value:=jsonb_build_object('id',run_value,'agent_id',definition_value,'state','queued','evidence_ids',jsonb_build_array(trigger_value),'definition_version',expected_version,'version',1,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
  END IF;
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,response_value->>'id',actor_value,CASE WHEN prior_run IS NULL THEN 'run_queued' ELSE 'run_deduplicated' END,trigger_digest_value,jsonb_build_object('run_id',response_value->>'id','definition_id',definition_value,'definition_version',expected_version,'trigger_kind','runtime_decision','trigger_id',trigger_value,'trigger_version',event_row.sequence,'device_id',event_row.device_id));
  INSERT INTO zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(organization_value,workspace_value,environment_value,actor_value,'runSecurityAgent',idempotency_value,definition_value,expected_version,intent_value,intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_schedule_attack_path_triggers_v33(worker_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;trigger_digest_value bytea;run_value text;audit_value text;correlation_value text;created_value integer:=0;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_worker') OR length(worker_value) NOT BETWEEN 1 AND 128 OR limit_value NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='attack path scheduling rejected';END IF;
  FOR candidate IN
    WITH eligible AS (
      SELECT definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version AS definition_version,(definition.body->>'concurrency_limit')::integer AS concurrency_limit,
        path.id AS trigger_id,path.version AS trigger_version,path.state AS trigger_state,path.updated_at,row_number() OVER(PARTITION BY definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id ORDER BY path.updated_at,path.id) AS definition_ordinal
      FROM zasp_security_agent_definitions definition JOIN zasp_risk_attack_paths path ON (path.organization_id,path.workspace_id,path.environment_id)=(definition.organization_id,definition.workspace_id,definition.environment_id)
      WHERE definition.activation='supervised' AND definition.deleted_at IS NULL AND definition.body->>'enabled'='true' AND definition.body->>'trigger_kind'='attack_path' AND definition.body->'environment_ids' ? definition.environment_id
        AND path.state=definition.body->>'trigger_source' AND path.state IN('observed','verified') AND zasp_risk_attack_path_valid(path)
        AND definition.body->'allowed_actions'=jsonb_build_array('create_temporary_policy') AND definition.body->>'verification_kind'='policy_state' AND (definition.body->>'temporary_policy_seconds')::integer BETWEEN 60 AND 3600
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch WHERE (switch.organization_id,switch.workspace_id,switch.environment_id,switch.action_key,switch.execution_enabled)=('*','*','*','*',true))
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch WHERE (switch.organization_id,switch.workspace_id,switch.environment_id,switch.action_key,switch.execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'*',true))
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch WHERE (switch.organization_id,switch.workspace_id,switch.environment_id,switch.action_key,switch.execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'create_temporary_policy',true))
        AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,path.id,path.version))
        AND (SELECT count(*) FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.definition_id)=(definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id) AND run.state IN('queued','planning','waiting_approval','running','verifying','contained'))<(definition.body->>'concurrency_limit')::integer
    ) SELECT * FROM eligible WHERE definition_ordinal=1 ORDER BY updated_at,organization_id,workspace_id,environment_id,definition_id,trigger_id LIMIT limit_value
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,'attack-path-trigger'),0));
    CONTINUE WHEN NOT EXISTS(SELECT 1 FROM zasp_risk_attack_paths path WHERE (path.organization_id,path.workspace_id,path.environment_id,path.id,path.version,path.state)=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.trigger_id,candidate.trigger_version,candidate.trigger_state) AND path.state IN('observed','verified') AND zasp_risk_attack_path_valid(path));
    CONTINUE WHEN EXISTS(SELECT 1 FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.trigger_id,candidate.trigger_version));
    CONTINUE WHEN (SELECT count(*) FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.definition_id)=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id) AND run.state IN('queued','planning','waiting_approval','running','verifying','contained'))>=candidate.concurrency_limit;
    trigger_digest_value:=digest(convert_to(jsonb_build_object('kind','attack_path','id',candidate.trigger_id,'version',candidate.trigger_version,'state',candidate.trigger_state)::text,'UTF8'),'sha256');
    run_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_run',candidate.definition_id||chr(31)||candidate.trigger_id||chr(31)||candidate.trigger_version::text);
    INSERT INTO zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.trigger_id,'attack_path',candidate.trigger_version,trigger_digest_value,run_value) ON CONFLICT DO NOTHING;
    CONTINUE WHEN NOT FOUND;
    INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,run_value,candidate.definition_id,candidate.definition_version,candidate.trigger_id,worker_value,'queued');
    audit_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_audit',run_value||chr(31)||'attack-path-trigger');
    correlation_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_correlation',run_value||chr(31)||'attack-path-trigger');
    INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,audit_value,correlation_value,run_value,worker_value,'run_queued',trigger_digest_value,jsonb_build_object('run_id',run_value,'definition_id',candidate.definition_id,'definition_version',candidate.definition_version,'trigger_kind','attack_path','trigger_id',candidate.trigger_id,'trigger_version',candidate.trigger_version,'trigger_state',candidate.trigger_state,'automatic',true,'action','create_temporary_policy'));
    created_value:=created_value+1;
  END LOOP;
  IF created_value>0 THEN UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;END IF;
  RETURN jsonb_build_object('created',created_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_schedule_connector_revocation_triggers(worker_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;trigger_digest_value bytea;run_value text;audit_value text;correlation_value text;created_value integer:=0;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_worker') OR length(worker_value) NOT BETWEEN 1 AND 128 OR limit_value NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='connector revocation scheduling rejected';END IF;
  FOR candidate IN
    WITH eligible AS (
    SELECT definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version definition_version,(definition.body->>'concurrency_limit')::integer concurrency_limit,finding.id trigger_id,finding.version trigger_version,finding.updated_at,
      row_number() OVER (PARTITION BY definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id ORDER BY finding.updated_at,finding.id) definition_ordinal
    FROM zasp_security_agent_definitions definition JOIN zasp_risk_findings finding ON (finding.organization_id,finding.workspace_id,finding.environment_id)=(definition.organization_id,definition.workspace_id,definition.environment_id)
    WHERE definition.activation='supervised' AND definition.deleted_at IS NULL AND definition.body->>'enabled'='true' AND definition.body->>'trigger_kind'='finding' AND definition.body->'environment_ids' ? definition.environment_id AND COALESCE(finding.rule,finding.source)=definition.body->>'trigger_source' AND finding.status='open' AND definition.body->'allowed_actions'=jsonb_build_array('revoke_integration_connection') AND definition.body->>'verification_kind'='connection_state'
      AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'*',true)) AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'revoke_integration_connection',true))
      AND (SELECT count(DISTINCT evidence.integration_id) FROM zasp_risk_finding_evidence finding_evidence JOIN zasp_inventory_evidence evidence ON (evidence.organization_id,evidence.workspace_id,evidence.environment_id,evidence.id)=(finding_evidence.organization_id,finding_evidence.workspace_id,finding_evidence.environment_id,finding_evidence.evidence_id) WHERE (finding_evidence.organization_id,finding_evidence.workspace_id,finding_evidence.environment_id,finding_evidence.finding_id)=(finding.organization_id,finding.workspace_id,finding.environment_id,finding.id))=1
      AND EXISTS(
        SELECT 1
        FROM zasp_risk_finding_evidence finding_evidence
        JOIN zasp_inventory_evidence evidence ON (evidence.organization_id,evidence.workspace_id,evidence.environment_id,evidence.id)=(finding_evidence.organization_id,finding_evidence.workspace_id,finding_evidence.environment_id,finding_evidence.evidence_id)
        JOIN zasp_integration_connections connection ON (connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,connection.state)=(evidence.organization_id,evidence.workspace_id,evidence.environment_id,evidence.integration_id,'verified')
        JOIN zasp_integrations integration ON (integration.organization_id,integration.workspace_id,integration.environment_id,integration.id,integration.state)=(connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,'active')
        JOIN zasp_workflow_records workflow ON (workflow.organization_id,workflow.workspace_id,workflow.environment_id,workflow.kind,workflow.id)=(connection.organization_id,connection.workspace_id,connection.environment_id,'integration',connection.integration_id)
        WHERE (finding_evidence.organization_id,finding_evidence.workspace_id,finding_evidence.environment_id,finding_evidence.finding_id)=(finding.organization_id,finding.workspace_id,finding.environment_id,finding.id)
          AND workflow.deleted_at IS NULL AND workflow.body->>'status'='active' AND workflow.body->>'connector_key'=connection.provider AND integration.kind=connection.provider AND connection.provider IN('github','okta')
          AND (SELECT count(*) FROM zasp_integration_connections candidate_connection WHERE (candidate_connection.organization_id,candidate_connection.workspace_id,candidate_connection.environment_id,candidate_connection.integration_id,candidate_connection.state)=(evidence.organization_id,evidence.workspace_id,evidence.environment_id,evidence.integration_id,'verified'))=1
          AND (SELECT count(*) FROM zasp_connector_credentials candidate_credential WHERE (candidate_credential.organization_id,candidate_credential.workspace_id,candidate_credential.environment_id,candidate_credential.integration_id,candidate_credential.status)=(evidence.organization_id,evidence.workspace_id,evidence.environment_id,evidence.integration_id,'active'))=1
          AND EXISTS(SELECT 1 FROM zasp_connector_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.integration_id,credential.provider,credential.credential_reference,credential.status)=(connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,connection.provider,connection.connection_reference,'active') AND (connection.provider='github' AND credential.credential_class='github_installation_reference' AND CASE WHEN connection.connection_reference ~ '^ref:github/installation/[1-9][0-9]{0,19}$' THEN substring(connection.connection_reference FROM 25)::numeric<=9223372036854775807 ELSE false END OR connection.provider='okta' AND credential.credential_class='okta_refresh_reference' AND connection.connection_reference LIKE 'ref:okta/refresh/%' AND length(connection.connection_reference)>17))
      )
      AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,finding.id,finding.version))
      AND (SELECT count(*) FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.definition_id)=(definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id) AND run.state IN('queued','planning','waiting_approval','running','verifying','contained'))<(definition.body->>'concurrency_limit')::integer
    )
    SELECT organization_id,workspace_id,environment_id,definition_id,definition_version,concurrency_limit,trigger_id,trigger_version,updated_at FROM eligible WHERE definition_ordinal=1
    ORDER BY updated_at,organization_id,workspace_id,environment_id,definition_id,trigger_id LIMIT limit_value
  LOOP
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,'connector-revocation-trigger'),0));
    CONTINUE WHEN EXISTS(SELECT 1 FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.trigger_id,candidate.trigger_version));
    CONTINUE WHEN (SELECT count(*) FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.definition_id)=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id) AND run.state IN('queued','planning','waiting_approval','running','verifying','contained'))>=candidate.concurrency_limit;
    trigger_digest_value:=digest(convert_to(jsonb_build_object('kind','finding','id',candidate.trigger_id,'version',candidate.trigger_version)::text,'UTF8'),'sha256');
    run_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_run',candidate.definition_id||chr(31)||candidate.trigger_id||chr(31)||candidate.trigger_version::text);
    INSERT INTO zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.trigger_id,'finding',candidate.trigger_version,trigger_digest_value,run_value) ON CONFLICT DO NOTHING;CONTINUE WHEN NOT FOUND;
    INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,run_value,candidate.definition_id,candidate.definition_version,candidate.trigger_id,worker_value,'queued');
    audit_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_audit',run_value||chr(31)||'connector-revocation-trigger');correlation_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_correlation',run_value||chr(31)||'connector-revocation-trigger');
    INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,audit_value,correlation_value,run_value,worker_value,'run_queued',trigger_digest_value,jsonb_build_object('run_id',run_value,'definition_id',candidate.definition_id,'definition_version',candidate.definition_version,'trigger_kind','finding','trigger_id',candidate.trigger_id,'trigger_version',candidate.trigger_version,'automatic',true,'action','revoke_integration_connection'));
    created_value:=created_value+1;
  END LOOP;
  IF created_value>0 THEN UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;END IF;
  RETURN jsonb_build_object('created',created_value);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_schedule_session_isolation_triggers(worker_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;trigger_digest_value bytea;run_value text;audit_value text;correlation_value text;created_value integer:=0;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_worker') OR length(worker_value) NOT BETWEEN 1 AND 128 OR limit_value NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session isolation scheduling rejected';END IF;
  FOR candidate IN
    WITH violations AS (
      SELECT definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version definition_version,(definition.body->>'concurrency_limit')::integer concurrency_limit,
             event.classification->>'session_id' session_id,event.device_id,max(event.sequence) trigger_version,max(event.occurred_at) occurred_at,count(*) violation_count
      FROM zasp_security_agent_definitions definition
      JOIN zasp_runtime_gateway_events event ON (event.organization_id,event.workspace_id,event.environment_id)=(definition.organization_id,definition.workspace_id,definition.environment_id)
      JOIN zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,'active')
      JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.credential_id)
      WHERE definition.activation='supervised' AND definition.deleted_at IS NULL AND definition.body->>'enabled'='true' AND definition.body->>'trigger_kind'='runtime_decision' AND definition.body->'environment_ids' ? definition.environment_id
        AND definition.body->'allowed_actions'=jsonb_build_array('isolate_session') AND definition.body->>'verification_kind'='gateway_decision'
        AND event.decision='block' AND event.classification ? 'session_id' AND zasp_valid_product_id(event.classification->>'session_id') AND event.classification->>'outcome'=definition.body->>'trigger_source' AND event.occurred_at>=transaction_timestamp()-interval '5 minutes'
        AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp()
        AND credential.id=(SELECT current_credential.id FROM zasp_gateway_credentials current_credential WHERE (current_credential.organization_id,current_credential.workspace_id,current_credential.environment_id,current_credential.device_id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id) AND current_credential.revoked_at IS NULL AND current_credential.expires_at>transaction_timestamp() ORDER BY current_credential.issued_at DESC,current_credential.id DESC LIMIT 1)
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true))
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'*',true))
        AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(definition.organization_id,definition.workspace_id,definition.environment_id,'isolate_session',true))
        AND (SELECT count(*) FROM zasp_security_agent_runs running WHERE (running.organization_id,running.workspace_id,running.environment_id,running.definition_id)=(definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id) AND running.state IN('queued','planning','waiting_approval','running','verifying','contained'))<(definition.body->>'concurrency_limit')::integer
      GROUP BY definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version,(definition.body->>'concurrency_limit')::integer,event.classification->>'session_id',event.device_id
      HAVING count(*)>=3
    ), eligible AS (
      SELECT violations.*,row_number() OVER(PARTITION BY organization_id,workspace_id,environment_id,definition_id ORDER BY occurred_at,session_id,device_id) definition_ordinal
      FROM violations
      WHERE NOT EXISTS(SELECT 1 FROM zasp_security_agent_trigger_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.definition_id,receipt.trigger_id,receipt.trigger_version)=(violations.organization_id,violations.workspace_id,violations.environment_id,violations.definition_id,violations.session_id,violations.trigger_version))
    ) SELECT * FROM eligible WHERE definition_ordinal=1 ORDER BY occurred_at,organization_id,workspace_id,environment_id,definition_id LIMIT limit_value
  LOOP
    SELECT digest(convert_to(jsonb_build_object('kind','runtime_decision','session_id',candidate.session_id,'device_id',candidate.device_id,'events',COALESCE(jsonb_agg(jsonb_build_object('event_id',event_id,'sequence',sequence,'request_digest','sha256:'||encode(request_digest,'hex')) ORDER BY sequence,event_id),'[]'::jsonb))::text,'UTF8'),'sha256') INTO trigger_digest_value
    FROM (SELECT event.event_id,event.sequence,event.request_digest FROM zasp_runtime_gateway_events event WHERE (event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.classification->>'session_id')=(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.device_id,candidate.session_id) AND event.decision='block' AND event.sequence<=candidate.trigger_version ORDER BY event.sequence DESC,event.event_id DESC LIMIT 3) recent;
    run_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_run',candidate.definition_id||chr(31)||candidate.session_id||chr(31)||candidate.trigger_version);
    audit_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_audit',run_value||chr(31)||'queued');
    correlation_value:=zasp_discovery_canonical_id(candidate.organization_id,candidate.workspace_id,candidate.environment_id,'security_agent_correlation',run_value||chr(31)||'queued');
    INSERT INTO zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.session_id,'runtime_decision',candidate.trigger_version,trigger_digest_value,run_value) ON CONFLICT DO NOTHING;
    IF NOT FOUND THEN CONTINUE;END IF;
    INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,run_value,candidate.definition_id,candidate.definition_version,candidate.session_id,worker_value,'queued');
    INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(candidate.organization_id,candidate.workspace_id,candidate.environment_id,audit_value,correlation_value,run_value,worker_value,'run_queued',trigger_digest_value,jsonb_build_object('run_id',run_value,'definition_id',candidate.definition_id,'definition_version',candidate.definition_version,'trigger_kind','runtime_decision','trigger_id',candidate.session_id,'trigger_version',candidate.trigger_version,'device_id',candidate.device_id,'count',candidate.violation_count));
    created_value:=created_value+1;
  END LOOP;
  RETURN jsonb_build_object('created',created_value);
END
$function$

