CREATE OR REPLACE FUNCTION public.zasp_security_agent_set_kill_switch(organization_value text, workspace_value text, environment_value text, action_value text, enabled_value boolean, expected_version bigint, actor_value text, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value zasp_security_agent_kill_switches%ROWTYPE;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR length(organization_value) NOT BETWEEN 1 AND 128 OR length(workspace_value) NOT BETWEEN 1 AND 128 OR length(environment_value) NOT BETWEEN 1 AND 128 OR length(action_value) NOT BETWEEN 1 AND 128
     OR length(actor_value) NOT BETWEEN 1 AND 128 OR length(audit_value) NOT BETWEEN 1 AND 128 OR length(correlation_value) NOT BETWEEN 1 AND 128 OR expected_version<0 THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent kill switch rejected';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,action_value),0));
  IF expected_version=0 THEN
    INSERT INTO zasp_security_agent_kill_switches(organization_id,workspace_id,environment_id,action_key,execution_enabled,updated_by)
    VALUES(organization_value,workspace_value,environment_value,action_value,enabled_value,actor_value)
    RETURNING * INTO result_value;
  ELSE
    UPDATE zasp_security_agent_kill_switches switch_row SET execution_enabled=enabled_value,version=switch_row.version+1,updated_by=actor_value,updated_at=transaction_timestamp()
    WHERE (switch_row.organization_id,switch_row.workspace_id,switch_row.environment_id,switch_row.action_key,switch_row.version)=(organization_value,workspace_value,environment_value,action_value,expected_version)
    RETURNING * INTO result_value;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent kill switch version conflict';END IF;
  END IF;
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,actor_id,event_kind,event_digest,body)
  VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,actor_value,'kill_switch_changed',digest(convert_to(jsonb_build_object('action_key',action_value,'enabled',enabled_value,'version',result_value.version)::text,'UTF8'),'sha256'),jsonb_build_object('action_key',action_value,'enabled',enabled_value,'version',result_value.version));
  UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
  RETURN jsonb_build_object('action_key',result_value.action_key,'enabled',result_value.execution_enabled,'version',result_value.version,'replayed',false);
EXCEPTION WHEN unique_violation THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent kill switch version conflict';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_simulate(organization_value text, workspace_value text, environment_value text, definition_value text, actor_value text, idempotency_value text, expected_version bigint, run_value text, goal_value text, evidence_values jsonb, expires_value timestamp with time zone, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row zasp_security_agent_definitions%ROWTYPE; receipt_row zasp_security_agent_request_receipts%ROWTYPE; canonical_evidence jsonb; steps_value jsonb; plan_value jsonb; plan_digest bytea; trigger_digest_value bytea; intent_value jsonb; intent_digest_value bytea; response_value jsonb; summary_value text;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR expected_version<=0 OR NOT zasp_valid_product_id(definition_value) OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR NOT zasp_valid_product_id(receipt_value)
     OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' OR length(goal_value) NOT BETWEEN 1 AND 1024 OR btrim(goal_value)<>goal_value OR goal_value~'[[:cntrl:]]'
     OR jsonb_typeof(evidence_values)<>'array' OR jsonb_array_length(evidence_values) NOT BETWEEN 1 AND 100 OR expires_value IS NULL OR expires_value<=transaction_timestamp() OR expires_value>transaction_timestamp()+interval '16 minutes' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent simulation rejected';
  END IF;
  SELECT jsonb_agg(evidence ORDER BY evidence) INTO canonical_evidence FROM jsonb_array_elements_text(evidence_values) evidence;
  IF (SELECT count(*) FROM jsonb_array_elements_text(canonical_evidence))<>(SELECT count(DISTINCT evidence) FROM jsonb_array_elements_text(canonical_evidence) evidence)
     OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(canonical_evidence) evidence WHERE NOT zasp_valid_product_id(evidence)) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent simulation evidence rejected';
  END IF;
  intent_value:=jsonb_build_object('definition_id',definition_value,'expected_version',expected_version,'goal',goal_value,'evidence_ids',canonical_evidence,'expires_at',to_char(expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'simulateSecurityAgent',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt
  WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'simulateSecurityAgent',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>definition_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=transaction_timestamp() OR (receipt_row.response->>'expires_at')::timestamptz<=transaction_timestamp()
       OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_definitions current_definition WHERE (current_definition.organization_id,current_definition.workspace_id,current_definition.environment_id,current_definition.definition_id,current_definition.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version) AND current_definition.deleted_at IS NULL) THEN
      RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent simulation replay conflict';
    END IF;
    IF EXISTS(
      SELECT 1 FROM jsonb_array_elements_text(receipt_row.response->'matched_evidence_ids') evidence
      WHERE NOT EXISTS(SELECT 1 FROM zasp_risk_findings finding WHERE (finding.organization_id,finding.workspace_id,finding.environment_id,finding.id)=(organization_value,workspace_value,environment_value,evidence) AND finding.status IN('open','under_review','accepted'))
        AND NOT EXISTS(SELECT 1 FROM zasp_risk_attack_paths path WHERE (path.organization_id,path.workspace_id,path.environment_id,path.id)=(organization_value,workspace_value,environment_value,evidence) AND path.state IN('observed','verified'))
        AND NOT EXISTS(SELECT 1 FROM zasp_inventory_entities entity WHERE (entity.organization_id,entity.workspace_id,entity.environment_id,entity.id,entity.state)=(organization_value,workspace_value,environment_value,evidence,'active'))
        AND NOT EXISTS(SELECT 1 FROM zasp_inventory_evidence evidence_row WHERE (evidence_row.organization_id,evidence_row.workspace_id,evidence_row.environment_id,evidence_row.id)=(organization_value,workspace_value,environment_value,evidence))
    ) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent simulation replay denied';END IF;

    IF EXISTS(SELECT 1 FROM public.zasp_security_agent_definitions d
      WHERE (d.organization_id,d.workspace_id,d.environment_id,d.definition_id)=(organization_value,workspace_value,environment_value,definition_value)
       AND (d.body ? 'existing_test' OR d.body->'allowed_actions' ?| ARRAY['run_test','rerun_test','start_attack_lab']))
     OR EXISTS(SELECT 1 FROM public.zasp_security_agent_definition_versions h
      WHERE (h.organization_id,h.workspace_id,h.environment_id,h.definition_id,h.version)=(organization_value,workspace_value,environment_value,definition_value,receipt_row.expected_version)
       AND (h.definition ? 'existing_test' OR h.definition->'allowed_actions' ?| ARRAY['run_test','rerun_test','start_attack_lab'])) THEN
     RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test lifecycle requires versioned authority';
    END IF;
    RETURN receipt_row.response||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO definition_row FROM zasp_security_agent_definitions candidate
  WHERE (candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version)
    AND candidate.deleted_at IS NULL AND candidate.activation IN('validated','supervised','autonomous') AND candidate.body->'environment_ids' ? environment_value FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent simulation definition rejected';END IF;
  IF definition_row.body ? 'existing_test' OR definition_row.body->'allowed_actions' ?| ARRAY['run_test','rerun_test','start_attack_lab'] THEN
   RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test lifecycle requires versioned authority';
  END IF;

  IF EXISTS(
    SELECT 1 FROM jsonb_array_elements_text(canonical_evidence) evidence
    WHERE NOT EXISTS(SELECT 1 FROM zasp_risk_findings finding WHERE (finding.organization_id,finding.workspace_id,finding.environment_id,finding.id)=(organization_value,workspace_value,environment_value,evidence) AND finding.status IN('open','under_review','accepted'))
      AND NOT EXISTS(SELECT 1 FROM zasp_risk_attack_paths path WHERE (path.organization_id,path.workspace_id,path.environment_id,path.id)=(organization_value,workspace_value,environment_value,evidence) AND path.state IN('observed','verified'))
      AND NOT EXISTS(SELECT 1 FROM zasp_inventory_entities entity WHERE (entity.organization_id,entity.workspace_id,entity.environment_id,entity.id,entity.state)=(organization_value,workspace_value,environment_value,evidence,'active'))
      AND NOT EXISTS(SELECT 1 FROM zasp_inventory_evidence evidence_row WHERE (evidence_row.organization_id,evidence_row.workspace_id,evidence_row.environment_id,evidence_row.id)=(organization_value,workspace_value,environment_value,evidence))
  ) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent simulation evidence denied';END IF;
  SELECT jsonb_agg(jsonb_build_object('index',ordinality-1,'action',action,'authorization',CASE WHEN definition_row.body->>'autonomy'='supervised' THEN 'approval_required' ELSE 'allow' END,'approval_required',definition_row.body->>'autonomy'='supervised') ORDER BY ordinality)
  INTO steps_value FROM jsonb_array_elements_text(definition_row.body->'allowed_actions') WITH ORDINALITY action_rows(action,ordinality) WHERE ordinality<=(definition_row.body->>'max_steps')::integer;
  IF jsonb_typeof(steps_value)<>'array' OR jsonb_array_length(steps_value) NOT BETWEEN 1 AND LEAST(100,(definition_row.body->>'max_steps')::integer) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent simulation plan rejected';END IF;
  summary_value:=format('Planned %s action(s) from %s evidence record(s)',jsonb_array_length(steps_value),jsonb_array_length(canonical_evidence));
  plan_value:=jsonb_build_object(
    'version',1,'definition_id',definition_value,'definition_version',expected_version,'catalog_version',definition_row.plan_catalog_version,
    'target_scope',jsonb_build_object('organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value),
    'goal',goal_value,'summary',summary_value,'evidence_ids',canonical_evidence,'steps',steps_value,
    'budgets',jsonb_build_object('max_steps',(definition_row.body->>'max_steps')::integer,'max_duration_seconds',(definition_row.body->>'max_duration_seconds')::integer,'temporary_policy_seconds',(definition_row.body->>'temporary_policy_seconds')::integer,'ai_token_budget',(definition_row.body->>'ai_token_budget')::integer,'concurrency_limit',(definition_row.body->>'concurrency_limit')::integer),
    'verification',jsonb_build_object('kind',definition_row.body->>'verification_kind'),'expires_at',to_char(expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  plan_digest:=digest(convert_to(plan_value::text,'UTF8'),'sha256');trigger_digest_value:=digest(convert_to(jsonb_build_object('kind','simulation','evidence_ids',canonical_evidence,'goal',goal_value)::text,'UTF8'),'sha256');
  INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state,plan_hash,completed_at)
  VALUES(organization_value,workspace_value,environment_value,run_value,definition_value,expected_version,encode(trigger_digest_value,'hex'),actor_value,'simulated',plan_digest,transaction_timestamp());
  INSERT INTO zasp_security_agent_plans(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_digest,catalog_version,plan,plan_hash,expires_at)
  VALUES(organization_value,workspace_value,environment_value,run_value,definition_value,expected_version,trigger_digest_value,definition_row.plan_catalog_version,plan_value,plan_digest,expires_value);
  INSERT INTO zasp_security_agent_steps(organization_id,workspace_id,environment_id,run_id,step_id,step_index,action_key,input_digest,authorization_result,state)
  SELECT organization_value,workspace_value,environment_value,run_value,zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'security_agent_step',run_value||chr(31)||(step->>'index')), (step->>'index')::integer,step->>'action',digest(convert_to(step::text,'UTF8'),'sha256'),step->>'authorization',CASE WHEN step->>'authorization'='approval_required' THEN 'waiting_approval' ELSE 'authorized' END
  FROM jsonb_array_elements(steps_value) step;
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
  VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,run_value,actor_value,'simulation_created',plan_digest,jsonb_build_object('run_id',run_value,'definition_id',definition_value,'definition_version',expected_version,'plan_hash','sha256:'||encode(plan_digest,'hex'),'side_effects',0));
  response_value:=jsonb_build_object('run_id',run_value,'definition_id',definition_value,'definition_version',expected_version,'plan_hash','sha256:'||encode(plan_digest,'hex'),'catalog_version',definition_row.plan_catalog_version,'expires_at',to_char(expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'matched_evidence_ids',canonical_evidence,'summary',summary_value,'steps',steps_value,'side_effects',0,'version',1,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
  INSERT INTO zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id)
  VALUES(organization_value,workspace_value,environment_value,actor_value,'simulateSecurityAgent',idempotency_value,definition_value,expected_version,intent_value,intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_store_session_policy_target_v27(organization_value text, workspace_value text, environment_value text, run_value text, step_value text, phase_value text, worker_value text, lease_token_value text, device_value text, credential_value text, sequence_value bigint, policy_version_value bigint, key_value text, issued_value timestamp with time zone, expires_value timestamp with time zone, failure_mode_value text, payload_digest_value bytea, policies_value jsonb, signature_value bytea, envelope_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE budget_stop_value jsonb;target_row zasp_security_agent_temporary_policy_targets%ROWTYPE;ttl_seconds integer;session_value text;
BEGIN
 PERFORM zasp_authorization80_worker.ordered_legacy_writer_organization(organization_value);
 IF phase_value='apply' THEN PERFORM zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,false);END IF;
  IF NOT zasp_security_agent_action_principal_ready() OR phase_value NOT IN('apply','cleanup') OR octet_length(payload_digest_value)<>32 OR octet_length(signature_value)<>64 OR octet_length(envelope_digest_value)<>32 OR jsonb_typeof(policies_value)<>'array' OR jsonb_array_length(policies_value)>100 OR phase_value='cleanup' AND policies_value<>'[]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy target rejected';END IF;
  SELECT * INTO target_row FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id,target.credential_id,target.sequence,target.policy_version)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value,credential_value,sequence_value,policy_version_value) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='session policy target missing';END IF;
  PERFORM 1 FROM zasp_security_agent_effects effect WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,effect.state,effect.lease_owner,effect.lease_token)=(organization_value,workspace_value,environment_value,run_value,step_value,target_row.action_key,'leased',worker_value,lease_token_value) AND effect.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session policy lease lost';END IF;
  SELECT (plan.plan->'steps'->0->>'ttl_seconds')::integer,plan.plan->'steps'->0->>'session_id' INTO STRICT ttl_seconds,session_value FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(organization_value,workspace_value,environment_value,run_value);
  IF ttl_seconds NOT BETWEEN 60 AND 3600 OR failure_mode_value<>'closed' OR phase_value='apply' AND expires_value<>issued_value+make_interval(secs=>ttl_seconds) OR phase_value='cleanup' AND expires_value<>issued_value+interval '5 minutes' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy target rejected';END IF;
  IF target_row.action_key='isolate_session' AND phase_value='apply' AND (NOT zasp_valid_product_id(session_value) OR jsonb_array_length(policies_value)<>2 OR EXISTS(SELECT 1 FROM jsonb_array_elements(policies_value) policy WHERE policy->>'action'<>'block' OR NOT policy->'conditions' @> jsonb_build_array(jsonb_build_object('field','session_id','operator','equals','value',session_value)))) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session isolation policy rejected';END IF;
  IF phase_value='apply' AND (NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,target_row.action_key,true))) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session policy execution disabled';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_gateway_devices device WHERE (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(organization_value,workspace_value,environment_value,device_value,'active')) OR credential_value IS DISTINCT FROM (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(organization_value,workspace_value,environment_value,device_value) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session policy credential changed';END IF;

  IF phase_value='apply' AND target_row.state='planned' THEN
   -- Protect the bundle FK before the final clock check. Never wait here
   -- while holding run/effect/target authority needed by another worker.
   BEGIN
    PERFORM 1 FROM zasp_gateway_credentials c WHERE (c.organization_id,c.workspace_id,c.environment_id,c.device_id,c.id)=(organization_value,workspace_value,environment_value,device_value,credential_value) FOR KEY SHARE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='legacy policy credential missing';END IF;
   EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='legacy policy credential busy';END;
   budget_stop_value:=zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,true);
   IF budget_stop_value IS NOT NULL THEN RETURN jsonb_build_object('budget_action_stop',budget_stop_value||jsonb_build_object('phase',phase_value,'device_id',device_value,'credential_id',credential_value,'sequence',sequence_value,'policy_version',policy_version_value));END IF;
  END IF;
  BEGIN
  IF target_row.state<>'planned' THEN
    IF (target_row.key_id,target_row.issued_at,target_row.expires_at,target_row.failure_mode,target_row.payload_digest,target_row.policies,target_row.signature,target_row.envelope_digest) IS DISTINCT FROM (key_value,issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='session policy target replay conflict';END IF;
  ELSE
    INSERT INTO zasp_runtime_gateway_policy_bundles(organization_id,workspace_id,environment_id,device_id,credential_id,sequence,policy_version,key_id,algorithm,audience,issued_at,expires_at,failure_mode,payload_digest,policies,signature,envelope_digest) VALUES(organization_value,workspace_value,environment_value,device_value,credential_value,sequence_value,policy_version_value,key_value,'Ed25519','runtime-gateway-policy',issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value) ON CONFLICT(organization_id,workspace_id,environment_id,device_id,sequence) DO NOTHING;
    IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM zasp_runtime_gateway_policy_bundles bundle WHERE (bundle.organization_id,bundle.workspace_id,bundle.environment_id,bundle.device_id,bundle.credential_id,bundle.sequence,bundle.policy_version,bundle.key_id,bundle.issued_at,bundle.expires_at,bundle.failure_mode,bundle.payload_digest,bundle.policies,bundle.signature,bundle.envelope_digest)=(organization_value,workspace_value,environment_value,device_value,credential_value,sequence_value,policy_version_value,key_value,issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='session policy bundle conflict';END IF;
    UPDATE zasp_security_agent_temporary_policy_targets target SET state='stored',key_id=key_value,issued_at=issued_value,expires_at=expires_value,failure_mode=failure_mode_value,payload_digest=payload_digest_value,policies=policies_value,signature=signature_value,envelope_digest=envelope_digest_value,stored_at=transaction_timestamp() WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value);
  END IF;

   -- Unique-index insertion can wait after the precheck. All writes above are
   -- tentative until this current-clock check succeeds. A stop rolls them back
   -- together, then is persisted outside the failed subtransaction.
   IF phase_value='apply' AND target_row.state='planned' THEN
    budget_stop_value:=zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,true);
    IF budget_stop_value IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='ZB001',MESSAGE='legacy policy budget rollback';END IF;
   END IF;
  EXCEPTION WHEN SQLSTATE 'ZB001' THEN
   budget_stop_value:=zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,true);
   IF budget_stop_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='legacy policy stop changed';END IF;
   RETURN jsonb_build_object('budget_action_stop',budget_stop_value||jsonb_build_object('phase',phase_value,'device_id',device_value,'credential_id',credential_value,'sequence',sequence_value,'policy_version',policy_version_value));
  END;
  RETURN jsonb_build_object('device_id',device_value,'phase',phase_value,'sequence',sequence_value,'policy_version',policy_version_value,'envelope_digest','sha256:'||encode(envelope_digest_value,'hex'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_store_temporary_policy_target_v27(organization_value text, workspace_value text, environment_value text, run_value text, step_value text, phase_value text, worker_value text, lease_token_value text, device_value text, credential_value text, sequence_value bigint, policy_version_value bigint, key_value text, issued_value timestamp with time zone, expires_value timestamp with time zone, failure_mode_value text, payload_digest_value bytea, policies_value jsonb, signature_value bytea, envelope_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE budget_stop_value jsonb;target_row zasp_security_agent_temporary_policy_targets%ROWTYPE;ttl_seconds integer;
BEGIN
 PERFORM zasp_authorization80_worker.ordered_legacy_writer_organization(organization_value);
  PERFORM zasp_sa_multistep_prior.legacy_action_fence(organization_value,workspace_value,environment_value,run_value);
 IF phase_value='apply' THEN PERFORM zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,false);END IF;
  IF NOT zasp_security_agent_action_principal_ready() OR phase_value NOT IN('apply','cleanup') OR octet_length(payload_digest_value)<>32 OR octet_length(signature_value)<>64 OR octet_length(envelope_digest_value)<>32 OR jsonb_typeof(policies_value)<>'array' OR jsonb_array_length(policies_value)>100 OR (phase_value='cleanup' AND policies_value<>'[]'::jsonb) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='temporary policy target rejected';
  END IF;
  PERFORM 1 FROM zasp_security_agent_effects effect WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,effect.state,effect.lease_owner,effect.lease_token)=(organization_value,workspace_value,environment_value,run_value,step_value,'create_temporary_policy','leased',worker_value,lease_token_value) AND effect.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='temporary policy lease lost';END IF;
  SELECT (plan.plan->'steps'->0->>'ttl_seconds')::integer INTO STRICT ttl_seconds FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(organization_value,workspace_value,environment_value,run_value);
  IF ttl_seconds NOT BETWEEN 60 AND 3600 OR failure_mode_value<>'closed' OR phase_value='apply' AND expires_value<>issued_value+make_interval(secs=>ttl_seconds) OR phase_value='cleanup' AND expires_value<>issued_value+interval '5 minutes' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='temporary policy target rejected';
  END IF;
  IF phase_value='apply' AND (NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true))
     OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true))
     OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'create_temporary_policy',true))) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='temporary policy execution disabled';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_gateway_devices device WHERE (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(organization_value,workspace_value,environment_value,device_value,'active'))
     OR credential_value IS DISTINCT FROM (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(organization_value,workspace_value,environment_value,device_value) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1) THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='temporary policy credential changed';
  END IF;
  SELECT * INTO target_row FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id,target.credential_id,target.sequence,target.policy_version)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value,credential_value,sequence_value,policy_version_value) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='temporary policy target missing';END IF;

  IF phase_value='apply' AND target_row.state='planned' THEN
   -- Protect the bundle FK before the final clock check. Never wait here
   -- while holding run/effect/target authority needed by another worker.
   BEGIN
    PERFORM 1 FROM zasp_gateway_credentials c WHERE (c.organization_id,c.workspace_id,c.environment_id,c.device_id,c.id)=(organization_value,workspace_value,environment_value,device_value,credential_value) FOR KEY SHARE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='legacy policy credential missing';END IF;
   EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='legacy policy credential busy';END;
   budget_stop_value:=zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,true);
   IF budget_stop_value IS NOT NULL THEN RETURN jsonb_build_object('budget_action_stop',budget_stop_value||jsonb_build_object('phase',phase_value,'device_id',device_value,'credential_id',credential_value,'sequence',sequence_value,'policy_version',policy_version_value));END IF;
  END IF;
  BEGIN
  IF target_row.state<>'planned' THEN
    IF (target_row.key_id,target_row.issued_at,target_row.expires_at,target_row.failure_mode,target_row.payload_digest,target_row.policies,target_row.signature,target_row.envelope_digest) IS DISTINCT FROM (key_value,issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='temporary policy target replay conflict';END IF;
  ELSE
    INSERT INTO zasp_runtime_gateway_policy_bundles(organization_id,workspace_id,environment_id,device_id,credential_id,sequence,policy_version,key_id,algorithm,audience,issued_at,expires_at,failure_mode,payload_digest,policies,signature,envelope_digest)
    VALUES(organization_value,workspace_value,environment_value,device_value,credential_value,sequence_value,policy_version_value,key_value,'Ed25519','runtime-gateway-policy',issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value)
    ON CONFLICT(organization_id,workspace_id,environment_id,device_id,sequence) DO NOTHING;
    IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM zasp_runtime_gateway_policy_bundles bundle WHERE (bundle.organization_id,bundle.workspace_id,bundle.environment_id,bundle.device_id,bundle.credential_id,bundle.sequence,bundle.policy_version,bundle.key_id,bundle.issued_at,bundle.expires_at,bundle.failure_mode,bundle.payload_digest,bundle.policies,bundle.signature,bundle.envelope_digest)=(organization_value,workspace_value,environment_value,device_value,credential_value,sequence_value,policy_version_value,key_value,issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='temporary policy bundle conflict';END IF;
    UPDATE zasp_security_agent_temporary_policy_targets target SET state='stored',key_id=key_value,issued_at=issued_value,expires_at=expires_value,failure_mode=failure_mode_value,payload_digest=payload_digest_value,policies=policies_value,signature=signature_value,envelope_digest=envelope_digest_value,stored_at=transaction_timestamp()
    WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value);
  END IF;

   -- Unique-index insertion can wait after the precheck. All writes above are
   -- tentative until this current-clock check succeeds. A stop rolls them back
   -- together, then is persisted outside the failed subtransaction.
   IF phase_value='apply' AND target_row.state='planned' THEN
    budget_stop_value:=zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,true);
    IF budget_stop_value IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='ZB001',MESSAGE='legacy policy budget rollback';END IF;
   END IF;
  EXCEPTION WHEN SQLSTATE 'ZB001' THEN
   budget_stop_value:=zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,true);
   IF budget_stop_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='legacy policy stop changed';END IF;
   RETURN jsonb_build_object('budget_action_stop',budget_stop_value||jsonb_build_object('phase',phase_value,'device_id',device_value,'credential_id',credential_value,'sequence',sequence_value,'policy_version',policy_version_value));
  END;
  RETURN jsonb_build_object('device_id',device_value,'phase',phase_value,'sequence',sequence_value,'policy_version',policy_version_value,'envelope_digest','sha256:'||encode(envelope_digest_value,'hex'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_sync_definition_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE synchronized zasp_security_agent_definitions%ROWTYPE;
BEGIN
  IF NEW.kind<>'security_agent' THEN RETURN NEW;END IF;
  INSERT INTO zasp_security_agent_definitions(organization_id,workspace_id,environment_id,definition_id,activation,version,definition_version,body,plan_catalog_version,deleted_at,created_at,updated_at)
  VALUES(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.id,'draft',1,(NEW.body->>'definition_version')::integer,NEW.body||jsonb_build_object('enabled',false),'security-agent-actions-v1',NEW.deleted_at,NEW.created_at,NEW.updated_at)
  ON CONFLICT(organization_id,workspace_id,environment_id,definition_id) DO UPDATE SET activation='draft',version=zasp_security_agent_definitions.version+1,definition_version=(excluded.body->>'definition_version')::integer,body=excluded.body||jsonb_build_object('enabled',false),plan_catalog_version='security-agent-actions-v1',deleted_at=excluded.deleted_at,updated_at=excluded.updated_at
  RETURNING * INTO synchronized;
  INSERT INTO zasp_security_agent_definition_versions(organization_id,workspace_id,environment_id,definition_id,version,activation,definition,definition_digest,actor_id,created_at)
  VALUES(synchronized.organization_id,synchronized.workspace_id,synchronized.environment_id,synchronized.definition_id,synchronized.version,'draft',synchronized.body,digest(convert_to(synchronized.body::text,'UTF8'),'sha256'),session_user,synchronized.updated_at);
  UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
  RETURN NEW;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_test_dispatch(o text, w text, e text, r text, worker_value text, lease_value text, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_security_agent_runs%ROWTYPE;step_row public.zasp_security_agent_steps%ROWTYPE;
 plan_row public.zasp_security_agent_plans%ROWTYPE;definition_row public.zasp_security_agent_definitions%ROWTYPE;
 trigger_row public.zasp_security_agent_trigger_receipts%ROWTYPE;control_row record;control_count integer:=0;
 link_value jsonb;step_value jsonb;outcome_value text;result_digest_value bytea;response_value jsonb;runtime_expires timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test dispatch input rejected';END IF;
 -- The existing guard establishes principal, full scope, organization-before-
 -- run lock order, current lease and authoritative budget/stop state.
 IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RETURN public.zasp_security_agent_budget_stop_result(o,w,e,r,'execute');END IF;
 SELECT * INTO STRICT run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO plan_row FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) FOR SHARE;
 IF NOT FOUND OR plan_row.plan_hash IS DISTINCT FROM run_row.plan_hash OR plan_row.plan_hash IS DISTINCT FROM digest(convert_to(plan_row.plan::text,'UTF8'),'sha256') OR plan_row.expires_at<=clock_timestamp()
  OR jsonb_typeof(plan_row.plan->'steps') IS DISTINCT FROM 'array' OR jsonb_array_length(plan_row.plan->'steps')<>1 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test plan changed';END IF;
 SELECT * INTO step_row FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_index,state)=(o,w,e,r,0,'authorized') FOR UPDATE;
 IF NOT FOUND OR step_row.action_key NOT IN('run_test','rerun_test') OR step_row.input_digest IS DISTINCT FROM digest(convert_to((plan_row.plan->'steps'->0)::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test step changed';END IF;
 SELECT * INTO definition_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,run_row.definition_id,run_row.definition_version) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR definition_row.activation NOT IN('supervised','autonomous') OR definition_row.body->>'autonomy' IS DISTINCT FROM definition_row.activation OR definition_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb
  OR definition_row.body->'allowed_actions' IS DISTINCT FROM jsonb_build_array(step_row.action_key) OR definition_row.body->>'verification_kind' IS DISTINCT FROM 'test_run' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test definition changed';END IF;
 step_value:=plan_row.plan->'steps'->0;
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,step_row.step_id);
 SELECT * INTO trigger_row FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id,trigger_digest)=(o,w,e,r,run_row.definition_id,run_row.trigger_id,plan_row.trigger_digest) FOR SHARE;
 IF NOT FOUND OR trigger_row.trigger_kind<>'manual' AND trigger_row.trigger_kind IS DISTINCT FROM definition_row.body->>'trigger_kind' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test trigger changed';END IF;
 IF trigger_row.trigger_kind='manual' THEN PERFORM public.zasp_sa_manual_recheck(o,w,e,r); PERFORM 1; ELSIF trigger_row.trigger_kind='finding' THEN
  PERFORM 1 FROM public.zasp_risk_findings WHERE (organization_id,workspace_id,environment_id,id,version,status,rule)=(o,w,e,trigger_row.trigger_id,trigger_row.trigger_version,'open',definition_row.body->>'trigger_source') FOR SHARE;
 ELSIF trigger_row.trigger_kind='attack_path' THEN
  PERFORM 1 FROM public.zasp_risk_attack_paths p WHERE (organization_id,workspace_id,environment_id,id,version,state)=(o,w,e,trigger_row.trigger_id,trigger_row.trigger_version,definition_row.body->>'trigger_source') AND state IN('observed','verified') AND public.zasp_risk_attack_path_valid(p) FOR SHARE;
 ELSIF trigger_row.trigger_kind='runtime_decision' THEN
  SELECT credential.expires_at INTO runtime_expires FROM public.zasp_runtime_gateway_events event
  JOIN public.zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,'active')
  JOIN public.zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(event.organization_id,event.workspace_id,event.environment_id,event.device_id,event.credential_id)
  WHERE (event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id',event.sequence,event.decision,event.classification->>'outcome')=(o,w,e,trigger_row.trigger_id,trigger_row.trigger_version,'block',definition_row.body->>'trigger_source')
   AND credential.revoked_at IS NULL AND credential.expires_at>clock_timestamp()
   AND digest(convert_to(jsonb_build_object('kind','runtime_decision','session_id',trigger_row.trigger_id,'device_id',event.device_id,'event_id',event.event_id,'sequence',event.sequence,'request_digest','sha256:'||encode(event.request_digest,'hex'))::text,'UTF8'),'sha256')=trigger_row.trigger_digest
  FOR SHARE OF event,device,credential;
 ELSE RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test trigger unsupported';
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test evidence changed';END IF;
 FOR control_row IN SELECT * FROM public.zasp_security_agent_kill_switches
  WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*',step_row.action_key)
  ORDER BY organization_id,workspace_id,environment_id,action_key FOR SHARE LOOP
  control_count:=control_count+1;
  IF NOT control_row.execution_enabled THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test execution disabled';END IF;
 END LOOP;
 IF control_count<>3 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test execution disabled';END IF;
 BEGIN
  IF NOT public.zasp_security_agent_budget_reserve_step(o,w,e,r,worker_value,lease_value,step_row.step_id) THEN RETURN public.zasp_security_agent_budget_stop_result(o,w,e,r,'execute');END IF;
  INSERT INTO public.zasp_security_agent_effects(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state) VALUES(o,w,e,r,step_row.step_id,step_row.action_key,step_row.input_digest,'pending');
  link_value:=public.zasp_security_agent_test_link_enqueue(o,w,e,r,step_row.step_id,correlation_value);
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id,target_id,target_kind)=(o,w,e,r,step_row.step_id,step_value->>'test_target_id',step_value->>'test_target_kind')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test target changed';END IF;
  IF plan_row.expires_at<=clock_timestamp() OR runtime_expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test authority expired';END IF;
  PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,step_row.step_id);
  IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RAISE EXCEPTION USING ERRCODE='PZ001',MESSAGE='existing test budget stopped';END IF;
  outcome_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_effect',r||chr(31)||step_row.step_id||chr(31)||step_row.action_key);
  result_digest_value:=digest(convert_to(link_value::text,'UTF8'),'sha256');
  UPDATE public.zasp_security_agent_effects SET outcome_id=outcome_value,result_digest=result_digest_value WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,step_row.step_id,step_row.action_key);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,correlation_value,r,step_row.step_id,worker_value,'effect_dispatched',result_digest_value,jsonb_build_object('run_id',r,'step_id',step_row.step_id,'action',step_row.action_key,'test_run_id',link_value->>'test_run_id','test_definition_id',link_value->>'definition_id','outcome_id',outcome_value));
  -- Audit relation/index waits can outlive any earlier check. Keep the lease
  -- until all potentially blocking writes finish, then recheck held authority.
  PERFORM public.zasp_production_security_agent_run_context_test_binding(o,w,e,run_row.definition_id,run_row.definition_version);
  PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,step_row.step_id);
  IF plan_row.expires_at<=clock_timestamp() OR runtime_expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test authority expired';END IF;
  IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RAISE EXCEPTION USING ERRCODE='PZ001',MESSAGE='existing test budget stopped';END IF;
  UPDATE public.zasp_security_agent_steps SET state='executing',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,step_row.step_id);
  UPDATE public.zasp_security_agent_runs SET state='running',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  response_value:=jsonb_build_object('run_id',r,'state','running','version',run_row.version+1,'step_id',step_row.step_id,'effect_state','pending','outcome_id',outcome_value,'result_digest','sha256:'||encode(result_digest_value,'hex'));
  RETURN response_value;
 EXCEPTION WHEN SQLSTATE 'PZ001' THEN
  -- Roll back reservation, effect, link and enqueue, then persist the stop
  -- outside that subtransaction. Never return a stop alongside hidden work.
  IF NOT public.zasp_security_agent_budget_can_start(o,w,e,r,worker_value,lease_value) THEN RETURN public.zasp_security_agent_budget_stop_result(o,w,e,r,'execute');END IF;
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test budget changed';
 END;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_test_enqueue_core(organization_value text, workspace_value text, environment_value text, actor_value text, idempotency_value text, definition_value text, definition_version_value bigint, run_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row zasp_red_team_definitions%ROWTYPE;intent_value jsonb;digest_value bytea;receipt_row zasp_red_team_request_receipts%ROWTYPE;run_row zasp_red_team_runs%ROWTYPE;payload_value jsonb;result_value jsonb;
BEGIN
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(definition_value) OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(correlation_value) OR definition_version_value NOT BETWEEN 1 AND 1000000 OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team run rejected';END IF;
 intent_value:=jsonb_build_object('definition_id',definition_value,'definition_version',definition_version_value,'run_id',run_value);digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'runTest',idempotency_value),0));
 SELECT * INTO receipt_row FROM zasp_red_team_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'runTest',idempotency_value);IF FOUND THEN IF receipt_row.resource_id<>run_value OR receipt_row.expected_version<>definition_version_value OR receipt_row.intent_digest<>digest_value OR receipt_row.expires_at<=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='red team run replay rejected';END IF;RETURN receipt_row.result||jsonb_build_object('replayed',true);END IF;
 SELECT * INTO STRICT definition_row FROM zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,enabled)=(organization_value,workspace_value,environment_value,definition_value,definition_version_value,true) AND zasp_red_team_safety_authorized(organization_id,workspace_id,environment_id,target_id,target_kind,safety) FOR UPDATE;
 INSERT INTO zasp_red_team_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,requested_by,input_digest) VALUES(organization_value,workspace_value,environment_value,run_value,definition_value,definition_version_value,actor_value,digest_value) RETURNING * INTO run_row;
 payload_value:=jsonb_build_object('organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value,'run_id',run_value,'definition_id',definition_value,'definition_version',definition_version_value,'input_digest',encode(digest_value,'hex'));
 INSERT INTO zasp_red_team_outbox(organization_id,workspace_id,environment_id,outbox_id,deterministic_key,payload,payload_digest) VALUES(organization_value,workspace_value,environment_value,zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'red_team_outbox',run_value),'test-jobs:'||run_value,payload_value,digest(convert_to(payload_value::text,'UTF8'),'sha256'));
 result_value:=zasp_red_team_mutation_result(organization_value,workspace_value,environment_value,actor_value,'runTest',run_value,correlation_value,idempotency_value,zasp_red_team_run_json(run_row));INSERT INTO zasp_red_team_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent_digest,audit_id,correlation_id,receipt_id,result) VALUES(organization_value,workspace_value,environment_value,actor_value,'runTest',idempotency_value,run_value,definition_version_value,digest_value,result_value->>'audit_id',result_value->>'correlation_id',result_value->>'receipt_id',result_value);RETURN result_value;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='red team definition not found';
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_test_link_enqueue(o text, w text, e text, r text, s text, c text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_security_agent_runs%ROWTYPE;step_row public.zasp_security_agent_steps%ROWTYPE;
 prior public.zasp_security_agent_test_links%ROWTYPE;body_value jsonb;binding jsonb;actor_value text;test_run text;result_value jsonb;baseline_value jsonb;baseline_cutoff timestamptz;categories_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(s) AND public.zasp_valid_product_id(c),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test link input rejected';
 END IF;
 SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link intent changed';END IF;
 SELECT * INTO step_row FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR UPDATE;
 IF NOT FOUND OR step_row.action_key NOT IN('run_test','rerun_test') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link intent changed';END IF;
 SELECT * INTO prior FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF FOUND THEN
  IF prior.action_key IS DISTINCT FROM step_row.action_key OR prior.input_digest IS DISTINCT FROM step_row.input_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link replay conflict';END IF;
  RETURN prior.result||jsonb_build_object('replayed',true);
 END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,s);
 PERFORM 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state)=(o,w,e,r,s,step_row.action_key,step_row.input_digest,'pending') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link effect missing';END IF;
 SELECT body INTO body_value FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,run_row.definition_id,run_row.definition_version) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR body_value->'allowed_actions' IS DISTINCT FROM jsonb_build_array(step_row.action_key) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link definition changed';END IF;
 SELECT actor_id INTO actor_value FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,run_row.definition_id,run_row.definition_version) FOR SHARE;
 IF NOT FOUND OR NOT COALESCE(public.zasp_valid_product_id(actor_value),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link actor unavailable';END IF;
 test_run:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_run',r||chr(31)||s||chr(31)||step_row.action_key);
 -- Match the shared human/API core's advisory-before-test-definition order.
 -- Take all such blocking locks before the resolver's wall-clock checks.
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),o,w,e,actor_value,'runTest','agent-step:'||test_run),0));
 -- Enqueue's existing core takes a write lock on the definition. Take that
 -- lock before the resolver's SHARE lock, avoiding concurrent lock upgrades.
 PERFORM 1 FROM public.zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,body_value->'existing_test'->>'definition_id') FOR UPDATE;
 binding:=public.zasp_production_security_agent_run_context_test_binding(o,w,e,run_row.definition_id,run_row.definition_version);
 SELECT categories INTO STRICT categories_value FROM public.zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,binding->>'definition_id',(binding->>'definition_version')::bigint);
 -- queued_at defaults to transaction start and can predate lock waits. Use
 -- the wall-clock pre-enqueue boundary and snapshot before creating new work.
 baseline_cutoff:=clock_timestamp();
 -- Snapshot committed completion receipts visible at enqueue. Do not lock old
 -- runs here: completion locks run before definition, and we own definition.
 -- This is a candidate, not remediation proof. Settlement must retrieve both
 -- immutable objects and validate their full comparison/evaluation identities.
 -- A legacy candidate lacking comparison data must not be replaced by an older
 -- comparable result merely to manufacture a fail-to-pass claim.
 SELECT jsonb_build_object('schema_version','security-agent-test-baseline-v1',
  'run_id',a.run_id,'attempt',a.attempt,'input_digest',encode(a.input_digest,'hex'),
  'completed_at',to_char(a.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'input_artifact',a.input_artifact,
  'output_artifact',jsonb_build_object('reference',a.evidence_reference,'key',a.evidence_key,
   'version_id',a.evidence_version_id,'sha256',encode(a.evidence_checksum,'hex'),'size_bytes',a.evidence_size))
 INTO baseline_value
 FROM public.zasp_red_team_runs b
 JOIN public.zasp_red_team_attempts a ON (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.attempt)=(b.organization_id,b.workspace_id,b.environment_id,b.run_id,b.attempt)
 WHERE (b.organization_id,b.workspace_id,b.environment_id,b.definition_id,b.definition_version,b.state,b.verdict)=
  (o,w,e,binding->>'definition_id',(binding->>'definition_version')::bigint,'complete','fail')
 AND b.run_id<>test_run AND b.completed_at<baseline_cutoff AND a.completed_at=b.completed_at
 AND b.error_code IS NULL AND a.error_code IS NULL
 AND (a.input_digest,a.verdict,a.evidence_reference,a.evidence_key,a.evidence_version_id,a.evidence_checksum,a.evidence_size)=
  (b.input_digest,b.verdict,b.evidence_reference,b.evidence_key,b.evidence_version_id,b.evidence_checksum,b.evidence_size)
 AND public.zasp_red_team_valid_input_artifact(o,w,e,a.input_artifact)
 AND a.evidence_checksum<>decode(repeat('00',32),'hex')
 AND public.zasp_discovery_s3_object_reference(a.evidence_reference)
 AND a.evidence_key='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||b.run_id
 AND substring(a.evidence_reference FROM '^s3://[^/]+/(.+)$')=a.evidence_key
 AND a.input_artifact->>'reference'<>a.evidence_reference
 AND length(a.evidence_version_id) BETWEEN 1 AND 512 AND a.evidence_version_id!~'[[:space:][:cntrl:]]'
 ORDER BY b.completed_at DESC,b.run_id DESC,a.attempt DESC LIMIT 1;
 result_value:=public.zasp_security_agent_test_enqueue_core(o,w,e,actor_value,'agent-step:'||test_run,binding->>'definition_id',(binding->>'definition_version')::bigint,test_run,c);
 -- Only an existing agent link can authorize replay. A colliding human/API
 -- receipt must not be adopted as new Security Agent provenance.
 IF result_value->'replayed' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test link enqueue conflict';END IF;
 -- A uniqueness/FK wait inside enqueue is also time spent. Recheck while the
 -- prerequisite rows remain locked; failure rolls back run/outbox/receipt too.
 PERFORM public.zasp_production_security_agent_run_context_test_binding(o,w,e,run_row.definition_id,run_row.definition_version);
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,s);
 result_value:=jsonb_build_object('test_run_id',test_run,'definition_id',binding->>'definition_id','definition_version',(binding->>'definition_version')::bigint,'state','pending','replayed',false);
 INSERT INTO public.zasp_security_agent_test_links(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,test_definition_id,test_definition_version,test_run_id,target_id,target_kind,test_categories,baseline,result)
 VALUES(o,w,e,r,s,step_row.action_key,step_row.input_digest,binding->>'definition_id',(binding->>'definition_version')::bigint,test_run,binding->>'target_id',binding->>'target_kind',categories_value,baseline_value,result_value);
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_step(o,w,e,r,s);
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_settle_security_agent_webhook_parent(o text, w text, e text, id_value text, token_value text, generation_value bigint, worker_value text, audit_value text, correlation_value text, outcome_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d public.zasp_security_agent_webhook_deliveries%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;run_state text;step_state text;reason_value text;result_value jsonb;preserve_parent boolean:=false;
BEGIN
 IF NOT public.zasp_sa_export_principal_ready('zasp_security_agent_worker') OR NOT public.zasp_sa_webhook_guard() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='webhook settlement authority unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value) AND public.zasp_valid_product_id(outcome_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='webhook settlement identity rejected';END IF;
 SELECT * INTO d FROM public.zasp_security_agent_webhook_deliveries WHERE (organization_id,workspace_id,environment_id,delivery_id,settlement_worker,settlement_token,settlement_generation)=(o,w,e,id_value,worker_value,token_value,generation_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='webhook settlement fence rejected';END IF;
 IF d.settlement_state='settled' THEN RETURN d.settlement_result;END IF;
 IF d.settlement_state<>'leased' OR d.settlement_expires_at<=clock_timestamp() OR d.state NOT IN('acknowledged','failed','uncertain','cancelled') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='webhook settlement expired';END IF;
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,d.run_id) FOR UPDATE;
 SELECT * INTO STRICT st FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,d.run_id,d.step_id) FOR UPDATE;
 IF rr.state='cancelled' THEN run_state:='cancelled';step_state:='cancelled';reason_value:='webhook_parent_cancelled';
 ELSIF d.state='cancelled' AND rr.state IN('contained','remediated','failed','inconclusive','needs_human','simulated') AND rr.version=d.settlement_parent_version AND rr.plan_hash=d.plan_hash THEN
  run_state:=rr.state;step_state:=st.state;reason_value:='webhook_parent_outcome_preserved';preserve_parent:=true;
 ELSIF rr.state IN('contained','remediated','failed','inconclusive','needs_human','simulated') OR st.state IN('succeeded','failed','inconclusive','cancelled') OR rr.version<>d.settlement_parent_version OR rr.plan_hash IS DISTINCT FROM d.plan_hash THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='webhook parent settlement changed';
 ELSE run_state:=CASE d.state WHEN 'acknowledged' THEN 'needs_human' WHEN 'uncertain' THEN 'needs_human' WHEN 'cancelled' THEN 'cancelled' ELSE 'failed' END;step_state:=CASE d.state WHEN 'acknowledged' THEN 'succeeded' WHEN 'uncertain' THEN 'inconclusive' WHEN 'cancelled' THEN 'cancelled' ELSE 'failed' END;reason_value:=CASE d.state WHEN 'acknowledged' THEN 'webhook_handoff_acknowledged' WHEN 'uncertain' THEN 'webhook_delivery_uncertain' WHEN 'cancelled' THEN 'webhook_delivery_cancelled' ELSE 'webhook_delivery_failed' END;
 END IF;
 IF NOT preserve_parent AND st.state NOT IN('succeeded','failed','inconclusive','cancelled') THEN UPDATE public.zasp_security_agent_steps SET state=step_state,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,d.run_id,d.step_id);END IF;
 IF NOT preserve_parent AND rr.state<>'cancelled' THEN UPDATE public.zasp_security_agent_runs SET state=run_state,last_error_code=reason_value,completed_at=clock_timestamp(),version=version+1,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,d.run_id);END IF;
 result_value:=jsonb_build_object('delivery_id',d.delivery_id,'run_id',d.run_id,'step_id',d.step_id,'state',run_state,'delivery_state',d.state,'outcome_id',outcome_value,'reason',reason_value);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,correlation_value,d.run_id,d.step_id,worker_value,'webhook_parent_settled',digest(convert_to(result_value::text,'UTF8'),'sha256'),result_value);
 UPDATE public.zasp_security_agent_webhook_deliveries SET settlement_state='settled',settlement_result=result_value WHERE (organization_id,workspace_id,environment_id,delivery_id)=(o,w,e,d.delivery_id);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_workflow_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    mutation_response jsonb;
    existing_receipt_id text;
BEGIN
    LOCK TABLE "public"."zasp_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."zasp_schema_versions" AS release
          JOIN "public"."zasp_schema_metadata" AS schema_marker
            ON schema_marker."key" = 'production_core_schema'
           AND schema_marker."value" = 'production-recovery-v1'
         WHERE release."version" = 27
           AND release."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."zasp_schema_versions" AS later_release
                WHERE later_release."version" > 60
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance release unavailable';
    END IF;
    IF requested_receipt_id IS NOT NULL AND requested_receipt_id <> '' AND length(requested_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_response := "public"."zasp_workflow_mutate_v3"(
        mutation, requested_kind, requested_id,
        requested_organization_id, requested_workspace_id, requested_environment_id,
        requested_principal_id, requested_operation, requested_idempotency_key,
        expected_version, requested_intent, requested_body, requested_audit_id, requested_correlation_id
    );
    existing_receipt_id := mutation_response ->> 'receipt_id';
    IF existing_receipt_id IS NOT NULL THEN
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    IF requested_receipt_id IS NULL OR requested_receipt_id = '' THEN
        UPDATE "public"."zasp_workflow_idempotency"
           SET "receipt_semantics" = 'receiptless_incompatible'
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key
           AND NULLIF("response" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    INSERT INTO "public"."zasp_workflow_receipts" (
        "organization_id", "workspace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "result", "resource_kind", "resource_id",
        "resource_version", "audit_id", "correlation_id"
    ) VALUES (
        requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_receipt_id,
        requested_operation, requested_idempotency_key, requested_intent, mutation_response -> 'body', requested_kind, requested_id,
        (mutation_response ->> 'version')::bigint, mutation_response ->> 'audit_id', mutation_response ->> 'correlation_id'
    );
    mutation_response := mutation_response || jsonb_build_object('receipt_id', requested_receipt_id);
    UPDATE "public"."zasp_workflow_idempotency"
       SET "response" = mutation_response - 'replayed',
           "receipt_semantics" = 'receipt_backed'
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_workflow_mutate_v3(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_body jsonb;
    result_version bigint;
    result_secret_generation bigint;
BEGIN
IF requested_kind='security_agent' THEN PERFORM public.zasp_sa_export_legacy_definition_fence(requested_organization_id,requested_workspace_id,requested_environment_id,requested_id,requested_body);END IF;
    IF mutation NOT IN ('create', 'update', 'delete', 'rotate_secret') OR
       requested_kind NOT IN ('policy', 'integration', 'sensor', 'security_agent', 'security_agent_run', 'security_agent_approval') OR
       length(requested_id) < 1 OR length(requested_id) > 128 OR
       length(requested_idempotency_key) < 16 OR length(requested_idempotency_key) > 128 OR
       jsonb_typeof(requested_intent) <> 'object' OR jsonb_typeof(requested_body) <> 'object' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow mutation';
    END IF;

	PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31), requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_operation, requested_idempotency_key), 0));
    digest_value := digest(convert_to(requested_intent::text, 'UTF8'), 'sha256');
    SELECT "request_digest", "response" INTO prior_digest, prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest <> digest_value THEN RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'idempotency conflict'; END IF;
        RETURN prior_response || jsonb_build_object('replayed', true);
    END IF;

    IF mutation = 'create' THEN
        IF requested_kind = 'policy' AND (requested_operation <> 'createPolicy' OR requested_body ->> 'rollout' <> 'draft') THEN
            RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'policy must be created as draft';
        END IF;
        INSERT INTO "public"."zasp_workflow_records" ("organization_id", "workspace_id", "environment_id", "kind", "id", "body")
        VALUES (requested_organization_id, requested_workspace_id, requested_environment_id, requested_kind, requested_id, requested_body)
        RETURNING "body", "version", "secret_generation" INTO result_body, result_version, result_secret_generation;
    ELSIF mutation = 'update' THEN
        UPDATE "public"."zasp_workflow_records" AS record
           SET "body" = CASE WHEN requested_kind = 'policy' THEN requested_body - '_target_environment_id' ELSE requested_body END,
               "version" = record."version" + 1,
               "updated_at" = transaction_timestamp()
         WHERE record."organization_id" = requested_organization_id AND record."workspace_id" = requested_workspace_id AND record."environment_id" = requested_environment_id
           AND record."kind" = requested_kind AND record."id" = requested_id AND record."deleted_at" IS NULL AND record."version" = expected_version
           AND (requested_kind <> 'policy' OR
                requested_operation = 'updatePolicy' AND requested_body ->> 'rollout' = record."body" ->> 'rollout' OR
                requested_operation = 'rolloutPolicy' AND requested_body ->> '_target_environment_id' = requested_environment_id AND
                    ((record."body" ->> 'rollout' = 'draft' AND requested_body ->> 'rollout' = 'monitor') OR
                     (record."body" ->> 'rollout' = 'monitor' AND requested_body ->> 'rollout' = 'enforced')) OR
                requested_operation = 'disablePolicy' AND requested_body ->> '_target_environment_id' = requested_environment_id AND
                    record."body" ->> 'rollout' IN ('monitor', 'enforced') AND requested_body ->> 'rollout' = 'disabled')
        RETURNING record."body", record."version", record."secret_generation" INTO result_body, result_version, result_secret_generation;
    ELSIF mutation = 'delete' THEN
        UPDATE "public"."zasp_workflow_records" SET "deleted_at" = transaction_timestamp(), "version" = "version" + 1, "updated_at" = transaction_timestamp()
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id AND "environment_id" = requested_environment_id
           AND "kind" = requested_kind AND "id" = requested_id AND "deleted_at" IS NULL AND "version" = expected_version
        RETURNING "body", "version", "secret_generation" INTO result_body, result_version, result_secret_generation;
    ELSIF mutation = 'rotate_secret' THEN
        UPDATE "public"."zasp_workflow_records" SET "secret_generation" = "secret_generation" + 1, "version" = "version" + 1, "updated_at" = transaction_timestamp()
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id AND "environment_id" = requested_environment_id
           AND "kind" = requested_kind AND "id" = requested_id AND "deleted_at" IS NULL AND "version" = expected_version
        RETURNING "body", "version", "secret_generation" INTO result_body, result_version, result_secret_generation;
    END IF;

    IF result_body IS NULL THEN
        IF EXISTS (SELECT 1 FROM "public"."zasp_workflow_records" WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id AND "environment_id" = requested_environment_id AND "kind" = requested_kind AND "id" = requested_id AND "deleted_at" IS NULL) THEN
            RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'workflow version conflict';
        END IF;
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'workflow record missing';
    END IF;

    prior_response := jsonb_build_object('body', result_body, 'version', result_version, 'secret_generation', result_secret_generation, 'audit_id', requested_audit_id, 'correlation_id', requested_correlation_id, 'replayed', false);
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id", "workspace_id", "environment_id", "audit_id", "correlation_id", "principal_id", "operation", "resource_kind", "resource_id", "resource_version")
    VALUES (requested_organization_id, requested_workspace_id, requested_environment_id, requested_audit_id, requested_correlation_id, requested_principal_id, requested_operation, requested_kind, requested_id, result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id", "workspace_id", "environment_id", "principal_id", "operation", "idempotency_key", "request_digest", "response")
    VALUES (requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_operation, requested_idempotency_key, digest_value, prior_response);
    RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_workflow_receipt_acknowledge(requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
BEGIN
    UPDATE "public"."zasp_workflow_receipts"
       SET "acknowledged_at" = COALESCE("acknowledged_at", transaction_timestamp())
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "receipt_id" = requested_receipt_id AND "expires_at" > transaction_timestamp();
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'workflow receipt missing';
    END IF;
    RETURN jsonb_build_object('acknowledged', true);
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_workflow_receipt_cleanup(requested_limit integer DEFAULT 1000)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    deleted_count integer;
BEGIN
    IF requested_limit < 1 OR requested_limit > 1000 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt cleanup';
    END IF;
    WITH expired AS (
        SELECT ctid FROM "public"."zasp_workflow_receipts"
         WHERE "expires_at" <= transaction_timestamp()
         ORDER BY "expires_at", "receipt_id"
         LIMIT requested_limit
         FOR UPDATE SKIP LOCKED
    ), deleted AS (
        DELETE FROM "public"."zasp_workflow_receipts" AS receipt
         USING expired
         WHERE receipt.ctid = expired.ctid
         RETURNING 1
    )
    SELECT count(*)::integer INTO deleted_count FROM deleted;
    RETURN jsonb_build_object('deleted', deleted_count);
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_workflow_receipt_list(requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_limit integer DEFAULT 20)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    response jsonb;
BEGIN
    IF requested_limit < 1 OR requested_limit > 50 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt list';
    END IF;
    SELECT jsonb_build_object('items', COALESCE(jsonb_agg(jsonb_build_object(
        'id', "receipt_id", 'operation', "operation", 'idempotency_key', "idempotency_key",
        'intent', "intent", 'result', "result", 'resource_kind', "resource_kind", 'resource_id', "resource_id",
        'resource_version', "resource_version", 'audit_id', "audit_id", 'correlation_id', "correlation_id",
        'created_at', "created_at", 'expires_at', "expires_at"
    ) ORDER BY "created_at", "receipt_id"), '[]'::jsonb)) INTO response
      FROM (
        SELECT * FROM "public"."zasp_workflow_receipts"
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "acknowledged_at" IS NULL AND "expires_at" > transaction_timestamp()
         ORDER BY "created_at", "receipt_id" LIMIT requested_limit
      ) AS visible;
    RETURN response;
END;
$function$

CREATE OR REPLACE FUNCTION public.zasp_workflow_replay(requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, requested_intent jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
BEGIN
    IF length(requested_operation) < 1 OR length(requested_operation) > 128 OR
       length(requested_idempotency_key) < 16 OR length(requested_idempotency_key) > 128 OR
       jsonb_typeof(requested_intent) <> 'object' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow replay';
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31), requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_operation, requested_idempotency_key), 0));
    digest_value := digest(convert_to(requested_intent::text, 'UTF8'), 'sha256');
    SELECT "request_digest", "response" INTO prior_digest, prior_response
      FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RETURN jsonb_build_object('found', false);
    END IF;
IF requested_operation IN('createSecurityAgent','updateSecurityAgent','deleteSecurityAgent') AND (COALESCE(prior_response->'body'->'allowed_actions' ? 'create_evidence_export',false) OR COALESCE(requested_intent->'body'->'allowed_actions' ? 'create_evidence_export',false) OR EXISTS(SELECT 1 FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(requested_organization_id,requested_workspace_id,requested_environment_id,requested_intent->>'resource_id') AND body->'allowed_actions' ? 'create_evidence_export')) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='export definition replay requires versioned authority';END IF;
    IF prior_digest <> digest_value THEN
        RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'idempotency conflict';
    END IF;
    RETURN jsonb_build_object('found', true, 'result', prior_response || jsonb_build_object('replayed', true));
END;
$function$

CREATE OR REPLACE FUNCTION zasp_audit_exports_predecessor.zasp_risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">51)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_audit_exports_predecessor.zasp_workflow_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    mutation_response jsonb;
    existing_receipt_id text;
BEGIN
    LOCK TABLE "public"."zasp_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."zasp_schema_versions" AS release
          JOIN "public"."zasp_schema_metadata" AS schema_marker
            ON schema_marker."key" = 'production_core_schema'
           AND schema_marker."value" = 'production-recovery-v1'
         WHERE release."version" = 27
           AND release."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."zasp_schema_versions" AS later_release
                WHERE later_release."version" > 51
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance release unavailable';
    END IF;
    IF requested_receipt_id IS NOT NULL AND requested_receipt_id <> '' AND length(requested_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_response := "public"."zasp_workflow_mutate_v3"(
        mutation, requested_kind, requested_id,
        requested_organization_id, requested_workspace_id, requested_environment_id,
        requested_principal_id, requested_operation, requested_idempotency_key,
        expected_version, requested_intent, requested_body, requested_audit_id, requested_correlation_id
    );
    existing_receipt_id := mutation_response ->> 'receipt_id';
    IF existing_receipt_id IS NOT NULL THEN
        RETURN mutation_response;
    END IF;
    IF requested_receipt_id IS NULL OR requested_receipt_id = '' THEN
        UPDATE "public"."zasp_workflow_idempotency"
           SET "receipt_semantics" = 'receiptless_incompatible'
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key
           AND NULLIF("response" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        RETURN mutation_response;
    END IF;
    INSERT INTO "public"."zasp_workflow_receipts" (
        "organization_id", "workspace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "result", "resource_kind", "resource_id",
        "resource_version", "audit_id", "correlation_id"
    ) VALUES (
        requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_receipt_id,
        requested_operation, requested_idempotency_key, requested_intent, mutation_response -> 'body', requested_kind, requested_id,
        (mutation_response ->> 'version')::bigint, mutation_response ->> 'audit_id', mutation_response ->> 'correlation_id'
    );
    mutation_response := mutation_response || jsonb_build_object('receipt_id', requested_receipt_id);
    UPDATE "public"."zasp_workflow_idempotency"
       SET "response" = mutation_response - 'replayed',
           "receipt_semantics" = 'receipt_backed'
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    RETURN mutation_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_authorization79.ack(o text, d bigint, g bigint, s text, m text, tuples_value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF NOT zasp_authorization79.worker() OR NOT zasp_authorization79.locked(o) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='projection acknowledgement rejected';END IF;
 PERFORM zasp_authorization79.revalidate_pending(o,d,g,s,m);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization79.stages WHERE(organization_id,revision,generation,store_id,model_id,tuples)=(o,d,g,s,m,tuples_value)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='projection stage mismatch';END IF;
 DELETE FROM zasp_authorization79.inventory WHERE organization_id=o AND store_id=s;
 INSERT INTO zasp_authorization79.inventory SELECT o,s,v FROM jsonb_array_elements(tuples_value) v;
 UPDATE zasp_authorization79.outbox SET applied_at=clock_timestamp() WHERE organization_id=o AND revision<=d AND applied_at IS NULL;
 INSERT INTO zasp_authorization79.receipts(organization_id,revision,generation,store_id,model_id,tuple_count) VALUES(o,d,g,s,m,jsonb_array_length(tuples_value));
 UPDATE zasp_authorization79.organizations SET applied=d,applied_at=clock_timestamp(),blocked_reason='' WHERE organization_id=o;
 DELETE FROM zasp_authorization79.stages WHERE organization_id=o;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization79.capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior text;next_org text;org text;old_value jsonb;new_value jsonb;columns text[];
BEGIN
 old_value:=CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END;new_value:=CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END;
 -- Ignore unrelated payload/status updates. Every permission-affecting column
 -- is listed in the trigger installation below, including raw SQL write paths.
 columns:=string_to_array(TG_ARGV[1],',');

 IF TG_RELID='public.zasp_discovery_syncs'::regclass AND TG_OP='UPDATE' AND old_value->>'state' IN('queued','running') AND new_value->>'state' IN('queued','running')
 AND NOT EXISTS(SELECT 1 FROM unnest(columns) k WHERE k<>'state' AND old_value->k IS DISTINCT FROM new_value->k)
 AND EXISTS(SELECT 1 FROM zasp_authorization80_worker.discovery_associations a JOIN zasp_temporal72.runs r ON(r.organization_id,r.workspace_id,r.environment_id,r.job_id,r.sync_id,r.integration_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id,a.sync_id,a.integration_id)
 JOIN zasp_authorization80_worker.discovery_state s ON(s.organization_id,s.workspace_id,s.environment_id,s.job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id)
 WHERE(a.organization_id,a.workspace_id,a.environment_id,a.sync_id,a.integration_id,a.source_kind)=(new_value->>'organization_id',new_value->>'workspace_id',new_value->>'environment_id',new_value->>'id',new_value->>'integration_id',new_value->>'trigger_kind')
 AND new_value->>'principal_id'=CASE a.source_kind WHEN 'manual' THEN a.grantor_id ELSE a.principal_id END AND a.admission=zasp_authorization80_worker.discovery72_admission_identity(r) AND s.present AND s.state=r.state AND s.state IN('admitted','collecting','partial','retryable','complete','applying')) THEN RETURN NEW;END IF;

 IF TG_OP='UPDATE' AND (SELECT jsonb_object_agg(k,old_value->k) FROM unnest(columns) k) IS NOT DISTINCT FROM (SELECT jsonb_object_agg(k,new_value->k) FROM unnest(columns) k) THEN RETURN NEW;END IF;
 prior:=old_value->>TG_ARGV[0];next_org:=new_value->>TG_ARGV[0];
 FOR org IN SELECT DISTINCT x FROM unnest(ARRAY[prior,next_org]) x WHERE x IS NOT NULL ORDER BY x LOOP PERFORM zasp_authorization79.touch(org);END LOOP;
 -- Row triggers do not precede PostgreSQL tuple locks. A lock inversion must
 -- abort the whole caller transaction; callers restart at a fresh Check.
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization79.configure(o text, s text, m text, repair boolean DEFAULT false)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE row_value zasp_authorization79.organizations%ROWTYPE;
BEGIN
 IF NOT zasp_authorization79.operator() OR NOT zasp_authorization79.ready('8b358e304b2eedaed7a4148f317f6d21d9c624ccc39105ca6199265ae661a987') OR s!~'^[0-7][0-9A-HJKMNP-TV-Z]{25}$' OR m!~'^[0-7][0-9A-HJKMNP-TV-Z]{25}$' OR NOT EXISTS(SELECT 1 FROM public.zasp_organizations WHERE id=o) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='projection configuration rejected';END IF;
 -- Configuration takes the same session advisory serialization as reconcile,
 -- so no old-store operation is still running when a generation changes.
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-auth79/'||o,0));
 SELECT * INTO row_value FROM zasp_authorization79.organizations WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND OR (row_value.store_id,row_value.model_id) IS DISTINCT FROM(s,m) OR repair THEN
  PERFORM zasp_authorization79.touch(o);
  UPDATE zasp_authorization79.organizations SET generation=generation+1,store_id=s,model_id=m,blocked_reason='pending' WHERE organization_id=o;
 END IF;
 RETURN (SELECT to_jsonb(x) FROM zasp_authorization79.organizations x WHERE organization_id=o);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization79.revalidate(o text, d bigint, g bigint, s text, m text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE v zasp_authorization79.organizations%ROWTYPE;
BEGIN
 IF NOT zasp_authorization79.reader() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='projection fence rejected';END IF;
 SELECT * INTO v FROM zasp_authorization79.organizations WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND OR (v.desired,v.applied,v.generation,v.store_id,v.model_id) IS DISTINCT FROM(d,d,g,s,m) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='authorization changed; retry from Check';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization79.snapshot(o text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT zasp_authorization79.worker() OR NOT zasp_authorization79.locked(o) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='projection session rejected';END IF;
 PERFORM zasp_authorization80_worker.expire_test_targets(o);
 PERFORM zasp_authorization80_worker.expire_discovery72(o);
 PERFORM zasp_authorization80_worker.expire_ordered_targets(o);
 PERFORM zasp_authorization80_worker.expire_ordered_effects(o);
 PERFORM zasp_authorization80_worker.expire_ordered_policies(o);
 IF EXISTS(SELECT 1 FROM public.zasp_environments WHERE organization_id=o GROUP BY id HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM zasp_authorization79.resources WHERE organization_id=o GROUP BY kind,id HAVING count(*)>1)
 OR EXISTS(SELECT 1 FROM zasp_authorization79.resources r WHERE r.organization_id=o AND NOT EXISTS(SELECT 1 FROM public.zasp_environments e WHERE(e.organization_id,e.workspace_id,e.id)=(r.organization_id,r.workspace_id,r.environment_id))) THEN RAISE EXCEPTION USING ERRCODE='23514',MESSAGE='authorization source ancestry rejected';END IF;
 -- One SQL statement snapshot binds source facts and desired revision. Missing
 -- parents or duplicate scoped IDs fail closed rather than manufacturing edges.
 WITH scopes AS(SELECT e.organization_id,e.workspace_id,e.id environment_id FROM public.zasp_environments e JOIN public.zasp_workspaces w ON(w.organization_id,w.id)=(e.organization_id,e.workspace_id) JOIN public.zasp_organizations x ON x.id=e.organization_id WHERE e.organization_id=o),
 roles AS(SELECT a.organization_id,a.workspace_id,a.environment_id,a.principal_id,m.role FROM public.zasp_authorized_scopes a JOIN public.zasp_identity_memberships m USING(organization_id,principal_id) WHERE a.organization_id=o AND m.active UNION SELECT g.organization_id,g.workspace_id,g.environment_id,v.principal_id,g.role FROM public.zasp_group_mappings g JOIN public.zasp_identity_member_groups v USING(organization_id,group_reference) JOIN public.zasp_identity_memberships m USING(organization_id,principal_id) WHERE g.organization_id=o AND m.active)
 SELECT jsonb_build_object('revision',(SELECT to_jsonb(x) FROM zasp_authorization79.organizations x WHERE organization_id=o),
 'scopes',COALESCE((SELECT jsonb_agg(to_jsonb(x)) FROM scopes x),'[]'),
 'members',COALESCE((SELECT jsonb_agg(to_jsonb(x)-'organization_id') FROM zasp_authorization79.members x WHERE organization_id=o),'[]'),
 'roles',COALESCE((SELECT jsonb_agg(to_jsonb(x)) FROM roles x),'[]'),
 'resources',COALESCE((SELECT jsonb_agg(to_jsonb(x)) FROM zasp_authorization79.resources x WHERE organization_id=o),'[]'),
 'grants',COALESCE((SELECT jsonb_agg(to_jsonb(x)) FROM zasp_authorization79.current_grants x WHERE organization_id=o),'[]'),
 'known',COALESCE((SELECT jsonb_agg(i.tuple) FROM zasp_authorization79.inventory i JOIN zasp_authorization79.organizations x USING(organization_id,store_id) WHERE i.organization_id=o),'[]')) INTO result;
 UPDATE zasp_authorization79.organizations SET last_attempt_at=clock_timestamp() WHERE organization_id=o;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization79.stage(o text, d bigint, g bigint, s text, m text, tuples_value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF NOT zasp_authorization79.worker() OR NOT zasp_authorization79.locked(o) OR jsonb_typeof(tuples_value)<>'array' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='projection stage rejected';END IF;
 PERFORM zasp_authorization79.revalidate_pending(o,d,g,s,m);
 INSERT INTO zasp_authorization79.inventory SELECT o,s,v FROM jsonb_array_elements(tuples_value) v ON CONFLICT DO NOTHING;
 INSERT INTO zasp_authorization79.stages VALUES(o,d,g,s,m,tuples_value) ON CONFLICT(organization_id) DO UPDATE SET revision=d,generation=g,store_id=s,model_id=m,tuples=tuples_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.audit_page(org_value text, workspace_value text, environment_value text, principal_value text, session_value bytea, csrf_value text, filters_value jsonb, after_time_value timestamp with time zone, after_id_value text, limit_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE started timestamptz:=clock_timestamp();entry record;filter record;from_value timestamptz;to_value timestamptz;parsed timestamptz;item jsonb;item_text text;estimated bigint;budget bigint:=2050;retained integer:=0;seen integer:=0;stopped boolean:=false;items jsonb:='[]';result jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(org_value) AND public.zasp_valid_product_id(workspace_value) AND public.zasp_valid_product_id(environment_value) AND public.zasp_valid_product_id(principal_value),false)
 OR session_value IS NULL OR octet_length(session_value)<>32 OR session_value=decode(repeat('00',32),'hex') OR csrf_value IS NULL
 OR limit_value IS NULL OR limit_value NOT BETWEEN 1 AND 100
 OR jsonb_typeof(filters_value) IS DISTINCT FROM 'object' OR octet_length(filters_value::text)>1024
 OR (after_time_value IS NULL)<>(after_id_value IS NULL)
 OR (after_id_value IS NOT NULL AND (NOT public.zasp_valid_product_id(after_id_value) OR NOT isfinite(after_time_value) OR extract(year FROM after_time_value AT TIME ZONE 'UTC') NOT BETWEEN 1 AND 9999))
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public audit query rejected';END IF;
 FOR filter IN SELECT key,value FROM jsonb_each(filters_value) LOOP
  IF filter.key NOT IN('actor_id','action','outcome','from','to') OR jsonb_typeof(filter.value)<>'string' OR filter.value#>>'{}'='' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public audit query rejected';END IF;
  IF filter.key='actor_id' AND NOT public.zasp_valid_product_id(filter.value#>>'{}') OR filter.key='action' AND NOT public.zasp_audit_export_public_action(filter.value#>>'{}') OR filter.key='outcome' AND filter.value#>>'{}' NOT IN('succeeded','denied','failed') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public audit query rejected';END IF;
  IF filter.key IN('from','to') THEN
   BEGIN
    IF filter.value#>>'{}' !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$' THEN RAISE EXCEPTION USING ERRCODE='22023';END IF;
    parsed:=(filter.value#>>'{}')::timestamptz;
    IF NOT isfinite(parsed) OR to_char(parsed AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>filter.value#>>'{}' THEN RAISE EXCEPTION USING ERRCODE='22023';END IF;
   EXCEPTION WHEN data_exception THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public audit query rejected';END;
   IF filter.key='from' THEN from_value:=parsed;ELSE to_value:=parsed;END IF;
  END IF;
 END LOOP;
 IF from_value>=to_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public audit query rejected';END IF;
 IF NOT COALESCE(zasp_authorization80.source_ready(52,expected_checksum,expected_fingerprint),false) OR NOT COALESCE(public.zasp_discovery_principal_ready('zasp_discovery_api'),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public audit authority unavailable';END IF;
 PERFORM zasp_authorization80.checked_browser(org_value,workspace_value,environment_value,principal_value,session_value,csrf_value,false); PERFORM zasp_authorization80.require_read(org_value,workspace_value,environment_value,ARRAY['listAuditEvents'],'view_audit',true,principal_value);
 -- The materialized stage contains identities only. Collision probes ignore
 -- every caller filter and keyset, and the bounded fetch shares this snapshot.
 FOR entry IN
  WITH candidates AS MATERIALIZED (
   SELECT s.id,s.occurred_at,s.source_kind FROM public.zasp_audit_export_public_source_v1 s
   WHERE s.organization_id=org_value AND zasp_authorization80.parent_allowed(s.organization_id,s.workspace_id,s.environment_id,'audit_event',s.id,s.source_kind)
   AND (NOT filters_value ? 'actor_id' OR s.actor_id=filters_value->>'actor_id')
   AND (NOT filters_value ? 'action' OR s.action=filters_value->>'action')
   AND (NOT filters_value ? 'outcome' OR CASE s.outcome WHEN 'rejected' THEN 'denied' ELSE s.outcome END=filters_value->>'outcome')
   AND (from_value IS NULL OR s.occurred_at>=from_value) AND (to_value IS NULL OR s.occurred_at<to_value)
   AND (after_time_value IS NULL OR (s.occurred_at,s.id COLLATE "C")<(after_time_value,after_id_value COLLATE "C"))
   ORDER BY s.occurred_at DESC,s.id COLLATE "C" DESC LIMIT limit_value+1
  )
  SELECT fetched.source,(SELECT count(*) FROM public.zasp_audit_export_public_source_v1 collision WHERE collision.organization_id=org_value AND collision.id=c.id) AS identity_count
  FROM candidates c CROSS JOIN LATERAL (
   SELECT s AS source FROM public.zasp_audit_export_public_source_v1 s
   WHERE s.organization_id=org_value AND s.id=c.id AND s.source_kind=c.source_kind
   -- Retain the correlated fetch boundary: flattening this into a hash join
   -- constructs unselected whole-source composites before the identity match.
   OFFSET 0
  ) fetched
  ORDER BY c.occurred_at DESC,c.id COLLATE "C" DESC
 LOOP
  item:=public.zasp_audit_export_public_item(entry.source,entry.identity_count);
  seen:=seen+1;
  IF NOT stopped AND retained<limit_value THEN
   item_text:=item::text;
   estimated:=octet_length(item_text)::bigint+5::bigint*(char_length(item_text)-char_length(translate(item_text,'<>&','')))+3::bigint*(char_length(item_text)-char_length(translate(item_text,U&'\2028\2029','')));
   IF retained=0 OR budget+estimated+1<=786432 THEN items:=items||jsonb_build_array(item);retained:=retained+1;budget:=budget+estimated+1;ELSE stopped:=true;END IF;
  END IF;
  IF clock_timestamp()>started+interval '5 seconds' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public audit page deadline exceeded';END IF;
 END LOOP;
 result:=jsonb_build_object('items',items,'has_more',seen>retained);
 IF octet_length(result::text)>1052672 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public audit page unavailable';END IF;
 IF NOT COALESCE(zasp_authorization80.source_ready(52,expected_checksum,expected_fingerprint),false) OR NOT COALESCE(public.zasp_discovery_principal_ready('zasp_discovery_api'),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public audit authority unavailable';END IF;
 PERFORM zasp_authorization80.checked_browser(org_value,workspace_value,environment_value,principal_value,session_value,csrf_value,false); PERFORM zasp_authorization80.require_read(org_value,workspace_value,environment_value,ARRAY['listAuditEvents'],'view_audit',true,principal_value);
 IF clock_timestamp()>started+interval '5 seconds' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public audit page deadline exceeded';END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.checked_browser(o text, w text, e text, p text, d bytea, csrf text DEFAULT NULL::text, fresh boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proof jsonb;
BEGIN
 proof:=zasp_authorization80.context();
 IF csrf IS NOT NULL AND encode(public.digest(csrf,'sha256'),'hex') IS DISTINCT FROM proof->>'csrf_digest' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current browser CSRF binding required';END IF;
 IF proof IS NULL OR(proof->>'organization_id',proof->>'workspace_id',proof->>'environment_id',proof->>'principal_id',proof->>'credential_digest',proof->>'credential_kind') IS DISTINCT FROM(o,w,e,p,encode(d,'hex'),'1') OR(fresh AND NOT COALESCE((proof->>'fresh_auth')::boolean,false)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current browser authorization required';END IF;
 PERFORM zasp_authorization80.identity_fence(proof);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.compliance_read(org_value text, workspace_value text, environment_value text, principal_value text, session_value bytea, operation_value text, parameters_value jsonb, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;items_value jsonb;cursor_value jsonb;last_value jsonb;limit_value integer:=100;framework_value text;control_value text;family_value text;kind_value text;id_value text;version_value bigint;stamp timestamptz:=statement_timestamp();next_value jsonb;
BEGIN
 IF NOT zasp_authorization80.source_ready(56,expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='compliance release unavailable';END IF;
 IF NOT public.zasp_discovery_principal_ready('zasp_discovery_api') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='compliance API authority rejected';END IF;
 IF EXISTS(SELECT 1 FROM unnest(ARRAY[org_value,workspace_value,environment_value,principal_value]) v WHERE NOT public.zasp_valid_product_id(v)) OR octet_length(session_value) IS DISTINCT FROM 32 OR session_value=decode(repeat('00',32),'hex') OR parameters_value IS NULL OR jsonb_typeof(parameters_value)<>'object' OR octet_length(parameters_value::text)>4096 OR operation_value IS NULL OR operation_value NOT IN('listControls','listEvidence','getEvidence') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='compliance request rejected';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_object_keys(parameters_value) k WHERE k<>ALL(CASE WHEN operation_value='getEvidence' THEN ARRAY['source_kind','source_id','source_version'] ELSE ARRAY['framework','control_id','limit','cursor'] END)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='compliance parameter rejected';END IF;
 PERFORM zasp_authorization80.checked_browser(org_value,workspace_value,environment_value,principal_value,session_value);
 PERFORM zasp_authorization80.require_read(org_value,workspace_value,environment_value,CASE WHEN operation_value IN('listControls','listEvidence') THEN ARRAY['listComplianceControls','listComplianceEvidence'] WHEN operation_value='getEvidence' THEN ARRAY['getComplianceEvidence'] ELSE ARRAY[]::text[] END,'view_compliance',true,principal_value); IF operation_value='getEvidence' AND ((zasp_authorization80.context()#>>'{path_parameters,sourceKind}') IS DISTINCT FROM parameters_value->>'source_kind' OR (zasp_authorization80.context()#>>'{path_parameters,id}') IS DISTINCT FROM parameters_value->>'source_id') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='compliance request binding rejected';END IF;
 framework_value:=parameters_value->>'framework';control_value:=parameters_value->>'control_id';
 IF parameters_value ? 'framework' AND (jsonb_typeof(parameters_value->'framework')<>'string' OR framework_value NOT IN('soc2_security','hipaa')) OR parameters_value ? 'control_id' AND (jsonb_typeof(parameters_value->'control_id')<>'string' OR NOT EXISTS(SELECT 1 FROM public.zasp_compliance_mappings() m WHERE m.control_id=control_value AND (framework_value IS NULL OR m.framework=framework_value))) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='compliance filter rejected';END IF;
 SELECT required_sources[1] INTO family_value FROM public.zasp_compliance_mappings() m WHERE m.control_id=control_value;
 IF parameters_value ? 'limit' THEN
  IF jsonb_typeof(parameters_value->'limit')<>'number' OR parameters_value->>'limit' !~ '^[1-9][0-9]{0,2}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='compliance page size rejected';END IF;
  limit_value:=(parameters_value->>'limit')::integer;
  IF limit_value>100 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='compliance page size rejected';END IF;
 END IF;
 cursor_value:=parameters_value->'cursor';
 IF parameters_value ? 'cursor' THEN
  IF jsonb_typeof(cursor_value)<>'object' OR (SELECT count(*) FROM jsonb_object_keys(cursor_value))<>8 OR cursor_value->>'organization_id' IS DISTINCT FROM org_value OR cursor_value->>'workspace_id' IS DISTINCT FROM workspace_value OR cursor_value->>'environment_id' IS DISTINCT FROM environment_value OR cursor_value->>'operation' IS DISTINCT FROM operation_value OR cursor_value->>'framework' IS DISTINCT FROM COALESCE(framework_value,'') OR cursor_value->>'control_id' IS DISTINCT FROM COALESCE(control_value,'') OR jsonb_typeof(cursor_value->'source_kind')<>'string' OR jsonb_typeof(cursor_value->'source_id')<>'string' OR EXISTS(SELECT 1 FROM jsonb_object_keys(cursor_value) k WHERE k<>ALL(ARRAY['organization_id','workspace_id','environment_id','operation','framework','control_id','source_kind','source_id'])) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='compliance cursor rejected';END IF;
  IF operation_value='listEvidence' AND NOT public.zasp_compliance_valid_target(cursor_value->>'source_kind',cursor_value->>'source_id') OR operation_value='listControls' AND NOT EXISTS(SELECT 1 FROM public.zasp_compliance_mappings() m WHERE m.framework=cursor_value->>'source_kind' AND m.control_id=cursor_value->>'source_id') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='compliance cursor rejected';END IF;
 END IF;
 IF operation_value='getEvidence' THEN
  kind_value:=parameters_value->>'source_kind';id_value:=parameters_value->>'source_id';
  IF NOT public.zasp_compliance_valid_target(kind_value,id_value) OR jsonb_typeof(parameters_value->'source_kind') IS DISTINCT FROM 'string' OR jsonb_typeof(parameters_value->'source_id') IS DISTINCT FROM 'string' OR parameters_value ? 'source_version' AND (jsonb_typeof(parameters_value->'source_version')<>'number' OR parameters_value->>'source_version' !~ '^[1-9][0-9]{0,14}$') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='compliance target rejected';END IF;
  version_value:=(parameters_value->>'source_version')::bigint;
 END IF;
 -- Materialize every eligible row once in this statement. Invalid sources must
 -- fail collection even when a first page or a category filter excludes them.
 WITH sources AS MATERIALIZED (SELECT * FROM public.zasp_compliance_sources(org_value,workspace_value,environment_value) s WHERE zasp_authorization80.parent_allowed(org_value,workspace_value,environment_value,'compliance_evidence',s.source_id,s.source_kind)),
 checked AS (SELECT COALESCE(bool_and(source_valid AND source_time IS NOT NULL AND source_time<=stamp AND source_version>0 AND public.zasp_compliance_valid_target(source_kind,source_id)),true) valid FROM sources),
 page AS (SELECT * FROM sources s WHERE operation_value<>'listControls' AND (family_value IS NULL OR s.source_family=family_value) AND (operation_value<>'getEvidence' OR (s.source_kind,s.source_id)=(kind_value,id_value)) AND (cursor_value IS NULL OR (s.source_kind COLLATE "C",s.source_id COLLATE "C")>(cursor_value->>'source_kind' COLLATE "C",cursor_value->>'source_id' COLLATE "C")) ORDER BY s.source_kind COLLATE "C",s.source_id COLLATE "C" LIMIT limit_value+1),
 controls AS (SELECT m.*,CASE WHEN NOT EXISTS(SELECT 1 FROM sources s WHERE s.source_family=ANY(m.required_sources) AND COALESCE((s.metadata->>'migration_seeded')::boolean,false)=false) THEN 'missing' WHEN NOT EXISTS(SELECT 1 FROM sources s WHERE s.source_family=ANY(m.required_sources) AND s.source_time>=stamp-m.maximum_age_seconds*interval '1 second' AND COALESCE((s.metadata->>'migration_seeded')::boolean,false)=false) THEN 'stale' ELSE 'fresh' END freshness,to_char(COALESCE((SELECT max(s.source_time)+m.maximum_age_seconds*interval '1 second' FROM sources s WHERE s.source_family=ANY(m.required_sources) AND COALESCE((s.metadata->>'migration_seeded')::boolean,false)=false),'1970-01-01 00:00:00+00'::timestamptz) AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') fresh_until FROM public.zasp_compliance_mappings() m WHERE operation_value='listControls' AND (framework_value IS NULL OR m.framework=framework_value) AND (control_value IS NULL OR m.control_id=control_value) AND (cursor_value IS NULL OR (m.framework COLLATE "C",m.control_id COLLATE "C")>(cursor_value->>'source_kind' COLLATE "C",cursor_value->>'source_id' COLLATE "C")) ORDER BY m.framework COLLATE "C",m.control_id COLLATE "C" LIMIT limit_value+1)
 SELECT jsonb_build_object('valid',(SELECT valid FROM checked),'items',CASE WHEN operation_value='listControls' THEN COALESCE((SELECT jsonb_agg(to_jsonb(c) ORDER BY c.framework COLLATE "C",c.control_id COLLATE "C") FROM controls c),'[]'::jsonb) ELSE COALESCE((SELECT jsonb_agg(jsonb_build_object('id',s.source_id,'asset',s.source_id,'source',s.source_family,'timestamp',to_char(s.source_time AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'organization_id',org_value,'workspace_id',workspace_value,'environment_id',environment_value,'target',jsonb_build_object('source_kind',s.source_kind,'source_id',s.source_id,'source_version',s.source_version),'freshness',CASE WHEN s.source_time<stamp-interval '24 hours' THEN 'stale' ELSE 'fresh' END,'metadata',s.metadata) ORDER BY s.source_kind COLLATE "C",s.source_id COLLATE "C") FROM page s),'[]'::jsonb) END) INTO result_value;
 IF NOT (result_value->>'valid')::boolean THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='compliance invalid source';END IF;
 items_value:=result_value->'items';
 IF operation_value='getEvidence' THEN
  IF jsonb_array_length(items_value)=0 THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='compliance source not found';END IF;
  IF jsonb_array_length(items_value)<>1 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='compliance source identity collision';END IF;
  IF version_value IS NOT NULL AND (items_value->0->'target'->>'source_version')::bigint<>version_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='compliance source_changed';END IF;
  result_value:=items_value->0;
 ELSE
  IF jsonb_array_length(items_value)>limit_value THEN
   items_value:=items_value-limit_value;last_value:=items_value->(limit_value-1);
   next_value:=jsonb_build_object('organization_id',org_value,'workspace_id',workspace_value,'environment_id',environment_value,'operation',operation_value,'framework',COALESCE(framework_value,''),'control_id',COALESCE(control_value,''),'source_kind',CASE WHEN operation_value='listControls' THEN last_value->>'framework' ELSE last_value->'target'->>'source_kind' END,'source_id',CASE WHEN operation_value='listControls' THEN last_value->>'control_id' ELSE last_value->'target'->>'source_id' END);
  END IF;
  result_value:=jsonb_build_object('mapping_revision','product-evidence-v1','collected_at',to_char(stamp AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'items',items_value,'next_cursor',next_value);
 END IF;
 PERFORM zasp_authorization80.checked_browser(org_value,workspace_value,environment_value,principal_value,session_value);
 PERFORM zasp_authorization80.require_read(org_value,workspace_value,environment_value,CASE WHEN operation_value IN('listControls','listEvidence') THEN ARRAY['listComplianceControls','listComplianceEvidence'] WHEN operation_value='getEvidence' THEN ARRAY['getComplianceEvidence'] ELSE ARRAY[]::text[] END,'view_compliance',true,principal_value); IF operation_value='getEvidence' AND ((zasp_authorization80.context()#>>'{path_parameters,sourceKind}') IS DISTINCT FROM parameters_value->>'source_kind' OR (zasp_authorization80.context()#>>'{path_parameters,id}') IS DISTINCT FROM parameters_value->>'source_id') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='compliance request binding rejected';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.context()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;seal text;
BEGIN
 p:=NULLIF(current_setting('zasp.authorization80',true),'')::jsonb;
 seal:=NULLIF(current_setting('zasp.authorization80_seal',true),'');
 IF p IS NULL OR seal IS NULL OR pg_current_xact_id_if_assigned() IS NULL OR seal IS DISTINCT FROM zasp_authorization80.context_seal(p)
 OR NOT COALESCE((p->>'expires_at')::bigint>floor(extract(epoch FROM clock_timestamp())*1000)::bigint,false) THEN RETURN NULL;END IF;
 RETURN p;
EXCEPTION WHEN data_exception THEN RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.create_environment(new_id text, o text, requested_workspace text, name_value text, audit_value text, actor_value text, w text, e text, permissions_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 PERFORM zasp_authorization80.require_hierarchy_create(o,w,e,actor_value,'createEnvironment',permissions_value);
 IF requested_workspace IS DISTINCT FROM w THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='hierarchy parent unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(new_id) AND public.zasp_valid_product_id(audit_value),false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid hierarchy creation identifier';END IF;
 WITH created AS (
  INSERT INTO public.zasp_environments(id,organization_id,workspace_id,name,environment_class) VALUES(new_id,o,w,name_value,'development') RETURNING *
 ),granted AS (
  INSERT INTO public.zasp_authorized_scopes(principal_id,organization_id,workspace_id,environment_id,label,permissions,is_default)
  SELECT actor_value,o,w,new_id,name_value,'[]'::jsonb,false FROM created
 ),bootstrap AS (
  INSERT INTO public.zasp_core_payloads(organization_id,workspace_id,environment_id,operation,payload)
  SELECT o,w,new_id,'session_bootstrap:'||actor_value,jsonb_build_object('correlation_id',audit_value) FROM created
 ),controls AS (
  INSERT INTO public.zasp_data_controls(organization_id,workspace_id,environment_id,environment_class,collection_mode,retention_days,deletion_enabled)
  SELECT organization_id,workspace_id,id,environment_class,'metadata_only',30,true FROM created
 ),audited AS (
  INSERT INTO public.zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata)
  SELECT o,w,new_id,audit_value,actor_value,'environment.create',new_id,'succeeded','{}'::jsonb FROM created
 ) SELECT jsonb_build_object('id',id,'organization_id',organization_id,'workspace_id',workspace_id,'name',name,'environment_class',environment_class,'version',version,'audit_correlation_id',audit_value) INTO result FROM created;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.create_sensor(organization_value text, workspace_value text, environment_value text, principal_value text, sensor_value text, name_value text, kind_value text, mode_value text, idempotency_value text, request_digest_value bytea, token_value text, generation_value bigint, locator_digest_value bytea, salt_value bytea, token_hash_value bytea, expires_value timestamp with time zone, runtime_sensor_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_value zasp_runtime_sensor_mutations%ROWTYPE;result_value jsonb;stored_runtime text;
BEGIN
 IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'createSensorEnrollment',NULL,principal_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current sensor authorization required';END IF;
 IF runtime_sensor_value IS NOT NULL AND NOT COALESCE(kind_value='otlp' AND zasp_valid_product_id(runtime_sensor_value) AND runtime_sensor_value<>sensor_value,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor pairing rejected';END IF;
 IF runtime_sensor_value IS NOT NULL AND NOT COALESCE(zasp_discovery_principal_ready('zasp_discovery_api') AND zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'createSensorEnrollment',NULL,principal_value),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value),0));
 IF runtime_sensor_value IS NOT NULL AND NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'createSensorEnrollment',NULL,principal_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
 SELECT * INTO prior_value FROM zasp_runtime_sensor_mutations WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value) FOR UPDATE;
 IF FOUND THEN
  -- Receipt row locking can independently wait after the advisory lock.
  IF runtime_sensor_value IS NOT NULL AND NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'createSensorEnrollment',NULL,principal_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
  SELECT runtime_sensor_id INTO stored_runtime FROM zasp_runtime_sensor_pairings WHERE (organization_id,workspace_id,environment_id,sensor_id)=(organization_value,workspace_value,environment_value,prior_value.sensor_id);
  IF prior_value.request_digest IS DISTINCT FROM request_digest_value OR stored_runtime IS DISTINCT FROM runtime_sensor_value
   OR prior_value.result#>>'{body,id}' IS DISTINCT FROM prior_value.sensor_id OR prior_value.result#>>'{body,runtime_sensor_id}' IS DISTINCT FROM stored_runtime
   OR prior_value.result#>>'{body,name}' IS DISTINCT FROM name_value OR prior_value.result#>>'{body,kind}' IS DISTINCT FROM kind_value OR prior_value.result#>>'{body,mode}' IS DISTINCT FROM mode_value THEN
   RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor pairing replay conflict';
  END IF;
  RETURN jsonb_set(prior_value.result,'{replayed}','true'::jsonb);
 END IF;
 IF runtime_sensor_value IS NOT NULL THEN
  -- FOR SHARE conflicts with status updates; KEY SHARE would not fence revoke.
  PERFORM 1 FROM zasp_sensors WHERE (organization_id,workspace_id,environment_id,id)=(organization_value,workspace_value,environment_value,runtime_sensor_value) AND kind='tetragon' AND state='active' FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime sensor pairing anchor missing';END IF;
  -- Permission may have changed while waiting for the anchor or idempotency lock.
  IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'createSensorEnrollment',NULL,principal_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
 END IF;
 result_value:=zasp_runtime_public_create_sensor_v44(organization_value,workspace_value,environment_value,principal_value,sensor_value,name_value,kind_value,mode_value,idempotency_value,request_digest_value,token_value,generation_value,locator_digest_value,salt_value,token_hash_value,expires_value);
 IF result_value->>'replayed' IS DISTINCT FROM 'false' OR result_value#>>'{body,id}' IS DISTINCT FROM sensor_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor pairing creation conflict';END IF;
 IF runtime_sensor_value IS NOT NULL THEN
  -- The legacy creation path may have waited on credential uniqueness locks.
  IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'createSensorEnrollment',NULL,principal_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='sensor pairing authority rejected';END IF;
  INSERT INTO zasp_runtime_sensor_pairings(organization_id,workspace_id,environment_id,sensor_id,runtime_sensor_id) VALUES(organization_value,workspace_value,environment_value,sensor_value,runtime_sensor_value);
  result_value:=jsonb_set(result_value,'{body,runtime_sensor_id}',to_jsonb(runtime_sensor_value));
  UPDATE zasp_runtime_sensor_mutations SET result=result_value WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,sensor_id)=(organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value,sensor_value) AND request_digest=request_digest_value;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor pairing receipt missing';END IF;
 END IF;
 PERFORM zasp_authorization80.sensor_audit(organization_value,workspace_value,environment_value,principal_value,'createSensorEnrollment',idempotency_value,result_value);RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80.create_workspace(new_id text, o text, name_value text, w text, e text, audit_value text, actor_value text, new_environment_id text, permissions_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 PERFORM zasp_authorization80.require_hierarchy_create(o,w,e,actor_value,'createWorkspace',permissions_value);
 IF NOT COALESCE(public.zasp_valid_product_id(new_id) AND public.zasp_valid_product_id(new_environment_id) AND public.zasp_valid_product_id(audit_value),false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid hierarchy creation identifier';END IF;
 WITH created_workspace AS (
  INSERT INTO public.zasp_workspaces(id,organization_id,name) VALUES(new_id,o,name_value) RETURNING *
 ),created_environment AS (
  INSERT INTO public.zasp_environments(id,organization_id,workspace_id,name,environment_class)
  SELECT new_environment_id,o,new_id,'Development','development' FROM created_workspace RETURNING *
 ),granted AS (
  INSERT INTO public.zasp_authorized_scopes(principal_id,organization_id,workspace_id,environment_id,label,permissions,is_default)
  SELECT actor_value,o,new_id,new_environment_id,left(name_value||' / Development',128),'[]'::jsonb,false FROM created_environment
 ),bootstrap AS (
  INSERT INTO public.zasp_core_payloads(organization_id,workspace_id,environment_id,operation,payload)
  SELECT o,new_id,new_environment_id,'session_bootstrap:'||actor_value,jsonb_build_object('correlation_id',audit_value) FROM created_environment
 ),controls AS (
  INSERT INTO public.zasp_data_controls(organization_id,workspace_id,environment_id,environment_class,collection_mode,retention_days,deletion_enabled)
  SELECT o,new_id,new_environment_id,'development','metadata_only',30,true FROM created_environment
 ),audited AS (
  INSERT INTO public.zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata)
  SELECT o,w,e,audit_value,actor_value,'workspace.onboard',new_id,'succeeded',jsonb_build_object('initial_environment_id',new_environment_id) FROM created_environment
 ) SELECT jsonb_build_object('id',id,'organization_id',organization_id,'name',name,'version',version,'initial_environment_id',new_environment_id,'audit_correlation_id',audit_value) INTO result FROM created_workspace;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.delete_sensor(organization_value text, workspace_value text, environment_value text, principal_value text, sensor_value text, expected_version_value bigint, idempotency_value text, request_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_value zasp_runtime_sensor_mutations%ROWTYPE;result_value jsonb;
BEGIN
 IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'deleteSensor',sensor_value,principal_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current sensor authorization required';END IF;
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(principal_value) OR NOT zasp_valid_product_id(sensor_value) OR expected_version_value<1 OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR octet_length(request_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor mutation rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,sensor_value),0));
 SELECT * INTO prior_value FROM zasp_runtime_sensor_mutations mutation WHERE (mutation.organization_id,mutation.workspace_id,mutation.environment_id,mutation.principal_id,mutation.operation,mutation.idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,'deleteSensor',idempotency_value);
 IF FOUND THEN IF (prior_value.request_digest,prior_value.sensor_id,prior_value.expected_version) IS DISTINCT FROM (request_digest_value,sensor_value,expected_version_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor mutation conflict';END IF;RETURN jsonb_set(prior_value.result,'{replayed}','true'::jsonb);END IF;
 UPDATE zasp_sensor_tokens token_row SET revoked_at=COALESCE(token_row.revoked_at,transaction_timestamp()) WHERE (token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id)=(organization_value,workspace_value,environment_value,sensor_value) AND token_row.format_version=1;
 UPDATE zasp_sensors sensor_row SET state='deleted',version=sensor_row.version+1,updated_at=transaction_timestamp(),revoked_at=COALESCE(sensor_row.revoked_at,transaction_timestamp()) WHERE (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id,sensor_row.version)=(organization_value,workspace_value,environment_value,sensor_value,expected_version_value) AND sensor_row.state IN('pending','active','degraded','revoked');
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='sensor mutation conflict';END IF;
 result_value:=jsonb_build_object('body',zasp_runtime_public_sensor_value(organization_value,workspace_value,environment_value,sensor_value),'token_id',NULL,'token_generation',NULL,'token_expires_at',NULL,'replayed',false);
 INSERT INTO zasp_runtime_sensor_mutations(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,request_digest,sensor_id,expected_version,result) VALUES(organization_value,workspace_value,environment_value,principal_value,'deleteSensor',idempotency_value,request_digest_value,sensor_value,expected_version_value,result_value);PERFORM zasp_runtime_mark_used();PERFORM zasp_authorization80.sensor_audit(organization_value,workspace_value,environment_value,principal_value,'deleteSensor',idempotency_value,result_value);RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.fence(envelope text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;r jsonb;target jsonb;current_value jsonb;descriptor jsonb;
BEGIN
 IF NOT zasp_authorization79.reader() OR NOT zasp_authorization80.ready('d7fbda32a2b3b9ea0ffbd4f7c7a7967a9d4fba2f6573f49e8386e9586a18a1fd') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization fence rejected';END IF;
 p:=zasp_authorization80.verify_attestation(envelope);
 r:=p->'revision';
 IF r->>'organization_id' IS DISTINCT FROM p->>'organization_id' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization scope rejected';END IF;
 PERFORM zasp_authorization79.revalidate(r->>'organization_id',(r->>'desired')::bigint,(r->>'generation')::bigint,r->>'store_id',r->>'model_id');
 PERFORM zasp_authorization80.identity_fence(p);
 FOR target IN SELECT value FROM jsonb_array_elements(p->'targets') ORDER BY value->>'kind',value->>'id' LOOP
  IF target->>'organization_id' IS DISTINCT FROM p->>'organization_id' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization target scope rejected';END IF;
  IF target->>'kind' IN('organization','organization_identity','workspace','environment') THEN
   PERFORM 1 FROM public.zasp_environments x WHERE(x.organization_id,x.workspace_id,x.id)=(target->>'organization_id',target->>'workspace_id',target->>'environment_id') FOR SHARE;
   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='authorization target changed';END IF;
   IF target->>'kind'='workspace' THEN
    PERFORM 1 FROM public.zasp_workspaces x WHERE(x.organization_id,x.id,x.version)=(target->>'organization_id',target->>'id',(target->>'version')::bigint) FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='authorization workspace version changed';END IF;
   ELSIF target->>'kind'='environment' THEN
    PERFORM 1 FROM public.zasp_environments x WHERE(x.organization_id,x.workspace_id,x.id,x.version)=(target->>'organization_id',target->>'workspace_id',target->>'id',(target->>'version')::bigint) FOR SHARE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='authorization environment version changed';END IF;
   END IF;
  ELSE
   descriptor:=zasp_authorization80.source(target->>'kind');
   SELECT v INTO current_value FROM zasp_authorization80.source_rows(target->>'organization_id',target->>'workspace_id',target->>'environment_id',target->>'kind',COALESCE(NULLIF(target->>'source_id',''),target->>'id'),true) v;
   IF current_value IS NULL OR COALESCE((current_value->>'version')::bigint,0) IS DISTINCT FROM (target->>'version')::bigint THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='authorization target version changed';END IF;
  END IF;
 END LOOP;
 PERFORM set_config('zasp.authorization80',p::text,true);
 PERFORM txid_current();
 PERFORM set_config('zasp.authorization80_seal',zasp_authorization80.context_seal(p),true);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.get_data_controls(o text, w text, e text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT zasp_authorization80.data_controls_authorized(o,w,e,'getDataControls') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current data controls authorization required';END IF;
 SELECT jsonb_build_object('environment_id',environment_id,'environment_class',environment_class,'collection_mode',collection_mode,'retention_days',retention_days,'deletion_enabled',deletion_enabled,'version',version) INTO result
 FROM public.zasp_data_controls WHERE(organization_id,workspace_id,environment_id)=(o,w,e);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='data controls missing';END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.global_search(o text, w text, e text, q text, n integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;normalized text:=lower(q);
BEGIN
 PERFORM zasp_authorization80.require_read(o,w,e,ARRAY['globalSearch'],'view');
 IF q IS NULL OR char_length(q) NOT BETWEEN 2 AND 128 OR octet_length(q)>128 OR q<>btrim(q) OR q!~'^[A-Za-z0-9 .:_/-]+$' OR n NOT BETWEEN 1 AND 100 OR public.zasp_inventory_scope_state(o,w,e)->>'phase' IS DISTINCT FROM 'cutover' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='authorization search rejected';END IF;
 WITH candidates AS(
 SELECT id,product_kind kind,display_name name,CASE WHEN id=q THEN 0 WHEN product_kind=normalized THEN 1 WHEN lower(display_name)=normalized THEN 2 ELSE 3 END rank
 FROM public.zasp_inventory_entities v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.state)=(o,w,e,'active') AND zasp_authorization80.allowed(o,w,e,product_kind,id) AND(id=q OR product_kind=normalized OR lower(display_name) COLLATE "C" LIKE normalized COLLATE "C"||'%')
 UNION ALL SELECT id,'finding',title,CASE WHEN id=q THEN 0 WHEN normalized='finding' THEN 1 WHEN lower(title)=normalized THEN 2 ELSE 3 END FROM public.zasp_risk_findings f WHERE(f.organization_id,f.workspace_id,f.environment_id)=(o,w,e) AND zasp_authorization80.allowed(o,w,e,'finding',id) AND(id=q OR normalized='finding' OR lower(title) COLLATE "C" LIKE normalized COLLATE "C"||'%')
 ),visible AS(SELECT id,kind,name FROM candidates ORDER BY rank,kind,lower(name),id LIMIT n)
 SELECT jsonb_build_object('items',COALESCE(jsonb_agg(jsonb_build_object('id',id,'type',kind,'name',name) ORDER BY kind,lower(name),id),'[]'::jsonb)) INTO result FROM visible;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.hierarchy_write_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE admitted boolean;
BEGIN
 IF TG_NARGS<>1 OR TG_LEVEL<>'STATEMENT' OR TG_WHEN<>'BEFORE'
  OR TG_RELID NOT IN('public.zasp_workspaces'::regclass,'public.zasp_environments'::regclass,'public.zasp_authorized_scopes'::regclass,'public.zasp_core_payloads'::regclass)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='hierarchy writer contract rejected';END IF;
 IF current_user=TG_ARGV[0] AND EXISTS(SELECT 1 FROM pg_class c JOIN pg_roles r ON r.oid=c.relowner WHERE c.oid=TG_RELID AND r.rolname=TG_ARGV[0] AND r.rolcanlogin)
 THEN RETURN NULL;END IF;
 -- Source19 deprovision removes direct grants under its exact nonlogin owner.
 -- It does not need scope INSERT/UPDATE, hierarchy writes or TRUNCATE.
 IF current_user='zasp_discovery_authority' AND TG_RELID='public.zasp_authorized_scopes'::regclass AND TG_OP='DELETE'
  AND EXISTS(SELECT 1 FROM pg_roles WHERE rolname=current_user AND NOT rolcanlogin AND NOT rolsuper AND NOT rolbypassrls)
 THEN
  IF EXISTS(SELECT 1 FROM zasp_authorization80.runtime_profile WHERE identity_mode<>'none') THEN
   EXECUTE 'SELECT zasp_authorization80_identity.scope_cleanup_allowed()' INTO admitted;
   IF NOT COALESCE(admitted,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='verified identity cleanup required';END IF;
  END IF;
  RETURN NULL;
 END IF;
 RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='checked hierarchy writer required';
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.identity_fence(p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE credential jsonb;kind integer;
BEGIN
 PERFORM 1 FROM public.zasp_identity_memberships m WHERE(m.principal_id,m.organization_id)=(p->>'principal_id',p->>'organization_id') AND m.active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='current identity changed; retry from Check';END IF;
 kind:=(p->>'credential_kind')::integer;
 IF kind=1 THEN
  SELECT to_jsonb(s) INTO credential FROM public.zasp_product_sessions s WHERE s.token_digest=decode(p->>'credential_digest','hex') AND s.session_id=p->>'credential_id' FOR SHARE;
 ELSIF kind=2 THEN
  SELECT to_jsonb(t) INTO credential FROM public.zasp_product_api_tokens t WHERE t.token_digest=decode(p->>'credential_digest','hex') AND t.id=p->>'credential_id' FOR SHARE;
 ELSE RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='credential kind rejected';END IF;
 IF credential IS NULL OR credential->>'revoked_at' IS NOT NULL OR (credential->>'expires_at')::timestamptz<=clock_timestamp()
 OR (credential->>'principal_id',credential->>'organization_id',credential->>'workspace_id',credential->>'environment_id') IS DISTINCT FROM(p->>'principal_id',p->>'organization_id',p->>'workspace_id',p->>'environment_id')
 OR NOT EXISTS(SELECT 1 FROM public.zasp_identity_admin_effective_scopes(p->>'principal_id',p->>'organization_id') s WHERE(s.workspace_id,s.environment_id)=(p->>'workspace_id',p->>'environment_id'))
 OR(kind=2 AND(NOT credential->'permissions' ? (p->>'permission') OR credential->'permissions' IS DISTINCT FROM p->'pat_ceiling'))
 OR(kind=1 AND encode(public.digest(credential->>'csrf_token','sha256'),'hex') IS DISTINCT FROM p->>'csrf_digest')
 OR(kind=1 AND COALESCE((p->>'fresh_auth')::boolean,false) AND (credential->>'authenticated_at')::timestamptz<=clock_timestamp()-interval '5 minutes')
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='current credential changed; retry from Check';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_connector_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  mutation_response jsonb;
  connector_key text;
  display_name_value text;
  configuration_value jsonb;
  response_version bigint;
  typed_row zasp_integrations%ROWTYPE;
  workflow_row zasp_workflow_records%ROWTYPE;
  connection_row zasp_integration_connections%ROWTYPE;
  credential_row zasp_connector_credentials%ROWTYPE;
  revocation_effect_id text;
  revocation_digest bytea;
BEGIN
	IF requested_kind<>'integration' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='connector workflow kind rejected';
	END IF;
	IF mutation='delete' THEN
		SELECT * INTO workflow_row FROM zasp_workflow_records WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id AND environment_id=requested_environment_id AND kind='integration' AND id=requested_id AND deleted_at IS NULL FOR UPDATE;
		IF EXISTS(SELECT 1 FROM zasp_connector_oauth_attempts WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id AND environment_id=requested_environment_id AND integration_id=requested_id AND status IN('pending','consuming'))
		  OR EXISTS(SELECT 1 FROM zasp_connector_effects WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id AND environment_id=requested_environment_id AND integration_id=requested_id AND operation='authorize' AND status IN('pending','unknown')) THEN
			RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='connector authorization unresolved';
		END IF;
    SELECT * INTO connection_row FROM zasp_integration_connections WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id AND environment_id=requested_environment_id AND integration_id=requested_id AND state='verified' ORDER BY id LIMIT 1 FOR UPDATE;
    SELECT * INTO credential_row FROM zasp_connector_credentials WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id AND environment_id=requested_environment_id AND integration_id=requested_id AND status='active' ORDER BY id LIMIT 1 FOR UPDATE;
    IF workflow_row.id IS NOT NULL AND (connection_row.id IS NOT NULL OR credential_row.id IS NOT NULL) THEN
      mutation_response:=zasp_authorization80.integration_receipt_mutate(
        'update',requested_kind,requested_id,requested_organization_id,requested_workspace_id,requested_environment_id,
        requested_principal_id,requested_operation,requested_idempotency_key,expected_version,requested_intent,
        jsonb_set(workflow_row.body,'{status}','"revoking"'::jsonb),requested_audit_id,requested_correlation_id,requested_receipt_id
      );
      revocation_effect_id:=zasp_discovery_canonical_id(requested_organization_id,requested_workspace_id,requested_environment_id,'connector_effect','revoke'||chr(31)||requested_id||chr(31)||requested_idempotency_key);
      revocation_digest:=digest(convert_to(jsonb_build_object('integration_id',requested_id,'provider',COALESCE(connection_row.provider,credential_row.provider),'connection_reference',COALESCE(connection_row.connection_reference,credential_row.credential_reference),'credential_version',credential_row.version)::text,'UTF8'),'sha256');
      PERFORM zasp_connector_begin_effect(requested_organization_id,requested_workspace_id,requested_environment_id,revocation_effect_id,requested_id,'',COALESCE(connection_row.provider,credential_row.provider),'revoke',requested_idempotency_key,revocation_digest);
      PERFORM zasp_connector_resolve_effect(requested_organization_id,requested_workspace_id,requested_environment_id,revocation_effect_id,'unknown',COALESCE(connection_row.connection_reference,credential_row.credential_reference),'{}'::jsonb,'revocation_requested');
      UPDATE zasp_integrations SET state='degraded',version=GREATEST(version,(mutation_response->>'version')::bigint),updated_at=transaction_timestamp() WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id AND environment_id=requested_environment_id AND id=requested_id AND state<>'deleted';
      PERFORM zasp_connector_audit_event(requested_organization_id,requested_workspace_id,requested_environment_id,requested_id,'',revocation_effect_id,'revocation_requested',requested_principal_id,'','{}'::jsonb);
      RETURN mutation_response;
    END IF;
  END IF;
  mutation_response:=zasp_authorization80.integration_receipt_mutate(
    mutation,requested_kind,requested_id,requested_organization_id,requested_workspace_id,requested_environment_id,
    requested_principal_id,requested_operation,requested_idempotency_key,expected_version,requested_intent,
    requested_body,requested_audit_id,requested_correlation_id,requested_receipt_id
  );
  IF mutation='delete' THEN
    UPDATE zasp_integrations SET state='deleted',deleted_at=COALESCE(deleted_at,transaction_timestamp()),
      version=GREATEST(version,(mutation_response->>'version')::bigint),updated_at=CASE WHEN state='deleted' THEN updated_at ELSE transaction_timestamp() END
    WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id AND environment_id=requested_environment_id
      AND id=requested_id AND state<>'deleted';
    IF NOT FOUND AND NOT EXISTS(SELECT 1 FROM zasp_integrations WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id AND environment_id=requested_environment_id AND id=requested_id AND state='deleted') THEN
      RAISE EXCEPTION USING ERRCODE='02000',MESSAGE='typed integration unavailable';
    END IF;
    RETURN mutation_response;
  END IF;
  connector_key:=requested_body->>'connector_key';
  display_name_value:=requested_body->>'name';
  configuration_value:=zasp_authorization80.integration_typed_configuration(requested_body->>'connector_key',requested_body->'configuration');
  response_version:=(mutation_response->>'version')::bigint;
  IF connector_key IS NULL OR length(connector_key) NOT BETWEEN 1 AND 64 OR display_name_value IS NULL OR length(display_name_value) NOT BETWEEN 1 AND 128
    OR jsonb_typeof(configuration_value)<>'object' OR NOT zasp_reference_only(configuration_value) OR response_version<1 THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid typed integration';
  END IF;
  IF mutation='create' THEN
    PERFORM zasp_discovery_create_integration(requested_organization_id,requested_workspace_id,requested_environment_id,requested_id,connector_key,'1.0.0',display_name_value,configuration_value,NULL);
  ELSIF mutation='update' THEN
    SELECT * INTO typed_row FROM zasp_integrations WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id
      AND environment_id=requested_environment_id AND id=requested_id FOR UPDATE;
    IF NOT FOUND OR typed_row.kind<>connector_key OR typed_row.state='deleted' THEN
      RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='typed integration conflict';
    END IF;
    IF NOT COALESCE((mutation_response->>'replayed')::boolean,false) THEN
      UPDATE zasp_integrations SET display_name=display_name_value,configuration=configuration_value,version=GREATEST(typed_row.version+1,response_version),updated_at=transaction_timestamp()
      WHERE organization_id=requested_organization_id AND workspace_id=requested_workspace_id AND environment_id=requested_environment_id AND id=requested_id;
    END IF;
  ELSE
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid connector workflow mutation';
  END IF;
  RETURN mutation_response;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_mutate(action_value text, kind_value text, id_value text, o text, w text, e text, actor_value text, operation_value text, key_value text, expected_version bigint, intent_value jsonb, body_value jsonb, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;replay jsonb;result jsonb;old_workflow public.zasp_workflow_records%ROWTYPE;old_typed public.zasp_integrations%ROWTYPE;prepared jsonb;input jsonb;connector text;next_version bigint;next_typed bigint;revision_value bigint;clock_value text;
BEGIN
 PERFORM zasp_authorization80.integration_current_ready();
 p:=zasp_authorization80.require_integration_operation(o,w,e,actor_value,operation_value,CASE operation_value WHEN 'createIntegration' THEN e ELSE id_value END);
 IF NOT COALESCE(kind_value='integration' AND (action_value,operation_value) IN(('create','createIntegration'),('update','updateIntegration'))
  AND public.zasp_valid_product_id(id_value) AND public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value)
  AND ((p->>'credential_kind'='1' AND public.zasp_valid_product_id(receipt_value)) OR (p->>'credential_kind'='2' AND receipt_value=''))
  AND jsonb_typeof(intent_value)='object' AND intent_value-ARRAY['resource_id','expected_version','body']='{}'::jsonb
  AND intent_value->'expected_version'=to_jsonb(expected_version)
  AND intent_value->>'resource_id'=CASE action_value WHEN 'create' THEN '' ELSE id_value END
  AND ((action_value='create' AND expected_version=0) OR (action_value='update' AND expected_version>0)),false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration mutation request rejected';END IF;
 replay:=zasp_authorization80.integration_replay(o,w,e,actor_value,operation_value,key_value,intent_value);
 IF (replay->>'found')::boolean THEN RETURN replay->'result';END IF;
 input:=intent_value->'body';
 IF NOT COALESCE(jsonb_typeof(input)='object' AND input-ARRAY['name','connector_key','configuration']='{}'::jsonb
  AND jsonb_typeof(input->'name')='string' AND octet_length(input->>'name') BETWEEN 1 AND 128
  AND jsonb_typeof(body_value)='object' AND body_value->>'id'=id_value AND body_value->'name'=input->'name' AND body_value->'configuration'=input->'configuration',false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration body rejected';END IF;
 IF action_value='update' THEN
  SELECT * INTO old_workflow FROM public.zasp_workflow_records r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.kind,r.id)=(o,w,e,'integration',id_value) AND r.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration unavailable';END IF;
  SELECT * INTO old_typed FROM public.zasp_integrations i WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(o,w,e,id_value) AND i.deleted_at IS NULL AND i.state<>'deleted' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration unavailable';END IF;
  IF old_workflow.version<>expected_version OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'targets') t WHERE(t->>'kind',t->>'id',(t->>'version')::bigint)=('integration',id_value,old_typed.version))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='integration version conflict';END IF;
  IF old_workflow.version=9223372036854775807 OR old_typed.version=9223372036854775807 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='integration version exhausted';END IF;
  connector:=old_workflow.body->>'connector_key';
  IF connector IS DISTINCT FROM old_typed.kind OR old_typed.configuration IS DISTINCT FROM zasp_authorization80.integration_typed_configuration(connector,old_workflow.body->'configuration') OR body_value-ARRAY['name','configuration','updated_at'] IS DISTINCT FROM old_workflow.body-ARRAY['name','configuration','updated_at']
  THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration server fields rejected';END IF;
  next_version:=old_workflow.version+1;next_typed:=GREATEST(old_typed.version+1,next_version);
 ELSE
  connector:=input->>'connector_key';
  IF NOT COALESCE(jsonb_typeof(input->'connector_key')='string' AND body_value->>'connector_key'=connector AND body_value->>'status'=CASE connector WHEN 'generic-webhook' THEN 'configured' ELSE 'pending_authorization' END
   AND body_value-ARRAY['id','name','connector_key','configuration','status','created_at','updated_at']='{}'::jsonb,false)
  THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration server fields rejected';END IF;
  IF EXISTS(SELECT 1 FROM public.zasp_integrations i WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(o,w,e,id_value)) OR EXISTS(SELECT 1 FROM public.zasp_workflow_records r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.kind,r.id)=(o,w,e,'integration',id_value)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='integration already exists';END IF;
  next_version:=1;next_typed:=1;
 END IF;
 IF NOT COALESCE(zasp_authorization80.integration_setup_valid(connector,input->'configuration'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration setup rejected';END IF;
 PERFORM zasp_authorization80.integration_rejection_classify(p);
 PERFORM zasp_authorization80.identity_fence(p);
 PERFORM zasp_authorization79.revalidate(o,(p#>>'{revision,desired}')::bigint,(p#>>'{revision,generation}')::bigint,p#>>'{revision,store_id}',p#>>'{revision,model_id}');
 clock_value:=to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS"Z"');
 prepared:=body_value||jsonb_build_object('updated_at',clock_value);
 IF action_value='create' THEN prepared:=prepared||jsonb_build_object('created_at',clock_value);END IF;
 result:=zasp_authorization80.integration_connector_mutate(action_value,kind_value,id_value,o,w,e,actor_value,operation_value,key_value,expected_version,intent_value,prepared,audit_value,correlation_value,receipt_value);
 -- Create inserts two captured resource rows; an update changes neither
 -- source79's membership columns nor lifecycle state. Retain the held revision
 -- lock and require this exact delta, never a caller-selected new revision.
 revision_value:=(p#>>'{revision,desired}')::bigint+CASE action_value WHEN 'create' THEN 2 ELSE 0 END;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization79.organizations x WHERE x.organization_id=o AND x.desired=revision_value AND x.applied=(p#>>'{revision,applied}')::bigint AND x.generation=(p#>>'{revision,generation}')::bigint AND x.store_id=p#>>'{revision,store_id}' AND x.model_id=p#>>'{revision,model_id}')
 OR NOT EXISTS(SELECT 1 FROM public.zasp_integrations i WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id,i.version,i.kind,i.configuration)=(o,w,e,id_value,next_typed,connector,zasp_authorization80.integration_typed_configuration(connector,prepared->'configuration')))
 OR NOT EXISTS(SELECT 1 FROM public.zasp_workflow_records r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.kind,r.id,r.version,r.body)=(o,w,e,'integration',id_value,next_version,prepared))
 OR result->>'audit_id' IS DISTINCT FROM audit_value OR result->>'correlation_id' IS DISTINCT FROM correlation_value OR (result->>'version')::bigint IS DISTINCT FROM next_version
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='integration mutation accounting changed';END IF;
 PERFORM zasp_authorization80.integration_rejection_classify(p);
 PERFORM zasp_authorization80.identity_fence(p);
 PERFORM zasp_authorization80.integration_current_ready();
 IF zasp_authorization80.context() IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='integration proof expired';END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_receipt_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    mutation_response jsonb;
    existing_receipt_id text;
BEGIN
    LOCK TABLE "public"."zasp_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    PERFORM zasp_authorization80.integration_current_ready();
    PERFORM zasp_authorization80.integration_current_ready();
    IF requested_receipt_id IS NOT NULL AND requested_receipt_id <> '' AND length(requested_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_response := "public"."zasp_workflow_mutate_v3"(
        mutation, requested_kind, requested_id,
        requested_organization_id, requested_workspace_id, requested_environment_id,
        requested_principal_id, requested_operation, requested_idempotency_key,
        expected_version, requested_intent, requested_body, requested_audit_id, requested_correlation_id
    );
    existing_receipt_id := mutation_response ->> 'receipt_id';
    IF existing_receipt_id IS NOT NULL THEN
        PERFORM zasp_authorization80.integration_current_ready(); RETURN mutation_response;
    END IF;
    IF requested_receipt_id IS NULL OR requested_receipt_id = '' THEN
        UPDATE "public"."zasp_workflow_idempotency"
           SET "receipt_semantics" = 'receiptless_incompatible'
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key
           AND NULLIF("response" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        PERFORM zasp_authorization80.integration_current_ready(); RETURN mutation_response;
    END IF;
    INSERT INTO "public"."zasp_workflow_receipts" (
        "organization_id", "workspace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "result", "resource_kind", "resource_id",
        "resource_version", "audit_id", "correlation_id"
    ) VALUES (
        requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_receipt_id,
        requested_operation, requested_idempotency_key, requested_intent, mutation_response -> 'body', requested_kind, requested_id,
        (mutation_response ->> 'version')::bigint, mutation_response ->> 'audit_id', mutation_response ->> 'correlation_id'
    );
    mutation_response := mutation_response || jsonb_build_object('receipt_id', requested_receipt_id);
    UPDATE "public"."zasp_workflow_idempotency"
       SET "response" = mutation_response - 'replayed',
           "receipt_semantics" = 'receipt_backed'
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    PERFORM zasp_authorization80.integration_current_ready(); RETURN mutation_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_reference_complete(o text, w text, e text, actor_value text, id_value text, provider_value text, connection_value text, reference_value text, key_value text, expected_version bigint, configuration_value jsonb, intent_value jsonb, audit_value text, correlation_value text, receipt_value text, subject_kind_value text, subject_id_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;result jsonb;replay jsonb;workflow_row public.zasp_workflow_records%ROWTYPE;typed_row public.zasp_integrations%ROWTYPE;connection_row public.zasp_integration_connections%ROWTYPE;next_typed bigint;next_connection bigint;revision_delta bigint;expected_intent jsonb;connection_digest bytea;connection_hex text;
BEGIN
 p:=zasp_authorization80.require_integration_reference(o,w,e,actor_value,id_value);
 -- Match connectorDeterministicID: scoped SHA256, first16 bytes, UUIDv4 and
 -- RFC4122 variant bits. The older discovery canonical ID fixes a different
 -- variant nibble and is not this public connection identity contract.
 connection_digest:=substring(public.digest(convert_to(concat_ws(chr(31),o,w,e,id_value,'reference-connection:'||provider_value),'UTF8'),'sha256') FROM 1 FOR 16);
 connection_digest:=set_byte(connection_digest,6,(get_byte(connection_digest,6)&15)|64);
 connection_digest:=set_byte(connection_digest,8,(get_byte(connection_digest,8)&63)|128);
 connection_hex:=encode(connection_digest,'hex');
 expected_intent:=jsonb_build_object('configuration',configuration_value,'expected_version',expected_version,'idempotency_key',key_value,'integration_id',id_value,'provider',provider_value,'scope',jsonb_build_object('environment_id',e,'organization_id',o,'workspace_id',w));
 IF NOT COALESCE(intent_value=expected_intent AND expected_version BETWEEN 1 AND 1000000 AND key_value~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$'
  AND provider_value IN('aws','kubernetes') AND connection_value='pid_'||substr(connection_hex,1,8)||'-'||substr(connection_hex,9,4)||'-'||substr(connection_hex,13,4)||'-'||substr(connection_hex,17,4)||'-'||substr(connection_hex,21,12) AND public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value) AND public.zasp_valid_product_id(receipt_value)
  AND public.zasp_reference_authorization_configuration_valid(provider_value,configuration_value)
  AND public.zasp_execution_subject_valid(provider_value,subject_kind_value,subject_id_value),false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid reference completion';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),o,w,e,actor_value,'completeIntegrationReferenceAuthorization',key_value),0));
 replay:=public.zasp_reference_authorization_exact_replay(o,w,e,actor_value,id_value,key_value,intent_value);
 IF (replay->>'found')::boolean THEN
  PERFORM zasp_authorization80.require_integration_reference(o,w,e,actor_value,id_value);
  RETURN replay->'result';
 END IF;
 SELECT * INTO STRICT workflow_row FROM public.zasp_workflow_records WHERE(organization_id,workspace_id,environment_id,kind,id)=(o,w,e,'integration',id_value) AND deleted_at IS NULL FOR UPDATE;
 SELECT * INTO STRICT typed_row FROM public.zasp_integrations WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,id_value) AND deleted_at IS NULL FOR UPDATE;
 SELECT * INTO connection_row FROM public.zasp_integration_connections WHERE(organization_id,workspace_id,environment_id,integration_id,provider)=(o,w,e,id_value,provider_value) FOR UPDATE;
 PERFORM zasp_authorization80.require_integration_reference(o,w,e,actor_value,id_value);
 IF workflow_row.version<>expected_version OR typed_row.version=9223372036854775807 OR connection_row.version=9223372036854775807
 THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='reference version conflict';END IF;
 next_typed:=GREATEST(typed_row.version+1,expected_version+1);
 next_connection:=CASE WHEN connection_row.id IS NULL THEN expected_version+1 ELSE GREATEST(connection_row.version+1,expected_version+1) END;
 revision_delta:=CASE WHEN connection_row.id IS NULL THEN 2 WHEN typed_row.state='degraded' AND connection_row.state='verified' THEN 4 ELSE 3 END;
 result:=zasp_authorization80.integration_reference_execution_complete(o,w,e,actor_value,id_value,provider_value,connection_value,reference_value,key_value,expected_version,configuration_value,intent_value,audit_value,correlation_value,receipt_value,subject_kind_value,subject_id_value);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization79.organizations x WHERE x.organization_id=o AND x.desired=(p#>>'{revision,desired}')::bigint+revision_delta AND x.applied=(p#>>'{revision,applied}')::bigint AND x.generation=(p#>>'{revision,generation}')::bigint AND x.store_id=p#>>'{revision,store_id}' AND x.model_id=p#>>'{revision,model_id}')
 OR NOT EXISTS(SELECT 1 FROM public.zasp_integrations i WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id,i.version,i.state,i.configuration)=(o,w,e,id_value,next_typed,'active',configuration_value))
 OR NOT EXISTS(SELECT 1 FROM public.zasp_workflow_records r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.kind,r.id,r.version,r.body)=(o,w,e,'integration',id_value,expected_version+1,result->'body'))
 OR NOT EXISTS(SELECT 1 FROM public.zasp_integration_connections c JOIN public.zasp_discovery_connection_subjects s ON(s.organization_id,s.workspace_id,s.environment_id,s.integration_id,s.connection_id)=(c.organization_id,c.workspace_id,c.environment_id,c.integration_id,c.id)
  WHERE(c.organization_id,c.workspace_id,c.environment_id,c.integration_id,c.id,c.provider,c.connection_reference,c.version,c.state)=(o,w,e,id_value,connection_value,provider_value,reference_value,next_connection,'verified')
  AND(s.provider,s.subject_kind,s.subject_id,s.connection_version,s.configuration_digest,s.source)=(provider_value,subject_kind_value,subject_id_value,next_connection,public.digest(convert_to(configuration_value::text,'UTF8'),'sha256'),'reference'))
 OR result->>'audit_id' IS DISTINCT FROM audit_value OR result->>'correlation_id' IS DISTINCT FROM correlation_value OR result->>'receipt_id' IS DISTINCT FROM receipt_value OR(result->>'version')::bigint IS DISTINCT FROM expected_version+1
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='reference mutation accounting changed';END IF;
 PERFORM zasp_authorization80.integration_reference_finish(p);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_reference_execution_complete(organization_value text, workspace_value text, environment_value text, principal_value text, integration_value text, provider_value text, connection_value text, reference_value text, idempotency_value text, expected_version_value bigint, configuration_value jsonb, intent_value jsonb, audit_value text, correlation_value text, receipt_value text, subject_kind_value text, subject_id_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;connection_version_value bigint;replay_value jsonb;typed_version_value bigint;old_connection_version bigint;
BEGIN
 SELECT version INTO STRICT typed_version_value FROM public.zasp_integrations WHERE (organization_id,workspace_id,environment_id,id)=(organization_value,workspace_value,environment_value,integration_value) FOR UPDATE;
 SELECT version INTO old_connection_version FROM public.zasp_integration_connections WHERE (organization_id,workspace_id,environment_id,integration_id,provider)=(organization_value,workspace_value,environment_value,integration_value,provider_value) FOR UPDATE;
 replay_value:=zasp_workflow_replay(organization_value,workspace_value,environment_value,principal_value,'completeIntegrationReferenceAuthorization',idempotency_value,intent_value);
 IF (replay_value->>'found')::boolean THEN RETURN replay_value->'result';END IF;
 DELETE FROM zasp_discovery_connection_subjects subject
  WHERE (subject.organization_id,subject.workspace_id,subject.environment_id,subject.integration_id,subject.connection_id,subject.provider)=(organization_value,workspace_value,environment_value,integration_value,connection_value,provider_value)
    AND EXISTS(SELECT 1 FROM zasp_integrations integration JOIN zasp_integration_connections connection ON (connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,connection.id,connection.provider,connection.state)=(integration.organization_id,integration.workspace_id,integration.environment_id,integration.id,connection_value,provider_value,'verified') WHERE (integration.organization_id,integration.workspace_id,integration.environment_id,integration.id,integration.kind,integration.version,integration.state)=(organization_value,workspace_value,environment_value,integration_value,provider_value,typed_version_value,'degraded'));
 UPDATE zasp_integration_connections connection SET state='pending',verified_at=NULL,updated_at=transaction_timestamp()
  WHERE (connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,connection.id,connection.provider)=(organization_value,workspace_value,environment_value,integration_value,connection_value,provider_value)
    AND connection.state='verified' AND connection.version=old_connection_version
    AND EXISTS(SELECT 1 FROM zasp_integrations integration WHERE (integration.organization_id,integration.workspace_id,integration.environment_id,integration.id,integration.kind,integration.version,integration.state)=(organization_value,workspace_value,environment_value,integration_value,provider_value,typed_version_value,'degraded'))
    AND NOT EXISTS(SELECT 1 FROM zasp_discovery_connection_subjects subject WHERE (subject.organization_id,subject.workspace_id,subject.environment_id,subject.integration_id,subject.connection_id)=(organization_value,workspace_value,environment_value,integration_value,connection_value));
 result_value:=zasp_authorization80.integration_reference_native_complete(organization_value,workspace_value,environment_value,principal_value,integration_value,provider_value,connection_value,reference_value,idempotency_value,expected_version_value,configuration_value,intent_value,audit_value,correlation_value,receipt_value);
 SELECT connection.version INTO STRICT connection_version_value FROM zasp_integration_connections connection
  WHERE (connection.organization_id,connection.workspace_id,connection.environment_id,connection.integration_id,connection.id,connection.provider)=(organization_value,workspace_value,environment_value,integration_value,connection_value,provider_value);
 PERFORM zasp_execution_bind_connection_subject(organization_value,workspace_value,environment_value,integration_value,connection_value,provider_value,subject_kind_value,subject_id_value,connection_version_value,configuration_value,'reference');
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_reference_native_complete(organization_value text, workspace_value text, environment_value text, principal_value text, integration_value text, provider_value text, connection_value text, reference_value text, idempotency_value text, expected_version_value bigint, configuration_value jsonb, intent_value jsonb, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE workflow_row zasp_workflow_records%ROWTYPE; integration_row zasp_integrations%ROWTYPE;
  connection_row zasp_integration_connections%ROWTYPE; desired_body jsonb; result_value jsonb; replay_value jsonb;
  expected_intent jsonb;
BEGIN
  IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value)
    OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(principal_value)
    OR NOT zasp_valid_product_id(integration_value) OR NOT zasp_valid_product_id(connection_value)
    OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR NOT zasp_valid_product_id(receipt_value)
    OR expected_version_value NOT BETWEEN 1 AND 1000000 OR length(idempotency_value) NOT BETWEEN 16 AND 128
    OR provider_value NOT IN('aws','kubernetes')
    OR NOT zasp_reference_authorization_configuration_valid(provider_value,configuration_value)
    OR reference_value<>(CASE provider_value WHEN 'aws' THEN configuration_value->>'external_id_reference' ELSE configuration_value->>'connection_reference' END) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid reference authorization completion';
  END IF;
  expected_intent:=jsonb_build_object(
    'configuration',configuration_value,'expected_version',expected_version_value,'idempotency_key',idempotency_value,
    'integration_id',integration_value,'provider',provider_value,
    'scope',jsonb_build_object('environment_id',environment_value,'organization_id',organization_value,'workspace_id',workspace_value));
  IF intent_value<>expected_intent THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid reference authorization intent'; END IF;
  replay_value:=zasp_reference_authorization_exact_replay(organization_value,workspace_value,environment_value,principal_value,integration_value,idempotency_value,intent_value);
  IF (replay_value->>'found')::boolean THEN RETURN replay_value->'result'; END IF;

  SELECT * INTO workflow_row FROM zasp_workflow_records
   WHERE organization_id=organization_value AND workspace_id=workspace_value AND environment_id=environment_value
     AND kind='integration' AND id=integration_value AND deleted_at IS NULL FOR UPDATE;
  SELECT * INTO integration_row FROM zasp_integrations
   WHERE organization_id=organization_value AND workspace_id=workspace_value AND environment_id=environment_value
     AND id=integration_value FOR UPDATE;
  replay_value:=zasp_reference_authorization_exact_replay(organization_value,workspace_value,environment_value,principal_value,integration_value,idempotency_value,intent_value);
  IF (replay_value->>'found')::boolean THEN RETURN replay_value->'result'; END IF;
  IF workflow_row.id IS NULL OR integration_row.id IS NULL OR workflow_row.version<>expected_version_value
    OR workflow_row.body->>'connector_key'<>provider_value
    OR workflow_row.body->'configuration'<>configuration_value OR integration_row.kind<>provider_value
    OR integration_row.configuration<>configuration_value OR workflow_row.body->>'status' NOT IN('configured','pending_authorization','degraded')
    OR integration_row.state NOT IN('pending','authorizing','degraded') THEN
    RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='reference authorization intent changed';
  END IF;
  desired_body:=jsonb_set(
    jsonb_set(workflow_row.body,'{status}','"active"'::jsonb),
    '{updated_at}',
    to_jsonb(to_char(transaction_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
  result_value:=zasp_authorization80.integration_connector_mutate(
    'update','integration',integration_value,organization_value,workspace_value,environment_value,principal_value,
    'completeIntegrationReferenceAuthorization',idempotency_value,expected_version_value,intent_value,desired_body,
    audit_value,correlation_value,receipt_value);
  UPDATE zasp_integrations SET state='active',version=GREATEST(integration_row.version+1,(result_value->>'version')::bigint),updated_at=transaction_timestamp(),deleted_at=NULL
   WHERE organization_id=organization_value AND workspace_id=workspace_value AND environment_id=environment_value AND id=integration_value
     AND version=GREATEST(integration_row.version+1,(result_value->>'version')::bigint) AND state IN('pending','authorizing','degraded') RETURNING * INTO integration_row;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='typed reference authorization conflict'; END IF;
  INSERT INTO zasp_integration_connections(organization_id,workspace_id,environment_id,id,integration_id,provider,connection_reference,state,version,verified_at)
  VALUES(organization_value,workspace_value,environment_value,connection_value,integration_value,provider_value,reference_value,'verified',(result_value->>'version')::bigint,transaction_timestamp())
  ON CONFLICT(organization_id,workspace_id,environment_id,integration_id,provider) DO UPDATE
    SET state='verified',version=GREATEST(zasp_integration_connections.version+1,EXCLUDED.version),verified_at=COALESCE(zasp_integration_connections.verified_at,transaction_timestamp()),revoked_at=NULL,updated_at=transaction_timestamp()
    WHERE zasp_integration_connections.id=EXCLUDED.id AND zasp_integration_connections.connection_reference=EXCLUDED.connection_reference
      AND zasp_integration_connections.state IN('pending','invalid') RETURNING * INTO connection_row;
  IF NOT FOUND OR connection_row.id<>connection_value OR connection_row.version<(result_value->>'version')::bigint THEN
    RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='reference connection conflict';
  END IF;
  RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_reference_replay(o text, w text, e text, actor_value text, id_value text, key_value text, expected_version bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;result jsonb;
BEGIN
 p:=zasp_authorization80.require_integration_reference(o,w,e,actor_value,id_value);
 IF NOT COALESCE(key_value~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' AND expected_version BETWEEN 1 AND 1000000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid reference replay';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),o,w,e,actor_value,'completeIntegrationReferenceAuthorization',key_value),0));
 result:=public.zasp_reference_authorization_replay(o,w,e,actor_value,id_value,key_value,expected_version);
 PERFORM zasp_authorization80.require_integration_reference(o,w,e,actor_value,id_value);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_reference_value(o text, w text, e text, id_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;result jsonb;
BEGIN
 p:=zasp_authorization80.context();
 p:=zasp_authorization80.require_integration_reference(o,w,e,p->>'principal_id',id_value);
 SELECT jsonb_build_object('body',r.body,'version',r.version,'secret_generation',r.secret_generation) INTO STRICT result FROM public.zasp_workflow_records r
 WHERE(r.organization_id,r.workspace_id,r.environment_id,r.kind,r.id)=(o,w,e,'integration',id_value) AND r.deleted_at IS NULL FOR SHARE;
 PERFORM zasp_authorization80.integration_reference_finish(p);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_rejection(o text, w text, e text, actor_value text, credential_value bytea, operation_value text, target_value text, audit_value text, correlation_value text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;
BEGIN
 p:=zasp_authorization80.require_integration_operation(o,w,e,actor_value,operation_value,target_value);
 IF credential_value IS DISTINCT FROM decode(p->>'credential_digest','hex')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='integration rejection authorization denied';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value),false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration rejection identifiers rejected';END IF;
 INSERT INTO public.zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata,occurred_at)
 VALUES(o,w,e,audit_value,actor_value,'integration.setup.rejected',target_value,'rejected',jsonb_build_object('operation',operation_value,'resource_kind','integration','reason','invalid_configuration','correlation_id',correlation_value),clock_timestamp());
 -- Native callers cannot skip post-wait classification by omitting the Go
 -- transaction's final fence. Any failure aborts this entire SQL statement.
 PERFORM zasp_authorization80.integration_rejection_classify(p);
 PERFORM zasp_authorization80.identity_fence(p);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_rejection_classify(p jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE credential jsonb;kind_value integer;target_value text;
BEGIN
 -- Every public entry reaches this check, even if its private proof context
 -- was installed through the shared fence. Post-wait source reads need a new
 -- READ COMMITTED snapshot; the Go transaction check alone is insufficient.
 IF current_setting('transaction_isolation')<>'read committed'
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='integration rejection isolation unavailable';END IF;
 IF NOT COALESCE(zasp_authorization80.source_ready(56,'f5871c564709034eaf89f325fcb732a3f3314ecc0ff95f7a0ec99f6d674ddfc1','8534cdcdce945aab8f85dce88d9bf8a01b100387490a7cefe5d51f2ae11d8ced')
  AND public.zasp_discovery_principal_ready('zasp_discovery_api'),false)
 THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='integration rejection source unavailable';END IF;
 IF NOT COALESCE(p->>'operation_id' IN('createIntegration','updateIntegration') AND p->>'permission'='manage_workflows'
  AND p->>'credential_kind' IN('1','2') AND NOT(p->>'collection')::boolean,false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='integration rejection authorization denied';END IF;
 target_value:=CASE p->>'operation_id' WHEN 'createIntegration' THEN p->>'environment_id' ELSE p#>>'{path_parameters,id}' END;
 IF NOT COALESCE(public.zasp_valid_product_id(target_value) AND EXISTS(SELECT 1 FROM jsonb_array_elements(p->'allowed') a
  WHERE(a->>'organization_id',a->>'workspace_id',a->>'environment_id',a->>'kind',a->>'id')=
  (p->>'organization_id',p->>'workspace_id',p->>'environment_id',CASE p->>'operation_id' WHEN 'createIntegration' THEN 'environment' ELSE 'integration' END,target_value)),false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='integration rejection authorization denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM public.zasp_identity_memberships m WHERE(m.organization_id,m.principal_id)=(p->>'organization_id',p->>'principal_id') AND m.active)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='integration rejection authorization denied';END IF;
 kind_value:=(p->>'credential_kind')::integer;
 IF kind_value=1 THEN
  SELECT to_jsonb(s) INTO credential FROM public.zasp_product_sessions s WHERE s.token_digest=decode(p->>'credential_digest','hex') AND s.session_id=p->>'credential_id';
 ELSE
  SELECT to_jsonb(s) INTO credential FROM public.zasp_product_api_tokens s WHERE s.token_digest=decode(p->>'credential_digest','hex') AND s.id=p->>'credential_id';
 END IF;
 IF credential IS NULL OR credential->>'revoked_at' IS NOT NULL
  OR(credential->>'principal_id',credential->>'organization_id',credential->>'workspace_id',credential->>'environment_id') IS DISTINCT FROM(p->>'principal_id',p->>'organization_id',p->>'workspace_id',p->>'environment_id')
 THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='integration rejection credential unavailable';END IF;
 -- These predicates can only deny. PAT permissions are a credential ceiling;
 -- effective-scope existence is not a replacement for the signed FGA decision.
 IF(kind_value=2 AND(NOT credential->'permissions' ? 'manage_workflows' OR credential->'permissions' IS DISTINCT FROM p->'pat_ceiling'))
  OR(kind_value=1 AND encode(public.digest(credential->>'csrf_token','sha256'),'hex') IS DISTINCT FROM p->>'csrf_digest')
  OR NOT EXISTS(SELECT 1 FROM public.zasp_identity_admin_effective_scopes(p->>'principal_id',p->>'organization_id') s WHERE(s.workspace_id,s.environment_id)=(p->>'workspace_id',p->>'environment_id'))
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='integration rejection authorization denied';END IF;
 IF p->>'operation_id'='updateIntegration' AND NOT EXISTS(
  SELECT 1 FROM public.zasp_integrations i JOIN public.zasp_workflow_records r
  ON(r.organization_id,r.workspace_id,r.environment_id,r.id,r.kind)=(i.organization_id,i.workspace_id,i.environment_id,i.id,'integration')
  WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(p->>'organization_id',p->>'workspace_id',p->>'environment_id',target_value)
  AND i.deleted_at IS NULL AND i.state<>'deleted' AND r.deleted_at IS NULL)
 THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration rejection target unavailable';END IF;
 IF (credential->>'expires_at')::timestamptz<=clock_timestamp()
 THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='integration rejection credential unavailable';END IF;
 IF NOT COALESCE((p->>'expires_at')::bigint>floor(extract(epoch FROM clock_timestamp())*1000)::bigint,false)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='integration rejection proof expired';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_rejection_fence(envelope text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;
BEGIN
 p:=zasp_authorization80.verify_attestation(envelope);
 PERFORM zasp_authorization80.integration_rejection_classify(p);
 BEGIN
  PERFORM zasp_authorization80.fence(envelope);
 EXCEPTION WHEN serialization_failure THEN
  -- A lock wait can change the deny reason. This branch always raises: it
  -- never continues a failed fence into an audit write or a commit.
  PERFORM zasp_authorization80.integration_rejection_classify(p);
  RAISE;
 END;
 -- Shared fencing checks credentials before target locks. Recheck the wall
 -- clock after those waits while retaining all acquired authority locks.
 PERFORM zasp_authorization80.integration_rejection_classify(p);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_replay(o text, w text, e text, actor_value text, operation_value text, key_value text, intent_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;target_value text;prior_digest bytea;prior_response jsonb;
BEGIN
 p:=zasp_authorization80.context();
 target_value:=CASE operation_value WHEN 'createIntegration' THEN e ELSE p#>>'{path_parameters,id}' END;
 PERFORM zasp_authorization80.require_integration_operation(o,w,e,actor_value,operation_value,target_value);
 IF NOT COALESCE(length(key_value) BETWEEN 16 AND 128 AND key_value~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$'
  AND jsonb_typeof(intent_value)='object'
  AND jsonb_typeof(intent_value->'body')='object'
  AND intent_value->>'resource_id'=CASE operation_value WHEN 'createIntegration' THEN '' ELSE target_value END,false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='integration replay request rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),o,w,e,actor_value,operation_value,key_value),0));
 PERFORM zasp_authorization80.integration_rejection_classify(p);
 SELECT request_digest,response INTO prior_digest,prior_response FROM public.zasp_workflow_idempotency
 WHERE(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor_value,operation_value,key_value);
 IF NOT FOUND THEN RETURN jsonb_build_object('found',false);END IF;
 IF prior_digest<>public.digest(convert_to(intent_value::text,'UTF8'),'sha256')
 THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='idempotency conflict';END IF;
 RETURN jsonb_build_object('found',true,'result',prior_response||jsonb_build_object('replayed',true));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_setup_valid(k text, c jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE keys text[];value text;url text;host text;path text;
BEGIN
 IF jsonb_typeof(c) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 IF EXISTS(SELECT 1 FROM jsonb_each(c) x WHERE jsonb_typeof(x.value)<>'string' OR octet_length(x.value#>>'{}') NOT BETWEEN 1 AND 2048 OR x.value#>>'{}'<>btrim(x.value#>>'{}',E' \t\r\n\v\f') OR x.value#>>'{}'~E'[\r\n]') THEN RETURN false;END IF;
 SELECT array_agg(key ORDER BY key) INTO keys FROM jsonb_object_keys(c) key;
 CASE k
 WHEN 'github' THEN RETURN keys=ARRAY['authorization_mode'] AND c->>'authorization_mode'='github_app';
 WHEN 'aws' THEN RETURN keys=ARRAY['external_id_reference','region','role_arn']
  AND c->>'role_arn'~'^arn:aws:iam::[0-9]{12}:role/[A-Za-z0-9+=,.@_/-]+$' AND length(split_part(c->>'role_arn',':role/',2)) BETWEEN 1 AND 512
  AND octet_length(c->>'external_id_reference') BETWEEN 12 AND 512 AND c->>'external_id_reference'~'^ref:[a-z0-9_./:-]+$'
  AND c->>'region'~'^[a-z]{2}(-gov)?-[a-z]+-[0-9]$';
 WHEN 'kubernetes' THEN RETURN keys=ARRAY['connection_reference'] AND octet_length(c->>'connection_reference') BETWEEN 12 AND 512 AND c->>'connection_reference'~'^ref:[a-z0-9_./:-]+$';
 WHEN 'okta' THEN RETURN keys=ARRAY['issuer'] AND c->>'issuer'~'^https://[a-z0-9][a-z0-9-]{1,61}[a-z0-9]\.okta\.com$';
 WHEN 'slack' THEN RETURN keys=ARRAY['workspace_label'] AND octet_length(c->>'workspace_label')<=128;
 WHEN 'generic-webhook' THEN
  IF keys IS DISTINCT FROM ARRAY['destination_url','signing_secret_reference'] AND keys IS DISTINCT FROM ARRAY['destination_url','signing_secret_reference','signing_secret_version'] THEN RETURN false;END IF;
  IF c ? 'signing_secret_version' AND c->>'signing_secret_version'!~'^[A-Za-z0-9-]{32,64}$' THEN RETURN false;END IF;
  IF left(c->>'signing_secret_reference',11)<>'secret_ref_' OR octet_length(c->>'signing_secret_reference')>128 THEN RETURN false;END IF;
  url:=c->>'destination_url';
  IF url!~'^https://[^/?#@[:space:]]+(/[^?#[:space:]]*)?$' THEN RETURN false;END IF;
  host:=lower(split_part(substr(url,9),'/',1));
  IF host~'[[:cntrl:]|{}^`\\]' OR strpos(regexp_replace(host,'%(25|[89A-Fa-f][0-9A-Fa-f])','','g'),'%')>0 OR (strpos(host,':')>0 AND host!~'^[^:]+:[0-9]*$')
   OR strpos(regexp_replace(url,'%[0-9A-Fa-f]{2}','','g'),'%')>0 THEN RETURN false;END IF;
  -- Literal IP destinations and local hostnames never carry outbound authority.
  IF host~'^\[' OR host~'^[0-9.]+(:[0-9]+)?$' THEN RETURN false;END IF;
  host:=split_part(host,':',1);
  IF host='' OR host='localhost' OR host~'\.(localhost|local|internal)$' THEN RETURN false;END IF;
  path:=substr(url,9+length(split_part(substr(url,9),'/',1)));
  IF path LIKE '%\%%' AND path LIKE '%..%' THEN RETURN false;END IF;
  RETURN true;
 ELSE RETURN false;END CASE;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_typed_configuration(k text, c jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF k='generic-webhook' THEN
  IF NOT COALESCE(zasp_authorization80.integration_setup_valid(k,c),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid typed webhook configuration';END IF;
  RETURN c-'signing_secret_version';
 END IF;
 RETURN c;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_update_value(o text, w text, e text, id_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;result jsonb;
BEGIN
 p:=zasp_authorization80.context();
 PERFORM zasp_authorization80.require_integration_operation(o,w,e,p->>'principal_id','updateIntegration',id_value);
 SELECT jsonb_build_object('body',r.body,'version',r.version,'secret_generation',r.secret_generation) INTO result
 FROM public.zasp_workflow_records r JOIN public.zasp_integrations i
 ON(i.organization_id,i.workspace_id,i.environment_id,i.id)=(r.organization_id,r.workspace_id,r.environment_id,r.id)
 WHERE(r.organization_id,r.workspace_id,r.environment_id,r.kind,r.id)=(o,w,e,'integration',id_value)
 AND r.deleted_at IS NULL AND i.deleted_at IS NULL AND i.state<>'deleted' FOR SHARE OF r,i;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration rejection target unavailable';END IF;
 PERFORM zasp_authorization80.integration_rejection_classify(p);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.integration_value(o text, w text, e text, id_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;result jsonb;typed_version bigint;
BEGIN
 PERFORM zasp_authorization80.integration_current_ready();
 p:=zasp_authorization80.context();
 IF NOT COALESCE(zasp_authorization80.read_request(o,w,e,ARRAY['getIntegration'],'view') AND NOT(p->>'collection')::boolean AND p#>>'{path_parameters,id}'=id_value AND zasp_authorization80.allowed(o,w,e,'integration',id_value),false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='integration read denied';END IF;
 SELECT jsonb_build_object('body',r.body,'version',r.version,'secret_generation',r.secret_generation),i.version INTO result,typed_version FROM public.zasp_workflow_records r JOIN public.zasp_integrations i
 ON(i.organization_id,i.workspace_id,i.environment_id,i.id)=(r.organization_id,r.workspace_id,r.environment_id,r.id)
 WHERE(r.organization_id,r.workspace_id,r.environment_id,r.kind,r.id)=(o,w,e,'integration',id_value) AND r.deleted_at IS NULL AND i.deleted_at IS NULL AND i.state<>'deleted' FOR SHARE OF r,i;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='integration unavailable';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'targets') t WHERE(t->>'kind',t->>'id',(t->>'version')::bigint)=('integration',id_value,typed_version)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='integration target changed';END IF;
 PERFORM zasp_authorization79.revalidate(o,(p#>>'{revision,desired}')::bigint,(p#>>'{revision,generation}')::bigint,p#>>'{revision,store_id}',p#>>'{revision,model_id}');
 PERFORM zasp_authorization80.identity_fence(p);
 PERFORM zasp_authorization80.integration_current_ready();
 IF zasp_authorization80.context() IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='integration proof expired';END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.inventory_page(o text, w text, e text, k text, a text, n integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 PERFORM zasp_authorization80.require_read(o,w,e,ARRAY[CASE k WHEN 'agent' THEN 'listAgents' WHEN 'tool' THEN 'listTools' WHEN 'identity' THEN 'listIdentities' WHEN 'runtime' THEN 'listRuntimes' WHEN 'asset' THEN 'listAssets' END],'view');
 IF n NOT BETWEEN 1 AND 100 OR k NOT IN('asset','agent','tool','identity','runtime') OR public.zasp_inventory_scope_state(o,w,e)->>'phase' IS DISTINCT FROM 'cutover' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='authorization inventory page rejected';END IF;
 WITH candidates AS(SELECT id FROM public.zasp_inventory_entities v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.state,v.product_kind)=(o,w,e,'active',k) AND(a IS NULL OR id>a) AND zasp_authorization80.allowed(o,w,e,k,id) ORDER BY id LIMIT n+1),visible AS(SELECT id FROM candidates ORDER BY id LIMIT n)
 SELECT jsonb_build_object('items',COALESCE((SELECT jsonb_agg(public.zasp_inventory_detail(o,w,e,id,k)->'summary' ORDER BY id) FROM visible),'[]'::jsonb),'next_id',CASE WHEN(SELECT count(*) FROM candidates)>n THEN(SELECT max(id) FROM visible) END) INTO result;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.parent_allowed(o text, w text, e text, k text, i text, selector text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE targets jsonb;target jsonb;
BEGIN
 targets:=zasp_authorization80.parent_targets(o,w,e,k,i,selector);
 IF jsonb_array_length(targets)=0 THEN RETURN false;END IF;
 FOR target IN SELECT value FROM jsonb_array_elements(targets) LOOP
  IF NOT zasp_authorization80.allowed(target->>'organization_id',target->>'workspace_id',target->>'environment_id',target->>'kind',COALESCE(NULLIF(target->>'source_id',''),target->>'id')) THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.parent_targets(o text, w text, e text, k text, i text, selector text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE row_value jsonb;parent_kind text;parent_id text;result jsonb;part jsonb;scope_value record;
BEGIN
 IF i IS NULL THEN
  result:='[]'::jsonb;
  FOR scope_value IN SELECT workspace_id,id FROM public.zasp_environments WHERE organization_id=o AND(k='audit_event' OR(workspace_id,id)=(w,e)) ORDER BY workspace_id,id LOOP
   result:=result||zasp_authorization80.resolve(o,scope_value.workspace_id,scope_value.id,'*',NULL);
   IF jsonb_array_length(result)>10000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='authorization candidates exceed bound';END IF;
  END LOOP;
  RETURN result;
 END IF;
 IF k='workflow_receipt' THEN
  SELECT to_jsonb(r) INTO row_value FROM public.zasp_workflow_receipts r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.receipt_id)=(o,w,e,i);
  parent_kind:=row_value->>'resource_kind';parent_id:=row_value->>'resource_id';
 ELSIF k='security_agent_audit' THEN
  SELECT to_jsonb(r) INTO row_value FROM public.zasp_security_agent_audit r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.audit_id)=(o,w,e,i);
  parent_kind:='security_agent_run';parent_id:=row_value->>'run_id';
 ELSIF k IN('audit_export','compliance_export') THEN
  SELECT v INTO row_value FROM zasp_authorization80.source_rows(o,w,e,k,i) v;
  parent_kind:='environment';parent_id:=row_value->>'environment_id';
 ELSIF k='audit_event' THEN
  SELECT to_jsonb(s) INTO row_value FROM public.zasp_audit_export_public_source_v1 s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.id)=(o,w,e,i) AND(selector IS NULL OR s.source_kind=selector);
  parent_id:=row_value->>'target_id';
  CASE row_value->>'source_kind'
   WHEN 'workflow_policy' THEN parent_kind:='policy';
   WHEN 'red_team_mutation' THEN parent_kind:=CASE WHEN row_value->>'action' IN('test.create','test.update') THEN 'test' WHEN row_value->>'action' IN('test.run.queued','test.run.cancel_requested') THEN 'test_run' END;
   WHEN 'administration' THEN
    CASE row_value->>'action'
     WHEN 'sensor.create','sensor.update','sensor.delete','sensor.token.rotate' THEN
      -- Administration events have an explicit receipt-recorded environment
      -- authority. This policy is stable after sensor deletion; it neither
      -- preserves sensor grants nor falls back from a failed sensor Check.
      IF row_value->>'outcome' IS DISTINCT FROM 'succeeded' OR NOT EXISTS(
       SELECT 1 FROM public.zasp_runtime_sensor_mutations m
       WHERE(m.organization_id,m.workspace_id,m.environment_id,m.principal_id,m.sensor_id,m.created_at)=
        (o,w,e,row_value->>'actor_id',parent_id,(row_value->>'occurred_at')::timestamptz)
       AND m.operation=CASE row_value->>'action' WHEN 'sensor.create' THEN 'createSensorEnrollment' WHEN 'sensor.update' THEN 'updateSensor' WHEN 'sensor.delete' THEN 'deleteSensor' WHEN 'sensor.token.rotate' THEN 'rotateSensorToken' END
       AND i=public.zasp_discovery_canonical_id(o,w,e,'sensor_mutation_audit',jsonb_build_array(m.principal_id,m.operation,m.idempotency_key)::text)
       AND m.result#>>'{body,id}'=parent_id
       AND row_value->'metadata'=jsonb_build_object('sensor_version',m.result#>'{body,version}')
       AND jsonb_typeof(m.result#>'{body,version}')='number'
       AND(m.operation<>'deleteSensor' OR m.result#>>'{body,state}'='deleted')
      ) THEN RETURN '[]'::jsonb;END IF;
      parent_kind:='environment';parent_id:=e;
     WHEN 'data_controls.update' THEN parent_kind:='environment';
     WHEN 'environment.create' THEN parent_kind:='environment';
     WHEN 'environment.update' THEN parent_kind:='environment';
     WHEN 'workspace.update' THEN parent_kind:='workspace';
     WHEN 'workspace.onboard' THEN parent_kind:='workspace';
     WHEN 'session.revoke' THEN parent_kind:='product_session';parent_id:=row_value->'metadata'->>'session_id';
     -- These control-plane events have an explicit recorded environment scope.
     -- This is that scope's view_audit check, never organization member authority.
     WHEN 'api_token.create','api_token.rotate','api_token.revoke','api_token.reveal.acknowledge','group_mapping.update','member.role.update','identity.member.deprovision','identity_provider.createSSOConnection','identity_provider.deleteSSOConnection','identity_provider.testSSOConnection','identity_provider.createSCIMConnection','identity_provider.deleteSCIMConnection' THEN parent_kind:='environment';parent_id:=e;
     ELSE RETURN '[]'::jsonb;
    END CASE;
   ELSE RETURN '[]'::jsonb;
  END CASE;
 ELSIF k='compliance_evidence' THEN
  SELECT to_jsonb(s) INTO row_value FROM public.zasp_compliance_sources(o,w,e) s WHERE(s.source_kind,s.source_id)=(selector,i);
  IF selector IN('administration','workflow_policy','red_team_mutation') THEN RETURN zasp_authorization80.parent_targets(o,w,e,'audit_event',i,selector);END IF;
  parent_id:=i;
  CASE selector
   WHEN 'finding' THEN parent_kind:='finding';
   WHEN 'policy' THEN parent_kind:='policy';
   WHEN 'configuration' THEN parent_kind:='environment';
   WHEN 'red_team_test','attack_lab_test' THEN
    parent_kind:=CASE selector WHEN 'red_team_test' THEN 'test_run' ELSE 'attack_lab_run' END;
    result:=zasp_authorization80.resolve(o,w,e,parent_kind,i);
    part:=zasp_authorization80.resolve(o,w,e,'test',row_value->'metadata'->>'definition_id');
    IF jsonb_array_length(result)=0 OR jsonb_array_length(part)=0 THEN RETURN '[]'::jsonb;END IF;
    RETURN result||part;
   ELSE RETURN '[]'::jsonb;
  END CASE;
 ELSE RETURN '[]'::jsonb;
 END IF;
 IF row_value IS NULL OR parent_kind IS NULL OR parent_id IS NULL THEN RETURN '[]'::jsonb;END IF;
 RETURN zasp_authorization80.resolve(o,w,e,parent_kind,parent_id);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.register_verifier(v text, k bytea)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE changed boolean; org text;
BEGIN
 IF NOT zasp_authorization80.ready('d7fbda32a2b3b9ea0ffbd4f7c7a7967a9d4fba2f6573f49e8386e9586a18a1fd')
 OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_principal_bindings WHERE principal_name=session_user AND authority_role='zasp_discovery_authority')
 OR NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER')
 OR NOT COALESCE(octet_length(k)=32 AND v=encode(public.digest(k,'sha256'),'hex'),false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization verifier registration rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-authorization80-verifier',0));
 SELECT NOT EXISTS(SELECT 1 FROM zasp_authorization80.verifier WHERE version=v AND key=k) INTO changed;
 IF changed THEN
  -- Lock revisions before changing verifier material, matching current fences.
  FOR org IN SELECT id FROM public.zasp_organizations ORDER BY id LOOP PERFORM zasp_authorization79.touch(org);END LOOP;
  INSERT INTO zasp_authorization80.verifier(version,key) VALUES(v,k) ON CONFLICT(singleton) DO UPDATE SET version=EXCLUDED.version,key=EXCLUDED.key;
 END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.require_integration_operation(o text, w text, e text, actor_value text, operation_value text, target_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;
BEGIN
 p:=zasp_authorization80.context();
 IF NOT COALESCE((p->>'organization_id',p->>'workspace_id',p->>'environment_id',p->>'principal_id',p->>'operation_id')=(o,w,e,actor_value,operation_value)
  AND operation_value IN('createIntegration','updateIntegration')
  AND target_value=CASE operation_value WHEN 'createIntegration' THEN e ELSE p#>>'{path_parameters,id}' END,false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='integration rejection authorization denied';END IF;
 PERFORM zasp_authorization80.integration_rejection_classify(p);
 RETURN p;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.require_integration_reference(o text, w text, e text, actor_value text, id_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb;typed_version bigint;
BEGIN
 PERFORM zasp_authorization80.integration_current_ready();
 p:=zasp_authorization80.context();
 IF NOT COALESCE((p->>'organization_id',p->>'workspace_id',p->>'environment_id',p->>'principal_id',p->>'operation_id',p->>'permission',p->>'credential_kind')=(o,w,e,actor_value,'authorizeIntegrationReference','manage_workflows','1')
  AND (p->>'fresh_auth')::boolean AND NOT(p->>'collection')::boolean AND p#>>'{path_parameters,id}'=id_value
  AND zasp_authorization80.allowed(o,w,e,'integration',id_value),false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='reference authorization denied';END IF;
 PERFORM zasp_authorization79.revalidate(o,(p#>>'{revision,desired}')::bigint,(p#>>'{revision,generation}')::bigint,p#>>'{revision,store_id}',p#>>'{revision,model_id}');
 SELECT i.version INTO typed_version FROM public.zasp_integrations i JOIN public.zasp_workflow_records r
 ON(r.organization_id,r.workspace_id,r.environment_id,r.kind,r.id)=(i.organization_id,i.workspace_id,i.environment_id,'integration',i.id)
 WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(o,w,e,id_value) AND i.deleted_at IS NULL AND i.state<>'deleted' AND r.deleted_at IS NULL FOR SHARE OF i,r;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='reference integration unavailable';END IF;
 IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'targets') t WHERE(t->>'kind',t->>'id',(t->>'version')::bigint)=('integration',id_value,typed_version))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='reference target changed';END IF;
 PERFORM zasp_authorization80.integration_reference_finish(p);
 RETURN p;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.resolve(o text, w text, e text, k text, i text DEFAULT NULL::text, selector text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;descriptor jsonb;entry text;part jsonb;
BEGIN
 IF NOT zasp_authorization79.reader() OR NOT zasp_authorization80.ready('d7fbda32a2b3b9ea0ffbd4f7c7a7967a9d4fba2f6573f49e8386e9586a18a1fd') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization resolver rejected';END IF;
 IF k='environment' AND i IS NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.zasp_workspaces x WHERE(x.organization_id,x.id)=(o,w)) THEN RETURN '[]'::jsonb;END IF;
 ELSIF NOT EXISTS(SELECT 1 FROM public.zasp_environments x WHERE(x.organization_id,x.workspace_id,x.id)=(o,w,e)) THEN RETURN '[]'::jsonb;END IF;
 IF k IN('workflow_receipt','security_agent_audit','audit_event','audit_export','compliance_export','compliance_evidence','compliance_control') THEN RETURN zasp_authorization80.parent_targets(o,w,e,k,i,selector);END IF;
 IF k='*' THEN
  result:=zasp_authorization80.resolve(o,w,e,'environment',e);
  FOREACH entry IN ARRAY ARRAY['agent','tool','identity','runtime','asset','finding','attack_path','policy','integration','sensor','security_agent','security_agent_run','security_agent_approval','test','test_run','attack_lab_run','recovery_backup','recovery_restore','session','product_session','discovery_sync','discovery_schedule'] LOOP
   part:=zasp_authorization80.resolve(o,w,e,entry,NULL);result:=result||part;
   IF jsonb_array_length(result)>10000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='authorization candidates exceed bound';END IF;
  END LOOP;
  RETURN result;
 END IF;
 IF k IN('workspace','environment') THEN
  SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',o,'workspace_id',x.workspace_id,'environment_id',x.id,'kind',k,'id',CASE k WHEN 'workspace' THEN x.workspace_id ELSE x.id END,'version',CASE k WHEN 'workspace' THEN parent.version ELSE x.version END) ORDER BY x.workspace_id,x.id),'[]'::jsonb) INTO result
  FROM public.zasp_environments x JOIN public.zasp_workspaces parent ON(parent.organization_id,parent.id)=(x.organization_id,x.workspace_id)
  WHERE x.organization_id=o AND(k='workspace' AND(i IS NULL OR(parent.id,x.id)=(i,e)) OR k='environment' AND x.workspace_id=w AND(i IS NULL OR x.id=i));
  IF jsonb_array_length(result)>10000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='authorization candidates exceed bound';END IF;
  RETURN result;
 END IF;
 IF k IN('organization','organization_identity') THEN
  IF i IS DISTINCT FROM (CASE k WHEN 'organization' THEN o WHEN 'organization_identity' THEN o WHEN 'workspace' THEN w ELSE e END) THEN RETURN '[]'::jsonb;END IF;
  RETURN jsonb_build_array(jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'kind',k,'id',i,'version',0));
 END IF;
 descriptor:=zasp_authorization80.source(k);
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'kind',k,'id',zasp_authorization80.object_id(o,w,e,k,v->>(descriptor->>1)),'source_id',v->>(descriptor->>1),'version',COALESCE((v->>'version')::bigint,0))),'[]'::jsonb) INTO result FROM zasp_authorization80.source_rows(o,w,e,k,i) v;
 IF jsonb_array_length(result)>10000 THEN RAISE EXCEPTION USING ERRCODE='54000',MESSAGE='authorization candidates exceed bound';END IF;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(result) x WHERE NOT public.zasp_valid_product_id(x->>'id')) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='authorization resource identity unavailable';END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.risk_page(k text, o text, w text, e text, a text, n integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 PERFORM zasp_authorization80.require_read(o,w,e,ARRAY[CASE k WHEN 'finding' THEN 'listFindings' WHEN 'attack_path' THEN 'listAttackPaths' END],'view');
 IF n NOT BETWEEN 1 AND 100 OR k NOT IN('finding','attack_path') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='authorization page rejected';END IF;
 IF k='finding' THEN
  WITH candidates AS(SELECT id FROM public.zasp_risk_findings f WHERE(f.organization_id,f.workspace_id,f.environment_id)=(o,w,e) AND(a IS NULL OR id>a) AND zasp_authorization80.allowed(o,w,e,k,id) AND public.zasp_risk_finding_visible(f) ORDER BY id LIMIT n+1),visible AS(SELECT id FROM candidates ORDER BY id LIMIT n)
  SELECT jsonb_build_object('items',COALESCE((SELECT jsonb_agg(public.zasp_risk_finding_get(id,o,w,e) ORDER BY id) FROM visible),'[]'::jsonb),'next_id',CASE WHEN(SELECT count(*) FROM candidates)>n THEN(SELECT max(id) FROM visible) END) INTO result;
 ELSE
  WITH candidates AS(SELECT id FROM public.zasp_risk_attack_paths p WHERE(p.organization_id,p.workspace_id,p.environment_id)=(o,w,e) AND(a IS NULL OR id>a) AND zasp_authorization80.allowed(o,w,e,k,id) AND public.zasp_risk_attack_path_valid(p) ORDER BY id LIMIT n+1),visible AS(SELECT id FROM candidates ORDER BY id LIMIT n)
  SELECT jsonb_build_object('items',COALESCE((SELECT jsonb_agg(public.zasp_risk_attack_path_get(id,o,w,e) ORDER BY id) FROM visible),'[]'::jsonb),'next_id',CASE WHEN(SELECT count(*) FROM candidates)>n THEN(SELECT max(id) FROM visible) END) INTO result;
 END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.rotate_sensor(organization_value text, workspace_value text, environment_value text, principal_value text, sensor_value text, expected_version_value bigint, idempotency_value text, request_digest_value bytea, token_value text, generation_value bigint, locator_digest_value bytea, salt_value bytea, token_hash_value bytea, expires_value timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_value zasp_runtime_sensor_mutations%ROWTYPE;current_token_value text;result_value jsonb;
BEGIN
 IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'rotateSensorToken',sensor_value,principal_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current sensor authorization required';END IF;
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(principal_value) OR NOT zasp_valid_product_id(sensor_value) OR NOT zasp_valid_product_id(token_value) OR expected_version_value<1 OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR octet_length(request_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor mutation rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,sensor_value),0));
 SELECT * INTO prior_value FROM zasp_runtime_sensor_mutations mutation WHERE (mutation.organization_id,mutation.workspace_id,mutation.environment_id,mutation.principal_id,mutation.operation,mutation.idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,'rotateSensorToken',idempotency_value);
 IF FOUND THEN IF (prior_value.request_digest,prior_value.sensor_id,prior_value.expected_version) IS DISTINCT FROM (request_digest_value,sensor_value,expected_version_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor mutation conflict';END IF;RETURN jsonb_set(prior_value.result,'{replayed}','true'::jsonb);END IF;
 SELECT token_row.id INTO current_token_value FROM zasp_sensor_tokens token_row JOIN zasp_sensors sensor_row ON (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id,sensor_row.version)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id,expected_version_value) WHERE (token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id)=(organization_value,workspace_value,environment_value,sensor_value) AND token_row.format_version=1 AND token_row.revoked_at IS NULL ORDER BY token_row.token_generation DESC LIMIT 1;
 IF current_token_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='sensor mutation rejected';END IF;
 PERFORM zasp_runtime_rotate_sensor_token(organization_value,workspace_value,environment_value,sensor_value,current_token_value,token_value,generation_value,expected_version_value,locator_digest_value,salt_value,token_hash_value,expires_value);
 result_value:=jsonb_build_object('body',zasp_runtime_public_sensor_value(organization_value,workspace_value,environment_value,sensor_value),'token_id',token_value,'token_generation',generation_value,'token_expires_at',to_char(expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'replayed',false);
 INSERT INTO zasp_runtime_sensor_mutations(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,request_digest,sensor_id,expected_version,token_id,token_generation,result) VALUES(organization_value,workspace_value,environment_value,principal_value,'rotateSensorToken',idempotency_value,request_digest_value,sensor_value,expected_version_value,token_value,generation_value,result_value);PERFORM zasp_authorization80.sensor_audit(organization_value,workspace_value,environment_value,principal_value,'rotateSensorToken',idempotency_value,result_value);RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.runtime_audit_ready()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE selected text;result boolean;
BEGIN
 IF(SELECT count(*) FROM zasp_authorization80.runtime_profile)<>1 THEN RETURN false;END IF;
 SELECT audit_mode INTO selected FROM zasp_authorization80.runtime_profile WHERE singleton;
 IF selected='none' THEN
  RETURN to_regnamespace('zasp_authorization80_audit') IS NULL AND NOT EXISTS(SELECT 1 FROM pg_trigger WHERE tgrelid='public.zasp_admin_audit'::regclass AND tgname='zasp_authorization80_audit_write_guard');
 ELSIF selected='source52-canonical61-audit-v1' THEN
  IF to_regclass('zasp_authorization80_audit.registration') IS NULL OR to_regprocedure('zasp_authorization80_audit.catalog_ready()') IS NULL THEN RETURN false;END IF;
  EXECUTE 'SELECT zasp_authorization80_audit.catalog_ready()' INTO result;
  RETURN COALESCE(result,false);
 END IF;
 RETURN false;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.runtime_profile_ready()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE selected text;result boolean;
BEGIN
 IF(SELECT count(*) FROM zasp_authorization80.runtime_profile)<>1 THEN RETURN false;END IF;
 SELECT name INTO selected FROM zasp_authorization80.runtime_profile WHERE singleton;
 IF selected='canonical61-authorization79-80-v1' THEN
  RETURN to_regnamespace('zasp_temporal78') IS NULL AND to_regnamespace('zasp_authorization80_temporal') IS NULL;
 ELSIF selected='canonical61-temporal78-authorization79-80-v1' THEN
  IF to_regnamespace('zasp_temporal78') IS NULL OR to_regclass('zasp_authorization80_temporal.registration') IS NULL OR to_regprocedure('zasp_authorization80_temporal.catalog_ready()') IS NULL THEN RETURN false;END IF;
  -- Closed dispatch, not an identifier supplied by a caller or selector row.
  EXECUTE 'SELECT zasp_authorization80_temporal.catalog_ready()' INTO result;
  RETURN COALESCE(result,false);
 END IF;
 RETURN false;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.runtime_sandbox_query_hydrate(organization_value text, workspace_value text, environment_value text, principal_value text, ids_value text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE status_value jsonb;items_value jsonb;actual_ids text[];
BEGIN
IF NOT COALESCE(zasp_authorization80.session_source_readiness(50,(SELECT checksum FROM zasp_schema_versions WHERE version=50),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_sandbox_binding_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
 IF ids_value IS NULL OR cardinality(ids_value)>101 OR array_ndims(ids_value)>1
 OR EXISTS(SELECT 1 FROM unnest(ids_value) id WHERE id IS NULL OR (id<>'unattributed' AND NOT zasp_valid_product_id(id)))
 OR ids_value IS DISTINCT FROM ARRAY(SELECT DISTINCT id FROM unnest(ids_value) id ORDER BY id) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session candidates rejected';
 END IF;
 status_value:=zasp_authorization80.runtime_sandbox_query_status(organization_value,workspace_value,environment_value,principal_value);
 IF status_value IS NULL THEN RETURN NULL;END IF;
 SELECT COALESCE(jsonb_agg(zasp_runtime_session_summary_json(summary_value) ORDER BY id),'[]'::jsonb),COALESCE(array_agg(id ORDER BY id),'{}'::text[])
 INTO items_value,actual_ids FROM zasp_runtime_session_summaries summary_value
 WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND zasp_authorization80.allowed(organization_value,workspace_value,environment_value,'session',id) AND id=ANY(ids_value);
 IF actual_ids IS DISTINCT FROM ids_value THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime session candidates unavailable';END IF;
 RETURN jsonb_build_object('items',items_value,'search',status_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80.runtime_sandbox_query_status(organization_value text, workspace_value text, environment_value text, principal_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE pending_value bigint;quarantined_value bigint;last_indexed_value timestamptz;oldest_pending_value timestamptz;
BEGIN
IF NOT COALESCE(zasp_authorization80.session_source_readiness(50,(SELECT checksum FROM zasp_schema_versions WHERE version=50),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_sandbox_binding_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
 IF NOT zasp_authorization80.session_query_authorized(organization_value,workspace_value,environment_value,principal_value) THEN RETURN NULL;END IF;
 IF NOT COALESCE((zasp_authorization80.context()->>'environment_view')::boolean,false) THEN RETURN jsonb_build_object('visibility','resource_only');END IF;
 SELECT count(*),min(created_at) INTO pending_value,oldest_pending_value FROM (
  SELECT created_at FROM zasp_runtime_sandbox_search_outbox WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND state IN('pending','leased') ORDER BY created_at LIMIT 1001
 ) pending;
 SELECT count(*) INTO quarantined_value FROM (
  SELECT created_at FROM zasp_runtime_sandbox_search_outbox WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND state='quarantined' ORDER BY created_at LIMIT 1001
 ) quarantined;
 SELECT indexed_at INTO last_indexed_value FROM zasp_runtime_sandbox_search_outbox WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND state='indexed' ORDER BY indexed_at DESC LIMIT 1;
 RETURN jsonb_build_object('state',CASE WHEN quarantined_value>0 THEN 'blocked' WHEN pending_value>0 THEN 'catching_up' WHEN last_indexed_value IS NULL THEN 'empty' ELSE 'current' END,
 'pending_batches',least(pending_value,1000),'pending_batches_capped',pending_value>1000,'quarantined_batches',least(quarantined_value,1000),'quarantined_batches_capped',quarantined_value>1000,
 'last_indexed_at',last_indexed_value,'oldest_pending_at',oldest_pending_value,'checked_at',statement_timestamp(),'selector_coverage','observed_only');
END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80.runtime_sandbox_session_event_get(organization_value text, workspace_value text, environment_value text, principal_value text, id_value text, event_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT COALESCE(zasp_authorization80.session_source_readiness(50,(SELECT checksum FROM zasp_schema_versions WHERE version=50),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_sandbox_binding_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 IF NOT COALESCE(id_value='unattributed' OR zasp_valid_product_id(id_value),false) OR NOT COALESCE(zasp_valid_product_id(event_value),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session evidence query rejected';
 END IF;
 IF NOT (((zasp_authorization80.session_read_authorized(organization_value,workspace_value,environment_value,principal_value) AND zasp_authorization80.context()->>'operation_id'='getSessionEvent') AND zasp_authorization80.context()#>>'{path_parameters,id}'=id_value AND zasp_authorization80.allowed(organization_value,workspace_value,environment_value,'session',id_value)) AND zasp_authorization80.context()#>>'{path_parameters,eventId}'=event_value) THEN RETURN NULL;END IF;
 SELECT jsonb_build_object('id',event_id,'session_id',session_id,'agent_id',agent_id,
  'class',CASE WHEN event_class='process' THEN 'runtime' ELSE event_class END,'action',action,
  'label',title,'evidence_id',evidence_id,'source',source,'confidence',confidence,'at',event_time,'projected_at',projected_at)||jsonb_strip_nulls(jsonb_build_object('sandbox_id',sandbox_id,'sandbox_source_sensor_id',sandbox_source_sensor_id))
 INTO result_value FROM zasp_runtime_session_events
 WHERE (organization_id,workspace_id,environment_id,event_id)=(organization_value,workspace_value,environment_value,event_value)
 AND COALESCE(session_id,'unattributed')=id_value;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80.runtime_session_get(organization_value text, workspace_value text, environment_value text, principal_value text, id_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT COALESCE(id_value='unattributed' OR zasp_valid_product_id(id_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session target rejected';END IF;
 IF NOT ((zasp_authorization80.session_read_authorized(organization_value,workspace_value,environment_value,principal_value) AND zasp_authorization80.context()->>'operation_id'='getSession') AND zasp_authorization80.context()#>>'{path_parameters,id}'=id_value AND zasp_authorization80.allowed(organization_value,workspace_value,environment_value,'session',id_value)) THEN RETURN NULL;END IF;
 SELECT zasp_runtime_session_summary_json(summary_value) INTO result_value FROM zasp_runtime_session_summaries summary_value
 WHERE (organization_id,workspace_id,environment_id,id)=(organization_value,workspace_value,environment_value,id_value);
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80.runtime_session_query_hydrate(organization_value text, workspace_value text, environment_value text, principal_value text, ids_value text[])
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE status_value jsonb;items_value jsonb;actual_ids text[];
BEGIN
 IF ids_value IS NULL OR cardinality(ids_value)>101 OR array_ndims(ids_value)>1
 OR EXISTS(SELECT 1 FROM unnest(ids_value) id WHERE id IS NULL OR (id<>'unattributed' AND NOT zasp_valid_product_id(id)))
 OR ids_value IS DISTINCT FROM ARRAY(SELECT DISTINCT id FROM unnest(ids_value) id ORDER BY id) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session candidates rejected';
 END IF;
 status_value:=zasp_authorization80.runtime_session_query_status(organization_value,workspace_value,environment_value,principal_value);
 IF status_value IS NULL THEN RETURN NULL;END IF;
 SELECT COALESCE(jsonb_agg(zasp_runtime_session_summary_json(summary_value) ORDER BY id),'[]'::jsonb),COALESCE(array_agg(id ORDER BY id),'{}'::text[])
 INTO items_value,actual_ids FROM zasp_runtime_session_summaries summary_value
 WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND zasp_authorization80.allowed(organization_value,workspace_value,environment_value,'session',id) AND id=ANY(ids_value);
 IF actual_ids IS DISTINCT FROM ids_value THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime session candidates unavailable';END IF;
 RETURN jsonb_build_object('items',items_value,'search',status_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80.runtime_session_query_status(organization_value text, workspace_value text, environment_value text, principal_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE pending_value bigint;quarantined_value bigint;last_indexed_value timestamptz;oldest_pending_value timestamptz;
BEGIN
 IF NOT zasp_authorization80.session_query_authorized(organization_value,workspace_value,environment_value,principal_value) THEN RETURN NULL;END IF;
 IF NOT COALESCE((zasp_authorization80.context()->>'environment_view')::boolean,false) THEN RETURN jsonb_build_object('visibility','resource_only');END IF;
 SELECT count(*),min(created_at) INTO pending_value,oldest_pending_value FROM (
  SELECT created_at FROM zasp_runtime_session_search_outbox WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND state IN('pending','leased') ORDER BY created_at LIMIT 1001
 ) pending;
 SELECT count(*) INTO quarantined_value FROM (
  SELECT created_at FROM zasp_runtime_session_search_outbox WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND state='quarantined' ORDER BY created_at LIMIT 1001
 ) quarantined;
 SELECT indexed_at INTO last_indexed_value FROM zasp_runtime_session_search_outbox WHERE (organization_id,workspace_id,environment_id)=(organization_value,workspace_value,environment_value) AND state='indexed' ORDER BY indexed_at DESC LIMIT 1;
 RETURN jsonb_build_object('state',CASE WHEN quarantined_value>0 THEN 'blocked' WHEN pending_value>0 THEN 'catching_up' WHEN last_indexed_value IS NULL THEN 'empty' ELSE 'current' END,
 'pending_batches',least(pending_value,1000),'pending_batches_capped',pending_value>1000,'quarantined_batches',least(quarantined_value,1000),'quarantined_batches_capped',quarantined_value>1000,
 'last_indexed_at',last_indexed_value,'oldest_pending_at',oldest_pending_value,'checked_at',statement_timestamp(),'selector_coverage','observed_only');
END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80.sensor_audit(o text, w text, e text, p text, op text, key_value text, result_value jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE receipt public.zasp_runtime_sensor_mutations%ROWTYPE;audit_value text;action_value text;
BEGIN
 IF result_value->>'replayed' IS DISTINCT FROM 'false' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='sensor audit new receipt required';END IF;
 SELECT * INTO STRICT receipt FROM public.zasp_runtime_sensor_mutations WHERE(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,p,op,key_value);
 IF receipt.result IS DISTINCT FROM result_value OR receipt.sensor_id IS DISTINCT FROM result_value#>>'{body,id}' THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='sensor audit receipt mismatch';END IF;
 action_value:=CASE op WHEN 'createSensorEnrollment' THEN 'sensor.create' WHEN 'updateSensor' THEN 'sensor.update' WHEN 'deleteSensor' THEN 'sensor.delete' WHEN 'rotateSensorToken' THEN 'sensor.token.rotate' END;
 IF action_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='sensor audit operation rejected';END IF;
 audit_value:=public.zasp_discovery_canonical_id(o,w,e,'sensor_mutation_audit',jsonb_build_array(p,op,key_value)::text);
 INSERT INTO public.zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata,occurred_at)
 VALUES(o,w,e,audit_value,p,action_value,receipt.sensor_id,'succeeded',jsonb_build_object('sensor_version',(result_value#>>'{body,version}')::bigint),receipt.created_at);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.sensor_coverage(organization_value text, workspace_value text, environment_value text, sensor_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'getSensorCoverage',sensor_value,NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current sensor authorization required';END IF;
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(sensor_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor query rejected';END IF;
 SELECT jsonb_build_object('sensor_id',sensor_row.id,'supported',sensor_row.kind IN('tetragon','otlp'),'status',CASE WHEN sensor_row.state IN('revoked','deleted') THEN 'revoked' WHEN heartbeat_row.sensor_id IS NULL THEN 'pending' WHEN heartbeat_row.observed_at<transaction_timestamp()-interval '5 minutes' THEN 'offline' ELSE heartbeat_row.status END,
  'last_heartbeat',CASE WHEN heartbeat_row.observed_at IS NULL THEN NULL ELSE to_char(heartbeat_row.observed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,'kernel',COALESCE(heartbeat_row.metadata->>'kernel',''),'btf',COALESCE((heartbeat_row.metadata->>'btf')::boolean,false),'capabilities',COALESCE(heartbeat_row.metadata->'capabilities','[]'::jsonb),'event_rate',COALESCE((heartbeat_row.metadata->>'event_rate')::numeric,0),'drops',COALESCE(heartbeat_row.dropped_events,0)) INTO result_value
 FROM zasp_sensors sensor_row LEFT JOIN zasp_sensor_heartbeats heartbeat_row ON (heartbeat_row.organization_id,heartbeat_row.workspace_id,heartbeat_row.environment_id,heartbeat_row.sensor_id)=(sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id)
 WHERE (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id)=(organization_value,workspace_value,environment_value,sensor_value) AND sensor_row.state<>'deleted';
 IF result_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='sensor missing';END IF;RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.sensor_detail(organization_value text, workspace_value text, environment_value text, sensor_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'getSensor',sensor_value,NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current sensor authorization required';END IF;
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(sensor_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor query rejected';END IF;
 SELECT zasp_runtime_public_sensor_value(organization_value,workspace_value,environment_value,sensor_value) INTO result_value FROM zasp_sensors sensor_row WHERE (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id)=(organization_value,workspace_value,environment_value,sensor_value) AND sensor_row.state<>'deleted';
 IF result_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='sensor missing';END IF;RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.sensor_page(organization_value text, workspace_value text, environment_value text, after_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE items_value jsonb;next_value text;
BEGIN
 IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'listSensors',NULL,NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current sensor authorization required';END IF;
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR after_value IS NOT NULL AND NOT zasp_valid_product_id(after_value) OR limit_value NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor query rejected';END IF;
 SELECT COALESCE(jsonb_agg(zasp_runtime_public_sensor_value(organization_value,workspace_value,environment_value,item.id) ORDER BY item.id),'[]'::jsonb),CASE WHEN count(*)=limit_value THEN max(item.id) END INTO items_value,next_value
 FROM(SELECT sensor_row.id FROM zasp_sensors sensor_row WHERE (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id)=(organization_value,workspace_value,environment_value) AND sensor_row.state<>'deleted' AND zasp_authorization80.allowed(organization_value,workspace_value,environment_value,'sensor',sensor_row.id) AND (after_value IS NULL OR sensor_row.id>after_value) ORDER BY sensor_row.id LIMIT limit_value) item;
 RETURN jsonb_build_object('items',items_value,'next_id',next_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.sensor_token_authority(organization_value text, workspace_value text, environment_value text, sensor_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'rotateSensorToken',sensor_value,NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current sensor authorization required';END IF;
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(sensor_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor query rejected';END IF;
 SELECT jsonb_build_object('generation',token_row.token_generation,'sensor_version',sensor_row.version) INTO result_value
 FROM zasp_sensors sensor_row JOIN zasp_sensor_tokens token_row ON (token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id,token_row.sensor_version_at_issue)=(sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id,sensor_row.version)
 WHERE (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id)=(organization_value,workspace_value,environment_value,sensor_value) AND sensor_row.state IN('pending','active','degraded') AND token_row.format_version=1 AND token_row.revoked_at IS NULL AND token_row.expires_at>transaction_timestamp()
 ORDER BY token_row.token_generation DESC LIMIT 1;
 IF result_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='sensor missing';END IF;RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.source_rows(o text, w text, e text, k text, i text DEFAULT NULL::text, lock_rows boolean DEFAULT false)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE descriptor jsonb;query_value text;
BEGIN
 descriptor:=zasp_authorization80.source(k);
 IF descriptor IS NULL OR to_regclass('public.'||(descriptor->>0)) IS NULL THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='authorization resource source unavailable';END IF;
 query_value:=format('SELECT to_jsonb(t) FROM public.%I t WHERE to_jsonb(t)->>''organization_id''=$1 AND to_jsonb(t)->>''workspace_id''=$2 AND to_jsonb(t)->>''environment_id''=$3 AND ($4 IS NULL OR to_jsonb(t)->>%L=$4) AND to_jsonb(t)->>''deleted_at'' IS NULL',descriptor->>0,descriptor->>1);
 IF descriptor->>0='zasp_inventory_entities' THEN query_value:=query_value||' AND to_jsonb(t)->>''state''=''active'' AND to_jsonb(t)->>''product_kind''=$5';END IF;
 IF descriptor->>0='zasp_workflow_records' THEN query_value:=query_value||' AND to_jsonb(t)->>''kind''=$5';END IF;
 query_value:=query_value||format(' ORDER BY to_jsonb(t)->>%L LIMIT 10001',descriptor->>1);
 IF lock_rows THEN query_value:=query_value||' FOR SHARE OF t';END IF;
 RETURN QUERY EXECUTE query_value USING o,w,e,i,k;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.unique_json(v json, depth integer DEFAULT 0)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE child json;
BEGIN
 IF depth>32 THEN RETURN false;END IF;
 IF json_typeof(v)='object' THEN
  IF (SELECT count(*)<>count(DISTINCT key) FROM json_each(v)) THEN RETURN false;END IF;
  FOR child IN SELECT value FROM json_each(v) LOOP IF NOT zasp_authorization80.unique_json(child,depth+1) THEN RETURN false;END IF;END LOOP;
 ELSIF json_typeof(v)='array' THEN
  FOR child IN SELECT value FROM json_array_elements(v) LOOP IF NOT zasp_authorization80.unique_json(child,depth+1) THEN RETURN false;END IF;END LOOP;
 END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.update_data_controls(o text, w text, e text, mode_value text, days_value integer, deletion_value boolean, version_value bigint, class_value text, audit_value text, actor_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;
BEGIN
 IF NOT zasp_authorization80.data_controls_authorized(o,w,e,'updateDataControls',actor_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current data controls authorization required';END IF;
 IF NOT public.zasp_valid_product_id(audit_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid data controls audit identifier';END IF;
 WITH updated AS (
  UPDATE public.zasp_data_controls SET collection_mode=mode_value,retention_days=days_value,deletion_enabled=deletion_value,version=version+1,migration_seeded=false,updated_at=transaction_timestamp()
  WHERE(organization_id,workspace_id,environment_id)=(o,w,e) AND version=version_value AND environment_class=class_value RETURNING *
 ),audited AS (
  INSERT INTO public.zasp_admin_audit(organization_id,workspace_id,environment_id,id,actor_id,action,target_id,outcome,metadata)
  SELECT o,w,e,audit_value,actor_value,'data_controls.update',e,'succeeded',jsonb_build_object('collection_mode',mode_value,'retention_days',days_value::text) FROM updated
 ) SELECT jsonb_build_object('environment_id',environment_id,'environment_class',environment_class,'collection_mode',collection_mode,'retention_days',retention_days,'deletion_enabled',deletion_enabled,'version',version,'audit_correlation_id',audit_value) INTO result FROM updated;
 RETURN COALESCE(result,jsonb_build_object('_mutation_state',CASE WHEN EXISTS(SELECT 1 FROM public.zasp_data_controls WHERE(organization_id,workspace_id,environment_id)=(o,w,e)) THEN 'conflict' ELSE 'not_found' END));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.update_sensor(organization_value text, workspace_value text, environment_value text, principal_value text, sensor_value text, expected_version_value bigint, name_value text, mode_value text, idempotency_value text, request_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior_value zasp_runtime_sensor_mutations%ROWTYPE;result_value jsonb;
BEGIN
 IF NOT zasp_authorization80.sensor_authorized(organization_value,workspace_value,environment_value,'updateSensor',sensor_value,principal_value) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current sensor authorization required';END IF;
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(principal_value) OR NOT zasp_valid_product_id(sensor_value) OR expected_version_value<1 OR length(name_value) NOT BETWEEN 1 AND 128 OR name_value<>btrim(name_value) OR name_value ~ '[[:cntrl:]]' OR mode_value NOT IN('metadata_only','full') OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR octet_length(request_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='sensor mutation rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,sensor_value),0));
 SELECT * INTO prior_value FROM zasp_runtime_sensor_mutations mutation WHERE (mutation.organization_id,mutation.workspace_id,mutation.environment_id,mutation.principal_id,mutation.operation,mutation.idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,'updateSensor',idempotency_value);
 IF FOUND THEN IF (prior_value.request_digest,prior_value.sensor_id,prior_value.expected_version) IS DISTINCT FROM (request_digest_value,sensor_value,expected_version_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='sensor mutation conflict';END IF;RETURN jsonb_set(prior_value.result,'{replayed}','true'::jsonb);END IF;
 UPDATE zasp_sensors sensor_row SET name=name_value,mode=mode_value,version=sensor_row.version+1,updated_at=transaction_timestamp() WHERE (sensor_row.organization_id,sensor_row.workspace_id,sensor_row.environment_id,sensor_row.id,sensor_row.version)=(organization_value,workspace_value,environment_value,sensor_value,expected_version_value) AND sensor_row.state IN('pending','active','degraded');
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='sensor mutation conflict';END IF;
 UPDATE zasp_sensor_tokens token_row SET sensor_version_at_issue=expected_version_value+1 WHERE (token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id)=(organization_value,workspace_value,environment_value,sensor_value) AND token_row.format_version=1 AND token_row.revoked_at IS NULL;
 result_value:=jsonb_build_object('body',zasp_runtime_public_sensor_value(organization_value,workspace_value,environment_value,sensor_value),'token_id',NULL,'token_generation',NULL,'token_expires_at',NULL,'replayed',false);
 INSERT INTO zasp_runtime_sensor_mutations(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,request_digest,sensor_id,expected_version,result) VALUES(organization_value,workspace_value,environment_value,principal_value,'updateSensor',idempotency_value,request_digest_value,sensor_value,expected_version_value,result_value);PERFORM zasp_runtime_mark_used();PERFORM zasp_authorization80.sensor_audit(organization_value,workspace_value,environment_value,principal_value,'updateSensor',idempotency_value,result_value);RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80.verify_attestation(envelope text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE outer_value json;body_bytes bytea;body_json json;proof jsonb;k bytea;now_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint;
BEGIN
 IF envelope IS NULL OR octet_length(envelope)>12*1024*1024 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization attestation rejected';END IF;
 outer_value:=envelope::json;
 IF json_typeof(outer_value)<>'object' OR NOT zasp_authorization80.unique_json(outer_value)
 OR (SELECT count(*) FROM json_each(outer_value))<>3
 OR EXISTS(SELECT 1 FROM json_each(outer_value) WHERE key NOT IN('body','version','mac') OR json_typeof(value)<>'string')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization attestation rejected';END IF;
 SELECT key INTO k FROM zasp_authorization80.verifier WHERE version=outer_value->>'version';
 body_bytes:=decode(outer_value->>'body','base64');
 IF NOT COALESCE(k IS NOT NULL AND octet_length(body_bytes) BETWEEN 1 AND 8*1024*1024
 AND outer_value->>'mac'=encode(public.hmac(convert_to('zasp-authorization-attestation-v1','UTF8')||decode('00','hex')||body_bytes,k,'sha256'),'hex'),false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization attestation rejected';END IF;
 -- Parse the exact authenticated bytes, not a parallel unsigned allowed list.
 body_json:=convert_from(body_bytes,'UTF8')::json;
 IF json_typeof(body_json)<>'object' OR NOT zasp_authorization80.unique_json(body_json) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization attestation rejected';END IF;
 proof:=body_json::jsonb;
 IF NOT COALESCE(proof->>'attestation_domain'='zasp-authorization-attestation-v1' AND proof->>'key_version'=outer_value->>'version'
 AND (proof->>'issued_at')::bigint<=now_ms+5000 AND (proof->>'expires_at')::bigint>now_ms
 AND (proof->>'expires_at')::bigint-(proof->>'issued_at')::bigint BETWEEN 1 AND 60000,false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization attestation rejected';END IF;
 RETURN proof;
EXCEPTION WHEN data_exception THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='authorization attestation rejected';
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.inner_authenticate_sensor(locator_value bytea, secret_value bytea, audience_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE locator_hash bytea;candidate_scope record;token_row zasp_sensor_tokens%ROWTYPE;sensor_row zasp_sensors%ROWTYPE;computed_hash bytea;
BEGIN

 IF NOT public.zasp_discovery_principal_ready('zasp_runtime_ingest') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current runtime ingest principal rejected';END IF;

 IF octet_length(locator_value)<>16 OR octet_length(secret_value)<>32 OR audience_value<>'event-ingest' THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 locator_hash:=digest(locator_value,'sha256');
 SELECT token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.sensor_id INTO candidate_scope FROM zasp_sensor_tokens token_value WHERE token_value.locator_digest=locator_hash;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate_scope.organization_id,candidate_scope.workspace_id,candidate_scope.environment_id,candidate_scope.sensor_id),0));
 SELECT token_value.* INTO token_row FROM zasp_sensor_tokens token_value WHERE token_value.locator_digest=locator_hash FOR UPDATE;
 SELECT sensor_value.* INTO sensor_row FROM zasp_sensors sensor_value WHERE (sensor_value.organization_id,sensor_value.workspace_id,sensor_value.environment_id,sensor_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id) FOR UPDATE;
 computed_hash:=zasp_runtime_sensor_secret_hash(audience_value,token_row.id,token_row.token_generation,token_row.salt,secret_value);
 IF token_row.format_version<>1 OR token_row.audience<>audience_value OR token_row.revoked_at IS NOT NULL OR token_row.expires_at<=transaction_timestamp()
  OR token_row.sensor_version_at_issue<>sensor_row.version OR sensor_row.state NOT IN('pending','active','degraded')
  OR digest(token_row.token_hash||computed_hash,'sha256')<>digest(token_row.token_hash||token_row.token_hash,'sha256')
  OR EXISTS(SELECT 1 FROM zasp_sensor_tokens newer WHERE (newer.organization_id,newer.workspace_id,newer.environment_id,newer.sensor_id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id) AND newer.token_generation>token_row.token_generation)
 THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 UPDATE zasp_sensor_tokens token_value SET last_authenticated_at=transaction_timestamp() WHERE (token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.id);
 PERFORM zasp_runtime_mark_used();

 IF NOT public.zasp_discovery_principal_ready('zasp_runtime_ingest') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current runtime ingest principal rejected';END IF;
 RETURN jsonb_build_object('organization_id',token_row.organization_id,'workspace_id',token_row.workspace_id,'environment_id',token_row.environment_id,'sensor_id',token_row.sensor_id,'sensor_kind',sensor_row.kind,'sensor_mode',sensor_row.mode,'sensor_version',sensor_row.version,'token_id',token_row.id,'token_generation',token_row.token_generation,'audience',token_row.audience);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.inner_commit_reserved_batch(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, request_digest_value bytea, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;event_payload jsonb;result_value jsonb;
BEGIN


 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR octet_length(request_digest_value)<>32 OR NOT zasp_valid_product_id(job_value) OR NOT zasp_valid_product_id(outbox_value) OR NOT zasp_discovery_s3_object_reference(artifact_reference_value) OR length(artifact_key_value) NOT BETWEEN 32 AND 1024 OR right(artifact_reference_value,length(artifact_key_value)+1)<>'/'||artifact_key_value OR length(artifact_version_value) NOT BETWEEN 1 AND 1024 OR artifact_version_value<>btrim(artifact_version_value) OR octet_length(artifact_checksum_value)<>32 OR artifact_size_value NOT BETWEEN 1 AND 67108864 OR artifact_kms_key_value !~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation,authority_row.request_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime batch rejected';END IF;
 IF batch_row.payload_schema_version='runtime-event-v2' AND batch_row.source_kind<>'tetragon' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime precision source rejected';END IF;
IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();END IF;
 IF batch_row.state NOT IN('uploading','unknown') THEN
  IF batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND (batch_row.raw_artifact_reference,batch_row.raw_artifact_key,batch_row.raw_artifact_version_id,batch_row.raw_artifact_checksum,batch_row.raw_artifact_size_bytes,batch_row.raw_artifact_kms_key) IS NOT DISTINCT FROM (artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value)
   AND EXISTS(SELECT 1 FROM zasp_discovery_jobs job_row WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.id,job_row.kind,job_row.authority_id)=(organization_value,workspace_value,environment_value,job_value,'runtime',batch_value))
   AND EXISTS(SELECT 1 FROM zasp_discovery_outbox outbox_row WHERE (outbox_row.organization_id,outbox_row.workspace_id,outbox_row.environment_id,outbox_row.id,outbox_row.topic,outbox_row.deterministic_key,outbox_row.payload_version)=(organization_value,workspace_value,environment_value,outbox_value,'runtime-events','runtime:'||batch_value,15))
  THEN IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();END IF;  
 RETURN jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state,'replayed',true);END IF;
  RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';
 END IF;
 IF (batch_row.raw_artifact_key,batch_row.content_digest,batch_row.payload_size_bytes) IS DISTINCT FROM (artifact_key_value,artifact_checksum_value,artifact_size_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';END IF;
 INSERT INTO zasp_runtime_batches(organization_id,workspace_id,environment_id,id,sensor_id,idempotency_key,payload_digest,event_count,payload_reference,payload_size_bytes,payload_media_type,payload_schema_version)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.sensor_id,batch_row.idempotency_key,batch_row.content_digest,batch_row.event_count,artifact_reference_value,batch_row.payload_size_bytes,batch_row.payload_media_type,batch_row.payload_schema_version);
 INSERT INTO zasp_discovery_jobs(organization_id,workspace_id,environment_id,id,kind,authority_id,idempotency_key,request_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_row.batch_id,batch_row.idempotency_key,batch_row.request_digest);
 INSERT INTO zasp_runtime_stage_work(organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,stage_order,implementation_version,input_digest)
 SELECT batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.batch_generation,stage_value.stage,stage_value.stage_order,CASE WHEN batch_row.payload_schema_version='runtime-event-v2' THEN CASE stage_value.stage WHEN 'archive' THEN 'runtime-archive-v2' WHEN 'index' THEN 'runtime-index-v2' WHEN 'correlate' THEN 'runtime-correlation-v4' WHEN 'project' THEN 'runtime-projection-v3' WHEN 'complete' THEN 'runtime-complete-v3' END WHEN batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN CASE stage_value.stage WHEN 'archive' THEN 'runtime-archive-v1' WHEN 'index' THEN 'runtime-index-v1' WHEN 'correlate' THEN 'runtime-correlation-v3' WHEN 'project' THEN 'runtime-projection-v2' WHEN 'complete' THEN 'runtime-complete-v2' END ELSE stage_value.version_value END,CASE WHEN stage_value.stage_order=1 THEN batch_row.content_digest ELSE NULL END
 FROM (VALUES('archive',1,'runtime-archive-v1'),('index',2,'runtime-index-v1'),('correlate',3,'runtime-correlation-v2'),('project',4,'runtime-projection-v1'),('complete',5,'runtime-complete-v1')) stage_value(stage,stage_order,version_value);
 event_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',artifact_reference_value,'artifact_key',artifact_key_value,'artifact_version_id',artifact_version_value,'artifact_checksum',encode(artifact_checksum_value,'hex'),'artifact_size_bytes',artifact_size_value,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
 INSERT INTO zasp_discovery_outbox(organization_id,workspace_id,environment_id,id,topic,deterministic_key,payload_version,payload,payload_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_row.batch_id,15,event_payload,digest(convert_to(event_payload::text,'UTF8'),'sha256'));
 UPDATE zasp_runtime_batch_authorities authority_row SET raw_artifact_reference=artifact_reference_value,raw_artifact_version_id=artifact_version_value,raw_artifact_checksum=artifact_checksum_value,raw_artifact_size_bytes=artifact_size_value,raw_artifact_kms_key=artifact_kms_key_value,state='queued',finalized_at=transaction_timestamp() WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id);
 result_value:=jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state','queued','replayed',false);
IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();END IF;

 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.inner_finalize_batch_v15(locator_value bytea, secret_value bytea, audience_value text, batch_value text, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;batch_row zasp_runtime_batch_authorities%ROWTYPE;
BEGIN


 authority_value:=zasp_authorization80_runtime.inner_authenticate_sensor(locator_value,secret_value,audience_value);
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(authority_value->>'organization_id',authority_value->>'workspace_id',authority_value->>'environment_id',batch_value);
 IF NOT FOUND OR (batch_row.sensor_id,batch_row.sensor_token_id,batch_row.token_generation) IS DISTINCT FROM (authority_value->>'sensor_id',authority_value->>'token_id',(authority_value->>'token_generation')::bigint) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime batch rejected';END IF;

 RETURN zasp_authorization80_runtime.inner_commit_reserved_batch(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.batch_generation,batch_row.request_digest,job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.inner_reconcile_batch(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, request_digest_value bytea, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;completion_digest_value bytea;result_value jsonb;
BEGIN


 IF NOT zasp_discovery_principal_ready('zasp_runtime_ingest') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime reconciliation rejected';END IF;
 IF NOT zasp_discovery_s3_object_reference(artifact_reference_value) OR length(artifact_key_value) NOT BETWEEN 32 AND 1024 OR right(artifact_reference_value,length(artifact_key_value)+1)<>'/'||artifact_key_value OR length(artifact_version_value) NOT BETWEEN 1 AND 1024 OR artifact_version_value<>btrim(artifact_version_value) OR octet_length(artifact_checksum_value)<>32 OR artifact_size_value NOT BETWEEN 1 AND 67108864 OR artifact_kms_key_value !~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation rejected';END IF;
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation,authority_row.request_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime reconciliation rejected';END IF;
 IF batch_row.state='quarantined' AND (batch_row.raw_artifact_reference,batch_row.raw_artifact_key,batch_row.raw_artifact_version_id,batch_row.raw_artifact_checksum,batch_row.raw_artifact_size_bytes,batch_row.raw_artifact_kms_key) IS NOT DISTINCT FROM (artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value) THEN  
 RETURN batch_row.completion_result;END IF;
 IF batch_row.state NOT IN('uploading','unknown','queued') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime reconciliation conflict';END IF;
 IF (batch_row.raw_artifact_key,batch_row.content_digest,batch_row.payload_size_bytes) IS DISTINCT FROM (artifact_key_value,artifact_checksum_value,artifact_size_value) THEN
  completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,encode(request_digest_value,'hex'),artifact_reference_value,artifact_key_value,artifact_version_value,encode(artifact_checksum_value,'hex'),artifact_size_value::text,artifact_kms_key_value,'reconcile-drift'),'UTF8'),'sha256');
  result_value:=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed','replayed',false);
  UPDATE zasp_runtime_batch_authorities authority_row SET raw_artifact_reference=artifact_reference_value,raw_artifact_key=artifact_key_value,raw_artifact_version_id=artifact_version_value,raw_artifact_checksum=artifact_checksum_value,raw_artifact_size_bytes=artifact_size_value,raw_artifact_kms_key=artifact_kms_key_value,state='quarantined',finalized_at=transaction_timestamp(),completed_at=transaction_timestamp(),completion_digest=completion_digest_value,completion_result=result_value WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);

 RETURN result_value;
 END IF;

 RETURN zasp_authorization80_runtime.inner_commit_reserved_batch(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value,job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.inner_reserve_batch_v15(locator_value bytea, secret_value bytea, audience_value text, batch_value text, idempotency_value text, content_digest_value bytea, source_kind_value text, media_type_value text, schema_version_value text, payload_size_value bigint, event_count_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;organization_value text;workspace_value text;environment_value text;sensor_value text;token_value text;token_generation_value bigint;generation_value bigint;request_digest_value bytea;artifact_key_value text;prior_value zasp_runtime_batch_authorities%ROWTYPE;
BEGIN


 IF NOT zasp_valid_product_id(batch_value) OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR octet_length(content_digest_value)<>32 OR source_kind_value NOT IN('tetragon','otlp') OR length(media_type_value) NOT BETWEEN 1 AND 128 OR media_type_value<>btrim(media_type_value) OR length(schema_version_value) NOT BETWEEN 1 AND 64 OR schema_version_value !~ '^[a-z0-9][a-z0-9_.-]+$' OR payload_size_value NOT BETWEEN 1 AND 67108864 OR event_count_value NOT BETWEEN 1 AND 1000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 authority_value:=zasp_authorization80_runtime.inner_authenticate_sensor(locator_value,secret_value,audience_value);
 organization_value:=authority_value->>'organization_id';workspace_value:=authority_value->>'workspace_id';environment_value:=authority_value->>'environment_id';sensor_value:=authority_value->>'sensor_id';token_value:=authority_value->>'token_id';token_generation_value:=(authority_value->>'token_generation')::bigint;
 IF authority_value->>'sensor_kind'<>source_kind_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 request_digest_value:=digest(convert_to(jsonb_build_object('sensor_id',sensor_value,'token_id',token_value,'token_generation',token_generation_value,'batch_id',batch_value,'idempotency_key',idempotency_value,'content_digest',encode(content_digest_value,'hex'),'source_kind',source_kind_value,'media_type',media_type_value,'schema_version',schema_version_value,'payload_size_bytes',payload_size_value,'event_count',event_count_value)::text,'UTF8'),'sha256');
 SELECT * INTO prior_value FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.sensor_id,authority_row.idempotency_key)=(organization_value,workspace_value,environment_value,sensor_value,idempotency_value);
 IF FOUND THEN
  IF (prior_value.batch_id,prior_value.sensor_token_id,prior_value.token_generation,prior_value.request_digest,prior_value.content_digest,prior_value.source_kind,prior_value.payload_media_type,prior_value.payload_schema_version,prior_value.payload_size_bytes,prior_value.event_count) IS DISTINCT FROM (batch_value,token_value,token_generation_value,request_digest_value,content_digest_value,source_kind_value,media_type_value,schema_version_value,payload_size_value,event_count_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';END IF;

 RETURN jsonb_build_object('batch_id',prior_value.batch_id,'generation',prior_value.batch_generation,'artifact_key',prior_value.raw_artifact_key,'request_digest',encode(prior_value.request_digest,'hex'),'state',prior_value.state,'replayed',true);
 END IF;
 SELECT COALESCE(max(authority_row.batch_generation),0)+1 INTO generation_value FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.sensor_id)=(organization_value,workspace_value,environment_value,sensor_value);
 artifact_key_value:=format('runtime/v15/%s/%s/%s/%s/%s/%s.json',organization_value,workspace_value,environment_value,sensor_value,lpad(generation_value::text,20,'0'),batch_value);
 INSERT INTO zasp_runtime_batch_authorities(organization_id,workspace_id,environment_id,batch_id,sensor_id,sensor_token_id,token_generation,batch_generation,idempotency_key,request_digest,content_digest,source_kind,payload_media_type,payload_schema_version,payload_size_bytes,event_count,raw_artifact_key)
 VALUES(organization_value,workspace_value,environment_value,batch_value,sensor_value,token_value,token_generation_value,generation_value,idempotency_value,request_digest_value,content_digest_value,source_kind_value,media_type_value,schema_version_value,payload_size_value,event_count_value,artifact_key_value);

 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'artifact_key',artifact_key_value,'request_digest',encode(request_digest_value,'hex'),'state','uploading','replayed',false);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.projection_organization_lock(o text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();
 IF NOT COALESCE(public.zasp_runtime_principal_ready('zasp_runtime_coordinator'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime projection principal unavailable';END IF;
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime projection organization unavailable';END IF;
 PERFORM zasp_authorization80_runtime.require_current();
 IF NOT COALESCE(public.zasp_runtime_principal_ready('zasp_runtime_coordinator'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime projection principal changed';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_ack_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, provider_ack_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE delivery_row zasp_runtime_deliveries%ROWTYPE;result_value jsonb;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR octet_length(provider_ack_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id,existing.batch_generation,existing.message_id,existing.message_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value) FOR UPDATE;
 IF FOUND AND delivery_row.disposition='acked' AND delivery_row.provider_ack_digest=provider_ack_digest_value THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',true);END IF;
 IF NOT FOUND OR delivery_row.disposition<>'ack_pending' OR delivery_row.lease_owner<>worker_value OR delivery_row.lease_token<>lease_token_value OR delivery_row.lease_expires_at<=transaction_timestamp() OR delivery_row.visibility_deadline<=transaction_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) AND authority_row.state IN('succeeded','failed','quarantined') AND authority_row.completion_digest IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 UPDATE zasp_runtime_deliveries existing SET disposition='acked',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,provider_ack_digest=provider_ack_digest_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',false);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_ack_outbox(topic_value text, organization_value text, workspace_value text, environment_value text, outbox_value text, worker_value text, lease_token_value text, provider_ack_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;remaining_count integer;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
 IF topic_value<>'runtime-events' OR provider_ack_value !~ '^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox acknowledgement';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox WHERE (organization_id,workspace_id,environment_id,id,topic)=(organization_value,workspace_value,environment_value,outbox_value,topic_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease missing';END IF;
 result:=zasp_discovery_ack_outbox(organization_value,workspace_value,environment_value,outbox_value,worker_value,lease_token_value,provider_ack_value);
 SELECT count(*) INTO remaining_count FROM zasp_discovery_outbox WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN result||jsonb_build_object('remaining_count',remaining_count);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_authenticate_sensor(locator_value bytea, secret_value bytea, audience_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE locator_hash bytea;candidate_scope record;token_row zasp_sensor_tokens%ROWTYPE;sensor_row zasp_sensors%ROWTYPE;computed_hash bytea;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();
 IF NOT public.zasp_discovery_principal_ready('zasp_runtime_ingest') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current runtime ingest principal rejected';END IF;

 IF octet_length(locator_value)<>16 OR octet_length(secret_value)<>32 OR audience_value<>'event-ingest' THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 locator_hash:=digest(locator_value,'sha256');
 SELECT token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.sensor_id INTO candidate_scope FROM zasp_sensor_tokens token_value WHERE token_value.locator_digest=locator_hash;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate_scope.organization_id,candidate_scope.workspace_id,candidate_scope.environment_id,candidate_scope.sensor_id),0));
 SELECT token_value.* INTO token_row FROM zasp_sensor_tokens token_value WHERE token_value.locator_digest=locator_hash FOR UPDATE;
 SELECT sensor_value.* INTO sensor_row FROM zasp_sensors sensor_value WHERE (sensor_value.organization_id,sensor_value.workspace_id,sensor_value.environment_id,sensor_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id) FOR UPDATE;
 computed_hash:=zasp_runtime_sensor_secret_hash(audience_value,token_row.id,token_row.token_generation,token_row.salt,secret_value);
 IF token_row.format_version<>1 OR token_row.audience<>audience_value OR token_row.revoked_at IS NOT NULL OR token_row.expires_at<=transaction_timestamp()
  OR token_row.sensor_version_at_issue<>sensor_row.version OR sensor_row.state NOT IN('pending','active','degraded')
  OR digest(token_row.token_hash||computed_hash,'sha256')<>digest(token_row.token_hash||token_row.token_hash,'sha256')
  OR EXISTS(SELECT 1 FROM zasp_sensor_tokens newer WHERE (newer.organization_id,newer.workspace_id,newer.environment_id,newer.sensor_id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id) AND newer.token_generation>token_row.token_generation)
 THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 UPDATE zasp_sensor_tokens token_value SET last_authenticated_at=transaction_timestamp() WHERE (token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.id);
 PERFORM zasp_runtime_mark_used();
  PERFORM zasp_authorization80_runtime.require_current();
 IF NOT public.zasp_discovery_principal_ready('zasp_runtime_ingest') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='current runtime ingest principal rejected';END IF;
 RETURN jsonb_build_object('organization_id',token_row.organization_id,'workspace_id',token_row.workspace_id,'environment_id',token_row.environment_id,'sensor_id',token_row.sensor_id,'sensor_kind',sensor_row.kind,'sensor_mode',sensor_row.mode,'sensor_version',sensor_row.version,'token_id',token_row.id,'token_generation',token_row.token_generation,'audience',token_row.audience);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_claim_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, receive_count_value integer, worker_value text, lease_token_value text, lease_seconds integer, visibility_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;delivery_row zasp_runtime_deliveries%ROWTYPE;outbox_digest bytea;disposition_value text;replayed_value boolean:=false;lease_expires_value timestamptz;visibility_deadline_value timestamptz;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR message_value !~ '^[A-Za-z0-9_-]{1,128}$' OR octet_length(message_digest_value)<>32 OR receive_count_value NOT BETWEEN 1 AND 100 OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR visibility_seconds<lease_seconds OR visibility_seconds>43200 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-runtime-delivery',organization_value,workspace_value,environment_value,batch_value),0));
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR batch_row.state='uploading' THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery missing';END IF;
 SELECT outbox.payload_digest INTO outbox_digest FROM zasp_discovery_outbox outbox WHERE (outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.topic,outbox.deterministic_key,outbox.payload_version)=(organization_value,workspace_value,environment_value,'runtime-events','runtime:'||batch_value,15);
 IF NOT FOUND OR outbox_digest IS DISTINCT FROM message_digest_value THEN
  IF batch_row.state NOT IN('succeeded','failed','unknown','quarantined') THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);END IF;
  PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value) FOR UPDATE;
 -- v36: exact durable outbox identity permits at-least-once publication.
 IF FOUND AND delivery_row.batch_generation=generation_value AND delivery_row.message_digest=message_digest_value AND delivery_row.message_id<>message_value THEN
  IF batch_row.state='unknown' OR delivery_row.disposition='unknown' THEN
   PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF batch_row.state IN('succeeded','failed','quarantined') THEN
   PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);
  END IF;
  IF delivery_row.disposition NOT IN('held','ack_pending') THEN
   PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp() THEN
   PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_duplicate','replayed',true);
  END IF;
  UPDATE zasp_runtime_deliveries existing SET message_id=message_value,receive_count=receive_count_value,provider_ack_digest=NULL,lease_expires_at=transaction_timestamp()
   WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  delivery_row.message_id:=message_value;delivery_row.receive_count:=receive_count_value;delivery_row.lease_expires_at:=transaction_timestamp();
 END IF;
 IF FOUND AND (delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest) IS DISTINCT FROM (generation_value,message_value,message_digest_value) THEN
  UPDATE zasp_runtime_deliveries existing SET disposition='quarantined',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value) AND authority_row.state NOT IN('succeeded','failed','unknown','quarantined');
  PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 IF FOUND AND receive_count_value<delivery_row.receive_count THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime delivery conflict';END IF;
 IF FOUND AND delivery_row.disposition='acked' THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);END IF;
 IF batch_row.state='unknown' OR FOUND AND delivery_row.disposition='unknown' THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',FOUND);END IF;
 IF FOUND AND delivery_row.disposition IN('held','ack_pending') AND delivery_row.lease_expires_at>transaction_timestamp() AND (delivery_row.lease_owner,delivery_row.lease_token) IS DISTINCT FROM (worker_value,lease_token_value) THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false,'lease_expires_at',delivery_row.lease_expires_at);END IF;
 IF EXISTS(SELECT 1 FROM zasp_runtime_deliveries other WHERE other.organization_id=organization_value AND other.batch_id<>batch_value AND other.disposition IN('held','ack_pending') AND other.lease_expires_at>transaction_timestamp()) THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false);END IF;
 disposition_value:=CASE WHEN batch_row.state IN('succeeded','failed','quarantined') THEN 'ack_pending' ELSE 'held' END;
 lease_expires_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);visibility_deadline_value:=transaction_timestamp()+make_interval(secs=>visibility_seconds);
 IF FOUND THEN
  replayed_value:=delivery_row.receive_count=receive_count_value AND delivery_row.disposition=disposition_value AND (delivery_row.lease_owner,delivery_row.lease_token) IS NOT DISTINCT FROM (worker_value,lease_token_value);
  UPDATE zasp_runtime_deliveries existing SET receive_count=GREATEST(existing.receive_count,receive_count_value),disposition=disposition_value,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=lease_expires_value,visibility_deadline=visibility_deadline_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 ELSE
  INSERT INTO zasp_runtime_deliveries(organization_id,workspace_id,environment_id,batch_id,batch_generation,message_id,message_digest,receive_count,disposition,lease_owner,lease_token,lease_expires_at,visibility_deadline) VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,receive_count_value,disposition_value,worker_value,lease_token_value,lease_expires_value,visibility_deadline_value);
 END IF;
 PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition',CASE WHEN disposition_value='held' THEN 'claimed' ELSE disposition_value END,'replayed',replayed_value,'lease_expires_at',lease_expires_value,'visibility_deadline',visibility_deadline_value,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'artifact_kms_key',batch_row.raw_artifact_kms_key,'request_digest',encode(batch_row.request_digest,'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_claim_stage_precision_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, expected_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR expected_stage IS NULL OR stage_value IS DISTINCT FROM expected_stage THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_precision_claim_version',true),'');
 PERFORM set_config('zasp.runtime_precision_claim_version',CASE stage_value WHEN 'archive' THEN 'runtime-archive-v2' WHEN 'index' THEN 'runtime-index-v2' WHEN 'correlate' THEN 'runtime-correlation-v4' WHEN 'project' THEN 'runtime-projection-v3' WHEN 'complete' THEN 'runtime-complete-v3' END,true);
 IF NOT COALESCE(zasp_authorization80_runtime.source_ready(51,(SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
  WHERE stage_row.stage=stage_value AND (CASE stage_value WHEN 'archive' THEN stage_row.implementation_version IN('runtime-archive-v1','runtime-archive-v2') WHEN 'index' THEN stage_row.implementation_version IN('runtime-index-v1','runtime-index-v2') WHEN 'correlate' THEN stage_row.implementation_version IN('runtime-correlation-v1','runtime-correlation-v2','runtime-correlation-v3','runtime-correlation-v4') WHEN 'project' THEN stage_row.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3') WHEN 'complete' THEN stage_row.implementation_version IN('runtime-complete-v1','runtime-complete-v2','runtime-complete-v3') ELSE false END) AND stage_row.attempt>=100 AND stage_row.state IN('pending','retryable','leased') AND (stage_row.state<>'leased' OR stage_row.lease_expires_at<=transaction_timestamp())
  RETURNING stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.completion_digest,stage_row.completion_result
 ),failed_batches AS (
  UPDATE zasp_runtime_batch_authorities authority_row SET state='failed',completed_at=transaction_timestamp(),completion_digest=exhausted.completion_digest,completion_result=exhausted.completion_result
  FROM exhausted WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id)
  RETURNING authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.completion_digest,authority_row.completion_result
 ),failed_legacy_batches AS (
  UPDATE zasp_runtime_batches batch_row SET state='failed',completed_at=transaction_timestamp()
  FROM failed_batches WHERE (batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id)
  RETURNING batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id
 ),failed_jobs AS (
  UPDATE zasp_discovery_jobs job_row SET state='failed',last_error='exhausted',completed_at=transaction_timestamp(),updated_at=transaction_timestamp(),completion_digest=failed_batches.completion_digest,completion_result=failed_batches.completion_result
  FROM failed_batches WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.kind,job_row.authority_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,'runtime',failed_batches.batch_id)
  RETURNING job_row.organization_id
 )
 UPDATE zasp_runtime_deliveries delivery_row SET disposition='ack_pending',updated_at=transaction_timestamp()
 FROM failed_batches WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id) AND delivery_row.disposition='held';
 WITH eligible AS (
  SELECT stage_row.ctid row_id,stage_row.*,row_number() OVER(PARTITION BY stage_row.organization_id ORDER BY stage_row.available_at,stage_row.batch_id) organization_rank
  FROM zasp_runtime_stage_work stage_row
  WHERE stage_row.stage=stage_value AND (CASE stage_value WHEN 'archive' THEN stage_row.implementation_version IN('runtime-archive-v1','runtime-archive-v2') WHEN 'index' THEN stage_row.implementation_version IN('runtime-index-v1','runtime-index-v2') WHEN 'correlate' THEN stage_row.implementation_version IN('runtime-correlation-v1','runtime-correlation-v2','runtime-correlation-v3','runtime-correlation-v4') WHEN 'project' THEN stage_row.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3') WHEN 'complete' THEN stage_row.implementation_version IN('runtime-complete-v1','runtime-complete-v2','runtime-complete-v3') ELSE false END) AND stage_row.attempt<100 AND stage_row.available_at<=transaction_timestamp() AND (stage_row.state IN('pending','retryable') OR stage_row.state='leased' AND stage_row.lease_expires_at<=transaction_timestamp())
   AND stage_row.input_digest IS NOT NULL
   AND EXISTS(SELECT 1 FROM zasp_runtime_deliveries delivery_row WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.disposition)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,'held') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp())
   AND (stage_row.stage_order=1 OR EXISTS(SELECT 1 FROM zasp_runtime_stage_work predecessor WHERE (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order,predecessor.state,predecessor.effect_digest)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage_order-1,'succeeded',stage_row.predecessor_digest)))
   AND NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work live_row WHERE live_row.stage=stage_value AND live_row.organization_id=stage_row.organization_id AND live_row.state='leased' AND live_row.lease_expires_at>transaction_timestamp())
 ),organizations AS (
  SELECT eligible.organization_id,min(eligible.available_at) first_available,MAX(fairness.last_claimed_at) last_claimed_at
  FROM eligible LEFT JOIN zasp_runtime_stage_fairness fairness ON (fairness.stage,fairness.organization_id)=(stage_value,eligible.organization_id)
  WHERE eligible.organization_rank=1 GROUP BY eligible.organization_id
  ORDER BY MAX(fairness.last_claimed_at) NULLS FIRST,min(eligible.available_at),eligible.organization_id LIMIT claim_limit
 ),candidates AS (
  SELECT stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage
  FROM zasp_runtime_stage_work stage_row JOIN eligible ON stage_row.ctid=eligible.row_id JOIN organizations ON organizations.organization_id=eligible.organization_id
  WHERE eligible.organization_rank=1 ORDER BY organizations.last_claimed_at NULLS FIRST,organizations.first_available,stage_row.organization_id,stage_row.batch_id FOR UPDATE OF stage_row SKIP LOCKED
 ),claimed AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='leased',attempt=stage_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp(),last_error_class=NULL
  FROM candidates WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage)=(candidates.organization_id,candidates.workspace_id,candidates.environment_id,candidates.batch_id,candidates.stage)
  RETURNING stage_row.*
 ),fairness AS (
  INSERT INTO zasp_runtime_stage_fairness(stage,organization_id,last_claimed_at) SELECT stage_value,claimed.organization_id,transaction_timestamp() FROM claimed
  ON CONFLICT(stage,organization_id) DO UPDATE SET last_claimed_at=excluded.last_claimed_at RETURNING organization_id
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'stage',claimed.stage,'attempt',claimed.attempt,'implementation_version',claimed.implementation_version,'predecessor_digest',CASE WHEN claimed.predecessor_digest IS NULL THEN NULL ELSE encode(claimed.predecessor_digest,'hex') END,'input_digest',encode(claimed.input_digest,'hex'),'input_reference',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_reference ELSE predecessor.result_reference END,'input_version_id',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_version_id ELSE predecessor.result_version_id END,'lease_expires_at',claimed.lease_expires_at) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO result_value
 FROM claimed JOIN zasp_runtime_batch_authorities authority_row ON (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.batch_generation)
 LEFT JOIN zasp_runtime_stage_work predecessor ON (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.stage_order-1);
 IF stage_value='archive' AND jsonb_array_length(result_value)>0 THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='processing' WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(item->>'organization_id',item->>'workspace_id',item->>'environment_id',item->>'batch_id'));END IF;
 PERFORM set_config('zasp.runtime_precision_claim_version',prior_capability,true);
 IF NOT COALESCE(zasp_authorization80_runtime.source_ready(51,(SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_commit_reserved_batch(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, request_digest_value bytea, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;event_payload jsonb;result_value jsonb;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR octet_length(request_digest_value)<>32 OR NOT zasp_valid_product_id(job_value) OR NOT zasp_valid_product_id(outbox_value) OR NOT zasp_discovery_s3_object_reference(artifact_reference_value) OR length(artifact_key_value) NOT BETWEEN 32 AND 1024 OR right(artifact_reference_value,length(artifact_key_value)+1)<>'/'||artifact_key_value OR length(artifact_version_value) NOT BETWEEN 1 AND 1024 OR artifact_version_value<>btrim(artifact_version_value) OR octet_length(artifact_checksum_value)<>32 OR artifact_size_value NOT BETWEEN 1 AND 67108864 OR artifact_kms_key_value !~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation,authority_row.request_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime batch rejected';END IF;
 IF batch_row.payload_schema_version='runtime-event-v2' AND batch_row.source_kind<>'tetragon' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime precision source rejected';END IF;
IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();END IF;
 IF batch_row.state NOT IN('uploading','unknown') THEN
  IF batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND (batch_row.raw_artifact_reference,batch_row.raw_artifact_key,batch_row.raw_artifact_version_id,batch_row.raw_artifact_checksum,batch_row.raw_artifact_size_bytes,batch_row.raw_artifact_kms_key) IS NOT DISTINCT FROM (artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value)
   AND EXISTS(SELECT 1 FROM zasp_discovery_jobs job_row WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.id,job_row.kind,job_row.authority_id)=(organization_value,workspace_value,environment_value,job_value,'runtime',batch_value))
   AND EXISTS(SELECT 1 FROM zasp_discovery_outbox outbox_row WHERE (outbox_row.organization_id,outbox_row.workspace_id,outbox_row.environment_id,outbox_row.id,outbox_row.topic,outbox_row.deterministic_key,outbox_row.payload_version)=(organization_value,workspace_value,environment_value,outbox_value,'runtime-events','runtime:'||batch_value,15))
  THEN IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();END IF;  PERFORM zasp_authorization80_runtime.require_current();
 RETURN jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state,'replayed',true);END IF;
  RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';
 END IF;
 IF (batch_row.raw_artifact_key,batch_row.content_digest,batch_row.payload_size_bytes) IS DISTINCT FROM (artifact_key_value,artifact_checksum_value,artifact_size_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';END IF;
 INSERT INTO zasp_runtime_batches(organization_id,workspace_id,environment_id,id,sensor_id,idempotency_key,payload_digest,event_count,payload_reference,payload_size_bytes,payload_media_type,payload_schema_version)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.sensor_id,batch_row.idempotency_key,batch_row.content_digest,batch_row.event_count,artifact_reference_value,batch_row.payload_size_bytes,batch_row.payload_media_type,batch_row.payload_schema_version);
 INSERT INTO zasp_discovery_jobs(organization_id,workspace_id,environment_id,id,kind,authority_id,idempotency_key,request_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_row.batch_id,batch_row.idempotency_key,batch_row.request_digest);
 INSERT INTO zasp_runtime_stage_work(organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,stage_order,implementation_version,input_digest)
 SELECT batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.batch_generation,stage_value.stage,stage_value.stage_order,CASE WHEN batch_row.payload_schema_version='runtime-event-v2' THEN CASE stage_value.stage WHEN 'archive' THEN 'runtime-archive-v2' WHEN 'index' THEN 'runtime-index-v2' WHEN 'correlate' THEN 'runtime-correlation-v4' WHEN 'project' THEN 'runtime-projection-v3' WHEN 'complete' THEN 'runtime-complete-v3' END WHEN batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN CASE stage_value.stage WHEN 'archive' THEN 'runtime-archive-v1' WHEN 'index' THEN 'runtime-index-v1' WHEN 'correlate' THEN 'runtime-correlation-v3' WHEN 'project' THEN 'runtime-projection-v2' WHEN 'complete' THEN 'runtime-complete-v2' END ELSE stage_value.version_value END,CASE WHEN stage_value.stage_order=1 THEN batch_row.content_digest ELSE NULL END
 FROM (VALUES('archive',1,'runtime-archive-v1'),('index',2,'runtime-index-v1'),('correlate',3,'runtime-correlation-v2'),('project',4,'runtime-projection-v1'),('complete',5,'runtime-complete-v1')) stage_value(stage,stage_order,version_value);
 event_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',artifact_reference_value,'artifact_key',artifact_key_value,'artifact_version_id',artifact_version_value,'artifact_checksum',encode(artifact_checksum_value,'hex'),'artifact_size_bytes',artifact_size_value,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
 INSERT INTO zasp_discovery_outbox(organization_id,workspace_id,environment_id,id,topic,deterministic_key,payload_version,payload,payload_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_row.batch_id,15,event_payload,digest(convert_to(event_payload::text,'UTF8'),'sha256'));
 UPDATE zasp_runtime_batch_authorities authority_row SET raw_artifact_reference=artifact_reference_value,raw_artifact_version_id=artifact_version_value,raw_artifact_checksum=artifact_checksum_value,raw_artifact_size_bytes=artifact_size_value,raw_artifact_kms_key=artifact_kms_key_value,state='queued',finalized_at=transaction_timestamp() WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id);
 result_value:=jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state','queued','replayed',false);
IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_authorization80_runtime.runtime_precision_transport_ready();END IF;
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_finalize_batch_v15_internal(locator_value bytea, secret_value bytea, audience_value text, batch_value text, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;batch_row zasp_runtime_batch_authorities%ROWTYPE;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 authority_value:=zasp_authorization80_runtime.runtime_authenticate_sensor(locator_value,secret_value,audience_value);
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(authority_value->>'organization_id',authority_value->>'workspace_id',authority_value->>'environment_id',batch_value);
 IF NOT FOUND OR (batch_row.sensor_id,batch_row.sensor_token_id,batch_row.token_generation) IS DISTINCT FROM (authority_value->>'sensor_id',authority_value->>'token_id',(authority_value->>'token_generation')::bigint) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime batch rejected';END IF;
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN zasp_authorization80_runtime.runtime_commit_reserved_batch(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.batch_generation,batch_row.request_digest,job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_finalize_batch_v17(locator_value bytea, secret_value bytea, audience_value text, batch_value text, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;result_value jsonb;work_value zasp_runtime_ingest_reconciliation_work%ROWTYPE;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 authority_value:=zasp_authorization80_runtime.inner_authenticate_sensor(locator_value,secret_value,audience_value);
 SELECT * INTO work_value FROM zasp_runtime_ingest_reconciliation_work work_row WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id)=(authority_value->>'organization_id',authority_value->>'workspace_id',authority_value->>'environment_id',batch_value) FOR UPDATE;
 IF FOUND AND work_value.state='leased' AND work_value.lease_expires_at>transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime batch finalize leased';END IF;
 result_value:=zasp_authorization80_runtime.inner_finalize_batch_v15(locator_value,secret_value,audience_value,batch_value,job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='succeeded',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completion_worker='request',completion_token_digest=digest(convert_to('request','UTF8'),'sha256'),completion_digest=digest(convert_to(result_value::text,'UTF8'),'sha256'),completion_result=result_value,completed_at=transaction_timestamp()
 WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation)=(authority_value->>'organization_id',authority_value->>'workspace_id',authority_value->>'environment_id',batch_value,(result_value->>'generation')::bigint) AND work_row.state NOT IN('succeeded','quarantined');
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_finish_precise_session_projection(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, attempt_value integer, input_digest_value bytea, implementation_value text, outcome_value text, effect_digest_value bytea, result_reference_value text, result_version_value text, result_digest_value bytea, error_class_value text, retry_after_seconds integer, receipt_bytes bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE predecessor zasp_runtime_stage_work%ROWTYPE;complete_row zasp_runtime_stage_work%ROWTYPE;receipt_value jsonb;item jsonb;event_value zasp_runtime_session_events%ROWTYPE;retained zasp_runtime_session_events%ROWTYPE;result_value jsonb;ids text[]:='{}';digest_value bytea;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 IF NOT COALESCE(zasp_authorization80_runtime.source_ready(51,(SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 IF num_nulls(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,input_digest_value,implementation_value,outcome_value,effect_digest_value,result_reference_value,result_version_value,result_digest_value,retry_after_seconds,receipt_bytes)>0
 OR NOT COALESCE(zasp_runtime_principal_ready('zasp_runtime_coordinator') AND zasp_runtime_stage_for_session()='complete' AND outcome_value='succeeded' AND implementation_value='runtime-complete-v3' AND octet_length(receipt_bytes) BETWEEN 1 AND 4194304,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session projection authority rejected';
 END IF;
 PERFORM zasp_authorization80_runtime.projection_organization_lock(organization_value);
 SELECT * INTO predecessor FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'project') FOR SHARE;
 IF NOT FOUND OR predecessor.state<>'succeeded' OR predecessor.implementation_version<>'runtime-projection-v3' OR predecessor.result_digest IS DISTINCT FROM digest(receipt_bytes,'sha256') OR predecessor.effect_digest IS DISTINCT FROM input_digest_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session predecessor receipt rejected';
 END IF;
 SELECT * INTO complete_row FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'complete') FOR UPDATE;
 IF NOT FOUND OR complete_row.implementation_version<>'runtime-complete-v3' OR complete_row.predecessor_digest IS DISTINCT FROM predecessor.effect_digest OR complete_row.input_digest IS DISTINCT FROM input_digest_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session receipt binding rejected';
 END IF;
 IF NOT COALESCE(public.zasp_runtime_principal_ready('zasp_runtime_coordinator'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime projection principal changed';END IF;
 IF complete_row.state='leased' AND complete_row.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime projection lease expired';END IF;
 receipt_value:=convert_from(receipt_bytes,'UTF8')::jsonb;
 IF NOT COALESCE(jsonb_typeof(receipt_value)='object' AND receipt_value->>'schema'='runtime-projection-receipt-v3' AND receipt_value->>'implementation_version'='runtime-projection-v3'
 AND (receipt_value->>'organization_id',receipt_value->>'workspace_id',receipt_value->>'environment_id',receipt_value->>'batch_id')=(organization_value,workspace_value,environment_value,batch_value)
 AND receipt_value->>'generation'=generation_value::text AND receipt_value->>'effect_digest'=encode(input_digest_value,'hex') AND input_digest_value=effect_digest_value
 AND jsonb_typeof(receipt_value->'items')='array' AND jsonb_array_length(receipt_value->'items') BETWEEN 1 AND 1000,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session receipt shape rejected';
 END IF;
 IF NOT COALESCE(zasp_authorization80_runtime.source_ready(51,(SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 result_value:=zasp_runtime_finish_stage_v39(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,input_digest_value,implementation_value,outcome_value,effect_digest_value,result_reference_value,result_version_value,result_digest_value,error_class_value,retry_after_seconds);
 FOR item IN SELECT value FROM jsonb_array_elements(receipt_value->'items') LOOP
  event_value.organization_id:=organization_value;event_value.workspace_id:=workspace_value;event_value.environment_id:=environment_value;
  event_value.event_id:=item->>'event_id';event_value.session_id:=NULLIF(item->>'session_id','');event_value.agent_id:=NULLIF(item->>'agent_id','');
  event_value.confidence:=item->>'confidence';event_value.source:=item->>'source';event_value.event_class:=item->>'event_class';event_value.action:=item->>'action';
  event_value.title:=item->>'title';event_value.evidence_id:=item->>'evidence_id';event_value.event_time:=(item->>'event_time')::timestamptz;event_value.projected_at:=transaction_timestamp();

  IF (item ? 'sandbox_id')<>(item ? 'sandbox_source_sensor_id')
  OR item ? 'sandbox_id' AND (jsonb_typeof(item->'sandbox_id') IS DISTINCT FROM 'string' OR jsonb_typeof(item->'sandbox_source_sensor_id') IS DISTINCT FROM 'string')
  OR item->>'confidence'='exact' AND NOT (item ? 'sandbox_id')
  OR event_value.agent_id IS NOT NULL AND event_value.agent_id=event_value.session_id
  THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session sandbox shape rejected';END IF;
  IF item->>'source' IS DISTINCT FROM 'tetragon' OR item->>'confidence'='exact' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime precise session source rejected';END IF;
  event_value.sandbox_id:=item->>'sandbox_id';event_value.sandbox_source_sensor_id:=item->>'sandbox_source_sensor_id';

  IF event_value.event_id=ANY(ids) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session duplicate event rejected';END IF;
  ids:=array_append(ids,event_value.event_id);
  INSERT INTO zasp_runtime_session_events SELECT (event_value).* ON CONFLICT DO NOTHING;
  SELECT * INTO STRICT retained FROM zasp_runtime_session_events WHERE (organization_id,workspace_id,environment_id,event_id)=(organization_value,workspace_value,environment_value,event_value.event_id);
  IF (to_jsonb(retained)-'projected_at') IS DISTINCT FROM (to_jsonb(event_value)-'projected_at') THEN
   RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime session event replay conflict';
  END IF;
 END LOOP;
 digest_value:=digest(receipt_bytes,'sha256');
 INSERT INTO zasp_runtime_session_projection_receipts VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,digest_value,ids) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM zasp_runtime_session_projection_receipts WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,receipt_digest,event_ids)=(organization_value,workspace_value,environment_value,batch_value,generation_value,digest_value,ids)) THEN
  RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime session receipt replay conflict';
 END IF;
 IF NOT COALESCE(zasp_authorization80_runtime.source_ready(51,(SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
  PERFORM zasp_authorization80_runtime.require_current();
 IF NOT COALESCE(public.zasp_runtime_principal_ready('zasp_runtime_coordinator'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime projection principal changed';END IF;
 IF complete_row.state='leased' AND complete_row.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime projection lease expired';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_finish_reconciliation(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work_value zasp_runtime_ingest_reconciliation_work%ROWTYPE;result_value jsonb;completion_digest_value bytea;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

 PERFORM zasp_authorization80_runtime.runtime_precision_reconciliation_ready();
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,worker_value,encode(digest(convert_to(lease_token_value,'UTF8'),'sha256'),'hex'),job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,encode(artifact_checksum_value,'hex'),artifact_size_value::text,artifact_kms_key_value),'UTF8'),'sha256');
 SELECT * INTO work_value FROM zasp_runtime_ingest_reconciliation_work work_row WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime reconciliation finish rejected';END IF;
 IF work_value.state IN('succeeded','quarantined') THEN
  IF (work_value.completion_worker,work_value.completion_token_digest,work_value.completion_digest) IS DISTINCT FROM (worker_value,digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime reconciliation finish conflict';END IF;
  PERFORM zasp_authorization80_runtime.runtime_precision_reconciliation_ready();
  PERFORM zasp_authorization80_runtime.require_current();
