CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_finish_stage(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, attempt_value integer, input_digest_value bytea, implementation_value text, outcome_value text, effect_digest_value bytea, result_reference_value text, result_version_value text, result_digest_value bytea, error_class_value text, retry_after_seconds integer)
