   PERFORM zasp_authorization80_runtime.require_current();
 RETURN result_value;
 END IF;
  PERFORM zasp_authorization80_runtime.require_current();
 RETURN zasp_authorization80_runtime.runtime_commit_reserved_batch(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value,job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_release_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, outcome_value text, error_class_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE completion_digest_value bytea;result_value jsonb;
BEGIN
 PERFORM zasp_authorization80_runtime.require_current();

