 PERFORM zasp_authorization80_runtime.require_current();

 IF num_nulls(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,token_value,attempt_value,receipt_digest_value,outcome_value,document_values,retry_seconds)>0 OR outcome_value NOT IN('indexed','retryable','quarantined') OR octet_length(receipt_digest_value)<>32
 OR (outcome_value='retryable' AND retry_seconds NOT BETWEEN 1 AND 3600) OR (outcome_value<>'retryable' AND retry_seconds<>0)
 OR NOT zasp_authorization80_runtime.runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime session search checkpoint rejected';END IF;
 IF NOT zasp_recovery_scope_mutable(organization_value,workspace_value,environment_value) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search recovery hold active';END IF;IF NOT zasp_authorization80_runtime.runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;SELECT * INTO work FROM zasp_runtime_sandbox_search_outbox WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 now_value:=clock_timestamp();IF NOT zasp_authorization80_runtime.runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF;
 IF NOT FOUND OR (work.worker_id,work.lease_digest,work.attempt,work.receipt_digest) IS DISTINCT FROM (worker_value,digest(convert_to(token_value,'UTF8'),'sha256'),attempt_value,receipt_digest_value)
 OR (outcome_value='indexed' AND work.document_ids IS DISTINCT FROM document_values) OR (outcome_value<>'indexed' AND cardinality(document_values)<>0) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime session search checkpoint binding rejected';END IF;
 IF work.state='indexed' AND outcome_value='indexed' THEN
  IF NOT zasp_authorization80_runtime.runtime_sandbox_search_worker_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox search authority unavailable';END IF; PERFORM zasp_authorization80_runtime.require_current();
