END
$function$

CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_sandbox_search_heartbeat(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, token_value text, attempt_value integer, lease_seconds integer)
