CREATE OR REPLACE FUNCTION zasp_authorization80_runtime.runtime_sensor_heartbeat(locator_value bytea, secret_value bytea, audience_value text, sequence_value bigint, status_value text, capabilities_value jsonb, kernel_value text, btf_value boolean, event_rate_value bigint, drops_value bigint)
