 ELSE
  IF(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.run_id) IS DISTINCT FROM(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.run_id) THEN
   UPDATE zasp_authorization80_worker.run_state SET present=false WHERE(organization_id,workspace_id,environment_id,run_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.run_id);
   UPDATE zasp_authorization80_worker.test_state SET present=false WHERE(organization_id,workspace_id,environment_id,run_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.run_id);
  ELSE
   UPDATE zasp_authorization80_worker.run_state SET definition_id=NEW.definition_id,definition_version=NEW.definition_version,state=NEW.state,run_version=NEW.version
    WHERE(organization_id,workspace_id,environment_id,run_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.run_id);
   UPDATE zasp_authorization80_worker.test_state SET definition_id=NEW.definition_id,definition_version=NEW.definition_version,state=NEW.state,run_version=NEW.version
    WHERE(organization_id,workspace_id,environment_id,run_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.run_id);
  END IF;
 END IF;
 RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_capture_mutation(v public.zasp_workflow_idempotency)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE audit public.zasp_workflow_audit%ROWTYPE;s zasp_temporal72.schedules%ROWTYPE;r zasp_temporal72.runs%ROWTYPE;body jsonb;proof jsonb;g zasp_authorization80_worker.discovery_schedule_grants%ROWTYPE;BEGIN
 IF v.operation NOT IN('syncIntegration','putIntegrationSchedule') THEN RETURN;END IF;
 SELECT * INTO STRICT audit FROM public.zasp_workflow_audit a WHERE(a.organization_id,a.workspace_id,a.environment_id,a.audit_id,a.correlation_id,a.principal_id,a.operation)=(v.organization_id,v.workspace_id,v.environment_id,v.response->>'audit_id',v.response->>'correlation_id',v.principal_id,v.operation);
 body:=v.response->'body';
 IF body IS NULL OR jsonb_typeof(body)<>'object' OR audit.resource_version IS DISTINCT FROM(v.response->>'version')::bigint THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery mutation receipt rejected';END IF;
 proof:=jsonb_build_object('audit_id',audit.audit_id,'audit_digest',encode(digest(convert_to(jsonb_build_array(audit.organization_id,audit.workspace_id,audit.environment_id,audit.audit_id,audit.correlation_id,audit.principal_id,audit.operation,audit.resource_kind,audit.resource_id,audit.resource_version)::text,'UTF8'),'sha256'),'hex'),'idempotency_key',v.idempotency_key,'request_digest',encode(v.request_digest,'hex'),'response_digest',encode(digest(convert_to(v.response::text,'UTF8'),'sha256'),'hex'));
 IF v.operation='putIntegrationSchedule' THEN
  SELECT * INTO STRICT s FROM zasp_temporal72.schedules WHERE(organization_id,workspace_id,environment_id,integration_id)=(v.organization_id,v.workspace_id,v.environment_id,audit.resource_id);
  IF audit.resource_kind<>'integration_schedule' OR body->>'integration_id' IS DISTINCT FROM s.integration_id OR(body->>'version')::bigint IS DISTINCT FROM s.version OR(body->>'cadence_seconds')::integer IS DISTINCT FROM s.cadence_seconds OR body->>'state' IS DISTINCT FROM s.state OR(body->>'created_at')::timestamptz IS DISTINCT FROM s.created_at OR(body->>'updated_at')::timestamptz IS DISTINCT FROM s.updated_at OR s.state='enabled' AND(body->>'next_run_at')::timestamptz IS DISTINCT FROM s.anchor THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery schedule provenance prerequisite';END IF;
  g:=(s.organization_id,s.workspace_id,s.environment_id,s.id,s.version,v.principal_id,zasp_authorization80_worker.discovery72_schedule_identity(s),proof);
  INSERT INTO zasp_authorization80_worker.discovery_schedule_grants SELECT g.* ON CONFLICT DO NOTHING;
  IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.discovery_schedule_grants old WHERE old=g) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery schedule provenance changed';END IF;
 ELSE
  SELECT * INTO STRICT r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,sync_id)=(v.organization_id,v.workspace_id,v.environment_id,audit.resource_id);
  IF audit.resource_kind<>'integration_sync' OR body->>'id' IS DISTINCT FROM r.sync_id OR body->>'integration_id' IS DISTINCT FROM r.integration_id OR r.schedule_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_syncs y WHERE(y.organization_id,y.workspace_id,y.environment_id,y.id,y.principal_id,y.idempotency_key,y.trigger_kind)=(r.organization_id,r.workspace_id,r.environment_id,r.sync_id,v.principal_id,v.idempotency_key,'manual')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery manual provenance prerequisite';END IF;
  PERFORM zasp_authorization80_worker.discovery72_store_association(r,public.zasp_discovery_canonical_id(r.organization_id,r.workspace_id,r.environment_id,'discovery_sync_service',r.sync_id),v.principal_id,'manual',NULL,proof);
 END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_capture_scheduled(o text, w text, e text, j text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;s zasp_temporal72.schedules%ROWTYPE;g zasp_authorization80_worker.discovery_schedule_grants%ROWTYPE;BEGIN
 SELECT * INTO STRICT r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 SELECT * INTO STRICT s FROM zasp_temporal72.schedules WHERE(organization_id,workspace_id,environment_id,id,integration_id)=(o,w,e,r.schedule_id,r.integration_id);
 SELECT * INTO STRICT g FROM zasp_authorization80_worker.discovery_schedule_grants WHERE(organization_id,workspace_id,environment_id,schedule_id,version)=(o,w,e,s.id,s.version);
 IF s.state<>'enabled' OR s.updated_at>r.admitted_at OR r.scheduled_for<s.anchor OR g.identity IS DISTINCT FROM zasp_authorization80_worker.discovery72_schedule_identity(s) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery scheduled provenance prerequisite';END IF;
 PERFORM zasp_authorization80_worker.discovery72_store_association(r,s.id,g.grantor_id,'schedule',s.version,g.provenance);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_capture_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE old_value jsonb:=to_jsonb(OLD);new_value jsonb:=CASE WHEN TG_OP='DELETE' THEN NULL ELSE to_jsonb(NEW) END;keys text[];BEGIN
 IF TG_TABLE_SCHEMA='zasp_temporal72' AND TG_TABLE_NAME='runs' THEN
  IF TG_OP='DELETE' THEN UPDATE zasp_authorization80_worker.discovery_state SET present=false WHERE(organization_id,workspace_id,environment_id,job_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.job_id);
  ELSE UPDATE zasp_authorization80_worker.discovery_state SET state=NEW.state,current_source=current_source AND zasp_authorization80_worker.discovery72_admission_identity(OLD)=zasp_authorization80_worker.discovery72_admission_identity(NEW) WHERE(organization_id,workspace_id,environment_id,job_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.job_id);END IF;
 ELSIF TG_TABLE_SCHEMA='zasp_temporal72' AND TG_TABLE_NAME='schedules' THEN
  IF TG_OP='DELETE' OR zasp_authorization80_worker.discovery72_schedule_identity(OLD) IS DISTINCT FROM zasp_authorization80_worker.discovery72_schedule_identity(NEW) THEN
   UPDATE zasp_authorization80_worker.discovery_state st SET current_source=false FROM zasp_authorization80_worker.discovery_associations a WHERE(st.organization_id,st.workspace_id,st.environment_id,st.job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) AND(a.organization_id,a.workspace_id,a.environment_id,a.schedule_id)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.id);
  END IF;
 ELSE
  keys:=CASE TG_TABLE_NAME WHEN 'zasp_integrations' THEN ARRAY['organization_id','workspace_id','environment_id','id','kind','version','configuration','state','deleted_at'] WHEN 'zasp_integration_connections' THEN ARRAY['organization_id','workspace_id','environment_id','integration_id','id','provider','version','connection_reference','state','revoked_at'] WHEN 'zasp_discovery_connection_subjects' THEN ARRAY['organization_id','workspace_id','environment_id','integration_id','connection_id','provider','subject_kind','subject_id','connection_version','configuration_digest'] ELSE ARRAY['organization_id','workspace_id','environment_id','integration_id','id','provider','version','credential_class','credential_reference','status','metadata','expires_at','rotated_from_id'] END;
  IF TG_OP='DELETE' OR EXISTS(SELECT 1 FROM unnest(keys) k WHERE old_value->k IS DISTINCT FROM new_value->k) THEN
   UPDATE zasp_authorization80_worker.discovery_state st SET current_source=false FROM zasp_authorization80_worker.discovery_associations a WHERE(st.organization_id,st.workspace_id,st.environment_id,st.job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) AND(a.organization_id,a.workspace_id,a.environment_id,a.integration_id)=(old_value->>'organization_id',old_value->>'workspace_id',old_value->>'environment_id',CASE WHEN TG_TABLE_NAME='zasp_integrations' THEN old_value->>'id' ELSE old_value->>'integration_id' END);
  END IF;
 END IF;
 RETURN CASE WHEN TG_OP='DELETE' THEN OLD ELSE NEW END;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_execute(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE phase text:=q->>'operation';o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';j text:=q->>'job_id';i text:=q->>'integration_id';d text:=q->>'input_digest';budget timestamptz:=CASE WHEN q ? 'budget_us' THEN timestamptz 'epoch'+(q->>'budget_us')::bigint*interval '1 microsecond' END;p zasp_temporal72.page_effects%ROWTYPE;v zasp_temporal72.page_waits%ROWTYPE;a zasp_temporal72.apply_effects%ROWTYPE;BEGIN
 PERFORM zasp_authorization80_worker.require_discovery72(phase,q);
 CASE phase
 WHEN 'prepare_page' THEN RETURN zasp_temporal72.prepare_page(o,w,e,j,i,d,budget,(q->>'expected')::bigint,q->>'expected_digest');
 WHEN 'guard_page' THEN RETURN to_jsonb(zasp_temporal72.guard_page_effect(o,w,e,j,q->>'effect_id',budget));
 WHEN 'prepare_apply' THEN RETURN zasp_temporal72.prepare_apply(o,w,e,j,i,d,budget,q->>'complete_receipt');
 WHEN 'commit_apply' THEN RETURN zasp_temporal72.commit_apply(o,w,e,j,q->>'effect_id',budget);
 WHEN 'record_page' THEN RETURN zasp_authorization80_worker.discovery72_record_page(o,w,e,j,q->>'effect_id',q->'details');
 WHEN 'settle' THEN RETURN zasp_authorization80_worker.discovery72_settle(o,w,e,j,i,d,budget,q->>'reason',q->>'receipt');
 WHEN 'finish' THEN RETURN zasp_authorization80_worker.discovery72_finish(o,w,e,j,i,d,q->>'outcome',q->>'receipt');
 WHEN 'replay_page' THEN
  SELECT * INTO v FROM zasp_temporal72.page_waits WHERE(organization_id,workspace_id,environment_id,job_id,expected_version)=(o,w,e,j,(q->>'expected')::bigint);
  IF FOUND THEN IF v.expected_digest IS DISTINCT FROM q->>'expected_digest' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery wait replay conflict';END IF;RETURN jsonb_build_object('found',true,'value',jsonb_build_object('page',v.result));END IF;
  SELECT * INTO p FROM zasp_temporal72.page_effects WHERE(organization_id,workspace_id,environment_id,job_id,expected_version)=(o,w,e,j,(q->>'expected')::bigint);
  IF FOUND THEN IF p.expected_digest IS DISTINCT FROM q->>'expected_digest' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery page replay conflict';END IF;RETURN jsonb_build_object('found',true,'value',jsonb_build_object('page',COALESCE(p.result,jsonb_build_object('outcome','outcome_unknown'))));END IF;
 WHEN 'replay_apply' THEN
  SELECT * INTO a FROM zasp_temporal72.apply_effects WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
  IF FOUND THEN IF a.complete_digest IS DISTINCT FROM q->>'complete_receipt' THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery apply replay conflict';END IF;RETURN jsonb_build_object('found',true,'value',jsonb_build_object('result',COALESCE(a.result,jsonb_build_object('outcome','outcome_unknown'))));END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery phase closed';
 END CASE;
 RETURN jsonb_build_object('found',false);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_finish(o text, w text, e text, j text, i text, input_digest text, outcome_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE budget timestamptz;
BEGIN
 IF NOT zasp_authorization80_worker.discovery72_role(true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery captured session rejected';END IF;
 SELECT deadline INTO budget FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id,integration_id)=(o,w,e,j,i);
 RETURN zasp_authorization80_worker.discovery72_settle(o,w,e,j,i,input_digest,budget,outcome_value,receipt_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_human_begin(op text, o text, w text, e text, actor text, i text, k text, a text, c text, receipt text, request jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb:=zasp_authorization80.context();m jsonb;delta bigint:=0;s record;BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF op NOT IN('syncIntegration','putIntegrationSchedule','deleteIntegrationSchedule') OR p IS NULL OR NULLIF(current_setting('zasp.discovery72_human',true),'') IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery human entry rejected';END IF;
 m:=jsonb_build_object('domain','discovery72-human-v1','stage','entry','key_version',p->>'key_version','proof_digest',encode(digest(convert_to(p::text,'UTF8'),'sha256'),'hex'),'organization_id',o,'workspace_id',w,'environment_id',e,'actor',actor,'integration_id',i,'operation',op,'idempotency_key',k,'audit_id',a,'correlation_id',c,'receipt_id',receipt,'request',request);
 PERFORM zasp_authorization80_worker.discovery72_human_check(m,0);
 IF op='syncIntegration' THEN delta:=1;
 ELSE
  -- Prelock every affected capture under the held org revision. Already-false
  -- rows remain false and capture_revision does not touch for those updates.
  FOR s IN SELECT st.* FROM zasp_authorization80_worker.discovery_state st JOIN zasp_authorization80_worker.discovery_associations x USING(organization_id,workspace_id,environment_id,job_id)
   JOIN zasp_temporal72.schedules n ON(n.organization_id,n.workspace_id,n.environment_id,n.id)=(x.organization_id,x.workspace_id,x.environment_id,x.schedule_id)
   WHERE(n.organization_id,n.workspace_id,n.environment_id,n.integration_id)=(o,w,e,i) ORDER BY st.job_id FOR UPDATE OF st LOOP
   IF s.current_source THEN delta:=delta+1;END IF;
  END LOOP;
 END IF;
 PERFORM zasp_authorization80_worker.discovery72_human_check(m,0);
 PERFORM zasp_authorization80_worker.discovery72_human_save(m||jsonb_build_object('mutation_delta',delta));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_human_check(m jsonb, delta bigint)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE p jsonb:=zasp_authorization80.context();target_version bigint;BEGIN
 IF current_setting('transaction_isolation')<>'read committed' OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal72.current_ready()
 OR p IS NULL OR NOT EXISTS(SELECT 1 FROM zasp_temporal72.principals WHERE authority_role='zasp_discovery_api' AND principal_name=session_user)
 OR NOT COALESCE(zasp_authorization80.read_request(m->>'organization_id',m->>'workspace_id',m->>'environment_id',ARRAY[m->>'operation'],'manage_workflows',false,m->>'actor')
 AND NOT(p->>'collection')::boolean AND p#>>'{path_parameters,id}'=m->>'integration_id'
 AND zasp_authorization80.allowed(m->>'organization_id',m->>'workspace_id',m->>'environment_id','integration',m->>'integration_id'),false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery current human authority required';END IF;
 -- The initial fence owns this revision row. Every later check admits only
 -- the measured local mutation delta, with all other pins unchanged.
 PERFORM 1 FROM zasp_authorization79.organizations x WHERE x.organization_id=m->>'organization_id'
 AND(x.desired,x.applied,x.generation,x.store_id,x.model_id)=((p#>>'{revision,desired}')::bigint+delta,(p#>>'{revision,applied}')::bigint,(p#>>'{revision,generation}')::bigint,p#>>'{revision,store_id}',p#>>'{revision,model_id}') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery human revision changed';END IF;
 SELECT version INTO target_version FROM public.zasp_integrations WHERE(organization_id,workspace_id,environment_id,id)=(m->>'organization_id',m->>'workspace_id',m->>'environment_id',m->>'integration_id') AND deleted_at IS NULL AND state<>'deleted' FOR SHARE;
 IF target_version IS NULL OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(p->'targets') t WHERE(t->>'organization_id',t->>'workspace_id',t->>'environment_id',t->>'kind',COALESCE(NULLIF(t->>'source_id',''),t->>'id'),(t->>'version')::bigint)=(m->>'organization_id',m->>'workspace_id',m->>'environment_id','integration',m->>'integration_id',target_version)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery human target changed';END IF;
 PERFORM zasp_authorization80.identity_fence(p);
 IF zasp_authorization80.context() IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery human proof expired';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_human_marker()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE m jsonb;p jsonb;seal text;expected_seal text;BEGIN
 m:=NULLIF(current_setting('zasp.discovery72_human',true),'')::jsonb;p:=zasp_authorization80.context();
 seal:=NULLIF(current_setting('zasp.discovery72_human_seal',true),'');expected_seal:=zasp_authorization80.context_seal(m);
 IF m IS NULL OR p IS NULL OR m->>'domain' IS DISTINCT FROM 'discovery72-human-v1'
 OR seal IS NULL OR expected_seal IS NULL OR seal IS DISTINCT FROM expected_seal
 OR m->>'proof_digest' IS DISTINCT FROM encode(digest(convert_to(p::text,'UTF8'),'sha256'),'hex')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery human invocation rejected';END IF;
 RETURN m;
EXCEPTION WHEN data_exception THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery human invocation rejected';
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_mutation_capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF NEW.operation NOT IN('syncIntegration','putIntegrationSchedule') THEN RETURN NULL;END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_temporal72.principals WHERE principal_name=session_user AND authority_role='zasp_discovery_api') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery provenance API session rejected';END IF;
 PERFORM zasp_authorization80_worker.discovery72_human_capture(NEW);
 PERFORM zasp_authorization80_worker.discovery72_capture_mutation(NEW);RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_record_page(o text, w text, e text, j text, effect_value text, details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;p zasp_temporal72.page_effects%ROWTYPE;outcome_value text;digest_value text;raw_digest text;result_value jsonb;next_version bigint;delay_value integer;cursor_value jsonb;manifest_value jsonb;scope_prefix text;sync_row public.zasp_discovery_syncs%ROWTYPE;
BEGIN
 IF NOT zasp_authorization80_worker.discovery72_role(true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery captured session rejected';END IF;
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery receipt scope rejected';END IF;
 SELECT * INTO p FROM zasp_temporal72.page_effects WHERE(organization_id,workspace_id,environment_id,job_id,effect_id)=(o,w,e,j,effect_value) FOR UPDATE;
 IF NOT FOUND OR details IS NULL OR jsonb_typeof(details)<>'object' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery receipt rejected';END IF;
 outcome_value:=details->>'outcome';
 IF outcome_value IS NULL OR outcome_value NOT IN('partial','complete','incomplete','retryable','denied','revoked','malformed','terminal','cancelled','outcome_unknown') OR details-(CASE WHEN outcome_value='complete' THEN ARRAY['outcome','cursor','manifest','candidate'] WHEN outcome_value='partial' THEN ARRAY['outcome','cursor','manifest'] ELSE ARRAY['outcome','retry_after_seconds'] END)<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery page outcome rejected';END IF;
 delay_value:=COALESCE((details->>'retry_after_seconds')::integer,0);
 IF outcome_value='retryable' AND delay_value NOT BETWEEN 1 AND 900 OR outcome_value<>'retryable' AND delay_value<>0 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery retry delay rejected';END IF;
 digest_value:=encode(digest(convert_to(jsonb_build_object('effect_id',effect_value,'details',details)::text,'UTF8'),'sha256'),'hex');
 raw_digest:=digest_value;
 IF p.result IS NOT NULL THEN
  IF p.record_digest IS DISTINCT FROM digest_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery receipt immutable';END IF;RETURN p.result;
 END IF;
 IF(r.checkpoint_version,r.checkpoint_digest) IS DISTINCT FROM(p.expected_version,p.expected_digest) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery receipt precondition conflict';END IF;
 IF outcome_value IN('partial','complete') THEN
  cursor_value:=details->'cursor';manifest_value:=details->'manifest';scope_prefix:='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/';
  SELECT * INTO STRICT sync_row FROM public.zasp_discovery_syncs WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,r.sync_id);
  IF NOT COALESCE(jsonb_typeof(cursor_value)='object' AND cursor_value ?& ARRAY['provider','version','value'] AND cursor_value-ARRAY['provider','version','value']='{}'::jsonb AND cursor_value->>'provider'=r.provider AND cursor_value->>'version' ~ '^[a-z][a-z0-9_.-]{1,63}$' AND length(cursor_value->>'value') BETWEEN 1 AND 2048
  AND jsonb_typeof(manifest_value)='object' AND manifest_value ?& ARRAY['reference','key','version_id','checksum','size_bytes','media_type','schema_version','parser_version','tool_version'] AND manifest_value-ARRAY['reference','key','version_id','checksum','size_bytes','media_type','schema_version','parser_version','tool_version']='{}'::jsonb
  AND public.zasp_discovery_s3_object_reference(manifest_value->>'reference') AND substring(manifest_value->>'reference' FROM '^s3://[a-z0-9][a-z0-9.-]{2,62}/(.+)$')=manifest_value->>'key' AND starts_with(manifest_value->>'key',scope_prefix) AND public.zasp_valid_product_id(substring(manifest_value->>'key' FROM length(scope_prefix)+1))
  AND length(manifest_value->>'version_id') BETWEEN 1 AND 1024 AND manifest_value->>'version_id' !~ '[[:space:][:cntrl:]]' AND manifest_value->>'checksum' ~ '^[0-9a-f]{64}$' AND manifest_value->>'checksum'<>repeat('0',64) AND (manifest_value->>'size_bytes')::bigint BETWEEN 1 AND 536870912
  AND manifest_value->>'media_type'='application/json' AND manifest_value->>'schema_version' ~ '^[a-z][a-z0-9_.-]{1,63}$' AND(manifest_value->>'parser_version',manifest_value->>'tool_version')=(sync_row.parser_version,sync_row.tool_version),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery partial manifest rejected';END IF;
  IF outcome_value='complete' AND NOT COALESCE(jsonb_typeof(details->'candidate')='object' AND (details->'candidate') ?& ARRAY['entities','relationships','evidence'] AND (details->'candidate')-ARRAY['entities','relationships','evidence']='{}'::jsonb AND jsonb_typeof(details->'candidate'->'entities')='array' AND jsonb_typeof(details->'candidate'->'relationships')='array' AND jsonb_typeof(details->'candidate'->'evidence')='array' AND jsonb_array_length(details->'candidate'->'entities')<=1000 AND jsonb_array_length(details->'candidate'->'relationships')<=2000 AND jsonb_array_length(details->'candidate'->'evidence')<=1000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery complete candidate rejected';END IF;
  IF outcome_value='complete' THEN
   details:=jsonb_set(details,'{candidate,relationships}',zasp_temporal72.normalize_relationships(o,w,e,r.integration_id,r.provider,details->'candidate'->'relationships'));
   digest_value:=encode(digest(convert_to(jsonb_build_object('effect_id',effect_value,'details',details)::text,'UTF8'),'sha256'),'hex');
  END IF;
  INSERT INTO zasp_temporal72.checkpoints(organization_id,workspace_id,environment_id,job_id,version,digest,effect_id,cursor,manifest,candidate) VALUES(o,w,e,j,1,digest_value,effect_value,cursor_value,manifest_value,details->'candidate')
  ON CONFLICT(organization_id,workspace_id,environment_id,job_id) DO UPDATE SET version=zasp_temporal72.checkpoints.version+1,digest=excluded.digest,effect_id=excluded.effect_id,cursor=excluded.cursor,manifest=excluded.manifest,candidate=excluded.candidate;
 END IF;
 next_version:=r.checkpoint_version+CASE WHEN outcome_value IN('partial','retryable') THEN 1 ELSE 0 END;
 result_value:=jsonb_build_object('outcome',outcome_value,'checkpoint_version',next_version,'receipt_digest',digest_value,'retry_after_seconds',delay_value);
 UPDATE zasp_temporal72.page_effects SET result=result_value,record_digest=raw_digest,recorded_at=clock_timestamp() WHERE(organization_id,workspace_id,environment_id,job_id,effect_id)=(o,w,e,j,effect_value);
 UPDATE zasp_temporal72.runs SET state=outcome_value,checkpoint_version=next_version,checkpoint_digest=digest_value,retry_not_before=CASE WHEN outcome_value='retryable' THEN clock_timestamp()+make_interval(secs=>delay_value) END WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 IF outcome_value='retryable' THEN
  UPDATE public.zasp_discovery_syncs SET state='queued',last_error='discovery retryable',last_error_code='retryable' WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,r.sync_id) AND state='running';
 END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_record_public_mutation(o text, w text, e text, actor text, op text, k text, intent jsonb, body jsonb, kind text, id text, version_value bigint, a text, c text, receipt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE m jsonb:=zasp_authorization80_worker.discovery72_human_marker();result jsonb;response jsonb;delta bigint;BEGIN
 IF m->>'stage' IS DISTINCT FROM 'entry' OR(o,w,e,actor,op,k,a,c,receipt) IS DISTINCT FROM(m->>'organization_id',m->>'workspace_id',m->>'environment_id',m->>'actor',m->>'operation',m->>'idempotency_key',m->>'audit_id',m->>'correlation_id',m->>'receipt_id')
 OR intent->'scope' IS DISTINCT FROM jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e)
 OR(intent->>'integration_id',intent->>'idempotency_key',intent->'expected_version') IS DISTINCT FROM(m->>'integration_id',k,m#>'{request,expected}')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery mutation invocation rejected';END IF;
 IF op='syncIntegration' THEN
  IF kind<>'integration_sync' OR id IS DISTINCT FROM m#>>'{request,sync_id}' OR body->>'id' IS DISTINCT FROM id OR intent->'body' IS DISTINCT FROM '{}'::jsonb
  OR NOT EXISTS(SELECT 1 FROM zasp_temporal72.runs r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.job_id,r.sync_id,r.integration_id,r.outbox_id,encode(r.request_digest,'hex'))=(o,w,e,m#>>'{request,job_id}',id,m->>'integration_id',m#>>'{request,outbox_id}',m#>>'{request,request_digest}')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery manual invocation changed';END IF;
 ELSE
  IF kind<>'integration_schedule' OR id IS DISTINCT FROM m->>'integration_id' OR body->>'integration_id' IS DISTINCT FROM id OR version_value IS DISTINCT FROM(m#>>'{request,expected}')::bigint+1
  OR(op='putIntegrationSchedule' AND intent->'body' IS DISTINCT FROM jsonb_build_object('cadence_seconds',m#>'{request,cadence}','state',m#>'{request,state}')) OR(op='deleteIntegrationSchedule' AND intent->'body' IS DISTINCT FROM '{}'::jsonb)
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery schedule invocation changed';END IF;
 END IF;
 delta:=(m->>'mutation_delta')::bigint;PERFORM zasp_authorization80_worker.discovery72_human_check(m,delta);
 response:=jsonb_build_object('body',body,'version',version_value,'audit_id',a,'correlation_id',c,'receipt_id',receipt);
 m:=m||jsonb_build_object('stage','recording','intent_digest',encode(digest(convert_to(intent::text,'UTF8'),'sha256'),'hex'),'response_digest',encode(digest(convert_to(response::text,'UTF8'),'sha256'),'hex'));
 PERFORM zasp_authorization80_worker.discovery72_human_save(m);
 result:=public.zasp_execution_record_public_mutation(o,w,e,actor,op,k,intent,body,kind,id,version_value,a,c,receipt);
 PERFORM zasp_authorization80_worker.discovery72_human_check(m,delta+CASE WHEN op='syncIntegration' THEN 1 ELSE 0 END);
 IF result-'replayed' IS DISTINCT FROM response OR result->'replayed' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery mutation receipt changed';END IF;
 PERFORM zasp_authorization80_worker.discovery72_human_clear();RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_role(compensation boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF compensation IS NULL OR current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='discovery worker isolation rejected';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal72.current_ready() THEN RETURN false;END IF;
 RETURN CASE WHEN compensation THEN zasp_temporal68.principal_ready('zasp_temporal_compensation') ELSE EXISTS(SELECT 1 FROM zasp_temporal72.principals WHERE principal_name=session_user AND authority_role='zasp_discovery_worker') END;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_settle(o text, w text, e text, j text, i text, input_digest text, budget timestamp with time zone, reason text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;a zasp_temporal72.apply_effects%ROWTYPE;result_value jsonb;outcome_value text;
BEGIN
 IF NOT zasp_authorization80_worker.discovery72_role(true) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery captured session rejected';END IF;
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id,integration_id)=(o,w,e,j,i) FOR UPDATE;
 IF NOT FOUND OR input_digest IS DISTINCT FROM encode(r.request_digest,'hex') OR budget IS NULL OR budget IS DISTINCT FROM r.deadline OR reason IS NULL OR reason NOT IN('succeeded','incomplete','retryable','denied','revoked','malformed','terminal','cancelled','outcome_unknown','deadline','activity_failed','apply_uncertain','settlement_uncertain') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery settlement rejected';END IF;
 SELECT * INTO a FROM zasp_temporal72.apply_effects WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 IF a.result IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.zasp_discovery_generation_reservations g JOIN public.zasp_discovery_snapshots s ON(s.organization_id,s.workspace_id,s.environment_id,s.id,s.integration_id,s.sync_id,s.source,s.generation)=(g.organization_id,g.workspace_id,g.environment_id,g.snapshot_id,g.integration_id,g.sync_id,g.source,g.generation) JOIN public.zasp_discovery_snapshot_inputs si ON(si.organization_id,si.workspace_id,si.environment_id,si.snapshot_id)=(s.organization_id,s.workspace_id,s.environment_id,s.id) JOIN public.zasp_discovery_syncs sy ON(sy.organization_id,sy.workspace_id,sy.environment_id,sy.id)=(s.organization_id,s.workspace_id,s.environment_id,s.sync_id) WHERE(g.organization_id,g.workspace_id,g.environment_id,g.sync_id)=(o,w,e,r.sync_id) AND s.complete AND s.state='complete' AND sy.state='succeeded' AND sy.snapshot_id=s.id AND encode(si.candidate_digest,'hex')=a.result->>'receipt_digest') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='discovery committed evidence inconsistent';END IF;
  IF reason='succeeded' AND receipt_value IS DISTINCT FROM a.result->>'receipt_digest' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery completion receipt rejected';END IF;
  RETURN a.result;
 END IF;
 IF reason='succeeded' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery success evidence missing';END IF;
 IF a.effect_id IS NOT NULL OR EXISTS(SELECT 1 FROM zasp_temporal72.page_effects WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j) AND(result IS NULL OR result->>'outcome'='outcome_unknown')) THEN outcome_value:='outcome_unknown';
 ELSE outcome_value:=CASE WHEN reason IN('denied','revoked','malformed','terminal') THEN reason ELSE 'incomplete' END;END IF;
 UPDATE zasp_temporal72.runs SET state=outcome_value WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 UPDATE public.zasp_discovery_syncs SET state='failed',completed_at=COALESCE(completed_at,clock_timestamp()),last_error='discovery '||outcome_value,last_error_code=CASE WHEN outcome_value='incomplete' THEN 'partial' ELSE outcome_value END WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,r.sync_id) AND state IN('queued','running');
 PERFORM public.zasp_execution_bump_freshness(o,w,e,i);
 RETURN jsonb_build_object('outcome',outcome_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_source(phase text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a zasp_authorization80_worker.discovery_associations%ROWTYPE;r zasp_temporal72.runs%ROWTYPE;s zasp_authorization80_worker.discovery_state%ROWTYPE;extra text[];page_value jsonb;apply_value jsonb;wait_value jsonb;compensation boolean:=phase IN('record_page','settle','finish','replay_page','replay_apply');checks jsonb:='[]'::jsonb;BEGIN
 IF phase IS NULL OR phase NOT IN('prepare_page','guard_page','prepare_apply','commit_apply','record_page','settle','finish','replay_page','replay_apply') OR NOT zasp_authorization80_worker.discovery72_role(compensation) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery worker phase/session rejected';END IF;
 extra:=CASE phase WHEN 'prepare_page' THEN ARRAY['budget_us','expected','expected_digest'] WHEN 'replay_page' THEN ARRAY['budget_us','expected','expected_digest'] WHEN 'guard_page' THEN ARRAY['effect_id','budget_us'] WHEN 'prepare_apply' THEN ARRAY['budget_us','complete_receipt'] WHEN 'replay_apply' THEN ARRAY['budget_us','complete_receipt'] WHEN 'commit_apply' THEN ARRAY['effect_id','budget_us'] WHEN 'record_page' THEN ARRAY['effect_id','details'] WHEN 'settle' THEN ARRAY['budget_us','reason','receipt'] WHEN 'finish' THEN ARRAY['outcome','receipt'] END;
 IF q->>'operation' IS DISTINCT FROM phase OR octet_length(q::text)>(CASE WHEN phase='record_page' THEN 67174400 ELSE 4096 END) OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','job_id','integration_id','input_digest','operation']||extra) OR EXISTS(SELECT 1 FROM jsonb_each(q) WHERE value='null'::jsonb) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery request rejected';END IF;
 SELECT * INTO a FROM zasp_authorization80_worker.discovery_associations WHERE(organization_id,workspace_id,environment_id,job_id,integration_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'job_id',q->>'integration_id');
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) FOR SHARE;
 SELECT * INTO s FROM zasp_authorization80_worker.discovery_state WHERE(organization_id,workspace_id,environment_id,job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) FOR SHARE;
 IF a.job_id IS NULL OR r.job_id IS NULL OR s.job_id IS NULL OR NOT s.present OR a.admission IS DISTINCT FROM zasp_authorization80_worker.discovery72_admission_identity(r) OR a.admission->>'request_digest' IS DISTINCT FROM q->>'input_digest' OR s.state IS DISTINCT FROM r.state OR a.deadline IS DISTINCT FROM r.deadline OR q ? 'budget_us' AND q->'budget_us' IS DISTINCT FROM to_jsonb(floor(extract(epoch FROM r.deadline)*1000000)::bigint) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery captured source rejected';END IF;
 IF NOT compensation THEN
  IF NOT s.current_source OR a.authority_until<=clock_timestamp() OR s.authority_until IS DISTINCT FROM a.authority_until OR a.credential_facts IS DISTINCT FROM zasp_authorization80_worker.discovery72_credentials(r) OR r.state NOT IN('admitted','collecting','partial','retryable','complete','applying') OR NOT EXISTS(SELECT 1 FROM public.zasp_identity_memberships WHERE(organization_id,principal_id,active)=(a.organization_id,a.grantor_id,true)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery delegation revoked';END IF;
  PERFORM zasp_temporal72.require_current_run(r,r.deadline);
  IF a.schedule_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM zasp_temporal72.schedules n JOIN zasp_authorization80_worker.discovery_schedule_grants g ON(g.organization_id,g.workspace_id,g.environment_id,g.schedule_id,g.version)=(n.organization_id,n.workspace_id,n.environment_id,n.id,n.version) WHERE(n.organization_id,n.workspace_id,n.environment_id,n.id,n.version,n.state)=(a.organization_id,a.workspace_id,a.environment_id,a.schedule_id,a.schedule_version,'enabled') AND g.identity=zasp_authorization80_worker.discovery72_schedule_identity(n) AND g.provenance=a.provenance) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery schedule delegation changed';END IF;
  checks:=jsonb_build_array(jsonb_build_object('kind','integration','id',a.integration_id,'permission','manage_workflows'),jsonb_build_object('kind','integration','id',a.integration_id,'permission','view'));
 END IF;
 IF phase IN('prepare_page','replay_page') AND(q->>'expected' !~ '^[0-9]+$' OR(q->>'expected')::bigint NOT BETWEEN 0 AND 9999 OR jsonb_typeof(q->'expected_digest') IS DISTINCT FROM 'string') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery checkpoint shape rejected';END IF;
 SELECT jsonb_build_object('effect_id',p.effect_id,'expected',p.expected_version,'expected_digest',p.expected_digest,'record_digest',p.record_digest,'result',p.result) INTO page_value FROM zasp_temporal72.page_effects p WHERE(p.organization_id,p.workspace_id,p.environment_id,p.job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) AND(CASE WHEN phase IN('prepare_page','replay_page') THEN p.expected_version=(q->>'expected')::bigint ELSE p.effect_id=q->>'effect_id' END) FOR SHARE;
 SELECT jsonb_build_object('effect_id',v.effect_id,'complete_digest',v.complete_digest,'result',v.result) INTO apply_value FROM zasp_temporal72.apply_effects v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.job_id)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id) FOR SHARE;
 IF phase IN('prepare_page','replay_page') THEN SELECT jsonb_build_object('expected',v.expected_version,'expected_digest',v.expected_digest,'result',v.result) INTO wait_value FROM zasp_temporal72.page_waits v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.job_id,v.expected_version)=(a.organization_id,a.workspace_id,a.environment_id,a.job_id,(q->>'expected')::bigint) FOR SHARE;END IF;
 IF phase IN('guard_page','record_page') AND page_value IS NULL OR phase='commit_apply' AND(apply_value IS NULL OR apply_value->>'effect_id' IS DISTINCT FROM q->>'effect_id') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery prepared effect absent';END IF;
 -- Native entries are independently callable, so their single fence must
 -- refresh authority after every source lock, not rely on the dispatcher.
 IF NOT compensation AND a.authority_until<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery authority expired after source locks';END IF;
 RETURN jsonb_build_object('organization_id',a.organization_id,'workspace_id',a.workspace_id,'environment_id',a.environment_id,'run_id',a.job_id,'task_id',a.sync_id,'principal_id',a.principal_id,'grantor_id',a.grantor_id,'trigger_kind',a.source_kind,'target_kind','integration','target_id',a.integration_id,'session_user',session_user,'checks',checks,'admission',a.admission,'provenance',a.provenance,'state',r.state,'checkpoint_version',r.checkpoint_version,'checkpoint_digest',r.checkpoint_digest,'page',page_value,'apply',apply_value,'wait',wait_value,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.discovery72_store_association(r zasp_temporal72.runs, principal text, grantor text, kind text, schedule_version bigint, provenance jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a zasp_authorization80_worker.discovery_associations%ROWTYPE;credentials jsonb;until_value timestamptz;BEGIN
 IF r.job_id IS NULL OR NOT public.zasp_valid_product_id(principal) OR NOT public.zasp_valid_product_id(grantor) OR provenance IS NULL OR kind NOT IN('manual','schedule')
 OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_syncs s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.id,s.integration_id,s.request_digest,s.trigger_kind)=(r.organization_id,r.workspace_id,r.environment_id,r.sync_id,r.integration_id,r.request_digest,kind)
 AND s.principal_id=CASE kind WHEN 'manual' THEN grantor ELSE principal END)
 OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_outbox b WHERE(b.organization_id,b.workspace_id,b.environment_id,b.id,b.topic)=(r.organization_id,r.workspace_id,r.environment_id,r.outbox_id,'discovery-jobs') AND b.payload=jsonb_build_object('organization_id',r.organization_id,'workspace_id',r.workspace_id,'environment_id',r.environment_id,'job_id',r.job_id,'sync_id',r.sync_id,'integration_id',r.integration_id,'request_digest',encode(r.request_digest,'hex')) AND b.payload_digest=digest(convert_to(b.payload::text,'UTF8'),'sha256'))
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery admission provenance rejected';END IF;
 credentials:=zasp_authorization80_worker.discovery72_credentials(r);
 SELECT LEAST(r.deadline,min(c.expires_at)) INTO until_value FROM public.zasp_connector_credentials c WHERE(c.organization_id,c.workspace_id,c.environment_id,c.integration_id,c.provider,c.credential_reference)=(r.organization_id,r.workspace_id,r.environment_id,r.integration_id,r.provider,r.credential_reference);
 a:=(r.organization_id,r.workspace_id,r.environment_id,r.job_id,r.sync_id,r.integration_id,principal,grantor,kind,r.schedule_id,schedule_version,zasp_authorization80_worker.discovery72_admission_identity(r),provenance,r.deadline,credentials,until_value);
 INSERT INTO zasp_authorization80_worker.discovery_associations SELECT a.* ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.discovery_associations old WHERE old=a) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery captured admission changed';END IF;
 INSERT INTO zasp_authorization80_worker.discovery_state VALUES(r.organization_id,r.workspace_id,r.environment_id,r.job_id,r.state,true,true,r.deadline,until_value) ON CONFLICT DO NOTHING;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.finding_facts(operation_value text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal78.run_owners%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;g zasp_temporal78.service_grants%ROWTYPE;a zasp_authorization80_worker.associations%ROWTYPE;grantor text;principal_value text;source_hash text;p jsonb;checks jsonb;receipt_hash text;cleanup boolean:=operation_value='finding.cleanup';replay boolean:=operation_value='finding.replay';
BEGIN
 IF operation_value NOT IN('finding.prepare','finding.apply','finding.replay','finding.cleanup','finding.planning') OR NOT zasp_temporal78.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.principal_ready(CASE WHEN cleanup THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker source reader rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest']||CASE WHEN cleanup THEN ARRAY['reason'] ELSE ARRAY[]::text[] END) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker source reference rejected';END IF;
 x:=zasp_temporal78.start_identity(q-'reason');
 SELECT * INTO STRICT r FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 principal_value:=public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_definition_service',x.definition_id);
 source_hash:=encode(digest(convert_to(jsonb_build_array(x.source_kind,x.definition_id,x.definition_version,x.input_digest,encode(x.snapshot_digest,'hex'))::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO a FROM zasp_authorization80_worker.associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF cleanup OR replay THEN
  IF a.run_id IS NULL OR(a.principal_id,a.definition_id,a.definition_version,a.finding_id,a.source_digest) IS DISTINCT FROM(principal_value,x.definition_id,x.definition_version,x.trigger_id,source_hash)
   OR NOT EXISTS(SELECT 1 FROM zasp_temporal78.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) AND NOT(cleanup AND(r.state='queued' OR EXISTS(SELECT 1 FROM zasp_temporal78.stops WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)))) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured cleanup unavailable';END IF;
  grantor:=a.grantor_id;checks:='[]'::jsonb;
  IF replay THEN receipt_hash:=encode(digest(convert_to(zasp_temporal78.effect_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id)::text,'UTF8'),'sha256'),'hex');END IF;
  -- Queued cancellation settles the already captured native start intent.
  -- Repeats require the immutable stop receipt, never a bare cancelled state.
  IF cleanup AND EXISTS(SELECT 1 FROM zasp_temporal78.stops WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN receipt_hash:=encode(digest(convert_to(zasp_temporal78.stop_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id)::text,'UTF8'),'sha256'),'hex');END IF;
 ELSE
  IF r.state NOT IN('queued','planning','waiting_approval') OR EXISTS(SELECT 1 FROM zasp_authorization80_worker.revocations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker task inactive';END IF;
  -- Existing context validates immutable78/66/65 provenance, native definition,
  -- grantor membership/scope, target snapshot and current source controls. Its
  -- tenant body stays inside SQL; only typed authority metadata leaves here.
  PERFORM zasp_temporal78.context(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
  IF x.source_kind='automatic77' THEN
   SELECT * INTO STRICT g FROM zasp_temporal78.service_grants WHERE(organization_id,workspace_id,environment_id,definition_id,definition_version)=(x.organization_id,x.workspace_id,x.environment_id,x.definition_id,x.definition_version) FOR SHARE;
   principal_value:=g.principal_id;grantor:=g.grantor_id;
  ELSE grantor:=r.requested_by;END IF;
  IF operation_value='finding.apply' THEN PERFORM zasp_temporal78.current_step(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id);END IF;
  checks:=jsonb_build_array(jsonb_build_object('kind','finding','id',x.trigger_id,'permission',CASE operation_value WHEN 'finding.planning' THEN 'view' ELSE 'manage_findings' END),jsonb_build_object('kind','security_agent','id',x.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',x.run_id,'permission','manage_workflows'));
 END IF;
 SELECT jsonb_build_object('plan_hash',encode(plan_hash,'hex'),'step_digest',encode(s.input_digest,'hex')) INTO p FROM public.zasp_security_agent_plans p JOIN public.zasp_security_agent_steps s USING(organization_id,workspace_id,environment_id,run_id) WHERE(p.organization_id,p.workspace_id,p.environment_id,p.run_id,s.step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id);
 RETURN jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'step_id',x.step_id,'effect_id',public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_effect',x.run_id||chr(31)||x.step_id||chr(31)||x.action_key),'principal_id',principal_value,'grantor_id',grantor,'definition_id',x.definition_id,'definition_version',x.definition_version,'finding_id',x.trigger_id,'target_version',x.trigger_version,'source_digest',source_hash,'run_version',r.version,'run_state',r.state,'plan',p,'checks',checks,'session_user',session_user,'receipt_digest',receipt_hash);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.finding_source(operation_value text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE f jsonb;BEGIN
 IF operation_value NOT IN('finding.apply','finding.replay','finding.cleanup','finding.planning') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker operation rejected';END IF;
 f:=zasp_authorization80_worker.finding_facts(operation_value,q);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.associations a WHERE(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.principal_id,a.grantor_id,a.source_digest)=(f->>'organization_id',f->>'workspace_id',f->>'environment_id',f->>'run_id',f->>'principal_id',f->>'grantor_id',f->>'source_digest')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker association missing';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.run_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(f->>'organization_id',f->>'workspace_id',f->>'environment_id',f->>'run_id',f->>'definition_id',(f->>'definition_version')::bigint,f->>'run_state',(f->>'run_version')::bigint,true)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker run capture changed';END IF;
 RETURN f;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered62_decide_inner(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;actor text;op text;k text;keys text[];d public.zasp_security_agent_definitions%ROWTYPE;
 prior public.zasp_security_agent_request_receipts%ROWTYPE;r text;a text;receipt_id text;evidence jsonb;result_value jsonb;audit_body jsonb;items jsonb:='[]';item record;next_value text;
 inner_q jsonb;inner_result jsonb;resource_value jsonb;was_replay boolean;approval_row public.zasp_security_agent_approvals%ROWTYPE;run_row public.zasp_security_agent_runs%ROWTYPE;
BEGIN
 IF q->>'operation' IS DISTINCT FROM 'decide' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='private ordered approval operation rejected';END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='public ordered requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 PERFORM 1 FROM zasp_ordered_public62.registration FOR SHARE;
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered principal rejected';END IF;
 IF NOT COALESCE(zasp_authorization80_worker.ordered62_inner_ready(c,f),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public ordered release unavailable';END IF;
 IF q IS NULL OR octet_length(q::text)>16384 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered request rejected';END IF;
 IF q->>'operation'='deployment_ready' THEN
  IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['operation']) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered deployment request rejected';END IF;
  IF NOT COALESCE(zasp_ordered_public62.ready(c,f),false) OR NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public ordered deployment unavailable';END IF;
  RETURN jsonb_build_object('contract_version',62,'ready',true);
 END IF;
 op:=q->>'operation';keys:=ARRAY['organization_id','workspace_id','environment_id','actor_id','operation'];
 CASE op WHEN 'ready' THEN NULL; WHEN 'activate' THEN keys:=keys||ARRAY['definition_id','definition_version'];
 WHEN 'resource_activation' THEN keys:=keys||ARRAY['definition_id'];
 WHEN 'classify_mutation' THEN keys:=keys||ARRAY['mutation_kind','definition_id','idempotency_key'];IF q->>'mutation_kind'='trigger' THEN keys:=keys||ARRAY['trigger'];END IF;
 WHEN 'classify_trigger_key' THEN keys:=keys||ARRAY['definition_id','idempotency_key'];
 WHEN 'activate_resource' THEN keys:=keys||ARRAY['definition_id','definition_version','activation','idempotency_key'];
 WHEN 'trigger_resource' THEN keys:=keys||ARRAY['definition_id','definition_version','trigger_id','trigger_version','trigger_kind','trigger_source','idempotency_key'];
 WHEN 'resource_run' THEN keys:=keys||ARRAY['run_id'];
 WHEN 'resource_approval' THEN keys:=keys||ARRAY['approval_id'];
 WHEN 'decide_resource' THEN keys:=keys||ARRAY['approval_id','approval_version','decision','fresh_auth_at','idempotency_key'];
 WHEN 'trigger' THEN keys:=keys||ARRAY['definition_id','definition_version','trigger_id','trigger_version','idempotency_key'];
 WHEN 'decide' THEN keys:=keys||ARRAY['run_id','run_version','approval_id','approval_version','decision','fresh_auth_at','idempotency_key'];
 WHEN 'cancel' THEN keys:=keys||ARRAY['run_id','run_version','idempotency_key'];
 WHEN 'detail' THEN keys:=keys||ARRAY['run_id'];
 WHEN 'classify' THEN keys:=keys||ARRAY['resource_kind','resource_id'];
 WHEN 'list' THEN keys:=keys||ARRAY['limit','after_run_id'];
 WHEN 'run_candidates','approval_candidates' THEN keys:=keys||ARRAY['resource_filter','state_filter','limit','before_created_at','before_id'];
 ELSE RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered operation rejected';END CASE;
 IF NOT zasp_sa_multistep_prior.closed(q,keys) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','actor_id','definition_id','trigger_id','run_id','approval_id','resource_id'] LOOP
  IF q ? k AND (jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered identity rejected';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['definition_version','trigger_version','run_version','approval_version'] LOOP
  IF q ? k AND (jsonb_typeof(q->k) IS DISTINCT FROM 'number' OR (q->>k)!~'^([1-9][0-9]{0,5}|1000000)$') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered version rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';actor:=q->>'actor_id';
 IF op IN('decide_resource','decide') OR(op='classify' AND q->>'resource_kind'='approval') THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM zasp_ordered_public62.authorize(o,w,e,actor,op IN('activate','trigger','decide','cancel','activate_resource','trigger_resource','decide_resource'));
 IF op='ready' THEN result_value:=jsonb_build_object('contract_version',62,'ready',true);
 ELSIF op IN('run_candidates','approval_candidates') THEN result_value:=zasp_ordered_public62.candidates(q);
 ELSIF op='resource_activation' THEN
  IF zasp_ordered_public62.classify(o,w,e,'definition',q->>'definition_id')<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO d FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,q->>'definition_id');
  result_value:=jsonb_build_object('contract_version',62,'id',d.definition_id,'activation',d.activation,'enabled',d.body->'enabled','version',d.version);
 ELSIF op='classify_trigger_key' THEN
  IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered trigger classification rejected';END IF;
  result_value:=jsonb_build_object('contract_version',62,'definition_id',q->>'definition_id','idempotency_key',q->>'idempotency_key','family',zasp_ordered_public62.classify_trigger_key(o,w,e,actor,q->>'definition_id',q->>'idempotency_key'));
 ELSIF op='classify_mutation' THEN
  IF jsonb_typeof(q->'mutation_kind') IS DISTINCT FROM 'string' OR q->>'mutation_kind' NOT IN('activate','trigger') OR jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation classification rejected';END IF;
  IF q->>'mutation_kind'='trigger' THEN
   IF NOT zasp_sa_multistep_prior.closed(q->'trigger',ARRAY['trigger_id','trigger_version']) OR jsonb_typeof(q->'trigger'->'trigger_id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->'trigger'->>'trigger_id'),false) OR jsonb_typeof(q->'trigger'->'trigger_version') IS DISTINCT FROM 'number' OR NOT COALESCE(q->'trigger'->>'trigger_version'~'^([1-9][0-9]{0,5}|1000000)$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation trigger identity rejected';END IF;
  END IF;
  result_value:=jsonb_build_object('contract_version',62,'mutation_kind',q->>'mutation_kind','definition_id',q->>'definition_id','idempotency_key',q->>'idempotency_key','trigger',q->'trigger','family',zasp_ordered_public62.classify_mutation(o,w,e,actor,q->>'mutation_kind',q->>'definition_id',q->>'idempotency_key',q->'trigger'->>'trigger_id',(q->'trigger'->>'trigger_version')::bigint));
 ELSIF op='activate_resource' THEN
  IF zasp_ordered_public62.classify_mutation(o,w,e,actor,'activate',q->>'definition_id',q->>'idempotency_key',NULL,NULL)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  result_value:=zasp_ordered_public62.activate_resource(c,f,q);
 ELSIF op='resource_run' THEN result_value:=zasp_ordered_public62.resource_run(o,w,e,q->>'run_id');
 ELSIF op='resource_approval' THEN
  IF zasp_ordered_public62.classify(o,w,e,'approval',q->>'approval_id')<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO approval_row FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,approval_id)=(o,w,e,q->>'approval_id');
  result_value:=zasp_ordered_public62.resource_run(o,w,e,approval_row.run_id);
 ELSIF op='trigger_resource' THEN
  IF zasp_ordered_public62.classify_mutation(o,w,e,actor,'trigger',q->>'definition_id',q->>'idempotency_key',q->>'trigger_id',(q->>'trigger_version')::bigint)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key') FOR SHARE;
  was_replay:=FOUND;
  SELECT definition INTO evidence FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint) FOR SHARE;
  IF jsonb_typeof(q->'trigger_kind') IS DISTINCT FROM 'string' OR jsonb_typeof(q->'trigger_source') IS DISTINCT FROM 'string' OR q->'trigger_kind' IS DISTINCT FROM evidence->'trigger_kind' OR q->'trigger_source' IS DISTINCT FROM evidence->'trigger_source' THEN
   IF was_replay THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered trigger rejected';END IF;
  inner_q:=(q-'trigger_kind'-'trigger_source')||jsonb_build_object('operation','trigger');
  inner_result:=zasp_ordered_public62.api(c,f,inner_q);r:=inner_result->>'run_id';
  IF zasp_ordered_public62.classify(o,w,e,'run',r)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger unavailable';END IF;
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key');
  result_value:=jsonb_build_object('contract_version',62,'id',r,'agent_id',inner_result->>'definition_id','definition_version',inner_result->'definition_version','state',inner_result->>'state','version',inner_result->'version','evidence_ids',jsonb_build_array(q->>'trigger_id'),'audit_id',prior.audit_id,'correlation_id',prior.correlation_id,'receipt_id',prior.receipt_id,'replayed',was_replay);
 ELSIF op='decide_resource' THEN
  IF zasp_ordered_public62.classify(o,w,e,'approval',q->>'approval_id')<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO approval_row FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,approval_id)=(o,w,e,q->>'approval_id');
  SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,approval_row.run_id);
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'decideSecurityAgentApproval',q->>'idempotency_key') FOR SHARE;
  inner_q:=q||jsonb_build_object('operation','decide','run_id',approval_row.run_id,'run_version',CASE WHEN prior.receipt_id IS NULL THEN run_row.version ELSE prior.expected_version END);
  inner_result:=zasp_ordered_public62.api(c,f,inner_q);
  result_value:=jsonb_build_object('mutation',inner_result,'resource',zasp_ordered_public62.resource_run(o,w,e,approval_row.run_id));
 ELSIF op='classify' THEN
  IF jsonb_typeof(q->'resource_kind') IS DISTINCT FROM 'string' OR q->>'resource_kind' NOT IN('definition','run','approval') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered resource kind rejected';END IF;
  result_value:=jsonb_build_object('contract_version',62,'resource_kind',q->>'resource_kind','resource_id',q->>'resource_id','family',zasp_ordered_public62.classify(o,w,e,q->>'resource_kind',q->>'resource_id'));
 ELSIF op IN('decide','cancel') THEN result_value:=zasp_authorization80_worker.ordered62_mutate_inner(c,f,q);
 ELSIF op='detail' THEN result_value:=zasp_ordered_public62.project(o,w,e,q->>'run_id');
 ELSIF op='list' THEN
  IF jsonb_typeof(q->'limit') IS DISTINCT FROM 'number' OR (q->>'limit')!~'^([1-9]|10)$' OR jsonb_typeof(q->'after_run_id') IS DISTINCT FROM 'string'
   OR q->>'after_run_id'<>'' AND NOT COALESCE(public.zasp_valid_product_id(q->>'after_run_id'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered page rejected';END IF;
  FOR item IN SELECT x.run_id FROM public.zasp_security_agent_runs x JOIN public.zasp_security_agent_definitions definition_item USING(organization_id,workspace_id,environment_id,definition_id)
   LEFT JOIN public.zasp_security_agent_definition_versions historical ON (historical.organization_id,historical.workspace_id,historical.environment_id,historical.definition_id,historical.version)=(x.organization_id,x.workspace_id,x.environment_id,x.definition_id,x.definition_version)
   WHERE (x.organization_id,x.workspace_id,x.environment_id)=(o,w,e) AND x.run_id>q->>'after_run_id' AND (definition_item.body->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb OR historical.definition->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb
    OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit a WHERE (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.event_kind)=(o,w,e,x.run_id,'ordered_public_triggered'))) ORDER BY x.run_id LIMIT (q->>'limit')::integer+1 LOOP
   PERFORM zasp_ordered_public62.history(o,w,e,item.run_id);
   IF jsonb_array_length(items)=(q->>'limit')::integer THEN next_value:=items->-1->>'run_id';EXIT;END IF;
   items:=items||jsonb_build_array(zasp_ordered_public62.project(o,w,e,item.run_id));
  END LOOP;
  result_value:=jsonb_build_object('contract_version',62,'items',items,'next_after_run_id',next_value);
 ELSIF op='activate' THEN
  PERFORM 1 FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,q->>'definition_id') FOR UPDATE;
  d:=zasp_ordered_public62.definition(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint,false);
  IF d.version>=1000000 OR NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered activation changed';END IF;
  UPDATE public.zasp_security_agent_definitions SET activation='supervised',version=version+1,body=body||jsonb_build_object('enabled',true),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d.definition_id) RETURNING * INTO d;
  INSERT INTO public.zasp_security_agent_definition_versions(organization_id,workspace_id,environment_id,definition_id,version,activation,definition,definition_digest,actor_id) VALUES(o,w,e,d.definition_id,d.version,'supervised',d.body,digest(convert_to(d.body::text,'UTF8'),'sha256'),actor);
  result_value:=jsonb_build_object('contract_version',62,'definition_id',d.definition_id,'definition_version',d.version,'activation','supervised');
  a:=public.zasp_discovery_canonical_id(o,w,e,'public62_activation',d.definition_id||chr(31)||d.version::text);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,a,a,actor,'ordered_public_activated',digest(convert_to(result_value::text,'UTF8'),'sha256'),result_value);
 ELSE
  IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR length(q->>'idempotency_key') NOT BETWEEN 16 AND 128 OR (q->>'idempotency_key')!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered idempotency rejected';END IF;
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key') FOR SHARE;
  IF FOUND THEN
   IF prior.intent IS DISTINCT FROM q OR prior.intent_digest IS DISTINCT FROM digest(convert_to(q::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
   IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,requested_by)=(o,w,e,prior.resource_id,q->>'definition_id',(q->>'definition_version')::bigint,actor)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered replay unavailable';END IF;
   r:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',(q->>'definition_id')||chr(31)||(q->>'trigger_id')||chr(31)||(q->>'trigger_version'));
   result_value:=jsonb_build_object('contract_version',62,'run_id',r,'definition_id',q->>'definition_id','definition_version',(q->>'definition_version')::bigint,'state','queued','version',1);
   IF prior.resource_id IS DISTINCT FROM r OR prior.expected_version IS DISTINCT FROM (q->>'definition_version')::bigint OR prior.response IS DISTINCT FROM result_value
    OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_audit history JOIN public.zasp_security_agent_trigger_receipts tr USING(organization_id,workspace_id,environment_id,run_id)
     JOIN public.zasp_security_agent_definition_versions versioned ON (versioned.organization_id,versioned.workspace_id,versioned.environment_id,versioned.definition_id,versioned.version)=(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint)
     WHERE (history.organization_id,history.workspace_id,history.environment_id,history.run_id,history.actor_id,history.event_kind)=(o,w,e,r,actor,'ordered_public_triggered')
      AND history.audit_id=prior.audit_id AND history.body->'request'=q AND history.body->'response'=result_value AND history.event_digest=digest(convert_to(history.body::text,'UTF8'),'sha256')
      AND history.body->'trigger_digest'=to_jsonb(encode(tr.trigger_digest,'hex')) AND tr.trigger_version=(q->>'trigger_version')::bigint AND tr.trigger_id=q->>'trigger_id'
      AND history.body->'existing_test'=versioned.definition->'existing_test' AND versioned.definition_digest=digest(convert_to(versioned.definition::text,'UTF8'),'sha256')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered replay authority changed';END IF;
  ELSE
   d:=zasp_ordered_public62.definition(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint,true);
   IF d.body->>'trigger_kind'='finding' THEN SELECT to_jsonb(x) INTO evidence FROM public.zasp_risk_findings x WHERE (organization_id,workspace_id,environment_id,id,version,status,rule)=(o,w,e,q->>'trigger_id',(q->>'trigger_version')::bigint,'open',d.body->>'trigger_source') FOR SHARE;
   ELSE SELECT to_jsonb(x) INTO evidence FROM public.zasp_risk_attack_paths x WHERE (organization_id,workspace_id,environment_id,id,version,state)=(o,w,e,q->>'trigger_id',(q->>'trigger_version')::bigint,d.body->>'trigger_source') AND state IN('observed','verified') AND public.zasp_risk_attack_path_valid(x) FOR SHARE;END IF;
   IF evidence IS NULL OR octet_length(evidence::text)>65536 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
   r:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',d.definition_id||chr(31)||(q->>'trigger_id')||chr(31)||(q->>'trigger_version'));
   a:=public.zasp_discovery_canonical_id(o,w,e,'public62_trigger',r);receipt_id:=public.zasp_discovery_canonical_id(o,w,e,'public62_receipt',actor||chr(31)||(q->>'idempotency_key'));
   IF NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger changed';END IF;
   INSERT INTO public.zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(o,w,e,r,d.definition_id,d.version,q->>'trigger_id',actor,'queued');
   INSERT INTO public.zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(o,w,e,d.definition_id,q->>'trigger_id',d.body->>'trigger_kind',(q->>'trigger_version')::bigint,digest(convert_to(evidence::text,'UTF8'),'sha256'),r);
   PERFORM zasp_sa_multistep_prior.context(o,w,e,r);
   result_value:=jsonb_build_object('contract_version',62,'run_id',r,'definition_id',d.definition_id,'definition_version',d.version,'state','queued','version',1);
   audit_body:=jsonb_build_object('request',q,'response',result_value,'trigger_digest',encode(digest(convert_to(evidence::text,'UTF8'),'sha256'),'hex'),'existing_test',d.body->'existing_test','definition_digest',encode(digest(convert_to(d.body::text,'UTF8'),'sha256'),'hex'));
   INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,a,a,r,actor,'ordered_public_triggered',digest(convert_to(audit_body::text,'UTF8'),'sha256'),audit_body);
   INSERT INTO public.zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key',r,d.version,q,digest(convert_to(q::text,'UTF8'),'sha256'),result_value,a,a,receipt_id);
  END IF;
 END IF;
 IF op='trigger' THEN PERFORM zasp_ordered_public62.history(o,w,e,r);END IF;
 IF result_value IS NULL OR octet_length(result_value::text)>65536 OR NOT zasp_authorization80_worker.ordered62_inner_ready(c,f) OR NOT public.zasp_security_agent_principal_ready('zasp_security_agent_api') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered authority changed';END IF;
 IF op IN('decide_resource','decide') OR(op='classify' AND q->>'resource_kind'='approval') THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,false);END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered62_mutate_inner(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';actor text:=q->>'actor_id';r text:=q->>'run_id';op text:=q->>'operation';
 operation_value text;fresh timestamptz;rr public.zasp_security_agent_runs%ROWTYPE;s public.zasp_security_agent_steps%ROWTYPE;approval public.zasp_security_agent_approvals%ROWTYPE;
 prior public.zasp_security_agent_request_receipts%ROWTYPE;audit_row public.zasp_security_agent_audit%ROWTYPE;transition_row public.zasp_security_agent_audit%ROWTYPE;decision_row public.zasp_security_agent_audit%ROWTYPE;
 audit_id_value text;receipt_id_value text;transition_id text;transition_q jsonb;transition_result jsonb;result_value jsonb;body_value jsonb;projection jsonb;
 admitted boolean;cleanup_value boolean;replayed boolean:=false;keys text[];expected_step_version bigint;phase_value text;expected_phase text;decision_id text;
BEGIN
 IF q->>'operation' IS DISTINCT FROM 'decide' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='private ordered approval operation rejected';END IF;
 IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR length(q->>'idempotency_key') NOT BETWEEN 16 AND 128 OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$'
  OR (q->>'run_version')::bigint>=1000000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation rejected';END IF;
 IF op='decide' THEN
  IF jsonb_typeof(q->'decision') IS DISTINCT FROM 'string' OR q->>'decision' NOT IN('approved','rejected') OR jsonb_typeof(q->'fresh_auth_at') IS DISTINCT FROM 'string'
   OR length(q->>'fresh_auth_at') NOT BETWEEN 20 AND 35 OR q->>'fresh_auth_at'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$' OR (q->>'approval_version')::bigint>=1000000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered decision rejected';END IF;
  fresh:=(q->>'fresh_auth_at')::timestamptz;
  IF fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered decision unavailable';END IF;
 END IF;
 operation_value:=CASE op WHEN 'decide' THEN 'decideSecurityAgentApproval' ELSE 'cancelSecurityAgentRun' END;
 -- Organization admission precedes budget/run, exactly as the private worker.
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 PERFORM 1 FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
 IF op='decide' THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,true);END IF;
 admitted:=EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r));
 IF admitted THEN PERFORM zasp_sa_multistep_prior.cleanup_lock(o,w,e,r);END IF;
 IF admitted AND op='cancel' THEN
  -- Cancellation must remain possible after gateway revocation or expiry.
  -- Validate retained authority here; validate terminal cleanup evidence after
  -- the reviewed transition creates its blocking audit, never live permission.
  PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,false);
  PERFORM zasp_ordered_public62.history(o,w,e,r);
 ELSE projection:=zasp_ordered_public62.project(o,w,e,r);END IF;
 audit_id_value:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_audit',actor||chr(31)||op||chr(31)||(q->>'idempotency_key'));
 receipt_id_value:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_receipt',actor||chr(31)||op||chr(31)||(q->>'idempotency_key'));
 SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,operation_value,q->>'idempotency_key') FOR SHARE;
 IF FOUND THEN
  IF prior.intent IS DISTINCT FROM q OR prior.intent_digest IS DISTINCT FROM digest(convert_to(q::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
  SELECT * INTO audit_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,audit_id_value) FOR SHARE;
  result_value:=prior.response;body_value:=audit_row.body;transition_id:=body_value->>'transition_audit_id';
  IF (prior.resource_id,prior.expected_version,prior.audit_id,prior.correlation_id,prior.receipt_id) IS DISTINCT FROM (r,(q->>'run_version')::bigint,audit_id_value,audit_id_value,receipt_id_value)
   OR (audit_row.run_id,audit_row.actor_id,audit_row.event_kind,audit_row.correlation_id) IS DISTINCT FROM (r,actor,'ordered_public_'||op,audit_id_value)
   OR NOT zasp_sa_multistep_prior.closed(body_value||jsonb_build_object('transition_audit_id',COALESCE(transition_id,''),'transition_digest',COALESCE(body_value->>'transition_digest','')),ARRAY['request','response','transition_audit_id','transition_digest']) OR NOT body_value ?& ARRAY['transition_audit_id','transition_digest'] OR body_value->'request' IS DISTINCT FROM q OR body_value->'response' IS DISTINCT FROM result_value
   OR audit_row.event_digest IS DISTINCT FROM digest(convert_to(body_value::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation history unavailable';END IF;
  replayed:=true;
 ELSE
  IF rr.version<>(q->>'run_version')::bigint OR rr.completed_at IS NOT NULL OR rr.state NOT IN('queued','planning','waiting_approval','running','verifying') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation state changed';END IF;
  IF op='decide' THEN
   IF NOT admitted OR rr.state<>'waiting_approval' OR actor=rr.requested_by THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,state)=(o,w,e,r,'waiting_approval') ORDER BY step_index LIMIT 1;
   SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
   IF approval.approval_id IS DISTINCT FROM q->>'approval_id' OR approval.state IS DISTINCT FROM 'pending' OR approval.version IS DISTINCT FROM (q->>'approval_version')::bigint OR s.version>=1000000
    OR approval.approver_id IS NOT NULL OR approval.decided_at IS NOT NULL OR approval.fresh_auth_at IS NOT NULL OR approval.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
  ELSIF admitted THEN
   -- Before the application receipt step zero owns cancellation. Once it is
   -- complete the canonical successor owns it, including the between-step gap.
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND step_index=CASE WHEN EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_index,state)=(o,w,e,r,0,'succeeded')) THEN 1 ELSE 0 END;
  END IF;
  PERFORM zasp_ordered_public62.history(o,w,e,r);
  IF NOT zasp_authorization80_worker.ordered62_inner_ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation authority changed';END IF;
  IF admitted THEN
   IF s.step_id IS NULL OR s.version>=1000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered current step unavailable';END IF;
   IF op='cancel' THEN SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);END IF;
   phase_value:=CASE s.state WHEN 'queued' THEN 'queued' WHEN 'waiting_approval' THEN 'pending-approval' WHEN 'authorized' THEN 'authorized' WHEN 'executing' THEN 'executing' END;
   -- The immutable cancel request retains positive pre-transition approval
   -- authority: pending=1, previously approved=2, no approval=1. Never infer
   -- a pending phase merely from missing prior decision evidence.
   transition_q:=jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'actor_id',actor,'run_id',r,'step_id',s.step_id,'operation',CASE WHEN op='cancel' THEN 'cancel' WHEN q->>'decision'='approved' THEN 'approve' ELSE 'reject' END,'run_version',rr.version,'approval_version',COALESCE(approval.version,1),'fresh_auth_at',CASE WHEN op='decide' THEN q->>'fresh_auth_at' ELSE to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END);
 IF op='decide' THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,true);END IF;
   transition_result:=zasp_temporal67.api_transition('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',transition_q);
   transition_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||CASE WHEN op='cancel' THEN 'ordered_run_cancelled' ELSE 'ordered_approval_decided' END);
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
  ELSE
   IF op<>'cancel' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered admission absent';END IF;
   phase_value:='before-admission';
   -- Preserve all planner/provider accounting evidence. needs_human remains
   -- eligible for release61 expired-lease recovery; cancelled would strand it.
   PERFORM 1 FROM zasp_sa_multistep_prior.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
   UPDATE public.zasp_security_agent_runs SET state=CASE WHEN state='queued' THEN 'cancelled' ELSE 'needs_human' END,version=version+1,completed_at=clock_timestamp(),updated_at=clock_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_error_code='public_cancel_requested' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  END IF;
  SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  cleanup_value:=EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,action_key)=(o,w,e,r,'create_temporary_policy') AND state<>'cleaned');
  result_value:=jsonb_build_object('contract_version',62,'organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'run_state',rr.state,'run_version',rr.version,'step_id',s.step_id,'step_state',s.state,'step_version',COALESCE(s.version,0),'audit_id',audit_id_value,'receipt_id',receipt_id_value,'replayed',false);
  IF op='decide' THEN result_value:=result_value||jsonb_build_object('approval_id',approval.approval_id,'approval_version',approval.version+1,'decision',q->>'decision','outcome',CASE WHEN q->>'decision'='approved' THEN 'approved' ELSE 'blocked' END);
  ELSE result_value:=result_value||jsonb_build_object('cleanup_required',cleanup_value,'cancellation_phase',phase_value,'outcome','cancelled-request');END IF;
  SELECT * INTO transition_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,transition_id);
  body_value:=jsonb_build_object('request',q,'response',result_value,'transition_audit_id',transition_id,'transition_digest',CASE WHEN transition_id IS NOT NULL THEN encode(digest(convert_to(transition_row.body::text,'UTF8'),'sha256'),'hex') END);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,approval_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_id_value,audit_id_value,r,s.step_id,approval.approval_id,actor,'ordered_public_'||op,digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
  INSERT INTO public.zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(o,w,e,actor,operation_value,q->>'idempotency_key',r,(q->>'run_version')::bigint,q,digest(convert_to(q::text,'UTF8'),'sha256'),result_value,audit_id_value,audit_id_value,receipt_id_value);
 END IF;
 keys:=ARRAY['contract_version','organization_id','workspace_id','environment_id','run_id','run_state','run_version','step_id','step_state','step_version','audit_id','receipt_id','replayed','outcome'];
 IF op='decide' THEN keys:=keys||ARRAY['approval_id','approval_version','decision'];ELSE keys:=keys||ARRAY['cleanup_required','cancellation_phase'];END IF;
 IF NOT zasp_sa_multistep_prior.closed(CASE WHEN admitted THEN result_value ELSE result_value||jsonb_build_object('step_id','','step_state','') END,keys) OR NOT result_value ?& keys OR octet_length(result_value::text)>4096
  OR result_value->'contract_version' IS DISTINCT FROM '62'::jsonb OR result_value->>'organization_id' IS DISTINCT FROM o OR result_value->>'workspace_id' IS DISTINCT FROM w OR result_value->>'environment_id' IS DISTINCT FROM e OR result_value->>'run_id' IS DISTINCT FROM r
  OR result_value->'run_version' IS DISTINCT FROM to_jsonb((q->>'run_version')::bigint+1) OR result_value->>'audit_id' IS DISTINCT FROM audit_id_value OR result_value->>'receipt_id' IS DISTINCT FROM receipt_id_value OR result_value->'replayed' IS DISTINCT FROM 'false'::jsonb
  OR op='decide' AND (result_value->>'decision' IS DISTINCT FROM q->>'decision' OR result_value->>'approval_id' IS DISTINCT FROM q->>'approval_id' OR result_value->'approval_version' IS DISTINCT FROM to_jsonb((q->>'approval_version')::bigint+1)
   OR result_value->>'run_state' IS DISTINCT FROM CASE WHEN q->>'decision'='approved' THEN 'running' ELSE 'needs_human' END OR result_value->>'step_state' IS DISTINCT FROM CASE WHEN q->>'decision'='approved' THEN 'authorized' ELSE 'cancelled' END OR result_value->>'outcome' IS DISTINCT FROM CASE WHEN q->>'decision'='approved' THEN 'approved' ELSE 'blocked' END)
  OR op='cancel' AND (result_value->>'outcome' IS DISTINCT FROM 'cancelled-request' OR result_value->>'run_state' NOT IN('cancelled','needs_human') OR jsonb_typeof(result_value->'cleanup_required') IS DISTINCT FROM 'boolean'
   OR result_value->'cleanup_required' IS DISTINCT FROM to_jsonb(EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,action_key)=(o,w,e,r,'create_temporary_policy')))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation result unavailable';END IF;
 IF transition_id IS NOT NULL THEN
  SELECT * INTO transition_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,transition_id) FOR SHARE;
  SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,result_value->>'step_id');
  -- Derive cancellation phase from immutable private transition evidence.
  -- Approval state alone cannot distinguish pending from prior authorization.
  SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
  IF op='decide' THEN expected_step_version:=s.step_index+2;
  ELSE
   decision_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||'ordered_approval_decided');
   SELECT * INTO decision_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,decision_id) FOR SHARE;
   IF FOUND THEN
    IF (decision_row.run_id,decision_row.step_id,decision_row.event_kind,decision_row.correlation_id) IS DISTINCT FROM (r,s.step_id,'ordered_approval_decided',decision_id)
     OR NOT zasp_sa_multistep_prior.closed(decision_row.body,ARRAY['contract_version','request','response']) OR decision_row.body->'contract_version' IS DISTINCT FROM '61'::jsonb
     OR NOT zasp_sa_multistep_prior.closed(decision_row.body->'request',ARRAY['organization_id','workspace_id','environment_id','actor_id','run_id','step_id','operation','run_version','approval_version','fresh_auth_at'])
     OR NOT zasp_sa_multistep_prior.closed(decision_row.body->'response',ARRAY['contract_version','organization_id','workspace_id','environment_id','run_id','step_id','outcome','run_state','run_version','step_state','approval_id','approval_version'])
     OR decision_row.event_digest IS DISTINCT FROM digest(convert_to((decision_row.body->'request')::text,'UTF8'),'sha256')
     OR (decision_row.body->'request'->>'organization_id',decision_row.body->'request'->>'workspace_id',decision_row.body->'request'->>'environment_id',decision_row.body->'request'->>'run_id',decision_row.body->'request'->>'step_id',decision_row.body->'request'->>'actor_id',decision_row.body->'request'->>'operation') IS DISTINCT FROM (o,w,e,r,s.step_id,decision_row.actor_id,'approve')
     OR decision_row.body->'request'->'approval_version' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(decision_row.body->'request'->'run_version') IS DISTINCT FROM 'number' OR decision_row.body->'request'->>'run_version'!~'^[1-9][0-9]{0,5}$'
     OR (decision_row.body->'response'->>'organization_id',decision_row.body->'response'->>'workspace_id',decision_row.body->'response'->>'environment_id',decision_row.body->'response'->>'run_id',decision_row.body->'response'->>'step_id',decision_row.body->'response'->>'outcome',decision_row.body->'response'->>'run_state',decision_row.body->'response'->>'step_state') IS DISTINCT FROM (o,w,e,r,s.step_id,'approved','running','authorized')
     OR decision_row.body->'response'->'contract_version' IS DISTINCT FROM '61'::jsonb OR decision_row.body->'response'->'run_version' IS DISTINCT FROM to_jsonb((decision_row.body->'request'->>'run_version')::bigint+1)
     OR decision_row.body->'response'->>'approval_id' IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_approval',r||chr(31)||s.step_id) OR decision_row.body->'response'->'approval_version' IS DISTINCT FROM '2'::jsonb
     OR decision_row.body->'response'->'approval_id' IS DISTINCT FROM transition_row.body->'response'->'approval_id' OR decision_row.body->'response'->'approval_version' IS DISTINCT FROM transition_row.body->'response'->'approval_version'
     OR approval.approval_id IS DISTINCT FROM decision_row.body->'response'->>'approval_id' OR approval.state IS DISTINCT FROM 'approved' OR approval.version IS DISTINCT FROM 2 OR approval.approver_id IS DISTINCT FROM decision_row.actor_id OR approval.fresh_auth_at IS DISTINCT FROM (decision_row.body->'request'->>'fresh_auth_at')::timestamptz
     OR approval.decided_at IS NULL OR approval.approver_id=rr.requested_by OR NOT COALESCE(public.zasp_valid_product_id(decision_row.actor_id),false)
     OR (decision_row.body->'response'->>'run_version')::bigint>(q->>'run_version')::bigint THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cancellation decision evidence unavailable';END IF;
   END IF;
   IF transition_row.body->'response'->>'step_state'='executing' AND transition_row.body->'request'->'approval_version'='2'::jsonb AND decision_row.audit_id IS NOT NULL THEN expected_phase:='executing';expected_step_version:=s.step_index+3;
   ELSIF transition_row.body->'response'->>'step_state'='cancelled' THEN
    IF s.step_index=1 AND transition_row.body->'request'->'approval_version'='1'::jsonb AND decision_row.audit_id IS NULL AND approval.approval_id IS NULL AND transition_row.body->'response'->>'approval_id'='' AND transition_row.body->'response'->'approval_version'='0'::jsonb THEN expected_phase:='queued';expected_step_version:=2;
    ELSIF transition_row.body->'response'->>'approval_id'=approval.approval_id AND approval.version=2 AND transition_row.body->'response'->'approval_version'='2'::jsonb THEN
     IF transition_row.body->'request'->'approval_version'='2'::jsonb AND decision_row.audit_id IS NOT NULL THEN expected_phase:='authorized';expected_step_version:=s.step_index+3;
     ELSIF transition_row.body->'request'->'approval_version'='1'::jsonb AND decision_row.audit_id IS NULL AND approval.state='cancelled' THEN expected_phase:='pending-approval';expected_step_version:=s.step_index+2;END IF;
    END IF;
   END IF;
   IF expected_phase IS NULL OR result_value->'cancellation_phase' IS DISTINCT FROM to_jsonb(expected_phase) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cancellation phase unavailable';END IF;
  END IF;
  IF s.step_id IS NULL OR jsonb_typeof(result_value->'step_version') IS DISTINCT FROM 'number' OR result_value->>'step_version'!~'^([1-9][0-9]{0,5}|1000000)$' OR (result_value->>'step_version')::bigint>s.version
   OR expected_step_version IS NULL OR result_value->'step_version' IS DISTINCT FROM to_jsonb(expected_step_version)
   OR transition_id IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||CASE WHEN op='cancel' THEN 'ordered_run_cancelled' ELSE 'ordered_approval_decided' END)
   OR body_value->>'transition_digest' IS DISTINCT FROM encode(digest(convert_to(transition_row.body::text,'UTF8'),'sha256'),'hex')
   OR transition_row.event_digest IS DISTINCT FROM digest(convert_to((transition_row.body->'request')::text,'UTF8'),'sha256')
   OR transition_row.body->'request'->>'actor_id' IS DISTINCT FROM actor OR transition_row.body->'request'->>'run_id' IS DISTINCT FROM r OR transition_row.body->'request'->>'step_id' IS DISTINCT FROM s.step_id
   OR transition_row.body->'request'->>'operation' IS DISTINCT FROM (CASE WHEN op='cancel' THEN 'cancel' WHEN q->>'decision'='approved' THEN 'approve' ELSE 'reject' END)
   OR transition_row.body->'request'->'run_version' IS DISTINCT FROM q->'run_version'
   OR transition_row.body->'response'->'run_version' IS DISTINCT FROM result_value->'run_version' OR transition_row.body->'response'->'run_state' IS DISTINCT FROM result_value->'run_state' OR transition_row.body->'response'->'step_state' IS DISTINCT FROM result_value->'step_state'
   OR op='decide' AND (transition_row.body->'request'->'approval_version' IS DISTINCT FROM q->'approval_version' OR transition_row.body->'request'->'fresh_auth_at' IS DISTINCT FROM q->'fresh_auth_at' OR transition_row.body->'response'->'approval_id' IS DISTINCT FROM q->'approval_id' OR transition_row.body->'response'->'approval_version' IS DISTINCT FROM result_value->'approval_version') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered transition history unavailable';END IF;
 ELSE
  IF result_value->>'run_state' IS DISTINCT FROM (CASE WHEN (q->>'run_version')::bigint=1 THEN 'cancelled' ELSE 'needs_human' END) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered pre-admission state unavailable';END IF;
  IF admitted OR op<>'cancel' OR result_value->>'cancellation_phase' IS DISTINCT FROM 'before-admission' OR result_value->'step_id' IS DISTINCT FROM 'null'::jsonb OR result_value->'step_state' IS DISTINCT FROM 'null'::jsonb OR result_value->'step_version' IS DISTINCT FROM '0'::jsonb OR result_value->'cleanup_required' IS DISTINCT FROM 'false'::jsonb OR body_value->'transition_digest' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cancellation history unavailable';END IF;
 END IF;
 IF op='decide' THEN
  SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id,approval_id)=(o,w,e,r,result_value->>'step_id',q->>'approval_id');
  IF (approval.state,approval.version,approval.approver_id,approval.fresh_auth_at) IS DISTINCT FROM (q->>'decision',(q->>'approval_version')::bigint+1,actor,fresh)
   OR approval.requester_id=actor OR approval.decided_at IS NULL OR approval.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered decision evidence changed';END IF;
 END IF;
 PERFORM zasp_ordered_public62.history(o,w,e,r);
 IF op='cancel' THEN PERFORM zasp_ordered_public62.project(o,w,e,r);END IF;
 IF NOT zasp_authorization80_worker.ordered62_inner_ready(c,f) OR op='decide' AND (fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation expired';END IF;
 IF op='decide' THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,false);END IF;
 RETURN result_value||jsonb_build_object('replayed',replayed);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_adapter_facts(compensation boolean, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;c zasp_temporal65.commands%ROWTYPE;
 tr public.zasp_security_agent_trigger_receipts%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;a zasp_authorization80_worker.ordered_associations%ROWTYPE;
 cv jsonb;resolution jsonb;metadata jsonb;checks jsonb;source_hash text;target_hash text;product text;expires timestamptz;k text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered source requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF compensation IS NULL OR NOT zasp_temporal68.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT (CASE WHEN compensation THEN zasp_temporal68.principal_ready('zasp_temporal_compensation') ELSE zasp_temporal68.adapter_principal_ready() END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered source principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest']) OR octet_length(q::text)>4096
  OR jsonb_typeof(q->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(q->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
  OR jsonb_typeof(q->'input_digest') IS DISTINCT FROM 'string' OR NOT COALESCE(q->>'input_digest'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered start rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered source scope rejected';END IF;
 END LOOP;
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') FOR SHARE;
 IF x.run_id IS NULL OR x.execution_owner<>'temporal' OR to_jsonb(x.definition_version) IS DISTINCT FROM q->'definition_version' OR x.input_digest IS DISTINCT FROM q->>'input_digest' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered owner changed';END IF;
 SELECT * INTO r FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF r.run_id IS NULL OR r.definition_version<>x.definition_version OR r.lease_owner IS NOT NULL OR r.lease_token IS NOT NULL OR r.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered parent changed';END IF;
 SELECT * INTO c FROM zasp_temporal65.commands WHERE(organization_id,workspace_id,environment_id,run_id,kind)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,'start') FOR SHARE;
 SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,r.definition_id,r.trigger_id) FOR SHARE;
 IF c.run_id IS NULL OR c.execution_owner<>'temporal' OR(c.definition_version,c.input_digest) IS DISTINCT FROM(x.definition_version,x.input_digest)
  OR tr.run_id IS NULL OR encode(tr.trigger_digest,'hex') IS DISTINCT FROM x.input_digest OR tr.trigger_kind NOT IN('finding','attack_path')
  OR r.run_id IS DISTINCT FROM public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_run',r.definition_id||chr(31)||r.trigger_id||chr(31)||tr.trigger_version::text) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered retained start changed';END IF;
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(r.organization_id,r.workspace_id,r.environment_id,r.definition_id,r.definition_version) FOR SHARE;
 IF h.definition_id IS NULL OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') OR h.definition->'allowed_actions' IS DISTINCT FROM '["create_temporary_policy","run_test"]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered historical definition changed';END IF;
 source_hash:=encode(digest(convert_to(jsonb_build_array(x.execution_owner,r.definition_id,x.definition_version,x.input_digest,c.event_id,tr.trigger_kind,tr.trigger_id,tr.trigger_version,encode(h.definition_digest,'hex'))::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO a FROM zasp_authorization80_worker.ordered_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF compensation THEN
  IF a.run_id IS NULL OR(a.definition_id,a.definition_version,a.definition_digest,a.source_digest) IS DISTINCT FROM(r.definition_id,r.definition_version,encode(h.definition_digest,'hex'),source_hash)
   OR NOT EXISTS(SELECT 1 FROM zasp_temporal68.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered captured planning absent';END IF;
  metadata:=to_jsonb(a);checks:='[]'::jsonb;
 ELSE
  IF r.state NOT IN('running','verifying') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered task inactive';END IF;
  cv:=zasp_sa_multistep_prior.context(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
  IF cv->'definition' IS DISTINCT FROM h.definition THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered definition binding changed';END IF;
  resolution:=zasp_temporal68.test_target(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id',cv->'test'->>'target_kind',cv->'test'->>'definition_id',(cv->'test'->>'version')::bigint);
  SELECT i.product_kind,least(i.fresh_until,b.valid_until) INTO STRICT product,expires FROM public.zasp_inventory_entities i JOIN public.zasp_attack_lab_credential_bindings b ON(b.organization_id,b.workspace_id,b.environment_id,b.binding_id)=(i.organization_id,i.workspace_id,i.environment_id,resolution#>>'{comparison,credential_binding_id}') WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id') FOR SHARE OF i,b;
  IF product IS NULL OR product NOT IN('agent','tool') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target kind rejected';END IF;
  IF expires IS NULL OR expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target expired';END IF;
  target_hash:=encode(digest(convert_to(resolution::text,'UTF8'),'sha256'),'hex');
  metadata:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,
   'principal_id',public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_definition_service',r.definition_id),'grantor_id',r.requested_by,
   'definition_id',r.definition_id,'definition_version',r.definition_version,'definition_digest',encode(h.definition_digest,'hex'),'source_digest',source_hash,
   'test_id',cv->'test'->>'definition_id','test_version',cv->'test'->'version','target_id',cv->'test'->>'target_id','target_kind',product,'target_digest',target_hash,
   'trigger_kind',tr.trigger_kind,'trigger_id',tr.trigger_id,'credential_binding_id',resolution#>>'{comparison,credential_binding_id}',
   'snapshot_id',resolution#>>'{provenance,snapshot_id}','evidence_id',resolution#>>'{provenance,evidence_id}','integration_id',resolution#>>'{provenance,integration_id}','source',resolution#>>'{provenance,source}');
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',r.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',r.run_id,'permission','manage_workflows'),jsonb_build_object('kind','test','id',cv->'test'->>'definition_id','permission','view'),jsonb_build_object('kind',product,'id',cv->'test'->>'target_id','permission','view'),jsonb_build_object('kind',tr.trigger_kind,'id',tr.trigger_id,'permission','view'));
 END IF;
 RETURN metadata||jsonb_build_object('run_state',r.state,'run_version',r.version,'checks',checks,'session_user',session_user,'fresh_until_ms',CASE WHEN compensation THEN NULL ELSE floor(extract(epoch FROM expires)*1000)::bigint END);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_application_source(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;op text;env jsonb;intent jsonb;ttl integer;generation_value bigint;result_hash bytea;deployment_hash bytea;expires timestamptz;applied timestamptz;control_value text;outcome_value text;deployment_value text;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;receipt public.zasp_sa_multistep_receipts%ROWTYPE;
BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor application principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR octet_length(q::text)>32768
  OR q->>'operation' NOT IN('source') OR jsonb_typeof(q->'payload') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor application request rejected';END IF;
 op:=q->>'operation';env:=q->'payload';o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';
 intent:=zasp_authorization80_worker.ordered68_signing_read_inner(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);
 IF intent->>'action_key'<>'create_temporary_policy' OR op='source' AND intent->>'state' NOT IN('started','unknown') OR op='complete' AND intent->>'state' NOT IN('started','unknown','cleanup_pending') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor source intent unavailable';END IF;
 SELECT (plan->'steps'->0->>'ttl_seconds')::integer INTO STRICT ttl FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF op='source' THEN
  IF NOT zasp_sa_multistep_prior.closed(env,ARRAY['device_id','credential_id','sequence','policy_version','key_id','issued_at','expires_at','failure_mode','payload_digest','policies','signature','envelope_digest'])
   OR env->'policies' IS DISTINCT FROM zasp_sa_multistep_prior.application_policies() OR env->>'failure_mode' IS DISTINCT FROM 'closed'
   OR NOT COALESCE(env->>'payload_digest'~'^sha256:[a-f0-9]{64}$' AND env->>'envelope_digest'~'^sha256:[a-f0-9]{64}$' AND env->>'key_id'~'^[a-z][a-z0-9_-]{7,63}$',false)
   OR octet_length(decode(env->>'signature','base64')) IS DISTINCT FROM 64 OR (env->>'issued_at')::timestamptz>clock_timestamp()+interval '5 seconds'
   OR (env->>'expires_at')::timestamptz<=clock_timestamp() OR (env->>'expires_at')::timestamptz IS DISTINCT FROM (env->>'issued_at')::timestamptz+make_interval(secs=>ttl)
   OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(intent->'snapshot'->'targets') x WHERE (x->>'device_id',x->>'credential_id',x->'sequence',x->'policy_version')=(env->>'device_id',env->>'credential_id',env->'sequence',env->'policy_version')) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor signed source rejected';END IF;
  SELECT * INTO t FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id,credential_id,sequence,policy_version)=(o,w,e,r,s,'apply',env->>'device_id',env->>'credential_id',(env->>'sequence')::bigint,(env->>'policy_version')::bigint) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor source identity changed';END IF;
  IF t.state='planned' THEN
   UPDATE public.zasp_security_agent_temporary_policy_targets SET state='stored',key_id=env->>'key_id',issued_at=(env->>'issued_at')::timestamptz,expires_at=(env->>'expires_at')::timestamptz,failure_mode='closed',payload_digest=decode(substr(env->>'payload_digest',8),'hex'),policies=env->'policies',signature=decode(env->>'signature','base64'),envelope_digest=decode(substr(env->>'envelope_digest',8),'hex'),stored_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id)=(o,w,e,r,s,'apply',t.device_id);
   generation_value:=public.zasp_policy_deployment_enqueue_device(o,w,e,t.device_id);
   UPDATE public.zasp_security_agent_temporary_policy_targets SET desired_generation=generation_value WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id)=(o,w,e,r,s,'apply',t.device_id);
  ELSIF (t.key_id,t.issued_at,t.expires_at,t.failure_mode,t.payload_digest,t.policies,t.signature,t.envelope_digest) IS DISTINCT FROM (env->>'key_id',(env->>'issued_at')::timestamptz,(env->>'expires_at')::timestamptz,'closed',decode(substr(env->>'payload_digest',8),'hex'),env->'policies',decode(env->>'signature','base64'),decode(substr(env->>'envelope_digest',8),'hex')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor source replay conflict';END IF;
 ELSIF env<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor application unexpected payload';
 ELSIF op='complete' THEN
  PERFORM zasp_sa_multistep_prior.deployment_verified(o,w,e,r,s);
  SELECT * INTO receipt FROM public.zasp_sa_multistep_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  IF NOT FOUND THEN
   IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply'))
    OR EXISTS(SELECT 1 FROM public.zasp_security_agent_temporary_policy_targets x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.phase)=(o,w,e,r,s,'apply') AND NOT EXISTS(SELECT 1 FROM zasp_temporal68.deliveries d WHERE (d.organization_id,d.workspace_id,d.environment_id,d.run_id,d.step_id,d.generation,d.phase,d.device_id,d.state,d.source_digest,d.desired_generation)=(o,w,e,r,s,1,'apply',x.device_id,'acknowledged',x.envelope_digest,x.desired_generation) AND d.read_at IS NOT NULL)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor application delivery receipt absent';END IF;
   SELECT * INTO st FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
   UPDATE public.zasp_security_agent_temporary_policy_targets SET state='verified',verified_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply') AND state='stored';
   SELECT digest(st.input_digest||decode(string_agg(encode(envelope_digest,'hex'),'' ORDER BY device_id),'hex'),'sha256'),digest(convert_to(jsonb_agg(jsonb_build_array(device_id,credential_id,sequence,policy_version,desired_generation,encode(envelope_digest,'hex')) ORDER BY device_id)::text,'UTF8'),'sha256'),min(expires_at),max(verified_at) INTO result_hash,deployment_hash,expires,applied FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply');
   control_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_control',r||chr(31)||s);
   outcome_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_effect',r||chr(31)||s||chr(31)||'apply');
   deployment_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_deployment',r||chr(31)||s||chr(31)||encode(deployment_hash,'hex'));
   INSERT INTO public.zasp_security_agent_controls(organization_id,workspace_id,environment_id,control_id,run_id,step_id,action_key,target_id,state,expires_at) VALUES(o,w,e,control_value,r,s,'create_temporary_policy',e,'active',expires);
   UPDATE public.zasp_security_agent_effects SET state='cleanup_pending',outcome_id=outcome_value,result_digest=result_hash,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy');
   UPDATE public.zasp_security_agent_steps SET state='succeeded',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
   UPDATE public.zasp_security_agent_runs SET version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
   UPDATE zasp_temporal68.effects SET state='cleanup_pending',completed_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1);
   INSERT INTO public.zasp_sa_multistep_receipts(organization_id,workspace_id,environment_id,run_id,plan_hash,step_id,action_key,input_digest,result_digest,receipt_kind,receipt_version,body)
    VALUES(o,w,e,r,decode(intent->'snapshot'->>'plan_hash','hex'),s,'create_temporary_policy',st.input_digest,result_hash,'temporary_policy_applied.v1',1,jsonb_build_object('deployment_id',deployment_value,'control_id',control_value,'control_version',1,'outcome_id',outcome_value,'applied_at',to_char(applied AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'expires_at',to_char(expires AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))) RETURNING * INTO receipt;
  END IF;
  IF NOT zasp_sa_multistep_prior.application_ready(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor application evidence changed';END IF;
 END IF;
 PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);
 IF NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor application catalog changed';END IF;
 IF op='complete' THEN RETURN jsonb_build_object('effect_key',intent->>'effect_key','receipt_kind',receipt.receipt_kind,'receipt',receipt.body,'result_digest','sha256:'||encode(receipt.result_digest,'hex'));END IF;
 RETURN jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'step_id',s,'generation',1,'effect_key',intent->>'effect_key','ttl_seconds',ttl,'targets',zasp_sa_multistep_prior.application_targets(o,w,e,r,s));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_cleanup_source(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;op text;intent jsonb;snapshot_value jsonb;env jsonb;acks jsonb;generation_value bigint;audit_value text;marker jsonb;renewal_body jsonb;targets_value jsonb;revision_value bigint;original_digest text;
 c zasp_temporal68.cleanups%ROWTYPE;t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;
BEGIN
 IF NOT(zasp_temporal68.principal_ready('zasp_temporal_compensation') OR zasp_temporal68.principal_ready('zasp_temporal_executor')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor compensation principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR octet_length(q::text)>32768 OR NOT COALESCE(q->>'operation' IN('source','renew'),false) OR jsonb_typeof(q->'payload') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor compensation request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';op:=q->>'operation';env:=q->'payload';
 intent:=zasp_authorization80_worker.ordered68_signing_read_inner(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO c FROM zasp_temporal68.cleanups WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR UPDATE;
 IF NOT FOUND THEN
  IF op<>'prepare' OR NOT (rr.state IN('cancelled','needs_human','failed','inconclusive','contained') OR zasp_sa_multistep_prior.orchestration_stop_required(o,w,e,r)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor compensation not required';END IF;
  snapshot_value:=zasp_temporal68.cleanup_snapshot(o,w,e,r,s);
  IF snapshot_value->>'kind'='applied' THEN PERFORM zasp_ordered_public62.retained_application(o,w,e,r);END IF;
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(snapshot_value->'targets') x WHERE x->>'state' IN('stored','verified')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor compensation has no source';END IF;
  INSERT INTO zasp_temporal68.cleanups(organization_id,workspace_id,environment_id,run_id,step_id,generation,snapshot,snapshot_digest,state,reason) VALUES(o,w,e,r,s,1,snapshot_value,digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'pending','execution_stopped') RETURNING * INTO c;
  UPDATE public.zasp_security_agent_runs SET state=CASE WHEN state='cancelled' THEN state ELSE 'needs_human' END,version=version+1,completed_at=COALESCE(completed_at,clock_timestamp()),updated_at=clock_timestamp(),last_error_code='cleanup_required' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  UPDATE public.zasp_security_agent_steps SET state='cancelled',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND state NOT IN('succeeded','inconclusive','cancelled');
  FOR t IN SELECT * FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply') AND state IN('stored','verified') ORDER BY device_id LOOP
   INSERT INTO public.zasp_security_agent_temporary_policy_targets(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id,credential_id,sequence,policy_version) VALUES(o,w,e,r,s,'cleanup',t.device_id,t.credential_id,1,1);
  END LOOP;
  audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_cleanup',intent->>'effect_key');
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,audit_value,r,s,session_user,'temporal_cleanup_required',c.snapshot_digest,c.snapshot);
 END IF;
 PERFORM zasp_temporal68.cleanup_current(o,w,e,r,s);
 IF op IN('source','renew') THEN
  IF op='renew' THEN
   IF NOT zasp_sa_multistep_prior.closed(env,ARRAY['source_digest','envelope']) OR NOT COALESCE(env->>'source_digest'~'^sha256:[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor cleanup renewal request rejected';END IF;
   original_digest:=env->>'source_digest';env:=env->'envelope';
  END IF;
  IF c.state='cleaned' OR NOT zasp_sa_multistep_prior.closed(env,ARRAY['device_id','credential_id','sequence','policy_version','key_id','issued_at','expires_at','failure_mode','payload_digest','policies','signature','envelope_digest']) OR env->'policies' IS DISTINCT FROM '[]'::jsonb OR env->>'failure_mode' IS DISTINCT FROM 'closed'
   OR NOT COALESCE(env->>'payload_digest'~'^sha256:[a-f0-9]{64}$' AND env->>'envelope_digest'~'^sha256:[a-f0-9]{64}$' AND env->>'key_id'~'^[a-z][a-z0-9_-]{7,63}$',false) OR octet_length(decode(env->>'signature','base64')) IS DISTINCT FROM 64
   OR (env->>'expires_at')::timestamptz IS DISTINCT FROM (env->>'issued_at')::timestamptz+interval '5 minutes' OR (env->>'expires_at')::timestamptz<=clock_timestamp() OR (env->>'issued_at')::timestamptz>clock_timestamp()+interval '5 seconds' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor signed cleanup source rejected';END IF;
  SELECT * INTO t FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id,credential_id,sequence,policy_version)=(o,w,e,r,s,'cleanup',env->>'device_id',env->>'credential_id',(env->>'sequence')::bigint,(env->>'policy_version')::bigint) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor cleanup source identity changed';END IF;
  IF op='renew' THEN
   marker:=zasp_temporal68.cleanup_marker(t);
   IF t.state<>'stored' OR original_digest IS DISTINCT FROM 'sha256:'||encode(t.envelope_digest,'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor cleanup renewal source changed';END IF;
   IF marker IS DISTINCT FROM env THEN
    IF (marker->>'expires_at')::timestamptz>clock_timestamp() OR (env->>'issued_at')::timestamptz<(marker->>'expires_at')::timestamptz THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor cleanup renewal window conflict';END IF;
    SELECT COALESCE(max(revision),0)+1 INTO revision_value FROM zasp_temporal68.cleanup_renewals WHERE (organization_id,workspace_id,environment_id,run_id,step_id,device_id)=(o,w,e,r,s,t.device_id);
    renewal_body:=jsonb_build_object('effect_key',intent->>'effect_key','source',to_jsonb(t)-ARRAY['state','verified_at'],'envelope',env);
    INSERT INTO zasp_temporal68.cleanup_renewals VALUES(o,w,e,r,s,t.device_id,revision_value,renewal_body,digest(convert_to(renewal_body::text,'UTF8'),'sha256'));
    audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_cleanup_renewal',intent->>'effect_key'||chr(31)||t.device_id||chr(31)||revision_value::text);
    INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,audit_value,r,s,session_user,'temporal_cleanup_renewed',digest(convert_to(renewal_body::text,'UTF8'),'sha256'),renewal_body);
   END IF;
  ELSIF t.state='planned' THEN
   UPDATE public.zasp_security_agent_temporary_policy_targets SET state='stored',key_id=env->>'key_id',issued_at=(env->>'issued_at')::timestamptz,expires_at=(env->>'expires_at')::timestamptz,failure_mode='closed',payload_digest=decode(substr(env->>'payload_digest',8),'hex'),policies='[]',signature=decode(env->>'signature','base64'),envelope_digest=decode(substr(env->>'envelope_digest',8),'hex'),stored_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id)=(o,w,e,r,s,'cleanup',t.device_id);
   generation_value:=public.zasp_policy_deployment_enqueue_device(o,w,e,t.device_id);
   UPDATE public.zasp_security_agent_temporary_policy_targets SET desired_generation=generation_value WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id)=(o,w,e,r,s,'cleanup',t.device_id);
  ELSIF (t.key_id,t.issued_at,t.expires_at,t.payload_digest,t.signature,t.envelope_digest) IS DISTINCT FROM(env->>'key_id',(env->>'issued_at')::timestamptz,(env->>'expires_at')::timestamptz,decode(substr(env->>'payload_digest',8),'hex'),decode(env->>'signature','base64'),decode(substr(env->>'envelope_digest',8),'hex')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor cleanup source replay conflict';END IF;
 ELSIF env<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor cleanup unexpected payload';
 ELSIF op='unknown' AND c.state<>'cleaned' THEN
  UPDATE zasp_temporal68.cleanups SET state='unknown',version=version+1 WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO c;
 ELSIF op='complete' AND c.state<>'cleaned' THEN
  acks:=zasp_temporal68.cleanup_acks(o,w,e,r,s,true);
  UPDATE public.zasp_security_agent_temporary_policy_targets SET state='verified',verified_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'cleanup');
  UPDATE public.zasp_security_agent_controls SET state='disabled',version=version+1 WHERE (organization_id,workspace_id,environment_id,run_id,step_id,state)=(o,w,e,r,s,'active');
  UPDATE public.zasp_security_agent_effects SET state='cleaned',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  UPDATE zasp_temporal68.effects SET state='cleaned' WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1);
  UPDATE zasp_temporal68.cleanups SET state='cleaned',version=version+1,completed_at=clock_timestamp(),receipt=jsonb_build_object('effect_key',intent->>'effect_key','snapshot_digest','sha256:'||encode(c.snapshot_digest,'hex'),'targets',acks,'outcome','cleaned') WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO c;
  UPDATE zasp_temporal68.cleanups SET receipt_digest=digest(convert_to(c.receipt::text,'UTF8'),'sha256') WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO c;
  IF c.snapshot->'test'->>'kind'='settled' AND c.snapshot->'test'->'response'->>'outcome'='not_reproduced' THEN
   UPDATE public.zasp_security_agent_runs SET state='remediated',version=version+1,updated_at=clock_timestamp(),last_error_code=NULL WHERE (organization_id,workspace_id,environment_id,run_id,state)=(o,w,e,r,'needs_human');
  END IF;
 END IF;
 PERFORM zasp_temporal68.cleanup_current(o,w,e,r,s);
 IF c.state='cleaned' AND (c.receipt->'targets' IS DISTINCT FROM zasp_temporal68.cleanup_acks(o,w,e,r,s,false) OR c.receipt_digest IS DISTINCT FROM digest(convert_to(c.receipt::text,'UTF8'),'sha256')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor cleaned receipt changed';END IF;
 IF NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor compensation catalog changed';END IF;
 IF op IN('read','source','renew') THEN
  targets_value:=zasp_sa_multistep_prior.cleanup_targets(o,w,e,r,s);
  IF op='renew' THEN SELECT jsonb_agg(CASE WHEN x->>'device_id'=env->>'device_id' THEN x||jsonb_build_object('envelope_digest',env->>'envelope_digest') ELSE x END ORDER BY x->>'device_id') INTO targets_value FROM jsonb_array_elements(targets_value)x;END IF;
  RETURN jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'step_id',s,'generation',1,'effect_key',intent->>'effect_key','ttl_seconds',300,'targets',targets_value);
 END IF;
 RETURN to_jsonb(c)||jsonb_build_object('effect_key',intent->>'effect_key');
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_completion_native(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;child_id text;op text;k text;category_value text;key_value text;payload jsonb;resolution jsonb;request_hash bytea;curated text;result_value jsonb;new_start boolean:=false;
 link public.zasp_security_agent_test_links%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;f zasp_temporal68.effects%ROWTYPE;j zasp_temporal68.invocations%ROWTYPE;prepared zasp_temporal68.test_inputs%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor invocation requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor invocation principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','effect_key','operation','payload','checksum','fingerprint']) OR octet_length(q::text)>8192
  OR NOT COALESCE(q->>'operation' IN('complete') AND q->>'effect_key'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation scope rejected';END IF;
 END LOOP;
 IF NOT COALESCE(zasp_temporal68.ready(q->>'checksum',q->>'fingerprint'),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor invocation version rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';child_id:=q->>'run_id';op:=q->>'operation';key_value:=q->>'effect_key';payload:=q->'payload';category_value:=payload->>'category';
 IF NOT zasp_sa_multistep_prior.closed(payload,CASE op WHEN 'resolve' THEN ARRAY['category','target_id','target_kind'] WHEN 'start' THEN ARRAY['category','request_digest'] ELSE ARRAY['category','request_digest','http_status','response_digest','protected','credential_version_digest'] END)
  OR NOT COALESCE(category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation payload rejected';END IF;
 SELECT * INTO link FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,child_id);
 IF NOT FOUND OR NOT zasp_temporal66.is_temporal(o,w,e,link.run_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor invocation owner rejected';END IF;
 PERFORM zasp_sa_multistep_prior.test_lock(o,w,e,link.run_id);
 PERFORM zasp_temporal68.current_plan(o,w,e,link.run_id,false);
 SELECT * INTO f FROM zasp_temporal68.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation,effect_key,action_key)=(o,w,e,link.run_id,link.step_id,1,key_value,'run_test') FOR UPDATE;
 SELECT * INTO child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,child_id) FOR UPDATE NOWAIT;
 SELECT * INTO prepared FROM zasp_temporal68.test_inputs WHERE (organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(o,w,e,link.run_id,link.step_id,child_id);
 IF NOT zasp_temporal68.test_intent_valid(o,w,e,link.run_id,link.step_id) OR f.run_id IS NULL OR prepared.run_id IS NULL OR child.run_id IS NULL OR f.effect_key IS DISTINCT FROM zasp_temporal68.effect_identity(o,w,e,link.run_id,link.step_id,1)
  OR f.snapshot_digest IS DISTINCT FROM digest(convert_to(f.snapshot::text,'UTF8'),'sha256') OR f.snapshot->'targets'->>'test_run_id' IS DISTINCT FROM child_id
  OR f.snapshot->'targets'->>'input_digest' IS DISTINCT FROM encode(child.input_digest,'hex') OR f.input_digest IS DISTINCT FROM link.input_digest
  OR (link.test_definition_id,link.test_definition_version) IS DISTINCT FROM(child.definition_id,child.definition_version)
  OR NOT link.test_categories ? category_value OR link.test_categories IS DISTINCT FROM f.snapshot->'targets'->'resolution'->'comparison'->'categories'
  OR child.worker_id IS NOT NULL OR child.lease_token IS NOT NULL OR child.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation association changed';END IF;
 PERFORM zasp_sa_multistep_prior.test_validate_input(o,w,e,link.run_id,link.step_id,prepared.manifest,prepared.body);
 resolution:=f.snapshot->'targets'->'resolution';
 IF op<>'complete' THEN
  PERFORM zasp_sa_multistep_prior.test_current(o,w,e,link.run_id,link.step_id);
  IF child.state<>'queued' OR child.cancel_requested OR link.reconcile_state<>'pending' OR f.state NOT IN('started','unknown')
   OR resolution IS DISTINCT FROM zasp_temporal68.test_target(o,w,e,link.target_id,link.target_kind,link.test_definition_id,link.test_definition_version) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation current authority changed';END IF;
 END IF;
 IF op='resolve' THEN
  IF (payload->>'target_id',payload->>'target_kind') IS DISTINCT FROM(link.target_id,link.target_kind) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation target rejected';END IF;
  result_value:=resolution->'binding';
 ELSE
  IF NOT COALESCE(payload->>'request_digest'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation digest rejected';END IF;
  request_hash:=decode(payload->>'request_digest','hex');
  curated:='{"schema_version":"red-team-target-v1","run_id":"'||child_id||'","target_id":"'||link.target_id||'","target_kind":"'||link.target_kind||'","category":"'||category_value||'","input":'||to_json(zasp_sa_multistep_prior.test_prompt(category_value))::text||'}';
  IF request_hash IS DISTINCT FROM digest(convert_to(curated,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor curated invocation rejected';END IF;
  SELECT * INTO j FROM zasp_temporal68.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child_id,category_value) FOR UPDATE;
  IF j.test_run_id IS NOT NULL AND (j.effect_key,j.input_digest,j.request_digest,j.target_resolution) IS DISTINCT FROM(key_value,child.input_digest,request_hash,resolution) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation replay conflict';END IF;
  IF op='start' AND j.state IS DISTINCT FROM 'completed' THEN
   IF f.state<>'started' OR EXISTS(SELECT 1 FROM zasp_temporal68.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,state)=(o,w,e,child_id,'started')) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor invocation outcome unknown';END IF;
   INSERT INTO zasp_temporal68.invocations(organization_id,workspace_id,environment_id,test_run_id,attempt,category,input_digest,request_digest,target_resolution,state,effect_key) VALUES(o,w,e,child_id,1,category_value,child.input_digest,request_hash,resolution,'started',key_value) RETURNING * INTO j;
   new_start:=true;
  ELSIF op='complete' THEN
   IF j.test_run_id IS NULL OR NOT COALESCE(payload->>'response_digest'~'^[a-f0-9]{64}$' AND payload->>'credential_version_digest'~'^[a-f0-9]{64}$' AND payload->>'credential_version_digest'<>repeat('0',64)
    AND jsonb_typeof(payload->'http_status')='number' AND payload->>'http_status'~'^[2-5][0-9]{2}$' AND (payload->'http_status'='200'::jsonb AND jsonb_typeof(payload->'protected')='boolean' OR payload->'http_status'<>'200'::jsonb AND payload->'protected'='null'::jsonb),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation observation rejected';END IF;
   IF j.state='completed' THEN
    IF (j.http_status,j.response_digest,j.protected,j.credential_version_digest) IS DISTINCT FROM((payload->>'http_status')::integer,decode(payload->>'response_digest','hex'),(payload->>'protected')::boolean,decode(payload->>'credential_version_digest','hex')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor observation replay conflict';END IF;
   ELSE
    UPDATE zasp_temporal68.invocations SET state='completed',completed_at=clock_timestamp(),http_status=(payload->>'http_status')::integer,response_digest=decode(payload->>'response_digest','hex'),protected=(payload->>'protected')::boolean,credential_version_digest=decode(payload->>'credential_version_digest','hex') WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child_id,category_value) RETURNING * INTO j;
   END IF;
  END IF;
  result_value:=jsonb_build_object('state',j.state,'attempt',1,'category',category_value,'input_digest',encode(j.input_digest,'hex'),'request_digest',encode(j.request_digest,'hex'),'target_binding',j.target_resolution->'binding','target_provenance',j.target_resolution->'provenance','target_comparison',j.target_resolution->'comparison','effect_key',j.effect_key);
  IF j.state='completed' THEN result_value:=result_value||jsonb_build_object('run_id',child_id,'http_status',j.http_status,'response_digest',encode(j.response_digest,'hex'),'protected',j.protected,'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));END IF;
 END IF;
 IF op<>'complete' THEN PERFORM zasp_sa_multistep_prior.test_current(o,w,e,link.run_id,link.step_id);END IF;
 IF NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor invocation authority changed';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_delivery_store(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;d text;op text;phase_value text;p jsonb;env jsonb;intent jsonb;composition_value jsonb;sequence_value bigint;audit_value text;response_value jsonb;readback jsonb;refresh_value boolean:=false;generation_value bigint;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;work public.zasp_policy_deployment_work%ROWTYPE;b public.zasp_runtime_gateway_policy_bundles%ROWTYPE;v zasp_temporal68.deliveries%ROWTYPE;
BEGIN
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR NOT zasp_sa_multistep_prior.deployment_wire(q,true)
  OR NOT COALESCE(q->>'operation' IN('store'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor delivery request rejected';END IF;
 op:=q->>'operation';p:=q->'payload';o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';d:=p->>'device_id';env:=p->'envelope';
 phase_value:=p->>'phase';
 IF NOT COALESCE(public.zasp_valid_product_id(d),false) OR NOT COALESCE(phase_value IN('apply','cleanup'),false)
  OR NOT zasp_sa_multistep_prior.closed(p,CASE op WHEN 'prepare' THEN ARRAY['device_id','phase'] WHEN 'store' THEN ARRAY['device_id','phase','envelope','digest'] ELSE ARRAY['device_id','phase','digest'] END)
  OR op<>'prepare' AND NOT COALESCE(p->>'digest'~'^sha256:[a-f0-9]{64}$',false)
  OR NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR (phase_value='cleanup' OR op IN('read','ack')) AND zasp_temporal68.principal_ready('zasp_temporal_compensation')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor delivery authority rejected';END IF;
 intent:=zasp_authorization80_worker.ordered68_signing_read_inner(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 IF intent->>'action_key'<>'create_temporary_policy' OR intent->>'state' NOT IN('started','unknown','cleanup_pending','cleaned') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor delivery intent unavailable';END IF;
 IF phase_value='cleanup' THEN PERFORM zasp_temporal68.cleanup_current(o,w,e,r,s);
 ELSIF op IN('prepare','store') THEN PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);END IF;
 SELECT * INTO t FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id)=(o,w,e,r,s,phase_value,d);
 SELECT * INTO work FROM public.zasp_policy_deployment_work WHERE (organization_id,workspace_id,environment_id,device_id)=(o,w,e,d);
 IF t.state NOT IN('stored','verified') OR t.envelope_digest IS NULL OR t.desired_generation IS NULL OR work.device_id IS NULL OR work.state='leased' OR work.lease_token IS NOT NULL OR work.lease_owner IS NOT NULL OR work.lease_expires_at IS NOT NULL
  OR (CASE WHEN phase_value='cleanup' THEN work.desired_generation<t.desired_generation ELSE work.desired_generation IS DISTINCT FROM t.desired_generation END) OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(intent->'snapshot'->'targets') x WHERE x->>'device_id'=d AND x->>'credential_id'=t.credential_id) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor delivery source or owner changed';END IF;
 generation_value:=work.desired_generation;
 composition_value:=CASE WHEN phase_value='cleanup' THEN zasp_temporal68.cleanup_composition(o,w,e,d,r,s) ELSE zasp_sa_multistep_prior.deployment_composition(o,w,e,d) END;
 SELECT * INTO v FROM zasp_temporal68.deliveries WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation,phase,device_id)=(o,w,e,r,s,1,phase_value,d) FOR UPDATE;
 IF phase_value='cleanup' AND (zasp_temporal68.cleanup_marker(t)->>'expires_at')::timestamptz<=clock_timestamp() AND v.state IS DISTINCT FROM 'acknowledged' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor cleanup signing marker expired';END IF;
 IF phase_value='cleanup' THEN
  PERFORM zasp_temporal68.delivery_history(t);
  refresh_value:=v.run_id IS NOT NULL AND (v.composition IS DISTINCT FROM composition_value OR v.desired_generation<>generation_value OR v.envelope IS NOT NULL AND (v.envelope->>'expires_at')::timestamptz<=clock_timestamp()+interval '1 minute');
  IF refresh_value THEN
   IF op<>'prepare' OR (zasp_temporal68.cleanup_marker(t)->>'expires_at')::timestamptz<=clock_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_temporal68.cleanups WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) AND state IN('pending','unknown')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor cleanup recomposition requires fresh authority';END IF;
   INSERT INTO zasp_temporal68.delivery_revisions VALUES(o,w,e,r,s,d,v.sequence,to_jsonb(v),digest(convert_to(to_jsonb(v)::text,'UTF8'),'sha256'));
  END IF;
 END IF;
 IF v.run_id IS NULL OR refresh_value THEN
  IF op<>'prepare' OR NOT refresh_value AND work.applied_generation>=work.desired_generation THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor delivery not prepared';END IF;
  SELECT COALESCE(max(x.sequence)+1,1) INTO sequence_value FROM (SELECT sequence FROM public.zasp_runtime_gateway_policy_bundles WHERE (organization_id,workspace_id,environment_id,device_id)=(o,w,e,d) UNION ALL SELECT sequence FROM zasp_temporal68.deliveries WHERE (organization_id,workspace_id,environment_id,device_id)=(o,w,e,d) UNION ALL SELECT sequence FROM zasp_temporal68.delivery_revisions WHERE (organization_id,workspace_id,environment_id,device_id)=(o,w,e,d))x;
  IF sequence_value NOT BETWEEN 1 AND 999999999 OR NOT zasp_sa_multistep_prior.deployment_signable(o,w,e,d,sequence_value,composition_value->'policies') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor delivery signing bound rejected';END IF;
  INSERT INTO zasp_temporal68.deliveries VALUES(o,w,e,r,s,1,phase_value,d,t.credential_id,t.sequence,t.envelope_digest,generation_value,sequence_value,composition_value,'prepared',NULL,NULL,NULL,NULL)
   ON CONFLICT(organization_id,workspace_id,environment_id,run_id,step_id,generation,phase,device_id) DO UPDATE SET desired_generation=EXCLUDED.desired_generation,sequence=EXCLUDED.sequence,composition=EXCLUDED.composition,state='prepared',envelope=NULL,envelope_digest=NULL,read_at=NULL,acknowledged_at=NULL WHERE refresh_value AND zasp_temporal68.deliveries.phase='cleanup' RETURNING * INTO v;
 END IF;
 IF (v.source_sequence,v.source_digest,v.credential_id,v.desired_generation,v.composition) IS DISTINCT FROM(t.sequence,t.envelope_digest,t.credential_id,generation_value,composition_value)
  OR (composition_value->>'expires_at')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor delivery snapshot changed';END IF;
 IF op='store' THEN
  IF NOT zasp_sa_multistep_prior.closed(env,ARRAY['contract_version','key_id','algorithm','audience','organization_id','workspace_id','environment_id','device_id','sequence','policy_version','issued_at','expires_at','failure_mode','payload_digest','policies','signature'])
   OR env->'contract_version' IS DISTINCT FROM '1'::jsonb OR env->>'algorithm' IS DISTINCT FROM 'Ed25519' OR env->>'audience' IS DISTINCT FROM 'runtime-gateway-policy'
   OR (env->>'organization_id',env->>'workspace_id',env->>'environment_id',env->>'device_id') IS DISTINCT FROM(o,w,e,d)
   OR env->'sequence' IS DISTINCT FROM to_jsonb(v.sequence) OR env->'policy_version' IS DISTINCT FROM to_jsonb(v.sequence) OR env->'policies' IS DISTINCT FROM v.composition->'policies'
   OR env->>'failure_mode' IS DISTINCT FROM 'closed' OR (env->>'expires_at')::timestamptz>(v.composition->>'expires_at')::timestamptz OR (env->>'expires_at')::timestamptz<t.expires_at OR (env->>'expires_at')::timestamptz<=clock_timestamp()
   OR (env->>'issued_at')::timestamptz>clock_timestamp()+interval '5 seconds' OR octet_length(zasp_sa_multistep_prior.deployment_json(env))>1048576 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor delivery envelope rejected';END IF;
  IF v.state='prepared' THEN
   INSERT INTO public.zasp_runtime_gateway_policy_bundles(organization_id,workspace_id,environment_id,device_id,credential_id,sequence,policy_version,key_id,algorithm,audience,issued_at,expires_at,failure_mode,payload_digest,policies,signature,envelope_digest)
    VALUES(o,w,e,d,v.credential_id,v.sequence,v.sequence,env->>'key_id','Ed25519','runtime-gateway-policy',(env->>'issued_at')::timestamptz,(env->>'expires_at')::timestamptz,'closed',decode(env->>'payload_digest','hex'),env->'policies',decode(translate(env->>'signature','-_','+/')||repeat('=',(4-length(env->>'signature')%4)%4),'base64'),decode(substr(p->>'digest',8),'hex'));
   UPDATE zasp_temporal68.deliveries SET state='stored',envelope=env,envelope_digest=decode(substr(p->>'digest',8),'hex') WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation,phase,device_id)=(o,w,e,r,s,1,phase_value,d) RETURNING * INTO v;
  ELSIF v.envelope IS DISTINCT FROM env OR v.envelope_digest IS DISTINCT FROM decode(substr(p->>'digest',8),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor delivery replay conflict';END IF;
 ELSIF op IN('read','ack') THEN
  SELECT * INTO b FROM public.zasp_runtime_gateway_policy_bundles WHERE (organization_id,workspace_id,environment_id,device_id,sequence)=(o,w,e,d,v.sequence);
  readback:=zasp_sa_multistep_prior.cleanup_bundle_snapshot(b);
  IF v.state='prepared' OR b.envelope_digest IS DISTINCT FROM v.envelope_digest OR v.envelope_digest IS DISTINCT FROM decode(substr(p->>'digest',8),'hex') OR b.credential_id IS DISTINCT FROM v.credential_id
   OR (readback-ARRAY['issued_at','expires_at']) IS DISTINCT FROM(v.envelope-ARRAY['issued_at','expires_at']) OR (b.issued_at,b.expires_at) IS DISTINCT FROM((v.envelope->>'issued_at')::timestamptz,(v.envelope->>'expires_at')::timestamptz) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor delivery readback changed';END IF;
  IF op='read' AND v.read_at IS NULL THEN
   UPDATE zasp_temporal68.deliveries SET state='read',read_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation,phase,device_id)=(o,w,e,r,s,1,phase_value,d) RETURNING * INTO v;
  ELSIF op='ack' AND v.state<>'acknowledged' THEN
   IF v.read_at IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor delivery readback absent';END IF;
   UPDATE public.zasp_policy_deployment_work SET applied_generation=v.desired_generation,applied_envelope_digest=v.envelope_digest,state='scheduled',attempt=0,available_at=LEAST(clock_timestamp()+interval '12 hours',b.expires_at-interval '1 minute'),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,device_id)=(o,w,e,d);
   UPDATE zasp_temporal68.deliveries SET state='acknowledged',acknowledged_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation,phase,device_id)=(o,w,e,r,s,1,phase_value,d) RETURNING * INTO v;
   audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_delivery',intent->>'effect_key'||chr(31)||phase_value||chr(31)||d||CASE WHEN phase_value='cleanup' THEN chr(31)||v.sequence::text ELSE '' END);
   INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body)
    VALUES(o,w,e,audit_value,audit_value,r,s,session_user,CASE WHEN phase_value='cleanup' THEN 'temporal_cleanup_delivery_finish' ELSE 'ordered_delivery_finish' END,digest(convert_to(to_jsonb(v)::text,'UTF8'),'sha256'),jsonb_build_object('composition',v.composition,'request',jsonb_build_object('device_id',d,'source_digest','sha256:'||encode(t.envelope_digest,'hex'),'digest','sha256:'||encode(v.envelope_digest,'hex'),'sequence',v.sequence),'effect_key',intent->>'effect_key','generation',1));
  END IF;
 END IF;
 IF phase_value='cleanup' THEN PERFORM zasp_temporal68.cleanup_current(o,w,e,r,s);
 ELSIF op IN('prepare','store') THEN PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);END IF;
 IF v.composition IS DISTINCT FROM (CASE WHEN phase_value='cleanup' THEN zasp_temporal68.cleanup_composition(o,w,e,d,r,s) ELSE zasp_sa_multistep_prior.deployment_composition(o,w,e,d) END) OR (v.composition->>'expires_at')::timestamptz<=clock_timestamp()+interval '1 minute' OR NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor delivery authority changed after wait';END IF;
 IF phase_value='cleanup' THEN PERFORM zasp_temporal68.delivery_history(t);END IF;
 IF phase_value='cleanup' AND v.state<>'acknowledged' AND (zasp_temporal68.cleanup_marker(t)->>'expires_at')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor cleanup marker expired after wait';END IF;
 response_value:=to_jsonb(v)||jsonb_build_object('effect_key',intent->>'effect_key');
 IF NOT zasp_sa_multistep_prior.deployment_wire(response_value,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor delivery response bound rejected';END IF;
 RETURN response_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_destinations(o text, w text, e text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE selected jsonb;locked_value jsonb;row_value record;d public.zasp_gateway_devices%ROWTYPE;c public.zasp_gateway_credentials%ROWTYPE;
 metadata jsonb:='[]'::jsonb;expires timestamptz;BEGIN
 SELECT COALESCE(jsonb_agg(jsonb_build_object('device_id',v.id,'credential_id',k.id) ORDER BY v.id),'[]'::jsonb) INTO selected
 FROM public.zasp_gateway_devices v JOIN LATERAL(SELECT id FROM public.zasp_gateway_credentials WHERE(organization_id,workspace_id,environment_id,device_id)=(o,w,e,v.id) AND revoked_at IS NULL AND expires_at>clock_timestamp() ORDER BY issued_at DESC,id DESC LIMIT 1) k ON true
 WHERE(v.organization_id,v.workspace_id,v.environment_id,v.state)=(o,w,e,'active');
 IF jsonb_array_length(selected) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered destination bound rejected';END IF;
 FOR row_value IN SELECT * FROM jsonb_to_recordset(selected) AS t(device_id text,credential_id text) ORDER BY device_id LOOP
  SELECT * INTO d FROM public.zasp_gateway_devices WHERE(organization_id,workspace_id,environment_id,id,state)=(o,w,e,row_value.device_id,'active') FOR SHARE NOWAIT;
  SELECT * INTO c FROM public.zasp_gateway_credentials WHERE(organization_id,workspace_id,environment_id,device_id,id)=(o,w,e,row_value.device_id,row_value.credential_id) AND revoked_at IS NULL AND expires_at>clock_timestamp() FOR SHARE NOWAIT;
  IF d.id IS NULL OR c.id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered destination changed';END IF;
  expires:=CASE WHEN expires IS NULL THEN c.expires_at ELSE least(expires,c.expires_at) END;
  -- Native gateway replay advances version with its floor on ordinary event
  -- traffic. Those bookkeeping fields do not change device authority.
  metadata:=metadata||jsonb_build_array(jsonb_build_array(d.id,encode(digest(convert_to((to_jsonb(d)-ARRAY['replay_floor','version','updated_at'])::text,'UTF8'),'sha256'),'hex'),c.id,encode(digest(convert_to(to_jsonb(c)::text,'UTF8'),'sha256'),'hex')));
 END LOOP;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('device_id',v.id,'credential_id',k.id) ORDER BY v.id),'[]'::jsonb) INTO locked_value
 FROM public.zasp_gateway_devices v JOIN LATERAL(SELECT id FROM public.zasp_gateway_credentials WHERE(organization_id,workspace_id,environment_id,device_id)=(o,w,e,v.id) AND revoked_at IS NULL AND expires_at>clock_timestamp() ORDER BY issued_at DESC,id DESC LIMIT 1) k ON true
 WHERE(v.organization_id,v.workspace_id,v.environment_id,v.state)=(o,w,e,'active');
 IF selected IS DISTINCT FROM locked_value OR expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered selected destination changed';END IF;
 RETURN jsonb_build_object('ids',(SELECT jsonb_agg(t->'device_id' ORDER BY t->>'device_id') FROM jsonb_array_elements(selected) t),'targets_digest',encode(digest(convert_to(selected::text,'UTF8'),'sha256'),'hex'),'identity_digest',encode(digest(convert_to(metadata::text,'UTF8'),'sha256'),'hex'),'fresh_until_ms',floor(extract(epoch FROM expires)*1000)::bigint);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_dispatch_readback(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proof jsonb;v jsonb;BEGIN
 proof:=zasp_authorization80_worker.require_ordered68_test('linked.dispatch',q);
 v:=zasp_authorization80_worker.ordered68_linked_native(q||jsonb_build_object('operation','read'));
 IF v->'send_permit' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered dispatch readback permit rejected';END IF;
 PERFORM zasp_authorization80_worker.ordered68_test_exit('linked.dispatch',proof);RETURN v;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_effect_facts(compensation boolean, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;c zasp_temporal65.commands%ROWTYPE;
 tr public.zasp_security_agent_trigger_receipts%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;a zasp_authorization80_worker.ordered_associations%ROWTYPE;
 cv jsonb;resolution jsonb;metadata jsonb;checks jsonb;source_hash text;target_hash text;product text;expires timestamptz;k text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered source requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF compensation IS NULL OR NOT zasp_temporal68.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered source principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest']) OR octet_length(q::text)>4096
  OR jsonb_typeof(q->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(q->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
  OR jsonb_typeof(q->'input_digest') IS DISTINCT FROM 'string' OR NOT COALESCE(q->>'input_digest'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered start rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered source scope rejected';END IF;
 END LOOP;
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') FOR SHARE;
 IF x.run_id IS NULL OR x.execution_owner<>'temporal' OR to_jsonb(x.definition_version) IS DISTINCT FROM q->'definition_version' OR x.input_digest IS DISTINCT FROM q->>'input_digest' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered owner changed';END IF;
 SELECT * INTO r FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF r.run_id IS NULL OR r.definition_version<>x.definition_version OR r.lease_owner IS NOT NULL OR r.lease_token IS NOT NULL OR r.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered parent changed';END IF;
 SELECT * INTO c FROM zasp_temporal65.commands WHERE(organization_id,workspace_id,environment_id,run_id,kind)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,'start') FOR SHARE;
 SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,r.definition_id,r.trigger_id) FOR SHARE;
 IF c.run_id IS NULL OR c.execution_owner<>'temporal' OR(c.definition_version,c.input_digest) IS DISTINCT FROM(x.definition_version,x.input_digest)
  OR tr.run_id IS NULL OR encode(tr.trigger_digest,'hex') IS DISTINCT FROM x.input_digest OR tr.trigger_kind NOT IN('finding','attack_path')
  OR r.run_id IS DISTINCT FROM public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_run',r.definition_id||chr(31)||r.trigger_id||chr(31)||tr.trigger_version::text) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered retained start changed';END IF;
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(r.organization_id,r.workspace_id,r.environment_id,r.definition_id,r.definition_version) FOR SHARE;
 IF h.definition_id IS NULL OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') OR h.definition->'allowed_actions' IS DISTINCT FROM '["create_temporary_policy","run_test"]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered historical definition changed';END IF;
 source_hash:=encode(digest(convert_to(jsonb_build_array(x.execution_owner,r.definition_id,x.definition_version,x.input_digest,c.event_id,tr.trigger_kind,tr.trigger_id,tr.trigger_version,encode(h.definition_digest,'hex'))::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO a FROM zasp_authorization80_worker.ordered_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF compensation THEN
  IF a.run_id IS NULL OR(a.definition_id,a.definition_version,a.definition_digest,a.source_digest) IS DISTINCT FROM(r.definition_id,r.definition_version,encode(h.definition_digest,'hex'),source_hash)
   OR NOT EXISTS(SELECT 1 FROM zasp_temporal68.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered captured planning absent';END IF;
  metadata:=to_jsonb(a);checks:='[]'::jsonb;
 ELSE
  IF r.state NOT IN('running','verifying') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered task inactive';END IF;
  cv:=zasp_sa_multistep_prior.context(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
  IF cv->'definition' IS DISTINCT FROM h.definition THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered definition binding changed';END IF;
  resolution:=zasp_temporal68.test_target(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id',cv->'test'->>'target_kind',cv->'test'->>'definition_id',(cv->'test'->>'version')::bigint);
  SELECT i.product_kind,least(i.fresh_until,b.valid_until) INTO STRICT product,expires FROM public.zasp_inventory_entities i JOIN public.zasp_attack_lab_credential_bindings b ON(b.organization_id,b.workspace_id,b.environment_id,b.binding_id)=(i.organization_id,i.workspace_id,i.environment_id,resolution#>>'{comparison,credential_binding_id}') WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id') FOR SHARE OF i,b;
  IF product IS NULL OR product NOT IN('agent','tool') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target kind rejected';END IF;
  IF expires IS NULL OR expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target expired';END IF;
  target_hash:=encode(digest(convert_to(resolution::text,'UTF8'),'sha256'),'hex');
  metadata:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,
   'principal_id',public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_definition_service',r.definition_id),'grantor_id',r.requested_by,
   'definition_id',r.definition_id,'definition_version',r.definition_version,'definition_digest',encode(h.definition_digest,'hex'),'source_digest',source_hash,
   'test_id',cv->'test'->>'definition_id','test_version',cv->'test'->'version','target_id',cv->'test'->>'target_id','target_kind',product,'target_digest',target_hash,
   'trigger_kind',tr.trigger_kind,'trigger_id',tr.trigger_id,'credential_binding_id',resolution#>>'{comparison,credential_binding_id}',
   'snapshot_id',resolution#>>'{provenance,snapshot_id}','evidence_id',resolution#>>'{provenance,evidence_id}','integration_id',resolution#>>'{provenance,integration_id}','source',resolution#>>'{provenance,source}');
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',r.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',r.run_id,'permission','manage_workflows'),jsonb_build_object('kind','test','id',cv->'test'->>'definition_id','permission','view'),jsonb_build_object('kind',product,'id',cv->'test'->>'target_id','permission','view'),jsonb_build_object('kind',tr.trigger_kind,'id',tr.trigger_id,'permission','view'));
 END IF;
 RETURN metadata||jsonb_build_object('run_state',r.state,'run_version',r.version,'checks',checks,'session_user',session_user,'fresh_until_ms',CASE WHEN compensation THEN NULL ELSE floor(extract(epoch FROM expires)*1000)::bigint END);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_effect_metadata(phase text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;a zasp_authorization80_worker.ordered_associations%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;plan_value public.zasp_security_agent_plans%ROWTYPE;
 v zasp_temporal68.effects%ROWTYPE;f jsonb;reference_value jsonb;step_value jsonb;effect_value jsonb;destinations jsonb;checks jsonb;captured_targets jsonb;
 compensation boolean:=phase IN('effect.read','effect.unknown');BEGIN
 IF phase IS NULL OR phase NOT IN('effect.reserve','effect.start','effect.read','effect.unknown') OR octet_length(q::text)>4096
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
 OR q->'generation' IS DISTINCT FROM '1'::jsonb OR q->'payload' IS DISTINCT FROM '{}'::jsonb OR q->>'operation' IS DISTINCT FROM split_part(phase,'.',2)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered effect request rejected';END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered effect requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect principal rejected';END IF;
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=q->>'organization_id' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect organization absent';END IF;
 PERFORM zasp_sa_multistep_prior.application_lock(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect owner absent';END IF;
 reference_value:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'definition_version',x.definition_version,'input_digest',x.input_digest);
 f:=zasp_authorization80_worker.ordered68_effect_facts(compensation,reference_value);
 a:=jsonb_populate_record(NULL::zasp_authorization80_worker.ordered_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_associations s WHERE s=a) OR NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true) AND(compensation OR s.target_current AND s.fresh_until>clock_timestamp())) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect admission changed';END IF;
 SELECT * INTO st FROM public.zasp_security_agent_steps WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,q->>'step_id') FOR SHARE;
 SELECT * INTO plan_value FROM public.zasp_security_agent_plans WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF st.step_id IS NULL OR plan_value.run_id IS NULL OR st.step_index NOT IN(0,1) OR st.action_key IS DISTINCT FROM (CASE st.step_index WHEN 0 THEN 'create_temporary_policy' ELSE 'run_test' END)
 OR plan_value.plan->'steps'->st.step_index->>'step_id' IS DISTINCT FROM st.step_id THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect step changed';END IF;
 PERFORM zasp_temporal68.current_plan(x.organization_id,x.workspace_id,x.environment_id,x.run_id,NOT compensation);
 SELECT * INTO v FROM zasp_temporal68.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,1) FOR SHARE;
 IF v.run_id IS NULL AND phase<>'effect.reserve' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered captured effect absent';END IF;
 IF v.run_id IS NOT NULL THEN
  IF v.effect_key IS DISTINCT FROM zasp_temporal68.effect_identity(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,1) OR(v.input_digest,v.plan_hash,v.action_key) IS DISTINCT FROM(st.input_digest,plan_value.plan_hash,st.action_key)
  OR v.snapshot_digest IS DISTINCT FROM digest(convert_to(v.snapshot::text,'UTF8'),'sha256') OR v.snapshot->>'input_digest' IS DISTINCT FROM encode(st.input_digest,'hex') OR v.snapshot->>'plan_hash' IS DISTINCT FROM encode(plan_value.plan_hash,'hex')
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.step_id,s.action_key,s.input_digest)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,st.action_key,st.input_digest))
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_effects s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.step_id,s.action_key,s.input_digest)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,st.action_key,st.input_digest) AND s.lease_owner IS NULL AND s.lease_token IS NULL AND s.lease_expires_at IS NULL)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured effect changed';END IF;
  effect_value:=jsonb_build_object('effect_key',v.effect_key,'generation',v.generation,'state',v.state,'snapshot_digest',encode(v.snapshot_digest,'hex'));
 END IF;
 checks:='[]'::jsonb;
 IF NOT compensation THEN
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',a.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',a.run_id,'permission','manage_workflows'));
  IF st.step_index=0 THEN
   destinations:=zasp_authorization80_worker.ordered68_destinations(x.organization_id,x.workspace_id,x.environment_id);
   IF v.run_id IS NOT NULL THEN
    SELECT jsonb_agg(jsonb_build_object('device_id',t->>'device_id','credential_id',t->>'credential_id') ORDER BY t->>'device_id') INTO captured_targets FROM jsonb_array_elements(v.snapshot->'targets') t;
    IF destinations->>'targets_digest' IS DISTINCT FROM encode(digest(convert_to(captured_targets::text,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured destinations changed';END IF;
   END IF;
   checks:=checks||(SELECT jsonb_agg(jsonb_build_object('kind','gateway_device','id',id_value,'permission','manage_workflows') ORDER BY id_value) FROM jsonb_array_elements_text(destinations->'ids') id_value);
   f:=jsonb_set(f,'{fresh_until_ms}',to_jsonb(least((f->>'fresh_until_ms')::bigint,(destinations->>'fresh_until_ms')::bigint)));
  ELSE
   checks:=checks||jsonb_build_array(jsonb_build_object('kind','test','id',a.test_id,'permission','run_tests'),jsonb_build_object('kind',a.target_kind,'id',a.target_id,'permission','run_tests'));
  END IF;
 END IF;
 step_value:=jsonb_build_object('step_id',st.step_id,'action_key',st.action_key,'state',st.state,'version',st.version,'input_digest',encode(st.input_digest,'hex'),'plan_hash',encode(plan_value.plan_hash,'hex'));
 RETURN f||jsonb_build_object('ordered_action_key',st.action_key,'ordered_device_ids',CASE WHEN compensation OR st.step_index=1 THEN '[]'::jsonb ELSE destinations->'ids' END,'checks',checks,'execution_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'step',step_value,'effect',effect_value,'destination_digest',destinations->'identity_digest','ordered_targets_digest',destinations->'targets_digest');
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_effect_read(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;op text;k text;g bigint;permit boolean:=false;live_value boolean;targets jsonb;snapshot_value jsonb;
 f zasp_temporal68.effects%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;device record;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor effect requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor catalog unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
  OR octet_length(q::text)>4096 OR q->'generation' IS DISTINCT FROM '1'::jsonb OR q->'payload' IS DISTINCT FROM '{}'::jsonb
  OR NOT COALESCE(q->>'operation' IN('read'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor effect request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id','step_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor effect scope rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';g:=1;op:=q->>'operation';live_value:=op IN('reserve','start');
 IF NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT live_value AND zasp_temporal68.principal_ready('zasp_temporal_compensation'))
  OR NOT zasp_temporal66.is_temporal(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor effect authority rejected';END IF;
 -- Use the existing Organization/budget/run/step/device order, with NOWAIT
 -- on independently owned deployment resources. No external IO is in here.
 PERFORM zasp_sa_multistep_prior.application_lock(o,w,e,r);
 PERFORM zasp_temporal68.current_plan(o,w,e,r,live_value);
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO st FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF NOT FOUND OR st.step_index NOT IN(0,1) OR st.action_key IS DISTINCT FROM (CASE st.step_index WHEN 0 THEN 'create_temporary_policy' ELSE 'run_test' END)
  OR rr.lease_token IS NOT NULL OR rr.lease_owner IS NOT NULL OR rr.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect step absent';END IF;
 IF live_value THEN
  IF st.step_index=0 THEN PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);
  ELSE PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);END IF;
 END IF;
 SELECT * INTO f FROM zasp_temporal68.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,g) FOR UPDATE;
 IF NOT FOUND THEN
  IF op<>'reserve' OR st.state<>'authorized' OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s))
   OR (SELECT count(*) FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))<>st.step_index
   OR st.step_index>=b.max_steps THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect reservation unavailable';END IF;
  INSERT INTO public.zasp_security_agent_step_reservations(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest) VALUES(o,w,e,r,s,st.action_key,st.input_digest);
  INSERT INTO public.zasp_security_agent_effects(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state,attempt) VALUES(o,w,e,r,s,st.action_key,st.input_digest,'pending',1);
  IF st.step_index=0 THEN
   SELECT COALESCE(jsonb_agg(jsonb_build_object('device_id',d.id,'credential_id',c.id) ORDER BY d.id),'[]'::jsonb) INTO targets FROM public.zasp_gateway_devices d JOIN LATERAL(SELECT id FROM public.zasp_gateway_credentials WHERE (organization_id,workspace_id,environment_id,device_id)=(o,w,e,d.id) AND revoked_at IS NULL AND expires_at>clock_timestamp() ORDER BY issued_at DESC,id DESC LIMIT 1)c ON true WHERE (d.organization_id,d.workspace_id,d.environment_id,d.state)=(o,w,e,'active');
   IF jsonb_array_length(targets) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor gateway target bound rejected';END IF;
   FOR device IN SELECT * FROM jsonb_to_recordset(targets) AS t(device_id text,credential_id text) LOOP
    INSERT INTO public.zasp_security_agent_temporary_policy_targets(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id,credential_id,sequence,policy_version) VALUES(o,w,e,r,s,'apply',device.device_id,device.credential_id,1,1);
   END LOOP;
   SELECT jsonb_agg(jsonb_build_object('device_id',device_id,'credential_id',credential_id,'sequence',sequence,'policy_version',policy_version) ORDER BY device_id) INTO targets FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply');
  ELSE
   targets:=zasp_temporal68.test_reserve(o,w,e,r,s);
  END IF;
  snapshot_value:=jsonb_build_object('plan_hash',encode(rr.plan_hash,'hex'),'input_digest',encode(st.input_digest,'hex'),'targets',targets);
  INSERT INTO zasp_temporal68.effects VALUES(o,w,e,r,s,g,zasp_temporal68.effect_identity(o,w,e,r,s,g),st.action_key,st.input_digest,rr.plan_hash,snapshot_value,digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'reserved',NULL,NULL) RETURNING * INTO f;
  UPDATE public.zasp_security_agent_steps SET state='executing',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 END IF;
 IF f.effect_key IS DISTINCT FROM zasp_temporal68.effect_identity(o,w,e,r,s,g) OR (f.input_digest,f.plan_hash,f.action_key) IS DISTINCT FROM(st.input_digest,rr.plan_hash,st.action_key)
  OR f.snapshot_digest IS DISTINCT FROM digest(convert_to(f.snapshot::text,'UTF8'),'sha256') OR f.snapshot->>'plan_hash' IS DISTINCT FROM encode(rr.plan_hash,'hex') OR f.snapshot->>'input_digest' IS DISTINCT FROM encode(st.input_digest,'hex')
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_effects x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.action_key,x.input_digest)=(o,w,e,r,s,f.action_key,f.input_digest) AND x.lease_token IS NULL AND x.lease_owner IS NULL AND x.lease_expires_at IS NULL)
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.action_key,x.input_digest)=(o,w,e,r,s,f.action_key,f.input_digest)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect intent changed';END IF;
 IF op='start' AND f.state='reserved' THEN
  UPDATE zasp_temporal68.effects SET state='started',started_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,g) RETURNING * INTO f;
  UPDATE public.zasp_security_agent_effects SET state='unknown_outcome',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  permit:=true;
 ELSIF op='unknown' THEN
  IF f.state NOT IN('started','unknown') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect not sent';END IF;
  UPDATE zasp_temporal68.effects SET state='unknown' WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,g) RETURNING * INTO f;
 END IF;
 IF live_value THEN
  IF st.step_index=0 THEN PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);ELSE PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);END IF;
 END IF;
 IF NOT zasp_temporal68.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor effect catalog changed';END IF;
 RETURN to_jsonb(f)||jsonb_build_object('send_permit',permit);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_effect_source(phase text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE f jsonb;c zasp_authorization80_worker.ordered_effect_scope%ROWTYPE;compensation boolean:=phase IN('effect.read','effect.unknown');BEGIN
 f:=zasp_authorization80_worker.ordered68_effect_metadata(phase,q);
 SELECT * INTO c FROM zasp_authorization80_worker.ordered_effect_scope WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 IF c.run_id IS NULL OR c.action_key IS DISTINCT FROM f->>'ordered_action_key'
 OR NOT compensation AND(NOT c.target_current OR c.fresh_until<=clock_timestamp() OR(c.device_ids,c.destination_digest,c.targets_digest) IS DISTINCT FROM(f->'ordered_device_ids',f->>'destination_digest',f->>'ordered_targets_digest')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect projection capture changed';END IF;
 RETURN f;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_facts(compensation boolean, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;c zasp_temporal65.commands%ROWTYPE;
 tr public.zasp_security_agent_trigger_receipts%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;a zasp_authorization80_worker.ordered_associations%ROWTYPE;
 cv jsonb;resolution jsonb;metadata jsonb;checks jsonb;source_hash text;target_hash text;product text;expires timestamptz;k text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered source requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF compensation IS NULL OR NOT zasp_temporal68.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered source principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest']) OR octet_length(q::text)>4096
  OR jsonb_typeof(q->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(q->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
  OR jsonb_typeof(q->'input_digest') IS DISTINCT FROM 'string' OR NOT COALESCE(q->>'input_digest'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered start rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered source scope rejected';END IF;
 END LOOP;
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') FOR SHARE;
 IF x.run_id IS NULL OR x.execution_owner<>'temporal' OR to_jsonb(x.definition_version) IS DISTINCT FROM q->'definition_version' OR x.input_digest IS DISTINCT FROM q->>'input_digest' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered owner changed';END IF;
 SELECT * INTO r FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF r.run_id IS NULL OR r.definition_version<>x.definition_version OR r.lease_owner IS NOT NULL OR r.lease_token IS NOT NULL OR r.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered parent changed';END IF;
 SELECT * INTO c FROM zasp_temporal65.commands WHERE(organization_id,workspace_id,environment_id,run_id,kind)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,'start') FOR SHARE;
 SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,r.definition_id,r.trigger_id) FOR SHARE;
 IF c.run_id IS NULL OR c.execution_owner<>'temporal' OR(c.definition_version,c.input_digest) IS DISTINCT FROM(x.definition_version,x.input_digest)
  OR tr.run_id IS NULL OR encode(tr.trigger_digest,'hex') IS DISTINCT FROM x.input_digest OR tr.trigger_kind NOT IN('finding','attack_path')
  OR r.run_id IS DISTINCT FROM public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_run',r.definition_id||chr(31)||r.trigger_id||chr(31)||tr.trigger_version::text) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered retained start changed';END IF;
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(r.organization_id,r.workspace_id,r.environment_id,r.definition_id,r.definition_version) FOR SHARE;
 IF h.definition_id IS NULL OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') OR h.definition->'allowed_actions' IS DISTINCT FROM '["create_temporary_policy","run_test"]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered historical definition changed';END IF;
 source_hash:=encode(digest(convert_to(jsonb_build_array(x.execution_owner,r.definition_id,x.definition_version,x.input_digest,c.event_id,tr.trigger_kind,tr.trigger_id,tr.trigger_version,encode(h.definition_digest,'hex'))::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO a FROM zasp_authorization80_worker.ordered_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF compensation THEN
  IF a.run_id IS NULL OR(a.definition_id,a.definition_version,a.definition_digest,a.source_digest) IS DISTINCT FROM(r.definition_id,r.definition_version,encode(h.definition_digest,'hex'),source_hash)
   OR NOT EXISTS(SELECT 1 FROM zasp_temporal68.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered captured planning absent';END IF;
  metadata:=to_jsonb(a);checks:='[]'::jsonb;
 ELSE
  IF r.state NOT IN('queued','planning','waiting_approval') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered task inactive';END IF;
  cv:=zasp_sa_multistep_prior.context(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
  IF cv->'definition' IS DISTINCT FROM h.definition THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered definition binding changed';END IF;
  resolution:=zasp_temporal68.test_target(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id',cv->'test'->>'target_kind',cv->'test'->>'definition_id',(cv->'test'->>'version')::bigint);
  SELECT i.product_kind,least(i.fresh_until,b.valid_until) INTO STRICT product,expires FROM public.zasp_inventory_entities i JOIN public.zasp_attack_lab_credential_bindings b ON(b.organization_id,b.workspace_id,b.environment_id,b.binding_id)=(i.organization_id,i.workspace_id,i.environment_id,resolution#>>'{comparison,credential_binding_id}') WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id') FOR SHARE OF i,b;
  IF product IS NULL OR product NOT IN('agent','tool') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target kind rejected';END IF;
  IF expires IS NULL OR expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target expired';END IF;
  target_hash:=encode(digest(convert_to(resolution::text,'UTF8'),'sha256'),'hex');
  metadata:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,
   'principal_id',public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_definition_service',r.definition_id),'grantor_id',r.requested_by,
   'definition_id',r.definition_id,'definition_version',r.definition_version,'definition_digest',encode(h.definition_digest,'hex'),'source_digest',source_hash,
   'test_id',cv->'test'->>'definition_id','test_version',cv->'test'->'version','target_id',cv->'test'->>'target_id','target_kind',product,'target_digest',target_hash,
   'trigger_kind',tr.trigger_kind,'trigger_id',tr.trigger_id,'credential_binding_id',resolution#>>'{comparison,credential_binding_id}',
   'snapshot_id',resolution#>>'{provenance,snapshot_id}','evidence_id',resolution#>>'{provenance,evidence_id}','integration_id',resolution#>>'{provenance,integration_id}','source',resolution#>>'{provenance,source}');
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',r.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',r.run_id,'permission','manage_workflows'),jsonb_build_object('kind','test','id',cv->'test'->>'definition_id','permission','view'),jsonb_build_object('kind',product,'id',cv->'test'->>'target_id','permission','view'),jsonb_build_object('kind',tr.trigger_kind,'id',tr.trigger_id,'permission','view'));
 END IF;
 RETURN metadata||jsonb_build_object('run_state',r.state,'run_version',r.version,'checks',checks,'session_user',session_user,'fresh_until_ms',CASE WHEN compensation THEN NULL ELSE floor(extract(epoch FROM expires)*1000)::bigint END);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_invocation_native(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;child_id text;op text;k text;category_value text;key_value text;payload jsonb;resolution jsonb;request_hash bytea;curated text;result_value jsonb;new_start boolean:=false;
 link public.zasp_security_agent_test_links%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;f zasp_temporal68.effects%ROWTYPE;j zasp_temporal68.invocations%ROWTYPE;prepared zasp_temporal68.test_inputs%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor invocation requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.adapter_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor invocation principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','effect_key','operation','payload','checksum','fingerprint']) OR octet_length(q::text)>8192
  OR NOT COALESCE(q->>'operation' IN('resolve','start','complete') AND q->>'effect_key'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation scope rejected';END IF;
 END LOOP;
 IF NOT COALESCE(zasp_temporal68.adapter_ready(q->>'checksum',q->>'fingerprint'),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor invocation version rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';child_id:=q->>'run_id';op:=q->>'operation';key_value:=q->>'effect_key';payload:=q->'payload';category_value:=payload->>'category';
 IF NOT zasp_sa_multistep_prior.closed(payload,CASE op WHEN 'resolve' THEN ARRAY['category','target_id','target_kind'] WHEN 'start' THEN ARRAY['category','request_digest'] ELSE ARRAY['category','request_digest','http_status','response_digest','protected','credential_version_digest'] END)
  OR NOT COALESCE(category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation payload rejected';END IF;
 SELECT * INTO link FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,child_id);
 IF NOT FOUND OR NOT zasp_temporal66.is_temporal(o,w,e,link.run_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor invocation owner rejected';END IF;
 PERFORM zasp_sa_multistep_prior.test_lock(o,w,e,link.run_id);
 PERFORM zasp_temporal68.current_plan(o,w,e,link.run_id,false);
 SELECT * INTO f FROM zasp_temporal68.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation,effect_key,action_key)=(o,w,e,link.run_id,link.step_id,1,key_value,'run_test') FOR UPDATE;
 SELECT * INTO child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,child_id) FOR UPDATE NOWAIT;
 SELECT * INTO prepared FROM zasp_temporal68.test_inputs WHERE (organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(o,w,e,link.run_id,link.step_id,child_id);
 IF NOT zasp_temporal68.test_intent_valid(o,w,e,link.run_id,link.step_id) OR f.run_id IS NULL OR prepared.run_id IS NULL OR child.run_id IS NULL OR f.effect_key IS DISTINCT FROM zasp_temporal68.effect_identity(o,w,e,link.run_id,link.step_id,1)
  OR f.snapshot_digest IS DISTINCT FROM digest(convert_to(f.snapshot::text,'UTF8'),'sha256') OR f.snapshot->'targets'->>'test_run_id' IS DISTINCT FROM child_id
  OR f.snapshot->'targets'->>'input_digest' IS DISTINCT FROM encode(child.input_digest,'hex') OR f.input_digest IS DISTINCT FROM link.input_digest
  OR (link.test_definition_id,link.test_definition_version) IS DISTINCT FROM(child.definition_id,child.definition_version)
  OR NOT link.test_categories ? category_value OR link.test_categories IS DISTINCT FROM f.snapshot->'targets'->'resolution'->'comparison'->'categories'
  OR child.worker_id IS NOT NULL OR child.lease_token IS NOT NULL OR child.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation association changed';END IF;
 PERFORM zasp_sa_multistep_prior.test_validate_input(o,w,e,link.run_id,link.step_id,prepared.manifest,prepared.body);
 resolution:=f.snapshot->'targets'->'resolution';
 IF op<>'complete' THEN
  PERFORM zasp_sa_multistep_prior.test_current(o,w,e,link.run_id,link.step_id);
  IF child.state<>'queued' OR child.cancel_requested OR link.reconcile_state<>'pending' OR f.state NOT IN('started','unknown')
   OR resolution IS DISTINCT FROM zasp_temporal68.test_target(o,w,e,link.target_id,link.target_kind,link.test_definition_id,link.test_definition_version) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation current authority changed';END IF;
 END IF;
 IF op='resolve' THEN
  IF (payload->>'target_id',payload->>'target_kind') IS DISTINCT FROM(link.target_id,link.target_kind) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation target rejected';END IF;
  result_value:=resolution->'binding';
 ELSE
  IF NOT COALESCE(payload->>'request_digest'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation digest rejected';END IF;
  request_hash:=decode(payload->>'request_digest','hex');
  curated:='{"schema_version":"red-team-target-v1","run_id":"'||child_id||'","target_id":"'||link.target_id||'","target_kind":"'||link.target_kind||'","category":"'||category_value||'","input":'||to_json(zasp_sa_multistep_prior.test_prompt(category_value))::text||'}';
  IF request_hash IS DISTINCT FROM digest(convert_to(curated,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor curated invocation rejected';END IF;
  SELECT * INTO j FROM zasp_temporal68.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child_id,category_value) FOR UPDATE;
  IF j.test_run_id IS NOT NULL AND (j.effect_key,j.input_digest,j.request_digest,j.target_resolution) IS DISTINCT FROM(key_value,child.input_digest,request_hash,resolution) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation replay conflict';END IF;
  IF op='start' AND j.state IS DISTINCT FROM 'completed' THEN
   IF f.state<>'started' OR EXISTS(SELECT 1 FROM zasp_temporal68.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,state)=(o,w,e,child_id,'started')) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor invocation outcome unknown';END IF;
   INSERT INTO zasp_temporal68.invocations(organization_id,workspace_id,environment_id,test_run_id,attempt,category,input_digest,request_digest,target_resolution,state,effect_key) VALUES(o,w,e,child_id,1,category_value,child.input_digest,request_hash,resolution,'started',key_value) RETURNING * INTO j;
   new_start:=true;
  ELSIF op='complete' THEN
   IF j.test_run_id IS NULL OR NOT COALESCE(payload->>'response_digest'~'^[a-f0-9]{64}$' AND payload->>'credential_version_digest'~'^[a-f0-9]{64}$' AND payload->>'credential_version_digest'<>repeat('0',64)
    AND jsonb_typeof(payload->'http_status')='number' AND payload->>'http_status'~'^[2-5][0-9]{2}$' AND (payload->'http_status'='200'::jsonb AND jsonb_typeof(payload->'protected')='boolean' OR payload->'http_status'<>'200'::jsonb AND payload->'protected'='null'::jsonb),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation observation rejected';END IF;
   IF j.state='completed' THEN
    IF (j.http_status,j.response_digest,j.protected,j.credential_version_digest) IS DISTINCT FROM((payload->>'http_status')::integer,decode(payload->>'response_digest','hex'),(payload->>'protected')::boolean,decode(payload->>'credential_version_digest','hex')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor observation replay conflict';END IF;
   ELSE
    UPDATE zasp_temporal68.invocations SET state='completed',completed_at=clock_timestamp(),http_status=(payload->>'http_status')::integer,response_digest=decode(payload->>'response_digest','hex'),protected=(payload->>'protected')::boolean,credential_version_digest=decode(payload->>'credential_version_digest','hex') WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child_id,category_value) RETURNING * INTO j;
   END IF;
  END IF;
  result_value:=jsonb_build_object('state',j.state,'attempt',1,'category',category_value,'input_digest',encode(j.input_digest,'hex'),'request_digest',encode(j.request_digest,'hex'),'target_binding',j.target_resolution->'binding','target_provenance',j.target_resolution->'provenance','target_comparison',j.target_resolution->'comparison','effect_key',j.effect_key);
  IF j.state='completed' THEN result_value:=result_value||jsonb_build_object('run_id',child_id,'http_status',j.http_status,'response_digest',encode(j.response_digest,'hex'),'protected',j.protected,'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));END IF;
 END IF;
 IF op<>'complete' THEN PERFORM zasp_sa_multistep_prior.test_current(o,w,e,link.run_id,link.step_id);END IF;
 IF NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.adapter_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor invocation authority changed';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_linked_native(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;op text;intent jsonb;p jsonb;doc jsonb;bytes bytea;resolution jsonb;permit boolean:=false;
 link public.zasp_security_agent_test_links%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;prepared zasp_temporal68.test_inputs%ROWTYPE;
BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor linked principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR octet_length(q::text)>131072
  OR NOT COALESCE(q->>'operation' IN('read','input','dispatch'),false) OR jsonb_typeof(q->'payload') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor linked request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';op:=q->>'operation';p:=q->'payload';
 intent:=zasp_authorization80_worker.ordered68_effect_read(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);
 IF intent->>'action_key' IS DISTINCT FROM 'run_test' OR intent->>'state' NOT IN('reserved','started','unknown') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked intent unavailable';END IF;
 SELECT * INTO link FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR UPDATE;
 SELECT * INTO child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link.test_run_id) FOR UPDATE NOWAIT;
 IF child.run_id IS NULL OR child.state<>'queued' OR child.cancel_requested OR child.lease_token IS NOT NULL OR child.worker_id IS NOT NULL OR child.lease_expires_at IS NOT NULL
  OR (link.test_definition_id,link.test_definition_version,link.input_digest,link.action_key) IS DISTINCT FROM(child.definition_id,child.definition_version,decode(intent->'snapshot'->>'input_digest','hex'),'run_test'::text)
  OR child.run_id IS DISTINCT FROM intent->'snapshot'->'targets'->>'test_run_id' OR encode(child.input_digest,'hex') IS DISTINCT FROM intent->'snapshot'->'targets'->>'input_digest'
  OR link.reconcile_state<>'pending' OR link.reconcile_token IS NOT NULL OR link.reconcile_worker IS NOT NULL OR link.reconcile_expires_at IS NOT NULL OR link.reconcile_settlement IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked association changed';END IF;
 resolution:=zasp_temporal68.test_target(o,w,e,link.target_id,link.target_kind,link.test_definition_id,link.test_definition_version);
 IF resolution IS DISTINCT FROM intent->'snapshot'->'targets'->'resolution' OR link.test_categories IS DISTINCT FROM resolution->'comparison'->'categories' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked target changed';END IF;
 SELECT * INTO prepared FROM zasp_temporal68.test_inputs WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF op='input' THEN
  IF NOT zasp_sa_multistep_prior.closed(p,ARRAY['manifest','body']) OR jsonb_typeof(p->'body') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor linked input rejected';END IF;
  bytes:=decode(p->>'body','base64');doc:=zasp_sa_multistep_prior.test_validate_input(o,w,e,r,s,p->'manifest',bytes);
  IF prepared.run_id IS NULL THEN
   IF intent->>'state'<>'reserved' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked input too late';END IF;
   INSERT INTO zasp_temporal68.test_inputs VALUES(o,w,e,r,s,child.run_id,p->'manifest',bytes) RETURNING * INTO prepared;
  ELSIF (prepared.manifest,prepared.body) IS DISTINCT FROM(p->'manifest',bytes) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked input replay changed';END IF;
 ELSIF p<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor linked unexpected payload';
 ELSIF op='dispatch' THEN
  IF prepared.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked input absent';END IF;
  PERFORM zasp_sa_multistep_prior.test_validate_input(o,w,e,r,s,prepared.manifest,prepared.body);
  intent:=zasp_authorization80_worker.ordered68_linked_start(q||jsonb_build_object('operation','start','payload','{}'::jsonb));permit:=(intent->>'send_permit')::boolean;
 END IF;
 PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);
 IF NOT zasp_temporal68.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor linked catalog changed';END IF;
 RETURN jsonb_build_object('effect_key',intent->>'effect_key','generation',1,'test_run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),'definition_id',child.definition_id,'definition_version',child.definition_version,'target_id',link.target_id,'target_kind',link.target_kind,'categories',link.test_categories,'target_resolution',resolution,'input_manifest',prepared.manifest,'input_body',convert_from(prepared.body,'UTF8'),'send_permit',permit);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_linked_start(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;op text;k text;g bigint;permit boolean:=false;live_value boolean;targets jsonb;snapshot_value jsonb;
 f zasp_temporal68.effects%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;device record;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor effect requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor catalog unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
  OR octet_length(q::text)>4096 OR q->'generation' IS DISTINCT FROM '1'::jsonb OR q->'payload' IS DISTINCT FROM '{}'::jsonb
  OR NOT COALESCE(q->>'operation' IN('start'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor effect request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id','step_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor effect scope rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';g:=1;op:=q->>'operation';live_value:=op IN('reserve','start');
 IF NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT live_value AND zasp_temporal68.principal_ready('zasp_temporal_compensation'))
  OR NOT zasp_temporal66.is_temporal(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor effect authority rejected';END IF;
 -- Use the existing Organization/budget/run/step/device order, with NOWAIT
 -- on independently owned deployment resources. No external IO is in here.
 PERFORM zasp_sa_multistep_prior.application_lock(o,w,e,r);
 PERFORM zasp_temporal68.current_plan(o,w,e,r,live_value);
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO st FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF NOT FOUND OR st.step_index NOT IN(0,1) OR st.action_key IS DISTINCT FROM (CASE st.step_index WHEN 0 THEN 'create_temporary_policy' ELSE 'run_test' END)
  OR rr.lease_token IS NOT NULL OR rr.lease_owner IS NOT NULL OR rr.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect step absent';END IF;
 IF live_value THEN
  IF st.step_index=0 THEN PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);
  ELSE PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);END IF;
 END IF;
 SELECT * INTO f FROM zasp_temporal68.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,g) FOR UPDATE;
 IF NOT FOUND THEN
  IF op<>'reserve' OR st.state<>'authorized' OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s))
   OR (SELECT count(*) FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))<>st.step_index
   OR st.step_index>=b.max_steps THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect reservation unavailable';END IF;
  INSERT INTO public.zasp_security_agent_step_reservations(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest) VALUES(o,w,e,r,s,st.action_key,st.input_digest);
  INSERT INTO public.zasp_security_agent_effects(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state,attempt) VALUES(o,w,e,r,s,st.action_key,st.input_digest,'pending',1);
  IF st.step_index=0 THEN
   SELECT COALESCE(jsonb_agg(jsonb_build_object('device_id',d.id,'credential_id',c.id) ORDER BY d.id),'[]'::jsonb) INTO targets FROM public.zasp_gateway_devices d JOIN LATERAL(SELECT id FROM public.zasp_gateway_credentials WHERE (organization_id,workspace_id,environment_id,device_id)=(o,w,e,d.id) AND revoked_at IS NULL AND expires_at>clock_timestamp() ORDER BY issued_at DESC,id DESC LIMIT 1)c ON true WHERE (d.organization_id,d.workspace_id,d.environment_id,d.state)=(o,w,e,'active');
   IF jsonb_array_length(targets) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor gateway target bound rejected';END IF;
   FOR device IN SELECT * FROM jsonb_to_recordset(targets) AS t(device_id text,credential_id text) LOOP
    INSERT INTO public.zasp_security_agent_temporary_policy_targets(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id,credential_id,sequence,policy_version) VALUES(o,w,e,r,s,'apply',device.device_id,device.credential_id,1,1);
   END LOOP;
   SELECT jsonb_agg(jsonb_build_object('device_id',device_id,'credential_id',credential_id,'sequence',sequence,'policy_version',policy_version) ORDER BY device_id) INTO targets FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply');
  ELSE
   targets:=zasp_temporal68.test_reserve(o,w,e,r,s);
  END IF;
  snapshot_value:=jsonb_build_object('plan_hash',encode(rr.plan_hash,'hex'),'input_digest',encode(st.input_digest,'hex'),'targets',targets);
  INSERT INTO zasp_temporal68.effects VALUES(o,w,e,r,s,g,zasp_temporal68.effect_identity(o,w,e,r,s,g),st.action_key,st.input_digest,rr.plan_hash,snapshot_value,digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'reserved',NULL,NULL) RETURNING * INTO f;
  UPDATE public.zasp_security_agent_steps SET state='executing',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 END IF;
 IF f.effect_key IS DISTINCT FROM zasp_temporal68.effect_identity(o,w,e,r,s,g) OR (f.input_digest,f.plan_hash,f.action_key) IS DISTINCT FROM(st.input_digest,rr.plan_hash,st.action_key)
  OR f.snapshot_digest IS DISTINCT FROM digest(convert_to(f.snapshot::text,'UTF8'),'sha256') OR f.snapshot->>'plan_hash' IS DISTINCT FROM encode(rr.plan_hash,'hex') OR f.snapshot->>'input_digest' IS DISTINCT FROM encode(st.input_digest,'hex')
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_effects x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.action_key,x.input_digest)=(o,w,e,r,s,f.action_key,f.input_digest) AND x.lease_token IS NULL AND x.lease_owner IS NULL AND x.lease_expires_at IS NULL)
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.action_key,x.input_digest)=(o,w,e,r,s,f.action_key,f.input_digest)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect intent changed';END IF;
 IF op='start' AND f.state='reserved' THEN
  UPDATE zasp_temporal68.effects SET state='started',started_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,g) RETURNING * INTO f;
  UPDATE public.zasp_security_agent_effects SET state='unknown_outcome',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  permit:=true;
 ELSIF op='unknown' THEN
  IF f.state NOT IN('started','unknown') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect not sent';END IF;
  UPDATE zasp_temporal68.effects SET state='unknown' WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,g) RETURNING * INTO f;
 END IF;
 IF live_value THEN
  IF st.step_index=0 THEN PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);ELSE PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);END IF;
 END IF;
 IF NOT zasp_temporal68.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor effect catalog changed';END IF;
 RETURN to_jsonb(f)||jsonb_build_object('send_permit',permit);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_operation_source(operation_value text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE compensation boolean;delivery_value boolean;phase_value text;f jsonb;effect_q jsonb;evidence jsonb;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;v zasp_temporal68.deliveries%ROWTYPE;
 c zasp_temporal68.cleanups%ROWTYPE;BEGIN
 IF operation_value IS NULL OR operation_value NOT IN('ordered68.application.read','ordered68.application.complete',
 'ordered68.cleanup.prepare','ordered68.cleanup.read','ordered68.cleanup.complete',
 'ordered68.delivery.apply.prepare','ordered68.delivery.apply.read','ordered68.delivery.apply.ack',
 'ordered68.delivery.cleanup.prepare','ordered68.delivery.cleanup.read','ordered68.delivery.cleanup.ack')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered ordinary operation rejected';END IF;
 compensation:=operation_value NOT IN('ordered68.application.read','ordered68.application.complete','ordered68.delivery.apply.prepare');
 delivery_value:=starts_with(operation_value,'ordered68.delivery.');
 phase_value:=CASE WHEN starts_with(operation_value,'ordered68.delivery.cleanup.') THEN 'cleanup' ELSE 'apply' END;
 IF NOT COALESCE(octet_length(q::text)<=32768 AND q->'generation'='1'::jsonb
 AND q->>'operation'=split_part(operation_value,'.',CASE WHEN delivery_value THEN 4 ELSE 3 END),false)
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
 OR NOT delivery_value AND q->'payload' IS DISTINCT FROM '{}'::jsonb
 OR delivery_value AND(NOT COALESCE(public.zasp_valid_product_id(q#>>'{payload,device_id}') AND q#>>'{payload,phase}'=phase_value,false)
  OR NOT zasp_sa_multistep_prior.closed(q->'payload',CASE WHEN q->>'operation'='prepare' THEN ARRAY['device_id','phase'] ELSE ARRAY['device_id','phase','digest'] END)
  OR q->>'operation'<>'prepare' AND NOT COALESCE(q#>>'{payload,digest}'~'^sha256:[a-f0-9]{64}$',false))
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered ordinary request rejected';END IF;
 IF operation_value='ordered68.delivery.apply.prepare' THEN
  -- Complete native composition capture precedes the creation of a delivery.
  RETURN zasp_authorization80_worker.ordered68_policy_source(operation_value,q);
 END IF;
 effect_q:=q||jsonb_build_object('operation',CASE WHEN compensation THEN 'read' ELSE 'start' END,'payload','{}'::jsonb);
 f:=zasp_authorization80_worker.ordered68_effect_source(CASE WHEN compensation THEN 'effect.read' ELSE 'effect.start' END,effect_q);
 IF f->>'ordered_action_key' IS DISTINCT FROM 'create_temporary_policy' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered ordinary Block intent rejected';END IF;
 IF NOT compensation THEN
  -- First completion and receipt replay both retain all current native gates.
  PERFORM zasp_sa_multistep_prior.application_current(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 END IF;
 IF delivery_value THEN
  SELECT * INTO t FROM public.zasp_security_agent_temporary_policy_targets
  WHERE(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',phase_value,q#>>'{payload,device_id}') FOR UPDATE;
  IF t.device_id IS NULL OR t.state NOT IN('stored','verified') OR t.envelope_digest IS NULL OR t.desired_generation IS NULL
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured delivery target absent';END IF;
  SELECT * INTO v FROM zasp_temporal68.deliveries
  WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation,phase,device_id)=(t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id,1,phase_value,t.device_id) FOR UPDATE;
  IF v.run_id IS NULL AND operation_value<>'ordered68.delivery.cleanup.prepare'
   OR v.run_id IS NOT NULL AND(v.source_sequence,v.source_digest,v.credential_id) IS DISTINCT FROM(t.sequence,t.envelope_digest,t.credential_id)
   OR q->>'operation'<>'prepare' AND(v.state NOT IN('stored','read','acknowledged') OR q#>>'{payload,digest}' IS DISTINCT FROM 'sha256:'||encode(v.envelope_digest,'hex'))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured delivery association changed';END IF;
  IF phase_value='cleanup' THEN
   PERFORM zasp_temporal68.cleanup_current(t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id);
  END IF;
  evidence:=jsonb_build_array(zasp_authorization80_worker.ordered68_row_json(t),zasp_authorization80_worker.ordered68_row_json(v));
 ELSIF starts_with(operation_value,'ordered68.cleanup.') THEN
  SELECT * INTO c FROM zasp_temporal68.cleanups WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)
   =(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',1) FOR UPDATE;
  IF c.run_id IS NULL THEN
   IF operation_value<>'ordered68.cleanup.prepare' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured cleanup absent';END IF;
   evidence:=zasp_temporal68.cleanup_snapshot(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
  ELSE
   PERFORM zasp_temporal68.cleanup_current(c.organization_id,c.workspace_id,c.environment_id,c.run_id,c.step_id);
   evidence:=zasp_authorization80_worker.ordered68_row_json(c);
  END IF;
 ELSE
  -- Bind the actual acknowledged delivery/source/receipt association, including
  -- receipt absence on the first completion. No audit or receipt is fabricated.
  SELECT jsonb_build_array(
   (SELECT COALESCE(jsonb_agg(zasp_authorization80_worker.ordered68_row_json(target_evidence) ORDER BY target_evidence.device_id),'[]'::jsonb) FROM public.zasp_security_agent_temporary_policy_targets target_evidence WHERE(target_evidence.organization_id,target_evidence.workspace_id,target_evidence.environment_id,target_evidence.run_id,target_evidence.step_id,target_evidence.phase)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id','apply')),
   (SELECT COALESCE(jsonb_agg(zasp_authorization80_worker.ordered68_row_json(d) ORDER BY device_id),'[]'::jsonb) FROM zasp_temporal68.deliveries d WHERE(d.organization_id,d.workspace_id,d.environment_id,d.run_id,d.step_id,d.generation,d.phase)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',1,'apply')),
   (SELECT zasp_authorization80_worker.ordered68_row_json(r) FROM public.zasp_sa_multistep_receipts r WHERE(r.organization_id,r.workspace_id,r.environment_id,r.run_id,r.step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id'))) INTO evidence;
 END IF;
 IF evidence IS NULL OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready()
 OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered ordinary session changed after wait';END IF;
 RETURN f||jsonb_build_object('execution_phase',operation_value,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),
 'operation_evidence_digest',encode(digest(convert_to(evidence::text,'UTF8'),'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_policy_begin(operation_value text, q jsonb, key_id_value text)
 RETURNS bytea
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proof jsonb;input_value jsonb;result bytea;BEGIN
 PERFORM zasp_authorization80_worker.ordered68_policy_purpose(operation_value);
 IF NOT COALESCE(key_id_value~'^[a-z][a-z0-9_-]{7,63}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered signing key rejected';END IF;
 -- The shared proof clone validates the exact original q and database session,
 -- takes organization before parent/target locks, and rechecks after its source.
 PERFORM zasp_authorization80_worker.ordered68_signing_boundary(operation_value);
 proof:=zasp_authorization80_worker.ordered68_signing_proof_inner(operation_value,q);
 input_value:=zasp_authorization80_worker.ordered68_policy_input(operation_value,q,key_id_value,floor(extract(epoch FROM clock_timestamp()))::bigint,proof->'facts');
 PERFORM zasp_authorization80_worker.ordered68_policy_proof_time(proof);
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.principal_ready(CASE proof->>'purpose' WHEN 'worker-forward' THEN 'zasp_temporal_executor' WHEN 'captured-compensation' THEN 'zasp_temporal_compensation' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing session changed';END IF;
 result:=convert_to(zasp_sa_multistep_prior.deployment_json(input_value),'UTF8');
 IF octet_length(result) NOT BETWEEN 1 AND 1048576 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered signing input bound';END IF;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_policy_input(operation_value text, q jsonb, key_id_value text, issued_value bigint, verified_facts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE phase_value text;policies_value jsonb;sequence_value bigint;version_value bigint;expires_value bigint;ttl integer;old_envelope jsonb;marker jsonb;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;v zasp_temporal68.deliveries%ROWTYPE;BEGIN
 -- Only begin/store call this owner-only helper, with the source equality
 -- already checked by their local proof parser. No facts cross native calls.
 phase_value:=CASE WHEN zasp_authorization80_worker.ordered68_policy_purpose(operation_value)='worker-forward' THEN 'apply' ELSE 'cleanup' END;
 SELECT * INTO STRICT t FROM public.zasp_security_agent_temporary_policy_targets
 WHERE(organization_id,workspace_id,environment_id,run_id,step_id,device_id,phase)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',q#>>'{payload,device_id}',phase_value) FOR UPDATE;
 IF verified_facts->>'signing_target_digest' IS DISTINCT FROM encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(t)::text,'UTF8'),'sha256'),'hex')
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered native signing target changed';END IF;
 IF operation_value IN('ordered68.delivery.apply.store','ordered68.delivery.cleanup.store') THEN
  SELECT * INTO STRICT v FROM zasp_temporal68.deliveries
  WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation,phase,device_id)=(t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id,1,phase_value,t.device_id) FOR UPDATE;
  IF verified_facts->>'signing_delivery_digest' IS DISTINCT FROM encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(v)::text,'UTF8'),'sha256'),'hex')
  OR v.state NOT IN('prepared','stored','read','acknowledged')
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered native signing delivery changed';END IF;
  sequence_value:=v.sequence;version_value:=v.sequence;policies_value:=v.composition->'policies';
  expires_value:=floor(extract(epoch FROM(v.composition->>'expires_at')::timestamptz))::bigint;
  IF v.state<>'prepared' THEN old_envelope:=v.envelope;END IF;
 ELSE
  sequence_value:=t.sequence;version_value:=t.policy_version;
  IF phase_value='apply' THEN
   SELECT(plan->'steps'->0->>'ttl_seconds')::integer INTO STRICT ttl FROM public.zasp_security_agent_plans
   WHERE(organization_id,workspace_id,environment_id,run_id)=(t.organization_id,t.workspace_id,t.environment_id,t.run_id);
   IF ttl NOT BETWEEN 60 AND 3600 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered native signing ttl changed';END IF;
   policies_value:=zasp_sa_multistep_prior.application_policies();
  ELSE ttl:=300;policies_value:='[]'::jsonb;END IF;
  expires_value:=issued_value+ttl;
  IF operation_value='ordered68.cleanup.renew' THEN
   marker:=zasp_temporal68.cleanup_marker(t);
   IF t.state<>'stored' OR q#>>'{payload,source_digest}' IS DISTINCT FROM 'sha256:'||encode(t.envelope_digest,'hex')
    OR verified_facts->>'signing_marker_digest' IS DISTINCT FROM encode(digest(convert_to(marker::text,'UTF8'),'sha256'),'hex')
   THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured renewal changed';END IF;
   IF(marker->>'expires_at')::timestamptz>clock_timestamp() THEN
    -- A completed renewal replays its exact signed input. The original marker
    -- has only timestamps and is not an existing renewal to replay.
    IF marker->>'key_id' IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered renewal window not reached';END IF;
    old_envelope:=marker;
   ELSIF to_timestamp(issued_value)<(marker->>'expires_at')::timestamptz THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered renewal precedes captured marker';
   END IF;
  ELSIF t.state<>'planned' THEN
   IF t.state NOT IN('stored','verified') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered source state changed';END IF;
   old_envelope:=jsonb_build_object('key_id',t.key_id,'issued_at',t.issued_at,'expires_at',t.expires_at,'policies',t.policies);
  END IF;
 END IF;
 IF old_envelope IS NOT NULL THEN
  IF old_envelope->>'key_id' IS DISTINCT FROM key_id_value OR old_envelope->'policies' IS DISTINCT FROM policies_value
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing replay identity changed';END IF;
  issued_value:=floor(extract(epoch FROM(old_envelope->>'issued_at')::timestamptz))::bigint;
  expires_value:=floor(extract(epoch FROM(old_envelope->>'expires_at')::timestamptz))::bigint;
 END IF;
 IF NOT COALESCE(sequence_value>0 AND version_value>0 AND issued_value<=floor(extract(epoch FROM clock_timestamp()))::bigint+5
 AND expires_value>floor(extract(epoch FROM clock_timestamp()))::bigint AND expires_value-issued_value BETWEEN 1 AND 86400
 AND jsonb_typeof(policies_value)='array' AND jsonb_array_length(policies_value)<=100,false)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered native signing input expired';END IF;
 RETURN jsonb_build_object('contract_version',1,'operation',operation_value,'decision_digest',encode(digest(convert_to(current_setting('zasp.worker_proof'),'UTF8'),'sha256'),'hex'),
 'key_id',key_id_value,'organization_id',t.organization_id,'workspace_id',t.workspace_id,'environment_id',t.environment_id,'device_id',t.device_id,
 'sequence',sequence_value,'policy_version',version_value,'issued_at',issued_value,'expires_at',expires_value,'failure_mode','closed','policies',policies_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_policy_metadata(operation_value text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE compensation boolean;delivery_value boolean;prepare_value boolean;phase_value text;f jsonb;effect_q jsonb;composition_value jsonb;
 checks jsonb:='[]'::jsonb;policy_ids jsonb:='[]'::jsonb;run_ids jsonb:='[]'::jsonb;marker jsonb;fresh_value bigint;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;v zasp_temporal68.deliveries%ROWTYPE;fx zasp_temporal68.effects%ROWTYPE;
 work public.zasp_policy_deployment_work%ROWTYPE;BEGIN
 -- Preparation is an ordinary forward operation, never a signing purpose. Its
 -- composition is captured before a delivery row necessarily exists.
 prepare_value:=operation_value='ordered68.delivery.apply.prepare';
 compensation:=CASE WHEN prepare_value THEN false ELSE zasp_authorization80_worker.ordered68_policy_purpose(operation_value)='captured-compensation' END;
 delivery_value:=prepare_value OR operation_value IN('ordered68.delivery.apply.store','ordered68.delivery.cleanup.store');
 phase_value:=CASE WHEN compensation THEN 'cleanup' ELSE 'apply' END;
 IF NOT COALESCE(octet_length(q::text)<=4096 AND q->'generation'='1'::jsonb
 AND q->>'operation'=CASE WHEN prepare_value THEN 'prepare' WHEN delivery_value THEN 'store' WHEN operation_value='ordered68.cleanup.renew' THEN 'renew' ELSE 'source' END
 AND public.zasp_valid_product_id(q#>>'{payload,device_id}'),false)
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
 OR NOT zasp_sa_multistep_prior.closed(q->'payload',CASE WHEN delivery_value THEN ARRAY['device_id','phase'] WHEN operation_value='ordered68.cleanup.renew' THEN ARRAY['device_id','source_digest'] ELSE ARRAY['device_id'] END)
 OR delivery_value AND q#>>'{payload,phase}' IS DISTINCT FROM phase_value
 OR operation_value='ordered68.cleanup.renew' AND NOT COALESCE(q#>>'{payload,source_digest}'~'^sha256:[a-f0-9]{64}$',false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered signing reference rejected';END IF;
 -- Retain the admitted parent, original native effect and complete destination
 -- digest. Compensation chooses only its captured path; no forward resolver.
 effect_q:=q||jsonb_build_object('operation',CASE WHEN compensation THEN 'read' ELSE 'start' END,'payload','{}'::jsonb);
 f:=zasp_authorization80_worker.ordered68_effect_source(CASE WHEN compensation THEN 'effect.read' ELSE 'effect.start' END,effect_q);
 IF f->>'ordered_action_key' IS DISTINCT FROM 'create_temporary_policy' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing effect rejected';END IF;
 SELECT * INTO STRICT fx FROM zasp_temporal68.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)
 =(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',1) FOR SHARE;
 IF fx.state NOT IN('started','unknown','cleanup_pending','cleaned') OR NOT compensation AND NOT delivery_value AND fx.state NOT IN('started','unknown')
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing intent unavailable';END IF;
 IF compensation THEN PERFORM zasp_temporal68.cleanup_current(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id);
 ELSE PERFORM zasp_sa_multistep_prior.application_current(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id);END IF;
 SELECT * INTO t FROM public.zasp_security_agent_temporary_policy_targets
 WHERE(organization_id,workspace_id,environment_id,run_id,step_id,device_id,phase)=(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id,q#>>'{payload,device_id}',phase_value) FOR UPDATE;
 IF t.device_id IS NULL OR t.action_key IS DISTINCT FROM 'create_temporary_policy'
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fx.snapshot->'targets') x WHERE(x->>'device_id',x->>'credential_id')=(t.device_id,t.credential_id))
 OR NOT compensation AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fx.snapshot->'targets') x WHERE(x->>'device_id',x->'sequence',x->'policy_version')=(t.device_id,to_jsonb(t.sequence),to_jsonb(t.policy_version)))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing captured destination changed';END IF;
 IF compensation THEN marker:=zasp_temporal68.cleanup_marker(t);END IF;
 IF delivery_value THEN
  SELECT * INTO v FROM zasp_temporal68.deliveries
  WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation,device_id,phase)=(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id,1,t.device_id,phase_value) FOR UPDATE;
  SELECT * INTO work FROM public.zasp_policy_deployment_work WHERE(organization_id,workspace_id,environment_id,device_id)=(t.organization_id,t.workspace_id,t.environment_id,t.device_id) FOR SHARE;
  composition_value:=CASE WHEN compensation THEN zasp_temporal68.cleanup_composition(t.organization_id,t.workspace_id,t.environment_id,t.device_id,t.run_id,t.step_id) ELSE zasp_sa_multistep_prior.deployment_composition(t.organization_id,t.workspace_id,t.environment_id,t.device_id) END;
  IF t.state NOT IN('stored','verified') OR t.envelope_digest IS NULL OR t.desired_generation IS NULL
  OR work.device_id IS NULL OR work.state='leased' OR work.lease_token IS NOT NULL OR work.lease_owner IS NOT NULL OR work.lease_expires_at IS NOT NULL
  OR v.run_id IS NULL AND NOT prepare_value OR v.run_id IS NOT NULL AND(v.state NOT IN('prepared','stored','read','acknowledged')
   OR(v.source_sequence,v.source_digest,v.credential_id,v.desired_generation,v.composition) IS DISTINCT FROM(t.sequence,t.envelope_digest,t.credential_id,work.desired_generation,composition_value))
  OR v.run_id IS NULL AND prepare_value AND work.applied_generation>=work.desired_generation
  OR (CASE WHEN compensation THEN work.desired_generation<t.desired_generation ELSE work.desired_generation IS DISTINCT FROM t.desired_generation END)
  OR(compensation AND v.state<>'acknowledged' AND(marker->>'expires_at')::timestamptz<=clock_timestamp())
  OR NOT COALESCE((composition_value->>'expires_at')::timestamptz>clock_timestamp()+interval '1 minute',false)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing composition changed';END IF;
  IF compensation THEN PERFORM zasp_temporal68.delivery_history(t);END IF;
  SELECT COALESCE(jsonb_agg(id ORDER BY id COLLATE "C"),'[]'::jsonb) INTO policy_ids FROM(SELECT value->>'id' id FROM jsonb_array_elements(composition_value->'persistent_sources')) p;
  SELECT COALESCE(jsonb_agg(id ORDER BY id COLLATE "C"),'[]'::jsonb) INTO run_ids FROM(SELECT DISTINCT value->>'run_id' id FROM jsonb_array_elements(composition_value->'temporary_sources')) p;
  IF jsonb_array_length(policy_ids)>100 OR jsonb_array_length(run_ids)>100
   OR NOT compensation AND jsonb_array_length(run_ids)<1
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(policy_ids||run_ids) x WHERE NOT COALESCE(public.zasp_valid_product_id(x),false))
   OR(SELECT count(*)<>count(DISTINCT x) FROM jsonb_array_elements_text(policy_ids) x)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing composition identities changed';END IF;
 ELSE
  IF t.state NOT IN('planned','stored','verified') OR operation_value='ordered68.cleanup.renew' AND(t.state<>'stored'
   OR q#>>'{payload,source_digest}' IS DISTINCT FROM 'sha256:'||encode(t.envelope_digest,'hex'))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing source state changed';END IF;
 END IF;
 IF NOT compensation THEN
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',f->>'definition_id','permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',f->>'run_id','permission','manage_workflows'),jsonb_build_object('kind','gateway_device','id',t.device_id,'permission','manage_workflows'))
   ||COALESCE((SELECT jsonb_agg(jsonb_build_object('kind','policy','id',x,'permission','view') ORDER BY x COLLATE "C") FROM jsonb_array_elements_text(policy_ids) x),'[]'::jsonb)
   ||COALESCE((SELECT jsonb_agg(jsonb_build_object('kind','security_agent_run','id',x,'permission','view') ORDER BY x COLLATE "C") FROM jsonb_array_elements_text(run_ids) x),'[]'::jsonb);
  fresh_value:=(f->>'fresh_until_ms')::bigint;
  IF delivery_value THEN fresh_value:=least(fresh_value,floor(extract(epoch FROM(composition_value->>'expires_at')::timestamptz)*1000)::bigint);END IF;
  f:=jsonb_set(f,'{fresh_until_ms}',to_jsonb(fresh_value));
 END IF;
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready()
 OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing session changed after wait';END IF;
 RETURN f||jsonb_build_object('ordered_device_ids','[]'::jsonb,'ordered_policy_device_id',t.device_id,'ordered_policy_ids',CASE WHEN compensation THEN '[]'::jsonb ELSE policy_ids END,'ordered_source_run_ids',CASE WHEN compensation THEN '[]'::jsonb ELSE run_ids END,
 'checks',checks,'execution_phase',operation_value,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),
 'signing_target_digest',encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(t)::text,'UTF8'),'sha256'),'hex'),
 'signing_delivery_digest',CASE WHEN delivery_value AND v.run_id IS NOT NULL THEN encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(v)::text,'UTF8'),'sha256'),'hex') ELSE NULL END,
 'signing_composition_digest',CASE WHEN delivery_value THEN encode(digest(convert_to(composition_value::text,'UTF8'),'sha256'),'hex') ELSE NULL END,
 'signing_marker_digest',CASE WHEN compensation THEN encode(digest(convert_to(marker::text,'UTF8'),'sha256'),'hex') ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_policy_purpose(operation_value text)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 CASE operation_value
 WHEN 'ordered68.application.source','ordered68.delivery.apply.store' THEN RETURN 'worker-forward';
 WHEN 'ordered68.cleanup.source','ordered68.cleanup.renew','ordered68.delivery.cleanup.store' THEN RETURN 'captured-compensation';
 ELSE RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing operation rejected';
 END CASE;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_policy_source(operation_value text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;BEGIN
 PERFORM zasp_authorization80_worker.ordered68_signing_boundary(operation_value);
 result_value:=zasp_authorization80_worker.ordered68_signing_source_inner(operation_value,q);
 PERFORM zasp_authorization80_worker.ordered68_signing_boundary(operation_value);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_policy_store(operation_value text, q jsonb, key_id_value text, input_bytes bytea, envelope_bytes bytea, mac_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proof jsonb;purpose_value text;k bytea;input_json json;envelope_json json;input_value jsonb;expected jsonb;env jsonb;payload jsonb;native_q jsonb;result jsonb;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;message_bytes bytea;zero_byte bytea:=decode('00','hex');digest_value text;BEGIN
 purpose_value:=zasp_authorization80_worker.ordered68_policy_purpose(operation_value);
 PERFORM zasp_authorization80_worker.ordered68_signing_boundary(operation_value);
 proof:=zasp_authorization80_worker.ordered68_signing_proof_inner(operation_value,q);
 IF NOT COALESCE(octet_length(input_bytes) BETWEEN 1 AND 1048576 AND octet_length(envelope_bytes) BETWEEN 1 AND 1048576
 AND mac_value~'^[a-f0-9]{64}$' AND key_id_value~'^[a-z][a-z0-9_-]{7,63}$',false)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store bound rejected';END IF;
 input_json:=convert_from(input_bytes,'UTF8')::json;envelope_json:=convert_from(envelope_bytes,'UTF8')::json;
 IF NOT zasp_authorization80.unique_json(input_json) OR NOT zasp_authorization80.unique_json(envelope_json)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store duplicate fields';END IF;
 input_value:=input_json::jsonb;env:=envelope_json::jsonb;
 IF NOT zasp_sa_multistep_prior.closed(input_value,ARRAY['contract_version','operation','decision_digest','key_id','organization_id','workspace_id','environment_id','device_id','sequence','policy_version','issued_at','expires_at','failure_mode','policies'])
 OR NOT zasp_sa_multistep_prior.closed(env,ARRAY['contract_version','key_id','algorithm','audience','organization_id','workspace_id','environment_id','device_id','sequence','policy_version','issued_at','expires_at','failure_mode','payload_digest','policies','signature'])
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store shape rejected';END IF;
 -- Recompute with the original issue time, not a newly sampled signing input.
 -- This reader retains actual source/sequence/composition and current/captured
 -- authority under the same transaction's locks. It performs no fresh lookup
 -- of forward credentials for captured compensation.
 expected:=zasp_authorization80_worker.ordered68_policy_input(operation_value,q,key_id_value,(input_value->>'issued_at')::bigint,proof->'facts');
 IF input_bytes IS DISTINCT FROM convert_to(zasp_sa_multistep_prior.deployment_json(expected),'UTF8')
 OR input_value->>'decision_digest' IS DISTINCT FROM encode(digest(convert_to(current_setting('zasp.worker_proof'),'UTF8'),'sha256'),'hex')
 OR env->'contract_version' IS DISTINCT FROM '1'::jsonb OR env->>'algorithm' IS DISTINCT FROM 'Ed25519' OR env->>'audience' IS DISTINCT FROM 'runtime-gateway-policy'
 OR(env->>'key_id',env->>'organization_id',env->>'workspace_id',env->>'environment_id',env->>'device_id',env->'sequence',env->'policy_version',env->>'failure_mode',env->'policies')
 IS DISTINCT FROM(key_id_value,input_value->>'organization_id',input_value->>'workspace_id',input_value->>'environment_id',input_value->>'device_id',input_value->'sequence',input_value->'policy_version',input_value->>'failure_mode',input_value->'policies')
 OR(env->>'issued_at')::timestamptz IS DISTINCT FROM to_timestamp((input_value->>'issued_at')::bigint)
 OR(env->>'expires_at')::timestamptz IS DISTINCT FROM to_timestamp((input_value->>'expires_at')::bigint)
 OR NOT COALESCE(env->>'payload_digest'~'^[a-f0-9]{64}$' AND env->>'signature'~'^[A-Za-z0-9_-]{86}$',false)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signed input changed';END IF;
 SELECT key INTO k FROM zasp_authorization80_worker.verifiers WHERE purpose=purpose_value AND version=proof->>'key_version' FOR SHARE;
 message_bytes:=convert_to('zasp-authorization-ordered68-policy-store-v1','UTF8')||zero_byte||convert_to(purpose_value,'UTF8')||zero_byte
 ||convert_to(encode(digest(convert_to(current_setting('zasp.worker_proof'),'UTF8'),'sha256'),'hex'),'UTF8')||zero_byte
 ||convert_to(encode(digest(input_bytes,'sha256'),'hex'),'UTF8')||zero_byte||convert_to(encode(digest(envelope_bytes,'sha256'),'hex'),'UTF8');
 IF k IS NULL OR mac_value IS DISTINCT FROM encode(hmac(message_bytes,k,'sha256'),'hex')
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store verification rejected';END IF;
 PERFORM zasp_authorization80_worker.ordered68_policy_proof_time(proof);
 digest_value:='sha256:'||encode(digest(envelope_bytes,'sha256'),'hex');
 IF operation_value IN('ordered68.delivery.apply.store','ordered68.delivery.cleanup.store') THEN
  payload:=jsonb_build_object('device_id',input_value->>'device_id','phase',CASE WHEN purpose_value='worker-forward' THEN 'apply' ELSE 'cleanup' END,'envelope',env,'digest',digest_value);
  native_q:=q||jsonb_build_object('operation','store','payload',payload);
  result:=zasp_authorization80_worker.ordered68_delivery_store(native_q);
 ELSE
  SELECT * INTO STRICT t FROM public.zasp_security_agent_temporary_policy_targets
   WHERE(organization_id,workspace_id,environment_id,run_id,step_id,device_id,phase)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',input_value->>'device_id',CASE WHEN purpose_value='worker-forward' THEN 'apply' ELSE 'cleanup' END) FOR UPDATE;
  payload:=jsonb_build_object('device_id',t.device_id,'credential_id',t.credential_id,'sequence',env->'sequence','policy_version',env->'policy_version','key_id',key_id_value,
   'issued_at',env->>'issued_at','expires_at',env->>'expires_at','failure_mode',env->>'failure_mode','payload_digest','sha256:'||(env->>'payload_digest'),'policies',env->'policies',
   'signature',encode(decode(translate(env->>'signature','-_','+/')||'==','base64'),'base64'),'envelope_digest',digest_value);
  IF operation_value='ordered68.application.source' THEN
   result:=zasp_authorization80_worker.ordered68_application_source(q||jsonb_build_object('operation','source','payload',payload));
  ELSIF operation_value='ordered68.cleanup.source' THEN
   result:=zasp_authorization80_worker.ordered68_cleanup_source(q||jsonb_build_object('operation','source','payload',payload));
  ELSE
   result:=zasp_authorization80_worker.ordered68_cleanup_source(q||jsonb_build_object('operation','renew','payload',jsonb_build_object('source_digest',q#>>'{payload,source_digest}','envelope',payload)));
  END IF;
 END IF;
 -- Native writes can legitimately advance their own source/revision. Do not
 -- compare a prewrite revision to those writes; do reject expiry after waits.
 PERFORM zasp_authorization80_worker.ordered68_policy_proof_time(proof);
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.principal_ready(CASE purpose_value WHEN 'worker-forward' THEN 'zasp_temporal_executor' WHEN 'captured-compensation' THEN 'zasp_temporal_compensation' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store session changed';END IF;
 RETURN result;
EXCEPTION WHEN data_exception THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signed store rejected';
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_progress_facts(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;c zasp_temporal65.commands%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;
 tr public.zasp_security_agent_trigger_receipts%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;a zasp_authorization80_worker.ordered_associations%ROWTYPE;source_hash text;
BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered progress executor rejected';END IF;
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') FOR SHARE;
 SELECT * INTO r FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 SELECT * INTO c FROM zasp_temporal65.commands WHERE(organization_id,workspace_id,environment_id,run_id,kind)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,'start') FOR SHARE;
 SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,r.definition_id,r.trigger_id) FOR SHARE;
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(r.organization_id,r.workspace_id,r.environment_id,r.definition_id,r.definition_version) FOR SHARE;
 IF x.run_id IS NULL OR r.run_id IS NULL OR c.run_id IS NULL OR tr.run_id IS NULL OR h.definition_id IS NULL OR x.execution_owner<>'temporal' OR c.execution_owner<>'temporal'
 OR(c.definition_version,c.input_digest) IS DISTINCT FROM(x.definition_version,x.input_digest) OR r.definition_version IS DISTINCT FROM x.definition_version
 OR r.lease_owner IS NOT NULL OR r.lease_token IS NOT NULL OR r.lease_expires_at IS NOT NULL OR tr.trigger_kind NOT IN('finding','attack_path') OR encode(tr.trigger_digest,'hex') IS DISTINCT FROM x.input_digest
 OR r.run_id IS DISTINCT FROM public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_run',r.definition_id||chr(31)||r.trigger_id||chr(31)||tr.trigger_version::text)
 OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') OR h.definition->'allowed_actions' IS DISTINCT FROM '["create_temporary_policy","run_test"]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered progress admission changed';END IF;
 source_hash:=encode(digest(convert_to(jsonb_build_array(x.execution_owner,r.definition_id,x.definition_version,x.input_digest,c.event_id,tr.trigger_kind,tr.trigger_id,tr.trigger_version,encode(h.definition_digest,'hex'))::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO a FROM zasp_authorization80_worker.ordered_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF a.run_id IS NULL OR(a.definition_id,a.definition_version,a.definition_digest,a.source_digest) IS DISTINCT FROM(r.definition_id,r.definition_version,encode(h.definition_digest,'hex'),source_hash)
 OR NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,r.state,r.version,true)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered progress capture changed';END IF;
 -- No test_current/application_ready here: the original progress transition
 -- owns both successor-ready and its conservative blocked branch.
 RETURN to_jsonb(a)||jsonb_build_object('run_state',r.state,'run_version',r.version,'session_user',session_user,'checks',jsonb_build_array(jsonb_build_object('kind','security_agent','id',a.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',a.run_id,'permission','manage_workflows')));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_signing_effect_metadata_inner(phase text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;a zasp_authorization80_worker.ordered_associations%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;plan_value public.zasp_security_agent_plans%ROWTYPE;
 v zasp_temporal68.effects%ROWTYPE;f jsonb;reference_value jsonb;step_value jsonb;effect_value jsonb;destinations jsonb;checks jsonb;captured_targets jsonb;
 compensation boolean:=phase IN('effect.read','effect.unknown');BEGIN
 IF phase IS NULL OR phase NOT IN('effect.reserve','effect.start','effect.read','effect.unknown') OR octet_length(q::text)>4096
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
 OR q->'generation' IS DISTINCT FROM '1'::jsonb OR q->'payload' IS DISTINCT FROM '{}'::jsonb OR q->>'operation' IS DISTINCT FROM split_part(phase,'.',2)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered effect request rejected';END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered effect requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect principal rejected';END IF;
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=q->>'organization_id' FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect organization absent';END IF;
 PERFORM zasp_sa_multistep_prior.application_lock(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered effect owner absent';END IF;
 reference_value:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'definition_version',x.definition_version,'input_digest',x.input_digest);
 f:=zasp_authorization80_worker.ordered68_signing_facts_inner(compensation,reference_value);
 a:=jsonb_populate_record(NULL::zasp_authorization80_worker.ordered_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_associations s WHERE s=a) OR NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true) AND(compensation OR s.target_current AND s.fresh_until>clock_timestamp())) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect admission changed';END IF;
 SELECT * INTO st FROM public.zasp_security_agent_steps WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,q->>'step_id') FOR SHARE;
 SELECT * INTO plan_value FROM public.zasp_security_agent_plans WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF st.step_id IS NULL OR plan_value.run_id IS NULL OR st.step_index NOT IN(0,1) OR st.action_key IS DISTINCT FROM (CASE st.step_index WHEN 0 THEN 'create_temporary_policy' ELSE 'run_test' END)
 OR plan_value.plan->'steps'->st.step_index->>'step_id' IS DISTINCT FROM st.step_id THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect step changed';END IF;
 PERFORM zasp_temporal68.current_plan(x.organization_id,x.workspace_id,x.environment_id,x.run_id,NOT compensation);
 SELECT * INTO v FROM zasp_temporal68.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,1) FOR SHARE;
 IF v.run_id IS NULL AND phase<>'effect.reserve' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered captured effect absent';END IF;
 IF v.run_id IS NOT NULL THEN
  IF v.effect_key IS DISTINCT FROM zasp_temporal68.effect_identity(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,1) OR(v.input_digest,v.plan_hash,v.action_key) IS DISTINCT FROM(st.input_digest,plan_value.plan_hash,st.action_key)
  OR v.snapshot_digest IS DISTINCT FROM digest(convert_to(v.snapshot::text,'UTF8'),'sha256') OR v.snapshot->>'input_digest' IS DISTINCT FROM encode(st.input_digest,'hex') OR v.snapshot->>'plan_hash' IS DISTINCT FROM encode(plan_value.plan_hash,'hex')
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.step_id,s.action_key,s.input_digest)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,st.action_key,st.input_digest))
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_effects s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.step_id,s.action_key,s.input_digest)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,st.step_id,st.action_key,st.input_digest) AND s.lease_owner IS NULL AND s.lease_token IS NULL AND s.lease_expires_at IS NULL)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured effect changed';END IF;
  effect_value:=jsonb_build_object('effect_key',v.effect_key,'generation',v.generation,'state',v.state,'snapshot_digest',encode(v.snapshot_digest,'hex'));
 END IF;
 checks:='[]'::jsonb;
 IF NOT compensation THEN
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',a.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',a.run_id,'permission','manage_workflows'));
  IF st.step_index=0 THEN
   destinations:=zasp_authorization80_worker.ordered68_destinations(x.organization_id,x.workspace_id,x.environment_id);
   IF v.run_id IS NOT NULL THEN
    SELECT jsonb_agg(jsonb_build_object('device_id',t->>'device_id','credential_id',t->>'credential_id') ORDER BY t->>'device_id') INTO captured_targets FROM jsonb_array_elements(v.snapshot->'targets') t;
    IF destinations->>'targets_digest' IS DISTINCT FROM encode(digest(convert_to(captured_targets::text,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered captured destinations changed';END IF;
   END IF;
   checks:=checks||(SELECT jsonb_agg(jsonb_build_object('kind','gateway_device','id',id_value,'permission','manage_workflows') ORDER BY id_value) FROM jsonb_array_elements_text(destinations->'ids') id_value);
   f:=jsonb_set(f,'{fresh_until_ms}',to_jsonb(least((f->>'fresh_until_ms')::bigint,(destinations->>'fresh_until_ms')::bigint)));
  ELSE
   checks:=checks||jsonb_build_array(jsonb_build_object('kind','test','id',a.test_id,'permission','run_tests'),jsonb_build_object('kind',a.target_kind,'id',a.target_id,'permission','run_tests'));
  END IF;
 END IF;
 step_value:=jsonb_build_object('step_id',st.step_id,'action_key',st.action_key,'state',st.state,'version',st.version,'input_digest',encode(st.input_digest,'hex'),'plan_hash',encode(plan_value.plan_hash,'hex'));
 RETURN f||jsonb_build_object('ordered_action_key',st.action_key,'ordered_device_ids',CASE WHEN compensation OR st.step_index=1 THEN '[]'::jsonb ELSE destinations->'ids' END,'checks',checks,'execution_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'step',step_value,'effect',effect_value,'destination_digest',destinations->'identity_digest','ordered_targets_digest',destinations->'targets_digest');
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_signing_effect_source_inner(phase text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE f jsonb;c zasp_authorization80_worker.ordered_effect_scope%ROWTYPE;compensation boolean:=phase IN('effect.read','effect.unknown');BEGIN
 f:=zasp_authorization80_worker.ordered68_signing_effect_metadata_inner(phase,q);
 SELECT * INTO c FROM zasp_authorization80_worker.ordered_effect_scope WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 IF c.run_id IS NULL OR c.action_key IS DISTINCT FROM f->>'ordered_action_key'
 OR NOT compensation AND(NOT c.target_current OR c.fresh_until<=clock_timestamp() OR(c.device_ids,c.destination_digest,c.targets_digest) IS DISTINCT FROM(f->'ordered_device_ids',f->>'destination_digest',f->>'ordered_targets_digest')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered effect projection capture changed';END IF;
 RETURN f;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_signing_facts_inner(compensation boolean, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;c zasp_temporal65.commands%ROWTYPE;
 tr public.zasp_security_agent_trigger_receipts%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;a zasp_authorization80_worker.ordered_associations%ROWTYPE;
 cv jsonb;resolution jsonb;metadata jsonb;checks jsonb;source_hash text;target_hash text;product text;expires timestamptz;k text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered source requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF compensation IS NULL OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered source principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest']) OR octet_length(q::text)>4096
  OR jsonb_typeof(q->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(q->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
  OR jsonb_typeof(q->'input_digest') IS DISTINCT FROM 'string' OR NOT COALESCE(q->>'input_digest'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered start rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered source scope rejected';END IF;
 END LOOP;
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') FOR SHARE;
 IF x.run_id IS NULL OR x.execution_owner<>'temporal' OR to_jsonb(x.definition_version) IS DISTINCT FROM q->'definition_version' OR x.input_digest IS DISTINCT FROM q->>'input_digest' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered owner changed';END IF;
 SELECT * INTO r FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF r.run_id IS NULL OR r.definition_version<>x.definition_version OR r.lease_owner IS NOT NULL OR r.lease_token IS NOT NULL OR r.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered parent changed';END IF;
 SELECT * INTO c FROM zasp_temporal65.commands WHERE(organization_id,workspace_id,environment_id,run_id,kind)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,'start') FOR SHARE;
 SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,r.definition_id,r.trigger_id) FOR SHARE;
 IF c.run_id IS NULL OR c.execution_owner<>'temporal' OR(c.definition_version,c.input_digest) IS DISTINCT FROM(x.definition_version,x.input_digest)
  OR tr.run_id IS NULL OR encode(tr.trigger_digest,'hex') IS DISTINCT FROM x.input_digest OR tr.trigger_kind NOT IN('finding','attack_path')
  OR r.run_id IS DISTINCT FROM public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_run',r.definition_id||chr(31)||r.trigger_id||chr(31)||tr.trigger_version::text) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered retained start changed';END IF;
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(r.organization_id,r.workspace_id,r.environment_id,r.definition_id,r.definition_version) FOR SHARE;
 IF h.definition_id IS NULL OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256') OR h.definition->'allowed_actions' IS DISTINCT FROM '["create_temporary_policy","run_test"]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered historical definition changed';END IF;
 source_hash:=encode(digest(convert_to(jsonb_build_array(x.execution_owner,r.definition_id,x.definition_version,x.input_digest,c.event_id,tr.trigger_kind,tr.trigger_id,tr.trigger_version,encode(h.definition_digest,'hex'))::text,'UTF8'),'sha256'),'hex');
 SELECT * INTO a FROM zasp_authorization80_worker.ordered_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF compensation THEN
  IF a.run_id IS NULL OR(a.definition_id,a.definition_version,a.definition_digest,a.source_digest) IS DISTINCT FROM(r.definition_id,r.definition_version,encode(h.definition_digest,'hex'),source_hash)
   OR NOT EXISTS(SELECT 1 FROM zasp_temporal68.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered captured planning absent';END IF;
  metadata:=to_jsonb(a);checks:='[]'::jsonb;
 ELSE
  IF r.state NOT IN('running','verifying') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered task inactive';END IF;
  cv:=zasp_sa_multistep_prior.context(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
  IF cv->'definition' IS DISTINCT FROM h.definition THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered definition binding changed';END IF;
  resolution:=zasp_temporal68.test_target(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id',cv->'test'->>'target_kind',cv->'test'->>'definition_id',(cv->'test'->>'version')::bigint);
  SELECT i.product_kind,least(i.fresh_until,b.valid_until) INTO STRICT product,expires FROM public.zasp_inventory_entities i JOIN public.zasp_attack_lab_credential_bindings b ON(b.organization_id,b.workspace_id,b.environment_id,b.binding_id)=(i.organization_id,i.workspace_id,i.environment_id,resolution#>>'{comparison,credential_binding_id}') WHERE(i.organization_id,i.workspace_id,i.environment_id,i.id)=(x.organization_id,x.workspace_id,x.environment_id,cv->'test'->>'target_id') FOR SHARE OF i,b;
  IF product IS NULL OR product NOT IN('agent','tool') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target kind rejected';END IF;
  IF expires IS NULL OR expires<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered target expired';END IF;
  target_hash:=encode(digest(convert_to(resolution::text,'UTF8'),'sha256'),'hex');
  metadata:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,
   'principal_id',public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_definition_service',r.definition_id),'grantor_id',r.requested_by,
   'definition_id',r.definition_id,'definition_version',r.definition_version,'definition_digest',encode(h.definition_digest,'hex'),'source_digest',source_hash,
   'test_id',cv->'test'->>'definition_id','test_version',cv->'test'->'version','target_id',cv->'test'->>'target_id','target_kind',product,'target_digest',target_hash,
   'trigger_kind',tr.trigger_kind,'trigger_id',tr.trigger_id,'credential_binding_id',resolution#>>'{comparison,credential_binding_id}',
   'snapshot_id',resolution#>>'{provenance,snapshot_id}','evidence_id',resolution#>>'{provenance,evidence_id}','integration_id',resolution#>>'{provenance,integration_id}','source',resolution#>>'{provenance,source}');
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',r.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',r.run_id,'permission','manage_workflows'),jsonb_build_object('kind','test','id',cv->'test'->>'definition_id','permission','view'),jsonb_build_object('kind',product,'id',cv->'test'->>'target_id','permission','view'),jsonb_build_object('kind',tr.trigger_kind,'id',tr.trigger_id,'permission','view'));
 END IF;
 RETURN metadata||jsonb_build_object('run_state',r.state,'run_version',r.version,'checks',checks,'session_user',session_user,'fresh_until_ms',CASE WHEN compensation THEN NULL ELSE floor(extract(epoch FROM expires)*1000)::bigint END);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_signing_metadata_inner(operation_value text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE compensation boolean;delivery_value boolean;prepare_value boolean;phase_value text;f jsonb;effect_q jsonb;composition_value jsonb;
 checks jsonb:='[]'::jsonb;policy_ids jsonb:='[]'::jsonb;run_ids jsonb:='[]'::jsonb;marker jsonb;fresh_value bigint;
 t public.zasp_security_agent_temporary_policy_targets%ROWTYPE;v zasp_temporal68.deliveries%ROWTYPE;fx zasp_temporal68.effects%ROWTYPE;
 work public.zasp_policy_deployment_work%ROWTYPE;BEGIN
 -- Preparation is an ordinary forward operation, never a signing purpose. Its
 -- composition is captured before a delivery row necessarily exists.
 prepare_value:=operation_value='ordered68.delivery.apply.prepare';
 compensation:=CASE WHEN prepare_value THEN false ELSE zasp_authorization80_worker.ordered68_policy_purpose(operation_value)='captured-compensation' END;
 delivery_value:=prepare_value OR operation_value IN('ordered68.delivery.apply.store','ordered68.delivery.cleanup.store');
 phase_value:=CASE WHEN compensation THEN 'cleanup' ELSE 'apply' END;
 IF NOT COALESCE(octet_length(q::text)<=4096 AND q->'generation'='1'::jsonb
 AND q->>'operation'=CASE WHEN prepare_value THEN 'prepare' WHEN delivery_value THEN 'store' WHEN operation_value='ordered68.cleanup.renew' THEN 'renew' ELSE 'source' END
 AND public.zasp_valid_product_id(q#>>'{payload,device_id}'),false)
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
 OR NOT zasp_sa_multistep_prior.closed(q->'payload',CASE WHEN delivery_value THEN ARRAY['device_id','phase'] WHEN operation_value='ordered68.cleanup.renew' THEN ARRAY['device_id','source_digest'] ELSE ARRAY['device_id'] END)
 OR delivery_value AND q#>>'{payload,phase}' IS DISTINCT FROM phase_value
 OR operation_value='ordered68.cleanup.renew' AND NOT COALESCE(q#>>'{payload,source_digest}'~'^sha256:[a-f0-9]{64}$',false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered signing reference rejected';END IF;
 -- Retain the admitted parent, original native effect and complete destination
 -- digest. Compensation chooses only its captured path; no forward resolver.
 effect_q:=q||jsonb_build_object('operation',CASE WHEN compensation THEN 'read' ELSE 'start' END,'payload','{}'::jsonb);
 f:=zasp_authorization80_worker.ordered68_signing_effect_source_inner(CASE WHEN compensation THEN 'effect.read' ELSE 'effect.start' END,effect_q);
 IF f->>'ordered_action_key' IS DISTINCT FROM 'create_temporary_policy' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing effect rejected';END IF;
 SELECT * INTO STRICT fx FROM zasp_temporal68.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)
 =(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id',1) FOR SHARE;
 IF fx.state NOT IN('started','unknown','cleanup_pending','cleaned') OR NOT compensation AND NOT delivery_value AND fx.state NOT IN('started','unknown')
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing intent unavailable';END IF;
 IF compensation THEN PERFORM zasp_temporal68.cleanup_current(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id);
 ELSE PERFORM zasp_sa_multistep_prior.application_current(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id);END IF;
 SELECT * INTO t FROM public.zasp_security_agent_temporary_policy_targets
 WHERE(organization_id,workspace_id,environment_id,run_id,step_id,device_id,phase)=(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id,q#>>'{payload,device_id}',phase_value) FOR UPDATE;
 IF t.device_id IS NULL OR t.action_key IS DISTINCT FROM 'create_temporary_policy'
 OR NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fx.snapshot->'targets') x WHERE(x->>'device_id',x->>'credential_id')=(t.device_id,t.credential_id))
 OR NOT compensation AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(fx.snapshot->'targets') x WHERE(x->>'device_id',x->'sequence',x->'policy_version')=(t.device_id,to_jsonb(t.sequence),to_jsonb(t.policy_version)))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing captured destination changed';END IF;
 IF compensation THEN marker:=zasp_temporal68.cleanup_marker(t);END IF;
 IF delivery_value THEN
  SELECT * INTO v FROM zasp_temporal68.deliveries
  WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation,device_id,phase)=(fx.organization_id,fx.workspace_id,fx.environment_id,fx.run_id,fx.step_id,1,t.device_id,phase_value) FOR UPDATE;
  SELECT * INTO work FROM public.zasp_policy_deployment_work WHERE(organization_id,workspace_id,environment_id,device_id)=(t.organization_id,t.workspace_id,t.environment_id,t.device_id) FOR SHARE;
  composition_value:=CASE WHEN compensation THEN zasp_temporal68.cleanup_composition(t.organization_id,t.workspace_id,t.environment_id,t.device_id,t.run_id,t.step_id) ELSE zasp_sa_multistep_prior.deployment_composition(t.organization_id,t.workspace_id,t.environment_id,t.device_id) END;
  IF t.state NOT IN('stored','verified') OR t.envelope_digest IS NULL OR t.desired_generation IS NULL
  OR work.device_id IS NULL OR work.state='leased' OR work.lease_token IS NOT NULL OR work.lease_owner IS NOT NULL OR work.lease_expires_at IS NOT NULL
  OR v.run_id IS NULL AND NOT prepare_value OR v.run_id IS NOT NULL AND(v.state NOT IN('prepared','stored','read','acknowledged')
   OR(v.source_sequence,v.source_digest,v.credential_id,v.desired_generation,v.composition) IS DISTINCT FROM(t.sequence,t.envelope_digest,t.credential_id,work.desired_generation,composition_value))
  OR v.run_id IS NULL AND prepare_value AND work.applied_generation>=work.desired_generation
  OR (CASE WHEN compensation THEN work.desired_generation<t.desired_generation ELSE work.desired_generation IS DISTINCT FROM t.desired_generation END)
  OR(compensation AND v.state<>'acknowledged' AND(marker->>'expires_at')::timestamptz<=clock_timestamp())
  OR NOT COALESCE((composition_value->>'expires_at')::timestamptz>clock_timestamp()+interval '1 minute',false)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing composition changed';END IF;
  IF compensation THEN PERFORM zasp_temporal68.delivery_history(t);END IF;
  SELECT COALESCE(jsonb_agg(id ORDER BY id COLLATE "C"),'[]'::jsonb) INTO policy_ids FROM(SELECT value->>'id' id FROM jsonb_array_elements(composition_value->'persistent_sources')) p;
  SELECT COALESCE(jsonb_agg(id ORDER BY id COLLATE "C"),'[]'::jsonb) INTO run_ids FROM(SELECT DISTINCT value->>'run_id' id FROM jsonb_array_elements(composition_value->'temporary_sources')) p;
  IF jsonb_array_length(policy_ids)>100 OR jsonb_array_length(run_ids)>100
   OR NOT compensation AND jsonb_array_length(run_ids)<1
   OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(policy_ids||run_ids) x WHERE NOT COALESCE(public.zasp_valid_product_id(x),false))
   OR(SELECT count(*)<>count(DISTINCT x) FROM jsonb_array_elements_text(policy_ids) x)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing composition identities changed';END IF;
 ELSE
  IF t.state NOT IN('planned','stored','verified') OR operation_value='ordered68.cleanup.renew' AND(t.state<>'stored'
   OR q#>>'{payload,source_digest}' IS DISTINCT FROM 'sha256:'||encode(t.envelope_digest,'hex'))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered signing source state changed';END IF;
 END IF;
 IF NOT compensation THEN
  checks:=jsonb_build_array(jsonb_build_object('kind','security_agent','id',f->>'definition_id','permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',f->>'run_id','permission','manage_workflows'),jsonb_build_object('kind','gateway_device','id',t.device_id,'permission','manage_workflows'))
   ||COALESCE((SELECT jsonb_agg(jsonb_build_object('kind','policy','id',x,'permission','view') ORDER BY x COLLATE "C") FROM jsonb_array_elements_text(policy_ids) x),'[]'::jsonb)
   ||COALESCE((SELECT jsonb_agg(jsonb_build_object('kind','security_agent_run','id',x,'permission','view') ORDER BY x COLLATE "C") FROM jsonb_array_elements_text(run_ids) x),'[]'::jsonb);
  fresh_value:=(f->>'fresh_until_ms')::bigint;
  IF delivery_value THEN fresh_value:=least(fresh_value,floor(extract(epoch FROM(composition_value->>'expires_at')::timestamptz)*1000)::bigint);END IF;
  f:=jsonb_set(f,'{fresh_until_ms}',to_jsonb(fresh_value));
 END IF;
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_authorization80_worker.catalog_ready()
 OR NOT zasp_temporal68.principal_ready(CASE WHEN compensation THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered signing session changed after wait';END IF;
 RETURN f||jsonb_build_object('ordered_device_ids','[]'::jsonb,'ordered_policy_device_id',t.device_id,'ordered_policy_ids',CASE WHEN compensation THEN '[]'::jsonb ELSE policy_ids END,'ordered_source_run_ids',CASE WHEN compensation THEN '[]'::jsonb ELSE run_ids END,
 'checks',checks,'execution_phase',operation_value,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),
 'signing_target_digest',encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(t)::text,'UTF8'),'sha256'),'hex'),
 'signing_delivery_digest',CASE WHEN delivery_value AND v.run_id IS NOT NULL THEN encode(digest(convert_to(zasp_authorization80_worker.ordered68_row_json(v)::text,'UTF8'),'sha256'),'hex') ELSE NULL END,
 'signing_composition_digest',CASE WHEN delivery_value THEN encode(digest(convert_to(composition_value::text,'UTF8'),'sha256'),'hex') ELSE NULL END,
 'signing_marker_digest',CASE WHEN compensation THEN encode(digest(convert_to(marker::text,'UTF8'),'sha256'),'hex') ELSE NULL END);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_signing_proof_inner(phase text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE envelope json;body_bytes bytea;proof jsonb;source_value jsonb;k bytea;purpose_value text;now_ms bigint:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint;revision_value zasp_authorization79.organizations%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='worker planning requires read committed';END IF;
 IF phase IS NULL OR phase NOT IN('ordered68.application.source','ordered68.delivery.apply.store','ordered68.cleanup.source','ordered68.cleanup.renew','ordered68.delivery.cleanup.store') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker planning phase rejected';END IF;
 purpose_value:=CASE WHEN phase IN('ordered68.cleanup.source','ordered68.cleanup.renew','ordered68.delivery.cleanup.store') THEN 'captured-compensation' ELSE 'worker-forward' END;
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.principal_ready(CASE purpose_value WHEN 'worker-forward' THEN 'zasp_temporal_executor' ELSE 'zasp_temporal_compensation' END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker planning role rejected';END IF;
 envelope:=NULLIF(current_setting('zasp.worker_proof',true),'')::json;
 IF envelope IS NULL OR octet_length(envelope::text)>65536 OR json_typeof(envelope)<>'object' OR NOT zasp_authorization80.unique_json(envelope) OR(SELECT count(*) FROM json_each(envelope))<>3 OR EXISTS(SELECT 1 FROM json_each(envelope) WHERE key NOT IN('body','version','mac') OR json_typeof(value)<>'string') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker proof rejected';END IF;
 SELECT key INTO k FROM zasp_authorization80_worker.verifiers WHERE purpose=purpose_value AND version=envelope->>'version' FOR SHARE;
 body_bytes:=decode(envelope->>'body','base64');
 IF k IS NULL OR octet_length(body_bytes) NOT BETWEEN 1 AND 32768 OR envelope->>'mac' IS DISTINCT FROM encode(hmac(convert_to('zasp-authorization-'||purpose_value||'-v1','UTF8')||decode('00','hex')||body_bytes,k,'sha256'),'hex') OR NOT zasp_authorization80.unique_json(convert_from(body_bytes,'UTF8')::json) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker proof rejected';END IF;
 proof:=convert_from(body_bytes,'UTF8')::jsonb;
 IF NOT COALESCE(proof->>'purpose'=purpose_value AND proof->>'key_version'=envelope->>'version' AND proof->>'operation'=phase AND proof->'request'='null'::jsonb AND proof->>'session_user'=session_user AND(proof->>'issued_at')::bigint<=now_ms+5000 AND(proof->>'expires_at')::bigint>now_ms AND(proof->>'expires_at')::bigint-(proof->>'issued_at')::bigint BETWEEN 1 AND 60000,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker planning proof binding rejected';END IF;
 SELECT * INTO revision_value FROM zasp_authorization79.organizations WHERE organization_id=q->>'organization_id' FOR UPDATE;
 IF revision_value.organization_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured organization missing';END IF;
 IF purpose_value='worker-forward' THEN
  IF revision_value.desired<>revision_value.applied OR proof->'revision' IS DISTINCT FROM jsonb_build_object('organization_id',revision_value.organization_id,'desired',revision_value.desired,'applied',revision_value.applied,'generation',revision_value.generation,'store_id',revision_value.store_id,'model_id',revision_value.model_id) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker authorization revision changed';END IF;
 END IF;
 source_value:=zasp_authorization80_worker.ordered68_signing_source_inner(phase,q);
 now_ms:=floor(extract(epoch FROM clock_timestamp())*1000)::bigint;
 IF NOT COALESCE((proof->>'issued_at')::bigint<=now_ms+5000 AND(proof->>'expires_at')::bigint>now_ms AND(proof->>'expires_at')::bigint-(proof->>'issued_at')::bigint BETWEEN 1 AND 60000,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker proof expired after source locks';END IF;
 IF proof->'facts' IS DISTINCT FROM source_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker planning source changed';END IF;
 RETURN proof;
EXCEPTION WHEN data_exception THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker proof rejected';
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_signing_read_inner(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;op text;k text;g bigint;permit boolean:=false;live_value boolean;targets jsonb;snapshot_value jsonb;
 f zasp_temporal68.effects%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;device record;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor effect requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor catalog unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload'])
  OR octet_length(q::text)>4096 OR q->'generation' IS DISTINCT FROM '1'::jsonb OR q->'payload' IS DISTINCT FROM '{}'::jsonb
  OR NOT COALESCE(q->>'operation' IN('read'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor effect request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id','step_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor effect scope rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';g:=1;op:=q->>'operation';live_value:=op IN('reserve','start');
 IF NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT live_value AND zasp_temporal68.principal_ready('zasp_temporal_compensation'))
  OR NOT zasp_temporal66.is_temporal(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor effect authority rejected';END IF;
 -- Use the existing Organization/budget/run/step/device order, with NOWAIT
 -- on independently owned deployment resources. No external IO is in here.
 PERFORM zasp_sa_multistep_prior.application_lock(o,w,e,r);
 PERFORM zasp_temporal68.current_plan(o,w,e,r,live_value);
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO st FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF NOT FOUND OR st.step_index NOT IN(0,1) OR st.action_key IS DISTINCT FROM (CASE st.step_index WHEN 0 THEN 'create_temporary_policy' ELSE 'run_test' END)
  OR rr.lease_token IS NOT NULL OR rr.lease_owner IS NOT NULL OR rr.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect step absent';END IF;
 IF live_value THEN
  IF st.step_index=0 THEN PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);
  ELSE PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);END IF;
 END IF;
 SELECT * INTO f FROM zasp_temporal68.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,g) FOR UPDATE;
 IF NOT FOUND THEN
  IF op<>'reserve' OR st.state<>'authorized' OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s))
   OR (SELECT count(*) FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))<>st.step_index
   OR st.step_index>=b.max_steps THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect reservation unavailable';END IF;
  INSERT INTO public.zasp_security_agent_step_reservations(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest) VALUES(o,w,e,r,s,st.action_key,st.input_digest);
  INSERT INTO public.zasp_security_agent_effects(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state,attempt) VALUES(o,w,e,r,s,st.action_key,st.input_digest,'pending',1);
  IF st.step_index=0 THEN
   SELECT COALESCE(jsonb_agg(jsonb_build_object('device_id',d.id,'credential_id',c.id) ORDER BY d.id),'[]'::jsonb) INTO targets FROM public.zasp_gateway_devices d JOIN LATERAL(SELECT id FROM public.zasp_gateway_credentials WHERE (organization_id,workspace_id,environment_id,device_id)=(o,w,e,d.id) AND revoked_at IS NULL AND expires_at>clock_timestamp() ORDER BY issued_at DESC,id DESC LIMIT 1)c ON true WHERE (d.organization_id,d.workspace_id,d.environment_id,d.state)=(o,w,e,'active');
   IF jsonb_array_length(targets) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor gateway target bound rejected';END IF;
   FOR device IN SELECT * FROM jsonb_to_recordset(targets) AS t(device_id text,credential_id text) LOOP
    INSERT INTO public.zasp_security_agent_temporary_policy_targets(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id,credential_id,sequence,policy_version) VALUES(o,w,e,r,s,'apply',device.device_id,device.credential_id,1,1);
   END LOOP;
   SELECT jsonb_agg(jsonb_build_object('device_id',device_id,'credential_id',credential_id,'sequence',sequence,'policy_version',policy_version) ORDER BY device_id) INTO targets FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply');
  ELSE
   targets:=zasp_temporal68.test_reserve(o,w,e,r,s);
  END IF;
  snapshot_value:=jsonb_build_object('plan_hash',encode(rr.plan_hash,'hex'),'input_digest',encode(st.input_digest,'hex'),'targets',targets);
  INSERT INTO zasp_temporal68.effects VALUES(o,w,e,r,s,g,zasp_temporal68.effect_identity(o,w,e,r,s,g),st.action_key,st.input_digest,rr.plan_hash,snapshot_value,digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'reserved',NULL,NULL) RETURNING * INTO f;
  UPDATE public.zasp_security_agent_steps SET state='executing',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 END IF;
 IF f.effect_key IS DISTINCT FROM zasp_temporal68.effect_identity(o,w,e,r,s,g) OR (f.input_digest,f.plan_hash,f.action_key) IS DISTINCT FROM(st.input_digest,rr.plan_hash,st.action_key)
  OR f.snapshot_digest IS DISTINCT FROM digest(convert_to(f.snapshot::text,'UTF8'),'sha256') OR f.snapshot->>'plan_hash' IS DISTINCT FROM encode(rr.plan_hash,'hex') OR f.snapshot->>'input_digest' IS DISTINCT FROM encode(st.input_digest,'hex')
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_effects x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.action_key,x.input_digest)=(o,w,e,r,s,f.action_key,f.input_digest) AND x.lease_token IS NULL AND x.lease_owner IS NULL AND x.lease_expires_at IS NULL)
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.action_key,x.input_digest)=(o,w,e,r,s,f.action_key,f.input_digest)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect intent changed';END IF;
 IF op='start' AND f.state='reserved' THEN
  UPDATE zasp_temporal68.effects SET state='started',started_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,g) RETURNING * INTO f;
  UPDATE public.zasp_security_agent_effects SET state='unknown_outcome',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  permit:=true;
 ELSIF op='unknown' THEN
  IF f.state NOT IN('started','unknown') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor effect not sent';END IF;
  UPDATE zasp_temporal68.effects SET state='unknown' WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,g) RETURNING * INTO f;
 END IF;
 IF live_value THEN
  IF st.step_index=0 THEN PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);ELSE PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);END IF;
 END IF;
 IF NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor effect catalog changed';END IF;
 RETURN to_jsonb(f)||jsonb_build_object('send_permit',permit);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_source(compensation boolean, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE f jsonb;a zasp_authorization80_worker.ordered_associations%ROWTYPE;BEGIN
 f:=zasp_authorization80_worker.ordered68_facts(compensation,q);a:=jsonb_populate_record(NULL::zasp_authorization80_worker.ordered_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_associations s WHERE s=a) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered association missing';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true) AND(compensation OR s.target_current AND s.fresh_until>clock_timestamp())) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered state capture changed';END IF;
 RETURN f;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_test_complete(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proof jsonb;v jsonb;l public.zasp_security_agent_test_links%ROWTYPE;j zasp_temporal68.invocations%ROWTYPE;BEGIN
 proof:=zasp_authorization80_worker.require_ordered68_test('adapter.complete',q);
 PERFORM zasp_authorization80_worker.ordered68_completion_native(q);
 SELECT * INTO STRICT l FROM public.zasp_security_agent_test_links WHERE(organization_id,workspace_id,environment_id,test_run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id');
 SELECT * INTO STRICT j FROM zasp_temporal68.invocations WHERE(organization_id,workspace_id,environment_id,test_run_id,category)=(l.organization_id,l.workspace_id,l.environment_id,l.test_run_id,q#>>'{payload,category}');
 v:=jsonb_build_object('organization_id',l.organization_id,'workspace_id',l.workspace_id,'environment_id',l.environment_id,'parent_run_id',l.run_id,'test_run_id',l.test_run_id,'step_id',l.step_id,'effect_key',j.effect_key,'category',j.category,'attempt',j.attempt,'state',j.state,'request_digest',encode(j.request_digest,'hex'),'response_digest',encode(j.response_digest,'hex'),'http_status',j.http_status,'protected',j.protected,'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 PERFORM zasp_authorization80_worker.ordered68_test_exit('adapter.complete',proof);RETURN v;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_test_replay(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proof jsonb;t zasp_temporal68.test_settlements%ROWTYPE;BEGIN
 proof:=zasp_authorization80_worker.require_ordered68_test('test.replay',q);
 IF NOT zasp_sa_multistep_prior.closed(q->'payload',ARRAY['output_manifest','output_body']) OR jsonb_typeof(q#>'{payload,output_body}') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered settlement replay shape rejected';END IF;
 PERFORM zasp_authorization80_worker.ordered68_effect_read(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 SELECT * INTO t FROM zasp_temporal68.test_settlements WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 IF t.run_id IS NULL OR(t.output_manifest,t.output_body) IS DISTINCT FROM(q#>'{payload,output_manifest}',decode(q#>>'{payload,output_body}','base64')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered settlement replay changed';END IF;
 PERFORM zasp_temporal68.test_evidence(t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id);
 PERFORM zasp_authorization80_worker.ordered68_test_exit('test.replay',proof);RETURN t.response;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_test_settle_native(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;p jsonb;intent jsonb;body bytea;summary jsonb;snapshot_value jsonb;snapshot_hash bytea;result_hash bytea;receipt jsonb;result_value jsonb;outcome text;parent_state text;invocation_id text;audit_id text;key_value text;
 i zasp_temporal68.test_inputs%ROWTYPE;t zasp_temporal68.test_settlements%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;
BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor settlement principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR octet_length(q::text)>1500000 OR q->>'operation' IS DISTINCT FROM 'complete'
  OR NOT zasp_sa_multistep_prior.closed(q->'payload',ARRAY['output_manifest','output_body']) OR jsonb_typeof(q->'payload'->'output_body') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor settlement request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';p:=q->'payload';body:=decode(p->>'output_body','base64');
 intent:=zasp_authorization80_worker.ordered68_effect_read(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 IF intent->>'action_key' IS DISTINCT FROM 'run_test' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor settlement action rejected';END IF;
 SELECT * INTO t FROM zasp_temporal68.test_settlements WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF FOUND THEN
  IF (t.output_manifest,t.output_body) IS DISTINCT FROM(p->'output_manifest',body) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor settlement replay changed';END IF;
  PERFORM zasp_temporal68.test_evidence(o,w,e,r,s);RETURN t.response;
 END IF;
 PERFORM zasp_sa_multistep_prior.test_lock(o,w,e,r);PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);
 SELECT * INTO STRICT i FROM zasp_temporal68.test_inputs WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO STRICT child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,i.test_run_id) FOR UPDATE NOWAIT;
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF intent->>'state' NOT IN('started','unknown') OR child.state<>'queued' OR child.cancel_requested OR child.attempt<>0 OR child.worker_id IS NOT NULL OR child.lease_token IS NOT NULL OR child.lease_expires_at IS NOT NULL
  OR intent->'snapshot'->'targets'->>'test_run_id' IS DISTINCT FROM child.run_id
  OR intent->'snapshot'->'targets'->'resolution' IS DISTINCT FROM (SELECT zasp_temporal68.test_target(o,w,e,target_id,target_kind,test_definition_id,test_definition_version) FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor settlement association changed';END IF;
 summary:=zasp_temporal68.test_validate_output(o,w,e,r,s,i.manifest,i.body,p->'output_manifest',body);
 key_value:='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||child.run_id;
 INSERT INTO public.zasp_red_team_attempts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,verdict,objective,behavior,error_code,evidence,evidence_reference,evidence_key,evidence_version_id,evidence_checksum,evidence_size)
 VALUES(o,w,e,child.run_id,1,child.input_digest,summary->>'verdict',summary->>'objective',summary->>'behavior',NULL,summary->'evidence',p->'output_manifest'->>'reference',key_value,p->'output_manifest'->>'version_id',digest(body,'sha256'),octet_length(body));
 UPDATE public.zasp_red_team_runs SET state='complete',attempt=1,version=version+1,verdict=summary->>'verdict',evidence_reference=p->'output_manifest'->>'reference',evidence_key=key_value,evidence_version_id=p->'output_manifest'->>'version_id',evidence_checksum=digest(body,'sha256'),evidence_size=octet_length(body),started_at=(intent->>'started_at')::timestamptz,completed_at=clock_timestamp(),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,child.run_id);
 snapshot_value:=zasp_temporal68.test_snapshot(o,w,e,r,s,p->'output_manifest');snapshot_hash:=digest(convert_to(snapshot_value::text,'UTF8'),'sha256');result_hash:=digest(decode(intent->'snapshot'->>'input_digest','hex')||snapshot_hash||digest(body,'sha256'),'sha256');
 outcome:=CASE WHEN summary->>'verdict'='pass' THEN 'not_reproduced' ELSE 'reproduced' END;parent_state:=CASE WHEN outcome='not_reproduced' THEN 'contained' ELSE 'needs_human' END;
 invocation_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_test_invocation',intent->>'effect_key');
 receipt:=jsonb_build_object('invocation_id',invocation_id,'snapshot_digest',encode(snapshot_hash,'hex'),'proof_digest',encode(digest(body,'sha256'),'hex'),'settlement_generation',1,'outcome',outcome);
 result_value:=jsonb_build_object('effect_key',intent->>'effect_key','generation',1,'test_run_id',child.run_id,'run_state',parent_state,'outcome',outcome,'result_digest','sha256:'||encode(result_hash,'hex'),'input_digest','sha256:'||(intent->'snapshot'->>'input_digest'),'plan_hash','sha256:'||encode(rr.plan_hash,'hex'),'receipt',receipt,'input_artifact',i.manifest,'output_artifact',p->'output_manifest');
 UPDATE zasp_temporal68.effects SET state='verified',completed_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1);
 UPDATE public.zasp_security_agent_effects SET state='verified',version=version+1,result_digest=result_hash,outcome_id=invocation_id,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE public.zasp_security_agent_steps SET state='succeeded',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE public.zasp_security_agent_runs SET state=parent_state,version=version+1,completed_at=clock_timestamp(),updated_at=clock_timestamp(),last_error_code=CASE WHEN parent_state='needs_human' THEN 'test_condition_persists' END WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 UPDATE public.zasp_security_agent_test_links SET reconcile_state='settled',reconcile_version=2,reconcile_settlement=result_value WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 INSERT INTO public.zasp_sa_multistep_receipts(organization_id,workspace_id,environment_id,run_id,plan_hash,step_id,action_key,input_digest,result_digest,receipt_kind,receipt_version,body) VALUES(o,w,e,r,rr.plan_hash,s,'run_test',decode(intent->'snapshot'->>'input_digest','hex'),result_hash,'existing_test_settled.v1',1,receipt);
 INSERT INTO zasp_temporal68.test_settlements(organization_id,workspace_id,environment_id,run_id,step_id,test_run_id,effect_key,output_manifest,output_body,snapshot,snapshot_digest,response) VALUES(o,w,e,r,s,child.run_id,intent->>'effect_key',p->'output_manifest',body,snapshot_value,snapshot_hash,result_value);
 audit_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_test_settlement',intent->>'effect_key');
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_id,audit_id,r,s,session_user,'temporal_test_settled',result_hash,result_value);
 PERFORM zasp_temporal68.current_plan(o,w,e,r,false);PERFORM zasp_temporal68.test_evidence(o,w,e,r,s);
 IF NOT zasp_temporal68.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor settlement authority changed';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_test_source(phase text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;child_id text;k text;expected text;limit_value integer;captured boolean;adapter boolean;
 x zasp_temporal66.run_owners%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;pl public.zasp_security_agent_plans%ROWTYPE;
 f zasp_temporal68.effects%ROWTYPE;l public.zasp_security_agent_test_links%ROWTYPE;i zasp_temporal68.test_inputs%ROWTYPE;j zasp_temporal68.invocations%ROWTYPE;
 a zasp_authorization80_worker.ordered_associations%ROWTYPE;scope_value zasp_authorization80_worker.ordered_effect_scope%ROWTYPE;
 facts jsonb;reference_value jsonb;observations jsonb;application_value jsonb;settlement_value jsonb;checks jsonb;
BEGIN
 IF phase IS NULL OR phase NOT IN('progress','test.state','linked.read','linked.input','linked.dispatch','adapter.resolve','adapter.start','adapter.complete','test.settle','test.replay','test.stop') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered test phase rejected';END IF;
 captured:=phase IN('test.state','adapter.complete','test.replay','test.stop');adapter:=phase IN('adapter.resolve','adapter.start');
 limit_value:=CASE WHEN phase IN('test.settle','test.replay') THEN 1500000 WHEN phase LIKE 'linked.%' THEN 131072 WHEN phase LIKE 'adapter.%' THEN 8192 ELSE 4096 END;
 IF octet_length(q::text)>limit_value OR jsonb_typeof(q) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered test request rejected';END IF;
 IF phase='progress' THEN
  IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','operation','actor_id','run_version','approval_version','fresh_auth_at']) OR q->>'operation' IS DISTINCT FROM 'progress' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered progress shape rejected';END IF;
 ELSIF phase='test.state' THEN
  IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version']) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered test state rejected';END IF;
 ELSIF phase LIKE 'adapter.%' THEN
  IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','effect_key','operation','payload','checksum','fingerprint']) OR q->>'operation' IS DISTINCT FROM split_part(phase,'.',2)
  OR NOT COALESCE(q->>'effect_key'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered adapter shape rejected';END IF;
 ELSE
  expected:=CASE phase WHEN 'test.settle' THEN 'complete' WHEN 'test.replay' THEN 'complete' WHEN 'test.stop' THEN 'stop' ELSE split_part(phase,'.',2) END;
  IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR q->'generation' IS DISTINCT FROM '1'::jsonb OR q->>'operation' IS DISTINCT FROM expected OR jsonb_typeof(q->'payload') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered test effect shape rejected';END IF;
 END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered test scope rejected';END IF;
 END LOOP;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered test requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready() OR NOT(CASE WHEN adapter THEN zasp_temporal68.adapter_principal_ready() ELSE zasp_temporal68.principal_ready(CASE WHEN captured THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered test principal rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered test organization absent';END IF;
 IF phase LIKE 'adapter.%' THEN
  child_id:=r;
  SELECT * INTO l FROM public.zasp_security_agent_test_links WHERE(organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,child_id);
  IF l.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered adapter child absent';END IF;
  r:=l.run_id;
 END IF;
 PERFORM zasp_sa_multistep_prior.test_lock(o,w,e,r);
 s:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_step',r||chr(31)||'1');
 IF phase<>'test.state' AND phase NOT LIKE 'adapter.%' AND q->>'step_id' IS DISTINCT FROM s THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test successor changed';END IF;
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR SHARE;
 IF x.run_id IS NULL OR phase='test.state' AND q->'definition_version' IS DISTINCT FROM to_jsonb(x.definition_version) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test owner changed';END IF;
 reference_value:=jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'definition_version',x.definition_version,'input_digest',x.input_digest);
 IF phase='progress' THEN facts:=zasp_authorization80_worker.ordered68_progress_facts(reference_value);
 ELSIF adapter THEN facts:=zasp_authorization80_worker.ordered68_adapter_facts(false,reference_value);
 ELSE facts:=zasp_authorization80_worker.ordered68_effect_facts(captured,reference_value);END IF;
 a:=jsonb_populate_record(NULL::zasp_authorization80_worker.ordered_associations,facts);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_associations v WHERE v=a) OR NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.ordered_state v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.run_id,v.definition_id,v.definition_version,v.state,v.run_version,v.present)=(o,w,e,r,a.definition_id,a.definition_version,facts->>'run_state',(facts->>'run_version')::bigint,true)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test capture changed';END IF;
 SELECT * INTO st FROM public.zasp_security_agent_steps WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR SHARE;
 SELECT * INTO pl FROM public.zasp_security_agent_plans WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR SHARE;
 IF st.step_id IS NULL OR st.step_index<>1 OR st.action_key<>'run_test' OR pl.run_id IS NULL OR pl.plan->'steps'->1->>'step_id' IS DISTINCT FROM s THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test plan changed';END IF;
 SELECT * INTO f FROM zasp_temporal68.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1) FOR SHARE;
 IF phase NOT IN('progress','test.state') THEN
  IF f.run_id IS NULL OR NOT zasp_temporal68.test_intent_valid(o,w,e,r,s) OR f.snapshot_digest IS DISTINCT FROM digest(convert_to(f.snapshot::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test intent changed';END IF;
  SELECT * INTO l FROM public.zasp_security_agent_test_links WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR UPDATE;
  IF phase LIKE 'adapter.%' AND(l.test_run_id IS DISTINCT FROM child_id OR q->>'effect_key' IS DISTINCT FROM f.effect_key) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered adapter identity changed';END IF;
  SELECT * INTO i FROM zasp_temporal68.test_inputs WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  SELECT * INTO scope_value FROM zasp_authorization80_worker.ordered_effect_scope WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  IF scope_value.run_id IS NULL OR scope_value.action_key<>'run_test' OR NOT captured AND(NOT scope_value.target_current OR scope_value.fresh_until<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered test execution scope absent';END IF;
  IF NOT captured THEN
   PERFORM zasp_sa_multistep_prior.test_current(o,w,e,r,s);
   IF zasp_temporal68.test_target(o,w,e,l.target_id,l.target_kind,l.test_definition_id,l.test_definition_version) IS DISTINCT FROM f.snapshot->'targets'->'resolution' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test target changed';END IF;
  END IF;
 END IF;
 IF phase='adapter.complete' THEN
  SELECT * INTO j FROM zasp_temporal68.invocations WHERE(organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child_id,q->'payload'->>'category') FOR UPDATE;
  IF j.test_run_id IS NULL OR j.effect_key IS DISTINCT FROM f.effect_key OR j.request_digest IS DISTINCT FROM decode(q->'payload'->>'request_digest','hex') OR j.target_resolution IS DISTINCT FROM f.snapshot->'targets'->'resolution' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered held journal changed';END IF;
 END IF;
 SELECT COALESCE(jsonb_agg(zasp_authorization80_worker.ordered68_row_json(v) ORDER BY category),'[]'::jsonb) INTO observations FROM zasp_temporal68.invocations v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.test_run_id)=(o,w,e,l.test_run_id);
 SELECT zasp_authorization80_worker.ordered68_row_json(v) INTO settlement_value FROM zasp_temporal68.test_settlements v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.run_id,v.step_id)=(o,w,e,r,s);
 IF phase='test.replay' AND settlement_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered stored settlement absent';END IF;
 -- Bind the real optional step0 application receipt without turning absence
 -- into an early refusal of native progress's blocked branch.
 SELECT jsonb_agg(zasp_authorization80_worker.ordered68_row_json(v) ORDER BY v.step_id) INTO application_value FROM public.zasp_sa_multistep_receipts v WHERE(v.organization_id,v.workspace_id,v.environment_id,v.run_id)=(o,w,e,r) AND v.step_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_step',r||chr(31)||'0');
 checks:=CASE WHEN captured THEN '[]'::jsonb WHEN phase='progress' THEN facts->'checks' ELSE jsonb_build_array(jsonb_build_object('kind','security_agent','id',a.definition_id,'permission','manage_workflows'),jsonb_build_object('kind','security_agent_run','id',a.run_id,'permission','manage_workflows'),jsonb_build_object('kind','test','id',a.test_id,'permission','run_tests'),jsonb_build_object('kind',a.target_kind,'id',a.target_id,'permission','run_tests')) END;
 IF NOT zasp_authorization80_worker.catalog_ready() OR NOT zasp_temporal68.current_ready() OR NOT(CASE WHEN adapter THEN zasp_temporal68.adapter_principal_ready() ELSE zasp_temporal68.principal_ready(CASE WHEN captured THEN 'zasp_temporal_compensation' ELSE 'zasp_temporal_executor' END) END) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered test source authority changed';END IF;
 RETURN facts||jsonb_build_object('checks',checks,'ordered_action_key','run_test','ordered_device_ids','[]'::jsonb,'execution_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),
 'native_digest',encode(digest(convert_to(jsonb_build_array(zasp_authorization80_worker.ordered68_row_json(st),zasp_authorization80_worker.ordered68_row_json(pl),zasp_authorization80_worker.ordered68_row_json(f),zasp_authorization80_worker.ordered68_row_json(l),zasp_authorization80_worker.ordered68_row_json(i),observations,settlement_value,application_value)::text,'UTF8'),'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_test_state(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE proof jsonb;v jsonb;result_value jsonb;BEGIN
 proof:=zasp_authorization80_worker.require_ordered68_test('test.state',q);
 v:=zasp_authorization80_worker.ordered69_status_inner(q);
 SELECT jsonb_build_object('run_id',v->'run_id','definition_version',v->'definition_version','run_state',v->'run_state','effects',COALESCE((SELECT jsonb_agg(jsonb_build_object('step_id',x->'step_id','effect_key',x->'effect_key','generation',x->'generation','state',x->'state','action_key',x->'action_key')) FROM jsonb_array_elements(v->'effects') x WHERE x->>'action_key'='run_test'),'[]'::jsonb)) INTO result_value;
 PERFORM zasp_authorization80_worker.ordered68_test_exit('test.state',proof);RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered68_test_stop_native(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;intent jsonb;snapshot_value jsonb;result_value jsonb;audit_id text;uncertain boolean;child public.zasp_red_team_runs%ROWTYPE;t zasp_temporal68.test_stops%ROWTYPE;
BEGIN
 IF NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR zasp_temporal68.principal_ready('zasp_temporal_compensation')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor stop principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR q->>'operation' IS DISTINCT FROM 'stop' OR q->'payload' IS DISTINCT FROM '{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor stop request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';
 intent:=zasp_authorization80_worker.ordered68_effect_read(q||jsonb_build_object('operation','read'));
 IF intent->>'action_key' IS DISTINCT FROM 'run_test' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor stop action rejected';END IF;
 PERFORM zasp_sa_multistep_prior.test_lock(o,w,e,r);
 SELECT * INTO t FROM zasp_temporal68.test_stops WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF FOUND THEN PERFORM zasp_temporal68.test_stop_evidence(o,w,e,r,s);RETURN t.response;END IF;
 IF intent->>'state' NOT IN('reserved','started','unknown') OR intent->>'state'='reserved' AND NOT zasp_sa_multistep_prior.orchestration_stop_required(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor stop not required';END IF;
 SELECT * INTO child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,intent->'snapshot'->'targets'->>'test_run_id') FOR UPDATE NOWAIT;
 IF child.run_id IS NULL OR child.state<>'queued' OR child.attempt<>0 OR child.worker_id IS NOT NULL OR child.lease_token IS NOT NULL OR child.lease_expires_at IS NOT NULL
  OR EXISTS(SELECT 1 FROM public.zasp_red_team_attempts WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,child.run_id))
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id,test_run_id,reconcile_state,reconcile_version)=(o,w,e,r,s,child.run_id,'pending',1) AND reconcile_worker IS NULL AND reconcile_token IS NULL AND reconcile_expires_at IS NULL AND reconcile_settlement IS NULL)
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor stopped child association changed';END IF;
 uncertain:=intent->>'state'<>'reserved';
 UPDATE public.zasp_red_team_runs SET state=CASE WHEN uncertain THEN 'failed' ELSE 'cancelled' END,error_code=CASE WHEN uncertain THEN 'outcome_unknown' ELSE 'cancelled' END,version=version+1,completed_at=clock_timestamp(),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,child.run_id);
 UPDATE public.zasp_security_agent_steps SET state='inconclusive',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE public.zasp_security_agent_effects SET state='unknown_outcome',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE zasp_temporal68.effects SET state='stopped',completed_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1);
 UPDATE public.zasp_security_agent_runs SET state=CASE WHEN state='cancelled' THEN state ELSE 'needs_human' END,version=version+1,completed_at=COALESCE(completed_at,clock_timestamp()),updated_at=clock_timestamp(),last_error_code='test_outcome_unknown' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 result_value:=jsonb_build_object('effect_key',intent->>'effect_key','generation',1,'test_run_id',child.run_id,'run_state',(SELECT state FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)),'reason',CASE WHEN uncertain THEN 'test_outcome_unknown' ELSE 'test_cancelled_before_dispatch' END);
 snapshot_value:=zasp_temporal68.test_stop_snapshot(o,w,e,r,s);
 INSERT INTO zasp_temporal68.test_stops VALUES(o,w,e,r,s,intent->>'effect_key',snapshot_value,digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),result_value);
 audit_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_test_stop',intent->>'effect_key');
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_id,audit_id,r,s,session_user,'temporal_test_stopped',digest(convert_to(jsonb_build_object('snapshot',snapshot_value,'response',result_value)::text,'UTF8'),'sha256'),jsonb_build_object('snapshot',snapshot_value,'response',result_value));
 PERFORM zasp_temporal68.test_stop_evidence(o,w,e,r,s);
 IF NOT zasp_temporal68.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor stop catalog changed';END IF;
 RETURN result_value;
END $function$

