CREATE OR REPLACE FUNCTION zasp_authorization80_worker.ordered_legacy_claim_organizations(session_value boolean)
 RETURNS text[]
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE cohort text[];locked_count bigint;BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='retained policy claim requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF session_value IS NULL OR NOT public.zasp_security_agent_action_principal_ready()
 OR NOT zasp_authorization80_worker.catalog_ready()
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='retained policy claim rejected';END IF;
 SELECT COALESCE(array_agg(DISTINCT effect.organization_id ORDER BY effect.organization_id),ARRAY[]::text[]) INTO cohort
 FROM public.zasp_security_agent_effects effect
 WHERE (effect.action_key='create_temporary_policy' OR session_value AND effect.action_key='isolate_session')
 AND (session_value OR NOT zasp_sa_multistep_prior.ordered_action_run(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id))
 AND (effect.state='pending' OR effect.state='leased' AND effect.lease_expires_at<=transaction_timestamp()
 OR effect.state='cleanup_pending' AND effect.updated_at<=transaction_timestamp());
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=ANY(cohort) ORDER BY organization_id FOR UPDATE;
 GET DIAGNOSTICS locked_count=ROW_COUNT;
 -- The empty cohort still rechecks caller identity; no table lock is needed.
 IF locked_count<>cardinality(cohort) OR NOT public.zasp_security_agent_action_principal_ready() OR NOT zasp_authorization80_worker.catalog_ready()
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='retained policy claim authority changed';END IF;
 RETURN cohort;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.planner_receipt_row(captured jsonb, actual jsonb, kind text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE names text[];name text;rendered jsonb:=actual;pattern text:='^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]{1,6})?[+-][0-9]{2}:[0-9]{2}$';
BEGIN
 IF jsonb_typeof(captured) IS DISTINCT FROM 'object' OR jsonb_typeof(actual) IS DISTINCT FROM 'object' THEN RETURN NULL;END IF;
 names:=CASE kind WHEN 'job' THEN ARRAY['budget_started_at','budget_deadline_at'] WHEN 'reservation' THEN ARRAY['reserved_at','settled_at','released_at'] ELSE NULL END;
 IF names IS NULL THEN RETURN NULL;END IF;
 FOREACH name IN ARRAY names LOOP
  IF (captured?name) IS DISTINCT FROM(actual?name) THEN RETURN NULL;END IF;
  IF NOT(actual?name) THEN CONTINUE;END IF;
  IF actual->name='null'::jsonb THEN
   IF captured->name IS DISTINCT FROM 'null'::jsonb THEN RETURN NULL;END IF;
  ELSE
   IF jsonb_typeof(captured->name) IS DISTINCT FROM 'string' OR jsonb_typeof(actual->name) IS DISTINCT FROM 'string'
    OR NOT(captured->>name ~ pattern) OR NOT(actual->>name ~ pattern)
    OR (captured->>name)::timestamptz IS DISTINCT FROM(actual->>name)::timestamptz THEN RETURN NULL;END IF;
   rendered:=jsonb_set(rendered,ARRAY[name],captured->name);
  END IF;
 END LOOP;
 RETURN rendered;
EXCEPTION WHEN data_exception THEN RETURN NULL;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.planning68_source(phase text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal66.run_owners%ROWTYPE;j zasp_temporal68.planning_jobs%ROWTYPE;reference_value jsonb;f jsonb;compensation boolean:=phase IN('reconcile','late_usage','recovery');
BEGIN
 IF phase IS NULL OR phase NOT IN('state','load','prepare','start','result','settle','artifacts','admit','reconcile','late_usage','recovery') OR octet_length(q::text)>524288
 OR phase='state' AND NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version'])
 OR phase<>'state' AND(q->>'operation' IS DISTINCT FROM phase OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','operation']||CASE WHEN phase IN('load','recovery') THEN ARRAY[]::text[] ELSE ARRAY['payload'] END)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker planning request rejected';END IF;
 SELECT * INTO x FROM zasp_temporal66.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') AND to_jsonb(definition_version)=q->'definition_version';
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker planning owner changed';END IF;
 reference_value:=jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'run_id',x.run_id,'definition_version',x.definition_version,'input_digest',x.input_digest);
 f:=zasp_authorization80_worker.ordered68_source(compensation,reference_value);
 SELECT * INTO j FROM zasp_temporal68.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR SHARE;
 IF compensation AND(j.run_id IS NULL OR j.state NOT IN('loaded','prepared','started','completed','settled','artifacts','needs_human')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker captured planning unavailable';END IF;
 RETURN f||jsonb_build_object('planning_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'job_digest',zasp_authorization80_worker.planner_job_digest(to_jsonb(j)));
END $function$

