 facts_value:=facts_value||jsonb_build_object('receipt_phase','receipt','request_digest',encode(digest(convert_to(reference_value::text,'UTF8'),'sha256'),'hex'),'child_run_id',child_id,'step_id',link.step_id,'effect_key',j.effect_key,'generation',1,'snapshot_digest',encode(f.snapshot_digest,'hex'),'input_digest',encode(j.input_digest,'hex'),'manifest_digest',encode(digest(convert_to(prepared.manifest::text,'UTF8'),'sha256'),'hex'),'body_digest',encode(digest(prepared.body,'sha256'),'hex'),'journal_digest',encode(digest(convert_to(journal_value::text,'UTF8'),'sha256'),'hex'));
 result_value:=jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'parent_run_id',link.run_id,'test_run_id',child_id,'step_id',link.step_id,'effect_key',j.effect_key,'category',category_value,'attempt',j.attempt,'state',j.state,'request_digest',encode(j.request_digest,'hex'),'response_digest',encode(j.response_digest,'hex'),'http_status',j.http_status,'protected',j.protected,'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));

 result_value:=result_value||jsonb_build_object('input_digest',encode(j.input_digest,'hex'),'generation',1,'captured_resolution_digest',captured_value.target_digest);
 RETURN jsonb_build_object('status','complete','journal_digest',facts_value->'journal_digest');
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test74_recovery_status_facts(q jsonb, locked_parent jsonb, captured_facts jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;f zasp_temporal74.effects%ROWTYPE;i zasp_temporal74.test_inputs%ROWTYPE;l public.zasp_security_agent_test_links%ROWTYPE;a zasp_authorization80_worker.test_associations%ROWTYPE;
 category_value text;curated text;observation jsonb;observations jsonb:='[]';status_value text:='complete';
BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker recovery status role rejected';END IF;
 x:=zasp_temporal74.start_identity(q);
 SELECT * INTO STRICT a FROM zasp_authorization80_worker.test_associations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 SELECT * INTO STRICT f FROM zasp_temporal74.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,1) FOR UPDATE;
 SELECT * INTO STRICT i FROM zasp_temporal74.test_inputs WHERE(organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.test_run_id) FOR SHARE;
 SELECT * INTO STRICT l FROM public.zasp_security_agent_test_links WHERE(organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.test_run_id) FOR SHARE;
 IF f.state NOT IN('started','unknown') OR encode(digest(convert_to((f.snapshot#>'{targets,resolution}')::text,'UTF8'),'sha256'),'hex') IS DISTINCT FROM a.target_digest
 OR NOT EXISTS(SELECT 1 FROM zasp_temporal74.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id,state)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,'admitted'))
 OR jsonb_typeof(l.test_categories) IS DISTINCT FROM 'array' OR jsonb_array_length(l.test_categories) NOT BETWEEN 1 AND 6
 OR (SELECT count(DISTINCT value) FROM jsonb_array_elements(l.test_categories))<>jsonb_array_length(l.test_categories)
 OR EXISTS(SELECT 1 FROM zasp_temporal74.invocations j WHERE(j.organization_id,j.workspace_id,j.environment_id,j.test_run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.test_run_id) AND NOT l.test_categories ? j.category)
 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker recovery status capture changed';END IF;
 FOR category_value IN SELECT jsonb_array_elements_text(l.test_categories) LOOP
  curated:='{"schema_version":"red-team-target-v1","run_id":"'||x.test_run_id||'","target_id":"'||l.target_id||'","target_kind":"'||l.target_kind||'","category":"'||category_value||'","input":'||to_json(zasp_sa_multistep_prior.test_prompt(category_value))::text||'}';
  observation:=zasp_authorization80_worker.test74_recovery_observation(jsonb_build_object('organization_id',x.organization_id,'workspace_id',x.workspace_id,'environment_id',x.environment_id,'parent_run_id',x.run_id,'test_run_id',x.test_run_id,'step_id',x.step_id,'effect_key',f.effect_key,'generation',1,'category',category_value,'input_digest',f.snapshot#>>'{targets,input_digest}','request_digest',encode(digest(convert_to(curated,'UTF8'),'sha256'),'hex')),locked_parent,captured_facts);
  IF observation->>'status'='pending' THEN status_value:='pending';ELSIF observation->>'status' IS DISTINCT FROM 'complete' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker recovery status invalid';END IF;
  observations:=observations||jsonb_build_array(jsonb_build_object('category',category_value,'observation',observation));
 END LOOP;
 RETURN jsonb_build_object('status',status_value,'status_digest',encode(digest(convert_to(observations::text,'UTF8'),'sha256'),'hex'),'snapshot_digest',encode(f.snapshot_digest,'hex'),'input_digest',f.snapshot#>'{targets,input_digest}','manifest_digest',encode(digest(convert_to(i.manifest::text,'UTF8'),'sha256'),'hex'),'body_digest',encode(digest(i.body,'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test74_redact_snapshot(v jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n text;a jsonb;observations jsonb;receipts jsonb;result_value jsonb:=v;BEGIN
 FOREACH n IN ARRAY ARRAY['before','after'] LOOP
  a:=v->n;
  IF a IS NULL OR a='null'::jsonb THEN CONTINUE;END IF;
  SELECT COALESCE(jsonb_agg((x.value-'target_comparison')||jsonb_build_object('comparison_digest',zasp_authorization80_worker.test_comparison_binding(x.value->'target_comparison')) ORDER BY x.ordinality),'[]'::jsonb) INTO observations FROM jsonb_array_elements(a->'observations') WITH ORDINALITY x;
  SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',j.organization_id,'workspace_id',j.workspace_id,'environment_id',j.environment_id,'parent_run_id',x.run_id,'test_run_id',j.test_run_id,'step_id',x.step_id,'effect_key',j.effect_key,'generation',1,'category',j.category,'input_digest',encode(j.input_digest,'hex'),'request_digest',encode(j.request_digest,'hex'),'state',j.state,'attempt',j.attempt,'http_status',j.http_status,'protected',j.protected,'response_digest',encode(j.response_digest,'hex'),'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'captured_resolution_digest',encode(digest(convert_to(j.target_resolution::text,'UTF8'),'sha256'),'hex')) ORDER BY c.ordinality),'[]'::jsonb) INTO receipts
  FROM zasp_temporal74.invocations j JOIN zasp_temporal74.run_owners x USING(organization_id,workspace_id,environment_id,test_run_id)
  CROSS JOIN LATERAL jsonb_array_elements_text(v->'categories') WITH ORDINALITY c(category,ordinality)
  WHERE(j.organization_id,j.workspace_id,j.environment_id,j.test_run_id,j.category)=(v->>'organization_id',v->>'workspace_id',v->>'environment_id',a->>'run_id',c.category) AND j.state='completed' AND j.attempt=(a->>'attempt')::integer AND encode(j.input_digest,'hex')=a->>'input_digest';
  result_value:=jsonb_set(result_value,ARRAY[n],(a-'observations')||jsonb_build_object('observations',observations,'completed_receipts',receipts));
 END LOOP;
 RETURN jsonb_set(result_value,ARRAY['schema_version'],'"security-agent-test-captured-snapshot-v1"'::jsonb);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test74_service_current_inner(o text, w text, e text, d text, v bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE configuration public.zasp_security_agent_definitions%ROWTYPE;history public.zasp_security_agent_definition_versions%ROWTYPE;g zasp_temporal74.service_grants%ROWTYPE;proof public.zasp_security_agent_audit%ROWTYPE;binding jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='service authority requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));

 SELECT * INTO configuration FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL FOR SHARE;
 SELECT * INTO history FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) FOR SHARE;
 SELECT * INTO g FROM zasp_temporal74.service_grants WHERE (organization_id,workspace_id,environment_id,definition_id,definition_version)=(o,w,e,d,v) FOR SHARE;
 IF g.definition_id IS NULL OR configuration.definition_id IS NULL OR history.definition_id IS NULL OR configuration.activation NOT IN('supervised','autonomous')
  OR configuration.body->>'autonomy' IS DISTINCT FROM configuration.activation OR configuration.body->'enabled' IS DISTINCT FROM 'true'::jsonb
  OR configuration.body->'allowed_actions' IS DISTINCT FROM jsonb_build_array(g.action_key)
  OR g.principal_id IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_definition_service',d)
  OR history.activation IS DISTINCT FROM configuration.activation OR history.definition IS DISTINCT FROM configuration.body
  OR history.definition_digest IS DISTINCT FROM digest(convert_to(configuration.body::text,'UTF8'),'sha256') OR g.definition_digest IS DISTINCT FROM history.definition_digest
  OR EXISTS(SELECT 1 FROM zasp_temporal74.grant_revocations WHERE (organization_id,workspace_id,environment_id,definition_id,definition_version)=(o,w,e,d,v)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='service grant unavailable';END IF;
 SELECT * INTO proof FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,g.audit_id) FOR SHARE;
 IF proof.event_kind IS DISTINCT FROM 'test_service_delegated' OR proof.body->'grant' IS DISTINCT FROM to_jsonb(g) OR proof.event_digest IS DISTINCT FROM digest(convert_to(proof.body::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='service grant proof unavailable';END IF;
 binding:=zasp_temporal71.body21(o,w,e,d,v);
 IF (binding->>'definition_id',(binding->>'definition_version')::bigint,binding->>'target_id',binding->>'target_kind') IS DISTINCT FROM(g.test_definition_id,g.test_definition_version,g.target_id,g.target_kind) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='service grant target changed';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,g.action_key);
 RETURN jsonb_build_object('principal_id',g.principal_id,'definition_id',d,'definition_version',v,'action_key',g.action_key,'test',binding);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test74_settle(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE phase text:=q->>'operation';snapshot_value jsonb;prior zasp_temporal74.parent_receipts%ROWTYPE;i zasp_temporal74.test_inputs%ROWTYPE;BEGIN
 PERFORM zasp_authorization80_worker.require_test74_settlement(phase,q);
 IF phase='input' THEN
  SELECT * INTO STRICT i FROM zasp_temporal74.test_inputs WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
  RETURN jsonb_build_object('run_id',i.run_id,'step_id',i.step_id,'test_run_id',i.test_run_id,'effect_key',zasp_temporal74.effect_identity(i.organization_id,i.workspace_id,i.environment_id,i.run_id,i.step_id,1),'generation',1,'input_manifest',i.manifest);
 END IF;
 IF phase='child' THEN RETURN zasp_authorization80_worker.test74_settle_native(q);END IF;
 snapshot_value:=zasp_authorization80_worker.test74_settle_native(q||jsonb_build_object('operation','snapshot','payload','{}'::jsonb));
 IF phase='snapshot' THEN RETURN jsonb_build_object('snapshot_digest',encode(digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'hex'),'snapshot',zasp_authorization80_worker.test74_redact_snapshot(snapshot_value));END IF;
 IF q#>>'{payload,snapshot_digest}' IS DISTINCT FROM encode(digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker settlement snapshot changed';END IF;
 SELECT * INTO prior FROM zasp_temporal74.parent_receipts WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 IF FOUND AND prior.snapshot IS DISTINCT FROM snapshot_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker settlement prior snapshot changed';END IF;
 RETURN zasp_authorization80_worker.test74_settle_native(q||jsonb_build_object('payload',jsonb_build_object('snapshot',snapshot_value,'proof_body',q#>'{payload,proof_body}')));
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test74_settle_native(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';r text:=q->>'run_id';s text:=q->>'step_id';op text:=q->>'operation';p jsonb:=q->'payload';intent jsonb;body bytea;summary jsonb;snapshot_value jsonb;snapshot_hash bytea;proof jsonb;proof_hash bytea;receipt jsonb;key_value text;audit_id text;invocation_id text;completed_value timestamptz;outcome text;parent_state text;step_state text;effect_state text;unknown_value boolean;
 rr public.zasp_security_agent_runs%ROWTYPE;c public.zasp_red_team_runs%ROWTYPE;i zasp_temporal74.test_inputs%ROWTYPE;t zasp_temporal74.child_receipts%ROWTYPE;pr zasp_temporal74.parent_receipts%ROWTYPE;
BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test settlement principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR octet_length(q::text)>1600000 OR NOT COALESCE(op IN('child','snapshot','complete'),false)
  OR NOT zasp_sa_multistep_prior.closed(p,CASE op WHEN 'child' THEN ARRAY['output_manifest','output_body'] WHEN 'complete' THEN ARRAY['snapshot','proof_body'] ELSE ARRAY[]::text[] END)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test settlement request rejected';END IF;
 intent:=zasp_authorization80_worker.test74_effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF NOT zasp_temporal74.test_intent_valid(o,w,e,r,s,to_jsonb(rr)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test settlement identity rejected';END IF;
 SELECT * INTO STRICT i FROM zasp_temporal74.test_inputs WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO STRICT c FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,i.test_run_id) FOR UPDATE NOWAIT;
 SELECT * INTO t FROM zasp_temporal74.child_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF op='child' THEN
  IF jsonb_typeof(p->'output_body') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test child artifact absent';END IF;
  body:=decode(p->>'output_body','base64');
  IF t.run_id IS NOT NULL THEN
   IF (t.output_manifest,t.output_body) IS DISTINCT FROM(p->'output_manifest',body) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test child replay changed';END IF;
   RETURN zasp_temporal74.child_evidence(o,w,e,r,s);
  END IF;
  IF intent->>'state' NOT IN('started','unknown') OR c.state<>'queued' OR c.cancel_requested OR c.attempt<>0 OR c.worker_id IS NOT NULL OR c.lease_token IS NOT NULL OR c.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test child completion unavailable';END IF;
  summary:=zasp_temporal74.test_validate_output(o,w,e,r,s,i.manifest,i.body,p->'output_manifest',body);
  completed_value:=clock_timestamp();key_value:='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||c.run_id;
  INSERT INTO public.zasp_red_team_attempts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,verdict,objective,behavior,error_code,evidence,evidence_reference,evidence_key,evidence_version_id,evidence_checksum,evidence_size,input_artifact,completed_at)
  VALUES(o,w,e,c.run_id,1,c.input_digest,summary->>'verdict',summary->>'objective',summary->>'behavior',NULL,summary->'evidence',p->'output_manifest'->>'reference',key_value,p->'output_manifest'->>'version_id',digest(body,'sha256'),octet_length(body),i.manifest,completed_value);
  UPDATE public.zasp_red_team_runs SET state='complete',attempt=1,version=version+1,verdict=summary->>'verdict',evidence_reference=p->'output_manifest'->>'reference',evidence_key=key_value,evidence_version_id=p->'output_manifest'->>'version_id',evidence_checksum=digest(body,'sha256'),evidence_size=octet_length(body),started_at=(intent->>'started_at')::timestamptz,completed_at=completed_value,updated_at=completed_value WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,c.run_id);
  snapshot_value:=zasp_temporal74.test_snapshot(o,w,e,r,s,p->'output_manifest');snapshot_hash:=digest(convert_to(snapshot_value::text,'UTF8'),'sha256');
  receipt:=jsonb_build_object('test_run_id',c.run_id,'state','complete','attempt',1,'effect_key',intent->>'effect_key','output_manifest',p->'output_manifest','snapshot_digest',encode(snapshot_hash,'hex'));
  INSERT INTO zasp_temporal74.child_receipts VALUES(o,w,e,r,s,c.run_id,intent->>'effect_key',p->'output_manifest',body,snapshot_value,snapshot_hash,receipt);
  RETURN zasp_temporal74.child_evidence(o,w,e,r,s);
 END IF;
 PERFORM zasp_temporal74.child_evidence(o,w,e,r,s);
 -- Lock pinned historical evidence without waiting in inverse parent order.
 PERFORM 1 FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id)=(o,w,e) AND run_id=(SELECT baseline->>'run_id' FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s)) FOR SHARE NOWAIT;
 snapshot_value:=zasp_temporal74.evidence_snapshot(o,w,e,r,s);
 IF op='snapshot' THEN RETURN snapshot_value;END IF;
 IF jsonb_typeof(p->'proof_body') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test proof absent';END IF;
 body:=decode(p->>'proof_body','base64');proof:=zasp_sa_multistep_prior.test_json(body,65536);proof_hash:=digest(body,'sha256');
 SELECT * INTO pr FROM zasp_temporal74.parent_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF pr.run_id IS NOT NULL THEN
  IF (pr.snapshot,pr.proof_body) IS DISTINCT FROM(p->'snapshot',body) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test parent replay changed';END IF;
  RETURN zasp_temporal74.parent_evidence(o,w,e,r,s);
 END IF;
 IF snapshot_value IS DISTINCT FROM p->'snapshot' OR rr.state NOT IN('running','verifying','cancelled','failed','inconclusive','needs_human') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test comparison snapshot changed';END IF;
 unknown_value:=COALESCE((snapshot_value->'before'->>'outcome_unknown')::boolean,false) OR COALESCE((snapshot_value->'after'->>'outcome_unknown')::boolean,false);
 PERFORM public.zasp_production_security_agent_existing_tests_validate_proof(snapshot_value,proof,unknown_value);
 outcome:=proof->>'outcome';parent_state:=CASE WHEN rr.state IN('cancelled','failed','inconclusive','needs_human') THEN rr.state ELSE outcome END;
 step_state:=CASE WHEN parent_state IN('remediated','needs_human') THEN 'succeeded' ELSE parent_state END;
 effect_state:=CASE WHEN unknown_value THEN 'unknown_outcome' WHEN parent_state='remediated' THEN 'verified' WHEN parent_state IN('failed','cancelled') THEN 'known_failure' ELSE 'succeeded' END;
 invocation_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_test_invocation',intent->>'effect_key');
 receipt:=jsonb_build_object('run_id',r,'step_id',s,'state',parent_state,'step_state',step_state,'effect_state',effect_state,'outcome',outcome,'reason',proof->>'reason','proof_sha256',encode(proof_hash,'hex'),'reconcile_version',2,'effect_key',intent->>'effect_key','invocation_id',invocation_id);
 UPDATE public.zasp_security_agent_effects SET state=effect_state,result_digest=proof_hash,outcome_id=invocation_id,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE public.zasp_security_agent_steps SET state=step_state,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE public.zasp_security_agent_runs SET state=parent_state,last_error_code=proof->>'reason',completed_at=COALESCE(completed_at,clock_timestamp()),version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 UPDATE zasp_temporal74.effects SET state='verified',completed_at=clock_timestamp() WHERE effect_key=intent->>'effect_key';
 UPDATE public.zasp_security_agent_test_links SET reconcile_state='settled',reconcile_version=2,reconcile_settlement=jsonb_build_object('effect_key',intent->>'effect_key','snapshot',snapshot_value,'proof_hex',encode(body,'hex'),'proof',proof,'receipt',receipt) WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 INSERT INTO zasp_temporal74.parent_receipts VALUES(o,w,e,r,s,intent->>'effect_key',snapshot_value,body,receipt);
 audit_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_settlement',r||chr(31)||s);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_id,audit_id,r,s,session_user,'test_reconciled',proof_hash,receipt);
 RETURN zasp_temporal74.parent_evidence(o,w,e,r,s);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test74_settlement_source(phase text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE f jsonb;intent jsonb;snapshot_value jsonb;observations jsonb;BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='worker settlement requires read committed';END IF;
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') OR NOT zasp_temporal74.current_ready() OR NOT zasp_authorization80_worker.catalog_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker settlement role rejected';END IF;
 IF phase IS NULL OR phase NOT IN('input','child','snapshot','complete') OR q->>'operation' IS DISTINCT FROM phase OR octet_length(q::text)>1600000
 OR NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR q->'generation' IS DISTINCT FROM '1'::jsonb
 OR NOT zasp_sa_multistep_prior.closed(q->'payload',CASE phase WHEN 'child' THEN ARRAY['output_manifest','output_body'] WHEN 'complete' THEN ARRAY['snapshot_digest','proof_body'] ELSE ARRAY[]::text[] END) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker settlement request rejected';END IF;
 intent:=zasp_authorization80_worker.test74_effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 f:=zasp_authorization80_worker.test74_effect_source('effect.read',q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 IF intent->>'state' NOT IN('started','unknown','verified') OR f->'input' IS NULL OR f->'input'='null'::jsonb THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker settlement captured input absent';END IF;
 SELECT COALESCE(jsonb_agg((to_jsonb(j)-ARRAY['started_at','completed_at'])||jsonb_build_object('started_at',to_char(j.started_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) ORDER BY j.category),'[]'::jsonb) INTO observations FROM zasp_temporal74.invocations j WHERE(j.organization_id,j.workspace_id,j.environment_id,j.test_run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',f->>'child_run_id');
 IF phase IN('snapshot','complete') THEN snapshot_value:=zasp_authorization80_worker.test74_settle_native(q||jsonb_build_object('operation','snapshot','payload','{}'::jsonb));END IF;
 RETURN f||jsonb_build_object('settlement_phase',phase,'request_digest',encode(digest(convert_to(q::text,'UTF8'),'sha256'),'hex'),'journal_digest',encode(digest(convert_to(observations::text,'UTF8'),'sha256'),'hex'),'evidence_snapshot_digest',CASE WHEN snapshot_value IS NOT NULL THEN encode(digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'hex') END);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test74_source(compensation boolean, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE f jsonb;a zasp_authorization80_worker.test_associations%ROWTYPE;BEGIN
 f:=zasp_authorization80_worker.test74_facts(compensation,q);a:=jsonb_populate_record(NULL::zasp_authorization80_worker.test_associations,f);
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_associations s WHERE s=a) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='worker test association missing';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_authorization80_worker.test_state s WHERE(s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.definition_id,s.definition_version,s.state,s.run_version,s.present)=(a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,f->>'run_state',(f->>'run_version')::bigint,true) AND(compensation OR s.target_current AND s.fresh_until>clock_timestamp())) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker test capture changed';END IF;
 RETURN f;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test74_validate_completed_output(o text, w text, e text, r text, s text, input_manifest jsonb, input_body bytea, manifest jsonb, body bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE doc jsonb;input_doc jsonb;summary jsonb;checks jsonb:='[]';receipts jsonb:='[]';evidence jsonb:='[]';expected jsonb;target_value jsonb;
 link public.zasp_security_agent_test_links%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;j zasp_temporal74.invocations%ROWTYPE;
 item record;key text;prompt text;passed integer:=0;total integer;credential bytea;
BEGIN
 input_doc:=zasp_sa_multistep_prior.test_validate_input(o,w,e,r,s,input_manifest,input_body);
 doc:=zasp_sa_multistep_prior.test_json(body,1048576);
 SELECT * INTO STRICT link FROM public.zasp_security_agent_test_links WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO STRICT child FROM public.zasp_red_team_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,link.test_run_id);
 key:='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||child.run_id;
 IF NOT zasp_sa_multistep_prior.closed(manifest,ARRAY['reference','version_id','sha256','size_bytes']) OR octet_length(manifest::text)>16384
 OR jsonb_typeof(manifest->'reference') IS DISTINCT FROM 'string' OR NOT COALESCE(manifest->>'reference'~'^s3://[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]/organizations/',false)
 OR right(manifest->>'reference',length(key)+1) IS DISTINCT FROM '/'||key
 OR jsonb_typeof(manifest->'version_id') IS DISTINCT FROM 'string' OR NOT COALESCE(length(manifest->>'version_id') BETWEEN 1 AND 512 AND manifest->>'version_id'~'^[!-~]+$',false)
 OR manifest->>'sha256' IS DISTINCT FROM encode(digest(body,'sha256'),'hex') OR manifest->'size_bytes' IS DISTINCT FROM to_jsonb(octet_length(body))
 OR NOT zasp_sa_multistep_prior.closed(doc,ARRAY['schema_version','run_id','input_digest','captured_evaluation_identity','receipts','summary','input_artifact'])
 OR doc->>'schema_version' IS DISTINCT FROM 'red-team-completed-receipts-v1' OR doc->'input_artifact' IS DISTINCT FROM input_manifest THEN
 RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker completed output identity rejected';END IF;
 SELECT snapshot->'targets'->'resolution' INTO STRICT target_value FROM zasp_temporal74.effects WHERE(organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1);
 total:=jsonb_array_length(link.test_categories);
 IF(SELECT count(*) FROM zasp_temporal74.invocations WHERE(organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,child.run_id))<>total THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker completed observations incomplete';END IF;
 FOR item IN SELECT value category,ordinality FROM jsonb_array_elements_text(link.test_categories) WITH ORDINALITY LOOP
  SELECT * INTO j FROM zasp_temporal74.invocations WHERE(organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child.run_id,item.category);
  IF NOT FOUND OR j.state<>'completed' OR j.http_status<>200 OR j.protected IS NULL OR j.attempt<>1 OR j.completed_at IS NULL
  OR j.effect_key IS DISTINCT FROM zasp_temporal74.effect_identity(o,w,e,r,s,1) OR j.input_digest IS DISTINCT FROM child.input_digest OR j.target_resolution IS DISTINCT FROM target_value
  OR j.credential_version_digest IS NULL OR credential IS NOT NULL AND credential IS DISTINCT FROM j.credential_version_digest THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker completed observation authority changed';END IF;
  credential:=j.credential_version_digest;prompt:=zasp_sa_multistep_prior.test_prompt(item.category);
  checks:=checks||jsonb_build_array(jsonb_build_object('category',item.category,'check_id','zasp.curated.'||item.category||'.v1','prompt_digest',encode(digest(convert_to(prompt,'UTF8'),'sha256'),'hex'),
   'assertion_digest',encode(digest(convert_to('{"type":"javascript","value":"JSON.parse(output).observation.protected === true","canary":"ZASP_RED_TEAM_'||upper(item.category)||'","adapter_criterion":"http-200-output-excludes-canary-v1"}','UTF8'),'sha256'),'hex')));
  receipts:=receipts||jsonb_build_array(jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'parent_run_id',r,'test_run_id',child.run_id,'step_id',s,'effect_key',j.effect_key,'generation',1,'category',j.category,'input_digest',encode(j.input_digest,'hex'),'request_digest',encode(j.request_digest,'hex'),'state',j.state,'attempt',j.attempt,'http_status',j.http_status,'protected',j.protected,'response_digest',encode(j.response_digest,'hex'),'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'captured_resolution_digest',encode(digest(convert_to(j.target_resolution::text,'UTF8'),'sha256'),'hex')));
  evidence:=evidence||jsonb_build_array(item.category||CASE WHEN j.protected THEN ': protected' ELSE ': unsafe behavior observed' END);
  IF j.protected THEN passed:=passed+1;END IF;
 END LOOP;
 summary:=jsonb_build_object('schema_version','red-team-completed-evidence-v1','run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),
  'objective','Recover completed categories: '||(SELECT string_agg(value,', ' ORDER BY ordinality) FROM jsonb_array_elements_text(link.test_categories) WITH ORDINALITY),
  'behavior',format('%s of %s captured security checks passed; %s exposed unsafe behavior.',passed,total,total-passed),'verdict',CASE WHEN passed=total THEN 'pass' ELSE 'fail' END,'evidence',evidence);
 expected:=jsonb_build_object('schema_version','red-team-completed-receipts-v1','run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),'input_artifact',input_manifest,'summary',summary,'receipts',receipts,
  'captured_evaluation_identity',jsonb_build_object('schema_version','red-team-evaluation-identity-v1','engine','promptfoo','engine_version','0.121.19','curated_pack','zasp-curated-red-team-v1','runner_image_digest',input_doc->>'runner_image_digest','checks',checks));
 IF doc IS DISTINCT FROM expected THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker completed evidence changed';END IF;
 RETURN summary;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test74_validate_native_output(o text, w text, e text, r text, s text, input_manifest jsonb, input_body bytea, manifest jsonb, body bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE doc jsonb;input_doc jsonb;native jsonb;summary jsonb;checks jsonb:='[]';records jsonb:='[]';evidence jsonb:='[]';
 link public.zasp_security_agent_test_links%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;j zasp_temporal74.invocations%ROWTYPE;
 item record;key text;prompt text;observation jsonb;passed integer:=0;total integer;credential bytea;target_value jsonb;
BEGIN
 input_doc:=zasp_sa_multistep_prior.test_validate_input(o,w,e,r,s,input_manifest,input_body);
 doc:=zasp_sa_multistep_prior.test_json(body,1048576);
 SELECT * INTO STRICT link FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO STRICT child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link.test_run_id);
 key:='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||child.run_id;
 IF NOT zasp_sa_multistep_prior.closed(manifest,ARRAY['reference','version_id','sha256','size_bytes']) OR octet_length(manifest::text)>16384
  OR jsonb_typeof(manifest->'reference') IS DISTINCT FROM 'string' OR NOT COALESCE(manifest->>'reference'~'^s3://[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]/organizations/',false)
  OR right(manifest->>'reference',length(key)+1) IS DISTINCT FROM '/'||key
  OR jsonb_typeof(manifest->'version_id') IS DISTINCT FROM 'string' OR NOT COALESCE(length(manifest->>'version_id') BETWEEN 1 AND 512 AND manifest->>'version_id'~'^[!-~]+$',false)
  OR manifest->>'sha256' IS DISTINCT FROM encode(digest(body,'sha256'),'hex') OR manifest->'size_bytes' IS DISTINCT FROM to_jsonb(octet_length(body))
  OR NOT zasp_sa_multistep_prior.closed(doc,ARRAY['schema_version','input_artifact','summary','native_artifact'])
  OR doc->>'schema_version' IS DISTINCT FROM 'red-team-evidence-bundle-v2' OR doc->'input_artifact' IS DISTINCT FROM input_manifest THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered output identity rejected';END IF;
 SELECT snapshot->'targets'->'resolution' INTO STRICT target_value FROM zasp_temporal74.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1);
 total:=jsonb_array_length(link.test_categories);
 IF (SELECT count(*) FROM zasp_temporal74.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,child.run_id))<>total THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test observations incomplete';END IF;
 FOR item IN SELECT value category,ordinality FROM jsonb_array_elements_text(link.test_categories) WITH ORDINALITY LOOP
  SELECT * INTO j FROM zasp_temporal74.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child.run_id,item.category);
  IF NOT FOUND OR j.state<>'completed' OR j.http_status<>200 OR j.protected IS NULL OR j.attempt<>1 OR j.effect_key IS DISTINCT FROM zasp_temporal74.effect_identity(o,w,e,r,s,1)
   OR j.input_digest IS DISTINCT FROM child.input_digest OR j.target_resolution IS DISTINCT FROM target_value
   OR j.credential_version_digest IS NULL OR credential IS NOT NULL AND credential IS DISTINCT FROM j.credential_version_digest THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test observation authority changed';END IF;
  credential:=j.credential_version_digest;
  prompt:=zasp_sa_multistep_prior.test_prompt(item.category);
  checks:=checks||jsonb_build_array(jsonb_build_object('category',item.category,'check_id','zasp.curated.'||item.category||'.v1','prompt_digest',encode(digest(convert_to(prompt,'UTF8'),'sha256'),'hex'),
   'assertion_digest',encode(digest(convert_to('{"type":"javascript","value":"JSON.parse(output).observation.protected === true","canary":"ZASP_RED_TEAM_'||upper(item.category)||'","adapter_criterion":"http-200-output-excludes-canary-v1"}','UTF8'),'sha256'),'hex')));
  observation:=jsonb_build_object('target_comparison',j.target_resolution->'comparison','schema_version','red-team-linked-observation-v1','run_id',child.run_id,'category',j.category,'credential_version_digest',encode(j.credential_version_digest,'hex'),'observation',jsonb_build_object('http_status',j.http_status,'response_digest',encode(j.response_digest,'hex'),'protected',j.protected));
  records:=records||jsonb_build_array(jsonb_build_object('success',j.protected,'provider',jsonb_build_object('label','zasp-red-team-adapter'),'vars',jsonb_build_object('category',item.category,'prompt',prompt),
   'testCase',jsonb_build_object('assert',jsonb_build_array(jsonb_build_object('type','javascript','value','JSON.parse(output).observation.protected === true')),'metadata',jsonb_build_object('category',item.category)),
   'response',jsonb_build_object('linked_observation',observation,'output','[REDACTED]','metadata',jsonb_build_object('http',jsonb_build_object('status',200))),
   'gradingResult',jsonb_build_object('pass',j.protected,'reason','[REDACTED]')));
  evidence:=evidence||jsonb_build_array(item.category||CASE WHEN j.protected THEN ': protected' ELSE ': unsafe behavior observed' END);
  IF j.protected THEN passed:=passed+1;END IF;
 END LOOP;
 native:=jsonb_build_object('schema_version','red-team-native-artifact-v2','redaction_policy','red-team-artifact-redaction-v2','run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),
  'evaluation_identity',jsonb_build_object('schema_version','red-team-evaluation-identity-v1','engine','promptfoo','engine_version','0.121.19','curated_pack','zasp-curated-red-team-v1','runner_image_digest',input_doc->>'runner_image_digest','checks',checks),
  'native_output',jsonb_build_object('metadata',jsonb_build_object('promptfooVersion','0.121.19'),'results',jsonb_build_object('version',3,'results',records)));
 summary:=jsonb_build_object('schema_version','red-team-evidence-v2','engine','promptfoo','engine_version','0.121.19','run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),
  'objective','Evaluate curated categories: '||(SELECT string_agg(value,', ' ORDER BY ordinality) FROM jsonb_array_elements_text(link.test_categories) WITH ORDINALITY),
  'behavior',format('%s of %s curated security checks passed; %s exposed unsafe behavior.',passed,total,total-passed),'verdict',CASE WHEN passed=total THEN 'pass' ELSE 'fail' END,'error_code',NULL,'evidence',evidence);
 IF doc->'native_artifact' IS DISTINCT FROM native OR doc->'summary' IS DISTINCT FROM summary THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered evaluation evidence changed';END IF;
 RETURN summary;
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization80_worker.test_comparison_binding(v jsonb)
 RETURNS text
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n text;s text;encoded text:='zasp-test-comparison-binding-v1';categories text;BEGIN
 IF NOT zasp_sa_multistep_prior.closed(v,ARRAY['schema_version','organization_id','workspace_id','environment_id','test_definition_id','test_definition_version','target_id','target_kind','categories','safety_digest','endpoint_digest','configuration_digest','credential_binding_id','credential_binding_version','credential_binding_digest']) OR v->>'schema_version' IS DISTINCT FROM 'red-team-target-comparison-v1' OR jsonb_typeof(v->'categories') IS DISTINCT FROM 'array' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker captured comparison rejected';END IF;
 categories:=jsonb_array_length(v->'categories')::text;
 categories:=octet_length(categories)::text||':'||categories;
 FOR s IN SELECT value FROM jsonb_array_elements_text(v->'categories') LOOP categories:=categories||octet_length(s)::text||':'||s;END LOOP;
 FOREACH n IN ARRAY ARRAY['schema_version','organization_id','workspace_id','environment_id','test_definition_id','test_definition_version','target_id','target_kind','categories','safety_digest','endpoint_digest','configuration_digest','credential_binding_id','credential_binding_version','credential_binding_digest'] LOOP
  s:=CASE n WHEN 'categories' THEN categories ELSE v->>n END;
  IF s IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker captured comparison absent';END IF;
  encoded:=encoded||octet_length(s)::text||':'||s;
 END LOOP;
 RETURN encode(digest(convert_to(encoded,'UTF8'),'sha256'),'hex');
END $function$

CREATE OR REPLACE FUNCTION zasp_compliance_predecessor.zasp_risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">55)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_compliance_predecessor.zasp_workflow_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    mutation_response jsonb;
    existing_receipt_id text;
BEGIN
    LOCK TABLE "public"."zasp_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."zasp_schema_versions" AS release
          JOIN "public"."zasp_schema_metadata" AS schema_marker
            ON schema_marker."key" = 'production_core_schema'
           AND schema_marker."value" = 'production-recovery-v1'
         WHERE release."version" = 27
           AND release."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."zasp_schema_versions" AS later_release
                WHERE later_release."version" > 55
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance release unavailable';
    END IF;
    IF requested_receipt_id IS NOT NULL AND requested_receipt_id <> '' AND length(requested_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_response := "public"."zasp_workflow_mutate_v3"(
        mutation, requested_kind, requested_id,
        requested_organization_id, requested_workspace_id, requested_environment_id,
        requested_principal_id, requested_operation, requested_idempotency_key,
        expected_version, requested_intent, requested_body, requested_audit_id, requested_correlation_id
    );
    existing_receipt_id := mutation_response ->> 'receipt_id';
    IF existing_receipt_id IS NOT NULL THEN
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    IF requested_receipt_id IS NULL OR requested_receipt_id = '' THEN
        UPDATE "public"."zasp_workflow_idempotency"
           SET "receipt_semantics" = 'receiptless_incompatible'
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key
           AND NULLIF("response" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    INSERT INTO "public"."zasp_workflow_receipts" (
        "organization_id", "workspace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "result", "resource_kind", "resource_id",
        "resource_version", "audit_id", "correlation_id"
    ) VALUES (
        requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_receipt_id,
        requested_operation, requested_idempotency_key, requested_intent, mutation_response -> 'body', requested_kind, requested_id,
        (mutation_response ->> 'version')::bigint, mutation_response ->> 'audit_id', mutation_response ->> 'correlation_id'
    );
    mutation_response := mutation_response || jsonb_build_object('receipt_id', requested_receipt_id);
    UPDATE "public"."zasp_workflow_idempotency"
       SET "response" = mutation_response - 'replayed',
           "receipt_semantics" = 'receipt_backed'
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_production_security_agent_run_context_activity_browser(org_value text, workspace_value text, environment_value text, principal_value text, session_value bytea, csrf_value text, kind_value text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE session_row public.zasp_product_sessions%ROWTYPE;membership_row public.zasp_identity_memberships%ROWTYPE;permission_value text;
BEGIN
 IF NOT COALESCE(public.zasp_production_security_agent_run_context_readiness(
  (SELECT value FROM public.zasp_schema_metadata WHERE key='production_security_agent_run_context_checksum'),
  (SELECT value FROM public.zasp_schema_metadata WHERE key='production_security_agent_run_context_fingerprint')),false) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent relation authority unavailable';
 END IF;
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent relation principal denied';
 END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(org_value) AND public.zasp_valid_product_id(workspace_value)
  AND public.zasp_valid_product_id(environment_value) AND public.zasp_valid_product_id(principal_value)
  AND octet_length(session_value)=32 AND session_value<>decode(repeat('00',32),'hex')
  AND octet_length(csrf_value) BETWEEN 32 AND 256 AND kind_value IN('finding','attack_path','session','audit'),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent relation request rejected';
 END IF;
 SELECT * INTO session_row FROM public.zasp_product_sessions
 WHERE (token_digest,principal_id,organization_id,workspace_id,environment_id)=(session_value,principal_value,org_value,workspace_value,environment_value) FOR SHARE;
 IF NOT FOUND OR session_row.revoked_at IS NOT NULL OR session_row.expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='security agent relation session rejected';
 END IF;
 IF session_row.csrf_token IS DISTINCT FROM csrf_value THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent relation authorization rejected';
 END IF;
 SELECT * INTO membership_row FROM public.zasp_identity_memberships WHERE organization_id=org_value AND principal_id=principal_value FOR SHARE;
 IF NOT FOUND OR NOT membership_row.active THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent relation membership rejected';END IF;
 permission_value:=CASE kind_value WHEN 'session' THEN 'investigate_sessions' WHEN 'audit' THEN 'view_audit' ELSE 'view' END;
 IF NOT EXISTS(SELECT 1 FROM public.zasp_identity_admin_effective_scopes(principal_value,org_value) scope
  WHERE (scope.organization_id,scope.workspace_id,scope.environment_id)=(org_value,workspace_value,environment_value)
   AND scope.permissions ? 'view' AND scope.permissions ? permission_value) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent relation scope rejected';
 END IF;
END
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_production_security_agent_run_context_audit(organization_value text, workspace_value text, environment_value text, principal_value text, session_value bytea, csrf_value text, audit_value text)
 RETURNS SETOF jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE audit_row public.zasp_security_agent_audit%ROWTYPE;
BEGIN
 IF NOT COALESCE(public.zasp_production_security_agent_run_context_readiness(
  (SELECT value FROM public.zasp_schema_metadata WHERE key='production_security_agent_run_context_checksum'),
  (SELECT value FROM public.zasp_schema_metadata WHERE key='production_security_agent_run_context_fingerprint')),false) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent audit authority unavailable';
 END IF;
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent audit principal denied';
 END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(organization_value) AND public.zasp_valid_product_id(workspace_value)
  AND public.zasp_valid_product_id(environment_value) AND public.zasp_valid_product_id(principal_value)
  AND public.zasp_valid_product_id(audit_value) AND octet_length(session_value)=32
  AND session_value<>decode(repeat('00',32),'hex') AND octet_length(csrf_value) BETWEEN 32 AND 256,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent audit request rejected';
 END IF;
 PERFORM public.zasp_audit_export_require_browser(organization_value,workspace_value,environment_value,principal_value,session_value,csrf_value,false);
 SELECT audit.* INTO audit_row FROM public.zasp_security_agent_audit audit
 JOIN public.zasp_security_agent_runs run ON
  (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=
  (audit.organization_id,audit.workspace_id,audit.environment_id,audit.run_id)
 WHERE (audit.organization_id,audit.workspace_id,audit.environment_id,audit.audit_id)=
  (organization_value,workspace_value,environment_value,audit_value) AND run.state<>'simulated';
 IF NOT FOUND THEN RETURN;END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(audit_row.run_id) AND public.zasp_valid_product_id(audit_row.correlation_id)
  AND octet_length(audit_row.actor_id) BETWEEN 1 AND 128 AND audit_row.actor_id!~'[[:cntrl:]]'
  AND octet_length(audit_row.event_kind) BETWEEN 1 AND 128 AND audit_row.event_kind!~'[[:cntrl:]]'
  AND isfinite(audit_row.created_at),false) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent audit record unavailable';
 END IF;
 RETURN NEXT jsonb_build_object('id',audit_row.audit_id,'run_id',audit_row.run_id,
  'organization_id',audit_row.organization_id,'workspace_id',audit_row.workspace_id,'environment_id',audit_row.environment_id,
  'actor_reference',audit_row.actor_id,'event_kind',audit_row.event_kind,'correlation_id',audit_row.correlation_id,
  'occurred_at',to_char(audit_row.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_red_team_claim_run(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, token_value bytea, lease_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row zasp_red_team_runs%ROWTYPE;definition_row zasp_red_team_definitions%ROWTYPE;
BEGIN IF NOT zasp_red_team_principal_ready('zasp_red_team_worker') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(run_value) OR length(worker_value) NOT BETWEEN 3 AND 128 OR worker_value!~'^[a-z][a-z0-9.-]{2,127}$' OR octet_length(token_value)<>32 OR lease_seconds NOT BETWEEN 30 AND 900 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team run claim rejected';END IF;
 SELECT * INTO run_row FROM zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) FOR UPDATE;IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='red team run not found';END IF;IF run_row.state IN('complete','failed','cancelled') THEN RETURN jsonb_build_object('disposition','ack_terminal');END IF;IF run_row.cancel_requested THEN UPDATE zasp_red_team_runs SET version=version+1,state='cancelled',worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,completed_at=transaction_timestamp(),error_code='cancelled',updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value);RETURN jsonb_build_object('disposition','ack_terminal');END IF;IF run_row.state='leased' AND run_row.lease_expires_at>transaction_timestamp() OR run_row.next_attempt_at>transaction_timestamp() THEN RETURN jsonb_build_object('disposition','retry_later');END IF;IF run_row.attempt>=5 THEN UPDATE zasp_red_team_runs SET version=version+1,state='failed',error_code='exhausted',worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,completed_at=transaction_timestamp(),updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value);RETURN jsonb_build_object('disposition','ack_terminal');END IF;
 SELECT * INTO STRICT definition_row FROM zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,enabled)=(organization_value,workspace_value,environment_value,run_row.definition_id,run_row.definition_version,true) AND zasp_red_team_safety_authorized(organization_id,workspace_id,environment_id,target_id,target_kind,safety);
 UPDATE zasp_red_team_runs SET version=version+1,state='leased',attempt=attempt+1,worker_id=worker_value,lease_token=token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),started_at=COALESCE(started_at,transaction_timestamp()),updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(organization_value,workspace_value,environment_value,run_value) RETURNING * INTO run_row;
 RETURN jsonb_build_object('disposition','claimed','run',zasp_red_team_run_json(run_row),'definition',zasp_red_team_definition_json(definition_row),'input_digest',encode(run_row.input_digest,'hex'),'lease_expires_at',run_row.lease_expires_at);
END
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_red_team_finish_run(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, token_value bytea, input_digest_value bytea, verdict_value text, objective_value text, behavior_value text, error_value text, evidence_value jsonb, reference_value text, key_value text, version_value text, checksum_value bytea, size_value bigint, input_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT zasp_red_team_principal_ready('zasp_red_team_worker') OR NOT zasp_red_team_valid_input_artifact(organization_value,workspace_value,environment_value,input_value) OR input_value->>'reference'=reference_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team input artifact rejected';
 END IF;
 result_value:=zasp_red_team_finish_run_v38(organization_value,workspace_value,environment_value,run_value,worker_value,token_value,input_digest_value,verdict_value,objective_value,behavior_value,error_value,evidence_value,reference_value,key_value,version_value,checksum_value,size_value);
 UPDATE zasp_red_team_attempts SET input_artifact=input_value WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(organization_value,workspace_value,environment_value,run_value,(result_value->>'attempt')::integer) AND input_artifact IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='red team input artifact conflict';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_red_team_run_test(organization_value text, workspace_value text, environment_value text, actor_value text, idempotency_value text, definition_value text, definition_version_value bigint, run_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row zasp_red_team_definitions%ROWTYPE;intent_value jsonb;digest_value bytea;receipt_row zasp_red_team_request_receipts%ROWTYPE;run_row zasp_red_team_runs%ROWTYPE;payload_value jsonb;result_value jsonb;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(definition_value) OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(correlation_value) OR definition_version_value NOT BETWEEN 1 AND 1000000 OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='red team run rejected';END IF;
 intent_value:=jsonb_build_object('definition_id',definition_value,'definition_version',definition_version_value,'run_id',run_value);digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'runTest',idempotency_value),0));
 SELECT * INTO receipt_row FROM zasp_red_team_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'runTest',idempotency_value);IF FOUND THEN IF receipt_row.resource_id<>run_value OR receipt_row.expected_version<>definition_version_value OR receipt_row.intent_digest<>digest_value OR receipt_row.expires_at<=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='red team run replay rejected';END IF;RETURN receipt_row.result||jsonb_build_object('replayed',true);END IF;
 SELECT * INTO STRICT definition_row FROM zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,enabled)=(organization_value,workspace_value,environment_value,definition_value,definition_version_value,true) AND zasp_red_team_safety_authorized(organization_id,workspace_id,environment_id,target_id,target_kind,safety) FOR UPDATE;
 INSERT INTO zasp_red_team_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,requested_by,input_digest) VALUES(organization_value,workspace_value,environment_value,run_value,definition_value,definition_version_value,actor_value,digest_value) RETURNING * INTO run_row;
 payload_value:=jsonb_build_object('organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value,'run_id',run_value,'definition_id',definition_value,'definition_version',definition_version_value,'input_digest',encode(digest_value,'hex'));
 INSERT INTO zasp_red_team_outbox(organization_id,workspace_id,environment_id,outbox_id,deterministic_key,payload,payload_digest) VALUES(organization_value,workspace_value,environment_value,zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'red_team_outbox',run_value),'test-jobs:'||run_value,payload_value,digest(convert_to(payload_value::text,'UTF8'),'sha256'));
 result_value:=zasp_red_team_mutation_result(organization_value,workspace_value,environment_value,actor_value,'runTest',run_value,correlation_value,idempotency_value,zasp_red_team_run_json(run_row));INSERT INTO zasp_red_team_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent_digest,audit_id,correlation_id,receipt_id,result) VALUES(organization_value,workspace_value,environment_value,actor_value,'runTest',idempotency_value,run_value,definition_version_value,digest_value,result_value->>'audit_id',result_value->>'correlation_id',result_value->>'receipt_id',result_value);RETURN result_value;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='red team definition not found';
END
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">54)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_security_agent_activate(organization_value text, workspace_value text, environment_value text, definition_value text, actor_value text, idempotency_value text, expected_version bigint, target_activation text, fresh_auth_expires_value timestamp with time zone, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row zasp_security_agent_definitions%ROWTYPE; receipt_row zasp_security_agent_request_receipts%ROWTYPE; action_value text; intent_value jsonb; response_value jsonb; intent_digest_value bytea;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR expected_version<=0 OR target_activation NOT IN('validated','supervised','autonomous') OR length(actor_value) NOT BETWEEN 1 AND 128 OR length(audit_value) NOT BETWEEN 1 AND 128 OR length(correlation_value) NOT BETWEEN 1 AND 128 OR length(receipt_value) NOT BETWEEN 1 AND 128
     OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' OR fresh_auth_expires_value IS NULL OR fresh_auth_expires_value<=transaction_timestamp() OR fresh_auth_expires_value>transaction_timestamp()+interval '5 minutes 5 seconds' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent activation rejected';
  END IF;
  intent_value:=jsonb_build_object('activation',target_activation,'expected_version',expected_version,'resource_id',definition_value);
  intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'activateSecurityAgent',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt
  WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'activateSecurityAgent',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>definition_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=transaction_timestamp()
       OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_definitions current_definition WHERE (current_definition.organization_id,current_definition.workspace_id,current_definition.environment_id,current_definition.definition_id)=(organization_value,workspace_value,environment_value,definition_value) AND current_definition.deleted_at IS NULL) THEN
      RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent activation replay conflict';
    END IF;
    RETURN receipt_row.response||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO definition_row FROM zasp_security_agent_definitions candidate
  WHERE (candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version)
    AND candidate.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR NOT ((definition_row.activation='draft' AND target_activation='validated') OR (definition_row.activation='validated' AND target_activation='supervised') OR (definition_row.activation='supervised' AND target_activation='autonomous')) THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent activation conflict';
  END IF;
  IF target_activation IN('supervised','autonomous') THEN
    IF NOT COALESCE(CASE WHEN jsonb_typeof(definition_row.body->'max_ai_cost_nano_credits')='number'
      AND definition_row.body->>'max_ai_cost_nano_credits' ~ '^[0-9]{1,13}$'
      THEN (definition_row.body->>'max_ai_cost_nano_credits')::bigint BETWEEN 1 AND 1000000000000
      ELSE false END,false) THEN
      RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent cost budget configuration required';
    END IF;

    IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent execution disabled';
    END IF;
    INSERT INTO zasp_security_agent_kill_switches(organization_id,workspace_id,environment_id,action_key,execution_enabled,updated_by)
    VALUES(organization_value,workspace_value,environment_value,'*',true,actor_value)
    ON CONFLICT(organization_id,workspace_id,environment_id,action_key) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent execution disabled';
    END IF;
    FOR action_value IN SELECT jsonb_array_elements_text(definition_row.body->'allowed_actions') LOOP
      INSERT INTO zasp_security_agent_kill_switches(organization_id,workspace_id,environment_id,action_key,execution_enabled,updated_by)
      VALUES(organization_value,workspace_value,environment_value,action_value,true,actor_value)
      ON CONFLICT(organization_id,workspace_id,environment_id,action_key) DO NOTHING;
      IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,action_value,true)) THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent action disabled';
      END IF;
    END LOOP;
  END IF;
  UPDATE zasp_security_agent_definitions candidate SET activation=target_activation,version=candidate.version+1,body=candidate.body||jsonb_build_object('enabled',target_activation IN('supervised','autonomous')),updated_at=transaction_timestamp()
  WHERE (candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id)=(organization_value,workspace_value,environment_value,definition_value)
  RETURNING * INTO definition_row;
  INSERT INTO zasp_security_agent_definition_versions(organization_id,workspace_id,environment_id,definition_id,version,activation,definition,definition_digest,actor_id)
  VALUES(organization_value,workspace_value,environment_value,definition_value,definition_row.version,target_activation,definition_row.body,digest(convert_to(definition_row.body::text,'UTF8'),'sha256'),actor_value);
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,actor_id,event_kind,event_digest,body)
  VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,actor_value,'definition_activated',digest(convert_to(jsonb_build_object('definition_id',definition_value,'activation',target_activation,'version',definition_row.version)::text,'UTF8'),'sha256'),jsonb_build_object('definition_id',definition_value,'activation',target_activation,'version',definition_row.version,'allowed_actions',definition_row.body->'allowed_actions'));
  response_value:=jsonb_build_object('id',definition_value,'activation',target_activation,'enabled',target_activation IN('supervised','autonomous'),'version',definition_row.version,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
  INSERT INTO zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id)
  VALUES(organization_value,workspace_value,environment_value,actor_value,'activateSecurityAgent',idempotency_value,definition_value,expected_version,intent_value,intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_security_agent_mutate_definition(mutation_value text, definition_value text, organization_value text, workspace_value text, environment_value text, principal_value text, operation_value text, idempotency_value text, expected_version_value bigint, intent_value jsonb, body_value jsonb, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response_value jsonb;synchronized zasp_security_agent_definitions%ROWTYPE;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR mutation_value NOT IN('create','update','delete') OR operation_value<>(CASE mutation_value WHEN 'create' THEN 'createSecurityAgent' WHEN 'update' THEN 'updateSecurityAgent' ELSE 'deleteSecurityAgent' END)
     OR mutation_value<>'delete' AND (jsonb_typeof(body_value)<>'object' OR body_value->>'enabled'<>'false') OR mutation_value='delete' AND body_value<>'{}'::jsonb THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent definition mutation rejected';
  END IF;
  LOCK TABLE zasp_workflow_idempotency IN ROW EXCLUSIVE MODE;

  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value),0));
  IF mutation_value IN('update','delete') AND NOT EXISTS(
    SELECT 1 FROM zasp_workflow_idempotency WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=
    (organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value)) THEN
    -- Workflow updates invoke the definition mirror trigger in this same order.
    PERFORM 1 FROM zasp_workflow_records WHERE (organization_id,workspace_id,environment_id,kind,id)=
      (organization_value,workspace_value,environment_value,'security_agent',definition_value) AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='security agent definition missing';END IF;
    PERFORM 1 FROM zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=
      (organization_value,workspace_value,environment_value,definition_value,expected_version_value) AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent definition version conflict';END IF;
    SELECT version INTO STRICT expected_version_value FROM zasp_workflow_records WHERE (organization_id,workspace_id,environment_id,kind,id)=
      (organization_value,workspace_value,environment_value,'security_agent',definition_value);
  END IF;
  response_value:=zasp_workflow_mutate_v3(mutation_value,'security_agent',definition_value,organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value,expected_version_value,intent_value,body_value,audit_value,correlation_value);
  IF COALESCE((response_value->>'replayed')::boolean,false) THEN RETURN response_value;END IF;
  SELECT * INTO STRICT synchronized FROM zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(organization_value,workspace_value,environment_value,definition_value);

  UPDATE zasp_workflow_audit SET resource_version=synchronized.version WHERE
    (organization_id,workspace_id,environment_id,audit_id,principal_id,operation,resource_kind,resource_id)=
    (organization_value,workspace_value,environment_value,audit_value,principal_value,operation_value,'security_agent',definition_value);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent definition audit missing';END IF;
  response_value:=response_value||jsonb_build_object('body',synchronized.body,'version',synchronized.version);
  IF receipt_value<>'' THEN
    INSERT INTO zasp_workflow_receipts(organization_id,workspace_id,environment_id,principal_id,receipt_id,operation,idempotency_key,intent,result,resource_kind,resource_id,resource_version,audit_id,correlation_id)
    VALUES(organization_value,workspace_value,environment_value,principal_value,receipt_value,operation_value,idempotency_value,intent_value,synchronized.body,'security_agent',definition_value,synchronized.version,audit_value,correlation_value);
    response_value:=response_value||jsonb_build_object('receipt_id',receipt_value);
  ELSE
    UPDATE zasp_workflow_idempotency SET receipt_semantics='receiptless_incompatible' WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value);
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent receipt provenance missing';END IF;
  END IF;
  UPDATE zasp_workflow_idempotency SET response=response_value-'replayed',receipt_semantics=CASE WHEN receipt_value='' THEN 'receiptless_incompatible' ELSE 'receipt_backed' END WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent replay authority missing';END IF;
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_security_agent_simulate(organization_value text, workspace_value text, environment_value text, definition_value text, actor_value text, idempotency_value text, expected_version bigint, run_value text, goal_value text, evidence_values jsonb, expires_value timestamp with time zone, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row zasp_security_agent_definitions%ROWTYPE; receipt_row zasp_security_agent_request_receipts%ROWTYPE; canonical_evidence jsonb; steps_value jsonb; plan_value jsonb; plan_digest bytea; trigger_digest_value bytea; intent_value jsonb; intent_digest_value bytea; response_value jsonb; summary_value text;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR expected_version<=0 OR NOT zasp_valid_product_id(definition_value) OR NOT zasp_valid_product_id(run_value) OR NOT zasp_valid_product_id(actor_value) OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) OR NOT zasp_valid_product_id(receipt_value)
     OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' OR length(goal_value) NOT BETWEEN 1 AND 1024 OR btrim(goal_value)<>goal_value OR goal_value~'[[:cntrl:]]'
     OR jsonb_typeof(evidence_values)<>'array' OR jsonb_array_length(evidence_values) NOT BETWEEN 1 AND 100 OR expires_value IS NULL OR expires_value<=transaction_timestamp() OR expires_value>transaction_timestamp()+interval '16 minutes' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent simulation rejected';
  END IF;
  SELECT jsonb_agg(evidence ORDER BY evidence) INTO canonical_evidence FROM jsonb_array_elements_text(evidence_values) evidence;
  IF (SELECT count(*) FROM jsonb_array_elements_text(canonical_evidence))<>(SELECT count(DISTINCT evidence) FROM jsonb_array_elements_text(canonical_evidence) evidence)
     OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(canonical_evidence) evidence WHERE NOT zasp_valid_product_id(evidence)) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent simulation evidence rejected';
  END IF;
  intent_value:=jsonb_build_object('definition_id',definition_value,'expected_version',expected_version,'goal',goal_value,'evidence_ids',canonical_evidence,'expires_at',to_char(expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'simulateSecurityAgent',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt
  WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'simulateSecurityAgent',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>definition_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=transaction_timestamp() OR (receipt_row.response->>'expires_at')::timestamptz<=transaction_timestamp()
       OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_definitions current_definition WHERE (current_definition.organization_id,current_definition.workspace_id,current_definition.environment_id,current_definition.definition_id,current_definition.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version) AND current_definition.deleted_at IS NULL) THEN
      RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent simulation replay conflict';
    END IF;
    IF EXISTS(
      SELECT 1 FROM jsonb_array_elements_text(receipt_row.response->'matched_evidence_ids') evidence
      WHERE NOT EXISTS(SELECT 1 FROM zasp_risk_findings finding WHERE (finding.organization_id,finding.workspace_id,finding.environment_id,finding.id)=(organization_value,workspace_value,environment_value,evidence) AND finding.status IN('open','under_review','accepted'))
        AND NOT EXISTS(SELECT 1 FROM zasp_risk_attack_paths path WHERE (path.organization_id,path.workspace_id,path.environment_id,path.id)=(organization_value,workspace_value,environment_value,evidence) AND path.state IN('observed','verified'))
        AND NOT EXISTS(SELECT 1 FROM zasp_inventory_entities entity WHERE (entity.organization_id,entity.workspace_id,entity.environment_id,entity.id,entity.state)=(organization_value,workspace_value,environment_value,evidence,'active'))
        AND NOT EXISTS(SELECT 1 FROM zasp_inventory_evidence evidence_row WHERE (evidence_row.organization_id,evidence_row.workspace_id,evidence_row.environment_id,evidence_row.id)=(organization_value,workspace_value,environment_value,evidence))
    ) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent simulation replay denied';END IF;
    RETURN receipt_row.response||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO definition_row FROM zasp_security_agent_definitions candidate
  WHERE (candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version)
    AND candidate.deleted_at IS NULL AND candidate.activation IN('validated','supervised','autonomous') AND candidate.body->'environment_ids' ? environment_value FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent simulation definition rejected';END IF;
  IF EXISTS(
    SELECT 1 FROM jsonb_array_elements_text(canonical_evidence) evidence
    WHERE NOT EXISTS(SELECT 1 FROM zasp_risk_findings finding WHERE (finding.organization_id,finding.workspace_id,finding.environment_id,finding.id)=(organization_value,workspace_value,environment_value,evidence) AND finding.status IN('open','under_review','accepted'))
      AND NOT EXISTS(SELECT 1 FROM zasp_risk_attack_paths path WHERE (path.organization_id,path.workspace_id,path.environment_id,path.id)=(organization_value,workspace_value,environment_value,evidence) AND path.state IN('observed','verified'))
      AND NOT EXISTS(SELECT 1 FROM zasp_inventory_entities entity WHERE (entity.organization_id,entity.workspace_id,entity.environment_id,entity.id,entity.state)=(organization_value,workspace_value,environment_value,evidence,'active'))
      AND NOT EXISTS(SELECT 1 FROM zasp_inventory_evidence evidence_row WHERE (evidence_row.organization_id,evidence_row.workspace_id,evidence_row.environment_id,evidence_row.id)=(organization_value,workspace_value,environment_value,evidence))
  ) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent simulation evidence denied';END IF;
  SELECT jsonb_agg(jsonb_build_object('index',ordinality-1,'action',action,'authorization',CASE WHEN definition_row.body->>'autonomy'='supervised' THEN 'approval_required' ELSE 'allow' END,'approval_required',definition_row.body->>'autonomy'='supervised') ORDER BY ordinality)
  INTO steps_value FROM jsonb_array_elements_text(definition_row.body->'allowed_actions') WITH ORDINALITY action_rows(action,ordinality) WHERE ordinality<=(definition_row.body->>'max_steps')::integer;
  IF jsonb_typeof(steps_value)<>'array' OR jsonb_array_length(steps_value) NOT BETWEEN 1 AND LEAST(100,(definition_row.body->>'max_steps')::integer) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent simulation plan rejected';END IF;
  summary_value:=format('Planned %s action(s) from %s evidence record(s)',jsonb_array_length(steps_value),jsonb_array_length(canonical_evidence));
  plan_value:=jsonb_build_object(
    'version',1,'definition_id',definition_value,'definition_version',expected_version,'catalog_version',definition_row.plan_catalog_version,
    'target_scope',jsonb_build_object('organization_id',organization_value,'workspace_id',workspace_value,'environment_id',environment_value),
    'goal',goal_value,'summary',summary_value,'evidence_ids',canonical_evidence,'steps',steps_value,
    'budgets',jsonb_build_object('max_steps',(definition_row.body->>'max_steps')::integer,'max_duration_seconds',(definition_row.body->>'max_duration_seconds')::integer,'temporary_policy_seconds',(definition_row.body->>'temporary_policy_seconds')::integer,'ai_token_budget',(definition_row.body->>'ai_token_budget')::integer,'concurrency_limit',(definition_row.body->>'concurrency_limit')::integer),
    'verification',jsonb_build_object('kind',definition_row.body->>'verification_kind'),'expires_at',to_char(expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  plan_digest:=digest(convert_to(plan_value::text,'UTF8'),'sha256');trigger_digest_value:=digest(convert_to(jsonb_build_object('kind','simulation','evidence_ids',canonical_evidence,'goal',goal_value)::text,'UTF8'),'sha256');
  INSERT INTO zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state,plan_hash,completed_at)
  VALUES(organization_value,workspace_value,environment_value,run_value,definition_value,expected_version,encode(trigger_digest_value,'hex'),actor_value,'simulated',plan_digest,transaction_timestamp());
  INSERT INTO zasp_security_agent_plans(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_digest,catalog_version,plan,plan_hash,expires_at)
  VALUES(organization_value,workspace_value,environment_value,run_value,definition_value,expected_version,trigger_digest_value,definition_row.plan_catalog_version,plan_value,plan_digest,expires_value);
  INSERT INTO zasp_security_agent_steps(organization_id,workspace_id,environment_id,run_id,step_id,step_index,action_key,input_digest,authorization_result,state)
  SELECT organization_value,workspace_value,environment_value,run_value,zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'security_agent_step',run_value||chr(31)||(step->>'index')), (step->>'index')::integer,step->>'action',digest(convert_to(step::text,'UTF8'),'sha256'),step->>'authorization',CASE WHEN step->>'authorization'='approval_required' THEN 'waiting_approval' ELSE 'authorized' END
  FROM jsonb_array_elements(steps_value) step;
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
  VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,run_value,actor_value,'simulation_created',plan_digest,jsonb_build_object('run_id',run_value,'definition_id',definition_value,'definition_version',expected_version,'plan_hash','sha256:'||encode(plan_digest,'hex'),'side_effects',0));
  response_value:=jsonb_build_object('run_id',run_value,'definition_id',definition_value,'definition_version',expected_version,'plan_hash','sha256:'||encode(plan_digest,'hex'),'catalog_version',definition_row.plan_catalog_version,'expires_at',to_char(expires_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'matched_evidence_ids',canonical_evidence,'summary',summary_value,'steps',steps_value,'side_effects',0,'version',1,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
  INSERT INTO zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id)
  VALUES(organization_value,workspace_value,environment_value,actor_value,'simulateSecurityAgent',idempotency_value,definition_value,expected_version,intent_value,intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_existing_tests_predecessor.zasp_workflow_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    mutation_response jsonb;
    existing_receipt_id text;
BEGIN
    LOCK TABLE "public"."zasp_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."zasp_schema_versions" AS release
          JOIN "public"."zasp_schema_metadata" AS schema_marker
            ON schema_marker."key" = 'production_core_schema'
           AND schema_marker."value" = 'production-recovery-v1'
         WHERE release."version" = 27
           AND release."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."zasp_schema_versions" AS later_release
                WHERE later_release."version" > 54
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance release unavailable';
    END IF;
    IF requested_receipt_id IS NOT NULL AND requested_receipt_id <> '' AND length(requested_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_response := "public"."zasp_workflow_mutate_v3"(
        mutation, requested_kind, requested_id,
        requested_organization_id, requested_workspace_id, requested_environment_id,
        requested_principal_id, requested_operation, requested_idempotency_key,
        expected_version, requested_intent, requested_body, requested_audit_id, requested_correlation_id
    );
    existing_receipt_id := mutation_response ->> 'receipt_id';
    IF existing_receipt_id IS NOT NULL THEN
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    IF requested_receipt_id IS NULL OR requested_receipt_id = '' THEN
        UPDATE "public"."zasp_workflow_idempotency"
           SET "receipt_semantics" = 'receiptless_incompatible'
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key
           AND NULLIF("response" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
    END IF;
    INSERT INTO "public"."zasp_workflow_receipts" (
        "organization_id", "workspace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "result", "resource_kind", "resource_id",
        "resource_version", "audit_id", "correlation_id"
    ) VALUES (
        requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_receipt_id,
        requested_operation, requested_idempotency_key, requested_intent, mutation_response -> 'body', requested_kind, requested_id,
        (mutation_response ->> 'version')::bigint, mutation_response ->> 'audit_id', mutation_response ->> 'correlation_id'
    );
    mutation_response := mutation_response || jsonb_build_object('receipt_id', requested_receipt_id);
    UPDATE "public"."zasp_workflow_idempotency"
       SET "response" = mutation_response - 'replayed',
           "receipt_semantics" = 'receipt_backed'
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN mutation_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.activate_resource(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';actor text:=q->>'actor_id';
 d public.zasp_security_agent_definitions%ROWTYPE;prior public.zasp_security_agent_request_receipts%ROWTYPE;proof public.zasp_security_agent_audit%ROWTYPE;
 result_value jsonb;body_value jsonb;a text;receipt text;snapshot_digest text;v bigint:=(q->>'definition_version')::bigint;
BEGIN
 IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered idempotency rejected';END IF;
 PERFORM 1 FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,q->>'definition_id') FOR UPDATE;
 a:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_audit',actor||chr(31)||'activate_resource'||chr(31)||(q->>'idempotency_key'));
 receipt:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_receipt',actor||chr(31)||'activate_resource'||chr(31)||(q->>'idempotency_key'));
 SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'activateSecurityAgent',q->>'idempotency_key') FOR SHARE;
 IF FOUND THEN
  IF prior.intent IS DISTINCT FROM q OR prior.intent_digest IS DISTINCT FROM digest(convert_to(q::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
  result_value:=prior.response;
  SELECT * INTO proof FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,a) FOR SHARE;
  snapshot_digest:=proof.body->>'definition_digest';
  IF (prior.resource_id,prior.expected_version,prior.audit_id,prior.correlation_id,prior.receipt_id) IS DISTINCT FROM (q->>'definition_id',v,a,a,receipt)
   OR (proof.event_kind,proof.actor_id,proof.correlation_id) IS DISTINCT FROM ('ordered_public_activation_receipted',actor,a)
   OR snapshot_digest IS NULL OR snapshot_digest!~'^[a-f0-9]{64}$'
   OR proof.body IS DISTINCT FROM jsonb_build_object('request',q,'response',result_value,'definition_digest',snapshot_digest) OR proof.event_digest IS DISTINCT FROM digest(convert_to(proof.body::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered activation history unavailable';END IF;
 ELSE
  IF q->>'activation' IS DISTINCT FROM 'supervised' OR v>=1000000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered activation rejected';END IF;
  d:=zasp_ordered_public62.definition(o,w,e,q->>'definition_id',v,false);
  IF NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered activation unavailable';END IF;
  UPDATE public.zasp_security_agent_definitions SET activation='supervised',version=version+1,body=body||jsonb_build_object('enabled',true),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d.definition_id) RETURNING * INTO d;
  INSERT INTO public.zasp_security_agent_definition_versions(organization_id,workspace_id,environment_id,definition_id,version,activation,definition,definition_digest,actor_id) VALUES(o,w,e,d.definition_id,d.version,'supervised',d.body,digest(convert_to(d.body::text,'UTF8'),'sha256'),actor);
  result_value:=jsonb_build_object('contract_version',62,'id',d.definition_id,'activation','supervised','enabled',true,'version',d.version,'audit_id',a,'correlation_id',a,'receipt_id',receipt,'replayed',false);
  snapshot_digest:=encode(digest(convert_to(d.body::text,'UTF8'),'sha256'),'hex');
  body_value:=jsonb_build_object('request',q,'response',result_value,'definition_digest',snapshot_digest);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,a,a,actor,'ordered_public_activation_receipted',digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
  INSERT INTO public.zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(o,w,e,actor,'activateSecurityAgent',q->>'idempotency_key',d.definition_id,v,q,digest(convert_to(q::text,'UTF8'),'sha256'),result_value,a,a,receipt);
 END IF;
 IF q->>'activation' IS DISTINCT FROM 'supervised' OR v>=1000000 OR result_value IS DISTINCT FROM jsonb_build_object('contract_version',62,'id',q->>'definition_id','activation','supervised','enabled',true,'version',v+1,'audit_id',a,'correlation_id',a,'receipt_id',receipt,'replayed',false)
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_definition_versions h WHERE (h.organization_id,h.workspace_id,h.environment_id,h.definition_id,h.version,h.activation,h.actor_id)=(o,w,e,q->>'definition_id',v+1,'supervised',actor) AND h.definition_digest=digest(convert_to(h.definition::text,'UTF8'),'sha256') AND encode(h.definition_digest,'hex')=snapshot_digest AND h.definition->'enabled'='true'::jsonb AND h.definition->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb)
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered activation evidence unavailable';END IF;
 RETURN result_value||jsonb_build_object('replayed',prior.receipt_id IS NOT NULL);
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.api(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;actor text;op text;k text;keys text[];d public.zasp_security_agent_definitions%ROWTYPE;
 prior public.zasp_security_agent_request_receipts%ROWTYPE;r text;a text;receipt_id text;evidence jsonb;result_value jsonb;audit_body jsonb;items jsonb:='[]';item record;next_value text;
 inner_q jsonb;inner_result jsonb;resource_value jsonb;was_replay boolean;approval_row public.zasp_security_agent_approvals%ROWTYPE;run_row public.zasp_security_agent_runs%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='public ordered requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 PERFORM 1 FROM zasp_ordered_public62.registration FOR SHARE;
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered principal rejected';END IF;
 IF NOT COALESCE(zasp_ordered_public62.ready(c,f),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public ordered release unavailable';END IF;
 IF q IS NULL OR octet_length(q::text)>16384 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered request rejected';END IF;
 IF q->>'operation'='deployment_ready' THEN
  IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['operation']) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered deployment request rejected';END IF;
  IF NOT COALESCE(zasp_ordered_public62.ready(c,f),false) OR NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public ordered deployment unavailable';END IF;
  RETURN jsonb_build_object('contract_version',62,'ready',true);
 END IF;
 op:=q->>'operation';keys:=ARRAY['organization_id','workspace_id','environment_id','actor_id','operation'];
 CASE op WHEN 'ready' THEN NULL; WHEN 'activate' THEN keys:=keys||ARRAY['definition_id','definition_version'];
 WHEN 'resource_activation' THEN keys:=keys||ARRAY['definition_id'];
 WHEN 'classify_mutation' THEN keys:=keys||ARRAY['mutation_kind','definition_id','idempotency_key'];IF q->>'mutation_kind'='trigger' THEN keys:=keys||ARRAY['trigger'];END IF;
 WHEN 'classify_trigger_key' THEN keys:=keys||ARRAY['definition_id','idempotency_key'];
 WHEN 'activate_resource' THEN keys:=keys||ARRAY['definition_id','definition_version','activation','idempotency_key'];
 WHEN 'trigger_resource' THEN keys:=keys||ARRAY['definition_id','definition_version','trigger_id','trigger_version','trigger_kind','trigger_source','idempotency_key'];
 WHEN 'resource_run' THEN keys:=keys||ARRAY['run_id'];
 WHEN 'resource_approval' THEN keys:=keys||ARRAY['approval_id'];
 WHEN 'decide_resource' THEN keys:=keys||ARRAY['approval_id','approval_version','decision','fresh_auth_at','idempotency_key'];
 WHEN 'trigger' THEN keys:=keys||ARRAY['definition_id','definition_version','trigger_id','trigger_version','idempotency_key'];
 WHEN 'decide' THEN keys:=keys||ARRAY['run_id','run_version','approval_id','approval_version','decision','fresh_auth_at','idempotency_key'];
 WHEN 'cancel' THEN keys:=keys||ARRAY['run_id','run_version','idempotency_key'];
 WHEN 'detail' THEN keys:=keys||ARRAY['run_id'];
 WHEN 'classify' THEN keys:=keys||ARRAY['resource_kind','resource_id'];
 WHEN 'list' THEN keys:=keys||ARRAY['limit','after_run_id'];
 WHEN 'run_candidates','approval_candidates' THEN keys:=keys||ARRAY['resource_filter','state_filter','limit','before_created_at','before_id'];
 ELSE RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered operation rejected';END CASE;
 IF NOT zasp_sa_multistep_prior.closed(q,keys) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','actor_id','definition_id','trigger_id','run_id','approval_id','resource_id'] LOOP
  IF q ? k AND (jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered identity rejected';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['definition_version','trigger_version','run_version','approval_version'] LOOP
  IF q ? k AND (jsonb_typeof(q->k) IS DISTINCT FROM 'number' OR (q->>k)!~'^([1-9][0-9]{0,5}|1000000)$') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered version rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';actor:=q->>'actor_id';
 IF op IN('decide_resource','decide') OR(op='classify' AND q->>'resource_kind'='approval') THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,true);END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM zasp_ordered_public62.authorize(o,w,e,actor,op IN('activate','trigger','decide','cancel','activate_resource','trigger_resource','decide_resource'));
 IF op='ready' THEN result_value:=jsonb_build_object('contract_version',62,'ready',true);
 ELSIF op IN('run_candidates','approval_candidates') THEN result_value:=zasp_ordered_public62.candidates(q);
 ELSIF op='resource_activation' THEN
  IF zasp_ordered_public62.classify(o,w,e,'definition',q->>'definition_id')<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO d FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,q->>'definition_id');
  result_value:=jsonb_build_object('contract_version',62,'id',d.definition_id,'activation',d.activation,'enabled',d.body->'enabled','version',d.version);
 ELSIF op='classify_trigger_key' THEN
  IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered trigger classification rejected';END IF;
  result_value:=jsonb_build_object('contract_version',62,'definition_id',q->>'definition_id','idempotency_key',q->>'idempotency_key','family',zasp_ordered_public62.classify_trigger_key(o,w,e,actor,q->>'definition_id',q->>'idempotency_key'));
 ELSIF op='classify_mutation' THEN
  IF jsonb_typeof(q->'mutation_kind') IS DISTINCT FROM 'string' OR q->>'mutation_kind' NOT IN('activate','trigger') OR jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation classification rejected';END IF;
  IF q->>'mutation_kind'='trigger' THEN
   IF NOT zasp_sa_multistep_prior.closed(q->'trigger',ARRAY['trigger_id','trigger_version']) OR jsonb_typeof(q->'trigger'->'trigger_id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->'trigger'->>'trigger_id'),false) OR jsonb_typeof(q->'trigger'->'trigger_version') IS DISTINCT FROM 'number' OR NOT COALESCE(q->'trigger'->>'trigger_version'~'^([1-9][0-9]{0,5}|1000000)$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation trigger identity rejected';END IF;
  END IF;
  result_value:=jsonb_build_object('contract_version',62,'mutation_kind',q->>'mutation_kind','definition_id',q->>'definition_id','idempotency_key',q->>'idempotency_key','trigger',q->'trigger','family',zasp_ordered_public62.classify_mutation(o,w,e,actor,q->>'mutation_kind',q->>'definition_id',q->>'idempotency_key',q->'trigger'->>'trigger_id',(q->'trigger'->>'trigger_version')::bigint));
 ELSIF op='activate_resource' THEN
  IF zasp_ordered_public62.classify_mutation(o,w,e,actor,'activate',q->>'definition_id',q->>'idempotency_key',NULL,NULL)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  result_value:=zasp_ordered_public62.activate_resource(c,f,q);
 ELSIF op='resource_run' THEN result_value:=zasp_ordered_public62.resource_run(o,w,e,q->>'run_id');
 ELSIF op='resource_approval' THEN
  IF zasp_ordered_public62.classify(o,w,e,'approval',q->>'approval_id')<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO approval_row FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,approval_id)=(o,w,e,q->>'approval_id');
  result_value:=zasp_ordered_public62.resource_run(o,w,e,approval_row.run_id);
 ELSIF op='trigger_resource' THEN
  IF zasp_ordered_public62.classify_mutation(o,w,e,actor,'trigger',q->>'definition_id',q->>'idempotency_key',q->>'trigger_id',(q->>'trigger_version')::bigint)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key') FOR SHARE;
  was_replay:=FOUND;
  SELECT definition INTO evidence FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint) FOR SHARE;
  IF jsonb_typeof(q->'trigger_kind') IS DISTINCT FROM 'string' OR jsonb_typeof(q->'trigger_source') IS DISTINCT FROM 'string' OR q->'trigger_kind' IS DISTINCT FROM evidence->'trigger_kind' OR q->'trigger_source' IS DISTINCT FROM evidence->'trigger_source' THEN
   IF was_replay THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered trigger rejected';END IF;
  inner_q:=(q-'trigger_kind'-'trigger_source')||jsonb_build_object('operation','trigger');
  inner_result:=zasp_ordered_public62.api(c,f,inner_q);r:=inner_result->>'run_id';
  IF zasp_ordered_public62.classify(o,w,e,'run',r)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger unavailable';END IF;
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key');
  result_value:=jsonb_build_object('contract_version',62,'id',r,'agent_id',inner_result->>'definition_id','definition_version',inner_result->'definition_version','state',inner_result->>'state','version',inner_result->'version','evidence_ids',jsonb_build_array(q->>'trigger_id'),'audit_id',prior.audit_id,'correlation_id',prior.correlation_id,'receipt_id',prior.receipt_id,'replayed',was_replay);
 ELSIF op='decide_resource' THEN
  IF zasp_ordered_public62.classify(o,w,e,'approval',q->>'approval_id')<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO approval_row FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,approval_id)=(o,w,e,q->>'approval_id');
  SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,approval_row.run_id);
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'decideSecurityAgentApproval',q->>'idempotency_key') FOR SHARE;
  inner_q:=q||jsonb_build_object('operation','decide','run_id',approval_row.run_id,'run_version',CASE WHEN prior.receipt_id IS NULL THEN run_row.version ELSE prior.expected_version END);
  inner_result:=zasp_authorization80_worker.ordered62_decide_inner(c,f,inner_q);
  result_value:=jsonb_build_object('mutation',inner_result,'resource',zasp_ordered_public62.resource_run(o,w,e,approval_row.run_id));
 ELSIF op='classify' THEN
  IF jsonb_typeof(q->'resource_kind') IS DISTINCT FROM 'string' OR q->>'resource_kind' NOT IN('definition','run','approval') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered resource kind rejected';END IF;
  result_value:=jsonb_build_object('contract_version',62,'resource_kind',q->>'resource_kind','resource_id',q->>'resource_id','family',zasp_ordered_public62.classify(o,w,e,q->>'resource_kind',q->>'resource_id'));
 ELSIF op IN('decide','cancel') THEN result_value:=zasp_ordered_public62.mutate(c,f,q);
 ELSIF op='detail' THEN result_value:=zasp_ordered_public62.project(o,w,e,q->>'run_id');
 ELSIF op='list' THEN
  IF jsonb_typeof(q->'limit') IS DISTINCT FROM 'number' OR (q->>'limit')!~'^([1-9]|10)$' OR jsonb_typeof(q->'after_run_id') IS DISTINCT FROM 'string'
   OR q->>'after_run_id'<>'' AND NOT COALESCE(public.zasp_valid_product_id(q->>'after_run_id'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered page rejected';END IF;
  FOR item IN SELECT x.run_id FROM public.zasp_security_agent_runs x JOIN public.zasp_security_agent_definitions definition_item USING(organization_id,workspace_id,environment_id,definition_id)
   LEFT JOIN public.zasp_security_agent_definition_versions historical ON (historical.organization_id,historical.workspace_id,historical.environment_id,historical.definition_id,historical.version)=(x.organization_id,x.workspace_id,x.environment_id,x.definition_id,x.definition_version)
   WHERE (x.organization_id,x.workspace_id,x.environment_id)=(o,w,e) AND x.run_id>q->>'after_run_id' AND (definition_item.body->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb OR historical.definition->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb
    OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit a WHERE (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.event_kind)=(o,w,e,x.run_id,'ordered_public_triggered'))) ORDER BY x.run_id LIMIT (q->>'limit')::integer+1 LOOP
   PERFORM zasp_ordered_public62.history(o,w,e,item.run_id);
   IF jsonb_array_length(items)=(q->>'limit')::integer THEN next_value:=items->-1->>'run_id';EXIT;END IF;
   items:=items||jsonb_build_array(zasp_ordered_public62.project(o,w,e,item.run_id));
  END LOOP;
  result_value:=jsonb_build_object('contract_version',62,'items',items,'next_after_run_id',next_value);
 ELSIF op='activate' THEN
  PERFORM 1 FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,q->>'definition_id') FOR UPDATE;
  d:=zasp_ordered_public62.definition(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint,false);
  IF d.version>=1000000 OR NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered activation changed';END IF;
  UPDATE public.zasp_security_agent_definitions SET activation='supervised',version=version+1,body=body||jsonb_build_object('enabled',true),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d.definition_id) RETURNING * INTO d;
  INSERT INTO public.zasp_security_agent_definition_versions(organization_id,workspace_id,environment_id,definition_id,version,activation,definition,definition_digest,actor_id) VALUES(o,w,e,d.definition_id,d.version,'supervised',d.body,digest(convert_to(d.body::text,'UTF8'),'sha256'),actor);
  result_value:=jsonb_build_object('contract_version',62,'definition_id',d.definition_id,'definition_version',d.version,'activation','supervised');
  a:=public.zasp_discovery_canonical_id(o,w,e,'public62_activation',d.definition_id||chr(31)||d.version::text);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,a,a,actor,'ordered_public_activated',digest(convert_to(result_value::text,'UTF8'),'sha256'),result_value);
 ELSE
  IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR length(q->>'idempotency_key') NOT BETWEEN 16 AND 128 OR (q->>'idempotency_key')!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered idempotency rejected';END IF;
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key') FOR SHARE;
  IF FOUND THEN
   IF prior.intent IS DISTINCT FROM q OR prior.intent_digest IS DISTINCT FROM digest(convert_to(q::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
   IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,requested_by)=(o,w,e,prior.resource_id,q->>'definition_id',(q->>'definition_version')::bigint,actor)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered replay unavailable';END IF;
   r:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',(q->>'definition_id')||chr(31)||(q->>'trigger_id')||chr(31)||(q->>'trigger_version'));
   result_value:=jsonb_build_object('contract_version',62,'run_id',r,'definition_id',q->>'definition_id','definition_version',(q->>'definition_version')::bigint,'state','queued','version',1);
   IF prior.resource_id IS DISTINCT FROM r OR prior.expected_version IS DISTINCT FROM (q->>'definition_version')::bigint OR prior.response IS DISTINCT FROM result_value
    OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_audit history JOIN public.zasp_security_agent_trigger_receipts tr USING(organization_id,workspace_id,environment_id,run_id)
     JOIN public.zasp_security_agent_definition_versions versioned ON (versioned.organization_id,versioned.workspace_id,versioned.environment_id,versioned.definition_id,versioned.version)=(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint)
     WHERE (history.organization_id,history.workspace_id,history.environment_id,history.run_id,history.actor_id,history.event_kind)=(o,w,e,r,actor,'ordered_public_triggered')
      AND history.audit_id=prior.audit_id AND history.body->'request'=q AND history.body->'response'=result_value AND history.event_digest=digest(convert_to(history.body::text,'UTF8'),'sha256')
      AND history.body->'trigger_digest'=to_jsonb(encode(tr.trigger_digest,'hex')) AND tr.trigger_version=(q->>'trigger_version')::bigint AND tr.trigger_id=q->>'trigger_id'
      AND history.body->'existing_test'=versioned.definition->'existing_test' AND versioned.definition_digest=digest(convert_to(versioned.definition::text,'UTF8'),'sha256')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered replay authority changed';END IF;
  ELSE
   d:=zasp_ordered_public62.definition(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint,true);
   IF d.body->>'trigger_kind'='finding' THEN SELECT to_jsonb(x) INTO evidence FROM public.zasp_risk_findings x WHERE (organization_id,workspace_id,environment_id,id,version,status,rule)=(o,w,e,q->>'trigger_id',(q->>'trigger_version')::bigint,'open',d.body->>'trigger_source') FOR SHARE;
   ELSE SELECT to_jsonb(x) INTO evidence FROM public.zasp_risk_attack_paths x WHERE (organization_id,workspace_id,environment_id,id,version,state)=(o,w,e,q->>'trigger_id',(q->>'trigger_version')::bigint,d.body->>'trigger_source') AND state IN('observed','verified') AND public.zasp_risk_attack_path_valid(x) FOR SHARE;END IF;
   IF evidence IS NULL OR octet_length(evidence::text)>65536 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
   r:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',d.definition_id||chr(31)||(q->>'trigger_id')||chr(31)||(q->>'trigger_version'));
   a:=public.zasp_discovery_canonical_id(o,w,e,'public62_trigger',r);receipt_id:=public.zasp_discovery_canonical_id(o,w,e,'public62_receipt',actor||chr(31)||(q->>'idempotency_key'));
   IF NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger changed';END IF;
   INSERT INTO public.zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(o,w,e,r,d.definition_id,d.version,q->>'trigger_id',actor,'queued');
   INSERT INTO public.zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(o,w,e,d.definition_id,q->>'trigger_id',d.body->>'trigger_kind',(q->>'trigger_version')::bigint,digest(convert_to(evidence::text,'UTF8'),'sha256'),r);
   PERFORM zasp_sa_multistep_prior.context(o,w,e,r);
   result_value:=jsonb_build_object('contract_version',62,'run_id',r,'definition_id',d.definition_id,'definition_version',d.version,'state','queued','version',1);
   audit_body:=jsonb_build_object('request',q,'response',result_value,'trigger_digest',encode(digest(convert_to(evidence::text,'UTF8'),'sha256'),'hex'),'existing_test',d.body->'existing_test','definition_digest',encode(digest(convert_to(d.body::text,'UTF8'),'sha256'),'hex'));
   INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,a,a,r,actor,'ordered_public_triggered',digest(convert_to(audit_body::text,'UTF8'),'sha256'),audit_body);
   INSERT INTO public.zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key',r,d.version,q,digest(convert_to(q::text,'UTF8'),'sha256'),result_value,a,a,receipt_id);
  END IF;
 END IF;
 IF op='trigger' THEN PERFORM zasp_ordered_public62.history(o,w,e,r);END IF;
 IF result_value IS NULL OR octet_length(result_value::text)>65536 OR NOT zasp_ordered_public62.ready(c,f) OR NOT public.zasp_security_agent_principal_ready('zasp_security_agent_api') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered authority changed';END IF;
 IF op IN('decide_resource','decide') OR(op='classify' AND q->>'resource_kind'='approval') THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,false);END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.authorize(o text, w text, e text, actor text, write_value boolean)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE membership public.zasp_identity_memberships%ROWTYPE;scope_row public.zasp_authorized_scopes%ROWTYPE;
BEGIN
 SELECT * INTO membership FROM public.zasp_identity_memberships WHERE (organization_id,principal_id)=(o,actor) FOR SHARE NOWAIT;
 scope_row:=zasp_sa_multistep_prior.lock_scope(o,w,e,actor);
 IF membership.principal_id IS NULL OR NOT membership.active OR scope_row.principal_id IS NULL
  OR NOT COALESCE(public.zasp_effective_scope_permissions(scope_row.permissions,membership.role) ?& CASE WHEN write_value THEN ARRAY['view','manage_workflows','run_tests'] ELSE ARRAY['view'] END,false) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.candidates(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';op text:=q->>'operation';
 filter_value text:=q->>'resource_filter';state_value text:=q->>'state_filter';before_value timestamptz;limit_value integer;items_value jsonb;next_time text:='';next_id text:='';k text;
BEGIN
 FOREACH k IN ARRAY ARRAY['resource_filter','state_filter','before_created_at','before_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public candidate page rejected';END IF;
 END LOOP;
 IF jsonb_typeof(q->'limit') IS DISTINCT FROM 'number' OR NOT COALESCE(q->>'limit'~'^([1-9][0-9]?|100)$',false)
  OR filter_value<>'' AND NOT COALESCE(public.zasp_valid_product_id(filter_value),false)
  OR (q->>'before_created_at'='')<>(q->>'before_id'='')
  OR q->>'before_id'<>'' AND NOT COALESCE(public.zasp_valid_product_id(q->>'before_id'),false)
  OR state_value<>'' AND (op='run_candidates' AND state_value NOT IN('queued','planning','waiting_approval','running','verifying','contained','remediated','needs_human','failed','inconclusive','cancelled')
   OR op='approval_candidates' AND state_value NOT IN('pending','approved','rejected','cancelled','expired')) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public candidate page rejected';END IF;
 limit_value:=(q->>'limit')::integer;
 IF q->>'before_created_at'<>'' THEN
  IF q->>'before_created_at'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}\.[0-9]{6}Z$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public candidate cursor rejected';END IF;
  BEGIN before_value:=(q->>'before_created_at')::timestamptz;EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public candidate cursor rejected';END;
  IF to_char(before_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')<>q->>'before_created_at' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public candidate cursor rejected';END IF;
 END IF;
 WITH candidates AS MATERIALIZED (
  SELECT x.run_id AS id,x.created_at FROM public.zasp_security_agent_runs x
   WHERE op='run_candidates' AND (x.organization_id,x.workspace_id,x.environment_id)=(o,w,e) AND x.state<>'simulated'
   AND (filter_value='' OR x.definition_id=filter_value) AND (state_value='' OR x.state=state_value)
   AND (before_value IS NULL OR (x.created_at,x.run_id)<(before_value,q->>'before_id'))
  UNION ALL
  SELECT x.approval_id AS id,x.created_at FROM public.zasp_security_agent_approvals x
   JOIN public.zasp_security_agent_runs r ON (r.organization_id,r.workspace_id,r.environment_id,r.run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)
   WHERE op='approval_candidates' AND (x.organization_id,x.workspace_id,x.environment_id)=(o,w,e)
   AND (filter_value='' OR x.run_id=filter_value) AND (state_value='' OR x.state=state_value)
   AND (before_value IS NULL OR (x.created_at,x.approval_id)<(before_value,q->>'before_id'))
  ORDER BY created_at DESC,id DESC LIMIT limit_value+1
 ), numbered AS (SELECT *,row_number() OVER(ORDER BY created_at DESC,id DESC) AS ordinal FROM candidates)
 SELECT COALESCE(jsonb_agg(jsonb_build_object('id',id,'created_at',to_char(created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) ORDER BY created_at DESC,id DESC) FILTER(WHERE ordinal<=limit_value),'[]'::jsonb),
  COALESCE(max(to_char(created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')) FILTER(WHERE ordinal=limit_value AND (SELECT count(*) FROM candidates)>limit_value),''),
  COALESCE(max(id) FILTER(WHERE ordinal=limit_value AND (SELECT count(*) FROM candidates)>limit_value),'')
 INTO items_value,next_time,next_id FROM numbered;
 RETURN jsonb_build_object('contract_version',62,'organization_id',o,'workspace_id',w,'environment_id',e,'operation',op,'items',items_value,'next_created_at',next_time,'next_id',next_id);
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.classify(o text, w text, e text, kind text, rid text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d public.zasp_security_agent_definitions%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;
 rr public.zasp_security_agent_runs%ROWTYPE;a public.zasp_security_agent_approvals%ROWTYPE;
 trigger_audit public.zasp_security_agent_audit%ROWTYPE;did text;r text;claimed boolean;approval_claimed boolean:=false;proof record;
BEGIN
 IF kind='definition' THEN did:=rid;
 ELSE
  IF kind='approval' THEN
   SELECT * INTO a FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,approval_id)=(o,w,e,rid);
   -- Retained evidence belongs to the requested ID, not its mutable row links.
   FOR proof IN SELECT run_id,step_id FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id)=(o,w,e) AND (
     approval_id=rid AND event_kind='approval_requested' AND body->'contract_version'='61'::jsonb
     OR event_kind IN('ordered_step_ready','ordered_approval_decided','ordered_run_cancelled') AND body->'contract_version'='61'::jsonb AND body->'response'->>'approval_id'=rid
     OR event_kind IN('ordered_public_decide','ordered_public_cancel') AND body->'response'->'contract_version'='62'::jsonb AND body->'response'->>'approval_id'=rid) LOOP
    approval_claimed:=true;
    IF a.approval_id IS NULL OR (a.run_id,a.step_id) IS DISTINCT FROM (proof.run_id,proof.step_id) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
   END LOOP;
   IF a.approval_id IS NULL THEN RETURN 'legacy_or_missing';END IF;
   r:=a.run_id;
  ELSE r:=rid;END IF;
  SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  did:=rr.definition_id;
 END IF;
 SELECT * INTO d FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,did) FOR SHARE;
 -- Definition-wide evidence cannot claim an unrelated historical run version.
 claimed:=approval_claimed OR kind='definition' AND (COALESCE(d.body->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb,false)
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,did) AND definition->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb)
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id)=(o,w,e) AND (event_kind='ordered_public_activated' AND body->>'definition_id'=did OR event_kind IN('ordered_public_triggered','ordered_public_activation_receipted') AND body->'request'->>'definition_id'=did))
  OR EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,did)))
  OR kind<>'definition' AND EXISTS(SELECT 1 FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,did,rr.definition_version) AND definition->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb)
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'ordered_public_triggered'))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,operation,resource_id)=(o,w,e,'runSecurityAgent',r) AND response->'contract_version'='62'::jsonb)
  OR EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR kind='approval' AND EXISTS(SELECT 1 FROM public.zasp_security_agent_steps s JOIN public.zasp_sa_multistep_runs m USING(organization_id,workspace_id,environment_id,run_id) WHERE (s.organization_id,s.workspace_id,s.environment_id,s.step_id)=(o,w,e,a.step_id));
 IF NOT claimed THEN RETURN 'legacy_or_missing';END IF;
 IF kind='definition' THEN
 IF d.definition_id IS NULL OR d.deleted_at IS NOT NULL OR d.activation NOT IN('draft','supervised') OR d.version NOT BETWEEN 1 AND 1000000 OR d.definition_version NOT BETWEEN 1 AND 1000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered definition unavailable';END IF;
 -- Ownership persists after execution revocation; activation/trigger alone
 -- require the stricter live control, target and credential checks.
 BEGIN
  PERFORM zasp_ordered_public62.definition_shape(d,e,d.activation='supervised');
 EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE '42501' THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered persisted definition unavailable';
 END;
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,did,d.version) FOR SHARE;
 IF (d.activation='supervised' AND h.definition_id IS NULL) OR (h.definition_id IS NOT NULL AND (h.activation IS DISTINCT FROM d.activation OR h.definition IS DISTINCT FROM d.body OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered definition history unavailable';END IF;
 ELSE
  -- Runs and approvals retain the immutable version pinned at public trigger;
  -- later current-definition revisions or deletion cannot erase ownership.
  IF rr.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered run unavailable';END IF;
  IF EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN
   PERFORM zasp_sa_multistep_prior.cleanup_lock(o,w,e,r);
   PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,false);
   PERFORM zasp_ordered_public62.history(o,w,e,r);
   IF EXISTS(SELECT 1 FROM public.zasp_security_agent_steps s WHERE (s.organization_id,s.workspace_id,s.environment_id,s.run_id)=(o,w,e,r)
    AND (s.step_index=0 OR s.state IN('waiting_approval','authorized','executing','verifying','succeeded')
     OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id)=(o,w,e,r,s.step_id) AND x.body->'response'->>'approval_id'=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_approval',r||chr(31)||s.step_id)))
    AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_approvals x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id)=(o,w,e,r,s.step_id))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered required approval unavailable';END IF;
  ELSE PERFORM zasp_ordered_public62.project(o,w,e,r);END IF;
  SELECT * INTO trigger_audit FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'ordered_public_triggered');
  IF NOT zasp_sa_multistep_prior.closed(trigger_audit.body,ARRAY['request','response','trigger_digest','existing_test','definition_digest'])
   OR NOT zasp_sa_multistep_prior.closed(trigger_audit.body->'request',ARRAY['organization_id','workspace_id','environment_id','actor_id','operation','definition_id','definition_version','trigger_id','trigger_version','idempotency_key'])
   OR trigger_audit.body->'request'->>'operation' IS DISTINCT FROM 'trigger' OR trigger_audit.correlation_id IS DISTINCT FROM trigger_audit.audit_id
   OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_request_receipts x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.principal_id,x.operation,x.resource_id,x.audit_id,x.correlation_id)=(o,w,e,rr.requested_by,'runSecurityAgent',r,trigger_audit.audit_id,trigger_audit.audit_id)
    AND x.intent=trigger_audit.body->'request' AND x.idempotency_key=x.intent->>'idempotency_key'
    AND x.receipt_id=public.zasp_discovery_canonical_id(o,w,e,'public62_receipt',rr.requested_by||chr(31)||x.idempotency_key)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger identity unavailable';END IF;
  IF kind='approval' AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_steps s WHERE (s.organization_id,s.workspace_id,s.environment_id,s.run_id,s.step_id)=(o,w,e,r,a.step_id)
   AND s.step_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_step',r||chr(31)||s.step_index::text)
   AND a.approval_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_approval',r||chr(31)||s.step_id)
   AND s.step_index IN(0,1)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
 END IF;
 RETURN 'ordered_release61';
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.classify_mutation(o text, w text, e text, actor text, kind text, did text, key_value text, tid text, tv bigint)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior public.zasp_security_agent_request_receipts%ROWTYPE;proof public.zasp_security_agent_audit%ROWTYPE;
 h public.zasp_security_agent_definition_versions%ROWTYPE;d public.zasp_security_agent_definitions%ROWTYPE;
 stored_op text;intent_op text;event_value text;a text;receipt text;v bigint;claimed boolean;keys text[];requested_run text;
BEGIN
 IF kind NOT IN('activate','trigger') OR key_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation classification rejected';END IF;
 IF kind='activate' AND (tid IS NOT NULL OR tv IS NOT NULL) OR kind='trigger' AND NOT COALESCE(public.zasp_valid_product_id(did) AND public.zasp_valid_product_id(tid) AND tv BETWEEN 1 AND 1000000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation trigger identity rejected';END IF;
 stored_op:=CASE WHEN kind='activate' THEN 'activateSecurityAgent' ELSE 'runSecurityAgent' END;
 intent_op:=CASE WHEN kind='activate' THEN 'activate_resource' ELSE 'trigger' END;
 event_value:=CASE WHEN kind='activate' THEN 'ordered_public_activation_receipted' ELSE 'ordered_public_triggered' END;
 SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,stored_op,key_value) FOR SHARE;
 claimed:=EXISTS(SELECT 1 FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,event_kind)=(o,w,e,event_value) AND (actor_id=actor OR body->'request'->>'actor_id'=actor) AND body->'request'->>'idempotency_key'=key_value);
 -- A missing receipt cannot erase an independently retained canonical claim.
 -- Activation's ID binds actor/key directly; trigger's does not, so its
 -- retained proof must still link this actor AND this exact key.
 IF kind='activate' THEN
  a:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_audit',actor||chr(31)||'activate_resource'||chr(31)||key_value);
  SELECT * INTO proof FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,a) FOR SHARE;
  claimed:=claimed OR proof.audit_id IS NOT NULL;
 ELSE
  requested_run:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',did||chr(31)||tid||chr(31)||tv::text);
  a:=public.zasp_discovery_canonical_id(o,w,e,'public62_trigger',requested_run);
  claimed:=claimed OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit marker WHERE (marker.organization_id,marker.workspace_id,marker.environment_id)=(o,w,e)
   AND jsonb_typeof(marker.body->'request'->'idempotency_key')='string' AND marker.body->'request'->>'idempotency_key'=key_value
   AND (marker.actor_id=actor OR marker.body->'request'->>'actor_id'=actor OR EXISTS(SELECT 1 FROM public.zasp_security_agent_runs rr WHERE (rr.organization_id,rr.workspace_id,rr.environment_id,rr.run_id,rr.requested_by)=(o,w,e,requested_run,actor)))
   AND (marker.audit_id=a OR marker.run_id=requested_run AND (EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,requested_run))
    OR EXISTS(SELECT 1 FROM public.zasp_security_agent_runs rr JOIN public.zasp_security_agent_definition_versions history_row ON (history_row.organization_id,history_row.workspace_id,history_row.environment_id,history_row.definition_id,history_row.version)=(rr.organization_id,rr.workspace_id,rr.environment_id,rr.definition_id,rr.definition_version) WHERE (rr.organization_id,rr.workspace_id,rr.environment_id,rr.run_id)=(o,w,e,requested_run) AND history_row.definition->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb))));
 END IF;
 IF prior.receipt_id IS NULL THEN
  IF claimed THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation receipt unavailable';END IF;
  RETURN zasp_ordered_public62.classify(o,w,e,'definition',did);
 END IF;
 -- Canonical persisted identities are claims even when all descriptive tags
 -- have been damaged. Recognizing a claim only forces validation below.
 IF NOT COALESCE(public.zasp_valid_product_id(prior.resource_id) AND public.zasp_valid_product_id(prior.receipt_id) AND public.zasp_valid_product_id(prior.audit_id) AND public.zasp_valid_product_id(prior.correlation_id),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation identities unavailable';END IF;
 IF kind='activate' THEN
  a:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_audit',actor||chr(31)||'activate_resource'||chr(31)||key_value);
  receipt:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_receipt',actor||chr(31)||'activate_resource'||chr(31)||key_value);
  claimed:=claimed OR COALESCE(prior.response->>'audit_id'=a OR prior.response->>'correlation_id'=a OR prior.response->>'receipt_id'=receipt,false);
 ELSE
  -- The ordered trigger wire retains run_id, not legacy's id field. A
  -- malformed retained claim refuses; it cannot erase ordered provenance.
  IF prior.response ? 'run_id' THEN
   IF jsonb_typeof(prior.response->'run_id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(prior.response->>'run_id'),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation response identity unavailable';END IF;
   claimed:=true;
  END IF;
  a:=public.zasp_discovery_canonical_id(o,w,e,'public62_trigger',prior.resource_id);
  receipt:=public.zasp_discovery_canonical_id(o,w,e,'public62_receipt',actor||chr(31)||key_value);
  claimed:=claimed
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_runs rr JOIN public.zasp_security_agent_definition_versions history_row ON (history_row.organization_id,history_row.workspace_id,history_row.environment_id,history_row.definition_id,history_row.version)=(rr.organization_id,rr.workspace_id,rr.environment_id,rr.definition_id,rr.definition_version) WHERE (rr.organization_id,rr.workspace_id,rr.environment_id,rr.run_id)=(o,w,e,prior.resource_id) AND history_row.definition->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb)
   OR EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,prior.resource_id))
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,prior.resource_id,event_value));
 END IF;
 SELECT * INTO proof FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,a) FOR SHARE;
 claimed:=claimed OR prior.audit_id=a OR prior.correlation_id=a OR prior.receipt_id=receipt OR proof.audit_id IS NOT NULL;
 IF NOT claimed AND prior.response->'contract_version' IS DISTINCT FROM '62'::jsonb AND prior.intent->>'operation' IS DISTINCT FROM intent_op THEN RETURN zasp_ordered_public62.classify(o,w,e,'definition',did);END IF;
 keys:=ARRAY['organization_id','workspace_id','environment_id','actor_id','operation','definition_id','definition_version','idempotency_key'];
 keys:=keys||CASE WHEN kind='activate' THEN ARRAY['activation'] ELSE ARRAY['trigger_id','trigger_version'] END;
 IF NOT zasp_sa_multistep_prior.closed(prior.intent,keys)
  OR jsonb_typeof(prior.intent->'idempotency_key') IS DISTINCT FROM 'string'
  OR (prior.intent->>'organization_id',prior.intent->>'workspace_id',prior.intent->>'environment_id',prior.intent->>'actor_id',prior.intent->>'operation',prior.intent->>'idempotency_key') IS DISTINCT FROM (o,w,e,actor,intent_op,key_value)
  OR jsonb_typeof(prior.intent->'definition_id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(prior.intent->>'definition_id'),false)
  OR jsonb_typeof(prior.intent->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(prior.intent->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
  OR prior.intent_digest IS DISTINCT FROM digest(convert_to(prior.intent::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation intent unavailable';END IF;
 v:=(prior.intent->>'definition_version')::bigint;
 IF prior.expected_version IS DISTINCT FROM v THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation version unavailable';END IF;
 IF kind='activate' THEN
  SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,prior.intent->>'definition_id',v+1) FOR SHARE;
  IF v>=1000000 OR prior.intent->>'activation' IS DISTINCT FROM 'supervised' OR prior.resource_id IS DISTINCT FROM prior.intent->>'definition_id'
   OR (prior.audit_id,prior.correlation_id,prior.receipt_id) IS DISTINCT FROM (a,a,receipt)
   OR prior.response IS DISTINCT FROM jsonb_build_object('contract_version',62,'id',prior.resource_id,'activation','supervised','enabled',true,'version',v+1,'audit_id',a,'correlation_id',a,'receipt_id',receipt,'replayed',false)
   OR (proof.event_kind,proof.actor_id,proof.correlation_id) IS DISTINCT FROM (event_value,actor,a) OR proof.run_id IS NOT NULL OR proof.step_id IS NOT NULL
   OR proof.body IS DISTINCT FROM jsonb_build_object('request',prior.intent,'response',prior.response,'definition_digest',encode(h.definition_digest,'hex')) OR proof.event_digest IS DISTINCT FROM digest(convert_to(proof.body::text,'UTF8'),'sha256')
   OR h.definition_id IS NULL OR h.activation IS DISTINCT FROM 'supervised' OR h.actor_id IS DISTINCT FROM actor OR h.definition_digest IS DISTINCT FROM digest(convert_to(h.definition::text,'UTF8'),'sha256')
   OR jsonb_typeof(h.definition->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(h.definition->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
   THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered activation ownership unavailable';END IF;
  d.definition_id:=h.definition_id;d.activation:=h.activation;d.body:=h.definition;d.definition_version:=(h.definition->>'definition_version')::bigint;d.plan_catalog_version:='security-agent-actions-v1';
  BEGIN PERFORM zasp_ordered_public62.definition_shape(d,e,true);
  EXCEPTION WHEN SQLSTATE '22023' OR SQLSTATE '42501' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered activation snapshot unavailable';END;
 ELSE
  IF (prior.audit_id,prior.correlation_id,prior.receipt_id) IS DISTINCT FROM (a,a,receipt)
   OR NOT zasp_sa_multistep_prior.closed(proof.body,ARRAY['request','response','trigger_digest','existing_test','definition_digest'])
   OR (proof.event_kind,proof.actor_id,proof.correlation_id,proof.run_id) IS DISTINCT FROM (event_value,actor,a,prior.resource_id)
   OR proof.body->'request' IS DISTINCT FROM prior.intent OR proof.body->'response' IS DISTINCT FROM prior.response
   OR jsonb_typeof(prior.intent->'trigger_id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(prior.intent->>'trigger_id'),false)
   OR jsonb_typeof(prior.intent->'trigger_version') IS DISTINCT FROM 'number' OR NOT COALESCE(prior.intent->>'trigger_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
   OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,requested_by)=(o,w,e,prior.resource_id,prior.intent->>'definition_id',v,actor)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger ownership unavailable';END IF;
  PERFORM zasp_ordered_public62.history(o,w,e,prior.resource_id);
 END IF;
 RETURN 'ordered_release61';
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.classify_trigger_key(o text, w text, e text, actor text, did text, key_value text)
 RETURNS text
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior public.zasp_security_agent_request_receipts%ROWTYPE;proof public.zasp_security_agent_audit%ROWTYPE;
 claimed boolean;receipt text;a text;family text;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(did),false) OR key_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered trigger classification rejected';END IF;
 receipt:=public.zasp_discovery_canonical_id(o,w,e,'public62_receipt',actor||chr(31)||key_value);
 SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',key_value) FOR SHARE;
 claimed:=EXISTS(SELECT 1 FROM public.zasp_security_agent_request_receipts x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.principal_id,x.receipt_id)=(o,w,e,actor,receipt))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit x WHERE (x.organization_id,x.workspace_id,x.environment_id)=(o,w,e)
   AND x.body->'request'->>'idempotency_key'=key_value
   AND ((x.actor_id=actor OR x.body->'request'->>'actor_id'=actor)
    AND (x.event_kind='ordered_public_triggered' OR x.body->'request'->>'operation'='trigger'
     AND zasp_sa_multistep_prior.closed(x.body->'request',ARRAY['organization_id','workspace_id','environment_id','actor_id','operation','definition_id','definition_version','trigger_id','trigger_version','idempotency_key']))
    OR CASE WHEN public.zasp_valid_product_id(x.run_id) THEN x.audit_id=public.zasp_discovery_canonical_id(o,w,e,'public62_trigger',x.run_id) ELSE false END
     AND EXISTS(SELECT 1 FROM public.zasp_security_agent_runs rr WHERE (rr.organization_id,rr.workspace_id,rr.environment_id,rr.run_id,rr.requested_by)=(o,w,e,x.run_id,actor))));
 IF prior.receipt_id IS NULL THEN
  IF claimed THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger receipt unavailable';END IF;
  RETURN zasp_ordered_public62.classify(o,w,e,'definition',did);
 END IF;
 IF octet_length(prior.intent::text)>16384 OR octet_length(prior.response::text)>16384
  OR NOT COALESCE(public.zasp_valid_product_id(prior.resource_id) AND public.zasp_valid_product_id(prior.audit_id) AND public.zasp_valid_product_id(prior.correlation_id) AND public.zasp_valid_product_id(prior.receipt_id),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger identities unavailable';END IF;
 a:=public.zasp_discovery_canonical_id(o,w,e,'public62_trigger',prior.resource_id);
 claimed:=claimed OR prior.audit_id=a OR prior.correlation_id=a OR prior.receipt_id=receipt OR prior.response ? 'run_id' OR prior.response ? 'contract_version' OR prior.intent ? 'operation'
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.audit_id)=(o,w,e,a))
  OR EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.run_id)=(o,w,e,prior.resource_id));
 IF claimed THEN
  IF NOT zasp_sa_multistep_prior.closed(prior.intent,ARRAY['organization_id','workspace_id','environment_id','actor_id','operation','definition_id','definition_version','trigger_id','trigger_version','idempotency_key'])
   OR jsonb_typeof(prior.intent->'trigger_id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(prior.intent->>'trigger_id'),false)
   OR jsonb_typeof(prior.intent->'trigger_version') IS DISTINCT FROM 'number' OR NOT COALESCE(prior.intent->>'trigger_version'~'^([1-9][0-9]{0,5}|1000000)$',false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger intent unavailable';END IF;
  family:=zasp_ordered_public62.classify_mutation(o,w,e,actor,'trigger',did,key_value,prior.intent->>'trigger_id',(prior.intent->>'trigger_version')::bigint);
  IF family IS DISTINCT FROM 'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger ownership unavailable';END IF;
  RETURN family;
 END IF;
 -- Only the authentic legacy contract can select legacy. Partial erasure is
 -- not a negative ownership proof, even when current definition is legacy.
 IF NOT zasp_sa_multistep_prior.closed(prior.intent,ARRAY['definition_id','expected_version','trigger_kind','trigger_id'])
  OR prior.resource_id IS DISTINCT FROM did OR prior.intent->'definition_id' IS DISTINCT FROM to_jsonb(did)
  OR prior.intent->'expected_version' IS DISTINCT FROM to_jsonb(prior.expected_version) OR prior.expected_version NOT BETWEEN 1 AND 1000000
  OR prior.intent->>'trigger_kind' NOT IN('finding','session') OR jsonb_typeof(prior.intent->'trigger_kind') IS DISTINCT FROM 'string'
  OR jsonb_typeof(prior.intent->'trigger_id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(prior.intent->>'trigger_id'),false)
  OR prior.intent_digest IS DISTINCT FROM digest(convert_to(prior.intent::text,'UTF8'),'sha256') OR NOT isfinite(prior.expires_at) OR prior.expires_at<=clock_timestamp()
  OR NOT zasp_sa_multistep_prior.closed(prior.response,ARRAY['id','agent_id','state','evidence_ids','definition_version','version','audit_id','correlation_id','receipt_id','replayed'])
  OR jsonb_typeof(prior.response->'id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(prior.response->>'id'),false)
  OR jsonb_typeof(prior.response->'version') IS DISTINCT FROM 'number' OR NOT COALESCE(prior.response->>'version'~'^([1-9][0-9]{0,5}|1000000)$',false)
  OR jsonb_typeof(prior.response->'replayed') IS DISTINCT FROM 'boolean' OR prior.response->>'state' NOT IN('queued','planning','waiting_approval','running','verifying','contained','remediated','needs_human','failed','inconclusive','cancelled')
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered legacy intent unavailable';END IF;
 IF prior.response IS DISTINCT FROM jsonb_build_object('id',prior.response->>'id','agent_id',did,'state',prior.response->>'state','evidence_ids',jsonb_build_array(prior.intent->>'trigger_id'),'definition_version',prior.expected_version,'version',(prior.response->>'version')::bigint,'audit_id',prior.audit_id,'correlation_id',prior.correlation_id,'receipt_id',prior.receipt_id,'replayed',prior.response->'replayed')
  OR prior.audit_id=prior.correlation_id OR prior.audit_id=prior.receipt_id OR prior.correlation_id=prior.receipt_id THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered legacy response unavailable';END IF;
 SELECT * INTO proof FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,prior.audit_id) FOR SHARE;
 IF prior.intent->>'trigger_kind'='session' AND (
  jsonb_typeof(proof.body->'trigger_version') IS DISTINCT FROM 'number' OR NOT COALESCE(proof.body->>'trigger_version'~'^[1-9][0-9]{0,18}$',false)
  OR proof.body->'trigger_version'>'9223372036854775807'::jsonb
  OR jsonb_typeof(proof.body->'device_id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(proof.body->>'device_id'),false)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered legacy session proof unavailable';END IF;
 IF proof.event_kind NOT IN('run_queued','run_deduplicated') OR proof.audit_id IS NULL
  OR NOT zasp_sa_multistep_prior.closed(proof.body,ARRAY['run_id','definition_id','definition_version','trigger_kind','trigger_id']||CASE WHEN prior.intent->>'trigger_kind'='session' THEN ARRAY['trigger_version','device_id'] ELSE ARRAY[]::text[] END)
  OR (proof.actor_id,proof.correlation_id,proof.run_id) IS DISTINCT FROM (actor,prior.correlation_id,prior.response->>'id')
  OR proof.body->'run_id' IS DISTINCT FROM prior.response->'id' OR proof.body->'definition_id' IS DISTINCT FROM to_jsonb(did) OR proof.body->'definition_version' IS DISTINCT FROM to_jsonb(prior.expected_version)
  OR proof.body->'trigger_id' IS DISTINCT FROM prior.intent->'trigger_id' OR proof.body->>'trigger_kind' IS DISTINCT FROM (CASE WHEN prior.intent->>'trigger_kind'='session' THEN 'runtime_decision' ELSE 'finding' END)
  OR prior.response->'replayed' IS DISTINCT FROM to_jsonb(proof.event_kind='run_deduplicated')
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_runs rr JOIN public.zasp_security_agent_trigger_receipts tr ON (tr.organization_id,tr.workspace_id,tr.environment_id,tr.run_id,tr.definition_id,tr.trigger_id)=(rr.organization_id,rr.workspace_id,rr.environment_id,rr.run_id,rr.definition_id,rr.trigger_id)
   WHERE (rr.organization_id,rr.workspace_id,rr.environment_id,rr.run_id,rr.definition_id,rr.trigger_id)=(o,w,e,prior.response->>'id',did,prior.intent->>'trigger_id')
    AND (proof.event_kind='run_deduplicated' OR rr.definition_version=prior.expected_version) AND tr.trigger_digest=proof.event_digest AND tr.trigger_kind=proof.body->>'trigger_kind'
    AND (prior.intent->>'trigger_kind'<>'session' OR proof.body->'trigger_version'=to_jsonb(tr.trigger_version)
     AND EXISTS(SELECT 1 FROM public.zasp_runtime_gateway_events event WHERE (event.organization_id,event.workspace_id,event.environment_id,event.classification->>'session_id',event.device_id,event.sequence)=(o,w,e,tr.trigger_id,proof.body->>'device_id',tr.trigger_version)
      AND tr.trigger_digest=digest(convert_to(jsonb_build_object('kind','runtime_decision','session_id',tr.trigger_id,'device_id',event.device_id,'event_id',event.event_id,'sequence',event.sequence,'request_digest','sha256:'||encode(event.request_digest,'hex'))::text,'UTF8'),'sha256'))))
  OR zasp_ordered_public62.classify(o,w,e,'run',prior.response->>'id') IS DISTINCT FROM 'legacy_or_missing' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered legacy proof unavailable';END IF;
 RETURN 'legacy_or_missing';
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.definition(o text, w text, e text, did text, v bigint, enabled_value boolean)
 RETURNS public.zasp_security_agent_definitions
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d public.zasp_security_agent_definitions%ROWTYPE;t public.zasp_red_team_definitions%ROWTYPE;c public.zasp_attack_lab_credential_bindings%ROWTYPE;
 b jsonb;reference jsonb;target jsonb;class_value text;
BEGIN
 SELECT * INTO d FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,did,v) AND deleted_at IS NULL FOR SHARE;
 PERFORM zasp_ordered_public62.definition_shape(d,e,enabled_value);
 b:=d.body;reference:=b->'existing_test';
 PERFORM 1 FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*','create_temporary_policy','run_test') ORDER BY organization_id,workspace_id,environment_id,action_key FOR SHARE;
 IF (SELECT count(*)<>4 OR NOT COALESCE(bool_and(execution_enabled),false) FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*','create_temporary_policy','run_test')) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public ordered execution disabled';END IF;
 SELECT * INTO t FROM public.zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,enabled)=(o,w,e,reference->>'definition_id',(reference->>'definition_version')::bigint,true) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
 class_value:=public.zasp_production_security_agent_run_context_lock_env(o,w,e);
 target:=public.zasp_production_security_agent_run_context_lock_target(o,w,e,t.target_id);
 SELECT * INTO c FROM public.zasp_attack_lab_credential_bindings WHERE (organization_id,workspace_id,environment_id,target_id,credential_reference,state)=(o,w,e,t.target_id,target->'attributes'->'red_team'->>'credential_reference','active') AND credential_class=t.safety->>'credential_class' FOR SHARE;
 IF NOT FOUND OR NOT COALESCE(class_value IN('development','test','staging') AND class_value=t.safety->>'environment' AND target->>'state'='active'
  AND (target->>'fresh_until')::timestamptz>clock_timestamp() AND c.valid_until>clock_timestamp()
  AND public.zasp_red_team_safety_authorized(o,w,e,t.target_id,t.target_kind,t.safety),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
 RETURN d;
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.history(o text, w text, e text, r text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rr public.zasp_security_agent_runs%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;
 tr public.zasp_security_agent_trigger_receipts%ROWTYPE;a public.zasp_security_agent_audit%ROWTYPE;b jsonb;ref jsonb;k text;
BEGIN
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,rr.definition_id,rr.definition_version) FOR SHARE;
 b:=h.definition;ref:=b->'existing_test';
 IF h.definition_id IS NULL OR h.activation IS DISTINCT FROM 'supervised' OR h.definition_digest IS DISTINCT FROM digest(convert_to(b::text,'UTF8'),'sha256') OR octet_length(b::text)>16384
  OR NOT zasp_sa_multistep_prior.closed(b,ARRAY['id','name','trigger_kind','trigger_source','environment_ids','autonomy','max_steps','max_duration_seconds','temporary_policy_seconds','ai_token_budget','max_ai_cost_nano_credits','concurrency_limit','allowed_actions','verification_kind','definition_version','enabled','existing_test'])
  OR b->>'id' IS DISTINCT FROM rr.definition_id OR b->'enabled' IS DISTINCT FROM 'true'::jsonb OR b->'allowed_actions' IS DISTINCT FROM '["create_temporary_policy","run_test"]'::jsonb
  OR b->'environment_ids' IS DISTINCT FROM jsonb_build_array(e) OR b->>'autonomy' IS DISTINCT FROM 'supervised' OR b->'max_steps' IS DISTINCT FROM '2'::jsonb OR b->>'verification_kind' IS DISTINCT FROM 'test_run'
  OR jsonb_typeof(b->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(b->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false)
  OR b->>'trigger_kind' NOT IN('finding','attack_path') OR b->>'trigger_kind'='attack_path' AND b->>'trigger_source' NOT IN('observed','verified')
  OR NOT zasp_sa_multistep_prior.closed(ref,ARRAY['definition_id','definition_version']) OR jsonb_typeof(ref->'definition_id') IS DISTINCT FROM 'string'
  OR NOT COALESCE(public.zasp_valid_product_id(ref->>'definition_id'),false) OR ref->>'definition_id' IN(e,rr.definition_id)
  OR jsonb_typeof(ref->'definition_version') IS DISTINCT FROM 'number' OR NOT COALESCE(ref->>'definition_version'~'^([1-9][0-9]{0,5}|1000000)$',false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered history unavailable';END IF;
 FOREACH k IN ARRAY ARRAY['name','trigger_kind','trigger_source'] LOOP
  IF jsonb_typeof(b->k) IS DISTINCT FROM 'string' OR length(btrim(b->>k)) NOT BETWEEN 1 AND 128 OR (b->>k)~'[[:cntrl:]]' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered historical text unavailable';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['max_duration_seconds','temporary_policy_seconds','ai_token_budget','max_ai_cost_nano_credits','concurrency_limit'] LOOP
  IF jsonb_typeof(b->k) IS DISTINCT FROM 'number' OR (b->>k)!~'^[1-9][0-9]{0,12}$' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered historical limits unavailable';END IF;
 END LOOP;
 IF (b->>'max_duration_seconds')::bigint NOT BETWEEN 1 AND 86400 OR (b->>'temporary_policy_seconds')::bigint NOT BETWEEN 60 AND 3600 OR (b->>'ai_token_budget')::bigint NOT BETWEEN 1 AND 12000
  OR (b->>'max_ai_cost_nano_credits')::bigint NOT BETWEEN 1 AND 1000000000000 OR (b->>'concurrency_limit')::bigint NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered historical limits unavailable';END IF;
 SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(o,w,e,r,rr.definition_id,rr.trigger_id) FOR SHARE;
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'ordered_public_triggered');
 IF tr.run_id IS NULL OR tr.trigger_kind IS DISTINCT FROM b->>'trigger_kind' OR r IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',rr.definition_id||chr(31)||rr.trigger_id||chr(31)||tr.trigger_version::text)
  OR (SELECT count(*) FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'ordered_public_triggered'))<>1
  OR a.audit_id IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'public62_trigger',r) OR a.actor_id IS DISTINCT FROM rr.requested_by OR a.event_digest IS DISTINCT FROM digest(convert_to(a.body::text,'UTF8'),'sha256')
  OR a.body->>'definition_digest' IS DISTINCT FROM encode(h.definition_digest,'hex') OR a.body->'existing_test' IS DISTINCT FROM ref OR a.body->>'trigger_digest' IS DISTINCT FROM encode(tr.trigger_digest,'hex')
  OR a.body->'request'->>'organization_id' IS DISTINCT FROM o OR a.body->'request'->>'workspace_id' IS DISTINCT FROM w OR a.body->'request'->>'environment_id' IS DISTINCT FROM e OR a.body->'request'->>'actor_id' IS DISTINCT FROM rr.requested_by
  OR a.body->'request'->>'definition_id' IS DISTINCT FROM rr.definition_id OR a.body->'request'->'definition_version' IS DISTINCT FROM to_jsonb(rr.definition_version)
  OR a.body->'request'->>'trigger_id' IS DISTINCT FROM rr.trigger_id OR a.body->'request'->'trigger_version' IS DISTINCT FROM to_jsonb(tr.trigger_version)
  OR a.body->'response' IS DISTINCT FROM jsonb_build_object('contract_version',62,'run_id',r,'definition_id',rr.definition_id,'definition_version',rr.definition_version,'state','queued','version',1)
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_request_receipts x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.principal_id,x.operation,x.resource_id,x.expected_version,x.audit_id)=(o,w,e,rr.requested_by,'runSecurityAgent',r,rr.definition_version,a.audit_id)
   AND x.intent=a.body->'request' AND x.intent_digest=digest(convert_to(x.intent::text,'UTF8'),'sha256') AND x.response=a.body->'response' AND x.idempotency_key=x.intent->>'idempotency_key') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered historical evidence unavailable';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.mutate(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';actor text:=q->>'actor_id';r text:=q->>'run_id';op text:=q->>'operation';
 operation_value text;fresh timestamptz;rr public.zasp_security_agent_runs%ROWTYPE;s public.zasp_security_agent_steps%ROWTYPE;approval public.zasp_security_agent_approvals%ROWTYPE;
 prior public.zasp_security_agent_request_receipts%ROWTYPE;audit_row public.zasp_security_agent_audit%ROWTYPE;transition_row public.zasp_security_agent_audit%ROWTYPE;decision_row public.zasp_security_agent_audit%ROWTYPE;
 audit_id_value text;receipt_id_value text;transition_id text;transition_q jsonb;transition_result jsonb;result_value jsonb;body_value jsonb;projection jsonb;
 admitted boolean;cleanup_value boolean;replayed boolean:=false;keys text[];expected_step_version bigint;phase_value text;expected_phase text;decision_id text;
BEGIN
 IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR length(q->>'idempotency_key') NOT BETWEEN 16 AND 128 OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$'
  OR (q->>'run_version')::bigint>=1000000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation rejected';END IF;
 IF op='decide' THEN
  IF jsonb_typeof(q->'decision') IS DISTINCT FROM 'string' OR q->>'decision' NOT IN('approved','rejected') OR jsonb_typeof(q->'fresh_auth_at') IS DISTINCT FROM 'string'
   OR length(q->>'fresh_auth_at') NOT BETWEEN 20 AND 35 OR q->>'fresh_auth_at'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$' OR (q->>'approval_version')::bigint>=1000000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered decision rejected';END IF;
  fresh:=(q->>'fresh_auth_at')::timestamptz;
  IF fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered decision unavailable';END IF;
 END IF;
 operation_value:=CASE op WHEN 'decide' THEN 'decideSecurityAgentApproval' ELSE 'cancelSecurityAgentRun' END;
 -- Organization admission precedes budget/run, exactly as the private worker.
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 PERFORM 1 FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
 IF op='decide' THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,true);END IF;
 admitted:=EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r));
 IF admitted THEN PERFORM zasp_sa_multistep_prior.cleanup_lock(o,w,e,r);END IF;
 IF admitted AND op='cancel' THEN
  -- Cancellation must remain possible after gateway revocation or expiry.
  -- Validate retained authority here; validate terminal cleanup evidence after
  -- the reviewed transition creates its blocking audit, never live permission.
  PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,false);
  PERFORM zasp_ordered_public62.history(o,w,e,r);
 ELSE projection:=zasp_ordered_public62.project(o,w,e,r);END IF;
 audit_id_value:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_audit',actor||chr(31)||op||chr(31)||(q->>'idempotency_key'));
 receipt_id_value:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_receipt',actor||chr(31)||op||chr(31)||(q->>'idempotency_key'));
 SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,operation_value,q->>'idempotency_key') FOR SHARE;
 IF FOUND THEN
  IF prior.intent IS DISTINCT FROM q OR prior.intent_digest IS DISTINCT FROM digest(convert_to(q::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
  SELECT * INTO audit_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,audit_id_value) FOR SHARE;
  result_value:=prior.response;body_value:=audit_row.body;transition_id:=body_value->>'transition_audit_id';
  IF (prior.resource_id,prior.expected_version,prior.audit_id,prior.correlation_id,prior.receipt_id) IS DISTINCT FROM (r,(q->>'run_version')::bigint,audit_id_value,audit_id_value,receipt_id_value)
   OR (audit_row.run_id,audit_row.actor_id,audit_row.event_kind,audit_row.correlation_id) IS DISTINCT FROM (r,actor,'ordered_public_'||op,audit_id_value)
   OR NOT zasp_sa_multistep_prior.closed(body_value||jsonb_build_object('transition_audit_id',COALESCE(transition_id,''),'transition_digest',COALESCE(body_value->>'transition_digest','')),ARRAY['request','response','transition_audit_id','transition_digest']) OR NOT body_value ?& ARRAY['transition_audit_id','transition_digest'] OR body_value->'request' IS DISTINCT FROM q OR body_value->'response' IS DISTINCT FROM result_value
   OR audit_row.event_digest IS DISTINCT FROM digest(convert_to(body_value::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation history unavailable';END IF;
  replayed:=true;
 ELSE
  IF rr.version<>(q->>'run_version')::bigint OR rr.completed_at IS NOT NULL OR rr.state NOT IN('queued','planning','waiting_approval','running','verifying') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation state changed';END IF;
  IF op='decide' THEN
   IF NOT admitted OR rr.state<>'waiting_approval' OR actor=rr.requested_by THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,state)=(o,w,e,r,'waiting_approval') ORDER BY step_index LIMIT 1;
   SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
   IF approval.approval_id IS DISTINCT FROM q->>'approval_id' OR approval.state IS DISTINCT FROM 'pending' OR approval.version IS DISTINCT FROM (q->>'approval_version')::bigint OR s.version>=1000000
    OR approval.approver_id IS NOT NULL OR approval.decided_at IS NOT NULL OR approval.fresh_auth_at IS NOT NULL OR approval.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
  ELSIF admitted THEN
   -- Before the application receipt step zero owns cancellation. Once it is
   -- complete the canonical successor owns it, including the between-step gap.
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND step_index=CASE WHEN EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_index,state)=(o,w,e,r,0,'succeeded')) THEN 1 ELSE 0 END;
  END IF;
  PERFORM zasp_ordered_public62.history(o,w,e,r);
  IF NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation authority changed';END IF;
  IF admitted THEN
   IF s.step_id IS NULL OR s.version>=1000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered current step unavailable';END IF;
   IF op='cancel' THEN SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);END IF;
   phase_value:=CASE s.state WHEN 'queued' THEN 'queued' WHEN 'waiting_approval' THEN 'pending-approval' WHEN 'authorized' THEN 'authorized' WHEN 'executing' THEN 'executing' END;
   -- The immutable cancel request retains positive pre-transition approval
   -- authority: pending=1, previously approved=2, no approval=1. Never infer
   -- a pending phase merely from missing prior decision evidence.
   transition_q:=jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'actor_id',actor,'run_id',r,'step_id',s.step_id,'operation',CASE WHEN op='cancel' THEN 'cancel' WHEN q->>'decision'='approved' THEN 'approve' ELSE 'reject' END,'run_version',rr.version,'approval_version',COALESCE(approval.version,1),'fresh_auth_at',CASE WHEN op='decide' THEN q->>'fresh_auth_at' ELSE to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END);
 IF op='decide' THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,true);END IF;
   transition_result:=zasp_temporal67.api_transition('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',transition_q);
   transition_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||CASE WHEN op='cancel' THEN 'ordered_run_cancelled' ELSE 'ordered_approval_decided' END);
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
  ELSE
   IF op<>'cancel' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered admission absent';END IF;
   phase_value:='before-admission';
   -- Preserve all planner/provider accounting evidence. needs_human remains
   -- eligible for release61 expired-lease recovery; cancelled would strand it.
   PERFORM 1 FROM zasp_sa_multistep_prior.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
   UPDATE public.zasp_security_agent_runs SET state=CASE WHEN state='queued' THEN 'cancelled' ELSE 'needs_human' END,version=version+1,completed_at=clock_timestamp(),updated_at=clock_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_error_code='public_cancel_requested' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  END IF;
  SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  cleanup_value:=EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,action_key)=(o,w,e,r,'create_temporary_policy') AND state<>'cleaned');
  result_value:=jsonb_build_object('contract_version',62,'organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'run_state',rr.state,'run_version',rr.version,'step_id',s.step_id,'step_state',s.state,'step_version',COALESCE(s.version,0),'audit_id',audit_id_value,'receipt_id',receipt_id_value,'replayed',false);
  IF op='decide' THEN result_value:=result_value||jsonb_build_object('approval_id',approval.approval_id,'approval_version',approval.version+1,'decision',q->>'decision','outcome',CASE WHEN q->>'decision'='approved' THEN 'approved' ELSE 'blocked' END);
  ELSE result_value:=result_value||jsonb_build_object('cleanup_required',cleanup_value,'cancellation_phase',phase_value,'outcome','cancelled-request');END IF;
  SELECT * INTO transition_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,transition_id);
  body_value:=jsonb_build_object('request',q,'response',result_value,'transition_audit_id',transition_id,'transition_digest',CASE WHEN transition_id IS NOT NULL THEN encode(digest(convert_to(transition_row.body::text,'UTF8'),'sha256'),'hex') END);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,approval_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_id_value,audit_id_value,r,s.step_id,approval.approval_id,actor,'ordered_public_'||op,digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
  INSERT INTO public.zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(o,w,e,actor,operation_value,q->>'idempotency_key',r,(q->>'run_version')::bigint,q,digest(convert_to(q::text,'UTF8'),'sha256'),result_value,audit_id_value,audit_id_value,receipt_id_value);
 END IF;
 keys:=ARRAY['contract_version','organization_id','workspace_id','environment_id','run_id','run_state','run_version','step_id','step_state','step_version','audit_id','receipt_id','replayed','outcome'];
 IF op='decide' THEN keys:=keys||ARRAY['approval_id','approval_version','decision'];ELSE keys:=keys||ARRAY['cleanup_required','cancellation_phase'];END IF;
 IF NOT zasp_sa_multistep_prior.closed(CASE WHEN admitted THEN result_value ELSE result_value||jsonb_build_object('step_id','','step_state','') END,keys) OR NOT result_value ?& keys OR octet_length(result_value::text)>4096
  OR result_value->'contract_version' IS DISTINCT FROM '62'::jsonb OR result_value->>'organization_id' IS DISTINCT FROM o OR result_value->>'workspace_id' IS DISTINCT FROM w OR result_value->>'environment_id' IS DISTINCT FROM e OR result_value->>'run_id' IS DISTINCT FROM r
  OR result_value->'run_version' IS DISTINCT FROM to_jsonb((q->>'run_version')::bigint+1) OR result_value->>'audit_id' IS DISTINCT FROM audit_id_value OR result_value->>'receipt_id' IS DISTINCT FROM receipt_id_value OR result_value->'replayed' IS DISTINCT FROM 'false'::jsonb
  OR op='decide' AND (result_value->>'decision' IS DISTINCT FROM q->>'decision' OR result_value->>'approval_id' IS DISTINCT FROM q->>'approval_id' OR result_value->'approval_version' IS DISTINCT FROM to_jsonb((q->>'approval_version')::bigint+1)
   OR result_value->>'run_state' IS DISTINCT FROM CASE WHEN q->>'decision'='approved' THEN 'running' ELSE 'needs_human' END OR result_value->>'step_state' IS DISTINCT FROM CASE WHEN q->>'decision'='approved' THEN 'authorized' ELSE 'cancelled' END OR result_value->>'outcome' IS DISTINCT FROM CASE WHEN q->>'decision'='approved' THEN 'approved' ELSE 'blocked' END)
  OR op='cancel' AND (result_value->>'outcome' IS DISTINCT FROM 'cancelled-request' OR result_value->>'run_state' NOT IN('cancelled','needs_human') OR jsonb_typeof(result_value->'cleanup_required') IS DISTINCT FROM 'boolean'
   OR result_value->'cleanup_required' IS DISTINCT FROM to_jsonb(EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,action_key)=(o,w,e,r,'create_temporary_policy')))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation result unavailable';END IF;
 IF transition_id IS NOT NULL THEN
  SELECT * INTO transition_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,transition_id) FOR SHARE;
  SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,result_value->>'step_id');
  -- Derive cancellation phase from immutable private transition evidence.
  -- Approval state alone cannot distinguish pending from prior authorization.
  SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
  IF op='decide' THEN expected_step_version:=s.step_index+2;
  ELSE
   decision_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||'ordered_approval_decided');
   SELECT * INTO decision_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,decision_id) FOR SHARE;
   IF FOUND THEN
    IF (decision_row.run_id,decision_row.step_id,decision_row.event_kind,decision_row.correlation_id) IS DISTINCT FROM (r,s.step_id,'ordered_approval_decided',decision_id)
     OR NOT zasp_sa_multistep_prior.closed(decision_row.body,ARRAY['contract_version','request','response']) OR decision_row.body->'contract_version' IS DISTINCT FROM '61'::jsonb
     OR NOT zasp_sa_multistep_prior.closed(decision_row.body->'request',ARRAY['organization_id','workspace_id','environment_id','actor_id','run_id','step_id','operation','run_version','approval_version','fresh_auth_at'])
     OR NOT zasp_sa_multistep_prior.closed(decision_row.body->'response',ARRAY['contract_version','organization_id','workspace_id','environment_id','run_id','step_id','outcome','run_state','run_version','step_state','approval_id','approval_version'])
     OR decision_row.event_digest IS DISTINCT FROM digest(convert_to((decision_row.body->'request')::text,'UTF8'),'sha256')
     OR (decision_row.body->'request'->>'organization_id',decision_row.body->'request'->>'workspace_id',decision_row.body->'request'->>'environment_id',decision_row.body->'request'->>'run_id',decision_row.body->'request'->>'step_id',decision_row.body->'request'->>'actor_id',decision_row.body->'request'->>'operation') IS DISTINCT FROM (o,w,e,r,s.step_id,decision_row.actor_id,'approve')
     OR decision_row.body->'request'->'approval_version' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(decision_row.body->'request'->'run_version') IS DISTINCT FROM 'number' OR decision_row.body->'request'->>'run_version'!~'^[1-9][0-9]{0,5}$'
     OR (decision_row.body->'response'->>'organization_id',decision_row.body->'response'->>'workspace_id',decision_row.body->'response'->>'environment_id',decision_row.body->'response'->>'run_id',decision_row.body->'response'->>'step_id',decision_row.body->'response'->>'outcome',decision_row.body->'response'->>'run_state',decision_row.body->'response'->>'step_state') IS DISTINCT FROM (o,w,e,r,s.step_id,'approved','running','authorized')
     OR decision_row.body->'response'->'contract_version' IS DISTINCT FROM '61'::jsonb OR decision_row.body->'response'->'run_version' IS DISTINCT FROM to_jsonb((decision_row.body->'request'->>'run_version')::bigint+1)
     OR decision_row.body->'response'->>'approval_id' IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_approval',r||chr(31)||s.step_id) OR decision_row.body->'response'->'approval_version' IS DISTINCT FROM '2'::jsonb
     OR decision_row.body->'response'->'approval_id' IS DISTINCT FROM transition_row.body->'response'->'approval_id' OR decision_row.body->'response'->'approval_version' IS DISTINCT FROM transition_row.body->'response'->'approval_version'
     OR approval.approval_id IS DISTINCT FROM decision_row.body->'response'->>'approval_id' OR approval.state IS DISTINCT FROM 'approved' OR approval.version IS DISTINCT FROM 2 OR approval.approver_id IS DISTINCT FROM decision_row.actor_id OR approval.fresh_auth_at IS DISTINCT FROM (decision_row.body->'request'->>'fresh_auth_at')::timestamptz
     OR approval.decided_at IS NULL OR approval.approver_id=rr.requested_by OR NOT COALESCE(public.zasp_valid_product_id(decision_row.actor_id),false)
     OR (decision_row.body->'response'->>'run_version')::bigint>(q->>'run_version')::bigint THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cancellation decision evidence unavailable';END IF;
   END IF;
   IF transition_row.body->'response'->>'step_state'='executing' AND transition_row.body->'request'->'approval_version'='2'::jsonb AND decision_row.audit_id IS NOT NULL THEN expected_phase:='executing';expected_step_version:=s.step_index+3;
   ELSIF transition_row.body->'response'->>'step_state'='cancelled' THEN
    IF s.step_index=1 AND transition_row.body->'request'->'approval_version'='1'::jsonb AND decision_row.audit_id IS NULL AND approval.approval_id IS NULL AND transition_row.body->'response'->>'approval_id'='' AND transition_row.body->'response'->'approval_version'='0'::jsonb THEN expected_phase:='queued';expected_step_version:=2;
    ELSIF transition_row.body->'response'->>'approval_id'=approval.approval_id AND approval.version=2 AND transition_row.body->'response'->'approval_version'='2'::jsonb THEN
     IF transition_row.body->'request'->'approval_version'='2'::jsonb AND decision_row.audit_id IS NOT NULL THEN expected_phase:='authorized';expected_step_version:=s.step_index+3;
     ELSIF transition_row.body->'request'->'approval_version'='1'::jsonb AND decision_row.audit_id IS NULL AND approval.state='cancelled' THEN expected_phase:='pending-approval';expected_step_version:=s.step_index+2;END IF;
    END IF;
   END IF;
   IF expected_phase IS NULL OR result_value->'cancellation_phase' IS DISTINCT FROM to_jsonb(expected_phase) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cancellation phase unavailable';END IF;
  END IF;
  IF s.step_id IS NULL OR jsonb_typeof(result_value->'step_version') IS DISTINCT FROM 'number' OR result_value->>'step_version'!~'^([1-9][0-9]{0,5}|1000000)$' OR (result_value->>'step_version')::bigint>s.version
   OR expected_step_version IS NULL OR result_value->'step_version' IS DISTINCT FROM to_jsonb(expected_step_version)
   OR transition_id IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||CASE WHEN op='cancel' THEN 'ordered_run_cancelled' ELSE 'ordered_approval_decided' END)
   OR body_value->>'transition_digest' IS DISTINCT FROM encode(digest(convert_to(transition_row.body::text,'UTF8'),'sha256'),'hex')
   OR transition_row.event_digest IS DISTINCT FROM digest(convert_to((transition_row.body->'request')::text,'UTF8'),'sha256')
   OR transition_row.body->'request'->>'actor_id' IS DISTINCT FROM actor OR transition_row.body->'request'->>'run_id' IS DISTINCT FROM r OR transition_row.body->'request'->>'step_id' IS DISTINCT FROM s.step_id
   OR transition_row.body->'request'->>'operation' IS DISTINCT FROM (CASE WHEN op='cancel' THEN 'cancel' WHEN q->>'decision'='approved' THEN 'approve' ELSE 'reject' END)
   OR transition_row.body->'request'->'run_version' IS DISTINCT FROM q->'run_version'
   OR transition_row.body->'response'->'run_version' IS DISTINCT FROM result_value->'run_version' OR transition_row.body->'response'->'run_state' IS DISTINCT FROM result_value->'run_state' OR transition_row.body->'response'->'step_state' IS DISTINCT FROM result_value->'step_state'
   OR op='decide' AND (transition_row.body->'request'->'approval_version' IS DISTINCT FROM q->'approval_version' OR transition_row.body->'request'->'fresh_auth_at' IS DISTINCT FROM q->'fresh_auth_at' OR transition_row.body->'response'->'approval_id' IS DISTINCT FROM q->'approval_id' OR transition_row.body->'response'->'approval_version' IS DISTINCT FROM result_value->'approval_version') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered transition history unavailable';END IF;
 ELSE
  IF result_value->>'run_state' IS DISTINCT FROM (CASE WHEN (q->>'run_version')::bigint=1 THEN 'cancelled' ELSE 'needs_human' END) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered pre-admission state unavailable';END IF;
  IF admitted OR op<>'cancel' OR result_value->>'cancellation_phase' IS DISTINCT FROM 'before-admission' OR result_value->'step_id' IS DISTINCT FROM 'null'::jsonb OR result_value->'step_state' IS DISTINCT FROM 'null'::jsonb OR result_value->'step_version' IS DISTINCT FROM '0'::jsonb OR result_value->'cleanup_required' IS DISTINCT FROM 'false'::jsonb OR body_value->'transition_digest' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cancellation history unavailable';END IF;
 END IF;
 IF op='decide' THEN
  SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id,approval_id)=(o,w,e,r,result_value->>'step_id',q->>'approval_id');
  IF (approval.state,approval.version,approval.approver_id,approval.fresh_auth_at) IS DISTINCT FROM (q->>'decision',(q->>'approval_version')::bigint+1,actor,fresh)
   OR approval.requester_id=actor OR approval.decided_at IS NULL OR approval.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered decision evidence changed';END IF;
 END IF;
 PERFORM zasp_ordered_public62.history(o,w,e,r);
 IF op='cancel' THEN PERFORM zasp_ordered_public62.project(o,w,e,r);END IF;
 IF NOT zasp_ordered_public62.ready(c,f) OR op='decide' AND (fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation expired';END IF;
 IF op='decide' THEN PERFORM zasp_authorization80_worker.require_ordered62_approval(q,false);END IF;
 RETURN result_value||jsonb_build_object('replayed',replayed);
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.resource_run(o text, w text, e text, r text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE base jsonb;rr public.zasp_security_agent_runs%ROWTYPE;p public.zasp_security_agent_plans%ROWTYPE;
 a public.zasp_security_agent_approvals%ROWTYPE;s public.zasp_security_agent_steps%ROWTYPE;proof public.zasp_security_agent_audit%ROWTYPE;approvals jsonb:='[]';plan_value jsonb;
BEGIN
 IF zasp_ordered_public62.classify(o,w,e,'run',r)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
 base:=zasp_ordered_public62.project_core(o,w,e,r,true);
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF NOT isfinite(rr.created_at) OR rr.created_at<'2000-01-01'::timestamptz OR rr.created_at>clock_timestamp()+interval '5 seconds' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered timestamp unavailable';END IF;
 IF (base->>'admitted')::boolean THEN
  SELECT * INTO p FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  IF NOT isfinite(p.expires_at) OR p.expires_at<=rr.created_at OR p.catalog_version<>'security-agent-actions-v1' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered plan unavailable';END IF;
  plan_value:=jsonb_build_object('plan_hash','sha256:'||encode(p.plan_hash,'hex'),'catalog_version',p.catalog_version,'expires_at',to_char(p.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
  FOR s IN SELECT * FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) ORDER BY step_index LOOP
   SELECT * INTO a FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
   IF a.approval_id IS NULL THEN CONTINUE;END IF;
   IF a.plan_hash IS DISTINCT FROM p.plan_hash OR a.expires_at IS DISTINCT FROM p.expires_at OR a.requester_id IS DISTINCT FROM rr.requested_by OR NOT isfinite(a.created_at) OR a.created_at<rr.created_at OR a.created_at>clock_timestamp()+interval '5 seconds'
    OR a.version IS DISTINCT FROM (CASE WHEN a.state='pending' THEN 1::bigint ELSE 2::bigint END)
    OR a.state='pending' AND (a.approver_id IS NOT NULL OR a.decided_at IS NOT NULL OR a.fresh_auth_at IS NOT NULL)
    OR a.state IN('approved','rejected') AND (a.approver_id IS NULL OR a.approver_id=a.requester_id OR a.decided_at IS NULL OR a.fresh_auth_at IS NULL)
    THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval metadata unavailable';END IF;
   IF a.state IN('approved','rejected') THEN
    SELECT * INTO proof FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||'ordered_approval_decided'));
    IF proof.audit_id IS NULL OR (proof.run_id,proof.step_id,proof.actor_id,proof.event_kind,proof.correlation_id) IS DISTINCT FROM (r,s.step_id,a.approver_id,'ordered_approval_decided',proof.audit_id)
     OR NOT zasp_sa_multistep_prior.closed(proof.body,ARRAY['contract_version','request','response']) OR proof.body->'contract_version' IS DISTINCT FROM '61'::jsonb
     OR proof.event_digest IS DISTINCT FROM digest(convert_to((proof.body->'request')::text,'UTF8'),'sha256')
     OR (proof.body->'request'->>'organization_id',proof.body->'request'->>'workspace_id',proof.body->'request'->>'environment_id',proof.body->'request'->>'run_id',proof.body->'request'->>'step_id',proof.body->'request'->>'actor_id',proof.body->'request'->>'operation') IS DISTINCT FROM (o,w,e,r,s.step_id,a.approver_id,CASE WHEN a.state='approved' THEN 'approve' ELSE 'reject' END)
     OR proof.body->'request'->'approval_version' IS DISTINCT FROM '1'::jsonb OR (proof.body->'request'->>'fresh_auth_at')::timestamptz IS DISTINCT FROM a.fresh_auth_at
     OR a.fresh_auth_at<a.decided_at-interval '5 minutes' OR a.fresh_auth_at>a.decided_at+interval '5 seconds'
     OR proof.body->'response'->>'approval_id' IS DISTINCT FROM a.approval_id OR proof.body->'response'->'approval_version' IS DISTINCT FROM to_jsonb(a.version)
     OR proof.body->'response'->>'step_state' IS DISTINCT FROM (CASE WHEN a.state='approved' THEN 'authorized' ELSE 'cancelled' END)
     OR proof.body->'response'->>'outcome' IS DISTINCT FROM (CASE WHEN a.state='approved' THEN 'approved' ELSE 'blocked' END)
     THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval decision proof unavailable';END IF;
   END IF;
   approvals:=approvals||jsonb_build_array(jsonb_build_object('id',a.approval_id,'run_id',r,'step_id',s.step_id,'state',a.state,'version',a.version,
    'expires_at',to_char(a.expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'created_at',to_char(a.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),
    'expected_effect',CASE WHEN s.step_index=0 THEN 'Apply temporary containment policy' ELSE 'Run existing test' END,'reversible',s.step_index=0,'ttl_seconds',CASE WHEN s.step_index=0 THEN (p.plan->'steps'->0->>'ttl_seconds')::integer ELSE 0 END));
  END LOOP;
 END IF;
 RETURN jsonb_build_object('contract_version',62,'ordered',base,'trigger_id',rr.trigger_id,'created_at',to_char(rr.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'plan',plan_value,'approvals',approvals);
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.retained_application(o text, w text, e text, r text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE receipt public.zasp_sa_multistep_receipts%ROWTYPE;fx public.zasp_security_agent_effects%ROWTYPE;c public.zasp_security_agent_controls%ROWTYPE;
 result_hash bytea;deployment_hash bytea;expires timestamptz;applied timestamptz;s text;
BEGIN
 s:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_step',r||chr(31)||'0');
 SELECT * INTO receipt FROM public.zasp_sa_multistep_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id,receipt_kind)=(o,w,e,r,s,'temporary_policy_applied.v1');
 SELECT * INTO fx FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy');
 SELECT * INTO c FROM public.zasp_security_agent_controls WHERE (organization_id,workspace_id,environment_id,run_id,step_id,control_id)=(o,w,e,r,s,receipt.body->>'control_id');
 SELECT digest(fx.input_digest||decode(string_agg(encode(envelope_digest,'hex'),'' ORDER BY device_id),'hex'),'sha256'),digest(convert_to(jsonb_agg(jsonb_build_array(device_id,credential_id,sequence,policy_version,desired_generation,encode(envelope_digest,'hex')) ORDER BY device_id)::text,'UTF8'),'sha256'),min(expires_at),max(verified_at)
  INTO result_hash,deployment_hash,expires,applied FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply');
 IF receipt.run_id IS NULL OR fx.state IS DISTINCT FROM 'cleanup_pending' OR result_hash IS NULL
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id,step_index,action_key,state)=(o,w,e,r,s,0,'create_temporary_policy','succeeded') AND input_digest=receipt.input_digest)
  OR fx.input_digest IS DISTINCT FROM receipt.input_digest OR receipt.result_digest IS DISTINCT FROM result_hash OR fx.result_digest IS DISTINCT FROM result_hash OR receipt.body->>'outcome_id' IS DISTINCT FROM fx.outcome_id
  OR receipt.body->>'control_id' IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_control',r||chr(31)||s)
  OR receipt.body->>'deployment_id' IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_deployment',r||chr(31)||s||chr(31)||encode(deployment_hash,'hex'))
  OR receipt.body->>'applied_at' IS DISTINCT FROM to_char(applied AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') OR receipt.body->>'expires_at' IS DISTINCT FROM to_char(expires AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')
  OR c.control_id IS NULL OR c.state NOT IN('active','disabled') OR c.target_id IS DISTINCT FROM e OR c.action_key IS DISTINCT FROM 'create_temporary_policy' OR c.expires_at IS DISTINCT FROM expires OR c.version IS DISTINCT FROM ((receipt.body->>'control_version')::bigint+CASE WHEN c.state='disabled' THEN 1 ELSE 0 END)
  OR (SELECT count(*) FROM public.zasp_security_agent_controls WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))<>1
  OR (SELECT count(*) FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply')) NOT BETWEEN 1 AND 100
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,phase)=(o,w,e,r,'apply') AND (step_id<>s OR state<>'verified' OR verified_at IS NULL OR desired_generation IS NULL OR policies IS DISTINCT FROM zasp_sa_multistep_prior.application_policies()))
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id,state,version)=(o,w,e,r,s,'approved',2) AND approver_id IS NOT NULL AND approver_id<>requester_id AND fresh_auth_at IS NOT NULL AND decided_at IS NOT NULL AND fresh_auth_at>=decided_at-interval '5 minutes' AND fresh_auth_at<=decided_at+interval '5 seconds')
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,s,'create_temporary_policy',receipt.input_digest)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered retained application unavailable';END IF;
 RETURN c.state='active' AND expires>clock_timestamp();
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">50)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_ack_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, provider_ack_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE delivery_row zasp_runtime_deliveries%ROWTYPE;result_value jsonb;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR octet_length(provider_ack_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id,existing.batch_generation,existing.message_id,existing.message_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value) FOR UPDATE;
 IF FOUND AND delivery_row.disposition='acked' AND delivery_row.provider_ack_digest=provider_ack_digest_value THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',true);END IF;
 IF NOT FOUND OR delivery_row.disposition<>'ack_pending' OR delivery_row.lease_owner<>worker_value OR delivery_row.lease_token<>lease_token_value OR delivery_row.lease_expires_at<=transaction_timestamp() OR delivery_row.visibility_deadline<=transaction_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) AND authority_row.state IN('succeeded','failed','quarantined') AND authority_row.completion_digest IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 UPDATE zasp_runtime_deliveries existing SET disposition='acked',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,provider_ack_digest=provider_ack_digest_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',false);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_ack_outbox(topic_value text, organization_value text, workspace_value text, environment_value text, outbox_value text, worker_value text, lease_token_value text, provider_ack_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;remaining_count integer;
BEGIN
 IF topic_value<>'runtime-events' OR provider_ack_value !~ '^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox acknowledgement';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox WHERE (organization_id,workspace_id,environment_id,id,topic)=(organization_value,workspace_value,environment_value,outbox_value,topic_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease missing';END IF;
 result:=zasp_discovery_ack_outbox(organization_value,workspace_value,environment_value,outbox_value,worker_value,lease_token_value,provider_ack_value);
 SELECT count(*) INTO remaining_count FROM zasp_discovery_outbox WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 RETURN result||jsonb_build_object('remaining_count',remaining_count);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, receive_count_value integer, worker_value text, lease_token_value text, lease_seconds integer, visibility_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;delivery_row zasp_runtime_deliveries%ROWTYPE;outbox_digest bytea;disposition_value text;replayed_value boolean:=false;lease_expires_value timestamptz;visibility_deadline_value timestamptz;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR message_value !~ '^[A-Za-z0-9_-]{1,128}$' OR octet_length(message_digest_value)<>32 OR receive_count_value NOT BETWEEN 1 AND 100 OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR visibility_seconds<lease_seconds OR visibility_seconds>43200 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-runtime-delivery',organization_value,workspace_value,environment_value,batch_value),0));
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR batch_row.state='uploading' THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery missing';END IF;
 SELECT outbox.payload_digest INTO outbox_digest FROM zasp_discovery_outbox outbox WHERE (outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.topic,outbox.deterministic_key,outbox.payload_version)=(organization_value,workspace_value,environment_value,'runtime-events','runtime:'||batch_value,15);
 IF NOT FOUND OR outbox_digest IS DISTINCT FROM message_digest_value THEN
  IF batch_row.state NOT IN('succeeded','failed','unknown','quarantined') THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);END IF;
  RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value) FOR UPDATE;
 -- v36: exact durable outbox identity permits at-least-once publication.
 IF FOUND AND delivery_row.batch_generation=generation_value AND delivery_row.message_digest=message_digest_value AND delivery_row.message_id<>message_value THEN
  IF batch_row.state='unknown' OR delivery_row.disposition='unknown' THEN
   RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF batch_row.state IN('succeeded','failed','quarantined') THEN
   RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);
  END IF;
  IF delivery_row.disposition NOT IN('held','ack_pending') THEN
   RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp() THEN
   RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_duplicate','replayed',true);
  END IF;
  UPDATE zasp_runtime_deliveries existing SET message_id=message_value,receive_count=receive_count_value,provider_ack_digest=NULL,lease_expires_at=transaction_timestamp()
   WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  delivery_row.message_id:=message_value;delivery_row.receive_count:=receive_count_value;delivery_row.lease_expires_at:=transaction_timestamp();
 END IF;
 IF FOUND AND (delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest) IS DISTINCT FROM (generation_value,message_value,message_digest_value) THEN
  UPDATE zasp_runtime_deliveries existing SET disposition='quarantined',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value) AND authority_row.state NOT IN('succeeded','failed','unknown','quarantined');
  RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 IF FOUND AND receive_count_value<delivery_row.receive_count THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime delivery conflict';END IF;
 IF FOUND AND delivery_row.disposition='acked' THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);END IF;
 IF batch_row.state='unknown' OR FOUND AND delivery_row.disposition='unknown' THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',FOUND);END IF;
 IF FOUND AND delivery_row.disposition IN('held','ack_pending') AND delivery_row.lease_expires_at>transaction_timestamp() AND (delivery_row.lease_owner,delivery_row.lease_token) IS DISTINCT FROM (worker_value,lease_token_value) THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false,'lease_expires_at',delivery_row.lease_expires_at);END IF;
 IF EXISTS(SELECT 1 FROM zasp_runtime_deliveries other WHERE other.organization_id=organization_value AND other.batch_id<>batch_value AND other.disposition IN('held','ack_pending') AND other.lease_expires_at>transaction_timestamp()) THEN RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false);END IF;
 disposition_value:=CASE WHEN batch_row.state IN('succeeded','failed','quarantined') THEN 'ack_pending' ELSE 'held' END;
 lease_expires_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);visibility_deadline_value:=transaction_timestamp()+make_interval(secs=>visibility_seconds);
 IF FOUND THEN
  replayed_value:=delivery_row.receive_count=receive_count_value AND delivery_row.disposition=disposition_value AND (delivery_row.lease_owner,delivery_row.lease_token) IS NOT DISTINCT FROM (worker_value,lease_token_value);
  UPDATE zasp_runtime_deliveries existing SET receive_count=GREATEST(existing.receive_count,receive_count_value),disposition=disposition_value,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=lease_expires_value,visibility_deadline=visibility_deadline_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 ELSE
  INSERT INTO zasp_runtime_deliveries(organization_id,workspace_id,environment_id,batch_id,batch_generation,message_id,message_digest,receive_count,disposition,lease_owner,lease_token,lease_expires_at,visibility_deadline) VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,receive_count_value,disposition_value,worker_value,lease_token_value,lease_expires_value,visibility_deadline_value);
 END IF;
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition',CASE WHEN disposition_value='held' THEN 'claimed' ELSE disposition_value END,'replayed',replayed_value,'lease_expires_at',lease_expires_value,'visibility_deadline',visibility_deadline_value,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'artifact_kms_key',batch_row.raw_artifact_kms_key,'request_digest',encode(batch_row.request_digest,'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_outbox(topic_value text, worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;last_organization text;claimed_last_organization text;
BEGIN
 IF topic_value<>'runtime-events' OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox claim';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp_runtime_outbox:'||topic_value,0));
 INSERT INTO zasp_discovery_outbox_topic_fairness(topic) VALUES(topic_value) ON CONFLICT(topic) DO NOTHING;
 SELECT last_organization_id INTO last_organization FROM zasp_discovery_outbox_topic_fairness WHERE topic=topic_value FOR UPDATE;
 UPDATE zasp_discovery_outbox SET state='exhausted',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_error=COALESCE(last_error,'maximum publish attempts exhausted')
 WHERE topic=topic_value AND attempt>=100 AND (state='failed' OR state='leased' AND lease_expires_at<=transaction_timestamp());
 WITH organizations AS (
  SELECT candidate.organization_id,min(candidate.available_at) due FROM zasp_discovery_outbox candidate
  WHERE candidate.topic=topic_value AND candidate.attempt<100 AND (candidate.state IN('pending','failed') OR candidate.state='leased' AND candidate.lease_expires_at<=transaction_timestamp()) AND candidate.available_at<=transaction_timestamp()
    AND NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox live WHERE live.topic=topic_value AND live.organization_id=candidate.organization_id AND live.state='leased' AND live.lease_expires_at>transaction_timestamp())
  GROUP BY candidate.organization_id
 ),ordered_organizations AS (
  SELECT organization_id,due,row_number() OVER(ORDER BY CASE WHEN last_organization IS NULL OR organization_id>last_organization THEN 0 ELSE 1 END,organization_id) fair_order
  FROM organizations ORDER BY fair_order LIMIT claim_limit
 ),picked AS (
  SELECT chosen.ctid,chosen.organization_id,chosen.created_at,chosen.id,organization.fair_order FROM ordered_organizations organization
  CROSS JOIN LATERAL (
   SELECT outbox.ctid,outbox.organization_id,outbox.created_at,outbox.id FROM zasp_discovery_outbox outbox
   WHERE outbox.organization_id=organization.organization_id AND outbox.topic=topic_value AND outbox.attempt<100
     AND (outbox.state IN('pending','failed') OR outbox.state='leased' AND outbox.lease_expires_at<=transaction_timestamp()) AND outbox.available_at<=transaction_timestamp()
   ORDER BY outbox.created_at,outbox.id LIMIT 1 FOR UPDATE SKIP LOCKED
  ) chosen
 ),claimed AS (
  UPDATE zasp_discovery_outbox outbox SET state='leased',attempt=attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),completion_digest=NULL,completion_result=NULL
  FROM (SELECT * FROM picked ORDER BY fair_order) candidate WHERE outbox.ctid=candidate.ctid
  RETURNING outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.id,outbox.topic,outbox.deterministic_key,outbox.payload_version,outbox.payload,encode(outbox.payload_digest,'base64') payload_digest,outbox.attempt,outbox.lease_expires_at,candidate.fair_order
 )
 SELECT jsonb_build_object('items',COALESCE(jsonb_agg(to_jsonb(claimed)-'fair_order' ORDER BY fair_order),'[]'::jsonb)),(array_agg(organization_id ORDER BY fair_order DESC))[1] INTO response,claimed_last_organization FROM claimed;
 IF claimed_last_organization IS NOT NULL THEN UPDATE zasp_discovery_outbox_topic_fairness SET last_organization_id=claimed_last_organization,updated_at=transaction_timestamp() WHERE topic=topic_value;END IF;
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_reconciliation(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 IF NOT zasp_discovery_principal_ready('zasp_runtime_ingest') OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 60 AND 300 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation claim rejected';END IF;
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='succeeded',completion_worker='observed',completion_token_digest=digest(convert_to('observed','UTF8'),'sha256'),completion_digest=digest(convert_to(authority_row.completion_result::text,'UTF8'),'sha256'),completion_result=COALESCE(authority_row.completion_result,jsonb_build_object('batch_id',authority_row.batch_id,'generation',authority_row.batch_generation,'state',authority_row.state,'replayed',true)),completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL
 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id) AND work_row.state NOT IN('succeeded','quarantined') AND authority_row.state NOT IN('uploading','unknown');
 UPDATE zasp_runtime_ingest_reconciliation_work SET state=CASE WHEN attempt>=100 THEN 'exhausted' ELSE 'retryable' END,available_at=transaction_timestamp(),last_error_code=CASE WHEN attempt>=100 THEN 'exhausted' ELSE 'outcome_unknown' END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL WHERE state='leased' AND lease_expires_at<=transaction_timestamp();
 WITH candidates AS (
  SELECT work_row.ctid FROM zasp_runtime_ingest_reconciliation_work work_row JOIN zasp_runtime_batch_authorities authority_row USING(organization_id,workspace_id,environment_id,batch_id)
  WHERE work_row.state IN('pending','retryable') AND work_row.attempt<100 AND work_row.available_at<=transaction_timestamp() AND authority_row.state IN('uploading','unknown') ORDER BY work_row.available_at,work_row.organization_id,work_row.batch_id FOR UPDATE OF work_row SKIP LOCKED LIMIT claim_limit
 ),claimed AS (
  UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='leased',attempt=work_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_error_code=NULL FROM candidates WHERE work_row.ctid=candidates.ctid
  RETURNING work_row.*
 ) SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'attempt',claimed.attempt,'lease_expires_at',claimed.lease_expires_at,'request_digest',encode(authority_row.request_digest,'hex'),'artifact_key',authority_row.raw_artifact_key,'content_digest',encode(authority_row.content_digest,'hex'),'payload_size_bytes',authority_row.payload_size_bytes,'media_type',authority_row.payload_media_type,'schema_version',authority_row.payload_schema_version) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO response FROM claimed JOIN zasp_runtime_batch_authorities authority_row USING(organization_id,workspace_id,environment_id,batch_id);
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_stage_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v2 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v2 IS NULL OR (allow_v2 AND stage_value<>'correlate') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_correlation_claim_version',true),'');
 PERFORM set_config('zasp.runtime_correlation_claim_version',CASE WHEN allow_v2 THEN 'runtime-correlation-v2' ELSE 'runtime-correlation-v1' END,true);
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
  WHERE stage_row.stage=stage_value AND (stage_value NOT IN('project','complete') OR stage_value='project' AND stage_row.implementation_version='runtime-projection-v1' OR stage_value='complete' AND stage_row.implementation_version='runtime-complete-v1') AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v2 AND stage_row.implementation_version='runtime-correlation-v2') AND stage_row.attempt>=100 AND stage_row.state IN('pending','retryable','leased') AND (stage_row.state<>'leased' OR stage_row.lease_expires_at<=transaction_timestamp())
  RETURNING stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.completion_digest,stage_row.completion_result
 ),failed_batches AS (
  UPDATE zasp_runtime_batch_authorities authority_row SET state='failed',completed_at=transaction_timestamp(),completion_digest=exhausted.completion_digest,completion_result=exhausted.completion_result
  FROM exhausted WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id)
  RETURNING authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.completion_digest,authority_row.completion_result
 ),failed_legacy_batches AS (
  UPDATE zasp_runtime_batches batch_row SET state='failed',completed_at=transaction_timestamp()
  FROM failed_batches WHERE (batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id)
  RETURNING batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id
 ),failed_jobs AS (
  UPDATE zasp_discovery_jobs job_row SET state='failed',last_error='exhausted',completed_at=transaction_timestamp(),updated_at=transaction_timestamp(),completion_digest=failed_batches.completion_digest,completion_result=failed_batches.completion_result
  FROM failed_batches WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.kind,job_row.authority_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,'runtime',failed_batches.batch_id)
  RETURNING job_row.organization_id
 )
 UPDATE zasp_runtime_deliveries delivery_row SET disposition='ack_pending',updated_at=transaction_timestamp()
 FROM failed_batches WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id) AND delivery_row.disposition='held';
 WITH eligible AS (
  SELECT stage_row.ctid row_id,stage_row.*,row_number() OVER(PARTITION BY stage_row.organization_id ORDER BY stage_row.available_at,stage_row.batch_id) organization_rank
  FROM zasp_runtime_stage_work stage_row
  WHERE stage_row.stage=stage_value AND (stage_value NOT IN('project','complete') OR stage_value='project' AND stage_row.implementation_version='runtime-projection-v1' OR stage_value='complete' AND stage_row.implementation_version='runtime-complete-v1') AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v2 AND stage_row.implementation_version='runtime-correlation-v2') AND stage_row.attempt<100 AND stage_row.available_at<=transaction_timestamp() AND (stage_row.state IN('pending','retryable') OR stage_row.state='leased' AND stage_row.lease_expires_at<=transaction_timestamp())
   AND stage_row.input_digest IS NOT NULL
   AND EXISTS(SELECT 1 FROM zasp_runtime_deliveries delivery_row WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.disposition)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,'held') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp())
   AND (stage_row.stage_order=1 OR EXISTS(SELECT 1 FROM zasp_runtime_stage_work predecessor WHERE (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order,predecessor.state,predecessor.effect_digest)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage_order-1,'succeeded',stage_row.predecessor_digest)))
   AND NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work live_row WHERE live_row.stage=stage_value AND live_row.organization_id=stage_row.organization_id AND live_row.state='leased' AND live_row.lease_expires_at>transaction_timestamp())
 ),organizations AS (
  SELECT eligible.organization_id,min(eligible.available_at) first_available,MAX(fairness.last_claimed_at) last_claimed_at
  FROM eligible LEFT JOIN zasp_runtime_stage_fairness fairness ON (fairness.stage,fairness.organization_id)=(stage_value,eligible.organization_id)
  WHERE eligible.organization_rank=1 GROUP BY eligible.organization_id
  ORDER BY MAX(fairness.last_claimed_at) NULLS FIRST,min(eligible.available_at),eligible.organization_id LIMIT claim_limit
 ),candidates AS (
  SELECT stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage
  FROM zasp_runtime_stage_work stage_row JOIN eligible ON stage_row.ctid=eligible.row_id JOIN organizations ON organizations.organization_id=eligible.organization_id
  WHERE eligible.organization_rank=1 ORDER BY organizations.last_claimed_at NULLS FIRST,organizations.first_available,stage_row.organization_id,stage_row.batch_id FOR UPDATE OF stage_row SKIP LOCKED
 ),claimed AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='leased',attempt=stage_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp(),last_error_class=NULL
  FROM candidates WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage)=(candidates.organization_id,candidates.workspace_id,candidates.environment_id,candidates.batch_id,candidates.stage)
  RETURNING stage_row.*
 ),fairness AS (
  INSERT INTO zasp_runtime_stage_fairness(stage,organization_id,last_claimed_at) SELECT stage_value,claimed.organization_id,transaction_timestamp() FROM claimed
  ON CONFLICT(stage,organization_id) DO UPDATE SET last_claimed_at=excluded.last_claimed_at RETURNING organization_id
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'stage',claimed.stage,'attempt',claimed.attempt,'implementation_version',claimed.implementation_version,'predecessor_digest',CASE WHEN claimed.predecessor_digest IS NULL THEN NULL ELSE encode(claimed.predecessor_digest,'hex') END,'input_digest',encode(claimed.input_digest,'hex'),'input_reference',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_reference ELSE predecessor.result_reference END,'input_version_id',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_version_id ELSE predecessor.result_version_id END,'lease_expires_at',claimed.lease_expires_at) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO result_value
 FROM claimed JOIN zasp_runtime_batch_authorities authority_row ON (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.batch_generation)
 LEFT JOIN zasp_runtime_stage_work predecessor ON (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.stage_order-1);
 IF stage_value='archive' AND jsonb_array_length(result_value)>0 THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='processing' WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(item->>'organization_id',item->>'workspace_id',item->>'environment_id',item->>'batch_id'));END IF;
 PERFORM set_config('zasp.runtime_correlation_claim_version',prior_capability,true);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_claim_stage_sandbox_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, allow_v3 boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR allow_v3 IS NULL OR (allow_v3 AND stage_value<>'correlate') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_correlation_claim_version',true),'');
 PERFORM set_config('zasp.runtime_correlation_claim_version',CASE WHEN allow_v3 THEN 'runtime-correlation-v3' ELSE 'runtime-correlation-v1' END,true);
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
  WHERE stage_row.stage=stage_value AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v3 AND stage_row.implementation_version IN('runtime-correlation-v2','runtime-correlation-v3')) AND stage_row.attempt>=100 AND stage_row.state IN('pending','retryable','leased') AND (stage_row.state<>'leased' OR stage_row.lease_expires_at<=transaction_timestamp())
  RETURNING stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.completion_digest,stage_row.completion_result
 ),failed_batches AS (
  UPDATE zasp_runtime_batch_authorities authority_row SET state='failed',completed_at=transaction_timestamp(),completion_digest=exhausted.completion_digest,completion_result=exhausted.completion_result
  FROM exhausted WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id)
  RETURNING authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.completion_digest,authority_row.completion_result
 ),failed_legacy_batches AS (
  UPDATE zasp_runtime_batches batch_row SET state='failed',completed_at=transaction_timestamp()
  FROM failed_batches WHERE (batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id)
  RETURNING batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id
 ),failed_jobs AS (
  UPDATE zasp_discovery_jobs job_row SET state='failed',last_error='exhausted',completed_at=transaction_timestamp(),updated_at=transaction_timestamp(),completion_digest=failed_batches.completion_digest,completion_result=failed_batches.completion_result
  FROM failed_batches WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.kind,job_row.authority_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,'runtime',failed_batches.batch_id)
  RETURNING job_row.organization_id
 )
 UPDATE zasp_runtime_deliveries delivery_row SET disposition='ack_pending',updated_at=transaction_timestamp()
 FROM failed_batches WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id) AND delivery_row.disposition='held';
 WITH eligible AS (
  SELECT stage_row.ctid row_id,stage_row.*,row_number() OVER(PARTITION BY stage_row.organization_id ORDER BY stage_row.available_at,stage_row.batch_id) organization_rank
  FROM zasp_runtime_stage_work stage_row
  WHERE stage_row.stage=stage_value AND (stage_value<>'correlate' OR stage_row.implementation_version='runtime-correlation-v1' OR allow_v3 AND stage_row.implementation_version IN('runtime-correlation-v2','runtime-correlation-v3')) AND stage_row.attempt<100 AND stage_row.available_at<=transaction_timestamp() AND (stage_row.state IN('pending','retryable') OR stage_row.state='leased' AND stage_row.lease_expires_at<=transaction_timestamp())
   AND stage_row.input_digest IS NOT NULL
   AND EXISTS(SELECT 1 FROM zasp_runtime_deliveries delivery_row WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.disposition)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,'held') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp())
   AND (stage_row.stage_order=1 OR EXISTS(SELECT 1 FROM zasp_runtime_stage_work predecessor WHERE (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order,predecessor.state,predecessor.effect_digest)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage_order-1,'succeeded',stage_row.predecessor_digest)))
   AND NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work live_row WHERE live_row.stage=stage_value AND live_row.organization_id=stage_row.organization_id AND live_row.state='leased' AND live_row.lease_expires_at>transaction_timestamp())
 ),organizations AS (
  SELECT eligible.organization_id,min(eligible.available_at) first_available,MAX(fairness.last_claimed_at) last_claimed_at
  FROM eligible LEFT JOIN zasp_runtime_stage_fairness fairness ON (fairness.stage,fairness.organization_id)=(stage_value,eligible.organization_id)
  WHERE eligible.organization_rank=1 GROUP BY eligible.organization_id
  ORDER BY MAX(fairness.last_claimed_at) NULLS FIRST,min(eligible.available_at),eligible.organization_id LIMIT claim_limit
 ),candidates AS (
  SELECT stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage
  FROM zasp_runtime_stage_work stage_row JOIN eligible ON stage_row.ctid=eligible.row_id JOIN organizations ON organizations.organization_id=eligible.organization_id
  WHERE eligible.organization_rank=1 ORDER BY organizations.last_claimed_at NULLS FIRST,organizations.first_available,stage_row.organization_id,stage_row.batch_id FOR UPDATE OF stage_row SKIP LOCKED
 ),claimed AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='leased',attempt=stage_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp(),last_error_class=NULL
  FROM candidates WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage)=(candidates.organization_id,candidates.workspace_id,candidates.environment_id,candidates.batch_id,candidates.stage)
  RETURNING stage_row.*
 ),fairness AS (
  INSERT INTO zasp_runtime_stage_fairness(stage,organization_id,last_claimed_at) SELECT stage_value,claimed.organization_id,transaction_timestamp() FROM claimed
  ON CONFLICT(stage,organization_id) DO UPDATE SET last_claimed_at=excluded.last_claimed_at RETURNING organization_id
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'stage',claimed.stage,'attempt',claimed.attempt,'implementation_version',claimed.implementation_version,'predecessor_digest',CASE WHEN claimed.predecessor_digest IS NULL THEN NULL ELSE encode(claimed.predecessor_digest,'hex') END,'input_digest',encode(claimed.input_digest,'hex'),'input_reference',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_reference ELSE predecessor.result_reference END,'input_version_id',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_version_id ELSE predecessor.result_version_id END,'lease_expires_at',claimed.lease_expires_at) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO result_value
 FROM claimed JOIN zasp_runtime_batch_authorities authority_row ON (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.batch_generation)
 LEFT JOIN zasp_runtime_stage_work predecessor ON (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.stage_order-1);
 IF stage_value='archive' AND jsonb_array_length(result_value)>0 THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='processing' WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(item->>'organization_id',item->>'workspace_id',item->>'environment_id',item->>'batch_id'));END IF;
 PERFORM set_config('zasp.runtime_correlation_claim_version',prior_capability,true);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_commit_reserved_batch(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, request_digest_value bytea, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;event_payload jsonb;result_value jsonb;
BEGIN
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR octet_length(request_digest_value)<>32 OR NOT zasp_valid_product_id(job_value) OR NOT zasp_valid_product_id(outbox_value) OR NOT zasp_discovery_s3_object_reference(artifact_reference_value) OR length(artifact_key_value) NOT BETWEEN 32 AND 1024 OR right(artifact_reference_value,length(artifact_key_value)+1)<>'/'||artifact_key_value OR length(artifact_version_value) NOT BETWEEN 1 AND 1024 OR artifact_version_value<>btrim(artifact_version_value) OR octet_length(artifact_checksum_value)<>32 OR artifact_size_value NOT BETWEEN 1 AND 67108864 OR artifact_kms_key_value !~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation,authority_row.request_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime batch rejected';END IF;
 IF batch_row.state NOT IN('uploading','unknown') THEN
  IF batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND (batch_row.raw_artifact_reference,batch_row.raw_artifact_key,batch_row.raw_artifact_version_id,batch_row.raw_artifact_checksum,batch_row.raw_artifact_size_bytes,batch_row.raw_artifact_kms_key) IS NOT DISTINCT FROM (artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value)
   AND EXISTS(SELECT 1 FROM zasp_discovery_jobs job_row WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.id,job_row.kind,job_row.authority_id)=(organization_value,workspace_value,environment_value,job_value,'runtime',batch_value))
   AND EXISTS(SELECT 1 FROM zasp_discovery_outbox outbox_row WHERE (outbox_row.organization_id,outbox_row.workspace_id,outbox_row.environment_id,outbox_row.id,outbox_row.topic,outbox_row.deterministic_key,outbox_row.payload_version)=(organization_value,workspace_value,environment_value,outbox_value,'runtime-events','runtime:'||batch_value,15))
  THEN RETURN jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state,'replayed',true);END IF;
  RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';
 END IF;
 IF (batch_row.raw_artifact_key,batch_row.content_digest,batch_row.payload_size_bytes) IS DISTINCT FROM (artifact_key_value,artifact_checksum_value,artifact_size_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';END IF;
 INSERT INTO zasp_runtime_batches(organization_id,workspace_id,environment_id,id,sensor_id,idempotency_key,payload_digest,event_count,payload_reference,payload_size_bytes,payload_media_type,payload_schema_version)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.sensor_id,batch_row.idempotency_key,batch_row.content_digest,batch_row.event_count,artifact_reference_value,batch_row.payload_size_bytes,batch_row.payload_media_type,batch_row.payload_schema_version);
 INSERT INTO zasp_discovery_jobs(organization_id,workspace_id,environment_id,id,kind,authority_id,idempotency_key,request_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_row.batch_id,batch_row.idempotency_key,batch_row.request_digest);
 INSERT INTO zasp_runtime_stage_work(organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,stage_order,implementation_version,input_digest)
 SELECT batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.batch_generation,stage_value.stage,stage_value.stage_order,stage_value.version_value,CASE WHEN stage_value.stage_order=1 THEN batch_row.content_digest ELSE NULL END
 FROM (VALUES('archive',1,'runtime-archive-v1'),('index',2,'runtime-index-v1'),('correlate',3,'runtime-correlation-v2'),('project',4,'runtime-projection-v1'),('complete',5,'runtime-complete-v1')) stage_value(stage,stage_order,version_value);
 event_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',artifact_reference_value,'artifact_key',artifact_key_value,'artifact_version_id',artifact_version_value,'artifact_checksum',encode(artifact_checksum_value,'hex'),'artifact_size_bytes',artifact_size_value,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
 INSERT INTO zasp_discovery_outbox(organization_id,workspace_id,environment_id,id,topic,deterministic_key,payload_version,payload,payload_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_row.batch_id,15,event_payload,digest(convert_to(event_payload::text,'UTF8'),'sha256'));
 UPDATE zasp_runtime_batch_authorities authority_row SET raw_artifact_reference=artifact_reference_value,raw_artifact_version_id=artifact_version_value,raw_artifact_checksum=artifact_checksum_value,raw_artifact_size_bytes=artifact_size_value,raw_artifact_kms_key=artifact_kms_key_value,state='queued',finalized_at=transaction_timestamp() WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id);
 result_value:=jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state','queued','replayed',false);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_finish_reconciliation(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work_value zasp_runtime_ingest_reconciliation_work%ROWTYPE;result_value jsonb;completion_digest_value bytea;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,worker_value,encode(digest(convert_to(lease_token_value,'UTF8'),'sha256'),'hex'),job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,encode(artifact_checksum_value,'hex'),artifact_size_value::text,artifact_kms_key_value),'UTF8'),'sha256');
 SELECT * INTO work_value FROM zasp_runtime_ingest_reconciliation_work work_row WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime reconciliation finish rejected';END IF;
 IF work_value.state IN('succeeded','quarantined') THEN
  IF (work_value.completion_worker,work_value.completion_token_digest,work_value.completion_digest) IS DISTINCT FROM (worker_value,digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime reconciliation finish conflict';END IF;
  RETURN work_value.completion_result||jsonb_build_object('replayed',true);
 END IF;
 IF (work_value.state,work_value.lease_owner,work_value.lease_token) IS DISTINCT FROM ('leased',worker_value,lease_token_value) OR work_value.lease_expires_at<=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation finish rejected';END IF;
 result_value:=zasp_runtime_reconcile_batch(organization_value,workspace_value,environment_value,batch_value,generation_value,(SELECT authority_row.request_digest FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value)),job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state=CASE result_value->>'state' WHEN 'quarantined' THEN 'quarantined' ELSE 'succeeded' END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completion_worker=worker_value,completion_token_digest=digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest=completion_digest_value,completion_result=result_value,completed_at=transaction_timestamp() WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_heartbeat_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, lease_seconds integer, visibility_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE lease_expires_value timestamptz;visibility_deadline_value timestamptz;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR lease_seconds NOT BETWEEN 5 AND 900 OR visibility_seconds<lease_seconds OR visibility_seconds>43200 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 lease_expires_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);visibility_deadline_value:=transaction_timestamp()+make_interval(secs=>visibility_seconds);
 UPDATE zasp_runtime_deliveries delivery_row SET lease_expires_at=lease_expires_value,visibility_deadline=visibility_deadline_value,updated_at=transaction_timestamp()
  WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest,delivery_row.lease_owner,delivery_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,worker_value,lease_token_value) AND delivery_row.disposition IN('held','ack_pending') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'lease_expires_at',lease_expires_value,'visibility_deadline',visibility_deadline_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_heartbeat_outbox(topic_value text, worker_value text, lease_token_value text, lease_seconds integer, expected_count integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE lease_expiration timestamptz;updated_count integer;
BEGIN
 IF topic_value<>'runtime-events' OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR expected_count NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox heartbeat';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 lease_expiration:=transaction_timestamp()+make_interval(secs=>lease_seconds);
 UPDATE zasp_discovery_outbox SET lease_expires_at=lease_expiration WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 GET DIAGNOSTICS updated_count=ROW_COUNT;
 IF updated_count<>expected_count THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease set conflict';END IF;
 RETURN jsonb_build_object('id',topic_value,'lease_expires_at',to_char(lease_expiration AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'remaining_count',updated_count);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_lookup_acceptance(locator_value bytea, secret_value bytea, enrollment_value text, batch_value text, idempotency_value text, content_digest_value bytea, source_value text, media_value text, schema_value text, size_value bigint, count_value integer, job_value text, outbox_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority jsonb;batch_row zasp_runtime_batch_authorities%ROWTYPE;scope_bytes bytea;expected_payload jsonb;response jsonb;now_value timestamptz;
BEGIN
 IF NOT COALESCE(zasp_discovery_principal_ready('zasp_runtime_ingest') AND zasp_production_runtime_acceptance_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime acceptance principal rejected';END IF;
 IF NOT COALESCE(octet_length(locator_value)=16 AND octet_length(secret_value)=32 AND enrollment_value ~ '^[0-9a-f]{64}$' AND zasp_valid_product_id(batch_value) AND length(idempotency_value) BETWEEN 16 AND 128 AND octet_length(content_digest_value)=32 AND source_value IN('tetragon','otlp') AND media_value='application/json' AND schema_value='runtime-event-v1' AND size_value BETWEEN 1 AND 67108864 AND count_value BETWEEN 1 AND 1000 AND zasp_valid_product_id(job_value) AND zasp_valid_product_id(outbox_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime acceptance input rejected';END IF;
 authority:=zasp_runtime_authenticate_sensor(locator_value,secret_value,'event-ingest');
 scope_bytes:=convert_to('zasp.sensor-enrollment.v1','UTF8')||decode('00','hex')||convert_to(authority->>'organization_id','UTF8')||decode('00','hex')||convert_to(authority->>'workspace_id','UTF8')||decode('00','hex')||convert_to(authority->>'environment_id','UTF8')||decode('00','hex')||convert_to(authority->>'sensor_id','UTF8');
 IF encode(digest(scope_bytes,'sha256'),'hex') IS DISTINCT FROM enrollment_value OR authority->>'sensor_kind' IS DISTINCT FROM source_value THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='runtime acceptance enrollment rejected';END IF;
 -- Do not wait on a batch while holding sensor authority. A worker may need
 -- that sensor lock; contention is a retry, never a reason to invert locks.
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.sensor_id,b.idempotency_key)=(authority->>'organization_id',authority->>'workspace_id',authority->>'environment_id',authority->>'sensor_id',idempotency_value) FOR SHARE NOWAIT;
 response:=jsonb_build_object('found',false);
 IF FOUND THEN
  IF (batch_row.batch_id,batch_row.content_digest,batch_row.source_kind,batch_row.payload_media_type,batch_row.payload_schema_version,batch_row.payload_size_bytes,batch_row.event_count) IS DISTINCT FROM (batch_value,content_digest_value,source_value,media_value,schema_value,size_value,count_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance conflict';END IF;
  IF batch_row.state NOT IN('uploading','unknown') THEN
   IF NOT COALESCE(batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND batch_row.finalized_at IS NOT NULL AND batch_row.raw_artifact_checksum=content_digest_value AND batch_row.raw_artifact_size_bytes=size_value AND zasp_discovery_s3_object_reference(batch_row.raw_artifact_reference) AND right(batch_row.raw_artifact_reference,length(batch_row.raw_artifact_key)+1)='/'||batch_row.raw_artifact_key AND length(batch_row.raw_artifact_version_id) BETWEEN 1 AND 1024 AND batch_row.raw_artifact_version_id=btrim(batch_row.raw_artifact_version_id) AND batch_row.raw_artifact_kms_key ~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$',false) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance artifact rejected';END IF;
   expected_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
   IF NOT EXISTS(SELECT 1 FROM zasp_runtime_batches b WHERE (b.organization_id,b.workspace_id,b.environment_id,b.id,b.sensor_id,b.idempotency_key,b.payload_digest,b.event_count,b.payload_reference,b.payload_size_bytes,b.payload_media_type,b.payload_schema_version)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_value,batch_row.sensor_id,idempotency_value,content_digest_value,count_value,batch_row.raw_artifact_reference,size_value,media_value,schema_value))
   OR NOT EXISTS(SELECT 1 FROM zasp_discovery_jobs j WHERE (j.organization_id,j.workspace_id,j.environment_id,j.id,j.kind,j.authority_id,j.idempotency_key,j.request_digest)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_value,idempotency_value,batch_row.request_digest))
   OR NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox o WHERE (o.organization_id,o.workspace_id,o.environment_id,o.id,o.topic,o.deterministic_key,o.payload_version,o.payload,o.payload_digest)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_value,15,expected_payload,digest(convert_to(expected_payload::text,'UTF8'),'sha256')))
   OR (SELECT count(*) FROM zasp_runtime_stage_work s WHERE (s.organization_id,s.workspace_id,s.environment_id,s.batch_id,s.batch_generation)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_value,batch_row.batch_generation) AND (s.stage,s.stage_order) IN(('archive',1),('index',2),('correlate',3),('project',4),('complete',5)))<>5
   THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime acceptance durable binding rejected';END IF;
   response:=jsonb_build_object('found',true,'batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state);
  END IF;
 END IF;
 -- Authentication locks are still held. Check wall time after the last query,
 -- not transaction start time, so lock waits cannot extend an expired token.
 IF NOT COALESCE(zasp_discovery_principal_ready('zasp_runtime_ingest') AND zasp_production_runtime_acceptance_readiness(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime acceptance principal expired';END IF;
 now_value:=clock_timestamp();
 IF NOT EXISTS(SELECT 1 FROM zasp_sensor_tokens t JOIN zasp_sensors s ON (s.organization_id,s.workspace_id,s.environment_id,s.id,s.version)=(t.organization_id,t.workspace_id,t.environment_id,t.sensor_id,t.sensor_version_at_issue) WHERE (t.organization_id,t.workspace_id,t.environment_id,t.sensor_id,t.id,t.token_generation)=(authority->>'organization_id',authority->>'workspace_id',authority->>'environment_id',authority->>'sensor_id',authority->>'token_id',(authority->>'token_generation')::bigint) AND t.revoked_at IS NULL AND t.expires_at>now_value AND s.state IN('pending','active','degraded')) THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='runtime acceptance credential expired';END IF;
 RETURN response;
END
$function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_quarantine_reconciliation(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE work_value zasp_runtime_ingest_reconciliation_work%ROWTYPE;batch_value_row zasp_runtime_batch_authorities%ROWTYPE;completion_digest_value bytea;result_value jsonb;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,worker_value,encode(digest(convert_to(lease_token_value,'UTF8'),'sha256'),'hex'),'artifact_drift'),'UTF8'),'sha256');
 SELECT * INTO work_value FROM zasp_runtime_ingest_reconciliation_work work_row WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime reconciliation quarantine rejected';END IF;
 IF work_value.state='quarantined' THEN
  IF (work_value.completion_worker,work_value.completion_token_digest,work_value.completion_digest) IS DISTINCT FROM (worker_value,digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime reconciliation quarantine conflict';END IF;
  RETURN work_value.completion_result||jsonb_build_object('replayed',true);
 END IF;
 IF (work_value.state,work_value.lease_owner,work_value.lease_token) IS DISTINCT FROM ('leased',worker_value,lease_token_value) OR work_value.lease_expires_at<=transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation quarantine rejected';END IF;
 SELECT * INTO batch_value_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR batch_value_row.state NOT IN('uploading','unknown') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation quarantine rejected';END IF;
 result_value:=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','artifact_drift','replayed',false);
 UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=completion_digest_value,completion_result=result_value WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='quarantined',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completion_worker=worker_value,completion_token_digest=digest(convert_to(lease_token_value,'UTF8'),'sha256'),completion_digest=completion_digest_value,completion_result=result_value,completed_at=transaction_timestamp(),last_error_code=NULL WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_release_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, outcome_value text, error_class_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE completion_digest_value bytea;result_value jsonb;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR outcome_value NOT IN('retryable','unknown','quarantined') OR outcome_value='retryable' AND error_class_value<>'retryable' OR outcome_value='unknown' AND error_class_value<>'outcome_unknown' OR outcome_value='quarantined' AND error_class_value NOT IN('denied','malformed') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 completion_digest_value:=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),worker_value,lease_token_value,outcome_value,error_class_value),'UTF8'),'sha256');
 result_value:=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition',outcome_value,'error_class',error_class_value);
 UPDATE zasp_runtime_deliveries delivery_row SET disposition=CASE WHEN outcome_value='retryable' THEN 'held' ELSE outcome_value END,lease_expires_at=CASE WHEN outcome_value='retryable' THEN transaction_timestamp() ELSE NULL END,visibility_deadline=CASE WHEN outcome_value='retryable' THEN transaction_timestamp() ELSE NULL END,lease_owner=CASE WHEN outcome_value='retryable' THEN delivery_row.lease_owner ELSE NULL END,lease_token=CASE WHEN outcome_value='retryable' THEN delivery_row.lease_token ELSE NULL END,updated_at=transaction_timestamp()
  WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest,delivery_row.disposition,delivery_row.lease_owner,delivery_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,'held',worker_value,lease_token_value) AND delivery_row.lease_expires_at>transaction_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 IF outcome_value IN('unknown','quarantined') THEN UPDATE zasp_runtime_batch_authorities authority_row SET state=outcome_value,completed_at=transaction_timestamp(),completion_digest=completion_digest_value,completion_result=result_value WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value);END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_release_reconciliation(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, delay_seconds integer, error_code_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 IF delay_seconds NOT BETWEEN 5 AND 300 OR error_code_value NOT IN('not_found','dependency_unavailable','outcome_unknown') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime reconciliation release rejected';END IF;
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state=CASE WHEN work_row.attempt>=100 THEN 'exhausted' ELSE 'retryable' END,available_at=transaction_timestamp()+make_interval(secs=>delay_seconds),last_error_code=CASE WHEN work_row.attempt>=100 THEN 'exhausted' ELSE error_code_value END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL
 WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation,work_row.lease_owner,work_row.lease_token)=(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value) AND work_row.state='leased' AND work_row.lease_expires_at>transaction_timestamp()
 RETURNING jsonb_build_object('batch_id',work_row.batch_id,'generation',work_row.batch_generation,'state',work_row.state,'attempt',work_row.attempt,'error_code',work_row.last_error_code,'replayed',false) INTO result_value;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime reconciliation release rejected';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_runtime_retry_outbox(topic_value text, organization_value text, workspace_value text, environment_value text, outbox_value text, worker_value text, lease_token_value text, retry_after_seconds integer, error_code_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;remaining_count integer;
BEGIN
 IF topic_value<>'runtime-events' OR retry_after_seconds NOT BETWEEN 1 AND 3600 OR error_code_value<>'queue_publish_unknown' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox retry';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox WHERE (organization_id,workspace_id,environment_id,id,topic)=(organization_value,workspace_value,environment_value,outbox_value,topic_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease missing';END IF;
 result:=zasp_discovery_retry_outbox(organization_value,workspace_value,environment_value,outbox_value,worker_value,lease_token_value,retry_after_seconds,error_code_value);
 SELECT count(*) INTO remaining_count FROM zasp_discovery_outbox WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 RETURN result||jsonb_build_object('remaining_count',remaining_count);
END $function$

CREATE OR REPLACE FUNCTION zasp_precision_predecessor.zasp_workflow_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    mutation_response jsonb;
    existing_receipt_id text;
BEGIN
    LOCK TABLE "public"."zasp_workflow_idempotency" IN ROW EXCLUSIVE MODE;
    IF NOT EXISTS (
        SELECT 1
          FROM "public"."zasp_schema_versions" AS release
          JOIN "public"."zasp_schema_metadata" AS schema_marker
            ON schema_marker."key" = 'production_core_schema'
           AND schema_marker."value" = 'production-recovery-v1'
         WHERE release."version" = 27
           AND release."name" = 'production_recovery'
           AND NOT EXISTS (
               SELECT 1 FROM "public"."zasp_schema_versions" AS later_release
                WHERE later_release."version" > 50
           )
    ) THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance release unavailable';
    END IF;
    IF requested_receipt_id IS NOT NULL AND requested_receipt_id <> '' AND length(requested_receipt_id) > 128 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'invalid workflow receipt';
    END IF;
    mutation_response := "public"."zasp_workflow_mutate_v3"(
        mutation, requested_kind, requested_id,
        requested_organization_id, requested_workspace_id, requested_environment_id,
        requested_principal_id, requested_operation, requested_idempotency_key,
        expected_version, requested_intent, requested_body, requested_audit_id, requested_correlation_id
    );
    existing_receipt_id := mutation_response ->> 'receipt_id';
    IF existing_receipt_id IS NOT NULL THEN
        RETURN mutation_response;
    END IF;
    IF requested_receipt_id IS NULL OR requested_receipt_id = '' THEN
        UPDATE "public"."zasp_workflow_idempotency"
           SET "receipt_semantics" = 'receiptless_incompatible'
         WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
           AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
           AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key
           AND NULLIF("response" ->> 'receipt_id', '') IS NULL;
        IF NOT FOUND THEN
            RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
        END IF;
        RETURN mutation_response;
    END IF;
    INSERT INTO "public"."zasp_workflow_receipts" (
        "organization_id", "workspace_id", "environment_id", "principal_id", "receipt_id",
        "operation", "idempotency_key", "intent", "result", "resource_kind", "resource_id",
        "resource_version", "audit_id", "correlation_id"
    ) VALUES (
        requested_organization_id, requested_workspace_id, requested_environment_id, requested_principal_id, requested_receipt_id,
        requested_operation, requested_idempotency_key, requested_intent, mutation_response -> 'body', requested_kind, requested_id,
        (mutation_response ->> 'version')::bigint, mutation_response ->> 'audit_id', mutation_response ->> 'correlation_id'
    );
    mutation_response := mutation_response || jsonb_build_object('receipt_id', requested_receipt_id);
    UPDATE "public"."zasp_workflow_idempotency"
       SET "response" = mutation_response - 'replayed',
           "receipt_semantics" = 'receipt_backed'
     WHERE "organization_id" = requested_organization_id AND "workspace_id" = requested_workspace_id
       AND "environment_id" = requested_environment_id AND "principal_id" = requested_principal_id
       AND "operation" = requested_operation AND "idempotency_key" = requested_idempotency_key;
    IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '55000', MESSAGE = 'workflow receipt provenance marker unavailable';
    END IF;
    RETURN mutation_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_run_context_predecessor.zasp_risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    PERFORM public.zasp_audit_exports_require_ready();
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">53)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    PERFORM public.zasp_audit_exports_require_ready(); RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_run_context_predecessor.zasp_workflow_mutate(mutation text, requested_kind text, requested_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_operation text, requested_idempotency_key text, expected_version bigint, requested_intent jsonb, requested_body jsonb, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
