$function$

CREATE OR REPLACE FUNCTION zasp_sa_export_prior.accounting_1(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, lease_token_value text, input_digest_value bytea, output_digest_value bytea, model_value text, policy_version_value text, candidate_value jsonb, approval_value text, approval_expires_value timestamp with time zone, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE context_envelope jsonb;context_value jsonb;expected_input bytea;run_attempt integer;prior zasp_security_agent_planner_receipts%ROWTYPE;result_value jsonb;response_value jsonb;summary_value text;
BEGIN
  IF input_digest_value IS NULL OR octet_length(input_digest_value)<>32 OR output_digest_value IS NULL OR octet_length(output_digest_value)<>32 OR model_value IS NULL OR length(model_value) NOT BETWEEN 1 AND 128 OR policy_version_value IS NULL OR length(policy_version_value) NOT BETWEEN 1 AND 64 OR jsonb_typeof(candidate_value) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(candidate_value) key) IS DISTINCT FROM ARRAY['steps','summary','version']::text[] OR jsonb_typeof(candidate_value->'version') IS DISTINCT FROM 'number' OR candidate_value->>'version' IS DISTINCT FROM '1' OR jsonb_typeof(candidate_value->'summary') IS DISTINCT FROM 'string' OR jsonb_typeof(candidate_value->'steps') IS DISTINCT FROM 'array' OR jsonb_array_length(candidate_value->'steps')<>1 OR jsonb_typeof(candidate_value->'steps'->0) IS DISTINCT FROM 'object' OR (SELECT array_agg(key ORDER BY key) FROM jsonb_object_keys(candidate_value->'steps'->0) key) IS DISTINCT FROM ARRAY['action','index','target_id']::text[] OR jsonb_typeof(candidate_value->'steps'->0->'index') IS DISTINCT FROM 'number' OR candidate_value->'steps'->0->>'index' IS DISTINCT FROM '0' OR jsonb_typeof(candidate_value->'steps'->0->'action') IS DISTINCT FROM 'string' OR jsonb_typeof(candidate_value->'steps'->0->'target_id') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent planner candidate rejected';END IF;
  summary_value:=candidate_value->>'summary';
  IF length(summary_value) NOT BETWEEN 1 AND 500 OR summary_value~'[[:cntrl:]]' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent planner candidate rejected';END IF;
  SELECT attempt INTO run_attempt FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  SELECT * INTO prior FROM zasp_security_agent_planner_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.run_id,receipt.attempt)=(organization_value,workspace_value,environment_value,run_value,run_attempt);
  IF FOUND THEN IF prior.input_digest<>input_digest_value OR prior.output_digest IS DISTINCT FROM output_digest_value OR (prior.outcome NOT IN('accepted','budget_stopped') OR (prior.outcome='budget_stopped' AND (prior.response ? 'budget_stop' OR prior.response->>'planner_outcome' IS DISTINCT FROM 'budget_stopped'))) OR prior.model<>model_value OR prior.policy_version<>policy_version_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent planner replay conflict';END IF;RETURN prior.response||jsonb_build_object('replayed',true);END IF;
  context_envelope:=zasp_security_agent_planner_context(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value);IF context_envelope ? 'budget_stop' THEN result_value:=zasp_security_agent_budget_stop_result(organization_value,workspace_value,environment_value,run_value,'prepare');ELSE context_value:=context_envelope->'context';expected_input:=decode(substring(context_envelope->>'input_digest' FROM 8),'hex');
  IF expected_input<>input_digest_value OR candidate_value->'steps'->0->>'action' IS DISTINCT FROM context_value->'allowed_actions'->>0 OR candidate_value->'steps'->0->>'target_id' IS DISTINCT FROM context_value->'allowed_targets'->>0 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent planner authority changed';END IF;
  result_value:=zasp_security_agent_prepare_run_v24(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value,approval_value,approval_expires_value,audit_value,correlation_value);
  END IF;
  response_value:=result_value||jsonb_build_object('planner_outcome',CASE WHEN result_value->>'state'='needs_human' THEN 'budget_stopped' ELSE 'accepted' END,'planner_summary',summary_value,'replayed',false);
  INSERT INTO zasp_security_agent_planner_receipts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,output_digest,outcome,model,policy_version,response) VALUES(organization_value,workspace_value,environment_value,run_value,run_attempt,input_digest_value,output_digest_value,CASE WHEN result_value->>'state'='needs_human' THEN 'budget_stopped' ELSE 'accepted' END,model_value,policy_version_value,response_value);
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_sa_export_prior.accounting_10(o text, w text, e text, r text, worker_value text, lease_value text, input_value bytea, output_value bytea, model_value text, policy_value text, error_value text, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE context_value jsonb;response_value jsonb;event_value jsonb;run_row public.zasp_security_agent_runs%ROWTYPE;
 prior public.zasp_security_agent_planner_receipts%ROWTYPE;outcome_value text;
BEGIN
 IF NOT COALESCE(public.zasp_sa_export_principal_ready('zasp_security_agent_worker') AND public.zasp_valid_product_id(o)
  AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND length(worker_value) BETWEEN 1 AND 128 AND length(lease_value) BETWEEN 16 AND 128,false) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='existing test failure principal rejected';
 END IF;
 IF NOT public.zasp_sa_export_guard() THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test failure release unavailable';
 END IF;
 IF NOT COALESCE(octet_length(input_value)=32 AND (output_value IS NULL OR octet_length(output_value)=32)
  AND length(model_value) BETWEEN 1 AND 128 AND length(policy_value) BETWEEN 1 AND 64
  AND error_value IN('planner_unavailable','planner_rejected') AND (error_value<>'planner_rejected' OR output_value IS NOT NULL)
  AND public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test failure input rejected';
 END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test failure run changed';END IF;
 SELECT * INTO prior FROM public.zasp_security_agent_planner_receipts WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,run_row.attempt);
 IF FOUND THEN
  IF prior.input_digest IS DISTINCT FROM input_value OR prior.output_digest IS DISTINCT FROM output_value
   OR prior.model IS DISTINCT FROM model_value OR prior.policy_version IS DISTINCT FROM policy_value
   OR prior.outcome NOT IN(error_value,'budget_stopped')
   OR (prior.outcome='budget_stopped' AND NOT (prior.response ? 'budget_stop')) THEN
   RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='existing test failure replay conflict';
  END IF;
  IF prior.outcome='budget_stopped' THEN RETURN prior.response;END IF;
  RETURN prior.response||jsonb_build_object('replayed',true);
 END IF;
 context_value:=public.zasp_sa_export_planner_context(o,w,e,r,worker_value,lease_value);
 BEGIN
  IF context_value ? 'budget_stop' THEN
   response_value:=context_value;outcome_value:='budget_stopped';
  ELSE
   IF context_value->>'input_digest' IS DISTINCT FROM 'sha256:'||encode(input_value,'hex') THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test failure authority changed';
   END IF;
   outcome_value:=error_value;
   response_value:=jsonb_build_object('run_id',r,'state','failed','version',run_row.version+1,'error_code',error_value,'replayed',false);
  END IF;
  INSERT INTO public.zasp_security_agent_planner_receipts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,output_digest,outcome,model,policy_version,response)
  VALUES(o,w,e,r,run_row.attempt,input_value,output_value,outcome_value,model_value,policy_value,response_value);
  IF outcome_value='budget_stopped' THEN RETURN response_value;END IF;
  event_value:=jsonb_build_object('run_id',r,'attempt',run_row.attempt,'error_code',error_value,'input_digest','sha256:'||encode(input_value,'hex'),
   'output_digest',CASE WHEN output_value IS NULL THEN NULL ELSE 'sha256:'||encode(output_value,'hex') END,'model',model_value,'policy_version',policy_value);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
