CREATE OR REPLACE FUNCTION zasp_security_agent_budgets_predecessor.zasp_security_agent_expire_approvals_v28(worker_value text, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item record;expired_value integer:=0;approval_version_value bigint;body_value jsonb;audit_value text;correlation_value text;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_worker') OR length(worker_value) NOT BETWEEN 1 AND 128 OR limit_value NOT BETWEEN 1 AND 25 THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent approval expiry rejected';
  END IF;
  FOR item IN
    SELECT approval.organization_id,approval.workspace_id,approval.environment_id,approval.approval_id,approval.run_id,approval.step_id
    FROM zasp_security_agent_approvals approval
    JOIN zasp_security_agent_runs run ON (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(approval.organization_id,approval.workspace_id,approval.environment_id,approval.run_id)
    WHERE approval.state='pending' AND approval.expires_at<=transaction_timestamp() AND run.state='waiting_approval'
    ORDER BY approval.expires_at,approval.organization_id,approval.workspace_id,approval.environment_id,approval.approval_id
    FOR UPDATE OF approval SKIP LOCKED LIMIT limit_value
  LOOP
    PERFORM 1 FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id,run.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,'waiting_approval') FOR UPDATE;
    IF NOT FOUND THEN CONTINUE;END IF;
    UPDATE zasp_security_agent_approvals approval SET state='expired',version=approval.version+1,decided_at=transaction_timestamp()
    WHERE (approval.organization_id,approval.workspace_id,approval.environment_id,approval.approval_id,approval.state)=(item.organization_id,item.workspace_id,item.environment_id,item.approval_id,'pending') AND approval.expires_at<=transaction_timestamp()
    RETURNING approval.version INTO approval_version_value;
    IF NOT FOUND THEN CONTINUE;END IF;
    UPDATE zasp_security_agent_steps step SET state='cancelled',version=step.version+1,updated_at=transaction_timestamp()
    WHERE (step.organization_id,step.workspace_id,step.environment_id,step.run_id,step.step_id,step.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,'waiting_approval');
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent approval step drift';END IF;
    UPDATE zasp_security_agent_runs run SET state='needs_human',version=run.version+1,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_error_code='approval_expired',updated_at=transaction_timestamp(),completed_at=transaction_timestamp()
    WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id,run.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,'waiting_approval');
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent approval run drift';END IF;
    body_value:=jsonb_build_object('approval_id',item.approval_id,'run_id',item.run_id,'step_id',item.step_id,'state','expired','version',approval_version_value);
    audit_value:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_audit',item.approval_id||chr(31)||'expired');
    correlation_value:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_correlation',item.approval_id||chr(31)||'expired');
    INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,approval_id,actor_id,event_kind,event_digest,body)
    VALUES(item.organization_id,item.workspace_id,item.environment_id,audit_value,correlation_value,item.run_id,item.step_id,item.approval_id,worker_value,'approval_expired',digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
    expired_value:=expired_value+1;
  END LOOP;
  RETURN jsonb_build_object('expired',expired_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_security_agent_budgets_predecessor.zasp_security_agent_fail_approval_notification(organization_value text, workspace_value text, environment_value text, delivery_value text, lease_token_value text, payload_digest_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE notification zasp_security_agent_approval_notifications%ROWTYPE;
BEGIN
 IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(delivery_value) OR lease_token_value!~'^[0-9a-f]{64}$' OR payload_digest_value!~'^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='approval notification failure rejected';END IF;
 SELECT * INTO notification FROM zasp_security_agent_approval_notifications row_value WHERE (row_value.organization_id,row_value.workspace_id,row_value.environment_id,row_value.delivery_id)=(organization_value,workspace_value,environment_value,delivery_value) FOR UPDATE;
 IF NOT FOUND OR notification.state<>'leased' OR notification.lease_token<>lease_token_value OR notification.lease_expires_at<=transaction_timestamp() OR notification.payload_digest<>decode(substr(payload_digest_value,8),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='approval notification lease lost';END IF;
 IF notification.attempt>=10 THEN
  UPDATE zasp_security_agent_approval_notifications SET state='exhausted',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,delivery_value);
  RETURN jsonb_build_object('transition','exhausted');
 END IF;
 UPDATE zasp_security_agent_approval_notifications SET state='retryable',available_at=transaction_timestamp()+make_interval(secs=>LEAST(60,attempt*attempt)),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,delivery_id)=(organization_value,workspace_value,environment_value,delivery_value);
 RETURN jsonb_build_object('transition','retryable');
END
$function$

CREATE OR REPLACE FUNCTION zasp_security_agent_budgets_predecessor.zasp_security_agent_fail_planner(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, lease_token_value text, input_digest_value bytea, output_digest_value bytea, model_value text, policy_version_value text, error_code_value text, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE context_envelope jsonb;expected_input bytea;run_row zasp_security_agent_runs%ROWTYPE;prior zasp_security_agent_planner_receipts%ROWTYPE;response_value jsonb;event_digest_value bytea;
BEGIN
  IF input_digest_value IS NULL OR octet_length(input_digest_value)<>32 OR output_digest_value IS NOT NULL AND octet_length(output_digest_value)<>32 OR error_code_value IS NULL OR error_code_value NOT IN('planner_unavailable','planner_rejected') OR error_code_value='planner_rejected' AND output_digest_value IS NULL OR model_value IS NULL OR length(model_value) NOT BETWEEN 1 AND 128 OR policy_version_value IS NULL OR length(policy_version_value) NOT BETWEEN 1 AND 64 OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent planner failure rejected';END IF;
  SELECT * INTO run_row FROM zasp_security_agent_runs run WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  SELECT * INTO prior FROM zasp_security_agent_planner_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.run_id,receipt.attempt)=(organization_value,workspace_value,environment_value,run_value,run_row.attempt);
  IF FOUND THEN IF prior.input_digest<>input_digest_value OR prior.output_digest IS DISTINCT FROM output_digest_value OR prior.outcome<>error_code_value OR prior.model<>model_value OR prior.policy_version<>policy_version_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent planner replay conflict';END IF;RETURN prior.response||jsonb_build_object('replayed',true);END IF;
  context_envelope:=zasp_security_agent_planner_context(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value);expected_input:=decode(substring(context_envelope->>'input_digest' FROM 8),'hex');
  IF expected_input<>input_digest_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent planner authority changed';END IF;
  UPDATE zasp_security_agent_runs run SET state='failed',last_error_code=error_code_value,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=run.version+1,updated_at=transaction_timestamp(),completed_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id,run.state,run.lease_owner,run.lease_token)=(organization_value,workspace_value,environment_value,run_value,'planning',worker_value,lease_token_value) AND run.lease_expires_at>transaction_timestamp() RETURNING * INTO run_row;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent planner lease lost';END IF;
  response_value:=jsonb_build_object('run_id',run_value,'state','failed','version',run_row.version,'error_code',error_code_value,'replayed',false);event_digest_value:=digest(convert_to(jsonb_build_object('run_id',run_value,'attempt',run_row.attempt,'input_digest','sha256:'||encode(input_digest_value,'hex'),'output_digest',CASE WHEN output_digest_value IS NULL THEN NULL ELSE 'sha256:'||encode(output_digest_value,'hex') END,'error_code',error_code_value,'model',model_value,'policy_version',policy_version_value)::text,'UTF8'),'sha256');
