CREATE OR REPLACE FUNCTION zasp_temporal71.adapter_protocol(o text, w text, e text, r text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE parent_id text;BEGIN
 PERFORM zasp_temporal71.require_principal('zasp_red_team_adapter');
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked protocol unavailable';END IF;
 SELECT l.run_id INTO parent_id FROM public.zasp_security_agent_test_links l JOIN public.zasp_security_agent_runs p ON (p.organization_id,p.workspace_id,p.environment_id,p.run_id)=(l.organization_id,l.workspace_id,l.environment_id,l.run_id)
 WHERE (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id)=(o,w,e,r) AND NOT zasp_temporal66.is_temporal(o,w,e,l.run_id);
 IF parent_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked protocol unavailable';END IF;
 IF zasp_temporal71.legacy_parent(o,w,e,parent_id) THEN RETURN jsonb_build_object('protocol','legacy_single_test');END IF;
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_runs p JOIN public.zasp_security_agent_plans plan USING(organization_id,workspace_id,environment_id,run_id)
 JOIN public.zasp_sa_multistep_runs m USING(organization_id,workspace_id,environment_id,run_id)
 JOIN public.zasp_security_agent_definition_versions d ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version)=(p.organization_id,p.workspace_id,p.environment_id,p.definition_id,p.definition_version)
 WHERE (p.organization_id,p.workspace_id,p.environment_id,p.run_id)=(o,w,e,parent_id) AND plan.plan->'contract_version'='61'::jsonb AND plan.plan_hash=p.plan_hash AND plan.plan_hash=digest(convert_to(plan.plan::text,'UTF8'),'sha256') AND d.definition_digest=digest(convert_to(d.definition::text,'UTF8'),'sha256')) THEN RETURN jsonb_build_object('protocol','retained_ordered');END IF;
 RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked protocol unavailable';
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body01(o text, w text, e text, r text, expected_version bigint, worker_value text, lease_value bytea, input_value bytea)
 RETURNS public.zasp_red_team_runs
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;link_row public.zasp_security_agent_test_links%ROWTYPE;linked boolean;outcome_value text;checksum_value text;fingerprint_value text;original_lease_expires_at timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked cancellation input rejected';END IF;
 IF worker_value IS NULL THEN
  IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api') AND expected_version BETWEEN 1 AND 999999 AND lease_value IS NULL AND input_value IS NULL,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked cancellation principal rejected';END IF;
 ELSE
  IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker') AND worker_value~'^[a-z][a-z0-9.-]{2,127}$' AND octet_length(lease_value)=32 AND octet_length(input_value)=32 AND expected_version IS NULL,false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked cancellation principal rejected';END IF;
 END IF;
 SELECT value INTO checksum_value FROM public.zasp_schema_metadata WHERE key='production_security_agent_existing_tests_checksum';
 SELECT value INTO fingerprint_value FROM public.zasp_schema_metadata WHERE key='production_security_agent_existing_tests_fingerprint';
 IF NOT COALESCE(zasp_temporal71.guard1(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked cancellation release unavailable';END IF;
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r);
 linked:=FOUND;
 IF linked THEN
  PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
  PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
  PERFORM 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link_row.run_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation parent unavailable';END IF;
  SELECT * INTO STRICT link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id,run_id,step_id)=(o,w,e,r,link_row.run_id,link_row.step_id) FOR UPDATE;
 ELSIF worker_value IS NOT NULL THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation association unavailable';
 END IF;
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='red team run not found';END IF;
 IF run_row.state IN('complete','failed','cancelled') OR worker_value IS NULL AND run_row.version IS DISTINCT FROM expected_version
  OR worker_value IS NOT NULL AND (run_row.state<>'leased' OR run_row.worker_id IS DISTINCT FROM worker_value OR run_row.lease_token IS DISTINCT FROM lease_value OR run_row.input_digest IS DISTINCT FROM input_value OR NOT run_row.cancel_requested OR run_row.lease_expires_at<=clock_timestamp()) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation authority changed';
 END IF;
 original_lease_expires_at:=run_row.lease_expires_at;
 IF linked THEN
  SELECT * INTO STRICT run_row FROM public.zasp_production_security_agent_existing_tests_cancel_transition(o,w,e,r);
 ELSE
  -- Preserve the legacy human API's queued/retryable versus leased behavior.
  UPDATE public.zasp_red_team_runs SET version=version+1,cancel_requested=true,state=CASE WHEN state IN('queued','retryable') THEN 'cancelled' ELSE state END,completed_at=CASE WHEN state IN('queued','retryable') THEN transaction_timestamp() ELSE completed_at END,error_code=CASE WHEN state IN('queued','retryable') THEN 'cancelled' ELSE error_code END,updated_at=transaction_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO run_row;
 END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked cancellation release unavailable';END IF;
 IF worker_value IS NOT NULL AND (original_lease_expires_at IS NULL OR original_lease_expires_at<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked cancellation lease expired';END IF;
 RETURN run_row;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body02(o text, w text, e text, r text, attempt_value integer, lease_value bytea, category_value text, request_digest_value bytea, status_value integer, response_digest_value bytea, protected_value boolean, credential_version_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;prior public.zasp_security_agent_test_invocations%ROWTYPE;
BEGIN
 IF NOT public.zasp_red_team_principal_ready('zasp_red_team_adapter') OR NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND attempt_value BETWEEN 1 AND 5 AND octet_length(lease_value)=32 AND octet_length(request_digest_value)=32 AND octet_length(response_digest_value)=32 AND octet_length(credential_version_value)=32 AND credential_version_value<>decode(repeat('00',32),'hex')
  AND category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information')
  AND status_value BETWEEN 200 AND 599 AND (status_value=200 AND protected_value IS NOT NULL OR status_value<>200 AND protected_value IS NULL),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked invocation response rejected';
 END IF;
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation run unavailable';END IF;
 SELECT * INTO prior FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,attempt,category)=(o,w,e,r,attempt_value,category_value) FOR UPDATE;
 IF NOT FOUND OR prior.input_digest IS DISTINCT FROM run_row.input_digest OR prior.request_digest IS DISTINCT FROM request_digest_value OR prior.lease_digest IS DISTINCT FROM digest(lease_value,'sha256') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation response association rejected';
 END IF;
 IF prior.state='completed' THEN
  IF prior.http_status IS DISTINCT FROM status_value OR prior.response_digest IS DISTINCT FROM response_digest_value OR prior.protected IS DISTINCT FROM protected_value OR prior.credential_version_digest IS DISTINCT FROM credential_version_value THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation response conflict';
  END IF;
 ELSE
  -- This records a known response, including one arriving after cancellation or
  -- lease expiry. It grants no new execution authority and changes no run state.
  UPDATE public.zasp_security_agent_test_invocations SET state='completed',completed_at=clock_timestamp(),http_status=status_value,response_digest=response_digest_value,protected=protected_value,credential_version_digest=credential_version_value
  WHERE (organization_id,workspace_id,environment_id,test_run_id,attempt,category,state)=(o,w,e,r,attempt_value,category_value,'started');
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation response changed';END IF;
 END IF;
 RETURN public.zasp_production_security_agent_existing_tests_invocation_receipt(o,w,e,r,attempt_value,category_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body02(o text, w text, e text, r text, attempt_value integer, lease_value bytea, category_value text, request_digest_value bytea, status_value integer, response_digest_value bytea, protected_value boolean, credential_version_value bytea, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_adapter'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 result_value:=zasp_temporal71.body02(o,w,e,r,attempt_value,lease_value,category_value,request_digest_value,status_value,response_digest_value,protected_value,credential_version_value);
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body03(o text, w text, e text, r text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE link_row public.zasp_security_agent_test_links%ROWTYPE;parent_row public.zasp_security_agent_runs%ROWTYPE;
 budget_row public.zasp_security_agent_run_budgets%ROWTYPE;control_row record;control_count integer:=0;binding_value jsonb;
BEGIN
 -- Shared only by separately role-checked claim and adapter entrypoints.
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_adapter') OR public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked invocation principal rejected';END IF;
 -- Discover only the parent identity before locks. Revalidate the exact link
 -- after organization, parent, budget and step authority have been locked.
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation parent missing';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation organization unavailable';END IF;
 SELECT * INTO parent_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id,state)=(o,w,e,link_row.run_id,'running') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation parent stopped';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_authorize_invocation(o,w,e,link_row.run_id,link_row.step_id);
 SELECT * INTO budget_row FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version)=(o,w,e,link_row.run_id,parent_row.definition_id,parent_row.definition_version) FOR UPDATE;
 IF NOT FOUND OR budget_row.stop_reason IS NOT NULL OR budget_row.deadline_at IS NULL OR budget_row.deadline_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation budget stopped';END IF;
 PERFORM 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state)=(o,w,e,link_row.run_id,link_row.step_id,link_row.action_key,link_row.input_digest,'executing') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation step stopped';END IF;
 PERFORM 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state)=(o,w,e,link_row.run_id,link_row.step_id,link_row.action_key,link_row.input_digest,'pending') FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation effect stopped';END IF;
 PERFORM 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,link_row.run_id,link_row.step_id,link_row.action_key,link_row.input_digest) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation reservation missing';END IF;
 PERFORM 1 FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,link_row.run_id,link_row.step_id,link_row.action_key,link_row.input_digest) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation parent changed';END IF;
 FOR control_row IN SELECT * FROM public.zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key)=('*','*','*','*') OR (organization_id,workspace_id,environment_id)=(o,w,e) AND action_key IN('*',link_row.action_key) ORDER BY organization_id,workspace_id,environment_id,action_key FOR SHARE LOOP
  control_count:=control_count+1;
  IF NOT control_row.execution_enabled THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation execution disabled';END IF;
 END LOOP;
 binding_value:=zasp_temporal71.body21(o,w,e,parent_row.definition_id,parent_row.definition_version);
 IF binding_value IS DISTINCT FROM jsonb_build_object('definition_id',link_row.test_definition_id,'definition_version',link_row.test_definition_version,'target_id',link_row.target_id,'target_kind',link_row.target_kind) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation target changed';
 END IF;
 IF control_count<>3 OR budget_row.deadline_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation authority unavailable';END IF;
 RETURN budget_row.deadline_at;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body04(o text, w text, e text, target_value text, target_kind_value text, r text, lease_value bytea, category_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;run_row public.zasp_red_team_runs%ROWTYPE;parent_deadline timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_adapter'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(target_value) AND octet_length(lease_value)=32 AND target_kind_value IN('agent_endpoint','mcp_server','coding_agent') AND category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked invocation resolution rejected';END IF;
 parent_deadline:=zasp_temporal71.body03(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR run_row.state<>'leased' OR run_row.lease_token IS DISTINCT FROM lease_value OR run_row.cancel_requested OR run_row.attempt NOT BETWEEN 1 AND 5 OR run_row.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease rejected';END IF;
 PERFORM 1 FROM public.zasp_security_agent_test_links l JOIN public.zasp_red_team_definitions d ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version,d.target_id,d.target_kind)=(l.organization_id,l.workspace_id,l.environment_id,l.test_definition_id,l.test_definition_version,l.target_id,l.target_kind)
 WHERE (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id,l.test_definition_id,l.test_definition_version,l.target_id,l.target_kind)=(o,w,e,r,run_row.definition_id,run_row.definition_version,target_value,target_kind_value) AND d.enabled AND d.categories ? category_value FOR SHARE OF l,d;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation association rejected';END IF;
 result_value:=public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,target_value,target_kind_value,run_row.definition_id,run_row.definition_version);
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r) AND target_resolution IS DISTINCT FROM result_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation target snapshot changed';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 parent_deadline:=zasp_temporal71.body03(o,w,e,r);
 IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease expired';END IF;
 RETURN result_value->'binding';
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body05(o text, w text, e text, r text, lease_value bytea, category_value text, request_digest_value bytea, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;parent_deadline timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_adapter'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 result_value:=zasp_temporal71.body06(o,w,e,r,lease_value,category_value,request_digest_value);
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test invocation release unavailable';END IF;
 -- Release identity checks can take time. Recheck held current authority after
 -- them, not only inside the core before those checks began.
 parent_deadline:=zasp_temporal71.body03(o,w,e,r);
 PERFORM 1 FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND state='leased' AND lease_token=lease_value AND NOT cancel_requested AND attempt BETWEEN 1 AND 5 AND lease_expires_at>clock_timestamp() AND parent_deadline>clock_timestamp();
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease expired';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body06(o text, w text, e text, r text, lease_value bytea, category_value text, request_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;link_row public.zasp_security_agent_test_links%ROWTYPE;prior public.zasp_security_agent_test_invocations%ROWTYPE;parent_deadline timestamptz;target_resolution_value jsonb;
BEGIN
 IF NOT public.zasp_red_team_principal_ready('zasp_red_team_adapter') OR NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND octet_length(lease_value)=32 AND octet_length(request_digest_value)=32
  AND category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information'),false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked invocation input rejected';
 END IF;
 parent_deadline:=zasp_temporal71.body03(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR run_row.state<>'leased' OR run_row.lease_token IS DISTINCT FROM lease_value OR run_row.lease_expires_at<=clock_timestamp() OR run_row.cancel_requested OR run_row.attempt NOT BETWEEN 1 AND 5 THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease rejected';
 END IF;
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id,test_definition_id,test_definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation association rejected';END IF;
 PERFORM 1 FROM public.zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,target_id,target_kind)=(o,w,e,link_row.test_definition_id,link_row.test_definition_version,link_row.target_id,link_row.target_kind) AND enabled AND categories ? category_value FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation definition rejected';END IF;
 target_resolution_value:=public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,link_row.target_id,link_row.target_kind,link_row.test_definition_id,link_row.test_definition_version);
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r) AND target_resolution IS DISTINCT FROM target_resolution_value) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation target snapshot changed';
 END IF;
 SELECT * INTO prior FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,r,category_value) FOR UPDATE;
 IF FOUND AND prior.state='completed' THEN
  IF prior.attempt<>run_row.attempt OR prior.input_digest IS DISTINCT FROM run_row.input_digest OR prior.request_digest IS DISTINCT FROM request_digest_value OR prior.lease_digest IS DISTINCT FROM digest(lease_value,'sha256') THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation replay conflict';
  END IF;
  PERFORM zasp_temporal71.body03(o,w,e,r);
  IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease expired';END IF;
  RETURN public.zasp_production_security_agent_existing_tests_invocation_receipt(o,w,e,r,prior.attempt,category_value);
 END IF;
 -- A different category/attempt cannot proceed while any earlier start lacks
 -- a terminal receipt. A known receipt replay above never sends network I/O.
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,state)=(o,w,e,r,'started')) THEN
  RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked invocation outcome unknown';
 END IF;
 INSERT INTO public.zasp_security_agent_test_invocations(organization_id,workspace_id,environment_id,test_run_id,attempt,category,input_digest,request_digest,target_resolution,lease_digest,state)
 VALUES(o,w,e,r,run_row.attempt,category_value,run_row.input_digest,request_digest_value,target_resolution_value,digest(lease_value,'sha256'),'started');
 PERFORM zasp_temporal71.body03(o,w,e,r);
 IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked invocation lease expired';END IF;
 RETURN jsonb_build_object('state','started','attempt',run_row.attempt,'category',category_value,'input_digest',encode(run_row.input_digest,'hex'),'request_digest',encode(request_digest_value,'hex'),'target_comparison',target_resolution_value->'comparison','target_binding',target_resolution_value->'binding','target_provenance',target_resolution_value->'provenance');
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body08(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;parent_state text;test_run text;run_row public.zasp_red_team_runs%ROWTYPE;outcome_value text;changed boolean:=false;
BEGIN
 deadline:=zasp_temporal71.body12(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 SELECT state INTO STRICT parent_state FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT test_run_id INTO STRICT test_run FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO STRICT run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,test_run) FOR UPDATE;
 IF parent_state IN('cancelled','failed','inconclusive','needs_human') AND run_row.state NOT IN('complete','failed','cancelled') THEN
  SELECT * INTO STRICT run_row FROM public.zasp_production_security_agent_existing_tests_cancel_transition(o,w,e,test_run);
  changed:=true;
 END IF;
 SELECT cancellation_outcome INTO STRICT outcome_value FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='stopped test reconciliation expired';END IF;
 RETURN jsonb_build_object('test_run_id',test_run,'state',run_row.state,'cancellation_outcome',outcome_value,'changed',changed,'generation',generation_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body09(o text, w text, e text, worker_value text, lease_value bytea, seconds_value integer, limit_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;link_row public.zasp_security_agent_test_links%ROWTYPE;result_value jsonb:='[]'::jsonb;
BEGIN
 PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF NOT COALESCE(seconds_value BETWEEN 10 AND 300 AND limit_value BETWEEN 1 AND 25,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler claim bounds rejected';END IF;
 -- Follow existing organization-before-parent-before-link order; a busy tenant
 -- or parent is skipped instead of blocking a polling worker.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0)) THEN RETURN result_value;END IF;
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE SKIP LOCKED;
 IF NOT FOUND THEN RETURN result_value;END IF;
 FOR candidate IN SELECT l.run_id,l.step_id FROM public.zasp_security_agent_test_links l
  JOIN public.zasp_security_agent_runs p ON (p.organization_id,p.workspace_id,p.environment_id,p.run_id)=(l.organization_id,l.workspace_id,l.environment_id,l.run_id)
  WHERE (l.organization_id,l.workspace_id,l.environment_id)=(o,w,e) AND zasp_temporal71.legacy_parent(l.organization_id,l.workspace_id,l.environment_id,l.run_id)
   AND (l.reconcile_state='pending' AND l.reconcile_next_at<=clock_timestamp() OR l.reconcile_state='leased' AND l.reconcile_expires_at<=clock_timestamp())
  ORDER BY l.reconcile_next_at,l.run_id,l.step_id LIMIT limit_value FOR UPDATE OF p SKIP LOCKED LOOP
  PERFORM 1 FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,candidate.run_id,candidate.step_id)
   AND (reconcile_state='pending' AND reconcile_next_at<=clock_timestamp() OR reconcile_state='leased' AND reconcile_expires_at<=clock_timestamp()) FOR UPDATE SKIP LOCKED;
  CONTINUE WHEN NOT FOUND;
  UPDATE public.zasp_security_agent_test_links SET reconcile_state='leased',reconcile_version=CASE WHEN reconcile_version=1000000 THEN 1 ELSE reconcile_version+1 END,reconcile_generation=gen_random_uuid(),reconcile_worker=worker_value,reconcile_token=digest(lease_value,'sha256'),reconcile_expires_at=clock_timestamp()+make_interval(secs=>seconds_value)
   WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,candidate.run_id,candidate.step_id) RETURNING * INTO link_row;
  result_value:=result_value||jsonb_build_array(jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',link_row.run_id,'step_id',link_row.step_id,'test_run_id',link_row.test_run_id,'version',link_row.reconcile_version,'generation',link_row.reconcile_generation,'lease_expires_at',to_char(link_row.reconcile_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
 END LOOP;
 PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (item->>'lease_expires_at')::timestamptz<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler claim expired';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body10(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;value jsonb;
BEGIN
 deadline:=zasp_temporal71.body12(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 value:=public.zasp_production_security_agent_existing_tests_evidence_snapshot(o,w,e,r,s);
 PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler read expired';END IF;
 RETURN jsonb_build_object('version',version_value,'generation',generation_value,'lease_expires_at',to_char(deadline AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'snapshot',value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body11(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, seconds_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;renewed timestamptz;
BEGIN
 IF NOT COALESCE(seconds_value BETWEEN 10 AND 300,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler renewal bounds rejected';END IF;
 deadline:=zasp_temporal71.body12(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 UPDATE public.zasp_security_agent_test_links SET reconcile_expires_at=clock_timestamp()+make_interval(secs=>seconds_value)
  WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) RETURNING reconcile_expires_at INTO renewed;
 PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() OR renewed<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler renewal expired';END IF;
 RETURN jsonb_build_object('run_id',r,'step_id',s,'version',version_value,'generation',generation_value,'lease_expires_at',to_char(renewed AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body12(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, expected_checksum text, expected_fingerprint text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;
BEGIN
 PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF NOT COALESCE(public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(s) AND version_value BETWEEN 1 AND 1000000 AND generation_value<>'00000000-0000-0000-0000-000000000000'::uuid,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler ownership input rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler organization changed';END IF;
 PERFORM 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler parent changed';END IF;
 SELECT reconcile_expires_at INTO deadline FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id,reconcile_state,reconcile_worker,reconcile_token,reconcile_version,reconcile_generation)=(o,w,e,r,s,'leased',worker_value,digest(lease_value,'sha256'),version_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler ownership changed';END IF;
 RETURN deadline;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body13(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, delay_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE deadline timestamptz;next_value timestamptz;
BEGIN
 IF NOT COALESCE(delay_value BETWEEN 10 AND 300 AND version_value BETWEEN 1 AND 1000000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler release bounds rejected';END IF;
 deadline:=zasp_temporal71.body12(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 UPDATE public.zasp_security_agent_test_links SET reconcile_state='pending',reconcile_version=LEAST(reconcile_version+1,1000000),reconcile_worker=NULL,reconcile_token=NULL,reconcile_expires_at=NULL,reconcile_next_at=clock_timestamp()+make_interval(secs=>delay_value)
  WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) RETURNING reconcile_next_at INTO next_value;
 PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test reconciler release expired';END IF;
 RETURN jsonb_build_object('run_id',r,'step_id',s,'version',LEAST(version_value+1,1000000),'generation',generation_value,'state','pending','next_check_at',to_char(next_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body14(after_o text, after_w text, after_e text, worker_value text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker') AND NOT pg_has_role(session_user,'zasp_security_agent_api','MEMBER'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test reconciler principal rejected';END IF;
 IF NOT COALESCE(worker_value~'^[a-z][a-z0-9.-]{2,127}$'
  AND ((after_o,after_w,after_e)=('','','') OR public.zasp_valid_product_id(after_o) AND public.zasp_valid_product_id(after_w) AND public.zasp_valid_product_id(after_e) AND after_o<>after_w AND after_o<>after_e AND after_w<>after_e),false)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test reconciler scope input rejected';END IF;
 IF NOT zasp_temporal71.guard1(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='test reconciler release unavailable';END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',s.organization_id,'workspace_id',s.workspace_id,'environment_id',s.environment_id)),'[]'::jsonb) INTO result_value
 FROM (
  SELECT DISTINCT l.organization_id COLLATE "C" AS organization_id,l.workspace_id COLLATE "C" AS workspace_id,l.environment_id COLLATE "C" AS environment_id
  FROM public.zasp_security_agent_test_links l JOIN public.zasp_security_agent_org_admissions a USING(organization_id)
  WHERE zasp_temporal71.legacy_parent(l.organization_id,l.workspace_id,l.environment_id,l.run_id) AND (l.organization_id COLLATE "C",l.workspace_id COLLATE "C",l.environment_id COLLATE "C")>(after_o COLLATE "C",after_w COLLATE "C",after_e COLLATE "C")
   AND (l.reconcile_state='pending' AND l.reconcile_next_at<=clock_timestamp() OR l.reconcile_state='leased' AND l.reconcile_expires_at<=clock_timestamp())
  ORDER BY organization_id,workspace_id,environment_id LIMIT 1
 ) s;
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker') AND NOT pg_has_role(session_user,'zasp_security_agent_api','MEMBER'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test reconciler principal rejected';END IF;
 IF NOT zasp_temporal71.guard1(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='test reconciler release unavailable';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body15(o text, w text, e text, r text, s text, worker_value text, lease_value bytea, version_value bigint, generation_value uuid, expected_snapshot jsonb, proof_bytes bytea, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE link_row public.zasp_security_agent_test_links%ROWTYPE;parent_row public.zasp_security_agent_runs%ROWTYPE;step_row public.zasp_security_agent_steps%ROWTYPE;effect_row public.zasp_security_agent_effects%ROWTYPE;test_row public.zasp_red_team_runs%ROWTYPE;
 deadline timestamptz;snapshot_value jsonb;proof_json json;proof_value jsonb;proof_digest bytea;receipt jsonb;outcome_value text;reason_value text;step_state text;effect_state text;parent_state text;unknown_value boolean;recover_value boolean;stopped boolean;audit_value text;
BEGIN
 PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF NOT COALESCE(public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(s) AND version_value BETWEEN 1 AND 1000000 AND generation_value<>'00000000-0000-0000-0000-000000000000'::uuid AND octet_length(proof_bytes) BETWEEN 1 AND 65536 AND jsonb_typeof(expected_snapshot)='object',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test settlement input rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement organization missing';END IF;
 SELECT * INTO parent_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement parent missing';END IF;
 SELECT * INTO link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement link missing';END IF;
 proof_digest:=digest(proof_bytes,'sha256');
 IF link_row.reconcile_state='settled' THEN
  IF NOT COALESCE(link_row.reconcile_settlement->>'worker'=worker_value AND link_row.reconcile_settlement->>'token_digest'=encode(digest(lease_value,'sha256'),'hex') AND link_row.reconcile_settlement->'claim_version'=to_jsonb(version_value)
   AND link_row.reconcile_settlement->'claim_generation'=to_jsonb(generation_value) AND link_row.reconcile_settlement->'snapshot'=expected_snapshot AND link_row.reconcile_settlement->>'proof_hex'=encode(proof_bytes,'hex'),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement replay conflict';END IF;
  PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
  RETURN link_row.reconcile_settlement->'receipt';
 END IF;
 deadline:=zasp_temporal71.body12(o,w,e,r,s,worker_value,lease_value,version_value,generation_value,expected_checksum,expected_fingerprint);
 SELECT * INTO step_row FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,s,link_row.action_key,link_row.input_digest) FOR UPDATE;
 IF NOT FOUND OR step_row.state NOT IN('executing','verifying','cancelled','failed','inconclusive') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement step changed';END IF;
 SELECT * INTO effect_row FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,s,link_row.action_key,link_row.input_digest) FOR UPDATE;
 IF NOT FOUND OR effect_row.state NOT IN('pending','known_failure','unknown_outcome') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement effect changed';END IF;
 stopped:=parent_row.state IN('cancelled','failed','inconclusive','needs_human');
 IF NOT stopped AND parent_row.state NOT IN('running','verifying') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement parent state changed';END IF;
 -- Completion locks test run before journal; holding run locks freezes both.
 -- NOWAIT avoids inverse historical-run waits during baseline comparison.
 PERFORM 1 FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id)=(o,w,e) AND run_id IN(link_row.test_run_id,link_row.baseline->>'run_id') ORDER BY run_id FOR SHARE NOWAIT;
 SELECT * INTO STRICT test_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link_row.test_run_id);
 snapshot_value:=public.zasp_production_security_agent_existing_tests_evidence_snapshot(o,w,e,r,s);
 IF snapshot_value IS DISTINCT FROM expected_snapshot THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement evidence changed';END IF;
 recover_value:=test_row.state='leased' AND test_row.lease_expires_at<=clock_timestamp() AND EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,link_row.test_run_id));
 IF test_row.state NOT IN('complete','failed','cancelled') AND NOT recover_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement execution pending';END IF;
 unknown_value:=recover_value OR link_row.cancellation_outcome IS NOT DISTINCT FROM 'outcome_unknown' OR test_row.error_code IS NOT DISTINCT FROM 'outcome_unknown'
  OR snapshot_value->'after'->'outcome_unknown'='true'::jsonb OR snapshot_value->'before'->'outcome_unknown'='true'::jsonb;
 unknown_value:=COALESCE(unknown_value,false);
 BEGIN proof_json:=convert_from(proof_bytes,'UTF8')::json;proof_value:=proof_json::jsonb;
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test settlement proof encoding rejected';END;
 IF EXISTS(WITH RECURSIVE nodes(value,depth) AS (
  SELECT proof_json,0 UNION ALL SELECT child.value,n.depth+1 FROM nodes n CROSS JOIN LATERAL (
   SELECT value FROM json_each(CASE WHEN json_typeof(n.value)='object' THEN n.value ELSE '{}'::json END)
   UNION ALL SELECT value FROM json_array_elements(CASE WHEN json_typeof(n.value)='array' THEN n.value ELSE '[]'::json END)
  ) child WHERE n.depth<=16
 ) SELECT 1 FROM nodes n WHERE depth>16 OR (SELECT count(*)<>count(DISTINCT key) FROM json_each(CASE WHEN json_typeof(n.value)='object' THEN n.value ELSE '{}'::json END))) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test settlement proof ambiguity rejected';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_validate_proof(snapshot_value,proof_value,unknown_value);
 outcome_value:=proof_value->>'outcome';reason_value:=proof_value->>'reason';
 IF recover_value THEN
  UPDATE public.zasp_red_team_runs SET state='failed',error_code='outcome_unknown',cancel_requested=true,completed_at=clock_timestamp(),worker_id=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link_row.test_run_id);
  UPDATE public.zasp_security_agent_test_links SET cancellation_outcome='outcome_unknown',cancellation_recorded_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) AND cancellation_outcome IS NULL;
 END IF;
 parent_state:=CASE WHEN stopped THEN parent_row.state ELSE outcome_value END;
 step_state:=CASE WHEN step_row.state IN('cancelled','failed','inconclusive') THEN step_row.state WHEN stopped THEN CASE WHEN parent_row.state='cancelled' THEN 'cancelled' ELSE 'inconclusive' END WHEN outcome_value IN('remediated','needs_human') THEN 'succeeded' ELSE outcome_value END;
 effect_state:=CASE WHEN effect_row.state<>'pending' THEN effect_row.state WHEN unknown_value THEN 'unknown_outcome' WHEN outcome_value='remediated' AND NOT stopped THEN 'verified' WHEN outcome_value IN('failed','cancelled') THEN 'known_failure' ELSE 'succeeded' END;
 UPDATE public.zasp_security_agent_effects SET state=effect_state,result_digest=proof_digest,version=version+1,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,link_row.action_key);
 UPDATE public.zasp_security_agent_steps SET state=step_state,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF NOT stopped THEN UPDATE public.zasp_security_agent_runs SET state=parent_state,version=version+1,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completed_at=clock_timestamp(),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
 receipt:=jsonb_build_object('run_id',r,'step_id',s,'state',parent_state,'step_state',step_state,'effect_state',effect_state,'outcome',outcome_value,'reason',reason_value,'proof_sha256',encode(proof_digest,'hex'),'reconcile_version',LEAST(version_value+1,1000000),'generation',generation_value);
 UPDATE public.zasp_security_agent_test_links SET reconcile_state='settled',reconcile_version=LEAST(reconcile_version+1,1000000),reconcile_worker=NULL,reconcile_token=NULL,reconcile_expires_at=NULL,
  reconcile_settlement=jsonb_build_object('worker',worker_value,'token_digest',encode(digest(lease_value,'sha256'),'hex'),'claim_version',version_value,'claim_generation',generation_value,'snapshot',expected_snapshot,'proof_hex',encode(proof_bytes,'hex'),'proof',proof_value,'receipt',receipt)
  WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_settlement',r||chr(31)||s);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,audit_value,r,s,worker_value,'test_reconciled',proof_digest,receipt);
 PERFORM zasp_temporal71.body07(o,w,e,worker_value,lease_value,expected_checksum,expected_fingerprint);
 IF deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='test settlement lease expired';END IF;
 RETURN receipt;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body16(o text, w text, e text, r text, worker_value text, lease_value bytea, input_value bytea, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;outcome_value text;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked cancellation release unavailable';END IF;
 SELECT * INTO run_row FROM zasp_temporal71.body01(o,w,e,r,NULL,worker_value,lease_value,input_value);
 SELECT cancellation_outcome INTO STRICT outcome_value FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r);
 RETURN jsonb_build_object('run',public.zasp_red_team_run_json(run_row),'cancellation_outcome',outcome_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body17(o text, w text, e text, r text, worker_value text, lease_value bytea, lease_seconds integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;definition_row public.zasp_red_team_definitions%ROWTYPE;
 parent_deadline timestamptz;result_value jsonb;disposition_value text;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked worker principal unavailable';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND length(worker_value) BETWEEN 3 AND 128 AND worker_value~'^[a-z][a-z0-9.-]{2,127}$' AND octet_length(lease_value)=32 AND lease_seconds BETWEEN 30 AND 900,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked worker claim rejected';
 END IF;
 -- A scoped, already-terminal child needs no live execution authorization.
 -- This read-only acknowledgement never takes a child lock or grants a lease;
 -- public worker operations cannot reopen terminal runs. It remains bound to
 -- the exact persisted link and definition, even after the parent has stopped.
 IF EXISTS(SELECT 1 FROM public.zasp_red_team_runs t JOIN public.zasp_security_agent_test_links l
  ON (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id,l.test_definition_id,l.test_definition_version)=(t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.definition_id,t.definition_version)
  WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id)=(o,w,e,r) AND t.state IN('complete','failed','cancelled')) THEN
  IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
  RETURN jsonb_build_object('disposition','ack_terminal');
 END IF;
 -- Keep the same organization -> parent -> budget -> step -> test-run order
 -- as invocation. Never call the legacy claim or take the child lock first.
 parent_deadline:=zasp_temporal71.body03(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker run unavailable';END IF;
 SELECT d.* INTO definition_row FROM public.zasp_red_team_definitions d JOIN public.zasp_security_agent_test_links l
 ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version,d.target_id,d.target_kind)=(l.organization_id,l.workspace_id,l.environment_id,l.test_definition_id,l.test_definition_version,l.target_id,l.target_kind)
 WHERE (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id,l.test_definition_id,l.test_definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) AND d.enabled FOR SHARE OF d,l;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker definition changed';END IF;
 IF run_row.state IN('complete','failed','cancelled') THEN
  disposition_value:='ack_terminal';
 ELSIF run_row.cancel_requested THEN
  -- The eventual journal-aware canceller owns cancellation evidence/state.
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker cancellation pending';
 ELSIF run_row.state='leased' AND run_row.lease_expires_at>clock_timestamp() OR run_row.next_attempt_at>clock_timestamp() THEN
  disposition_value:='retry_later';
 ELSIF run_row.attempt>=5 OR run_row.error_code='outcome_unknown' OR EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r)) THEN
  -- No new attempt over uncertain or previously executed work. Reconciliation
  -- distinguishes unknown outcomes from known partial/complete observations.
  disposition_value:='reconcile_required';
 ELSE
  PERFORM public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,definition_row.target_id,definition_row.target_kind,definition_row.definition_id,definition_row.version);
  parent_deadline:=zasp_temporal71.body03(o,w,e,r);
  UPDATE public.zasp_red_team_runs SET version=version+1,state='leased',attempt=attempt+1,error_code=NULL,worker_id=worker_value,lease_token=lease_value,
   lease_expires_at=LEAST(clock_timestamp()+make_interval(secs=>lease_seconds),parent_deadline),started_at=COALESCE(started_at,clock_timestamp()),updated_at=clock_timestamp()
  WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO run_row;
  disposition_value:='claimed';
 END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
 result_value:=jsonb_build_object('disposition',disposition_value);
 IF disposition_value='claimed' THEN
  -- Includes waits at UPDATE and time spent verifying the complete release.
  parent_deadline:=zasp_temporal71.body03(o,w,e,r);
  IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker claim expired';END IF;
  result_value:=result_value||jsonb_build_object('evidence_version','red-team-v2','run',public.zasp_red_team_run_json(run_row),'definition',public.zasp_red_team_definition_json(definition_row),'input_digest',encode(run_row.input_digest,'hex'),'lease_expires_at',run_row.lease_expires_at);
 END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body18(o text, w text, e text, r text, worker_value text, lease_value bytea, input_digest_value bytea, verdict_value text, objective_value text, behavior_value text, error_value text, evidence_value jsonb, reference_value text, key_value text, version_value text, checksum_value bytea, size_value bigint, input_value jsonb, expected_checksum text, expected_fingerprint text, artifact_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;link_row public.zasp_security_agent_test_links%ROWTYPE;definition_row public.zasp_red_team_definitions%ROWTYPE;
 parent_deadline timestamptz;target_value jsonb;result_value jsonb;expected_evidence jsonb;passed integer;total integer;
 artifact_json json;artifact_doc jsonb;native_doc jsonb;records jsonb;artifact_item record;observed jsonb;expected_observation jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test completion release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND worker_value~'^[a-z][a-z0-9.-]{2,127}$' AND octet_length(lease_value)=32 AND octet_length(input_digest_value)=32 AND input_digest_value<>decode(repeat('00',32),'hex')
  AND verdict_value IN('pass','fail','engine_error') AND (verdict_value IN('pass','fail') AND error_value IS NULL OR verdict_value='engine_error' AND error_value='outcome_unknown')
  AND objective_value IS NOT NULL AND behavior_value IS NOT NULL AND evidence_value IS NOT NULL
  AND reference_value IS NOT NULL AND key_value IS NOT NULL AND version_value IS NOT NULL
  AND octet_length(checksum_value)=32 AND checksum_value<>decode(repeat('00',32),'hex') AND size_value BETWEEN 1 AND 1048576
  AND octet_length(artifact_value)=size_value AND digest(artifact_value,'sha256')=checksum_value
  AND public.zasp_red_team_valid_input_artifact(o,w,e,input_value) AND input_value->>'reference'<>reference_value,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked completion input rejected';
 END IF;
 parent_deadline:=zasp_temporal71.body03(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR run_row.state<>'leased' OR run_row.worker_id IS DISTINCT FROM worker_value OR run_row.lease_token IS DISTINCT FROM lease_value OR run_row.input_digest IS DISTINCT FROM input_digest_value OR run_row.cancel_requested OR run_row.lease_expires_at<=clock_timestamp() THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion lease rejected';
 END IF;
 SELECT * INTO STRICT link_row FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id,test_definition_id,test_definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) FOR SHARE;
 SELECT * INTO STRICT definition_row FROM public.zasp_red_team_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version,target_id,target_kind,enabled)=(o,w,e,link_row.test_definition_id,link_row.test_definition_version,link_row.target_id,link_row.target_kind,true) FOR SHARE;
 target_value:=public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,link_row.target_id,link_row.target_kind,link_row.test_definition_id,link_row.test_definition_version);
 -- Start and Complete serialize on the same run lock. Every retained receipt
 -- must belong to this exact attempt, input, lease and pinned target snapshot.
 IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r) AND (attempt<>run_row.attempt OR input_digest IS DISTINCT FROM input_digest_value OR lease_digest IS DISTINCT FROM digest(lease_value,'sha256') OR target_resolution IS DISTINCT FROM target_value OR NOT definition_row.categories ? category)) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion journal conflict';
 END IF;
 total:=jsonb_array_length(definition_row.categories);
 IF objective_value IS DISTINCT FROM 'Evaluate curated categories: '||(SELECT string_agg(value,', ' ORDER BY ordinality) FROM jsonb_array_elements_text(definition_row.categories) WITH ORDINALITY c(value,ordinality)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion objective conflict';END IF;
 IF verdict_value IN('pass','fail') THEN
  IF (SELECT count(*) FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,state,http_status)=(o,w,e,r,'completed',200))<>total THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion observations missing';END IF;
  SELECT count(*) FILTER(WHERE j.protected),jsonb_agg(c.value||CASE WHEN j.protected THEN ': protected' ELSE ': unsafe behavior observed' END ORDER BY c.ordinality) INTO passed,expected_evidence
  FROM jsonb_array_elements_text(definition_row.categories) WITH ORDINALITY c(value,ordinality)
  JOIN public.zasp_security_agent_test_invocations j ON (j.organization_id,j.workspace_id,j.environment_id,j.test_run_id,j.category)=(o,w,e,r,c.value);
  IF verdict_value IS DISTINCT FROM (CASE WHEN passed=total THEN 'pass' ELSE 'fail' END) OR evidence_value IS DISTINCT FROM expected_evidence
   OR behavior_value IS DISTINCT FROM format('%s of %s curated security checks passed; %s exposed unsafe behavior.',passed,total,total-passed) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion verdict conflict';END IF;
 ELSE
  -- Engine error is retained as inconclusive evidence, never a successful test.
  IF NOT COALESCE((behavior_value='The bounded target adapter did not return a complete evaluation.' AND evidence_value='["Target adapter evaluation did not complete"]'::jsonb)
   OR (behavior_value='The bounded Promptfoo engine did not complete the evaluation.' AND evidence_value='["Promptfoo execution did not complete"]'::jsonb),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked completion error rejected';END IF;
 END IF;
 -- Compare the exact uploaded bytes, not a separate caller-selected manifest.
 BEGIN
  artifact_json:=convert_from(artifact_value,'UTF8')::json;
  artifact_doc:=artifact_json::jsonb;
 EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked artifact encoding rejected';
 END;
 IF EXISTS(WITH RECURSIVE nodes(value,depth) AS (
  SELECT artifact_json,0 UNION ALL
  SELECT child.value,n.depth+1 FROM nodes n CROSS JOIN LATERAL (
   SELECT value FROM json_each(CASE WHEN json_typeof(n.value)='object' THEN n.value ELSE '{}'::json END)
   UNION ALL SELECT value FROM json_array_elements(CASE WHEN json_typeof(n.value)='array' THEN n.value ELSE '[]'::json END)
  ) child WHERE n.depth<=24
 ) SELECT 1 FROM nodes n WHERE depth>24 OR (SELECT count(*)<>count(DISTINCT key) FROM json_each(CASE WHEN json_typeof(n.value)='object' THEN n.value ELSE '{}'::json END))) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked artifact ambiguity rejected';
 END IF;
 native_doc:=artifact_doc->'native_artifact';
 IF jsonb_typeof(artifact_doc) IS DISTINCT FROM 'object' OR artifact_doc->>'schema_version' IS DISTINCT FROM 'red-team-evidence-bundle-v2'
  OR artifact_doc-ARRAY['schema_version','input_artifact','summary','native_artifact']<>'{}'::jsonb
  OR artifact_doc->'input_artifact' IS DISTINCT FROM input_value
  OR artifact_doc->'summary' IS DISTINCT FROM jsonb_build_object('schema_version','red-team-evidence-v2','engine','promptfoo','engine_version','0.121.19','run_id',r,'input_digest',encode(input_digest_value,'hex'),'objective',objective_value,'behavior',behavior_value,'verdict',verdict_value,'error_code',error_value,'evidence',evidence_value)
  OR native_doc->>'schema_version' IS DISTINCT FROM 'red-team-native-artifact-v2' OR native_doc->>'redaction_policy' IS DISTINCT FROM 'red-team-artifact-redaction-v2'
  OR native_doc->>'run_id' IS DISTINCT FROM r OR native_doc->>'input_digest' IS DISTINCT FROM encode(input_digest_value,'hex') THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact association conflict';
 END IF;
 IF native_doc->'native_output'='null'::jsonb THEN
  IF verdict_value<>'engine_error' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact observations missing';END IF;
 ELSE
  records:=native_doc#>'{native_output,results,results}';
  IF jsonb_typeof(records) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact observations invalid';END IF;
  IF jsonb_array_length(records)<>total THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact observations incomplete';END IF;
  FOR artifact_item IN SELECT value,ordinality FROM jsonb_array_elements(records) WITH ORDINALITY LOOP
   observed:=artifact_item.value#>'{response,linked_observation}';
   IF artifact_item.value#>>'{vars,category}' IS DISTINCT FROM definition_row.categories->>(artifact_item.ordinality::integer-1) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact category conflict';END IF;
   IF observed IS NOT NULL AND observed<>'null'::jsonb THEN
    SELECT jsonb_build_object('target_comparison',j.target_resolution->'comparison','schema_version','red-team-linked-observation-v1','run_id',r,'category',j.category,'credential_version_digest',encode(j.credential_version_digest,'hex'),'observation',jsonb_build_object('http_status',j.http_status,'response_digest',encode(j.response_digest,'hex'),'protected',j.protected)) INTO expected_observation
    FROM public.zasp_security_agent_test_invocations j WHERE (j.organization_id,j.workspace_id,j.environment_id,j.test_run_id,j.category,j.state,j.http_status)=(o,w,e,r,definition_row.categories->>(artifact_item.ordinality::integer-1),'completed',200);
    IF NOT FOUND OR observed IS DISTINCT FROM expected_observation OR artifact_item.value->'success' IS DISTINCT FROM observed#>'{observation,protected}' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact journal conflict';END IF;
   ELSIF verdict_value IN('pass','fail') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked artifact observation missing';
   END IF;
  END LOOP;
 END IF;
 -- Reuse private predecessor persistence, never its public legacy entrypoint.
 -- It remains inaccessible to application roles and receives no new grant.
 result_value:=zasp_existing_tests_predecessor.zasp_red_team_finish_run(o,w,e,r,worker_value,lease_value,input_digest_value,verdict_value,objective_value,behavior_value,error_value,evidence_value,reference_value,key_value,version_value,checksum_value,size_value,input_value);
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test completion release unavailable';END IF;
 PERFORM zasp_temporal71.body03(o,w,e,r);
 IF run_row.lease_expires_at<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion authority expired';END IF;
 RETURN result_value;
EXCEPTION WHEN no_data_found THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked completion association rejected';
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body19(o text, w text, e text, r text, worker_value text, lease_value bytea, lease_seconds integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE run_row public.zasp_red_team_runs%ROWTYPE;definition_row public.zasp_red_team_definitions%ROWTYPE;
 parent_deadline timestamptz;prior_expiry timestamptz;new_expiry timestamptz;target_value jsonb;
 result_value jsonb:=jsonb_build_object('renewed',false,'cancel_requested',false);
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='linked worker principal unavailable';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r)
  AND length(worker_value) BETWEEN 3 AND 128 AND worker_value~'^[a-z][a-z0-9.-]{2,127}$' AND octet_length(lease_value)=32 AND lease_seconds BETWEEN 30 AND 900,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='linked worker heartbeat rejected';
 END IF;
 parent_deadline:=zasp_temporal71.body03(o,w,e,r);
 SELECT * INTO run_row FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF FOUND AND run_row.state='leased' AND run_row.worker_id=worker_value AND run_row.lease_token=lease_value AND run_row.lease_expires_at>clock_timestamp() THEN
  IF run_row.cancel_requested THEN
   -- Report the request without renewing or claiming external cancellation.
   result_value:=jsonb_build_object('renewed',false,'cancel_requested',true);
  ELSE
   SELECT d.* INTO definition_row FROM public.zasp_red_team_definitions d JOIN public.zasp_security_agent_test_links l
   ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id,d.version,d.target_id,d.target_kind)=(l.organization_id,l.workspace_id,l.environment_id,l.test_definition_id,l.test_definition_version,l.target_id,l.target_kind)
   WHERE (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id,l.test_definition_id,l.test_definition_version)=(o,w,e,r,run_row.definition_id,run_row.definition_version) AND d.enabled FOR SHARE OF d,l;
   IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker definition changed';END IF;
   target_value:=public.zasp_production_security_agent_existing_tests_invocation_target(o,w,e,definition_row.target_id,definition_row.target_kind,definition_row.definition_id,definition_row.version);
   IF EXISTS(SELECT 1 FROM public.zasp_security_agent_test_invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,r) AND target_resolution IS DISTINCT FROM target_value) THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker target snapshot changed';
   END IF;
   prior_expiry:=run_row.lease_expires_at;
   parent_deadline:=zasp_temporal71.body03(o,w,e,r);
   UPDATE public.zasp_red_team_runs SET lease_expires_at=LEAST(clock_timestamp()+make_interval(secs=>lease_seconds),parent_deadline),updated_at=clock_timestamp()
   WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING lease_expires_at INTO new_expiry;
   result_value:=jsonb_build_object('renewed',true,'cancel_requested',false,'lease_expires_at',new_expiry);
  END IF;
 END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='linked worker release unavailable';END IF;
 IF new_expiry IS NOT NULL THEN
  parent_deadline:=zasp_temporal71.body03(o,w,e,r);
  -- The old lease, not the freshly written expiry, authorized this renewal.
  -- Roll the entire statement back if an UPDATE/catalog wait outlived it.
  IF prior_expiry<=clock_timestamp() OR new_expiry<=clock_timestamp() OR parent_deadline<=clock_timestamp() THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='linked worker heartbeat expired';
  END IF;
 END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body20(o text, w text, e text, r text, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE protocol_value text;
BEGIN
 IF NOT COALESCE(public.zasp_red_team_principal_ready('zasp_red_team_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='red team principal unavailable';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker protocol release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='worker protocol input rejected';END IF;
 SELECT CASE WHEN EXISTS(SELECT 1 FROM public.zasp_security_agent_test_links l WHERE (l.organization_id,l.workspace_id,l.environment_id,l.test_run_id)=(o,w,e,r)) THEN 'linked' ELSE 'legacy' END INTO protocol_value
 FROM public.zasp_red_team_runs t WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id)=(o,w,e,r);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='worker protocol run unavailable';END IF;
 IF NOT COALESCE(zasp_temporal71.guard1(expected_checksum,expected_fingerprint),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='worker protocol release unavailable';END IF;
 RETURN jsonb_build_object('protocol',protocol_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal71.body21(org_value text, workspace_value text, environment_value text, agent_value text, version_value bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE body_value jsonb;reference_value jsonb;test_row public.zasp_red_team_definitions%ROWTYPE;target_value jsonb;class_value text;credential_expires timestamptz;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(org_value) AND public.zasp_valid_product_id(workspace_value) AND public.zasp_valid_product_id(environment_value) AND public.zasp_valid_product_id(agent_value) AND version_value BETWEEN 1 AND 1000000,false) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';
 END IF;
 SELECT definition.body INTO body_value FROM public.zasp_security_agent_definitions definition
 WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version)=(org_value,workspace_value,environment_value,agent_value,version_value) AND definition.deleted_at IS NULL FOR SHARE;
 reference_value:=body_value->'existing_test';
 IF NOT COALESCE((body_value->'allowed_actions' IN ('["run_test"]'::jsonb,'["rerun_test"]'::jsonb) AND body_value->>'verification_kind'='test_run' OR body_value->'allowed_actions'='["start_attack_lab"]'::jsonb AND body_value->>'verification_kind'='attack_lab_run' AND zasp_temporal71.guard2())
  AND jsonb_typeof(reference_value)='object' AND reference_value ?& ARRAY['definition_id','definition_version'] AND reference_value-ARRAY['definition_id','definition_version']='{}'::jsonb
  AND jsonb_typeof(reference_value->'definition_id')='string' AND public.zasp_valid_product_id(reference_value->>'definition_id')
  AND jsonb_typeof(reference_value->'definition_version')='number' AND reference_value->>'definition_version' ~ '^([1-9][0-9]{0,5}|1000000)$',false) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';
 END IF;
 SELECT * INTO test_row FROM public.zasp_red_team_definitions definition
 WHERE (definition.organization_id,definition.workspace_id,definition.environment_id,definition.definition_id,definition.version,definition.enabled)=(org_value,workspace_value,environment_value,reference_value->>'definition_id',(reference_value->>'definition_version')::bigint,true) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';END IF;
 class_value:=public.zasp_production_security_agent_run_context_lock_env(org_value,workspace_value,environment_value);
 IF NOT COALESCE(class_value IN('development','test','staging') AND class_value=test_row.safety->>'environment',false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';END IF;
 target_value:=public.zasp_production_security_agent_run_context_lock_target(org_value,workspace_value,environment_value,test_row.target_id);
 IF NOT COALESCE(target_value->>'state'='active',false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';END IF;
 SELECT binding.valid_until INTO credential_expires FROM public.zasp_attack_lab_credential_bindings binding
 WHERE (binding.organization_id,binding.workspace_id,binding.environment_id,binding.target_id,binding.credential_reference,binding.state)=(org_value,workspace_value,environment_value,test_row.target_id,target_value->'attributes'->'red_team'->>'credential_reference','active') AND binding.credential_class=test_row.safety->>'credential_class' FOR SHARE;
 IF NOT FOUND OR NOT COALESCE(credential_expires>clock_timestamp() AND (target_value->>'fresh_until')::timestamptz>clock_timestamp() AND public.zasp_red_team_safety_authorized(org_value,workspace_value,environment_value,test_row.target_id,test_row.target_kind,test_row.safety),false) THEN
  RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent test binding unavailable';
 END IF;
 RETURN jsonb_build_object('definition_id',test_row.definition_id,'definition_version',test_row.version,'target_id',test_row.target_id,'target_kind',test_row.target_kind);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal72.admit(o text, w text, e text, p text, i text, s text, j text, b text, k text, d bytea, trigger_value text, parser_value text, tool_value text, schedule_value text, due_value timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE integration_row public.zasp_integrations%ROWTYPE;connection_row public.zasp_integration_connections%ROWTYPE;subject_row public.zasp_discovery_connection_subjects%ROWTYPE;r zasp_temporal72.runs%ROWTYPE;payload jsonb;now_value timestamptz;
BEGIN
 IF NOT(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(p) AND public.zasp_valid_product_id(i) AND public.zasp_valid_product_id(s) AND public.zasp_valid_product_id(j) AND public.zasp_valid_product_id(b))
 OR octet_length(d)<>32 OR length(k) NOT BETWEEN 16 AND 128 OR trigger_value NOT IN('manual','schedule') OR parser_value!~'^[a-z][a-z0-9_.-]{1,63}$' OR tool_value!~'^[a-z][a-z0-9_.-]{1,63}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery admission rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'discovery72-admit',o,w,e,i,k),0));
 SELECT * INTO r FROM zasp_temporal72.runs WHERE (organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 IF FOUND THEN
  IF (r.sync_id,r.integration_id,r.request_digest,r.outbox_id) IS DISTINCT FROM(s,i,d,b) OR r.schedule_id IS DISTINCT FROM schedule_value OR r.scheduled_for IS DISTINCT FROM due_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery admission conflict';END IF;
  RETURN jsonb_build_object('outcome','admitted','start',zasp_temporal72.start_receipt(r));
 END IF;
 SELECT * INTO integration_row FROM public.zasp_integrations WHERE (organization_id,workspace_id,environment_id,id)=(o,w,e,i) AND state IN('active','degraded') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery connector revoked';END IF;
 SELECT * INTO connection_row FROM public.zasp_integration_connections WHERE (organization_id,workspace_id,environment_id,integration_id,provider,state)=(o,w,e,i,integration_row.kind,'verified') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery connection revoked';END IF;
 SELECT * INTO subject_row FROM public.zasp_discovery_connection_subjects WHERE (organization_id,workspace_id,environment_id,integration_id,connection_id,provider,connection_version,configuration_digest)=(o,w,e,i,connection_row.id,integration_row.kind,connection_row.version,digest(convert_to(integration_row.configuration::text,'UTF8'),'sha256')) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery subject rejected';END IF;
 now_value:=clock_timestamp();
 INSERT INTO public.zasp_discovery_syncs(organization_id,workspace_id,environment_id,id,integration_id,idempotency_key,request_digest,trigger_kind,principal_id,parser_version,tool_version,requested_at)
 VALUES(o,w,e,s,i,k,d,trigger_value,p,parser_value,tool_value,now_value);
 INSERT INTO zasp_temporal72.runs(organization_id,workspace_id,environment_id,job_id,sync_id,integration_id,schedule_id,scheduled_for,request_digest,outbox_id,connection_id,provider,integration_version,connection_version,configuration,configuration_digest,credential_reference,subject_kind,subject_id,admitted_at,deadline)
 VALUES(o,w,e,j,s,i,schedule_value,due_value,d,b,connection_row.id,integration_row.kind,integration_row.version,connection_row.version,integration_row.configuration,subject_row.configuration_digest,connection_row.connection_reference,subject_row.subject_kind,subject_row.subject_id,now_value,now_value+interval '24 hours') RETURNING * INTO r;
 payload:=jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'job_id',j,'sync_id',s,'integration_id',i,'request_digest',encode(d,'hex'));
 INSERT INTO public.zasp_discovery_outbox(organization_id,workspace_id,environment_id,id,topic,deterministic_key,payload_version,payload,payload_digest)
 VALUES(o,w,e,b,'discovery-jobs','sync:'||s,1,payload,digest(convert_to(payload::text,'UTF8'),'sha256'));
 PERFORM public.zasp_execution_bump_freshness(o,w,e,i);
 RETURN jsonb_build_object('outcome','admitted','start',zasp_temporal72.start_receipt(r));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.apply_retained_snapshot(organization_value text, workspace_value text, environment_value text, job_value text, worker_value text, lease_token_value text, integration_value text, sync_value text, snapshot_value text, generation_value bigint, source_value text, manifest_reference_value text, manifest_key_value text, manifest_version_value text, manifest_checksum_value bytea, manifest_size_value bigint, manifest_media_value text, manifest_schema_value text, collected_value timestamp with time zone, cursor_value text, parser_value text, tool_value text, entities_value jsonb, relationships_value jsonb, evidence_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prepared zasp_temporal72.retained_dispatches%ROWTYPE;job public.zasp_discovery_jobs%ROWTYPE;raw_digest bytea;mapped jsonb;
BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT * INTO job FROM public.zasp_discovery_jobs WHERE(organization_id,workspace_id,environment_id,id,kind,state,lease_owner,lease_token)=(organization_value,workspace_value,environment_value,job_value,'discovery','leased',worker_value,lease_token_value) AND lease_expires_at>transaction_timestamp() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='retained apply lease rejected';END IF;
 SELECT * INTO prepared FROM zasp_temporal72.retained_dispatches WHERE(organization_id,workspace_id,environment_id,job_id,attempt,sync_id,integration_id,provider,generation,snapshot_id,worker_id,token_digest)=(organization_value,workspace_value,environment_value,job_value,job.attempt,sync_value,integration_value,source_value,generation_value,snapshot_value,worker_value,digest(convert_to(lease_token_value,'UTF8'),'sha256')) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='retained apply preparation rejected';END IF;
 raw_digest:=digest(convert_to(jsonb_build_array(organization_value,workspace_value,environment_value,job_value,integration_value,sync_value,snapshot_value,generation_value,source_value,manifest_reference_value,manifest_key_value,manifest_version_value,encode(manifest_checksum_value,'hex'),manifest_size_value,manifest_media_value,manifest_schema_value,floor(extract(epoch FROM collected_value)*1000000)::bigint,cursor_value,parser_value,tool_value,entities_value,relationships_value,evidence_value)::text,'UTF8'),'sha256');
 IF prepared.raw_apply_digest IS NOT NULL THEN
  IF prepared.raw_apply_digest IS DISTINCT FROM raw_digest THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='retained apply replay conflict';END IF;
  mapped:=prepared.normalized_relationships;
 ELSE
  mapped:=zasp_temporal72.normalize_relationships(organization_value,workspace_value,environment_value,integration_value,source_value,relationships_value);
  UPDATE zasp_temporal72.retained_dispatches SET raw_apply_digest=raw_digest,normalized_relationships=mapped WHERE(organization_id,workspace_id,environment_id,job_id,attempt)=(organization_value,workspace_value,environment_value,job_value,job.attempt);
 END IF;
 RETURN public.zasp_execution_apply_complete_snapshot(organization_value,workspace_value,environment_value,job_value,worker_value,lease_token_value,integration_value,sync_value,snapshot_value,generation_value,source_value,manifest_reference_value,manifest_key_value,manifest_version_value,manifest_checksum_value,manifest_size_value,manifest_media_value,manifest_schema_value,collected_value,cursor_value,parser_value,tool_value,entities_value,mapped,evidence_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.claim_retained_delivery(o text, w text, e text, j text, worker_value text, token_value text, seconds_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE job public.zasp_discovery_jobs%ROWTYPE;a public.zasp_discovery_job_authorities%ROWTYPE;locked boolean;BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 IF worker_value IS NULL OR token_value IS NULL OR seconds_value IS NULL OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(token_value) NOT BETWEEN 16 AND 128 OR seconds_value NOT BETWEEN 5 AND 900 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid retained delivery claim';END IF;
 locked:=zasp_temporal72.try_capacity_lock();
 SELECT * INTO job FROM public.zasp_discovery_jobs WHERE(organization_id,workspace_id,environment_id,id,kind)=(o,w,e,j,'discovery');
 SELECT * INTO a FROM public.zasp_discovery_job_authorities WHERE(organization_id,workspace_id,environment_id,job_id,sync_id)=(o,w,e,j,job.authority_id);
 IF job.id IS NULL OR a.job_id IS NULL OR a.request_digest IS DISTINCT FROM job.request_digest OR EXISTS(SELECT 1 FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='retained delivery ownership rejected';END IF;
 IF job.state IN('succeeded','failed','cancelled') AND EXISTS(SELECT 1 FROM zasp_temporal72.active_owners(o) owner WHERE(owner.workspace_id,owner.environment_id,owner.job_id)=(w,e,j)) THEN RAISE EXCEPTION USING ERRCODE='55P03',MESSAGE='retained discovery awaits outcome evidence';END IF;
 IF job.state NOT IN('succeeded','failed','cancelled') AND(NOT locked OR NOT COALESCE(zasp_temporal72.retained_retry_safe(job),false) OR NOT zasp_temporal72.capacity_available(o,w,e,j,a.integration_id,a.provider)) THEN RETURN jsonb_build_object('id',j,'state',job.state,'attempt',job.attempt,'disposition','busy');END IF;
 IF NOT locked THEN RAISE EXCEPTION USING ERRCODE='55P03',MESSAGE='retained delivery capacity contended';END IF;
 RETURN public.zasp_execution_claim_delivery(o,w,e,j,worker_value,token_value,seconds_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.commit_apply(o text, w text, e text, j text, effect_value text, budget timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;a zasp_temporal72.apply_effects%ROWTYPE;c zasp_temporal72.checkpoints%ROWTYPE;g public.zasp_discovery_generation_reservations%ROWTYPE;m jsonb;candidate_value jsonb;digest_value bytea;result_value jsonb;
BEGIN
 PERFORM zasp_authorization80_worker.require_discovery72('commit_apply',zasp_authorization80_worker.discovery72_request('commit_apply',o,w,e,j,jsonb_build_object('effect_id',effect_value,'budget_us',floor(extract(epoch FROM budget)*1000000)::bigint)));
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j) FOR UPDATE;
 IF NOT FOUND OR budget IS NULL OR budget IS DISTINCT FROM r.deadline THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery apply scope rejected';END IF;
 SELECT * INTO a FROM zasp_temporal72.apply_effects WHERE(organization_id,workspace_id,environment_id,job_id,effect_id)=(o,w,e,j,effect_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery apply effect rejected';END IF;
 IF a.result IS NOT NULL THEN RETURN a.result;END IF;
 IF r.state<>'applying' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery apply state rejected';END IF;
 PERFORM zasp_temporal72.require_current_run(r,budget);
 SELECT * INTO STRICT c FROM zasp_temporal72.checkpoints WHERE(organization_id,workspace_id,environment_id,job_id,digest)=(o,w,e,j,a.complete_digest) AND candidate IS NOT NULL;
 SELECT * INTO STRICT g FROM public.zasp_discovery_generation_reservations WHERE(organization_id,workspace_id,environment_id,sync_id,integration_id,source)=(o,w,e,r.sync_id,r.integration_id,r.provider);
 m:=c.manifest;candidate_value:=c.candidate;
 digest_value:=digest(convert_to(jsonb_build_object('integration_id',r.integration_id,'sync_id',r.sync_id,'snapshot_id',g.snapshot_id,'generation',g.generation,'source',r.provider,'manifest_reference',m->>'reference','manifest_key',m->>'key','manifest_version_id',m->>'version_id','manifest_checksum',m->>'checksum','manifest_size_bytes',(m->>'size_bytes')::bigint,'manifest_media_type',m->>'media_type','manifest_schema_version',m->>'schema_version','collected_at_epoch_us',floor(extract(epoch FROM date_trunc('second',g.reserved_at))*1000000)::bigint,'cursor',c.cursor->>'value','parser_version',m->>'parser_version','tool_version',m->>'tool_version','entities',candidate_value->'entities','relationships',candidate_value->'relationships','evidence',candidate_value->'evidence')::text,'UTF8'),'sha256');
 PERFORM public.zasp_discovery_apply_snapshot(o,w,e,r.integration_id,r.sync_id,g.snapshot_id,g.generation,r.provider,m->>'reference',decode(m->>'checksum','hex'),date_trunc('second',g.reserved_at),r.provider,c.cursor->>'value',candidate_value->'entities',candidate_value->'relationships',candidate_value->'evidence');
 INSERT INTO public.zasp_discovery_snapshot_inputs(organization_id,workspace_id,environment_id,snapshot_id,integration_id,source,generation,candidate_digest,manifest_reference,manifest_key,manifest_version_id,manifest_checksum,manifest_size_bytes,manifest_media_type,manifest_schema_version,parser_version,tool_version,entities,relationships,evidence)
 VALUES(o,w,e,g.snapshot_id,r.integration_id,r.provider,g.generation,digest_value,m->>'reference',m->>'key',m->>'version_id',decode(m->>'checksum','hex'),(m->>'size_bytes')::bigint,m->>'media_type',m->>'schema_version',m->>'parser_version',m->>'tool_version',candidate_value->'entities',candidate_value->'relationships',candidate_value->'evidence');
 INSERT INTO public.zasp_discovery_snapshot_projection_items(organization_id,workspace_id,environment_id,snapshot_id,integration_id,source,section,item_id,payload)
 SELECT o,w,e,g.snapshot_id,r.integration_id,r.provider,section,value->>'id',value FROM(SELECT 'entities'::text section,value FROM jsonb_array_elements(candidate_value->'entities') UNION ALL SELECT 'relationships',value FROM jsonb_array_elements(candidate_value->'relationships') UNION ALL SELECT 'evidence',value FROM jsonb_array_elements(candidate_value->'evidence')) items;
 UPDATE public.zasp_projection_work SET input_digest=digest_value WHERE(organization_id,workspace_id,environment_id,snapshot_id)=(o,w,e,g.snapshot_id) AND state='pending' AND attempt=0;
 PERFORM public.zasp_execution_bump_freshness(o,w,e,r.integration_id);
 -- Crossing the original budget rolls back the whole local transaction.
 PERFORM zasp_temporal72.require_current_run(r,budget);
 result_value:=jsonb_build_object('outcome','succeeded','receipt_digest',encode(digest_value,'hex'));
 UPDATE zasp_temporal72.apply_effects SET result=result_value,committed_at=clock_timestamp() WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 UPDATE zasp_temporal72.runs SET state='succeeded' WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.delivery_route(o text, w text, e text, j text, payload_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE owned boolean;legacy public.zasp_discovery_jobs%ROWTYPE;s public.zasp_discovery_syncs%ROWTYPE;canonical jsonb;
BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 owned:=EXISTS(SELECT 1 FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j));
 SELECT * INTO legacy FROM public.zasp_discovery_jobs WHERE(organization_id,workspace_id,environment_id,id,kind)=(o,w,e,j,'discovery');
 IF owned THEN
  IF FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ambiguous discovery ownership';END IF;
  RETURN jsonb_build_object('ownership','temporal','start',zasp_temporal72.start_delivery(o,w,e,j,payload_value));
 END IF;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery ownership missing';END IF;
 SELECT * INTO s FROM public.zasp_discovery_syncs WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,legacy.authority_id);
 IF NOT FOUND OR EXISTS(SELECT 1 FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,sync_id)=(o,w,e,s.id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery sync ownership rejected';END IF;
 canonical:=jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'job_id',j,'sync_id',s.id,'integration_id',s.integration_id,'request_digest',encode(legacy.request_digest,'hex'));
 IF payload_value IS DISTINCT FROM canonical OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_outbox b WHERE(b.organization_id,b.workspace_id,b.environment_id,b.topic,b.payload_version)=(o,w,e,'discovery-jobs',1) AND b.payload=canonical AND b.payload_digest=digest(convert_to(canonical::text,'UTF8'),'sha256'))
 OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_job_authorities a WHERE(a.organization_id,a.workspace_id,a.environment_id,a.job_id,a.sync_id,a.integration_id,a.request_digest)=(o,w,e,j,s.id,s.integration_id,legacy.request_digest)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='retained discovery envelope rejected';END IF;
 RETURN jsonb_build_object('ownership','legacy','start',NULL);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.finish(o text, w text, e text, j text, i text, input_digest text, outcome_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE budget timestamptz;
BEGIN
 PERFORM zasp_authorization80_worker.require_discovery72('finish',zasp_authorization80_worker.discovery72_request('finish',o,w,e,j,jsonb_build_object('integration_id',i,'input_digest',input_digest,'outcome',outcome_value,'receipt',receipt_value)));
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT deadline INTO budget FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id,integration_id)=(o,w,e,j,i);
 RETURN zasp_temporal72.settle(o,w,e,j,i,input_digest,budget,outcome_value,receipt_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.guard_page_effect(o text, w text, e text, j text, effect_value text, budget timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;
BEGIN
 PERFORM zasp_authorization80_worker.require_discovery72('guard_page',zasp_authorization80_worker.discovery72_request('guard_page',o,w,e,j,jsonb_build_object('effect_id',effect_value,'budget_us',floor(extract(epoch FROM budget)*1000000)::bigint)));
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j) FOR SHARE;
 IF NOT FOUND OR r.state<>'collecting' OR NOT EXISTS(SELECT 1 FROM zasp_temporal72.page_effects WHERE(organization_id,workspace_id,environment_id,job_id,effect_id)=(o,w,e,j,effect_value) AND result IS NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery effect rejected';END IF;
 PERFORM zasp_temporal72.require_current_run(r,budget);
 IF NOT EXISTS(SELECT 1 FROM zasp_temporal72.active_owners(o) owner WHERE(owner.workspace_id,owner.environment_id,owner.job_id,owner.ownership)=(w,e,j,'temporal')) OR NOT zasp_temporal72.capacity_available(o,w,e,j,r.integration_id,r.provider) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery effect ownership rejected';END IF;
 RETURN true;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.last_good_freshness(o text, w text, e text, i text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE b jsonb;
BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_api');
 b:=public.zasp_execution_last_good_freshness(o,w,e,i);
 IF b->'latest_sync'<>'null'::jsonb THEN b:=b||jsonb_build_object('latest_sync',zasp_temporal72.sync_body(o,w,e,i,b->'latest_sync'->>'id'));END IF;
 RETURN b;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.migration_helper_identity(s text, o text, a text)
 RETURNS text
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE migration_owner oid;helper record;BEGIN
 IF s NOT IN('zasp_valid_product_id(text)','zasp_workflow_replay(text,text,text,text,text,text,jsonb)') THEN RETURN NULL;END IF;
 SELECT c.relowner INTO migration_owner FROM pg_class c JOIN pg_class core ON core.oid='public.zasp_core_payloads'::regclass AND core.relowner=c.relowner
 JOIN public.zasp_discovery_principal_bindings b ON b.authority_role='zasp_discovery_authority' AND b.principal_name=c.relowner::regrole::text
 JOIN pg_roles r ON r.oid=c.relowner AND r.rolcanlogin
 WHERE c.oid='public.zasp_authorized_scopes'::regclass;
 IF migration_owner IS NULL OR o IS DISTINCT FROM migration_owner::regrole::text THEN RETURN NULL;END IF;
 SELECT p.proowner,p.proacl INTO helper FROM pg_proc p WHERE p.oid=to_regprocedure('public.'||s);
 IF NOT FOUND OR helper.proowner IS DISTINCT FROM migration_owner OR COALESCE(helper.proacl::text,'') IS DISTINCT FROM a THEN RETURN NULL;END IF;
 IF s='zasp_valid_product_id(text)' THEN
  IF helper.proacl IS NOT NULL THEN RETURN NULL;END IF;
  RETURN '<migration-authority>|<default-function-acl>';
 END IF;
 IF helper.proacl IS NULL OR NOT(SELECT count(*)=3 AND count(DISTINCT x.grantee)=3 AND bool_and(x.grantor=migration_owner AND NOT x.is_grantable AND x.privilege_type='EXECUTE' AND x.grantee IN(0,migration_owner,'zasp_discovery_api'::regrole)) FROM aclexplode(helper.proacl) x) THEN RETURN NULL;END IF;
 RETURN '<migration-authority>|<public,owner,discovery-api:execute;grantor:owner;grantable:false>';
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.normalize_relationships(o text, w text, e text, i text, source_value text, items jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item jsonb;identity_value text;matches bigint;result jsonb:='[]'::jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(i) AND source_value IN('aws','kubernetes','github','okta') AND jsonb_typeof(items)='array' AND jsonb_array_length(items)<=20000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='relationship scope rejected';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP
  IF EXISTS(SELECT 1 FROM unnest(ARRAY['id','kind','source_native_id','from_entity_id','to_entity_id']) key WHERE jsonb_typeof(item->key) IS DISTINCT FROM 'string') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='raw relationship field type rejected';END IF;
  IF NOT COALESCE(jsonb_typeof(item)='object' AND item ?& ARRAY['id','kind','source_native_id','from_entity_id','to_entity_id','attributes'] AND item-ARRAY['id','kind','source_native_id','from_entity_id','to_entity_id','attributes']='{}'::jsonb AND public.zasp_valid_product_id(item->>'id') AND public.zasp_valid_product_id(item->>'from_entity_id') AND public.zasp_valid_product_id(item->>'to_entity_id') AND item->>'from_entity_id'<>item->>'to_entity_id' AND item->>'kind' ~ '^[a-z][a-z0-9_]{1,63}$' AND length(item->>'source_native_id') BETWEEN 1 AND 1024 AND jsonb_typeof(item->'attributes')='object' AND octet_length((item->'attributes')::text)<=65536,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='raw relationship rejected';END IF;
 END LOOP;
 IF EXISTS(SELECT 1 FROM jsonb_array_elements(items) value GROUP BY value->>'id' HAVING count(*)>1) OR EXISTS(SELECT 1 FROM jsonb_array_elements(items) value GROUP BY value->>'source_native_id' HAVING count(*)>1) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ambiguous relationship rejected';END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(items) LOOP
  SELECT count(*),min(id) INTO matches,identity_value FROM public.zasp_inventory_relationships WHERE(organization_id,workspace_id,environment_id,integration_id,source,source_native_id)=(o,w,e,i,source_value,item->>'source_native_id');
  IF matches>1 THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='ambiguous persisted relationship';END IF;
  IF matches=0 THEN identity_value:=public.zasp_discovery_relationship_id(o,w,e,i,source_value,item->>'kind',item->>'source_native_id');END IF;
  IF EXISTS(SELECT 1 FROM public.zasp_inventory_relationships WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,identity_value) AND (integration_id,source,source_native_id) IS DISTINCT FROM(i,source_value,item->>'source_native_id')) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='relationship identity collision';END IF;
  result:=result||jsonb_build_array(jsonb_set(item,'{id}',to_jsonb(identity_value)));
 END LOOP;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.outbox_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;row_value public.zasp_discovery_outbox%ROWTYPE;
BEGIN
 IF TG_OP='INSERT' THEN row_value:=NEW;ELSE row_value:=OLD;END IF;
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,outbox_id)=(row_value.organization_id,row_value.workspace_id,row_value.environment_id,row_value.id);
 IF NOT FOUND THEN
  IF TG_OP='DELETE' THEN RETURN OLD;END IF;
  -- An update cannot move a retained row into an owned identity.
  IF TG_OP='UPDATE' AND EXISTS(SELECT 1 FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,outbox_id)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.id)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery outbox ownership rejected';END IF;
  RETURN NEW;
 END IF;
 IF TG_OP='DELETE' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery outbox ownership rejected';END IF;
 IF TG_OP='INSERT' THEN
  IF NOT EXISTS(SELECT 1 FROM zasp_temporal72.principals WHERE principal_name=session_user AND authority_role IN('zasp_discovery_api','zasp_discovery_worker','zasp_discovery_scheduler')) OR NOT zasp_temporal72.current_ready()
  OR NEW.topic IS DISTINCT FROM 'discovery-jobs' OR NEW.payload_version IS DISTINCT FROM 1
  OR NEW.payload IS DISTINCT FROM jsonb_build_object('organization_id',r.organization_id,'workspace_id',r.workspace_id,'environment_id',r.environment_id,'job_id',r.job_id,'sync_id',r.sync_id,'integration_id',r.integration_id,'request_digest',encode(r.request_digest,'hex'))
  THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery outbox admission rejected';END IF;
 ELSE
  PERFORM zasp_temporal72.require_principal('zasp_outbox_worker');
  IF (NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.id,NEW.topic,NEW.deterministic_key,NEW.payload_version,NEW.payload,NEW.payload_digest,NEW.created_at) IS DISTINCT FROM (OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.id,OLD.topic,OLD.deterministic_key,OLD.payload_version,OLD.payload,OLD.payload_digest,OLD.created_at) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery outbox identity rejected';END IF;
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.pending_schedules(after_value text, all_value boolean, limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_scheduler');
 IF after_value IS NULL OR all_value IS NULL OR limit_value IS NULL OR limit_value NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery schedule page rejected';END IF;
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',organization_id,'workspace_id',workspace_id,'environment_id',environment_id,'schedule_id',id,'integration_id',integration_id) ORDER BY page_key),'[]') INTO result FROM(SELECT *,concat_ws('/',organization_id,workspace_id,environment_id,id,integration_id) AS page_key FROM zasp_temporal72.schedules WHERE(all_value OR delivered_revision<>version) AND concat_ws('/',organization_id,workspace_id,environment_id,id,integration_id)>after_value ORDER BY page_key LIMIT limit_value) page;
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.prepare_apply(o text, w text, e text, j text, i text, input_digest text, budget timestamp with time zone, complete_receipt text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;a zasp_temporal72.apply_effects%ROWTYPE;effect_value text;
BEGIN
 PERFORM zasp_authorization80_worker.require_discovery72('prepare_apply',zasp_authorization80_worker.discovery72_request('prepare_apply',o,w,e,j,jsonb_build_object('integration_id',i,'input_digest',input_digest,'budget_us',floor(extract(epoch FROM budget)*1000000)::bigint,'complete_receipt',complete_receipt)));
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id,integration_id)=(o,w,e,j,i) FOR UPDATE;
 IF NOT FOUND OR input_digest IS DISTINCT FROM encode(r.request_digest,'hex') OR budget IS NULL OR budget IS DISTINCT FROM r.deadline OR complete_receipt IS DISTINCT FROM r.checkpoint_digest THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery apply intent rejected';END IF;
 SELECT * INTO a FROM zasp_temporal72.apply_effects WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 IF FOUND THEN RETURN jsonb_build_object('result',COALESCE(a.result,jsonb_build_object('outcome','outcome_unknown')));END IF;
 IF r.state<>'complete' OR NOT EXISTS(SELECT 1 FROM zasp_temporal72.checkpoints WHERE(organization_id,workspace_id,environment_id,job_id,digest)=(o,w,e,j,complete_receipt) AND candidate IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery complete evidence missing';END IF;
 PERFORM zasp_temporal72.require_current_run(r,budget);
 effect_value:=encode(digest(convert_to(concat_ws(chr(31),'discovery72-apply',o,w,e,j,complete_receipt),'UTF8'),'sha256'),'hex');
 INSERT INTO zasp_temporal72.apply_effects(organization_id,workspace_id,environment_id,job_id,effect_id,complete_digest) VALUES(o,w,e,j,effect_value,complete_receipt);
 UPDATE zasp_temporal72.runs SET state='applying' WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 RETURN jsonb_build_object('effect_id',effect_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.prepare_page(o text, w text, e text, j text, i text, input_digest text, budget timestamp with time zone, expected bigint, expected_digest text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;p zasp_temporal72.page_effects%ROWTYPE;waiting zasp_temporal72.page_waits%ROWTYPE;reservation public.zasp_discovery_generation_reservations%ROWTYPE;sync_row public.zasp_discovery_syncs%ROWTYPE;effect_value text;generation_value bigint;wait_until timestamptz;wait_digest text;wait_result jsonb;
BEGIN
 PERFORM zasp_authorization80_worker.require_discovery72('prepare_page',zasp_authorization80_worker.discovery72_request('prepare_page',o,w,e,j,jsonb_build_object('integration_id',i,'input_digest',input_digest,'budget_us',floor(extract(epoch FROM budget)*1000000)::bigint,'expected',expected,'expected_digest',expected_digest)));
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id,integration_id)=(o,w,e,j,i) FOR UPDATE;
 IF NOT FOUND OR input_digest IS DISTINCT FROM encode(r.request_digest,'hex') OR budget IS NULL OR budget IS DISTINCT FROM r.deadline OR expected IS NULL OR expected NOT BETWEEN 0 AND 9999 OR expected_digest IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery page intent rejected';END IF;
 SELECT * INTO waiting FROM zasp_temporal72.page_waits WHERE(organization_id,workspace_id,environment_id,job_id,expected_version)=(o,w,e,j,expected);
 IF FOUND THEN
  IF waiting.expected_digest IS DISTINCT FROM expected_digest OR EXISTS(SELECT 1 FROM zasp_temporal72.page_effects WHERE(organization_id,workspace_id,environment_id,job_id,expected_version)=(o,w,e,j,expected)) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery wait replay conflict';END IF;
  RETURN jsonb_build_object('page',waiting.result);
 END IF;
 SELECT * INTO p FROM zasp_temporal72.page_effects WHERE(organization_id,workspace_id,environment_id,job_id,expected_version)=(o,w,e,j,expected);
 IF FOUND THEN
  IF p.expected_digest IS DISTINCT FROM expected_digest THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery page replay conflict';END IF;
  RETURN jsonb_build_object('page',COALESCE(p.result,jsonb_build_object('outcome','outcome_unknown')));
 END IF;
 IF(r.checkpoint_version,r.checkpoint_digest) IS DISTINCT FROM(expected,expected_digest) OR r.state NOT IN('admitted','partial','retryable') OR r.retry_not_before>clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery page precondition rejected';END IF;
 PERFORM zasp_temporal72.require_current_run(r,budget);
 -- Retain narrow provider/generation serialization, including retained jobs.
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),o,w,e,i,r.provider),0));
 IF NOT zasp_temporal72.try_capacity_lock() OR NOT zasp_temporal72.capacity_available(o,w,e,j,i,r.provider) THEN
  wait_until:=clock_timestamp()+interval '5 seconds';
  wait_digest:=encode(digest(convert_to(jsonb_build_object('kind','discovery72-no-io-wait','organization_id',o,'workspace_id',w,'environment_id',e,'job_id',j,'expected_version',expected,'expected_digest',expected_digest,'not_before',wait_until)::text,'UTF8'),'sha256'),'hex');
  wait_result:=jsonb_build_object('outcome','retryable','checkpoint_version',expected+1,'receipt_digest',wait_digest,'retry_after_seconds',5);
  INSERT INTO zasp_temporal72.page_waits VALUES(o,w,e,j,expected,expected_digest,wait_result,wait_until);
  UPDATE zasp_temporal72.runs SET state='retryable',checkpoint_version=expected+1,checkpoint_digest=wait_digest,retry_not_before=wait_until WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
  UPDATE public.zasp_discovery_syncs SET state='queued',last_error='discovery retryable',last_error_code='retryable' WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,r.sync_id) AND state IN('queued','running');
  RETURN jsonb_build_object('page',wait_result);
 END IF;
 SELECT * INTO reservation FROM public.zasp_discovery_generation_reservations WHERE(organization_id,workspace_id,environment_id,sync_id)=(o,w,e,r.sync_id);
 IF NOT FOUND THEN
  SELECT greatest(COALESCE((SELECT max(generation) FROM public.zasp_discovery_snapshots WHERE(organization_id,workspace_id,environment_id,integration_id,source)=(o,w,e,i,r.provider)),0),COALESCE((SELECT max(generation) FROM public.zasp_discovery_generation_reservations WHERE(organization_id,workspace_id,environment_id,integration_id,source)=(o,w,e,i,r.provider)),0))+1 INTO generation_value;
  INSERT INTO public.zasp_discovery_generation_reservations(organization_id,workspace_id,environment_id,sync_id,integration_id,source,generation,snapshot_id) VALUES(o,w,e,r.sync_id,i,r.provider,generation_value,'pid_'||gen_random_uuid()::text) RETURNING * INTO reservation;
 END IF;
 effect_value:=encode(digest(convert_to(concat_ws(chr(31),'discovery72-page',o,w,e,j,reservation.generation,expected,expected_digest),'UTF8'),'sha256'),'hex');
 INSERT INTO zasp_temporal72.page_effects(organization_id,workspace_id,environment_id,job_id,expected_version,expected_digest,effect_id) VALUES(o,w,e,j,expected,expected_digest,effect_value);
 UPDATE zasp_temporal72.runs SET state='collecting' WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 UPDATE public.zasp_discovery_syncs SET state='running',attempt=1,started_at=COALESCE(started_at,clock_timestamp()),last_error=NULL,last_error_code=NULL WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,r.sync_id) RETURNING * INTO sync_row;
 RETURN jsonb_build_object('effect_id',effect_value,'input',jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'job_id',j,'sync_id',r.sync_id,'integration_id',i,'connection_id',r.connection_id,'snapshot_id',reservation.snapshot_id,'generation',reservation.generation,'observation_time',date_trunc('second',reservation.reserved_at),'provider',r.provider,'collector_version','collector_v1','credential_class',CASE r.provider WHEN 'aws' THEN 'aws_assume_role' WHEN 'kubernetes' THEN 'kubernetes_cluster' WHEN 'github' THEN 'github_installation' ELSE 'okta_refresh' END,'credential_reference',r.credential_reference,'subject_kind',r.subject_kind,'subject_id',r.subject_id,'parser_version',sync_row.parser_version,'tool_version',sync_row.tool_version,'configuration',r.configuration,'checkpoint_version',0,'deadline',r.deadline,'effect_id',effect_value)||zasp_temporal72.resume_input(r));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.public_delete_schedule(o text, w text, e text, p text, i text, k text, expected bigint, a text, c text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE intent_value jsonb;replay_value jsonb;s zasp_temporal72.schedules%ROWTYPE;body_value jsonb;
BEGIN
 PERFORM zasp_authorization80_worker.discovery72_human_begin('deleteIntegrationSchedule',o,w,e,p,i,k,a,c,receipt_value,jsonb_build_object('expected',expected));
 PERFORM zasp_temporal72.require_actor(o,w,e,p);
 IF expected IS NULL OR expected NOT BETWEEN 1 AND 999999 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery schedule delete rejected';END IF;
 intent_value:=jsonb_build_object('scope',jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e),'integration_id',i,'expected_version',expected,'idempotency_key',k,'body','{}'::jsonb);
 replay_value:=public.zasp_workflow_replay(o,w,e,p,'deleteIntegrationSchedule',k,intent_value);
 IF (replay_value->>'found')::boolean THEN PERFORM zasp_authorization80_worker.discovery72_human_replay();RETURN replay_value->'result';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'discovery72-config',o,w,e,i),0));
 SELECT * INTO s FROM zasp_temporal72.schedules WHERE(organization_id,workspace_id,environment_id,integration_id)=(o,w,e,i) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='discovery schedule missing';END IF;
 IF s.version<>expected OR s.state='deleted' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery schedule version rejected';END IF;
 UPDATE zasp_temporal72.schedules SET state='deleted',version=version+1,updated_at=clock_timestamp() WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,s.id) RETURNING * INTO s;
 body_value:=zasp_temporal72.schedule_body(o,w,e,i,true);
 RETURN zasp_authorization80_worker.discovery72_record_public_mutation(o,w,e,p,'deleteIntegrationSchedule',k,intent_value,body_value,'integration_schedule',i,s.version,a,c,receipt_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.public_put_schedule(o text, w text, e text, p text, i text, k text, expected bigint, cadence integer, state_value text, a text, c text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE intent_value jsonb;replay_value jsonb;s zasp_temporal72.schedules%ROWTYPE;body_value jsonb;now_value timestamptz;
BEGIN
 PERFORM zasp_authorization80_worker.discovery72_human_begin('putIntegrationSchedule',o,w,e,p,i,k,a,c,receipt_value,jsonb_build_object('expected',expected,'cadence',cadence,'state',state_value));
 PERFORM zasp_temporal72.require_actor(o,w,e,p);
 IF expected IS NULL OR expected<0 OR cadence IS NULL OR cadence NOT BETWEEN 300 AND 2678400 OR state_value IS NULL OR state_value NOT IN('enabled','disabled') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery schedule request rejected';END IF;
 intent_value:=jsonb_build_object('scope',jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e),'integration_id',i,'expected_version',expected,'idempotency_key',k,'body',jsonb_build_object('cadence_seconds',cadence,'state',state_value));
 replay_value:=public.zasp_workflow_replay(o,w,e,p,'putIntegrationSchedule',k,intent_value);
 IF (replay_value->>'found')::boolean THEN PERFORM zasp_authorization80_worker.discovery72_human_replay();RETURN replay_value->'result';END IF;
 PERFORM 1 FROM public.zasp_integrations WHERE (organization_id,workspace_id,environment_id,id)=(o,w,e,i) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='discovery integration missing';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'discovery72-config',o,w,e,i),0));
 SELECT * INTO s FROM zasp_temporal72.schedules WHERE (organization_id,workspace_id,environment_id,integration_id)=(o,w,e,i) FOR UPDATE;
 now_value:=clock_timestamp();
 IF expected=0 THEN
  IF FOUND THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery schedule exists';END IF;
  INSERT INTO zasp_temporal72.schedules(organization_id,workspace_id,environment_id,id,integration_id,cadence_seconds,state,next_run_at,anchor,version,created_at,updated_at)
  VALUES(o,w,e,'pid_'||gen_random_uuid()::text,i,cadence,state_value,now_value+make_interval(secs=>cadence),now_value+make_interval(secs=>cadence),1,now_value,now_value) RETURNING * INTO s;
 ELSE
  IF NOT FOUND OR s.version<>expected OR s.state='deleted' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery schedule version rejected';END IF;
  UPDATE zasp_temporal72.schedules SET cadence_seconds=cadence,state=state_value,next_run_at=now_value+make_interval(secs=>cadence),anchor=now_value+make_interval(secs=>cadence),version=version+1,updated_at=now_value WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,s.id) RETURNING * INTO s;
 END IF;
 body_value:=zasp_temporal72.schedule_body(o,w,e,i,true);
 RETURN zasp_authorization80_worker.discovery72_record_public_mutation(o,w,e,p,'putIntegrationSchedule',k,intent_value,body_value,'integration_schedule',i,s.version,a,c,receipt_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.public_request_sync(o text, w text, e text, p text, i text, k text, expected bigint, s text, j text, b text, d bytea, parser_value text, tool_value text, a text, c text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE intent_value jsonb;replay_value jsonb;body_value jsonb;version_value bigint;
BEGIN
 PERFORM zasp_authorization80_worker.discovery72_human_begin('syncIntegration',o,w,e,p,i,k,a,c,receipt_value,jsonb_build_object('expected',expected,'sync_id',s,'job_id',j,'outbox_id',b,'request_digest',encode(d,'hex'),'parser_version',parser_value,'tool_version',tool_value));
 PERFORM zasp_temporal72.require_actor(o,w,e,p);
 intent_value:=jsonb_build_object('scope',jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e),'integration_id',i,'expected_version',expected,'idempotency_key',k,'body','{}'::jsonb);
 replay_value:=public.zasp_workflow_replay(o,w,e,p,'syncIntegration',k,intent_value);
 IF (replay_value->>'found')::boolean THEN PERFORM zasp_authorization80_worker.discovery72_human_replay();RETURN replay_value->'result';END IF;
 PERFORM 1 FROM public.zasp_integrations WHERE (organization_id,workspace_id,environment_id,id,version)=(o,w,e,i,expected) AND state IN('active','degraded') FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery integration version rejected';END IF;
 PERFORM zasp_temporal72.admit(o,w,e,p,i,s,j,b,k,d,'manual',parser_value,tool_value,NULL,NULL);
 body_value:=zasp_temporal72.sync_body(o,w,e,i,s);
 SELECT version INTO STRICT version_value FROM public.zasp_discovery_syncs WHERE (organization_id,workspace_id,environment_id,id)=(o,w,e,s);
 RETURN zasp_authorization80_worker.discovery72_record_public_mutation(o,w,e,p,'syncIntegration',k,intent_value,body_value,'integration_sync',s,version_value,a,c,receipt_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.reconcile_due(o text, w text, e text, s text, i text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.schedules%ROWTYPE;result jsonb:=jsonb_build_object('outcome','not_due');BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_scheduler');
 SELECT * INTO r FROM zasp_temporal72.schedules WHERE(organization_id,workspace_id,environment_id,id,integration_id)=(o,w,e,s,i) FOR UPDATE;
 IF NOT FOUND OR r.acknowledged_revision<>r.version THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery schedule acknowledgement missing';END IF;
 IF r.state='enabled' AND r.next_run_at<=clock_timestamp() THEN result:=zasp_temporal72.scheduled_admit(o,w,e,s,i,r.version,r.next_run_at);END IF;
 UPDATE zasp_temporal72.schedules SET delivered_revision=r.version WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,s);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.record_page(o text, w text, e text, j text, effect_value text, details jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;p zasp_temporal72.page_effects%ROWTYPE;outcome_value text;digest_value text;raw_digest text;result_value jsonb;next_version bigint;delay_value integer;cursor_value jsonb;manifest_value jsonb;scope_prefix text;sync_row public.zasp_discovery_syncs%ROWTYPE;
BEGIN
 PERFORM zasp_authorization80_worker.require_discovery72('record_page',zasp_authorization80_worker.discovery72_request('record_page',o,w,e,j,jsonb_build_object('effect_id',effect_value,'details',details)));
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery receipt scope rejected';END IF;
 SELECT * INTO p FROM zasp_temporal72.page_effects WHERE(organization_id,workspace_id,environment_id,job_id,effect_id)=(o,w,e,j,effect_value) FOR UPDATE;
 IF NOT FOUND OR details IS NULL OR jsonb_typeof(details)<>'object' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery receipt rejected';END IF;
 outcome_value:=details->>'outcome';
 IF outcome_value IS NULL OR outcome_value NOT IN('partial','complete','incomplete','retryable','denied','revoked','malformed','terminal','cancelled','outcome_unknown') OR details-(CASE WHEN outcome_value='complete' THEN ARRAY['outcome','cursor','manifest','candidate'] WHEN outcome_value='partial' THEN ARRAY['outcome','cursor','manifest'] ELSE ARRAY['outcome','retry_after_seconds'] END)<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery page outcome rejected';END IF;
 delay_value:=COALESCE((details->>'retry_after_seconds')::integer,0);
 IF outcome_value='retryable' AND delay_value NOT BETWEEN 1 AND 900 OR outcome_value<>'retryable' AND delay_value<>0 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery retry delay rejected';END IF;
 digest_value:=encode(digest(convert_to(jsonb_build_object('effect_id',effect_value,'details',details)::text,'UTF8'),'sha256'),'hex');
 raw_digest:=digest_value;
 IF p.result IS NOT NULL THEN
  IF p.record_digest IS DISTINCT FROM digest_value THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery receipt immutable';END IF;RETURN p.result;
 END IF;
 IF(r.checkpoint_version,r.checkpoint_digest) IS DISTINCT FROM(p.expected_version,p.expected_digest) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='discovery receipt precondition conflict';END IF;
 IF outcome_value IN('partial','complete') THEN
  cursor_value:=details->'cursor';manifest_value:=details->'manifest';scope_prefix:='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/';
  SELECT * INTO STRICT sync_row FROM public.zasp_discovery_syncs WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,r.sync_id);
  IF NOT COALESCE(jsonb_typeof(cursor_value)='object' AND cursor_value ?& ARRAY['provider','version','value'] AND cursor_value-ARRAY['provider','version','value']='{}'::jsonb AND cursor_value->>'provider'=r.provider AND cursor_value->>'version' ~ '^[a-z][a-z0-9_.-]{1,63}$' AND length(cursor_value->>'value') BETWEEN 1 AND 2048
  AND jsonb_typeof(manifest_value)='object' AND manifest_value ?& ARRAY['reference','key','version_id','checksum','size_bytes','media_type','schema_version','parser_version','tool_version'] AND manifest_value-ARRAY['reference','key','version_id','checksum','size_bytes','media_type','schema_version','parser_version','tool_version']='{}'::jsonb
  AND public.zasp_discovery_s3_object_reference(manifest_value->>'reference') AND substring(manifest_value->>'reference' FROM '^s3://[a-z0-9][a-z0-9.-]{2,62}/(.+)$')=manifest_value->>'key' AND starts_with(manifest_value->>'key',scope_prefix) AND public.zasp_valid_product_id(substring(manifest_value->>'key' FROM length(scope_prefix)+1))
  AND length(manifest_value->>'version_id') BETWEEN 1 AND 1024 AND manifest_value->>'version_id' !~ '[[:space:][:cntrl:]]' AND manifest_value->>'checksum' ~ '^[0-9a-f]{64}$' AND manifest_value->>'checksum'<>repeat('0',64) AND (manifest_value->>'size_bytes')::bigint BETWEEN 1 AND 536870912
  AND manifest_value->>'media_type'='application/json' AND manifest_value->>'schema_version' ~ '^[a-z][a-z0-9_.-]{1,63}$' AND(manifest_value->>'parser_version',manifest_value->>'tool_version')=(sync_row.parser_version,sync_row.tool_version),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery partial manifest rejected';END IF;
  IF outcome_value='complete' AND NOT COALESCE(jsonb_typeof(details->'candidate')='object' AND (details->'candidate') ?& ARRAY['entities','relationships','evidence'] AND (details->'candidate')-ARRAY['entities','relationships','evidence']='{}'::jsonb AND jsonb_typeof(details->'candidate'->'entities')='array' AND jsonb_typeof(details->'candidate'->'relationships')='array' AND jsonb_typeof(details->'candidate'->'evidence')='array' AND jsonb_array_length(details->'candidate'->'entities')<=1000 AND jsonb_array_length(details->'candidate'->'relationships')<=2000 AND jsonb_array_length(details->'candidate'->'evidence')<=1000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery complete candidate rejected';END IF;
  IF outcome_value='complete' THEN
   details:=jsonb_set(details,'{candidate,relationships}',zasp_temporal72.normalize_relationships(o,w,e,r.integration_id,r.provider,details->'candidate'->'relationships'));
   digest_value:=encode(digest(convert_to(jsonb_build_object('effect_id',effect_value,'details',details)::text,'UTF8'),'sha256'),'hex');
  END IF;
  INSERT INTO zasp_temporal72.checkpoints(organization_id,workspace_id,environment_id,job_id,version,digest,effect_id,cursor,manifest,candidate) VALUES(o,w,e,j,1,digest_value,effect_value,cursor_value,manifest_value,details->'candidate')
  ON CONFLICT(organization_id,workspace_id,environment_id,job_id) DO UPDATE SET version=zasp_temporal72.checkpoints.version+1,digest=excluded.digest,effect_id=excluded.effect_id,cursor=excluded.cursor,manifest=excluded.manifest,candidate=excluded.candidate;
 END IF;
 next_version:=r.checkpoint_version+CASE WHEN outcome_value IN('partial','retryable') THEN 1 ELSE 0 END;
 result_value:=jsonb_build_object('outcome',outcome_value,'checkpoint_version',next_version,'receipt_digest',digest_value,'retry_after_seconds',delay_value);
 UPDATE zasp_temporal72.page_effects SET result=result_value,record_digest=raw_digest,recorded_at=clock_timestamp() WHERE(organization_id,workspace_id,environment_id,job_id,effect_id)=(o,w,e,j,effect_value);
 UPDATE zasp_temporal72.runs SET state=outcome_value,checkpoint_version=next_version,checkpoint_digest=digest_value,retry_not_before=CASE WHEN outcome_value='retryable' THEN clock_timestamp()+make_interval(secs=>delay_value) END WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 IF outcome_value='retryable' THEN
  UPDATE public.zasp_discovery_syncs SET state='queued',last_error='discovery retryable',last_error_code='retryable' WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,r.sync_id) AND state='running';
 END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.require_actor(o text, w text, e text, p text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE scope_row public.zasp_authorized_scopes%ROWTYPE;membership public.zasp_identity_memberships%ROWTYPE;
BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_api');
 SELECT * INTO membership FROM public.zasp_identity_memberships WHERE (organization_id,principal_id)=(o,p) AND active FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery actor revoked';END IF;
 scope_row:=zasp_sa_multistep_prior.lock_scope(o,w,e,p);
 IF scope_row.principal_id IS NULL OR NOT(public.zasp_effective_scope_permissions(scope_row.permissions,membership.role)?'manage_workflows') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery scope denied';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.reservation_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;job public.zasp_discovery_jobs%ROWTYPE;g public.zasp_discovery_generation_reservations%ROWTYPE;checkpoint_value bigint;checkpoint_digest_value bytea;BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 IF TG_OP<>'INSERT' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery generation evidence immutable';END IF;
 IF NOT zasp_temporal72.try_capacity_lock() THEN RAISE EXCEPTION USING ERRCODE='55P03',MESSAGE='discovery capacity acquisition contended';END IF;
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,sync_id,integration_id,provider)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.sync_id,NEW.integration_id,NEW.source);
 SELECT j.* INTO job FROM public.zasp_discovery_jobs j JOIN public.zasp_discovery_job_authorities a ON(a.organization_id,a.workspace_id,a.environment_id,a.job_id,a.sync_id,a.request_digest)=(j.organization_id,j.workspace_id,j.environment_id,j.id,j.authority_id,j.request_digest) WHERE(a.organization_id,a.workspace_id,a.environment_id,a.sync_id,a.integration_id,a.provider)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.sync_id,NEW.integration_id,NEW.source);
 IF(r.job_id IS NULL)=(job.id IS NULL) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery generation ownership ambiguous';END IF;
 IF NOT zasp_temporal72.capacity_available(NEW.organization_id,NEW.workspace_id,NEW.environment_id,COALESCE(r.job_id,job.id),NEW.integration_id,NEW.source) THEN RAISE EXCEPTION USING ERRCODE='55P03',MESSAGE='discovery collection already active';END IF;
 IF r.job_id IS NOT NULL THEN
  PERFORM zasp_temporal72.require_current_run(r,r.deadline);
 ELSE
  IF job.state<>'leased' OR job.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='retained discovery lease missing';END IF;
  IF EXISTS(SELECT 1 FROM zasp_temporal72.retained_dispatches d WHERE(d.organization_id,d.workspace_id,d.environment_id,d.job_id,d.attempt)=(job.organization_id,job.workspace_id,job.environment_id,job.id,job.attempt)) THEN RAISE EXCEPTION USING ERRCODE='55P03',MESSAGE='retained discovery preparation unresolved';END IF;
  SELECT * INTO g FROM public.zasp_discovery_generation_reservations WHERE(organization_id,workspace_id,environment_id,sync_id)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.sync_id);
  IF FOUND THEN
   -- An already allocated generation may have reached provider IO before72
   -- was installed. Only an exact prior safe completion permits another send.
   IF NOT EXISTS(SELECT 1 FROM zasp_temporal72.retained_dispatches d JOIN public.zasp_discovery_job_checkpoints c ON(c.organization_id,c.workspace_id,c.environment_id,c.job_id,c.sync_id,c.integration_id,c.provider,c.version,c.checkpoint_digest)=(d.organization_id,d.workspace_id,d.environment_id,d.job_id,d.sync_id,d.integration_id,d.provider,d.safe_checkpoint_version,d.safe_checkpoint_digest)
    WHERE(d.organization_id,d.workspace_id,d.environment_id,d.job_id,d.attempt,d.sync_id,d.integration_id,d.provider,d.generation,d.snapshot_id)=(job.organization_id,job.workspace_id,job.environment_id,job.id,job.attempt-1,g.sync_id,g.integration_id,g.source,g.generation,g.snapshot_id)
    AND d.safe_completion_digest IS NOT NULL AND d.safe_checkpoint_version>d.checkpoint_version AND d.safe_checkpoint_digest=job.result_digest) THEN RAISE EXCEPTION USING ERRCODE='55P03',MESSAGE='retained prior generation preparation unresolved';END IF;
  ELSE g:=NEW;END IF;
  SELECT version,checkpoint_digest INTO checkpoint_value,checkpoint_digest_value FROM public.zasp_discovery_job_checkpoints WHERE(organization_id,workspace_id,environment_id,job_id)=(job.organization_id,job.workspace_id,job.environment_id,job.id);
  INSERT INTO zasp_temporal72.retained_dispatches(organization_id,workspace_id,environment_id,job_id,attempt,sync_id,integration_id,provider,generation,snapshot_id,worker_id,token_digest,checkpoint_version,checkpoint_digest) VALUES(job.organization_id,job.workspace_id,job.environment_id,job.id,job.attempt,job.authority_id,NEW.integration_id,NEW.source,g.generation,g.snapshot_id,job.lease_owner,digest(convert_to(job.lease_token,'UTF8'),'sha256'),COALESCE(checkpoint_value,0),checkpoint_digest_value);
 END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.resume_input(r zasp_temporal72.runs)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c zasp_temporal72.checkpoints%ROWTYPE;prior public.zasp_discovery_cursors%ROWTYPE;
BEGIN
 SELECT * INTO c FROM zasp_temporal72.checkpoints WHERE(organization_id,workspace_id,environment_id,job_id)=(r.organization_id,r.workspace_id,r.environment_id,r.job_id);
 IF FOUND THEN RETURN jsonb_build_object('checkpoint_version',c.version,'checkpoint_effect_id',c.effect_id,'checkpoint_digest',encode(decode(c.digest,'hex'),'base64'),'cursor_provider',c.cursor->>'provider','cursor_version',c.cursor->>'version','cursor_value',c.cursor->>'value','checkpoint_manifest_reference',c.manifest->>'reference','checkpoint_manifest_key',c.manifest->>'key','checkpoint_manifest_version_id',c.manifest->>'version_id','checkpoint_manifest_checksum',encode(decode(c.manifest->>'checksum','hex'),'base64'),'checkpoint_manifest_size_bytes',(c.manifest->>'size_bytes')::bigint,'checkpoint_manifest_media_type',c.manifest->>'media_type','checkpoint_manifest_schema_version',c.manifest->>'schema_version');END IF;
 SELECT * INTO prior FROM public.zasp_discovery_cursors WHERE(organization_id,workspace_id,environment_id,integration_id,provider)=(r.organization_id,r.workspace_id,r.environment_id,r.integration_id,r.provider);
 IF FOUND THEN RETURN jsonb_build_object('cursor_provider',prior.provider,'cursor_version','cursor_v1','cursor_value',prior.cursor_value);END IF;
 RETURN '{}'::jsonb;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.retained_claim_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a public.zasp_discovery_job_authorities%ROWTYPE;BEGIN
 IF OLD.kind='discovery' AND OLD.state='leased' AND NEW.state='retryable' AND NEW.completion_digest IS NOT NULL THEN
  UPDATE zasp_temporal72.retained_dispatches d SET safe_completion_digest=NEW.completion_digest,safe_checkpoint_version=c.version,safe_checkpoint_digest=c.checkpoint_digest FROM public.zasp_discovery_job_checkpoints c
  WHERE(d.organization_id,d.workspace_id,d.environment_id,d.job_id,d.attempt,d.worker_id,d.token_digest)=(OLD.organization_id,OLD.workspace_id,OLD.environment_id,OLD.id,OLD.attempt,OLD.lease_owner,digest(convert_to(OLD.lease_token,'UTF8'),'sha256'))
  AND(c.organization_id,c.workspace_id,c.environment_id,c.job_id,c.sync_id,c.integration_id,c.provider)=(d.organization_id,d.workspace_id,d.environment_id,d.job_id,d.sync_id,d.integration_id,d.provider) AND c.version>d.checkpoint_version AND c.checkpoint_digest=NEW.result_digest AND d.safe_completion_digest IS NULL;
 END IF;
 IF NEW.kind<>'discovery' OR NEW.state<>'leased' OR(OLD.state='leased' AND NEW.attempt=OLD.attempt AND NEW.lease_owner=OLD.lease_owner AND NEW.lease_token=OLD.lease_token) THEN RETURN NEW;END IF;
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT * INTO a FROM public.zasp_discovery_job_authorities WHERE(organization_id,workspace_id,environment_id,job_id,sync_id)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.id,NEW.authority_id);
 IF NOT FOUND OR a.request_digest IS DISTINCT FROM NEW.request_digest THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='retained discovery ownership missing';END IF;
 -- Row omission is the old bulk RETURNING contract. Direct old delivery may
 -- fail its NOT NULL sync update; the supported72 wrapper returns typed busy.
 IF NOT zasp_temporal72.try_capacity_lock() OR NOT COALESCE(zasp_temporal72.retained_retry_safe(OLD),false) OR NOT zasp_temporal72.capacity_available(a.organization_id,a.workspace_id,a.environment_id,a.job_id,a.integration_id,a.provider) THEN RETURN NULL;END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.schedule_ack(o text, w text, e text, s text, i text, revision bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_scheduler');
 UPDATE zasp_temporal72.schedules SET acknowledged_revision=revision WHERE(organization_id,workspace_id,environment_id,id,integration_id,version)=(o,w,e,s,i,revision);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='discovery desired revision changed';END IF;
 RETURN jsonb_build_object('revision',revision);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.schedule_body(o text, w text, e text, i text, include_deleted boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE s zasp_temporal72.schedules%ROWTYPE;
BEGIN
 SELECT * INTO s FROM zasp_temporal72.schedules WHERE (organization_id,workspace_id,environment_id,integration_id)=(o,w,e,i) AND (include_deleted OR state<>'deleted');
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='discovery schedule missing';END IF;
 RETURN jsonb_build_object('integration_id',i,'cadence_seconds',s.cadence_seconds,'state',s.state,'time_zone','UTC','next_run_at',CASE WHEN s.state='enabled' THEN to_char(s.next_run_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END,'version',s.version,'created_at',to_char(s.created_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'updated_at',to_char(s.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.schedule_current(o text, w text, e text, s text, i text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.schedules%ROWTYPE;BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_scheduler');
 UPDATE zasp_temporal72.schedules SET delivered_revision=0,acknowledged_revision=0 WHERE(organization_id,workspace_id,environment_id,id,integration_id)=(o,w,e,s,i) RETURNING * INTO r;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery desired schedule rejected';END IF;
 RETURN jsonb_build_object('ref',jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'schedule_id',s,'integration_id',i),'revision',r.version,'cadence_seconds',r.cadence_seconds,'anchor',r.anchor,'enabled',r.state='enabled');
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.scheduled_admit(o text, w text, e text, s text, i text, revision bigint, nominal timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE schedule_row zasp_temporal72.schedules%ROWTYPE;now_value timestamptz;wakeup_anchor timestamptz;temporal_tick boolean;seed text;due_text text;d bytea;k text;result jsonb;sync_value text;job_value text;outbox_value text;
BEGIN
 temporal_tick:=EXISTS(SELECT 1 FROM zasp_temporal72.principals WHERE principal_name=session_user AND authority_role='zasp_discovery_worker');
 IF temporal_tick THEN PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');ELSE PERFORM zasp_temporal72.require_principal('zasp_discovery_scheduler');END IF;
 PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=o FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery scheduled organization missing';END IF;
 SELECT * INTO schedule_row FROM zasp_temporal72.schedules WHERE (organization_id,workspace_id,environment_id,id,integration_id)=(o,w,e,s,i) FOR UPDATE;
 IF NOT FOUND OR revision IS NULL OR schedule_row.version IS DISTINCT FROM revision OR schedule_row.state<>'enabled' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery schedule rejected';END IF;
 now_value:=clock_timestamp();
 wakeup_anchor:=schedule_row.anchor;
 IF temporal_tick AND date_trunc('second',wakeup_anchor)<>wakeup_anchor THEN wakeup_anchor:=date_trunc('second',wakeup_anchor)+interval '1 second';END IF;
 IF nominal IS NULL OR nominal>now_value OR nominal<wakeup_anchor OR mod(extract(epoch FROM nominal-wakeup_anchor),schedule_row.cadence_seconds)<>0 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='discovery occurrence rejected';END IF;
 IF schedule_row.next_run_at>now_value THEN RETURN jsonb_build_object('outcome','not_due');END IF;
 due_text:=to_char(schedule_row.next_run_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS');
 IF extract(microseconds FROM schedule_row.next_run_at)::bigint%1000000<>0 THEN due_text:=due_text||'.'||rtrim(to_char(schedule_row.next_run_at AT TIME ZONE 'UTC','US'),'0');END IF;
 due_text:=due_text||'Z';seed:=concat_ws(chr(31),s,i,due_text);
 sync_value:=public.zasp_discovery_canonical_id(o,w,e,'scheduled_sync',seed);job_value:=public.zasp_discovery_canonical_id(o,w,e,'scheduled_job',seed);outbox_value:=public.zasp_discovery_canonical_id(o,w,e,'scheduled_outbox',seed);
 d:=digest(convert_to(concat_ws(chr(31),'schedule-sync-v1',o,w,e,i,seed,schedule_row.parser_version,schedule_row.tool_version),'UTF8'),'sha256');
 k:=encode(digest(convert_to('schedule-idempotency-v1'||chr(31)||seed,'UTF8'),'sha256'),'hex');
 result:=zasp_temporal72.admit(o,w,e,s,i,sync_value,job_value,outbox_value,k,d,'schedule',schedule_row.parser_version,schedule_row.tool_version,s,schedule_row.next_run_at);
 UPDATE zasp_temporal72.schedules SET next_run_at=schedule_row.next_run_at+make_interval(secs=>((floor(extract(epoch FROM now_value-schedule_row.next_run_at)/schedule_row.cadence_seconds)+1)*schedule_row.cadence_seconds)::double precision)
 WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,s);
 PERFORM zasp_authorization80_worker.discovery72_capture_scheduled(o,w,e,job_value);
 RETURN result;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.settle(o text, w text, e text, j text, i text, input_digest text, budget timestamp with time zone, reason text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;a zasp_temporal72.apply_effects%ROWTYPE;result_value jsonb;outcome_value text;
BEGIN
 PERFORM zasp_authorization80_worker.require_discovery72('settle',zasp_authorization80_worker.discovery72_request('settle',o,w,e,j,jsonb_build_object('integration_id',i,'input_digest',input_digest,'budget_us',floor(extract(epoch FROM budget)*1000000)::bigint,'reason',reason,'receipt',receipt_value)));
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id,integration_id)=(o,w,e,j,i) FOR UPDATE;
 IF NOT FOUND OR input_digest IS DISTINCT FROM encode(r.request_digest,'hex') OR budget IS NULL OR budget IS DISTINCT FROM r.deadline OR reason IS NULL OR reason NOT IN('succeeded','incomplete','retryable','denied','revoked','malformed','terminal','cancelled','outcome_unknown','deadline','activity_failed','apply_uncertain','settlement_uncertain') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery settlement rejected';END IF;
 SELECT * INTO a FROM zasp_temporal72.apply_effects WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 IF a.result IS NOT NULL THEN
  IF NOT EXISTS(SELECT 1 FROM public.zasp_discovery_generation_reservations g JOIN public.zasp_discovery_snapshots s ON(s.organization_id,s.workspace_id,s.environment_id,s.id,s.integration_id,s.sync_id,s.source,s.generation)=(g.organization_id,g.workspace_id,g.environment_id,g.snapshot_id,g.integration_id,g.sync_id,g.source,g.generation) JOIN public.zasp_discovery_snapshot_inputs si ON(si.organization_id,si.workspace_id,si.environment_id,si.snapshot_id)=(s.organization_id,s.workspace_id,s.environment_id,s.id) JOIN public.zasp_discovery_syncs sy ON(sy.organization_id,sy.workspace_id,sy.environment_id,sy.id)=(s.organization_id,s.workspace_id,s.environment_id,s.sync_id) WHERE(g.organization_id,g.workspace_id,g.environment_id,g.sync_id)=(o,w,e,r.sync_id) AND s.complete AND s.state='complete' AND sy.state='succeeded' AND sy.snapshot_id=s.id AND encode(si.candidate_digest,'hex')=a.result->>'receipt_digest') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='discovery committed evidence inconsistent';END IF;
  IF reason='succeeded' AND receipt_value IS DISTINCT FROM a.result->>'receipt_digest' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery completion receipt rejected';END IF;
  RETURN a.result;
 END IF;
 IF reason='succeeded' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery success evidence missing';END IF;
 IF a.effect_id IS NOT NULL OR EXISTS(SELECT 1 FROM zasp_temporal72.page_effects WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j) AND(result IS NULL OR result->>'outcome'='outcome_unknown')) THEN outcome_value:='outcome_unknown';
 ELSE outcome_value:=CASE WHEN reason IN('denied','revoked','malformed','terminal') THEN reason ELSE 'incomplete' END;END IF;
 UPDATE zasp_temporal72.runs SET state=outcome_value WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 UPDATE public.zasp_discovery_syncs SET state='failed',completed_at=COALESCE(completed_at,clock_timestamp()),last_error='discovery '||outcome_value,last_error_code=CASE WHEN outcome_value='incomplete' THEN 'partial' ELSE outcome_value END WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,r.sync_id) AND state IN('queued','running');
 PERFORM public.zasp_execution_bump_freshness(o,w,e,i);
 RETURN jsonb_build_object('outcome',outcome_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.start_delivery(o text, w text, e text, j text, payload_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_worker');
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,job_id)=(o,w,e,j);
 IF NOT FOUND OR payload_value IS NULL OR NOT EXISTS(SELECT 1 FROM public.zasp_discovery_outbox b WHERE(b.organization_id,b.workspace_id,b.environment_id,b.id,b.topic,b.payload_version)=(o,w,e,r.outbox_id,'discovery-jobs',1) AND b.payload=payload_value AND b.payload_digest=digest(convert_to(b.payload::text,'UTF8'),'sha256')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery start delivery rejected';END IF;
 -- Loading an original start is evidence/readback, not fresh-effect authority.
 RETURN zasp_temporal72.start_receipt(r)||jsonb_build_object('continuation',jsonb_build_object('checkpoint_version',0,'receipt_digest','','deadline',r.deadline));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.sync_body(o text, w text, e text, i text, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r zasp_temporal72.runs%ROWTYPE;b jsonb;
BEGIN
 b:=public.zasp_execution_sync_body(o,w,e,i,s);
 SELECT * INTO r FROM zasp_temporal72.runs WHERE(organization_id,workspace_id,environment_id,integration_id,sync_id)=(o,w,e,i,s);
 IF FOUND THEN
  IF (b->>'attempt')::integer NOT IN(0,1) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery run projection rejected';END IF;
  IF b->>'status'='queued' AND (b->>'attempt')::integer=0 AND r.state='retryable' AND NOT EXISTS(SELECT 1 FROM zasp_temporal72.page_waits wait WHERE(wait.organization_id,wait.workspace_id,wait.environment_id,wait.job_id,wait.expected_version+1)=(o,w,e,r.job_id,r.checkpoint_version) AND wait.result->>'receipt_digest'=r.checkpoint_digest AND wait.not_before=r.retry_not_before) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='discovery wait projection rejected';END IF;
  b:=b||jsonb_build_object('retry_at',CASE WHEN b->>'status'='queued' AND r.state='retryable' THEN to_char(r.retry_not_before AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') ELSE NULL END);
 ELSIF (b->>'attempt')::integer=0 AND (b->>'status' IN('failed','cancelled') OR b->>'status'='queued' AND (b->>'last_error_code' IS NOT NULL OR b->>'retry_at' IS NOT NULL)) THEN
  RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='legacy terminal attempt rejected';
 END IF;
 RETURN b;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.sync_detail(o text, w text, e text, i text, s text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE b jsonb;v bigint;
BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_api');
 b:=zasp_temporal72.sync_body(o,w,e,i,s);
 SELECT version INTO STRICT v FROM public.zasp_discovery_syncs WHERE(organization_id,workspace_id,environment_id,integration_id,id)=(o,w,e,i,s);
 RETURN jsonb_build_object('body',b,'version',v);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal72.sync_history(o text, w text, e text, i text, before_time timestamp with time zone, before_id text, lim integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE b jsonb;items jsonb;
BEGIN
 PERFORM zasp_temporal72.require_principal('zasp_discovery_api');
 b:=public.zasp_execution_sync_history(o,w,e,i,before_time,before_id,lim);
 SELECT COALESCE(jsonb_agg(zasp_temporal72.sync_body(o,w,e,i,item->>'id') ORDER BY ordinal),'[]'::jsonb) INTO items FROM jsonb_array_elements(b->'items') WITH ORDINALITY x(item,ordinal);
 RETURN b||jsonb_build_object('items',items);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal73.admit(o text, w text, e text, d text, v bigint, k text, t text, tv bigint, r text, actor_value text, audit_value text, correlation_value text, automatic_value boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row public.zasp_security_agent_definitions%ROWTYPE;prior public.zasp_security_agent_trigger_receipts%ROWTYPE;run_row public.zasp_security_agent_runs%ROWTYPE;
 binding_value jsonb;trigger_value jsonb;created_value boolean:=false;action_value text;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(d) AND public.zasp_valid_product_id(t) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value) AND v BETWEEN 1 AND 1000000 AND tv>=0,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test admission rejected';END IF;
 -- The same organization guard used by budget claim precedes all work rows.
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 SELECT * INTO definition_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR definition_row.activation NOT IN('supervised','autonomous') OR definition_row.body->>'autonomy' IS DISTINCT FROM definition_row.activation OR definition_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb OR definition_row.body->>'trigger_kind' IS DISTINCT FROM k THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission definition changed';END IF;
 action_value:=definition_row.body->'allowed_actions'->>0;
 binding_value:=zasp_temporal70.body15(o,w,e,d,v);
 IF action_value NOT IN('run_test','rerun_test','start_attack_lab') OR definition_row.body->'allowed_actions' IS DISTINCT FROM jsonb_build_array(action_value) OR definition_row.body->>'verification_kind' IS DISTINCT FROM (CASE action_value WHEN 'start_attack_lab' THEN 'attack_lab_run' ELSE 'test_run' END) OR NOT (definition_row.body->>'max_ai_cost_nano_credits' ~ '^[0-9]{1,13}$') OR (definition_row.body->>'max_ai_cost_nano_credits')::bigint NOT BETWEEN 1 AND 1000000000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission configuration changed';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,action_value);
 trigger_value:=public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',tv);
 SELECT * INTO prior FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_version)=(o,w,e,d,t,(trigger_value->>'version')::bigint) FOR SHARE;
 IF FOUND THEN
  SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,prior.run_id) FOR SHARE;
  IF NOT FOUND OR run_row.definition_id<>d OR run_row.definition_version<>v OR prior.trigger_kind<>k OR prior.trigger_digest IS DISTINCT FROM decode(trigger_value->>'digest','hex') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='existing test trigger intent conflict';END IF;
 ELSE
  IF zasp_temporal73.active_count(o,w,e,d) >= (definition_row.body->>'concurrency_limit')::integer THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test concurrency unavailable';END IF;
  -- Every prerequisite lock has completed before this final wall-clock check.
  IF zasp_temporal70.body15(o,w,e,d,v) IS DISTINCT FROM binding_value OR public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission authority changed';END IF;
  INSERT INTO public.zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(o,w,e,d,t,k,(trigger_value->>'version')::bigint,decode(trigger_value->>'digest','hex'),r);
  INSERT INTO public.zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(o,w,e,r,d,v,t,actor_value,'queued') RETURNING * INTO run_row;

  INSERT INTO zasp_temporal73.admissions VALUES(o,w,e,r,d,v,t,(trigger_value->>'version')::bigint,decode(trigger_value->>'digest','hex'),'retained_single_action');
  INSERT INTO zasp_temporal73.commands VALUES(o,w,e,r,1,'start');
  created_value:=true;
 END IF;
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
 VALUES(o,w,e,audit_value,correlation_value,run_row.run_id,actor_value,CASE WHEN created_value THEN 'run_queued' ELSE 'run_deduplicated' END,decode(trigger_value->>'digest','hex'),jsonb_build_object('run_id',run_row.run_id,'definition_id',d,'definition_version',v,'trigger_kind',k,'trigger_id',t,'trigger_version',trigger_value->'version','automatic',automatic_value,'action',action_value));
 PERFORM zasp_temporal70.body15(o,w,e,d,v);
 IF public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired';END IF;
 UPDATE public.zasp_security_agent_execution_state SET used_at=coalesce(used_at,clock_timestamp()) WHERE singleton;
 IF zasp_temporal70.body15(o,w,e,d,v) IS DISTINCT FROM binding_value OR public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired after final write';END IF;
 RETURN jsonb_build_object('id',run_row.run_id,'agent_id',d,'state',run_row.state,'evidence_ids',jsonb_build_array(t),'definition_version',v,'version',run_row.version,'created',created_value,'replayed',NOT created_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal73.capacity_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE bound_value integer;BEGIN
 IF NEW.state='simulated' THEN RETURN NEW;END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='admission requires read committed';END IF;
 IF NOT zasp_temporal73.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='admission release unavailable';END IF;
 IF NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||NEW.organization_id,0)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='admission organization busy';END IF;
 SELECT (body->>'concurrency_limit')::integer INTO bound_value FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.definition_id,NEW.definition_version) AND deleted_at IS NULL FOR SHARE;
 IF bound_value IS NULL OR bound_value<1 OR zasp_temporal73.active_count(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.definition_id)>=bound_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='admission definition capacity unavailable';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal73.schedule_body(worker_value text, limit_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;result_value jsonb;created_value integer:=0;run_value text;prior_count integer;admissions_value jsonb:='[]'::jsonb;admitted_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent principal unavailable';END IF;
 IF NOT COALESCE(length(worker_value) BETWEEN 1 AND 128 AND limit_value BETWEEN 1 AND 25,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test schedule rejected';END IF;
 IF NOT zasp_temporal70.guard01(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 FOR candidate IN
  SELECT d.organization_id o,d.workspace_id w,d.environment_id e,d.definition_id d,d.version v,d.body->>'trigger_kind' k,x.id t,x.version tv
  FROM public.zasp_security_agent_definitions d CROSS JOIN LATERAL (
   SELECT f.id,f.version FROM public.zasp_risk_findings f WHERE (f.organization_id,f.workspace_id,f.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='finding' AND f.status='open' AND f.rule=d.body->>'trigger_source'
   UNION ALL SELECT p.id,p.version FROM public.zasp_risk_attack_paths p WHERE (p.organization_id,p.workspace_id,p.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='attack_path' AND p.state=d.body->>'trigger_source' AND p.state IN('observed','verified') AND public.zasp_risk_attack_path_valid(p)
   UNION ALL SELECT ev.classification->>'session_id',ev.sequence FROM public.zasp_runtime_gateway_events ev
    JOIN public.zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(ev.organization_id,ev.workspace_id,ev.environment_id,ev.device_id,'active')
    JOIN public.zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(ev.organization_id,ev.workspace_id,ev.environment_id,ev.device_id,ev.credential_id)
    WHERE (ev.organization_id,ev.workspace_id,ev.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='runtime_decision' AND ev.decision='block' AND ev.classification->>'outcome'=d.body->>'trigger_source' AND ev.occurred_at>=clock_timestamp()-interval '5 minutes' AND ev.occurred_at<=clock_timestamp() AND public.zasp_valid_product_id(ev.classification->>'session_id')
    AND credential.revoked_at IS NULL AND credential.expires_at>clock_timestamp()
    AND credential.id=(SELECT c.id FROM public.zasp_gateway_credentials c WHERE (c.organization_id,c.workspace_id,c.environment_id,c.device_id)=(d.organization_id,d.workspace_id,d.environment_id,ev.device_id) AND c.revoked_at IS NULL AND c.expires_at>clock_timestamp() ORDER BY c.issued_at DESC,c.id DESC LIMIT 1)
    AND ev.event_id=(SELECT newest.event_id FROM public.zasp_runtime_gateway_events newest WHERE (newest.organization_id,newest.workspace_id,newest.environment_id,newest.classification->>'session_id',newest.decision,newest.classification->>'outcome')=(d.organization_id,d.workspace_id,d.environment_id,ev.classification->>'session_id','block',d.body->>'trigger_source') AND newest.occurred_at<=clock_timestamp() ORDER BY newest.occurred_at DESC,newest.sequence DESC,newest.event_id DESC LIMIT 1)
  ) x
  WHERE d.deleted_at IS NULL AND d.activation IN('supervised','autonomous') AND d.body->'enabled'='true'::jsonb AND d.body ? 'existing_test'
   AND zasp_temporal70.body04(d.organization_id,d.workspace_id,d.environment_id,d.body,d.activation)
   AND zasp_temporal73.active_count(d.organization_id,d.workspace_id,d.environment_id,d.definition_id)<(d.body->>'concurrency_limit')::integer
   AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.trigger_id,tr.trigger_version)=(d.organization_id,d.workspace_id,d.environment_id,d.definition_id,x.id,x.version))
  -- Scan work is capped independently of successful admissions. A refused
  -- candidate must not consume the entire caller's successful-work allowance.
  ORDER BY d.organization_id,d.workspace_id,d.environment_id,d.definition_id,x.id,x.version DESC LIMIT least(100,limit_value*4)
 LOOP
  EXIT WHEN created_value>=limit_value;
  BEGIN
   -- Skip contended organizations before entering the blocking shared core.
   CONTINUE WHEN NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||candidate.o,0));
   run_value:=public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_run',concat_ws(chr(31),candidate.d,candidate.v,candidate.k,candidate.t,candidate.tv));
   result_value:=zasp_temporal73.admit(candidate.o,candidate.w,candidate.e,candidate.d,candidate.v,candidate.k,candidate.t,candidate.tv,run_value,worker_value,public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_audit',run_value),public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_correlation',run_value),true);
   IF (result_value->>'created')::boolean THEN
    created_value:=created_value+1;
    admissions_value:=admissions_value||jsonb_build_array(jsonb_build_object('o',candidate.o,'w',candidate.w,'e',candidate.e,'d',candidate.d,'v',candidate.v,'r',run_value));
   END IF;
  EXCEPTION WHEN SQLSTATE '40001' OR SQLSTATE '42501' OR SQLSTATE '55000' OR SQLSTATE '23505' THEN
   -- A stale candidate rolls back its whole subtransaction, including receipts.
   CONTINUE;
  END;
 END LOOP;
 IF created_value<limit_value THEN
  prior_count:=(public.zasp_security_agent_schedule_triggers_v33(worker_value,limit_value-created_value)->>'created')::integer;
  IF prior_count IS NULL OR prior_count<0 OR prior_count>limit_value-created_value THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test scheduler bound violated';END IF;
  created_value:=created_value+prior_count;
 END IF;
 IF NOT zasp_temporal70.guard01(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 -- Later candidates and the delegated legacy scheduler can block after an
 -- earlier test admission. Revalidate every new test run at the commit edge.
 FOR admitted_value IN SELECT value FROM jsonb_array_elements(admissions_value) LOOP
  PERFORM zasp_temporal70.body15(admitted_value->>'o',admitted_value->>'w',admitted_value->>'e',admitted_value->>'d',(admitted_value->>'v')::bigint);
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr JOIN public.zasp_security_agent_definitions d ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id)=(tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id)
   WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.run_id)=(admitted_value->>'o',admitted_value->>'w',admitted_value->>'e',admitted_value->>'d',admitted_value->>'r')
    AND public.zasp_production_security_agent_existing_tests_trigger(tr.organization_id,tr.workspace_id,tr.environment_id,tr.trigger_kind,tr.trigger_id,d.body->>'trigger_source',tr.trigger_version)=jsonb_build_object('version',tr.trigger_version,'digest',encode(tr.trigger_digest,'hex'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test scheduled admission changed before commit';END IF;
 END LOOP;
 RETURN jsonb_build_object('created',created_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal74.accept_control(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;v zasp_temporal74.control_intents%ROWTYPE;t timestamptz;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test control acceptance rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest','control_id']) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test control acceptance shape rejected';END IF;
 x:=zasp_temporal74.start_identity(q-'control_id');
 SELECT * INTO STRICT v FROM zasp_temporal74.control_intents WHERE (organization_id,workspace_id,environment_id,run_id,control_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,q->>'control_id');
 PERFORM zasp_temporal74.control_value(v);
 INSERT INTO zasp_temporal74.control_receipts(organization_id,workspace_id,environment_id,control_id) VALUES(v.organization_id,v.workspace_id,v.environment_id,v.control_id) ON CONFLICT DO NOTHING;
 SELECT accepted_at INTO STRICT t FROM zasp_temporal74.control_receipts WHERE (organization_id,workspace_id,environment_id,control_id)=(v.organization_id,v.workspace_id,v.environment_id,v.control_id);
 RETURN jsonb_build_object('control_id',v.control_id,'workflow_id',x.workflow_id,'accepted_at',to_char(t AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.accept_start(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;accepted timestamptz;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test start acceptance rejected';END IF;
 x:=zasp_temporal74.start_identity(q);
 INSERT INTO zasp_temporal74.start_deliveries(organization_id,workspace_id,environment_id,run_id,accepted_at) VALUES(x.organization_id,x.workspace_id,x.environment_id,x.run_id,clock_timestamp())
 ON CONFLICT(organization_id,workspace_id,environment_id,run_id) DO UPDATE SET accepted_at=COALESCE(zasp_temporal74.start_deliveries.accepted_at,EXCLUDED.accepted_at) RETURNING accepted_at INTO accepted;
 RETURN jsonb_build_object('workflow_id',x.workflow_id,'accepted_at',to_char(accepted AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.activate_core(organization_value text, workspace_value text, environment_value text, definition_value text, actor_value text, idempotency_value text, expected_version bigint, target_activation text, fresh_auth_expires_value timestamp with time zone, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE binding_value jsonb; definition_row zasp_security_agent_definitions%ROWTYPE; receipt_row zasp_security_agent_request_receipts%ROWTYPE; action_value text; intent_value jsonb; response_value jsonb; intent_digest_value bytea;
BEGIN
 PERFORM public.zasp_sa_export_legacy_definition_fence(organization_value,workspace_value,environment_value,definition_value,NULL);
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR expected_version<=0 OR target_activation NOT IN('validated','supervised','autonomous') OR length(actor_value) NOT BETWEEN 1 AND 128 OR length(audit_value) NOT BETWEEN 1 AND 128 OR length(correlation_value) NOT BETWEEN 1 AND 128 OR length(receipt_value) NOT BETWEEN 1 AND 128
     OR length(idempotency_value) NOT BETWEEN 16 AND 128 OR idempotency_value!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' OR fresh_auth_expires_value IS NULL OR fresh_auth_expires_value<=clock_timestamp() OR fresh_auth_expires_value>transaction_timestamp()+interval '5 minutes 5 seconds' THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent activation rejected';
  END IF;
  intent_value:=jsonb_build_object('activation',target_activation,'expected_version',expected_version,'resource_id',definition_value);
  intent_digest_value:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,actor_value,'activateSecurityAgent',idempotency_value),0));
  SELECT * INTO receipt_row FROM zasp_security_agent_request_receipts receipt
  WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.principal_id,receipt.operation,receipt.idempotency_key)=(organization_value,workspace_value,environment_value,actor_value,'activateSecurityAgent',idempotency_value);
  IF FOUND THEN
    IF receipt_row.resource_id<>definition_value OR receipt_row.expected_version<>expected_version OR receipt_row.intent_digest<>intent_digest_value OR receipt_row.expires_at<=clock_timestamp()
       OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_definitions current_definition WHERE (current_definition.organization_id,current_definition.workspace_id,current_definition.environment_id,current_definition.definition_id)=(organization_value,workspace_value,environment_value,definition_value) AND current_definition.deleted_at IS NULL) THEN
      RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='security agent activation replay conflict';
    END IF;

    IF fresh_auth_expires_value<=clock_timestamp() OR receipt_row.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent activation authority expired';END IF;
    IF target_activation IN('supervised','autonomous') AND EXISTS(SELECT 1 FROM public.zasp_security_agent_definition_versions h
      WHERE (h.organization_id,h.workspace_id,h.environment_id,h.definition_id,h.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version)
       AND (h.definition ? 'existing_test' OR h.definition->'allowed_actions' ?| ARRAY['run_test','rerun_test','start_attack_lab'])) THEN
     SELECT * INTO definition_row FROM public.zasp_security_agent_definitions
      WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(organization_value,workspace_value,environment_value,definition_value,(receipt_row.response->>'version')::bigint) AND deleted_at IS NULL FOR SHARE;
     IF NOT FOUND OR definition_row.activation IS DISTINCT FROM target_activation OR definition_row.body->>'autonomy' IS DISTINCT FROM target_activation OR definition_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test activation replay changed';END IF;
     binding_value:=zasp_temporal71.body21(organization_value,workspace_value,environment_value,definition_value,definition_row.version);
     PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(organization_value,workspace_value,environment_value,definition_row.body->'allowed_actions'->>0);
     PERFORM zasp_temporal71.body21(organization_value,workspace_value,environment_value,definition_value,definition_row.version);
     IF (receipt_row.intent->>'fresh_auth_expires_at')::timestamptz IS NULL OR (receipt_row.intent->>'fresh_auth_expires_at')::timestamptz<=clock_timestamp() OR fresh_auth_expires_value<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent activation authority expired';END IF;
    END IF;
    RETURN receipt_row.response||jsonb_build_object('replayed',true);
  END IF;
  SELECT * INTO definition_row FROM zasp_security_agent_definitions candidate
  WHERE (candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id,candidate.version)=(organization_value,workspace_value,environment_value,definition_value,expected_version)
    AND candidate.deleted_at IS NULL FOR UPDATE;
  IF NOT FOUND OR NOT ((definition_row.activation='draft' AND target_activation='validated') OR (definition_row.activation='validated' AND target_activation='supervised') OR (definition_row.activation='supervised' AND target_activation='autonomous')) THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent activation conflict';
  END IF;

  IF definition_row.body ? 'existing_test' OR definition_row.body->'allowed_actions' ?| ARRAY['run_test','rerun_test','start_attack_lab'] THEN
   binding_value:=zasp_temporal71.body21(organization_value,workspace_value,environment_value,definition_value,expected_version);
   IF target_activation IN('supervised','autonomous') THEN
    PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(organization_value,workspace_value,environment_value,definition_row.body->'allowed_actions'->>0);
    PERFORM zasp_temporal71.body21(organization_value,workspace_value,environment_value,definition_value,expected_version);
    IF fresh_auth_expires_value<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent activation authority expired';END IF;
   END IF;
  END IF;
  IF target_activation IN('supervised','autonomous') THEN
    IF NOT COALESCE(CASE WHEN jsonb_typeof(definition_row.body->'max_ai_cost_nano_credits')='number'
      AND definition_row.body->>'max_ai_cost_nano_credits' ~ '^[0-9]{1,13}$'
      THEN (definition_row.body->>'max_ai_cost_nano_credits')::bigint BETWEEN 1 AND 1000000000000
      ELSE false END,false) THEN
      RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent cost budget configuration required';
    END IF;

    IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent execution disabled';
    END IF;
    INSERT INTO zasp_security_agent_kill_switches(organization_id,workspace_id,environment_id,action_key,execution_enabled,updated_by)
    VALUES(organization_value,workspace_value,environment_value,'*',true,actor_value)
    ON CONFLICT(organization_id,workspace_id,environment_id,action_key) DO NOTHING;
    IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) THEN
      RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent execution disabled';
    END IF;
    FOR action_value IN SELECT jsonb_array_elements_text(definition_row.body->'allowed_actions') LOOP
      INSERT INTO zasp_security_agent_kill_switches(organization_id,workspace_id,environment_id,action_key,execution_enabled,updated_by)
      VALUES(organization_value,workspace_value,environment_value,action_value,true,actor_value)
      ON CONFLICT(organization_id,workspace_id,environment_id,action_key) DO NOTHING;
      IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,action_value,true)) THEN
        RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent action disabled';
      END IF;
    END LOOP;
  END IF;
  UPDATE zasp_security_agent_definitions candidate SET activation=target_activation,version=candidate.version+1,body=candidate.body||jsonb_build_object('enabled',target_activation IN('supervised','autonomous')),updated_at=transaction_timestamp()
  WHERE (candidate.organization_id,candidate.workspace_id,candidate.environment_id,candidate.definition_id)=(organization_value,workspace_value,environment_value,definition_value)
  RETURNING * INTO definition_row;
  INSERT INTO zasp_security_agent_definition_versions(organization_id,workspace_id,environment_id,definition_id,version,activation,definition,definition_digest,actor_id)
  VALUES(organization_value,workspace_value,environment_value,definition_value,definition_row.version,target_activation,definition_row.body,digest(convert_to(definition_row.body::text,'UTF8'),'sha256'),actor_value);
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,actor_id,event_kind,event_digest,body)
  VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,actor_value,'definition_activated',digest(convert_to(jsonb_build_object('definition_id',definition_value,'activation',target_activation,'version',definition_row.version)::text,'UTF8'),'sha256'),jsonb_build_object('definition_id',definition_value,'activation',target_activation,'version',definition_row.version,'allowed_actions',definition_row.body->'allowed_actions'));
  response_value:=jsonb_build_object('id',definition_value,'activation',target_activation,'enabled',target_activation IN('supervised','autonomous'),'version',definition_row.version,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
  INSERT INTO zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id)
  VALUES(organization_value,workspace_value,environment_value,actor_value,'activateSecurityAgent',idempotency_value,definition_value,expected_version,intent_value||jsonb_build_object('fresh_auth_expires_at',fresh_auth_expires_value),intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  UPDATE zasp_security_agent_execution_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;

  IF binding_value IS NOT NULL AND zasp_temporal71.body21(organization_value,workspace_value,environment_value,definition_value,definition_row.version) IS DISTINCT FROM binding_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test activation binding changed';END IF;
  IF fresh_auth_expires_value<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent activation authority expired';END IF;
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal74.adapter_protocol(o text, w text, e text, c text, k text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE l public.zasp_security_agent_test_links%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='single-test adapter requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_temporal68.adapter_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test adapter unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(c) AND k~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test adapter scope rejected';END IF;
 SELECT * INTO l FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,c);
 IF l.test_run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='effect child unavailable';END IF;
 IF zasp_temporal74.is_owned(o,w,e,l.run_id) THEN
  IF NOT zasp_temporal74.lock_identity(o,w,e,l.run_id,c,k) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test adapter effect rejected';END IF;
  RETURN jsonb_build_object('protocol','single_test74');
 ELSIF zasp_temporal66.is_temporal(o,w,e,l.run_id) AND EXISTS(SELECT 1 FROM zasp_temporal68.effects f WHERE (f.organization_id,f.workspace_id,f.environment_id,f.run_id,f.step_id,f.generation,f.action_key,f.effect_key,f.input_digest)=(o,w,e,l.run_id,l.step_id,1,'run_test',k,l.input_digest) AND f.snapshot->'targets'->>'test_run_id'=c AND f.effect_key=zasp_temporal68.effect_identity(o,w,e,l.run_id,l.step_id,1)) THEN
  RETURN jsonb_build_object('protocol','ordered68');
 END IF;
 RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='effect adapter owner rejected';
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.admission_capacity(v jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE b integer;current_value jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='single-test shared admission isolation rejected';END IF;
 IF NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='single-test shared admission catalog unavailable';END IF;
 -- Retained claimers can already hold the parent. Never wait in inverse order.
 IF NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||(v->>'organization_id'),0)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test shared admission busy';END IF;
 SELECT (body->>'concurrency_limit')::integer INTO b FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(v->>'organization_id',v->>'workspace_id',v->>'environment_id',v->>'definition_id',(v->>'definition_version')::bigint) AND deleted_at IS NULL FOR SHARE;
 current_value:=zasp_temporal74.capacity(v->>'organization_id',v->>'workspace_id',v->>'environment_id',v->>'definition_id',v->>'run_id');
 IF b IS NULL OR b<1 OR (current_value->>'definition_count')::bigint>=b OR (current_value->>'organization_count')::bigint>=least(b,COALESCE((current_value->>'organization_limit')::integer,b)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test shared admission capacity unavailable';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.admit(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';r text:=q->>'run_id';
 j zasp_temporal74.planning_jobs%ROWTYPE;x zasp_temporal74.run_owners%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;
 cv jsonb;binding jsonb;item jsonb;plan_value jsonb;plan_digest bytea;expiry timestamptz;authorization_value text;state_value text;approval_value text;audit_value text;result_value jsonb;requester text;
BEGIN
 SELECT * INTO STRICT j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO STRICT x FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO STRICT b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 cv:=zasp_temporal74.context(o,w,e,r);
 IF j.state='admitted' THEN
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id,plan_hash)=(o,w,e,r,rr.plan_hash) AND plan_hash=digest(convert_to(plan::text,'UTF8'),'sha256')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test plan replay proof changed';END IF;
  RETURN j.receipt;
 END IF;
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_executor') OR j.state<>'artifacts' OR rr.state<>'planning' OR rr.version<>j.run_version OR j.context_value IS DISTINCT FROM cv OR j.result_value IS DISTINCT FROM zasp_temporal74.planning_result(j.raw_result,j.lookup_request->>'model',cv)
  OR q->'candidate' IS DISTINCT FROM j.result_value->'candidate' OR j.result_value->'candidate'='null'::jsonb OR j.result_value->'usage'='null'::jsonb OR j.input_version IS NULL OR j.output_version IS NULL OR b.stop_reason IS NOT NULL OR b.deadline_at<=clock_timestamp()
  OR NOT EXISTS(SELECT 1 FROM zasp_temporal74.provider_reservations p WHERE (p.organization_id,p.workspace_id,p.environment_id,p.run_id,p.attempt,p.reservation_id,p.input_digest,p.output_digest,p.total_tokens,p.cost_nano_credits)=(o,w,e,r,1,j.reservation_id,decode(substr(j.input_digest,8),'hex'),decode(substr(j.provider_digest,8),'hex'),(j.result_value->'usage'->>'total_tokens')::bigint,(j.result_value->'usage'->>'cost_nano_credits')::bigint) AND p.settled_at IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test admission proof unavailable';END IF;
 binding:=zasp_temporal71.body21(o,w,e,rr.definition_id,rr.definition_version);
 authorization_value:=CASE cv->'definition'->>'autonomy' WHEN 'autonomous' THEN 'autonomous' ELSE 'approval_required' END;
 state_value:=CASE authorization_value WHEN 'autonomous' THEN 'queued' ELSE 'waiting_approval' END;
 expiry:=least(b.deadline_at,clock_timestamp()+interval '15 minutes');
 approval_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_approval',r||chr(31)||x.step_id);
 item:=jsonb_build_object('index',0,'step_id',x.step_id,'action',x.action_key,'target_id',binding->>'definition_id','test_definition_version',binding->'definition_version','test_target_id',binding->>'target_id','test_target_kind',binding->>'target_kind','authorization',authorization_value);
 plan_value:=jsonb_build_object('definition_id',rr.definition_id,'definition_version',rr.definition_version,'catalog_version','security-agent-actions-v1','evidence_ids',jsonb_build_array(rr.trigger_id),'steps',jsonb_build_array(item),'verification',jsonb_build_object('kind','test_run'),'expires_at',to_char(expiry AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 plan_digest:=digest(convert_to(plan_value::text,'UTF8'),'sha256');
 INSERT INTO public.zasp_security_agent_plans(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_digest,catalog_version,plan,plan_hash,expires_at) VALUES(o,w,e,r,rr.definition_id,rr.definition_version,decode(x.input_digest,'hex'),'security-agent-actions-v1',plan_value,plan_digest,expiry);
 INSERT INTO public.zasp_security_agent_steps(organization_id,workspace_id,environment_id,run_id,step_id,step_index,action_key,input_digest,authorization_result,state) VALUES(o,w,e,r,x.step_id,0,x.action_key,digest(convert_to(item::text,'UTF8'),'sha256'),authorization_value,CASE authorization_value WHEN 'autonomous' THEN 'authorized' ELSE 'waiting_approval' END);
 IF authorization_value='approval_required' THEN
  requester:=rr.requested_by;
  IF x.source_kind='automatic73' THEN requester:=zasp_temporal74.authorize(o,w,e,x.definition_id,x.definition_version)->>'principal_id';END IF;
  INSERT INTO public.zasp_security_agent_approvals(organization_id,workspace_id,environment_id,approval_id,run_id,step_id,plan_hash,state,requester_id,expires_at) VALUES(o,w,e,approval_value,r,x.step_id,plan_digest,'pending',requester,expiry);
 END IF;
 UPDATE public.zasp_security_agent_runs SET state=state_value,version=version+1,plan_hash=plan_digest,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 result_value:=jsonb_build_object('contract_version',74,'outcome','admitted','organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'version',rr.version+1,'plan_hash','sha256:'||encode(plan_digest,'hex'),'step_id',x.step_id,'state',state_value,'approval_id',CASE authorization_value WHEN 'approval_required' THEN approval_value ELSE NULL END,'provider_reservation_id',j.reservation_id);
 audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_plan_admission',r);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,approval_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,audit_value,r,x.step_id,CASE authorization_value WHEN 'approval_required' THEN approval_value ELSE NULL END,rr.requested_by,CASE authorization_value WHEN 'autonomous' THEN 'run_authorized' ELSE 'approval_requested' END,digest(convert_to(result_value::text,'UTF8'),'sha256'),result_value);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.approval(o text, w text, e text, a text, actor_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 PERFORM zasp_temporal74.approval_viewer(o,w,e,actor_value);
 SELECT value INTO result_value FROM public.zasp_production_security_agent_existing_tests_approval_ctx_core(o,w,e,a) r(value);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='approval not found';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.approval_service(o text, w text, e text, d text, v bigint)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE configuration public.zasp_security_agent_definitions%ROWTYPE;history public.zasp_security_agent_definition_versions%ROWTYPE;g zasp_temporal74.service_grants%ROWTYPE;proof public.zasp_security_agent_audit%ROWTYPE;binding jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='service authority requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT public.zasp_security_agent_principal_ready('zasp_security_agent_api') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='service authority principal rejected';END IF;
 SELECT * INTO configuration FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL FOR SHARE;
 SELECT * INTO history FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) FOR SHARE;
 SELECT * INTO g FROM zasp_temporal74.service_grants WHERE (organization_id,workspace_id,environment_id,definition_id,definition_version)=(o,w,e,d,v) FOR SHARE;
 IF g.definition_id IS NULL OR configuration.definition_id IS NULL OR history.definition_id IS NULL OR configuration.activation NOT IN('supervised','autonomous')
  OR configuration.body->>'autonomy' IS DISTINCT FROM configuration.activation OR configuration.body->'enabled' IS DISTINCT FROM 'true'::jsonb
  OR configuration.body->'allowed_actions' IS DISTINCT FROM jsonb_build_array(g.action_key)
  OR g.principal_id IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_definition_service',d)
  OR history.activation IS DISTINCT FROM configuration.activation OR history.definition IS DISTINCT FROM configuration.body
  OR history.definition_digest IS DISTINCT FROM digest(convert_to(configuration.body::text,'UTF8'),'sha256') OR g.definition_digest IS DISTINCT FROM history.definition_digest
  OR EXISTS(SELECT 1 FROM zasp_temporal74.grant_revocations WHERE (organization_id,workspace_id,environment_id,definition_id,definition_version)=(o,w,e,d,v)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='service grant unavailable';END IF;
 SELECT * INTO proof FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,g.audit_id) FOR SHARE;
 IF proof.event_kind IS DISTINCT FROM 'test_service_delegated' OR proof.body->'grant' IS DISTINCT FROM to_jsonb(g) OR proof.event_digest IS DISTINCT FROM digest(convert_to(proof.body::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='service grant proof unavailable';END IF;
 binding:=zasp_temporal71.body21(o,w,e,d,v);
 IF (binding->>'definition_id',(binding->>'definition_version')::bigint,binding->>'target_id',binding->>'target_kind') IS DISTINCT FROM(g.test_definition_id,g.test_definition_version,g.target_id,g.target_kind) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='service grant target changed';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,g.action_key);
 RETURN jsonb_build_object('principal_id',g.principal_id,'definition_id',d,'definition_version',v,'action_key',g.action_key,'test',binding);
END $function$

