CREATE OR REPLACE FUNCTION zasp_temporal76.admit_body(o text, w text, e text, d text, v bigint, k text, t text, tv bigint, r text, actor_value text, audit_value text, correlation_value text, automatic_value boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row public.zasp_security_agent_definitions%ROWTYPE;prior public.zasp_security_agent_trigger_receipts%ROWTYPE;run_row public.zasp_security_agent_runs%ROWTYPE;
 binding_value jsonb;trigger_value jsonb;created_value boolean:=false;action_value text;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(d) AND public.zasp_valid_product_id(t) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value) AND v BETWEEN 1 AND 1000000 AND tv>=0,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test admission rejected';END IF;
 -- The same organization guard used by budget claim precedes all work rows.
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 SELECT * INTO definition_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR definition_row.activation NOT IN('supervised','autonomous') OR definition_row.body->>'autonomy' IS DISTINCT FROM definition_row.activation OR definition_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb OR definition_row.body->>'trigger_kind' IS DISTINCT FROM k THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission definition changed';END IF;
 action_value:=definition_row.body->'allowed_actions'->>0;
 binding_value:=zasp_temporal70.body15(o,w,e,d,v);
 IF action_value NOT IN('run_test','rerun_test','start_attack_lab') OR definition_row.body->'allowed_actions' IS DISTINCT FROM jsonb_build_array(action_value) OR definition_row.body->>'verification_kind' IS DISTINCT FROM (CASE action_value WHEN 'start_attack_lab' THEN 'attack_lab_run' ELSE 'test_run' END) OR NOT (definition_row.body->>'max_ai_cost_nano_credits' ~ '^[0-9]{1,13}$') OR (definition_row.body->>'max_ai_cost_nano_credits')::bigint NOT BETWEEN 1 AND 1000000000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission configuration changed';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,action_value);
 trigger_value:=public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',tv);
 SELECT * INTO prior FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_version)=(o,w,e,d,t,(trigger_value->>'version')::bigint) FOR SHARE;
 IF FOUND THEN
  SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,prior.run_id) FOR SHARE;
  IF NOT FOUND OR run_row.definition_id<>d OR run_row.definition_version<>v OR prior.trigger_kind<>k OR prior.trigger_digest IS DISTINCT FROM decode(trigger_value->>'digest','hex') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='existing test trigger intent conflict';END IF;
 ELSE
  IF zasp_temporal73.active_count(o,w,e,d) >= (definition_row.body->>'concurrency_limit')::integer THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test concurrency unavailable';END IF;
  -- Every prerequisite lock has completed before this final wall-clock check.
  IF zasp_temporal70.body15(o,w,e,d,v) IS DISTINCT FROM binding_value OR public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission authority changed';END IF;
  INSERT INTO public.zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(o,w,e,d,t,k,(trigger_value->>'version')::bigint,decode(trigger_value->>'digest','hex'),r);
  INSERT INTO public.zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(o,w,e,r,d,v,t,actor_value,'queued') RETURNING * INTO run_row;
  created_value:=true;
 END IF;
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
 VALUES(o,w,e,audit_value,correlation_value,run_row.run_id,actor_value,CASE WHEN created_value THEN 'run_queued' ELSE 'run_deduplicated' END,decode(trigger_value->>'digest','hex'),jsonb_build_object('run_id',run_row.run_id,'definition_id',d,'definition_version',v,'trigger_kind',k,'trigger_id',t,'trigger_version',trigger_value->'version','automatic',automatic_value,'action',action_value));
 PERFORM zasp_temporal70.body15(o,w,e,d,v);
 IF public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired';END IF;
 UPDATE public.zasp_security_agent_execution_state SET used_at=coalesce(used_at,clock_timestamp()) WHERE singleton;
 IF zasp_temporal70.body15(o,w,e,d,v) IS DISTINCT FROM binding_value OR public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired after final write';END IF;
 RETURN jsonb_build_object('id',run_row.run_id,'agent_id',d,'state',run_row.state,'evidence_ids',jsonb_build_array(t),'definition_version',v,'version',run_row.version,'created',created_value,'replayed',NOT created_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal76.capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rr public.zasp_security_agent_runs%ROWTYPE;t public.zasp_security_agent_trigger_receipts%ROWTYPE;c zasp_temporal65.commands%ROWTYPE;b jsonb;BEGIN
 IF NEW.operation<>'runSecurityAgent' THEN RETURN NEW;END IF;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.response->>'id');
 SELECT body INTO b FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(rr.organization_id,rr.workspace_id,rr.environment_id,rr.definition_id,rr.definition_version);
 IF b->'allowed_actions' NOT IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb) OR b->'max_steps'<>'1'::jsonb THEN RETURN NEW;END IF;
 SELECT * INTO c FROM zasp_temporal65.commands WHERE(organization_id,workspace_id,environment_id,run_id,kind)=(rr.organization_id,rr.workspace_id,rr.environment_id,rr.run_id,'start');
 -- A new request for an old occurrence must never transfer historical work.
 IF c.event_id IS DISTINCT FROM NEW.receipt_id OR NEW.response->'replayed'='true'::jsonb THEN RETURN NEW;END IF;
 IF NOT zasp_temporal76.current_ready() OR NOT public.zasp_security_agent_principal_ready('zasp_security_agent_api') OR c.execution_owner<>'legacy' OR rr.state<>'queued' OR rr.version<>1 OR rr.attempt<>0 OR rr.requested_by<>NEW.principal_id THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='human ownership capture rejected';END IF;
 PERFORM zasp_temporal74.human(rr.organization_id,rr.workspace_id,rr.environment_id,rr.requested_by);
 SELECT * INTO STRICT t FROM public.zasp_security_agent_trigger_receipts WHERE(organization_id,workspace_id,environment_id,run_id)=(rr.organization_id,rr.workspace_id,rr.environment_id,rr.run_id);
 INSERT INTO zasp_temporal76.admissions VALUES(rr.organization_id,rr.workspace_id,rr.environment_id,rr.run_id,c.event_id,rr.definition_id,rr.definition_version,rr.requested_by,CASE WHEN t.trigger_kind='manual' THEN 'manual65' ELSE 'resource65' END,t.trigger_id,t.trigger_version,c.input_digest);
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal76.family(o text, w text, e text, d text, actor text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE b jsonb;s public.zasp_authorized_scopes%ROWTYPE;BEGIN
 IF NOT zasp_temporal76.current_ready() OR NOT public.zasp_security_agent_principal_ready('zasp_security_agent_api') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='human test admission unavailable';END IF;
 s:=zasp_sa_multistep_prior.lock_scope(o,w,e,actor);
 IF s.principal_id IS NULL OR NOT COALESCE(s.permissions?'view',false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='human scope denied';END IF;
 SELECT body INTO b FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='human test scope denied';END IF;
 IF b->'allowed_actions' IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb) AND b->'max_steps'='1'::jsonb THEN PERFORM zasp_temporal74.human(o,w,e,actor);RETURN true;END IF;
 RETURN false;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal76.resource(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';d text:=q->>'definition_id';a text:=q->>'actor_id';b jsonb;source_value jsonb;result_value jsonb;k text;BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='human admission requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','definition_id','actor_id','idempotency_key','definition_version','run_id','trigger_kind','trigger_id','audit_id','correlation_id','receipt_id']||CASE WHEN q ? 'trigger_version' OR q ? 'trigger_source' THEN ARRAY['trigger_version','trigger_source'] ELSE ARRAY[]::text[] END) OR octet_length(q::text)>8192 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='human admission request rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 IF NOT zasp_temporal76.family(o,w,e,d,a) THEN RETURN 'null'::jsonb;END IF;
 SELECT body INTO b FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,(q->>'definition_version')::bigint) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='human definition changed';END IF;
 source_value:=CASE WHEN q ? 'trigger_version' THEN jsonb_build_object('trigger_version',q->'trigger_version','trigger_source',q->'trigger_source') ELSE '{}'::jsonb END;
 result_value:=zasp_temporal76.run_body(o,w,e,d,a,q->>'idempotency_key',(q->>'definition_version')::bigint,q->>'run_id',q->>'trigger_kind',q->>'trigger_id',q->>'audit_id',q->>'correlation_id',q->>'receipt_id','','',source_value);
 PERFORM zasp_temporal74.human(o,w,e,a);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal76.run_body(o text, w text, e text, d text, actor_value text, key_value text, v bigint, r text, k text, t text, audit_value text, correlation_value text, receipt_value text, expected_checksum text, expected_fingerprint text, human_contract jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;intent_value jsonb;intent_digest bytea;prior public.zasp_security_agent_request_receipts%ROWTYPE;definition_body jsonb;kind_value text;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent principal unavailable';END IF;
 IF NOT zasp_temporal76.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(actor_value) AND public.zasp_valid_product_id(receipt_value) AND length(key_value) BETWEEN 16 AND 128 AND key_value ~ '^[A-Za-z0-9][A-Za-z0-9._:-]*$' AND k IN('finding','attack_path','session'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test run rejected';END IF;
 SELECT body INTO definition_body FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d) AND deleted_at IS NULL;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='existing test run scope denied';END IF;
 IF NOT definition_body ? 'existing_test' AND NOT definition_body->'allowed_actions' ?| ARRAY['run_test','rerun_test','start_attack_lab'] THEN
  RETURN public.zasp_security_agent_run_v24(o,w,e,d,actor_value,key_value,v,r,k,t,audit_value,correlation_value,receipt_value);
 END IF;
 PERFORM zasp_temporal74.human(o,w,e,actor_value);
 kind_value:=CASE k WHEN 'session' THEN 'runtime_decision' ELSE k END;
 intent_value:=jsonb_build_object('definition_id',d,'expected_version',v,'trigger_kind',k,'trigger_id',t)||human_contract;
 intent_digest:=digest(convert_to(intent_value::text,'UTF8'),'sha256');
 -- Order matches shared admission before idempotency/work locks.
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),o,w,e,actor_value,'runSecurityAgent',key_value),0));
 SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor_value,'runSecurityAgent',key_value);
 IF FOUND THEN
  IF prior.resource_id<>d OR prior.expected_version<>v OR prior.intent_digest<>intent_digest OR prior.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='existing test run replay conflict';END IF;
  -- Replay validates current authority without writing another audit receipt.
  PERFORM 1 FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL AND activation IN('supervised','autonomous') FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test run definition changed';END IF;
  PERFORM zasp_temporal71.body21(o,w,e,d,v);
  PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,definition_body->'allowed_actions'->>0);
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.run_id,tr.trigger_id,tr.trigger_kind)=(o,w,e,d,prior.response->>'id',t,kind_value) AND public.zasp_production_security_agent_existing_tests_trigger(o,w,e,kind_value,t,definition_body->>'trigger_source',0)=jsonb_build_object('version',tr.trigger_version,'digest',encode(tr.trigger_digest,'hex'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test run trigger changed';END IF;
  PERFORM zasp_temporal71.body21(o,w,e,d,v);
  RETURN prior.response||jsonb_build_object('replayed',true);
 END IF;
 IF human_contract ? 'trigger_version' THEN
  IF NOT COALESCE(jsonb_typeof(human_contract->'trigger_version')='number' AND human_contract->>'trigger_version'~'^[1-9][0-9]{0,6}$' AND human_contract->>'trigger_source'=definition_body->>'trigger_source',false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='human source contract changed';END IF;
  PERFORM public.zasp_production_security_agent_existing_tests_trigger(o,w,e,kind_value,t,human_contract->>'trigger_source',(human_contract->>'trigger_version')::bigint);
 END IF;
 result_value:=(zasp_temporal76.admit_body(o,w,e,d,v,kind_value,t,0,r,actor_value,audit_value,correlation_value,false)-'created')||jsonb_build_object('audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value);
 INSERT INTO public.zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(o,w,e,actor_value,'runSecurityAgent',key_value,d,v,intent_value,intent_digest,result_value,audit_value,correlation_value,receipt_value);
 IF NOT zasp_temporal76.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 PERFORM zasp_temporal71.body21(o,w,e,d,v);
 IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.run_id,tr.trigger_id,tr.trigger_kind)=(o,w,e,d,result_value->>'id',t,kind_value) AND public.zasp_production_security_agent_existing_tests_trigger(o,w,e,kind_value,t,definition_body->>'trigger_source',tr.trigger_version)=jsonb_build_object('version',tr.trigger_version,'digest',encode(tr.trigger_digest,'hex'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission changed after receipt';END IF;
 RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal77.ack_source(o text, w text, e text, id_value text, workflow_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 PERFORM zasp_temporal77.require_executor();
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(id_value)
 AND workflow_value='automatic-source/v1/'||o||'/'||w||'/'||e||'/'||id_value,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic acceptance identity rejected';END IF;
 PERFORM 1 FROM zasp_temporal77.source_pending WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,id_value) FOR UPDATE;
 IF FOUND THEN
  INSERT INTO zasp_temporal77.source_acceptances(organization_id,workspace_id,environment_id,event_id,workflow_id) VALUES(o,w,e,id_value,workflow_value) ON CONFLICT DO NOTHING;
  DELETE FROM zasp_temporal77.source_pending WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,id_value);
  RETURN true;
 END IF;
 IF EXISTS(SELECT 1 FROM zasp_temporal77.source_acceptances WHERE(organization_id,workspace_id,environment_id,event_id,workflow_id)=(o,w,e,id_value,workflow_value)) THEN RETURN true;END IF;
 RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic acceptance source absent';
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.attempt_source(o text, w text, e text, id_value text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 PERFORM zasp_temporal77.require_executor();
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(id_value),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic delivery reference rejected';END IF;
 UPDATE zasp_temporal77.source_pending SET last_attempt_at=greatest(last_attempt_at,clock_timestamp()) WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,id_value);
 IF FOUND OR EXISTS(SELECT 1 FROM zasp_temporal77.source_acceptances WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,id_value)) THEN RETURN true;END IF;
 RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic delivery source absent';
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.capture_source()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE kind_value text;id_value text;version_value bigint;at_value timestamptz;
BEGIN
 IF TG_TABLE_SCHEMA<>'public' OR TG_LEVEL<>'ROW' OR TG_WHEN<>'AFTER' OR TG_OP NOT IN('INSERT','UPDATE') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic source capture context rejected';END IF;
 IF TG_TABLE_NAME='zasp_risk_findings' THEN kind_value:='finding';id_value:=NEW.id;version_value:=NEW.version;at_value:=NEW.updated_at;
 ELSIF TG_TABLE_NAME='zasp_risk_attack_paths' THEN kind_value:='attack_path';id_value:=NEW.id;version_value:=NEW.version;at_value:=NEW.updated_at;
 ELSIF TG_TABLE_NAME='zasp_runtime_gateway_events' AND TG_OP='INSERT' THEN kind_value:='runtime_decision';id_value:=NEW.event_id;version_value:=NEW.sequence;at_value:=NEW.occurred_at;
 ELSE RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic source capture relation rejected';END IF;
 PERFORM zasp_temporal77.put_source(NEW.organization_id,NEW.workspace_id,NEW.environment_id,kind_value,id_value,version_value,at_value);
 -- A legitimate discovery transaction updates finding.path_id without another
 -- version increment. Do not overwrite the occurrence or digest its transient
 -- row image. No network calls, matcher, or admission/budget locks belong here.
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.definition_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 IF NOT NEW.body ? 'trigger_rules' THEN RETURN NEW;END IF;
 IF NOT zasp_temporal77.ready('3b6117ba1b9b0e9cc2871bc89bf0027b7ca3d400b1354f0550c068f2145de3fb','8cac13406a1886a98cd327065e5525be28997add7a9bd359d12e7b4ed219f5ef') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='automatic trigger authority unavailable';END IF;
 IF NOT zasp_temporal77.rules_valid(NEW.body) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic trigger rules rejected';END IF;
 IF NEW.activation<>'draft' AND NOT zasp_temporal77.rules_capable(NEW.body) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic trigger action/source capability unavailable';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.deployment_compile(p jsonb, persistent boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;
BEGIN
 IF NOT p ? 'risk' THEN RETURN zasp_temporal77.legacy_deployment_compile(p,persistent);END IF;
 IF jsonb_typeof(p->'risk') IS DISTINCT FROM 'string' OR NOT COALESCE(p->>'risk' IN('low','medium','high','critical'),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy risk annotation rejected';END IF;
 result_value:=zasp_temporal77.legacy_deployment_compile(p-'risk',persistent);
 IF result_value IS NULL THEN RETURN NULL;END IF;
 -- NUL bytes are part of the Go hash contract but cannot appear in PostgreSQL
 -- text. Concatenate bytea, not chr(0) or an escaped text approximation.
 RETURN result_value||jsonb_build_object('risk',p->>'risk','digest',encode(digest(convert_to(result_value->>'rego','UTF8')||decode('00','hex')||convert_to('policy-risk-v1','UTF8')||decode('00','hex')||convert_to(p->>'risk','UTF8'),'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.legacy_deployment_compile(p jsonb, persistent boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE trigger_value text;action_value text;conditions jsonb;c jsonb;rego text;
BEGIN
 IF jsonb_typeof(p) IS DISTINCT FROM 'object' OR NOT zasp_sa_multistep_prior.deployment_bounded(p->'id',128)
  OR jsonb_typeof(p->'conditions') IS DISTINCT FROM 'array' OR jsonb_array_length(p->'conditions') NOT BETWEEN 1 AND 32 OR NOT COALESCE(p->>'action' IN('monitor','block'),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered composition policy rejected';END IF;
 trigger_value:=p->>'trigger';action_value:=p->>'action';
 IF persistent THEN
  IF NOT zasp_sa_multistep_prior.closed(p,ARRAY['id','name','scope','trigger','conditions','action','rollout','failure_mode']) OR NOT zasp_sa_multistep_prior.deployment_bounded(p->'name',256)
   OR p->>'scope' IS DISTINCT FROM 'environment' OR NOT COALESCE(trigger_value IN('tool','runtime','network','file','credential') AND p->>'rollout' IN('monitor','enforced') AND p->>'failure_mode' IN('open','closed'),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered persistent policy rejected';END IF;
  IF p->>'rollout'='monitor' THEN action_value:='monitor';END IF;
 ELSE
  IF NOT zasp_sa_multistep_prior.closed(p,ARRAY['id','trigger','action','conditions','rego','digest']) OR NOT zasp_sa_multistep_prior.deployment_bounded(p->'trigger',64) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered temporary policy rejected';END IF;
 END IF;
 FOR c IN SELECT value FROM jsonb_array_elements(p->'conditions') LOOP
  IF NOT zasp_sa_multistep_prior.closed(c,ARRAY['field','operator','value']) OR NOT zasp_sa_multistep_prior.deployment_bounded(c->'field',128)
   OR jsonb_typeof(c->'value') IS DISTINCT FROM 'string' OR NOT COALESCE(c->>'operator' IN('equals','present'),false) OR c->>'operator'='present' AND c->>'value'<>'' OR c->>'operator'='equals' AND NOT zasp_sa_multistep_prior.deployment_bounded(c->'value',256)
   OR persistent AND (c->>'operator'<>'equals' OR c->>'field' NOT IN('action','resource','principal_id','agent_id','session_id','environment_id')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered policy condition rejected';END IF;
 END LOOP;
 IF persistent THEN
  IF trigger_value NOT IN('tool','runtime') THEN RETURN NULL;END IF;
  trigger_value:=CASE trigger_value WHEN 'tool' THEN 'tool_call' ELSE 'http_request' END;
 END IF;
 SELECT jsonb_agg(value ORDER BY (value->>'field') COLLATE "C",(value->>'value') COLLATE "C") INTO conditions FROM jsonb_array_elements(p->'conditions');
 rego:=E'package zasp.runtime\n\nimport rego.v1\n\npolicy_id := '||zasp_sa_multistep_prior.deployment_json(p->'id')||E'\ntrigger := '||zasp_sa_multistep_prior.deployment_json(to_jsonb(trigger_value))||E'\n\ndefault decision := {"action": "monitor", "matched": false}\n\ndecision := {"action": '||zasp_sa_multistep_prior.deployment_json(to_jsonb(action_value))||E', "matched": true} if {\n';
 FOR c IN SELECT value FROM jsonb_array_elements(conditions) LOOP
  rego:=rego||E'\tinput['||zasp_sa_multistep_prior.deployment_json(c->'field')||CASE WHEN c->>'operator'='present' THEN '] != ""' ELSE '] == '||zasp_sa_multistep_prior.deployment_json(c->'value') END||E'\n';
 END LOOP;
 rego:=rego||E'}\n';
 RETURN jsonb_build_object('id',p->>'id','trigger',trigger_value,'action',action_value,'conditions',conditions,'rego',rego,'digest',encode(digest(convert_to(rego,'UTF8'),'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.pending_sources(limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 PERFORM zasp_temporal77.require_executor();
 IF limit_value IS NULL OR limit_value NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic delivery page bound rejected';END IF;
 IF (SELECT enabled FROM zasp_temporal75.configuration ORDER BY revision DESC LIMIT 1) IS DISTINCT FROM true THEN RETURN '[]'::jsonb;END IF;
 RETURN (SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',organization_id,'workspace_id',workspace_id,'environment_id',environment_id,'event_id',event_id) ORDER BY last_attempt_at,organization_id,workspace_id,environment_id,event_id),'[]'::jsonb)
  FROM(SELECT * FROM zasp_temporal77.source_pending ORDER BY last_attempt_at,organization_id,workspace_id,environment_id,event_id LIMIT limit_value) pending);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.put_source(o text, w text, e text, k text, id_value text, v bigint, at_value timestamp with time zone)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE inserted integer;BEGIN
 IF k='runtime_decision' THEN
  PERFORM 1 FROM zasp_authorization79.organizations WHERE organization_id=o FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime source organization unavailable';END IF;
 END IF;
 INSERT INTO zasp_temporal77.source_events(organization_id,workspace_id,environment_id,event_id,source_kind,source_id,source_version,source_at)
 VALUES(o,w,e,public.zasp_discovery_canonical_id(o,w,e,'automatic_source_v1',concat_ws(chr(31),k,id_value,v)),k,id_value,v,at_value)
 ON CONFLICT(organization_id,workspace_id,environment_id,source_kind,source_id,source_version) DO NOTHING;
 GET DIAGNOSTICS inserted=ROW_COUNT;RETURN inserted=1;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.record_gateway_event(credential_value text, event_value text, expected_floor_value bigint, next_floor_value bigint, request_digest_value bytea, policy_version_value bigint, decision_value text, action_kind_value text, classification_value jsonb, policy_ids_value jsonb, occurred_value timestamp with time zone, evaluation_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;base_value jsonb;canonical_digest bytea;legacy_digest_value bytea;result_value jsonb;prior zasp_temporal77.runtime_evaluations%ROWTYPE;
BEGIN
 IF NOT zasp_temporal77.ready('3b6117ba1b9b0e9cc2871bc89bf0027b7ca3d400b1354f0550c068f2145de3fb','8cac13406a1886a98cd327065e5525be28997add7a9bd359d12e7b4ed219f5ef') OR NOT public.zasp_runtime_principal_ready('zasp_gateway_control') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic runtime authority unavailable';END IF;
 IF NOT zasp_temporal77.evaluation_valid(evaluation_value,decision_value,policy_ids_value,classification_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway evaluation rejected';END IF;
 authority_value:=public.zasp_runtime_gateway_credential_authority(credential_value,'runtime-gateway');
 base_value:=jsonb_build_object('credential_id',credential_value,'device_id',authority_value->>'device_id','event_id',event_value,'expected_floor',expected_floor_value,'next_floor',next_floor_value,'policy_version',policy_version_value,'decision',decision_value,'action_kind',action_kind_value,'classification',classification_value,'policy_ids',policy_ids_value,'occurred_at',to_char(occurred_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 canonical_digest:=digest(convert_to((base_value||jsonb_build_object('evaluation',evaluation_value))::text,'UTF8'),'sha256');
 IF request_digest_value IS DISTINCT FROM canonical_digest THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway evaluation digest rejected';END IF;
 legacy_digest_value:=digest(convert_to(base_value::text,'UTF8'),'sha256');
 -- The original writer validates credential/device/floor and takes its existing
 -- device lock. Keep its canonical event bytes and receipt contract unchanged.
 result_value:=public.zasp_runtime_gateway_record_event_v27(credential_value,event_value,expected_floor_value,next_floor_value,legacy_digest_value,policy_version_value,decision_value,action_kind_value,classification_value,policy_ids_value,occurred_value);
 IF result_value->>'outcome'='record_window_expired' THEN RETURN result_value;END IF;
 IF result_value->'replayed'='true'::jsonb THEN
  SELECT * INTO prior FROM zasp_temporal77.runtime_evaluations WHERE (organization_id,workspace_id,environment_id,event_id)=(authority_value->>'organization_id',authority_value->>'workspace_id',authority_value->>'environment_id',event_value);
  IF NOT FOUND OR (prior.evaluation,prior.request_digest,prior.legacy_digest) IS DISTINCT FROM (evaluation_value,canonical_digest,legacy_digest_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='gateway evaluation replay rejected';END IF;
 ELSE
  INSERT INTO zasp_temporal77.runtime_evaluations(organization_id,workspace_id,environment_id,event_id,evaluation,request_digest,legacy_digest) VALUES(authority_value->>'organization_id',authority_value->>'workspace_id',authority_value->>'environment_id',event_value,evaluation_value,canonical_digest,legacy_digest_value);
 END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.risk_mutate(requested_operation text, requested_finding_id text, requested_organization_id text, requested_workspace_id text, requested_environment_id text, requested_principal_id text, requested_idempotency_key text, expected_version bigint, requested_status text, requested_reason text, requested_audit_id text, requested_correlation_id text, requested_receipt_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
AS $function$
DECLARE
    requested_intent jsonb;
    digest_value bytea;
    prior_digest bytea;
    prior_response jsonb;
    result_version bigint;
    result_body jsonb;
BEGIN
    LOCK TABLE "public"."zasp_risk_findings", "public"."zasp_workflow_idempotency", "public"."zasp_workflow_audit", "public"."zasp_workflow_receipts" IN ROW EXCLUSIVE MODE;
    PERFORM zasp_temporal77.require_risk_ready();
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" release JOIN "public"."zasp_schema_metadata" marker ON marker."key"='production_core_schema' AND marker."value"='production-recovery-v1' WHERE release."version"=27 AND release."name"='production_recovery' AND NOT EXISTS (SELECT 1 FROM "public"."zasp_schema_versions" later WHERE later."version">61)) THEN
        RAISE EXCEPTION USING ERRCODE='55000', MESSAGE='risk projection release unavailable';
    END IF;
    IF requested_operation NOT IN ('updateFinding','acceptFindingRisk') OR expected_version<1
       OR length(requested_idempotency_key) NOT BETWEEN 16 AND 128
       OR requested_finding_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_principal_id !~ '^pid_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
       OR requested_operation='updateFinding' AND (requested_status NOT IN ('open','under_review','resolved') OR requested_reason IS NOT NULL)
       OR requested_operation='acceptFindingRisk' AND (requested_status<>'accepted' OR length(requested_reason) NOT BETWEEN 1 AND 512) THEN
        RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='invalid risk mutation';
    END IF;
    IF NOT EXISTS (SELECT 1 FROM "public"."zasp_risk_findings" AS candidate WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "public"."zasp_risk_finding_visible"(candidate)) THEN
        RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='risk finding missing';
    END IF;
    requested_intent := jsonb_build_object('resource_id',requested_finding_id,'expected_version',expected_version,'body',CASE WHEN requested_operation='updateFinding' THEN jsonb_build_object('status',requested_status) ELSE jsonb_build_object('reason',requested_reason) END);
    PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key),0));
    digest_value := digest(convert_to(requested_intent::text,'UTF8'),'sha256');
    SELECT "request_digest","response" INTO prior_digest,prior_response FROM "public"."zasp_workflow_idempotency"
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id
       AND "principal_id"=requested_principal_id AND "operation"=requested_operation AND "idempotency_key"=requested_idempotency_key;
    IF FOUND THEN
        IF prior_digest<>digest_value THEN RAISE EXCEPTION USING ERRCODE='23505', MESSAGE='idempotency conflict'; END IF;
        PERFORM zasp_temporal77.require_risk_ready(); RETURN prior_response||jsonb_build_object('replayed',true);
    END IF;
    UPDATE "public"."zasp_risk_findings" AS candidate SET "status"=requested_status,"acceptance_reason"=CASE WHEN requested_operation='acceptFindingRisk' THEN requested_reason ELSE NULL END,"version"="version"+1,"updated_at"=transaction_timestamp()
     WHERE "organization_id"=requested_organization_id AND "workspace_id"=requested_workspace_id AND "environment_id"=requested_environment_id AND "id"=requested_finding_id AND "version"=expected_version AND "public"."zasp_risk_finding_visible"(candidate)
     RETURNING "version" INTO result_version;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001', MESSAGE='risk finding version conflict'; END IF;
    result_body := "public"."zasp_risk_finding_get"(requested_finding_id,requested_organization_id,requested_workspace_id,requested_environment_id);
    prior_response := jsonb_build_object('body',result_body,'version',result_version,'audit_id',requested_audit_id,'correlation_id',requested_correlation_id,'replayed',false);
    IF requested_receipt_id IS NOT NULL THEN prior_response:=prior_response||jsonb_build_object('receipt_id',requested_receipt_id); END IF;
    INSERT INTO "public"."zasp_workflow_audit" ("organization_id","workspace_id","environment_id","audit_id","correlation_id","principal_id","operation","resource_kind","resource_id","resource_version") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_audit_id,requested_correlation_id,requested_principal_id,requested_operation,'finding',requested_finding_id,result_version);
    INSERT INTO "public"."zasp_workflow_idempotency" ("organization_id","workspace_id","environment_id","principal_id","operation","idempotency_key","request_digest","response","receipt_semantics") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_operation,requested_idempotency_key,digest_value,prior_response-'replayed',CASE WHEN requested_receipt_id IS NULL THEN 'receiptless_incompatible' ELSE 'receipt_backed' END);
    IF requested_receipt_id IS NOT NULL THEN
        INSERT INTO "public"."zasp_workflow_receipts" ("organization_id","workspace_id","environment_id","principal_id","receipt_id","operation","idempotency_key","intent","result","resource_kind","resource_id","resource_version","audit_id","correlation_id") VALUES (requested_organization_id,requested_workspace_id,requested_environment_id,requested_principal_id,requested_receipt_id,requested_operation,requested_idempotency_key,requested_intent,result_body,'finding',requested_finding_id,result_version,requested_audit_id,requested_correlation_id);
    END IF;
    PERFORM zasp_temporal77.require_risk_ready(); RETURN prior_response;
END;
$function$

CREATE OR REPLACE FUNCTION zasp_temporal77.rules_valid(b jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE r jsonb;n jsonb;k text;
BEGIN
 IF jsonb_typeof(b) IS DISTINCT FROM 'object' THEN RETURN false;END IF;
 IF NOT b ? 'trigger_rules' THEN RETURN true;END IF;
 r:=b->'trigger_rules';
 IF jsonb_typeof(r) IS DISTINCT FROM 'object' OR octet_length(r::text)>2048 OR NOT zasp_temporal77.rule_integer(r->'version',1) THEN RETURN false;END IF;
 IF r->>'mode'='manual' THEN RETURN zasp_sa_multistep_prior.closed(r,ARRAY['version','mode']);END IF;
 k:=CASE b->>'trigger_kind' WHEN 'finding' THEN 'finding' WHEN 'attack_path' THEN 'attack_path' WHEN 'runtime_decision' THEN 'runtime' ELSE '' END;
 IF r->>'mode' IS DISTINCT FROM 'automatic' OR NOT zasp_sa_multistep_prior.closed(r,ARRAY['version','mode','cooldown_seconds',k]) OR NOT zasp_temporal77.rule_integer(r->'cooldown_seconds',86400) THEN RETURN false;END IF;
 n:=r->k;
 IF k='finding' THEN RETURN COALESCE(zasp_sa_multistep_prior.closed(n,ARRAY['family','minimum_severity']) AND zasp_temporal77.rule_text(n->'family') AND n->>'family'=b->>'trigger_source' AND n->>'minimum_severity' IN('low','medium','high','critical'),false);END IF;
 IF k='attack_path' THEN RETURN COALESCE(zasp_sa_multistep_prior.closed(n,ARRAY['state']) AND n->>'state' IN('potential','observed','verified') AND n->>'state'=b->>'trigger_source',false);END IF;
 IF k='runtime' THEN RETURN COALESCE(zasp_sa_multistep_prior.closed(n,ARRAY['decision','action','count','window_seconds']||CASE WHEN n ? 'risk' THEN ARRAY['risk'] ELSE ARRAY[]::text[] END) AND n->>'decision' IN('allow','monitor','block') AND zasp_temporal77.rule_text(n->'action') AND zasp_temporal77.rule_integer(n->'count',100) AND zasp_temporal77.rule_integer(n->'window_seconds',86400) AND (NOT n ? 'risk' OR n->>'risk' IN('low','medium','high','critical')),false);END IF;
 RETURN false;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.run_guard()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE d public.zasp_security_agent_definitions%ROWTYPE;BEGIN
 SELECT * INTO d FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.definition_id,NEW.definition_version);
 IF NOT d.body ? 'trigger_rules' THEN RETURN NEW;END IF;
 IF NOT zasp_temporal77.ready('3b6117ba1b9b0e9cc2871bc89bf0027b7ca3d400b1354f0550c068f2145de3fb','8cac13406a1886a98cd327065e5525be28997add7a9bd359d12e7b4ed219f5ef') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='automatic admission catalog unavailable';END IF;
 IF public.zasp_security_agent_principal_ready('zasp_security_agent_api') THEN RETURN NEW;END IF;
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT EXISTS(
  SELECT 1 FROM zasp_temporal77.occurrences a WHERE(a.organization_id,a.workspace_id,a.environment_id,a.definition_id,a.definition_version,a.run_id)=(NEW.organization_id,NEW.workspace_id,NEW.environment_id,NEW.definition_id,NEW.definition_version,NEW.run_id)
  AND a.disposition='admitted' AND a.definition_digest=digest(convert_to(d.body::text,'UTF8'),'sha256')
 ) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='configured automatic occurrence decision required';END IF;
 RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.runtime_page(o text, w text, e text, after_at timestamp with time zone, after_id text, floor_value timestamp with time zone, now_value timestamp with time zone, limit_value integer)
 RETURNS SETOF public.zasp_runtime_gateway_events
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE n integer:=0;BEGIN
 IF limit_value IS NULL OR limit_value NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime source page bound rejected';END IF;
 IF after_at IS NOT NULL THEN
  RETURN QUERY SELECT v.* FROM public.zasp_runtime_gateway_events v WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e)
   AND v.occurred_at=after_at AND v.event_id>after_id AND v.occurred_at BETWEEN floor_value AND now_value ORDER BY v.event_id LIMIT limit_value;
  GET DIAGNOSTICS n=ROW_COUNT;
 END IF;
 IF n<limit_value THEN
  RETURN QUERY SELECT v.* FROM public.zasp_runtime_gateway_events v WHERE(v.organization_id,v.workspace_id,v.environment_id)=(o,w,e)
   AND v.occurred_at<COALESCE(after_at,'infinity'::timestamptz) AND v.occurred_at BETWEEN floor_value AND now_value
   ORDER BY v.occurred_at DESC,v.event_id ASC LIMIT limit_value-n;
 END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.scan_sources(limit_value integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE cursor_value zasp_temporal77.source_scan%ROWTYPE;item record;table_value text;id_column text;version_column text;time_column text;
 scanned_value integer:=0;captured_value integer:=0;wrapped_value boolean:=false;now_value timestamptz:=clock_timestamp();
BEGIN
 PERFORM zasp_temporal77.require_executor();
 IF limit_value IS NULL OR limit_value NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic source scan bound rejected';END IF;
 SELECT * INTO STRICT cursor_value FROM zasp_temporal77.source_scan WHERE singleton FOR UPDATE;
 IF cursor_value.source_kind='runtime_decision' THEN
  IF NOT cursor_value.runtime_active THEN
   SELECT organization_id,workspace_id,environment_id INTO cursor_value.after_o,cursor_value.after_w,cursor_value.after_e
    FROM public.zasp_gateway_devices WHERE(organization_id,workspace_id,environment_id)>(cursor_value.after_o,cursor_value.after_w,cursor_value.after_e)
    ORDER BY organization_id,workspace_id,environment_id,id LIMIT 1;
   IF NOT FOUND THEN
    UPDATE zasp_temporal77.source_scan SET source_kind='finding',after_o='',after_w='',after_e='',after_id='',runtime_at=NULL,runtime_active=false WHERE singleton;
    RETURN jsonb_build_object('scanned',0,'captured',0,'wrapped',true);
   END IF;
   cursor_value.runtime_active:=true;cursor_value.runtime_at:=NULL;cursor_value.after_id:='';
  END IF;
  FOR item IN SELECT * FROM zasp_temporal77.runtime_page(cursor_value.after_o,cursor_value.after_w,cursor_value.after_e,cursor_value.runtime_at,cursor_value.after_id,now_value-interval '24 hours',now_value,limit_value) LOOP
   scanned_value:=scanned_value+1;
   IF zasp_temporal77.put_source(item.organization_id,item.workspace_id,item.environment_id,'runtime_decision',item.event_id,item.sequence,item.occurred_at) THEN captured_value:=captured_value+1;END IF;
   cursor_value.runtime_at:=item.occurred_at;cursor_value.after_id:=item.event_id;
  END LOOP;
  IF scanned_value<limit_value THEN cursor_value.runtime_active:=false;cursor_value.runtime_at:=NULL;cursor_value.after_id:='';END IF;
  UPDATE zasp_temporal77.source_scan SET after_o=cursor_value.after_o,after_w=cursor_value.after_w,after_e=cursor_value.after_e,after_id=cursor_value.after_id,runtime_at=cursor_value.runtime_at,runtime_active=cursor_value.runtime_active WHERE singleton;
  RETURN jsonb_build_object('scanned',scanned_value,'captured',captured_value,'wrapped',false);
 END IF;
 IF cursor_value.source_kind='finding' THEN table_value:='zasp_risk_findings';id_column:='id';version_column:='version';time_column:='updated_at';
 ELSE table_value:='zasp_risk_attack_paths';id_column:='id';version_column:='version';time_column:='updated_at';END IF;
 -- Fixed relation/column choices above, primary-key tuple seek, bounded rows.
 FOR item IN EXECUTE format('SELECT organization_id,workspace_id,environment_id,%I source_id,%I source_version,%I source_at FROM public.%I WHERE(organization_id,workspace_id,environment_id,%I)>($1,$2,$3,$4) ORDER BY organization_id,workspace_id,environment_id,%I LIMIT $5',id_column,version_column,time_column,table_value,id_column,id_column)
 USING cursor_value.after_o,cursor_value.after_w,cursor_value.after_e,cursor_value.after_id,limit_value LOOP
  scanned_value:=scanned_value+1;
  IF zasp_temporal77.put_source(item.organization_id,item.workspace_id,item.environment_id,cursor_value.source_kind,item.source_id,item.source_version,item.source_at) THEN captured_value:=captured_value+1;END IF;
  cursor_value.after_o:=item.organization_id;cursor_value.after_w:=item.workspace_id;cursor_value.after_e:=item.environment_id;cursor_value.after_id:=item.source_id;
 END LOOP;
 IF scanned_value<limit_value THEN
  cursor_value.source_kind:=CASE cursor_value.source_kind WHEN 'finding' THEN 'attack_path' ELSE 'runtime_decision' END;
  cursor_value.after_o:='';cursor_value.after_w:='';cursor_value.after_e:='';cursor_value.after_id:='';
 END IF;
 UPDATE zasp_temporal77.source_scan SET source_kind=cursor_value.source_kind,after_o=cursor_value.after_o,after_w=cursor_value.after_w,after_e=cursor_value.after_e,after_id=cursor_value.after_id WHERE singleton;
 RETURN jsonb_build_object('scanned',scanned_value,'captured',captured_value,'wrapped',wrapped_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.source_match(o text, w text, e text, event_value text, b jsonb, at_value timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE s zasp_temporal77.source_events%ROWTYPE;r jsonb;f public.zasp_risk_findings%ROWTYPE;p public.zasp_risk_attack_paths%ROWTYPE;
 evidence_value jsonb;anchor jsonb;pattern jsonb;digest_value bytea;trigger_value text;identity_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(event_value) AND at_value IS NOT NULL,false)
 OR NOT zasp_temporal77.rules_valid(b) OR b->'trigger_rules'->>'mode' IS DISTINCT FROM 'automatic' THEN RETURN NULL;END IF;
 SELECT * INTO s FROM zasp_temporal77.source_events WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,event_value);
 IF NOT FOUND OR s.source_kind IS DISTINCT FROM b->>'trigger_kind' THEN RETURN NULL;END IF;
 r:=b->'trigger_rules';trigger_value:=s.source_id;
 IF s.source_kind='finding' THEN
  SELECT * INTO f FROM public.zasp_risk_findings WHERE(organization_id,workspace_id,environment_id,id,version)=(o,w,e,s.source_id,s.source_version);
  IF NOT FOUND OR f.status<>'open' OR f.rule IS DISTINCT FROM r->'finding'->>'family'
   OR NOT public.zasp_risk_finding_visible(f)
   OR array_position(ARRAY['low','medium','high','critical'],f.severity)<array_position(ARRAY['low','medium','high','critical'],r->'finding'->>'minimum_severity') THEN RETURN NULL;END IF;
  identity_value:=jsonb_build_object('kind','finding','id',f.id,'version',f.version);
  evidence_value:=jsonb_build_object('kind','finding','source',to_jsonb(f),
   'evidence',(SELECT COALESCE(jsonb_agg(to_jsonb(child) ORDER BY position),'[]'::jsonb) FROM public.zasp_risk_finding_evidence child WHERE(organization_id,workspace_id,environment_id,finding_id)=(o,w,e,f.id)),
   'factors',(SELECT COALESCE(jsonb_agg(to_jsonb(child) ORDER BY position),'[]'::jsonb) FROM public.zasp_risk_finding_factors child WHERE(organization_id,workspace_id,environment_id,finding_id)=(o,w,e,f.id)));
  pattern:=jsonb_build_array('finding',f.id);
 ELSIF s.source_kind='attack_path' THEN
  SELECT * INTO p FROM public.zasp_risk_attack_paths WHERE(organization_id,workspace_id,environment_id,id,version)=(o,w,e,s.source_id,s.source_version);
  IF NOT FOUND OR p.state IS DISTINCT FROM r->'attack_path'->>'state' OR NOT public.zasp_risk_attack_path_valid(p) THEN RETURN NULL;END IF;
  identity_value:=jsonb_build_object('kind','attack_path','id',p.id,'version',p.version,'state',p.state);
  evidence_value:=jsonb_build_object('kind','attack_path','source',to_jsonb(p),
   'nodes',(SELECT COALESCE(jsonb_agg(to_jsonb(child) ORDER BY position),'[]'::jsonb) FROM public.zasp_risk_attack_path_nodes child WHERE(organization_id,workspace_id,environment_id,path_id)=(o,w,e,p.id)),
   'evidence',(SELECT COALESCE(jsonb_agg(to_jsonb(child) ORDER BY position),'[]'::jsonb) FROM public.zasp_risk_attack_path_evidence child WHERE(organization_id,workspace_id,environment_id,path_id)=(o,w,e,p.id)),
   'break_options',(SELECT COALESCE(jsonb_agg(to_jsonb(child) ORDER BY rank),'[]'::jsonb) FROM public.zasp_risk_break_options child WHERE(organization_id,workspace_id,environment_id,path_id)=(o,w,e,p.id)));
  pattern:=jsonb_build_array('attack_path',p.id);
 ELSE
  r:=r->'runtime';anchor:=zasp_temporal77.runtime_candidate(o,w,e,s.source_id,r,at_value);
  IF anchor IS NULL OR (anchor->>'sequence')::bigint<>s.source_version THEN RETURN NULL;END IF;
  SELECT jsonb_agg(candidate ORDER BY source_at,event_id) INTO evidence_value FROM(
   SELECT candidate,occurrence.source_at,occurrence.event_id FROM zasp_temporal77.source_events occurrence
   CROSS JOIN LATERAL(SELECT zasp_temporal77.runtime_candidate(o,w,e,occurrence.source_id,r,at_value) candidate) matched
   WHERE(occurrence.organization_id,occurrence.workspace_id,occurrence.environment_id,occurrence.source_kind)=(o,w,e,'runtime_decision')
   AND occurrence.source_at BETWEEN at_value-make_interval(secs=>(r->>'window_seconds')::integer) AND at_value
   AND candidate->'evaluation'->>'agent_id'=anchor->'evaluation'->>'agent_id'
   AND candidate->'evaluation'->>'session_id'=anchor->'evaluation'->>'session_id'
   ORDER BY occurrence.source_at,occurrence.event_id LIMIT (r->>'count')::integer
  ) matches;
  IF COALESCE(jsonb_array_length(evidence_value),0)<(r->>'count')::integer THEN RETURN NULL;END IF;
  pattern:=jsonb_build_array('runtime_decision',anchor->'evaluation'->>'agent_id',anchor->'evaluation'->>'session_id',r->>'action',r->>'decision');
  evidence_value:=jsonb_build_object('kind','runtime_decision','anchor',anchor,'events',evidence_value);
 END IF;
 digest_value:=digest(convert_to(evidence_value::text,'UTF8'),'sha256');
 RETURN jsonb_build_object('event_id',s.event_id,'kind',s.source_kind,'trigger_id',trigger_value,'version',s.source_version,'digest',encode(digest_value,'hex'),'cooldown_key',encode(digest(convert_to(pattern::text,'UTF8'),'sha256'),'hex'),'evidence',evidence_value)
  || CASE WHEN identity_value IS NOT NULL THEN jsonb_build_object('legacy_trigger_digest',encode(digest(convert_to(identity_value::text,'UTF8'),'sha256'),'hex')) ELSE '{}'::jsonb END;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.accept_control(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal78.run_owners%ROWTYPE;v zasp_temporal78.control_intents%ROWTYPE;t timestamptz;BEGIN
