AS $function$
DECLARE r text;env jsonb;BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal78.api_ready('29f2a16ea6d9021f159196106a9a57547cca797beaf87cc1fe15a937ae9b6021','11b999b767465c01389f4482f9196852905866873e585574888281220538d1d4') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='finding approval read unavailable';END IF;
