  prior_count:=0;
  IF session_count<limit_value THEN prior_count:=(zasp_temporal78.retained23(worker_value,limit_value-session_count)->>'created')::integer;END IF;
  RETURN jsonb_build_object('created',session_count+prior_count);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal78.retained33(worker_value text, limit_value integer)
