$function$

CREATE OR REPLACE FUNCTION zasp_temporal78.retained_body(worker_value text, limit_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;result_value jsonb;created_value integer:=0;run_value text;prior_count integer;admissions_value jsonb:='[]'::jsonb;admitted_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent principal unavailable';END IF;
 IF NOT COALESCE(length(worker_value) BETWEEN 1 AND 128 AND limit_value BETWEEN 1 AND 25,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test schedule rejected';END IF;
 IF NOT zasp_temporal70.guard01(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 FOR candidate IN
  SELECT d.organization_id o,d.workspace_id w,d.environment_id e,d.definition_id d,d.version v,d.body->>'trigger_kind' k,x.id t,x.version tv
  FROM public.zasp_security_agent_definitions d CROSS JOIN LATERAL (
   SELECT f.id,f.version FROM public.zasp_risk_findings f WHERE (f.organization_id,f.workspace_id,f.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='finding' AND f.status='open' AND f.rule=d.body->>'trigger_source'
   UNION ALL SELECT p.id,p.version FROM public.zasp_risk_attack_paths p WHERE (p.organization_id,p.workspace_id,p.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='attack_path' AND p.state=d.body->>'trigger_source' AND p.state IN('observed','verified') AND public.zasp_risk_attack_path_valid(p)
   UNION ALL SELECT ev.classification->>'session_id',ev.sequence FROM public.zasp_runtime_gateway_events ev
    JOIN public.zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(ev.organization_id,ev.workspace_id,ev.environment_id,ev.device_id,'active')
    JOIN public.zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(ev.organization_id,ev.workspace_id,ev.environment_id,ev.device_id,ev.credential_id)
    WHERE (ev.organization_id,ev.workspace_id,ev.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='runtime_decision' AND ev.decision='block' AND ev.classification->>'outcome'=d.body->>'trigger_source' AND ev.occurred_at>=clock_timestamp()-interval '5 minutes' AND ev.occurred_at<=clock_timestamp() AND public.zasp_valid_product_id(ev.classification->>'session_id')
    AND credential.revoked_at IS NULL AND credential.expires_at>clock_timestamp()
    AND credential.id=(SELECT c.id FROM public.zasp_gateway_credentials c WHERE (c.organization_id,c.workspace_id,c.environment_id,c.device_id)=(d.organization_id,d.workspace_id,d.environment_id,ev.device_id) AND c.revoked_at IS NULL AND c.expires_at>clock_timestamp() ORDER BY c.issued_at DESC,c.id DESC LIMIT 1)
    AND ev.event_id=(SELECT newest.event_id FROM public.zasp_runtime_gateway_events newest WHERE (newest.organization_id,newest.workspace_id,newest.environment_id,newest.classification->>'session_id',newest.decision,newest.classification->>'outcome')=(d.organization_id,d.workspace_id,d.environment_id,ev.classification->>'session_id','block',d.body->>'trigger_source') AND newest.occurred_at<=clock_timestamp() ORDER BY newest.occurred_at DESC,newest.sequence DESC,newest.event_id DESC LIMIT 1)
  ) x
  WHERE false AND d.deleted_at IS NULL AND d.activation IN('supervised','autonomous') AND d.body->'enabled'='true'::jsonb AND d.body ? 'existing_test'
   AND zasp_temporal70.body04(d.organization_id,d.workspace_id,d.environment_id,d.body,d.activation)
   AND zasp_temporal73.active_count(d.organization_id,d.workspace_id,d.environment_id,d.definition_id)<(d.body->>'concurrency_limit')::integer
   AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.trigger_id,tr.trigger_version)=(d.organization_id,d.workspace_id,d.environment_id,d.definition_id,x.id,x.version))
  -- Scan work is capped independently of successful admissions. A refused
  -- candidate must not consume the entire caller's successful-work allowance.
  ORDER BY d.organization_id,d.workspace_id,d.environment_id,d.definition_id,x.id,x.version DESC LIMIT least(100,limit_value*4)
 LOOP
  EXIT WHEN created_value>=limit_value;
  BEGIN
   -- Skip contended organizations before entering the blocking shared core.
   CONTINUE WHEN NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||candidate.o,0));
   run_value:=public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_run',concat_ws(chr(31),candidate.d,candidate.v,candidate.k,candidate.t,candidate.tv));
   result_value:=zasp_temporal73.admit(candidate.o,candidate.w,candidate.e,candidate.d,candidate.v,candidate.k,candidate.t,candidate.tv,run_value,worker_value,public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_audit',run_value),public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_correlation',run_value),true);
   IF (result_value->>'created')::boolean THEN
    created_value:=created_value+1;
    admissions_value:=admissions_value||jsonb_build_array(jsonb_build_object('o',candidate.o,'w',candidate.w,'e',candidate.e,'d',candidate.d,'v',candidate.v,'r',run_value));
   END IF;
  EXCEPTION WHEN SQLSTATE '40001' OR SQLSTATE '42501' OR SQLSTATE '55000' OR SQLSTATE '23505' THEN
   -- A stale candidate rolls back its whole subtransaction, including receipts.
   CONTINUE;
  END;
 END LOOP;
 IF created_value<limit_value THEN
  prior_count:=(zasp_temporal78.retained33(worker_value,limit_value-created_value)->>'created')::integer;
  IF prior_count IS NULL OR prior_count<0 OR prior_count>limit_value-created_value THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test scheduler bound violated';END IF;
  created_value:=created_value+prior_count;
 END IF;
 IF NOT zasp_temporal70.guard01(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 -- Later candidates and the delegated legacy scheduler can block after an
 -- earlier test admission. Revalidate every new test run at the commit edge.
 FOR admitted_value IN SELECT value FROM jsonb_array_elements(admissions_value) LOOP
  PERFORM zasp_temporal70.body15(admitted_value->>'o',admitted_value->>'w',admitted_value->>'e',admitted_value->>'d',(admitted_value->>'v')::bigint);
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr JOIN public.zasp_security_agent_definitions d ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id)=(tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id)
   WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.run_id)=(admitted_value->>'o',admitted_value->>'w',admitted_value->>'e',admitted_value->>'d',admitted_value->>'r')
    AND public.zasp_production_security_agent_existing_tests_trigger(tr.organization_id,tr.workspace_id,tr.environment_id,tr.trigger_kind,tr.trigger_id,d.body->>'trigger_source',tr.trigger_version)=jsonb_build_object('version',tr.trigger_version,'digest',encode(tr.trigger_digest,'hex'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test scheduled admission changed before commit';END IF;
 END LOOP;
 RETURN jsonb_build_object('created',created_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal78.retained_schedule(worker_value text, limit_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 PERFORM zasp_temporal70.require_worker();
 IF NOT zasp_temporal78.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='finding retained catalog unavailable';END IF;
 RETURN zasp_temporal78.retained_body(worker_value,limit_value,expected_checksum,expected_fingerprint);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.run_context(o text, w text, e text, r text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE envelope jsonb;item jsonb;step_value jsonb;arguments_value jsonb;x zasp_temporal78.run_owners%ROWTYPE;p public.zasp_security_agent_plans%ROWTYPE;j zasp_temporal78.planning_jobs%ROWTYPE;BEGIN
 IF NOT zasp_temporal78.api_ready('29f2a16ea6d9021f159196106a9a57547cca797beaf87cc1fe15a937ae9b6021','11b999b767465c01389f4482f9196852905866873e585574888281220538d1d4') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='finding public read unavailable';END IF;
 SELECT value INTO envelope FROM zasp_temporal66.run_context(o,w,e,r,(SELECT checksum FROM zasp_temporal66.registration),(SELECT fingerprint FROM zasp_temporal66.registration)) rows(value);
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO x FROM zasp_temporal78.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF envelope->'detail'->'run'->>'id' IS DISTINCT FROM r OR envelope->'action_details'->>'run_id' IS DISTINCT FROM r THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding public identity changed';END IF;
 IF envelope->'detail'->'plan'='null'::jsonb THEN RETURN envelope;END IF;
 SELECT * INTO p FROM public.zasp_security_agent_plans WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO j FROM zasp_temporal78.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 item:=p.plan->'steps'->0;step_value:=envelope->'action_details'->'steps'->0;
 IF p.run_id IS NULL OR j.run_id IS NULL OR j.state<>'admitted' OR p.plan_hash IS DISTINCT FROM digest(convert_to(p.plan::text,'UTF8'),'sha256')
  OR 'sha256:'||encode(p.plan_hash,'hex') IS DISTINCT FROM envelope->'action_details'->>'plan_hash' OR jsonb_array_length(p.plan->'steps')<>1 OR jsonb_array_length(envelope->'action_details'->'steps')<>1
  OR item IS DISTINCT FROM zasp_temporal78.plan_item(x,j.result_value->'candidate',item->>'authorization') OR NOT zasp_temporal78.candidate_valid(j.result_value->'candidate',j.context_value)
  OR (step_value->>'step_id',step_value->>'action') IS DISTINCT FROM(x.step_id,x.action_key) OR step_value->'index' IS DISTINCT FROM '0'::jsonb
  OR step_value->'arguments' IS DISTINCT FROM jsonb_build_object('target_id',item->'target_id','expected_version',item->'expected_version','target_status',item->'target_status')
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding public plan proof changed';END IF;
 IF (step_value->'effect'<>'null'::jsonb) IS DISTINCT FROM EXISTS(SELECT 1 FROM zasp_temporal78.response_metadata WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding public effect proof changed';END IF;
 IF step_value->'effect'<>'null'::jsonb THEN PERFORM zasp_temporal78.effect_evidence(o,w,e,r);END IF;
 arguments_value:=step_value->'arguments'||jsonb_build_object('assignee_id',item->'assignee_id','response_status',item->'response_status','note',item->'note');
 RETURN zasp_temporal78.project_approvals(o,w,e,jsonb_set(envelope,'{action_details,steps,0,arguments}',arguments_value));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.source_match(o text, w text, e text, event_value text, b jsonb, at_value timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
 SET "TimeZone" TO 'UTC'
AS $function$
DECLARE s zasp_temporal77.source_events%ROWTYPE;f public.zasp_risk_findings%ROWTYPE;evidence_value jsonb;identity_value jsonb;BEGIN
 IF b?'trigger_rules' OR NOT zasp_temporal78.capable(b) THEN RETURN zasp_temporal77.source_match(o,w,e,event_value,b,at_value);END IF;
 SELECT * INTO s FROM zasp_temporal77.source_events WHERE(organization_id,workspace_id,environment_id,event_id,source_kind)=(o,w,e,event_value,'finding');
 IF NOT FOUND OR at_value IS NULL OR NOT COALESCE(b->'environment_ids'?e,false) THEN RETURN NULL;END IF;
 SELECT * INTO f FROM public.zasp_risk_findings WHERE(organization_id,workspace_id,environment_id,id,version)=(o,w,e,s.source_id,s.source_version);
 IF NOT FOUND OR f.status<>'open' OR COALESCE(f.rule,f.source) IS DISTINCT FROM b->>'trigger_source' OR NOT public.zasp_risk_finding_visible(f) THEN RETURN NULL;END IF;
 identity_value:=jsonb_build_object('kind','finding','id',f.id,'version',f.version);
 evidence_value:=jsonb_build_object('kind','finding','source',to_jsonb(f),
  'evidence',(SELECT COALESCE(jsonb_agg(to_jsonb(child) ORDER BY position),'[]'::jsonb) FROM public.zasp_risk_finding_evidence child WHERE(organization_id,workspace_id,environment_id,finding_id)=(o,w,e,f.id)),
  'factors',(SELECT COALESCE(jsonb_agg(to_jsonb(child) ORDER BY position),'[]'::jsonb) FROM public.zasp_risk_finding_factors child WHERE(organization_id,workspace_id,environment_id,finding_id)=(o,w,e,f.id)));
 RETURN jsonb_build_object('event_id',s.event_id,'kind','finding','trigger_id',f.id,'version',f.version,
  'digest',encode(digest(convert_to(evidence_value::text,'UTF8'),'sha256'),'hex'),'evidence',evidence_value,
  'cooldown_key',encode(digest(convert_to(jsonb_build_array('finding',f.id)::text,'UTF8'),'sha256'),'hex'),
  'legacy_trigger_digest',encode(digest(convert_to(identity_value::text,'UTF8'),'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.start_identity(q jsonb)
 RETURNS zasp_temporal78.run_owners
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal78.run_owners%ROWTYPE;k text;
BEGIN
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest']) OR octet_length(q::text)>4096 OR q->>'input_digest'!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test start rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test start scope rejected';END IF;END LOOP;
 SELECT * INTO x FROM zasp_temporal78.run_owners WHERE (organization_id,workspace_id,environment_id,run_id,input_digest)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'input_digest') AND to_jsonb(definition_version)=q->'definition_version';
 IF x.run_id IS NULL OR x.workflow_id IS DISTINCT FROM 'security-agent-finding/v1/'||x.organization_id||'/'||x.workspace_id||'/'||x.environment_id||'/'||x.run_id
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts t WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.definition_id,t.trigger_id,t.trigger_version,t.trigger_digest)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.definition_id,x.trigger_id,x.trigger_version,decode(x.input_digest,'hex')))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test durable start changed';END IF;
 RETURN x;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.stop_evidence(o text, w text, e text, r text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal78.run_owners%ROWTYPE;t zasp_temporal78.stops%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;j zasp_temporal78.planning_jobs%ROWTYPE;a public.zasp_security_agent_audit%ROWTYPE;
BEGIN
 SELECT * INTO x FROM zasp_temporal78.run_owners WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO t FROM zasp_temporal78.stops WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO j FROM zasp_temporal78.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE(organization_id,workspace_id,environment_id,audit_id)=(o,w,e,t.audit_id);
 IF t.run_id IS NULL OR x.run_id IS NULL OR rr.completed_at IS NULL OR rr.lease_owner IS NOT NULL OR rr.lease_token IS NOT NULL OR rr.lease_expires_at IS NOT NULL
  OR t.audit_id IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_finding_stop',r)
  OR t.proof IS DISTINCT FROM jsonb_build_object('kind',t.proof->>'kind','run_state',rr.state,'run_reason',rr.last_error_code,'definition_version',x.definition_version,'input_digest',x.input_digest,'plan_hash',encode(rr.plan_hash,'hex'))
  OR (a.run_id,a.event_kind,a.correlation_id,a.body,a.event_digest) IS DISTINCT FROM(r,'temporal_finding_stopped',t.audit_id,jsonb_build_object('reason',t.reason,'proof',t.proof),digest(convert_to(jsonb_build_object('reason',t.reason,'proof',t.proof)::text,'UTF8'),'sha256'))
  OR EXISTS(SELECT 1 FROM zasp_temporal78.response_metadata WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding stop proof changed';END IF;
 IF t.proof->>'kind'='planning' THEN
  IF NOT zasp_temporal78.planning_terminal_valid(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding stopped planner changed';END IF;
 ELSIF t.proof->>'kind'='queued' THEN
  IF rr.state<>'cancelled' OR j.run_id IS NOT NULL OR rr.plan_hash IS NOT NULL OR EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) OR EXISTS(SELECT 1 FROM public.zasp_security_agent_run_budgets WHERE(organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding queued stop changed';END IF;
 ELSIF t.proof->>'kind'='admitted' THEN
  IF rr.state<>'cancelled' OR j.state IS DISTINCT FROM 'admitted'
   OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE(organization_id,workspace_id,environment_id,run_id,plan_hash)=(o,w,e,r,rr.plan_hash) AND plan_hash=digest(convert_to(plan::text,'UTF8'),'sha256'))
   OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE(organization_id,workspace_id,environment_id,run_id,step_id,state)=(o,w,e,r,x.step_id,'cancelled'))
  THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding admitted stop changed';END IF;
 ELSE RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding stop kind changed';END IF;
 RETURN jsonb_build_object('kind','stopped','reason',t.reason,'proof',t.proof,'audit_id',t.audit_id);
END $function$

