  context_envelope:=zasp_security_agent_planner_context_v33(organization_value,workspace_value,environment_value,run_value,worker_value,lease_token_value);IF context_envelope ? 'budget_stop' THEN result_value:=zasp_security_agent_budget_stop_result(organization_value,workspace_value,environment_value,run_value,'prepare');ELSE context_value:=context_envelope->'context';expected_input:=decode(substring(context_envelope->>'input_digest' FROM 8),'hex');
