  VALUES(organization_value,workspace_value,environment_value,actor_value,'decideSecurityAgentApproval',idempotency_value,approval_value,expected_version,intent_value,intent_digest_value,response_value,audit_value,correlation_value,receipt_value);
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_execute_run(organization_value text, workspace_value text, environment_value text, run_value text, worker_value text, lease_token_value text, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
