  RETURN to_regnamespace('zasp_ordered_public62') IS NULL AND public.zasp_discovery_schedule_replay_readiness('37956023196757f30a7ecb415e9d7d7e6f76cfa32a3ffa2d45445c172f6313ab','1ed52fb5f9a83384e1d3fecbc3bc116d3981a36479e9b3b1f6ec04b5cd4f3b36');
