  IF path_created<limit_value THEN prior_result:=zasp_security_agent_schedule_triggers_v24(worker_value,limit_value-path_created);prior_created:=(prior_result->>'created')::integer;END IF;
  RETURN jsonb_build_object('created',path_created+prior_created);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal74.admit(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';r text:=q->>'run_id';
 j zasp_temporal74.planning_jobs%ROWTYPE;x zasp_temporal74.run_owners%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;
 cv jsonb;binding jsonb;item jsonb;plan_value jsonb;plan_digest bytea;expiry timestamptz;authorization_value text;state_value text;approval_value text;audit_value text;result_value jsonb;requester text;
BEGIN
 SELECT * INTO STRICT j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO STRICT x FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO STRICT b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 cv:=zasp_temporal74.context(o,w,e,r);
 IF j.state='admitted' THEN
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id,plan_hash)=(o,w,e,r,rr.plan_hash) AND plan_hash=digest(convert_to(plan::text,'UTF8'),'sha256')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test plan replay proof changed';END IF;
  RETURN j.receipt;
 END IF;
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_executor') OR j.state<>'artifacts' OR rr.state<>'planning' OR rr.version<>j.run_version OR j.context_value IS DISTINCT FROM cv OR j.result_value IS DISTINCT FROM zasp_temporal74.planning_result(j.raw_result,j.lookup_request->>'model',cv)
  OR q->'candidate' IS DISTINCT FROM j.result_value->'candidate' OR j.result_value->'candidate'='null'::jsonb OR j.result_value->'usage'='null'::jsonb OR j.input_version IS NULL OR j.output_version IS NULL OR b.stop_reason IS NOT NULL OR b.deadline_at<=clock_timestamp()
  OR NOT EXISTS(SELECT 1 FROM zasp_temporal74.provider_reservations p WHERE (p.organization_id,p.workspace_id,p.environment_id,p.run_id,p.attempt,p.reservation_id,p.input_digest,p.output_digest,p.total_tokens,p.cost_nano_credits)=(o,w,e,r,1,j.reservation_id,decode(substr(j.input_digest,8),'hex'),decode(substr(j.provider_digest,8),'hex'),(j.result_value->'usage'->>'total_tokens')::bigint,(j.result_value->'usage'->>'cost_nano_credits')::bigint) AND p.settled_at IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test admission proof unavailable';END IF;
 binding:=zasp_temporal71.body21(o,w,e,rr.definition_id,rr.definition_version);
 authorization_value:=CASE cv->'definition'->>'autonomy' WHEN 'autonomous' THEN 'autonomous' ELSE 'approval_required' END;
 state_value:=CASE authorization_value WHEN 'autonomous' THEN 'queued' ELSE 'waiting_approval' END;
 expiry:=least(b.deadline_at,clock_timestamp()+interval '15 minutes');
 approval_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_approval',r||chr(31)||x.step_id);
 item:=jsonb_build_object('index',0,'step_id',x.step_id,'action',x.action_key,'target_id',binding->>'definition_id','test_definition_version',binding->'definition_version','test_target_id',binding->>'target_id','test_target_kind',binding->>'target_kind','authorization',authorization_value);
 plan_value:=jsonb_build_object('definition_id',rr.definition_id,'definition_version',rr.definition_version,'catalog_version','security-agent-actions-v1','evidence_ids',jsonb_build_array(rr.trigger_id),'steps',jsonb_build_array(item),'verification',jsonb_build_object('kind','test_run'),'expires_at',to_char(expiry AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 plan_digest:=digest(convert_to(plan_value::text,'UTF8'),'sha256');
 INSERT INTO public.zasp_security_agent_plans(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_digest,catalog_version,plan,plan_hash,expires_at) VALUES(o,w,e,r,rr.definition_id,rr.definition_version,decode(x.input_digest,'hex'),'security-agent-actions-v1',plan_value,plan_digest,expiry);
 INSERT INTO public.zasp_security_agent_steps(organization_id,workspace_id,environment_id,run_id,step_id,step_index,action_key,input_digest,authorization_result,state) VALUES(o,w,e,r,x.step_id,0,x.action_key,digest(convert_to(item::text,'UTF8'),'sha256'),authorization_value,CASE authorization_value WHEN 'autonomous' THEN 'authorized' ELSE 'waiting_approval' END);
 IF authorization_value='approval_required' THEN
  requester:=rr.requested_by;
  IF x.source_kind='automatic73' THEN requester:=zasp_temporal74.authorize(o,w,e,x.definition_id,x.definition_version)->>'principal_id';END IF;
  INSERT INTO public.zasp_security_agent_approvals(organization_id,workspace_id,environment_id,approval_id,run_id,step_id,plan_hash,state,requester_id,expires_at) VALUES(o,w,e,approval_value,r,x.step_id,plan_digest,'pending',requester,expiry);
 END IF;
 UPDATE public.zasp_security_agent_runs SET state=state_value,version=version+1,plan_hash=plan_digest,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 result_value:=jsonb_build_object('contract_version',74,'outcome','admitted','organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'version',rr.version+1,'plan_hash','sha256:'||encode(plan_digest,'hex'),'step_id',x.step_id,'state',state_value,'approval_id',CASE authorization_value WHEN 'approval_required' THEN approval_value ELSE NULL END,'provider_reservation_id',j.reservation_id);
 audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_plan_admission',r);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,approval_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,audit_value,r,x.step_id,CASE authorization_value WHEN 'approval_required' THEN approval_value ELSE NULL END,rr.requested_by,CASE authorization_value WHEN 'autonomous' THEN 'run_authorized' ELSE 'approval_requested' END,digest(convert_to(result_value::text,'UTF8'),'sha256'),result_value);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.configuration_core(mutation_value text, definition_value text, organization_value text, workspace_value text, environment_value text, principal_value text, operation_value text, idempotency_value text, expected_version_value bigint, intent_value jsonb, body_value jsonb, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response_value jsonb;synchronized zasp_security_agent_definitions%ROWTYPE;
BEGIN
  IF NOT zasp_security_agent_principal_ready('zasp_security_agent_api') OR mutation_value NOT IN('create','update','delete') OR operation_value<>(CASE mutation_value WHEN 'create' THEN 'createSecurityAgent' WHEN 'update' THEN 'updateSecurityAgent' ELSE 'deleteSecurityAgent' END)
     OR mutation_value<>'delete' AND (jsonb_typeof(body_value)<>'object' OR body_value->>'enabled'<>'false') OR mutation_value='delete' AND body_value<>'{}'::jsonb THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent definition mutation rejected';
  END IF;
  LOCK TABLE zasp_workflow_idempotency IN ROW EXCLUSIVE MODE;

  PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value),0));
  IF mutation_value IN('update','delete') AND NOT EXISTS(
    SELECT 1 FROM zasp_workflow_idempotency WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=
    (organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value)) THEN
    -- Workflow updates invoke the definition mirror trigger in this same order.
    PERFORM 1 FROM zasp_workflow_records WHERE (organization_id,workspace_id,environment_id,kind,id)=
      (organization_value,workspace_value,environment_value,'security_agent',definition_value) AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='security agent definition missing';END IF;
    PERFORM 1 FROM zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=
      (organization_value,workspace_value,environment_value,definition_value,expected_version_value) AND deleted_at IS NULL FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='security agent definition version conflict';END IF;
    SELECT version INTO STRICT expected_version_value FROM zasp_workflow_records WHERE (organization_id,workspace_id,environment_id,kind,id)=
      (organization_value,workspace_value,environment_value,'security_agent',definition_value);
  END IF;
  response_value:=zasp_workflow_mutate_v3(mutation_value,'security_agent',definition_value,organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value,expected_version_value,intent_value,body_value,audit_value,correlation_value);
  IF COALESCE((response_value->>'replayed')::boolean,false) THEN RETURN response_value;END IF;
  SELECT * INTO STRICT synchronized FROM zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(organization_value,workspace_value,environment_value,definition_value);

  UPDATE zasp_workflow_audit SET resource_version=synchronized.version WHERE
    (organization_id,workspace_id,environment_id,audit_id,principal_id,operation,resource_kind,resource_id)=
    (organization_value,workspace_value,environment_value,audit_value,principal_value,operation_value,'security_agent',definition_value);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent definition audit missing';END IF;

  IF mutation_value<>'delete' AND (synchronized.body ? 'existing_test'
    OR synchronized.body->'allowed_actions' ?| ARRAY['run_test','rerun_test','start_attack_lab']) THEN
    -- Resolve the exact persisted version under current scoped authority. Any
    -- refusal rolls back the workflow, mirror, history and audit together.
    PERFORM zasp_temporal71.body21(
      organization_value,workspace_value,environment_value,definition_value,synchronized.version);
  END IF;
  -- The inherited mirror trigger creates this version inside this transaction.
  -- Bind its provenance before returning or committing, never on a replay and
  -- never by rewriting an earlier version or trusting a caller-set session GUC.
  IF NOT COALESCE(zasp_valid_product_id(principal_value),false) THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='security agent definition actor rejected';
  END IF;
  UPDATE zasp_security_agent_definition_versions SET actor_id=principal_value
  WHERE (organization_id,workspace_id,environment_id,definition_id,version)=
    (organization_value,workspace_value,environment_value,definition_value,synchronized.version)
    AND actor_id=session_user AND definition=synchronized.body
    AND definition_digest=digest(convert_to(synchronized.body::text,'UTF8'),'sha256');
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent definition provenance missing';END IF;
  response_value:=response_value||jsonb_build_object('body',synchronized.body,'version',synchronized.version);
  IF receipt_value<>'' THEN
    INSERT INTO zasp_workflow_receipts(organization_id,workspace_id,environment_id,principal_id,receipt_id,operation,idempotency_key,intent,result,resource_kind,resource_id,resource_version,audit_id,correlation_id)
    VALUES(organization_value,workspace_value,environment_value,principal_value,receipt_value,operation_value,idempotency_value,intent_value,synchronized.body,'security_agent',definition_value,synchronized.version,audit_value,correlation_value);
    response_value:=response_value||jsonb_build_object('receipt_id',receipt_value);
  ELSE
    UPDATE zasp_workflow_idempotency SET receipt_semantics='receiptless_incompatible' WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value);
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent receipt provenance missing';END IF;
  END IF;
  UPDATE zasp_workflow_idempotency SET response=response_value-'replayed',receipt_semantics=CASE WHEN receipt_value='' THEN 'receiptless_incompatible' ELSE 'receipt_backed' END WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value);
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='security agent replay authority missing';END IF;
  RETURN response_value;
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal74.configuration_replay(o text, w text, e text, a text, operation_value text, k text, intent_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE current_body jsonb;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.api_ready('6ecde7cb0053af3378f47aef84ecbe99ca31d9cdced9fbe6d0dc64ee7e01b39e','0be1a2bfe93c30928eb03eae744993df6ec6c4db692b909aed9b7c486de6aca5') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test configuration unavailable';END IF;
 SELECT body INTO current_body FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,intent_value->>'resource_id');
 IF NOT COALESCE(current_body->'allowed_actions' IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb) OR current_body IS NULL AND intent_value->'body'->'allowed_actions' IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb),false) THEN RETURN NULL;END IF;
 PERFORM zasp_temporal74.manager(o,w,e,a);
 RETURN zasp_temporal74.configuration_replay_core(o,w,e,a,operation_value,k,intent_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.configuration_write(mutation_value text, d text, o text, w text, e text, a text, operation_value text, k text, v bigint, intent_value jsonb, body_value jsonb, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE current_row public.zasp_security_agent_definitions%ROWTYPE;result_value jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='test configuration requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.api_ready('6ecde7cb0053af3378f47aef84ecbe99ca31d9cdced9fbe6d0dc64ee7e01b39e','0be1a2bfe93c30928eb03eae744993df6ec6c4db692b909aed9b7c486de6aca5') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test configuration unavailable';END IF;
 SELECT * INTO current_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d);
 IF NOT COALESCE(current_row.body->'allowed_actions' IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb) OR current_row.definition_id IS NULL AND body_value->'allowed_actions' IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb),false) THEN RETURN NULL;END IF;
 PERFORM zasp_temporal74.manager(o,w,e,a);
 -- Keep the installed workflow-mirror-before-definition lock order.
 PERFORM 1 FROM public.zasp_workflow_records WHERE (organization_id,workspace_id,environment_id,kind,id)=(o,w,e,'security_agent',d) FOR UPDATE;
 SELECT * INTO current_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d) FOR UPDATE;
 result_value:=zasp_temporal74.configuration_core(mutation_value,d,o,w,e,a,operation_value,k,v,intent_value,body_value,audit_value,correlation_value,receipt_value);
 IF NOT COALESCE((result_value->>'replayed')::boolean,false) AND current_row.definition_id IS NOT NULL THEN
  INSERT INTO zasp_temporal74.grant_revocations(organization_id,workspace_id,environment_id,definition_id,definition_version,actor_id,audit_id)
   SELECT o,w,e,d,g.definition_version,a,audit_value FROM zasp_temporal74.service_grants g WHERE (g.organization_id,g.workspace_id,g.environment_id,g.definition_id,g.definition_version)=(o,w,e,d,current_row.version) ON CONFLICT DO NOTHING;
 END IF;
 PERFORM zasp_temporal74.manager(o,w,e,a);
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.definition(o text, w text, e text, d text, a text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE row_value public.zasp_security_agent_definitions%ROWTYPE;m public.zasp_identity_memberships%ROWTYPE;s public.zasp_authorized_scopes%ROWTYPE;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.api_ready('6ecde7cb0053af3378f47aef84ecbe99ca31d9cdced9fbe6d0dc64ee7e01b39e','0be1a2bfe93c30928eb03eae744993df6ec6c4db692b909aed9b7c486de6aca5') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test definition read unavailable';END IF;
 SELECT * INTO row_value FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR row_value.body->'allowed_actions' NOT IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb) THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.zasp_identity_memberships WHERE (organization_id,principal_id)=(o,a) FOR SHARE;
 s:=zasp_sa_multistep_prior.lock_scope(o,w,e,a);
 IF m.active IS DISTINCT FROM true OR s.principal_id IS NULL OR NOT COALESCE(s.permissions?'view' AND public.zasp_effective_scope_permissions(s.permissions,m.role)?'view',false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test definition read denied';END IF;
 RETURN jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'definition_id',d,'activation',row_value.activation,'version',row_value.version,'definition_version',row_value.definition_version,'body',row_value.body,'updated_at',to_char(row_value.updated_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.late_usage_valid(o text, w text, e text, r text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE l zasp_temporal74.planning_late_usage%ROWTYPE;j zasp_temporal74.planning_jobs%ROWTYPE;p zasp_temporal74.provider_reservations%ROWTYPE;
 a public.zasp_security_agent_audit%ROWTYPE;later public.zasp_security_agent_audit%ROWTYPE;association jsonb;cv jsonb;original jsonb;raw text;
BEGIN
 SELECT * INTO l FROM zasp_temporal74.planning_late_usage WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO p FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_terminal');
 SELECT * INTO later FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_late_usage');
 raw:=l.body->>'raw';association:=l.body->'association';original:=a.body->'reservation';
 IF l.run_id IS NULL OR raw IS NULL OR octet_length(raw) NOT BETWEEN 1 AND 65536 OR NOT zasp_sa_multistep_prior.closed(l.body,ARRAY['raw','association','terminal_digest','reservation','usage'])
  OR NOT zasp_sa_multistep_prior.closed(association,ARRAY['request_digest','credential_digest','reservation_id','response_id','response_digest']) THEN RETURN false;END IF;
 cv:=zasp_temporal74.planning_result(raw,j.lookup_request->>'model',j.context_value);
 RETURN COALESCE(j.state='needs_human' AND a.body->'job'=to_jsonb(j) AND a.event_digest=digest(convert_to(a.body::text,'UTF8'),'sha256')
  AND l.body_digest=digest(convert_to(l.body::text,'UTF8'),'sha256') AND l.body->>'terminal_digest'=encode(a.event_digest,'hex')
  AND later.audit_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_planning_late_usage',r) AND later.correlation_id=later.audit_id AND later.body=l.body AND later.event_digest=l.body_digest
  AND association->>'request_digest'=j.request_digest AND j.request_digest='sha256:'||encode(digest(convert_to(j.request_body,'UTF8'),'sha256'),'hex')
  AND association->>'credential_digest'=j.lookup_request->>'credential_digest' AND association->>'credential_digest'=l.credential_digest
  AND association->>'reservation_id'=j.reservation_id AND p.reservation_id=j.reservation_id
  AND association->>'response_id'=l.response_id AND (raw::jsonb)->>'id'=l.response_id
  AND association->>'response_digest'='sha256:'||encode(digest(convert_to(raw,'UTF8'),'sha256'),'hex')
  AND original->'settled_at'='null'::jsonb AND original->'total_tokens'='null'::jsonb AND original->'cost_nano_credits'='null'::jsonb
  AND to_jsonb(p)-ARRAY['settled_at','output_digest','prompt_tokens','completion_tokens','total_tokens','cost_nano_credits']=original-ARRAY['settled_at','output_digest','prompt_tokens','completion_tokens','total_tokens','cost_nano_credits']
  AND l.body->'reservation'=to_jsonb(p) AND cv->'usage'<>'null'::jsonb AND l.body->'usage'=cv->'usage' AND p.settled_at IS NOT NULL AND p.released_at IS NULL
  AND (p.prompt_tokens,p.completion_tokens,p.total_tokens,p.cost_nano_credits)=((cv->'usage'->>'prompt_tokens')::bigint,(cv->'usage'->>'completion_tokens')::bigint,(cv->'usage'->>'total_tokens')::bigint,(cv->'usage'->>'cost_nano_credits')::bigint)
  AND p.output_digest=digest(convert_to(raw,'UTF8'),'sha256')
  AND (j.raw_result IS NULL OR (j.raw_result::jsonb)-'usage'=(raw::jsonb)-'usage' AND j.result_value->'usage'='null'::jsonb),false);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.load_plan(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;k text;rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;job zasp_temporal74.planning_jobs%ROWTYPE;tr public.zasp_security_agent_trigger_receipts%ROWTYPE;cv jsonb;now_value timestamptz;BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor authority unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','operation']) OR q->>'operation'<>'load'
  OR q->>'definition_version'!~'^([1-9][0-9]{0,5}|1000000)$' OR jsonb_typeof(q->'definition_version')<>'number' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor plan request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k)<>'string' OR NOT public.zasp_valid_product_id(q->>k) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor scope rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR rr.definition_version<>(q->>'definition_version')::bigint OR NOT zasp_temporal74.is_owned(o,w,e,r)
  OR rr.lease_token IS NOT NULL OR rr.lease_owner IS NOT NULL OR rr.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor run unavailable';END IF;
 SELECT * INTO job FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN
  IF rr.state<>'queued' OR rr.attempt<>0 OR rr.version<>1 OR rr.available_at>clock_timestamp() OR rr.plan_hash IS NOT NULL OR b.run_id IS NOT NULL
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor run not fresh';END IF;
  SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(o,w,e,r,rr.definition_id,rr.trigger_id) FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,trigger_version,input_digest)=(o,w,e,r,rr.definition_id,rr.definition_version,tr.trigger_id,tr.trigger_version,encode(tr.trigger_digest,'hex'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor trigger identity rejected';END IF;
  UPDATE public.zasp_security_agent_runs SET state='planning',attempt=1,version=2 WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO rr;
  cv:=zasp_temporal74.context(o,w,e,r);
  IF octet_length(cv::text)>65536 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor input too large';END IF;
  IF zasp_temporal68.active_count(o,'planning',NULL)>(cv->'definition'->>'concurrency_limit')::integer THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor concurrency exceeded';END IF;
  now_value:=clock_timestamp();
  INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
  INSERT INTO public.zasp_security_agent_run_budgets(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,started_at,deadline_at,max_steps,max_tokens,max_cost_nano_credits,concurrency_limit)
   VALUES(o,w,e,r,rr.definition_id,rr.definition_version,now_value,now_value+make_interval(secs=>(cv->'definition'->>'max_duration_seconds')::integer),1,(cv->'definition'->>'ai_token_budget')::bigint,(cv->'definition'->>'max_ai_cost_nano_credits')::bigint,(cv->'definition'->>'concurrency_limit')::integer) RETURNING * INTO b;
  INSERT INTO zasp_temporal74.planning_jobs VALUES(o,w,e,r,rr.definition_version,rr.version,'loaded',b.started_at,b.deadline_at,cv,cv::text,'sha256:'||encode(digest(convert_to(cv::text,'UTF8'),'sha256'),'hex'),public.zasp_discovery_canonical_id(o,w,e,'security_agent_planning_input',r),public.zasp_discovery_canonical_id(o,w,e,'security_agent_planning_output',r),public.zasp_discovery_canonical_id(o,w,e,'security_agent_planning_reservation',r)) RETURNING * INTO job;
 END IF;
 IF rr.state<>'planning' OR rr.version<>job.run_version OR b.stop_reason IS NOT NULL OR b.deadline_at<=clock_timestamp()
  OR zasp_temporal74.context(o,w,e,r) IS DISTINCT FROM job.context_value OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor planning authority changed';END IF;
 RETURN to_jsonb(job);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.manager(o text, w text, e text, a text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE m public.zasp_identity_memberships%ROWTYPE;s public.zasp_authorized_scopes%ROWTYPE;
BEGIN
 SELECT * INTO m FROM public.zasp_identity_memberships WHERE (organization_id,principal_id)=(o,a) FOR SHARE;
 s:=zasp_sa_multistep_prior.lock_scope(o,w,e,a);
 IF m.active IS DISTINCT FROM true OR s.principal_id IS NULL OR NOT COALESCE(s.permissions?&ARRAY['view','manage_workflows'] AND public.zasp_effective_scope_permissions(s.permissions,m.role)?&ARRAY['view','manage_workflows'],false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test configuration permission rejected';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.plan(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;op text;payload jsonb;job zasp_temporal74.planning_jobs%ROWTYPE;
 rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;reservation zasp_temporal74.provider_reservations%ROWTYPE;
 selection jsonb;body_value text;bound_value jsonb;cv jsonb;reason text;receipt_value jsonb;send_value boolean:=false;
BEGIN
 IF q->>'operation'='reconcile' THEN RETURN zasp_temporal74.recover_plan(q);END IF;
 IF q->>'operation'='late_usage' THEN RETURN zasp_temporal74.record_late_usage(q);END IF;
 IF q->>'operation'='load' THEN RETURN zasp_temporal74.load_plan(q);END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor planning requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor planning unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','operation','payload']) OR octet_length(q::text)>524288
  OR q->>'operation' NOT IN('prepare','start','result','settle','artifacts','admit') OR jsonb_typeof(q->'payload')<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor planning request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';op:=q->>'operation';payload:=q->'payload';
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO job FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR NOT zasp_temporal74.is_owned(o,w,e,r) OR q->'definition_version' IS DISTINCT FROM to_jsonb(job.definition_version)
  OR rr.lease_owner IS NOT NULL OR rr.lease_token IS NOT NULL OR rr.lease_expires_at IS NOT NULL
  OR NOT(rr.state='planning' AND rr.version=job.run_version OR op='admit' AND job.state='admitted' AND rr.state IN('queued','waiting_approval') AND rr.version=job.run_version+1)
  OR b.run_id IS NULL OR b.stop_reason IS NOT NULL OR b.deadline_at<=clock_timestamp() OR (b.started_at,b.deadline_at) IS DISTINCT FROM (job.budget_started_at,job.budget_deadline_at)
  OR (b.definition_id,b.definition_version,b.max_steps,b.max_tokens,b.max_cost_nano_credits,b.concurrency_limit) IS DISTINCT FROM (rr.definition_id,rr.definition_version,1,(job.context_value->'definition'->>'ai_token_budget')::bigint,(job.context_value->'definition'->>'max_ai_cost_nano_credits')::bigint,(job.context_value->'definition'->>'concurrency_limit')::integer)
  OR zasp_temporal74.context(o,w,e,r) IS DISTINCT FROM job.context_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor planning authority changed';END IF;
 SELECT * INTO reservation FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1) FOR UPDATE;
 IF op IN('start','settle','admit') AND payload<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor planning unexpected payload';END IF;
 IF op='prepare' THEN
  IF NOT zasp_sa_multistep_prior.closed(payload,ARRAY['pricing','input_version']) OR jsonb_typeof(payload->'input_version')<>'string' OR length(payload->>'input_version') NOT BETWEEN 1 AND 1024 OR payload->>'input_version'!~'^[!-~]+$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor input artifact rejected';END IF;
  selection:=payload->'pricing';body_value:=zasp_temporal74.planning_body(job.context_value,selection);
  selection:=selection||jsonb_build_object('body',body_value,'body_digest','sha256:'||encode(digest(convert_to(body_value,'UTF8'),'sha256'),'hex'));
  IF (selection->>'organization_id',selection->>'workspace_id',selection->>'environment_id') IS DISTINCT FROM (o,w,e) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor pricing scope rejected';END IF;
  bound_value:=zasp_temporal74.pricing_lookup('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',selection);
  IF job.state='loaded' THEN
   IF reservation.run_id IS NOT NULL OR (bound_value->>'maximum_tokens')::bigint>b.max_tokens OR (bound_value->>'maximum_cost_nano_credits')::bigint>b.max_cost_nano_credits THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor pricing exceeds budget';END IF;
   INSERT INTO zasp_temporal74.provider_reservations(organization_id,workspace_id,environment_id,run_id,attempt,reservation_id,input_digest,model,cost_policy_version,cost_unit,maximum_tokens,maximum_cost_nano_credits)
    VALUES(o,w,e,r,1,job.reservation_id,decode(substring(job.input_digest FROM 8),'hex'),selection->>'model',bound_value->>'cost_policy_version','openrouter_credit',(bound_value->>'maximum_tokens')::bigint,(bound_value->>'maximum_cost_nano_credits')::bigint);
   UPDATE zasp_temporal74.planning_jobs SET state='prepared',request_body=body_value,request_digest=selection->>'body_digest',lookup_request=selection,pricing_bound=bound_value,input_version=payload->>'input_version' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
  ELSIF job.lookup_request IS DISTINCT FROM selection OR job.input_version IS DISTINCT FROM payload->>'input_version' OR job.pricing_bound IS DISTINCT FROM bound_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor intent conflict';END IF;
 END IF;
 IF job.lookup_request IS NOT NULL THEN
  IF job.request_body IS DISTINCT FROM zasp_temporal74.planning_body(job.context_value,job.lookup_request) OR job.request_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.request_body,'UTF8'),'sha256'),'hex') OR job.pricing_bound IS DISTINCT FROM zasp_temporal74.pricing_lookup('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',job.lookup_request) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor pricing drift';END IF;
  SELECT * INTO reservation FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1) FOR UPDATE;
  IF (reservation.reservation_id,reservation.input_digest,reservation.model,reservation.cost_policy_version,reservation.maximum_tokens,reservation.maximum_cost_nano_credits) IS DISTINCT FROM (job.reservation_id,decode(substring(job.input_digest FROM 8),'hex'),job.lookup_request->>'model',job.pricing_bound->>'cost_policy_version',(job.pricing_bound->>'maximum_tokens')::bigint,(job.pricing_bound->>'maximum_cost_nano_credits')::bigint) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor reservation drift';END IF;
  IF reservation.settled_at IS NOT NULL AND (reservation.output_digest,reservation.prompt_tokens,reservation.completion_tokens,reservation.total_tokens,reservation.cost_nano_credits) IS DISTINCT FROM (decode(substring(job.provider_digest FROM 8),'hex'),(job.result_value->'usage'->>'prompt_tokens')::bigint,(job.result_value->'usage'->>'completion_tokens')::bigint,(job.result_value->'usage'->>'total_tokens')::bigint,(job.result_value->'usage'->>'cost_nano_credits')::bigint) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor settlement differs from provider evidence';END IF;
 END IF;
 IF op='start' THEN
  IF job.state='prepared' THEN UPDATE zasp_temporal74.planning_jobs SET state='started' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;send_value:=true;
  ELSIF job.state<>'started' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor send unavailable';END IF;
 ELSIF op='result' THEN
  IF NOT zasp_sa_multistep_prior.closed(payload,ARRAY['raw']) OR jsonb_typeof(payload->'raw')<>'string' OR octet_length(payload->>'raw') NOT BETWEEN 1 AND 65536 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor result rejected';END IF;
  IF job.state='started' THEN
   cv:=zasp_temporal74.planning_result(payload->>'raw',job.lookup_request->>'model',job.context_value);body_value:=jsonb_build_object('raw',payload->>'raw','candidate',cv->'candidate')::text;
   UPDATE zasp_temporal74.planning_jobs SET state='completed',raw_result=payload->>'raw',result_value=cv,provider_digest='sha256:'||encode(digest(convert_to(payload->>'raw','UTF8'),'sha256'),'hex'),output_body=body_value,output_digest='sha256:'||encode(digest(convert_to(body_value,'UTF8'),'sha256'),'hex') WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
  ELSIF job.raw_result IS DISTINCT FROM payload->>'raw' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor result immutable';END IF;
 ELSIF op='settle' THEN
  IF job.state NOT IN('completed','settled','artifacts') OR job.result_value IS DISTINCT FROM zasp_temporal74.planning_result(job.raw_result,job.lookup_request->>'model',job.context_value) OR job.provider_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.raw_result,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor settlement unavailable';END IF;
  IF job.state='completed' THEN
   cv:=job.result_value->'usage';
   IF cv='null'::jsonb THEN reason:='budget_usage_unknown';ELSE
    UPDATE zasp_temporal74.provider_reservations SET settled_at=clock_timestamp(),output_digest=decode(substring(job.provider_digest FROM 8),'hex'),prompt_tokens=(cv->>'prompt_tokens')::bigint,completion_tokens=(cv->>'completion_tokens')::bigint,total_tokens=(cv->>'total_tokens')::bigint,cost_nano_credits=(cv->>'cost_nano_credits')::bigint WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);
    IF (cv->>'total_tokens')::bigint>least(reservation.maximum_tokens,b.max_tokens) THEN reason:='budget_tokens_exceeded';ELSIF (cv->>'cost_nano_credits')::bigint>least(reservation.maximum_cost_nano_credits,b.max_cost_nano_credits) THEN reason:='budget_cost_exceeded';END IF;
   END IF;
   UPDATE zasp_temporal74.planning_jobs SET state='settled' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
   IF reason IS NOT NULL OR job.result_value->'candidate'='null'::jsonb THEN
    IF reason IS NOT NULL THEN UPDATE public.zasp_security_agent_run_budgets SET stop_reason=reason WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
    PERFORM zasp_temporal74.planning_terminal(o,w,e,r,coalesce(reason,'planner_rejected'));
    SELECT * INTO job FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
   END IF;
  END IF;
 ELSIF op='artifacts' THEN
  IF job.state NOT IN('settled','artifacts') OR NOT zasp_sa_multistep_prior.closed(payload,ARRAY['input_version','output_version','output_digest']) OR payload->>'input_version' IS DISTINCT FROM job.input_version OR payload->>'output_digest' IS DISTINCT FROM job.output_digest OR jsonb_typeof(payload->'output_version')<>'string' OR length(payload->>'output_version') NOT BETWEEN 1 AND 1024 OR payload->>'output_version'!~'^[!-~]+$' OR job.output_version IS NOT NULL AND job.output_version IS DISTINCT FROM payload->>'output_version' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor artifact conflict';END IF;
  UPDATE zasp_temporal74.planning_jobs SET state='artifacts',output_version=payload->>'output_version' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
 ELSIF op='admit' THEN
  IF job.state NOT IN('artifacts','admitted') OR job.output_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.output_body,'UTF8'),'sha256'),'hex') OR job.output_body IS DISTINCT FROM jsonb_build_object('raw',job.raw_result,'candidate',job.result_value->'candidate')::text THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor immutable result unavailable';END IF;
  receipt_value:=zasp_temporal74.admit('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'definition_id',rr.definition_id,'definition_version',rr.definition_version,'trigger_id',rr.trigger_id,'attempt',1,'run_version',job.run_version,'input_digest',job.input_digest,'output_digest',job.provider_digest,'model',job.lookup_request->>'model','policy_version',job.lookup_request->>'request_policy_version','candidate',job.result_value->'candidate'));
  UPDATE zasp_temporal74.planning_jobs SET state='admitted',receipt=receipt_value WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
 END IF;
 IF b.deadline_at<=clock_timestamp() OR zasp_temporal74.context(o,w,e,r) IS DISTINCT FROM job.context_value OR NOT zasp_temporal74.current_ready() OR job.lookup_request IS NOT NULL AND job.pricing_bound IS DISTINCT FROM zasp_temporal74.pricing_lookup('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',job.lookup_request) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor planning authority expired after wait';END IF;
 IF op='admit' THEN RETURN job.receipt;END IF;
 IF op='start' THEN RETURN to_jsonb(job)||jsonb_build_object('send_permit',send_value);END IF;
 RETURN to_jsonb(job);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.planning_result(raw_value text, model_value text, cv jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE outer_value jsonb;candidate jsonb;usage_value jsonb;choice jsonb;k text;cost_value numeric;boundary_space text:=E' \t\n\r\v\f'||U&'\0085\00A0\1680\2000\2001\2002\2003\2004\2005\2006\2007\2008\2009\200A\2028\2029\202F\205F\3000';
BEGIN
 IF octet_length(raw_value) NOT BETWEEN 1 AND 65536 OR NOT zasp_sa_multistep_prior.pricing_unique_json(raw_value::json,0) THEN RETURN jsonb_build_object('candidate',NULL,'usage',NULL);END IF;
 outer_value:=raw_value::jsonb;
 IF jsonb_typeof(outer_value) IS DISTINCT FROM 'object' OR outer_value->>'model' IS DISTINCT FROM model_value THEN RETURN jsonb_build_object('candidate',NULL,'usage',NULL);END IF;
 BEGIN
  usage_value:=outer_value->'usage';
  FOREACH k IN ARRAY ARRAY['prompt_tokens','completion_tokens','total_tokens'] LOOP
   IF jsonb_typeof(usage_value->k) IS DISTINCT FROM 'number' OR usage_value->>k!~'^(0|[1-9][0-9]{0,18})$' OR (usage_value->>k)::numeric>9223372036854775807 THEN RAISE EXCEPTION 'unknown';END IF;
  END LOOP;
  IF (usage_value->>'prompt_tokens')::numeric+(usage_value->>'completion_tokens')::numeric<>(usage_value->>'total_tokens')::numeric
   OR jsonb_typeof(usage_value->'cost') IS DISTINCT FROM 'number' OR octet_length(usage_value->>'cost')>128 OR (usage_value->>'cost')::numeric<0 THEN RAISE EXCEPTION 'unknown';END IF;
  cost_value:=ceil((usage_value->>'cost')::numeric*1000000000);
  IF cost_value<0 OR cost_value>9223372036854775807 THEN RAISE EXCEPTION 'unknown';END IF;
  usage_value:=jsonb_build_object('prompt_tokens',(usage_value->>'prompt_tokens')::bigint,'completion_tokens',(usage_value->>'completion_tokens')::bigint,'total_tokens',(usage_value->>'total_tokens')::bigint,'cost_nano_credits',cost_value::bigint);
 EXCEPTION WHEN OTHERS THEN usage_value:=NULL;END;
 BEGIN
  IF jsonb_typeof(outer_value->'choices') IS DISTINCT FROM 'array' OR jsonb_array_length(outer_value->'choices')<>1 THEN RAISE EXCEPTION 'invalid';END IF;
  choice:=outer_value->'choices'->0;
  IF choice->'index' IS DISTINCT FROM '0'::jsonb OR choice->>'finish_reason' IS DISTINCT FROM 'stop' OR choice->'message'->>'role' IS DISTINCT FROM 'assistant'
   OR jsonb_typeof(choice->'message'->'content') IS DISTINCT FROM 'string' OR NOT zasp_sa_multistep_prior.pricing_unique_json((choice->'message'->>'content')::json,0) THEN RAISE EXCEPTION 'invalid';END IF;
  candidate:=(choice->'message'->>'content')::jsonb;
  IF NOT zasp_sa_multistep_prior.closed(candidate,ARRAY['version','summary','steps']) OR candidate->'version' IS DISTINCT FROM '1'::jsonb OR candidate->>'version'<>'1'
   OR jsonb_typeof(candidate->'summary') IS DISTINCT FROM 'string' OR octet_length(candidate->>'summary') NOT BETWEEN 1 AND 500 OR btrim(candidate->>'summary',boundary_space)<>candidate->>'summary' OR candidate->>'summary'~'[[:cntrl:]]'
   OR jsonb_typeof(candidate->'steps') IS DISTINCT FROM 'array' OR jsonb_array_length(candidate->'steps')<>1 OR candidate->'steps'->0 IS DISTINCT FROM jsonb_build_object('index',0,'action',cv->'context'->'allowed_actions'->>0,'target_id',cv->'context'->'existing_test'->>'definition_id') OR candidate->'steps'->0->>'index'<>'0' THEN RAISE EXCEPTION 'invalid';END IF;
 EXCEPTION WHEN OTHERS THEN candidate:=NULL;END;
 RETURN jsonb_build_object('candidate',candidate,'usage',usage_value);
EXCEPTION WHEN OTHERS THEN RETURN jsonb_build_object('candidate',NULL,'usage',NULL);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.planning_state(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;j zasp_temporal74.planning_jobs%ROWTYPE;k text;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR zasp_temporal68.principal_ready('zasp_temporal_compensation')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test planning read rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version']) OR octet_length(q::text)>4096 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test planning read shape rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test planning read scope rejected';END IF;END LOOP;
 SELECT * INTO x FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') AND to_jsonb(definition_version)=q->'definition_version';
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test planning owner changed';END IF;
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id,definition_version)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.definition_version);
 IF NOT FOUND THEN RETURN 'null'::jsonb;END IF;
 RETURN to_jsonb(j);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.planning_terminal(o text, w text, e text, r text, reason_value text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE body_value jsonb;audit_value text;dispatch_state text;
BEGIN
 SELECT state INTO STRICT dispatch_state FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 UPDATE public.zasp_security_agent_runs SET state='needs_human',last_error_code=reason_value,version=CASE WHEN state='needs_human' THEN version ELSE version+1 END,completed_at=COALESCE(completed_at,clock_timestamp()),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 UPDATE zasp_temporal74.planning_jobs SET state='needs_human' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT jsonb_build_object('job',to_jsonb(j),'reservation',(SELECT to_jsonb(p) FROM zasp_temporal74.provider_reservations p WHERE (p.organization_id,p.workspace_id,p.environment_id,p.run_id,p.attempt)=(o,w,e,r,1)),'reason',reason_value,'dispatch_state',dispatch_state) INTO body_value FROM zasp_temporal74.planning_jobs j WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_planning_terminal',r);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,audit_value,r,session_user,'temporal_planning_terminal',digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.planning_terminal_valid(o text, w text, e text, r text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a public.zasp_security_agent_audit%ROWTYPE;j zasp_temporal74.planning_jobs%ROWTYPE;p zasp_temporal74.provider_reservations%ROWTYPE;
BEGIN
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO p FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_terminal');
 IF EXISTS(SELECT 1 FROM zasp_temporal74.planning_late_usage WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN
  IF NOT zasp_temporal74.late_usage_valid(o,w,e,r) THEN RETURN false;END IF;
  -- The first terminal evidence remains authoritative for what was known at
  -- that instant. The separate immutable ledger proves the later charge.
  p:=jsonb_populate_record(NULL::zasp_temporal74.provider_reservations,a.body->'reservation');
 END IF;
 RETURN COALESCE(j.state='needs_human' AND a.audit_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_planning_terminal',r) AND a.correlation_id=a.audit_id AND a.event_digest=digest(convert_to(a.body::text,'UTF8'),'sha256')
  AND a.body=jsonb_build_object('job',to_jsonb(j),'reservation',CASE WHEN p.run_id IS NULL THEN 'null'::jsonb ELSE to_jsonb(p) END,'reason',(SELECT last_error_code FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)),'dispatch_state',a.body->>'dispatch_state')
  AND j.input_digest='sha256:'||encode(digest(convert_to(j.input_body,'UTF8'),'sha256'),'hex') AND j.input_body=j.context_value::text
  AND CASE WHEN a.body->>'reason'='planner_not_sent' THEN j.raw_result IS NULL AND j.result_value IS NULL AND j.provider_digest IS NULL AND j.output_body IS NULL AND j.output_digest IS NULL
   AND (a.body->>'dispatch_state'='loaded' AND j.lookup_request IS NULL AND j.pricing_bound IS NULL AND j.request_body IS NULL AND j.request_digest IS NULL AND j.input_version IS NULL AND p.run_id IS NULL
    OR a.body->>'dispatch_state'='prepared' AND j.lookup_request IS NOT NULL AND j.pricing_bound IS NOT NULL AND j.input_version IS NOT NULL AND p.released_at IS NOT NULL AND p.settled_at IS NULL AND p.output_digest IS NULL AND p.total_tokens IS NULL AND p.cost_nano_credits IS NULL)
   ELSE a.body->>'dispatch_state' IN('started','completed','settled','artifacts') AND p.released_at IS NULL
    AND (j.raw_result IS NULL AND p.settled_at IS NULL AND p.total_tokens IS NULL AND p.cost_nano_credits IS NULL OR j.raw_result IS NOT NULL AND j.provider_digest='sha256:'||encode(digest(convert_to(j.raw_result,'UTF8'),'sha256'),'hex') AND j.result_value=zasp_temporal74.planning_result(j.raw_result,j.lookup_request->>'model',j.context_value)
     AND (j.result_value->'usage'='null'::jsonb AND p.settled_at IS NULL OR j.result_value->'usage'<>'null'::jsonb AND p.settled_at IS NOT NULL AND (p.total_tokens,p.cost_nano_credits)=((j.result_value->'usage'->>'total_tokens')::bigint,(j.result_value->'usage'->>'cost_nano_credits')::bigint))) END,false);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.pricing_lookup(checksum_value text, fingerprint_value text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;k text;pid text;aid text;body jsonb;p zasp_sa_multistep_prior.pricing_policies%ROWTYPE;a zasp_sa_multistep_prior.pricing_accounts%ROWTYPE;response_value jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='pricing requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT COALESCE(zasp_temporal68.principal_ready('zasp_temporal_executor'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='pricing worker principal rejected';END IF;
 IF NOT public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='pricing release unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','provider','model','account_profile','cost_unit','credential_reference','credential_digest','request_policy_version','request_token_limit','body','body_digest','policy_id','policy_version','policy_digest','account_id','account_version']) OR octet_length(q::text)>524288 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='pricing lookup rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','policy_id','account_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT public.zasp_valid_product_id(q->>k) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='pricing lookup scope rejected';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['policy_version','account_version','request_token_limit'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'number' OR q->>k!~'^([1-9][0-9]{0,5}|1000000)$' OR k='policy_version' AND q->>k='1000000' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='pricing lookup version rejected';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['provider','model','account_profile','cost_unit','credential_reference','credential_digest','request_policy_version','body','body_digest','policy_digest'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='pricing lookup text rejected';END IF;
 END LOOP;
 IF octet_length(q->>'body') NOT BETWEEN 1 AND 65536 OR q->>'body_digest' IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(q->>'body','UTF8'),'sha256'),'hex') OR NOT zasp_sa_multistep_prior.pricing_unique_json((q->>'body')::json,0) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='pricing request digest rejected';END IF;
 body:=(q->>'body')::jsonb;
 IF NOT zasp_sa_multistep_prior.closed(body,ARRAY['model','max_tokens','messages','provider','response_format']) OR body->'model' IS DISTINCT FROM q->'model' OR body->'max_tokens' IS DISTINCT FROM q->'request_token_limit'
  OR body->'provider' IS DISTINCT FROM '{"data_collection":"deny","require_parameters":true}'::jsonb
  OR jsonb_typeof(body->'messages') IS DISTINCT FROM 'array' OR jsonb_array_length(body->'messages')<>2
  OR NOT zasp_sa_multistep_prior.closed(body->'messages'->0,ARRAY['role','content']) OR NOT zasp_sa_multistep_prior.closed(body->'messages'->1,ARRAY['role','content'])
  OR body->'messages'->0->>'role'<>'system' OR body->'messages'->1->>'role'<>'user'
  OR jsonb_typeof(body->'messages'->0->'content') IS DISTINCT FROM 'string' OR jsonb_typeof(body->'messages'->1->'content') IS DISTINCT FROM 'string'
  OR octet_length(body->'messages'->0->>'content') NOT BETWEEN 1 AND 4096 OR octet_length(body->'messages'->1->>'content') NOT BETWEEN 1 AND 49152
  OR NOT zasp_sa_multistep_prior.closed(body->'response_format',ARRAY['type','json_schema']) OR body->'response_format'->>'type'<>'json_schema'
  OR NOT zasp_sa_multistep_prior.closed(body->'response_format'->'json_schema',ARRAY['name','strict','schema']) OR body->'response_format'->'json_schema'->>'name'<>'security_response_plan'
  OR body->'response_format'->'json_schema'->'strict' IS DISTINCT FROM 'true'::jsonb OR jsonb_typeof(body->'response_format'->'json_schema'->'schema') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='pricing prepared request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';
 pid:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_pricing_policy',concat_ws(chr(31),q->>'provider',q->>'model',q->>'account_profile'));
 aid:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_pricing_account',concat_ws(chr(31),q->>'provider',q->>'account_profile'));
 IF pid<>q->>'policy_id' OR aid<>q->>'account_id' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='pricing canonical identity rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM 1 FROM zasp_sa_multistep_prior.pricing_policies WHERE (organization_id,workspace_id,environment_id)=(o,w,e) AND policy->>'provider'=q->>'provider' AND policy->>'model'=q->>'model' AND policy->>'account_profile'=q->>'account_profile' ORDER BY policy_id,version FOR SHARE;
 PERFORM 1 FROM zasp_sa_multistep_prior.pricing_accounts WHERE (organization_id,workspace_id,environment_id)=(o,w,e) AND provider=q->>'provider' AND account_profile=q->>'account_profile' ORDER BY account_id,version FOR SHARE;
 IF (SELECT count(DISTINCT policy_id) FROM zasp_sa_multistep_prior.pricing_policies WHERE (organization_id,workspace_id,environment_id)=(o,w,e) AND policy->>'provider'=q->>'provider' AND policy->>'model'=q->>'model' AND policy->>'account_profile'=q->>'account_profile')<>1
  OR (SELECT count(DISTINCT account_id) FROM zasp_sa_multistep_prior.pricing_accounts WHERE (organization_id,workspace_id,environment_id,provider,account_profile)=(o,w,e,q->>'provider',q->>'account_profile'))<>1 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='pricing policy absent or ambiguous';END IF;
 SELECT * INTO p FROM zasp_sa_multistep_prior.pricing_policies WHERE (organization_id,workspace_id,environment_id,policy_id)=(o,w,e,pid) ORDER BY version DESC LIMIT 1;
 SELECT * INTO a FROM zasp_sa_multistep_prior.pricing_accounts WHERE (organization_id,workspace_id,environment_id,account_id)=(o,w,e,aid) ORDER BY version DESC LIMIT 1;
 IF p.policy_id IS NULL OR a.account_id IS NULL OR p.disabled OR p.version<>(q->>'policy_version')::bigint OR p.policy_digest<>q->>'policy_digest' OR p.policy_digest<>zasp_sa_multistep_prior.pricing_digest(p)
  OR p.account_id<>aid OR p.account_version<>a.version OR a.version<>(q->>'account_version')::bigint
  OR a.credential_reference<>q->>'credential_reference' OR a.credential_digest<>q->>'credential_digest'
  OR p.policy->>'credential_reference'<>a.credential_reference OR p.policy->>'credential_digest'<>a.credential_digest
  OR (p.policy->>'effective_at')::timestamptz>clock_timestamp() OR (p.policy->>'expires_at')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='pricing current authority unavailable';END IF;
 FOREACH k IN ARRAY ARRAY['provider','model','account_profile','cost_unit','request_policy_version','request_token_limit'] LOOP
  IF p.policy->k IS DISTINCT FROM q->k THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='pricing request authority mismatch';END IF;
 END LOOP;
 response_value:=jsonb_build_object('contract_version',61,'organization_id',o,'workspace_id',w,'environment_id',e,'policy_id',pid,'policy_version',p.version,'policy_digest',p.policy_digest,'account_id',aid,'account_version',a.version,'body_digest',q->>'body_digest','policy',p.policy,'maximum_tokens',(p.policy->>'maximum_tokens')::bigint,'maximum_cost_nano_credits',(p.policy->>'maximum_cost_nano_credits')::bigint,'cost_policy_version','pricing61-'||p.version::text||'-'||substring(p.policy_digest FROM 8 FOR 32));
 IF NOT public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value) OR NOT zasp_temporal68.principal_ready('zasp_temporal_executor') OR (p.policy->>'expires_at')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='pricing lookup authority changed';END IF;
 RETURN response_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.record_control(o text, w text, e text, r text, actor_value text, operation_value text, key_value text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rc public.zasp_security_agent_request_receipts%ROWTYPE;kind_value text;id_value text;
BEGIN
 SELECT * INTO STRICT rc FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor_value,operation_value,key_value);
 IF NOT COALESCE(operation_value IN('cancelSecurityAgentRun','decideSecurityAgentApproval') AND rc.response->>'state' IN('approved','rejected','cancelled'),false) OR (CASE WHEN operation_value='cancelSecurityAgentRun' THEN rc.response->>'id' ELSE rc.response->>'run_id' END) IS DISTINCT FROM r THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test decision receipt rejected';END IF;
 kind_value:=CASE rc.response->>'state' WHEN 'approved' THEN 'approval' ELSE 'cancel' END;
 id_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_control',r||chr(31)||rc.receipt_id);
 INSERT INTO zasp_temporal74.control_intents VALUES(o,w,e,r,id_value,kind_value,actor_value,operation_value,key_value,rc.resource_id,rc.expected_version,rc.receipt_id,rc.audit_id,digest(convert_to(rc.response::text,'UTF8'),'sha256')) ON CONFLICT DO NOTHING;
 IF NOT EXISTS(SELECT 1 FROM zasp_temporal74.control_intents WHERE (organization_id,workspace_id,environment_id,run_id,control_id,kind,actor_id,operation,idempotency_key,resource_id,expected_version,receipt_id,audit_id,response_digest)=(o,w,e,r,id_value,kind_value,actor_value,operation_value,key_value,rc.resource_id,rc.expected_version,rc.receipt_id,rc.audit_id,digest(convert_to(rc.response::text,'UTF8'),'sha256'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test decision replay changed';END IF;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.record_late_usage(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;k text;payload jsonb;raw text;cv jsonb;body_value jsonb;audit_value text;
 j zasp_temporal74.planning_jobs%ROWTYPE;p zasp_temporal74.provider_reservations%ROWTYPE;l zasp_temporal74.planning_late_usage%ROWTYPE;a public.zasp_security_agent_audit%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='late usage requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR zasp_temporal68.principal_ready('zasp_temporal_compensation')) OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='late usage principal unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','operation','payload']) OR q->>'operation' IS DISTINCT FROM 'late_usage' OR octet_length(q::text)>131072
  OR NOT zasp_sa_multistep_prior.closed(q->'payload',ARRAY['raw','request_digest','credential_digest','reservation_id','response_id','response_digest']) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='late usage request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='late usage scope rejected';END IF;
 END LOOP;
 payload:=q->'payload';
 FOREACH k IN ARRAY ARRAY['raw','request_digest','credential_digest','reservation_id','response_id','response_digest'] LOOP
  IF jsonb_typeof(payload->k) IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='late usage association rejected';END IF;
 END LOOP;
 raw:=payload->>'raw';
 IF octet_length(raw) NOT BETWEEN 1 AND 65536 OR length(payload->>'response_id') NOT BETWEEN 1 AND 256 OR payload->>'response_id'!~'^[!-~]+$'
  OR payload->>'response_digest' IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(raw,'UTF8'),'sha256'),'hex')
  OR jsonb_typeof(raw::jsonb) IS DISTINCT FROM 'object' OR jsonb_typeof((raw::jsonb)->'id') IS DISTINCT FROM 'string' OR (raw::jsonb)->>'id' IS DISTINCT FROM payload->>'response_id'
  OR (SELECT count(*)<>count(DISTINCT key) FROM json_each(raw::json)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='late provider response rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM 1 FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 PERFORM 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF j.run_id IS NULL OR j.state<>'needs_human' OR q->'definition_version' IS DISTINCT FROM to_jsonb(j.definition_version)
  OR payload->>'request_digest' IS DISTINCT FROM j.request_digest OR payload->>'credential_digest' IS DISTINCT FROM j.lookup_request->>'credential_digest' OR payload->>'reservation_id' IS DISTINCT FROM j.reservation_id THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='late usage original association rejected';END IF;
 -- This retains the full owner/budget/run/terminal checks and cannot create a
 -- new terminal snapshot: the explicit state check above requires one already.
 PERFORM zasp_temporal74.recover_plan(q||jsonb_build_object('operation','reconcile','payload','{}'::jsonb));
 SELECT * INTO l FROM zasp_temporal74.planning_late_usage WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF FOUND THEN
  IF l.body->>'raw' IS DISTINCT FROM raw OR l.body->'association' IS DISTINCT FROM payload-'raw' OR NOT zasp_temporal74.late_usage_valid(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='late usage immutable conflict';END IF;
  RETURN to_jsonb(j);
 END IF;
 SELECT * INTO p FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1) FOR UPDATE;
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_terminal');
 cv:=zasp_temporal74.planning_result(raw,j.lookup_request->>'model',j.context_value);
 IF p.run_id IS NULL OR p.settled_at IS NOT NULL OR p.released_at IS NOT NULL OR cv->'usage' IS NULL OR cv->'usage'='null'::jsonb OR j.raw_result IS NOT NULL AND ((j.raw_result::jsonb)-'usage' IS DISTINCT FROM (raw::jsonb)-'usage' OR j.result_value->'usage' IS DISTINCT FROM 'null'::jsonb) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='late known usage unavailable';END IF;
 UPDATE zasp_temporal74.provider_reservations SET settled_at=clock_timestamp(),output_digest=digest(convert_to(raw,'UTF8'),'sha256'),prompt_tokens=(cv->'usage'->>'prompt_tokens')::bigint,completion_tokens=(cv->'usage'->>'completion_tokens')::bigint,total_tokens=(cv->'usage'->>'total_tokens')::bigint,cost_nano_credits=(cv->'usage'->>'cost_nano_credits')::bigint WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1) RETURNING * INTO p;
 body_value:=jsonb_build_object('raw',raw,'association',payload-'raw','terminal_digest',encode(a.event_digest,'hex'),'reservation',to_jsonb(p),'usage',cv->'usage');
 INSERT INTO zasp_temporal74.planning_late_usage VALUES(o,w,e,r,payload->>'response_id',payload->>'credential_digest',body_value,digest(convert_to(body_value::text,'UTF8'),'sha256'));
 audit_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_planning_late_usage',r);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_value,audit_value,r,session_user,'temporal_planning_late_usage',digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
 IF NOT zasp_temporal74.planning_terminal_valid(o,w,e,r) OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='late usage evidence rejected';END IF;
 RETURN to_jsonb(j);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.recover_plan(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;k text;j zasp_temporal74.planning_jobs%ROWTYPE;p zasp_temporal74.provider_reservations%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;cv jsonb;body_value text;reason_value text:='execution_authority_lost';
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor recovery requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR zasp_temporal68.principal_ready('zasp_temporal_compensation')) OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor planning recovery unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','operation','payload']) OR q->>'operation' IS DISTINCT FROM 'reconcile' OR octet_length(q::text)>131072 OR NOT(zasp_sa_multistep_prior.closed(q->'payload',ARRAY[]::text[]) OR zasp_sa_multistep_prior.closed(q->'payload',ARRAY['raw']) AND jsonb_typeof(q->'payload'->'raw')='string' AND octet_length(q->'payload'->>'raw') BETWEEN 1 AND 65536) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor planning recovery request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor recovery scope rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO p FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1) FOR UPDATE;
 IF NOT zasp_temporal74.is_owned(o,w,e,r) OR j.state NOT IN('loaded','prepared','started','completed','settled','artifacts','needs_human') OR j.run_id IS NULL OR (j.lookup_request IS NULL) IS DISTINCT FROM (p.run_id IS NULL) OR q->'definition_version' IS DISTINCT FROM to_jsonb(j.definition_version)
  OR rr.lease_owner IS NOT NULL OR rr.lease_token IS NOT NULL OR rr.lease_expires_at IS NOT NULL OR rr.plan_hash IS NOT NULL OR (b.started_at,b.deadline_at) IS DISTINCT FROM(j.budget_started_at,j.budget_deadline_at)
  OR (b.definition_id,b.definition_version,b.max_steps,b.max_tokens,b.max_cost_nano_credits,b.concurrency_limit) IS DISTINCT FROM(rr.definition_id,rr.definition_version,1,(j.context_value->'definition'->>'ai_token_budget')::bigint,(j.context_value->'definition'->>'max_ai_cost_nano_credits')::bigint,(j.context_value->'definition'->>'concurrency_limit')::integer)
  OR b.deadline_at IS DISTINCT FROM b.started_at+make_interval(secs=>(j.context_value->'definition'->>'max_duration_seconds')::integer)
  OR j.lookup_request IS NOT NULL AND (p.input_digest,p.reservation_id,p.model) IS DISTINCT FROM(decode(substr(j.input_digest,8),'hex'),j.reservation_id,j.lookup_request->>'model') OR j.input_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(j.input_body,'UTF8'),'sha256'),'hex') OR j.input_body IS DISTINCT FROM j.context_value::text THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor recovery intent changed';END IF;
 IF j.state='needs_human' THEN
  IF NOT zasp_temporal74.planning_terminal_valid(o,w,e,r) OR q->'payload'<>'{}'::jsonb AND q->'payload'->>'raw' IS DISTINCT FROM j.raw_result THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor terminal replay conflict';END IF;
  RETURN to_jsonb(j);
 END IF;
 IF j.state IN('loaded','prepared') THEN
  IF q->'payload'<>'{}'::jsonb OR j.raw_result IS NOT NULL OR p.settled_at IS NOT NULL OR p.released_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='unstarted recovery evidence rejected';END IF;
  IF j.state='prepared' THEN UPDATE zasp_temporal74.provider_reservations SET released_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);END IF;
  PERFORM zasp_temporal74.planning_terminal(o,w,e,r,'planner_not_sent');
  IF NOT zasp_temporal74.planning_terminal_valid(o,w,e,r) OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='unstarted terminal evidence rejected';END IF;
  SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  RETURN to_jsonb(j);
 END IF;
 IF q->'payload'<>'{}'::jsonb THEN
  IF j.state='started' THEN
   cv:=zasp_temporal74.planning_result(q->'payload'->>'raw',j.lookup_request->>'model',j.context_value);body_value:=jsonb_build_object('raw',q->'payload'->>'raw','candidate',cv->'candidate')::text;
   UPDATE zasp_temporal74.planning_jobs SET state='completed',raw_result=q->'payload'->>'raw',result_value=cv,provider_digest='sha256:'||encode(digest(convert_to(q->'payload'->>'raw','UTF8'),'sha256'),'hex'),output_body=body_value,output_digest='sha256:'||encode(digest(convert_to(body_value,'UTF8'),'sha256'),'hex') WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO j;
  ELSIF j.raw_result IS DISTINCT FROM q->'payload'->>'raw' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor retained provider response changed';END IF;
 END IF;
 IF b.deadline_at<=clock_timestamp() THEN reason_value:='budget_deadline_exceeded';END IF;
 cv:=j.result_value->'usage';
 IF cv IS NULL OR cv='null'::jsonb THEN reason_value:='budget_usage_unknown';
 ELSE
  IF j.provider_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(j.raw_result,'UTF8'),'sha256'),'hex') OR j.result_value IS DISTINCT FROM zasp_temporal74.planning_result(j.raw_result,j.lookup_request->>'model',j.context_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor recovery provider evidence changed';END IF;
  IF p.settled_at IS NULL THEN UPDATE zasp_temporal74.provider_reservations SET settled_at=clock_timestamp(),output_digest=decode(substr(j.provider_digest,8),'hex'),prompt_tokens=(cv->>'prompt_tokens')::bigint,completion_tokens=(cv->>'completion_tokens')::bigint,total_tokens=(cv->>'total_tokens')::bigint,cost_nano_credits=(cv->>'cost_nano_credits')::bigint WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);END IF;
  IF (cv->>'total_tokens')::bigint>least(p.maximum_tokens,b.max_tokens) THEN reason_value:='budget_tokens_exceeded';ELSIF (cv->>'cost_nano_credits')::bigint>least(p.maximum_cost_nano_credits,b.max_cost_nano_credits) THEN reason_value:='budget_cost_exceeded';END IF;
 END IF;
 IF reason_value LIKE 'budget_%' THEN UPDATE public.zasp_security_agent_run_budgets SET stop_reason=reason_value WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
 PERFORM zasp_temporal74.planning_terminal(o,w,e,r,reason_value);
 IF NOT zasp_temporal74.planning_terminal_valid(o,w,e,r) OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor planning recovery evidence changed';END IF;
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 RETURN to_jsonb(j);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.start_identity(q jsonb)
 RETURNS zasp_temporal74.run_owners
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;k text;
BEGIN
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest']) OR octet_length(q::text)>4096 OR q->>'input_digest'!~'^[a-f0-9]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test start rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test start scope rejected';END IF;END LOOP;
 SELECT * INTO x FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id,input_digest)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'input_digest') AND to_jsonb(definition_version)=q->'definition_version';
 IF x.run_id IS NULL OR x.workflow_id IS DISTINCT FROM 'security-agent-test/v1/'||x.organization_id||'/'||x.workspace_id||'/'||x.environment_id||'/'||x.run_id
  OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts t WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.definition_id,t.trigger_id,t.trigger_version,t.trigger_digest)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.definition_id,x.trigger_id,x.trigger_version,decode(x.input_digest,'hex')))
 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test durable start changed';END IF;
 RETURN x;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal75.desired(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE c zasp_temporal75.configuration%ROWTYPE;d public.zasp_security_agent_definitions%ROWTYPE;BEGIN
 PERFORM zasp_temporal75.require_executor();
 IF NOT COALESCE(jsonb_typeof(q)='object' AND q?&ARRAY['organization_id','workspace_id','environment_id','definition_id'] AND q-ARRAY['organization_id','workspace_id','environment_id','definition_id']='{}'::jsonb
 AND public.zasp_valid_product_id(q->>'organization_id') AND public.zasp_valid_product_id(q->>'workspace_id') AND public.zasp_valid_product_id(q->>'environment_id') AND public.zasp_valid_product_id(q->>'definition_id'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='selector scope rejected';END IF;
 SELECT * INTO c FROM zasp_temporal75.configuration ORDER BY revision DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='selector configuration missing';END IF;
 SELECT * INTO d FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'definition_id');
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='selector definition absent';END IF;
 RETURN jsonb_build_object('ref',q,'revision',c.revision,'schema_version',c.schema_version,'cadence_seconds',c.cadence_seconds,'enabled',c.enabled AND d.deleted_at IS NULL AND d.activation IN('supervised','autonomous') AND d.body->'enabled'='true'::jsonb AND d.body->'allowed_actions' IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal75.retained_body(worker_value text, limit_value integer, expected_checksum text, expected_fingerprint text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE candidate record;result_value jsonb;created_value integer:=0;run_value text;prior_count integer;admissions_value jsonb:='[]'::jsonb;admitted_value jsonb;
BEGIN
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_worker'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='security agent principal unavailable';END IF;
 IF NOT COALESCE(length(worker_value) BETWEEN 1 AND 128 AND limit_value BETWEEN 1 AND 25,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test schedule rejected';END IF;
 IF NOT zasp_temporal70.guard01(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 FOR candidate IN
  SELECT d.organization_id o,d.workspace_id w,d.environment_id e,d.definition_id d,d.version v,d.body->>'trigger_kind' k,x.id t,x.version tv
  FROM public.zasp_security_agent_definitions d CROSS JOIN LATERAL (
   SELECT f.id,f.version FROM public.zasp_risk_findings f WHERE (f.organization_id,f.workspace_id,f.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='finding' AND f.status='open' AND f.rule=d.body->>'trigger_source'
   UNION ALL SELECT p.id,p.version FROM public.zasp_risk_attack_paths p WHERE (p.organization_id,p.workspace_id,p.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='attack_path' AND p.state=d.body->>'trigger_source' AND p.state IN('observed','verified') AND public.zasp_risk_attack_path_valid(p)
   UNION ALL SELECT ev.classification->>'session_id',ev.sequence FROM public.zasp_runtime_gateway_events ev
    JOIN public.zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(ev.organization_id,ev.workspace_id,ev.environment_id,ev.device_id,'active')
    JOIN public.zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id,credential.id)=(ev.organization_id,ev.workspace_id,ev.environment_id,ev.device_id,ev.credential_id)
    WHERE (ev.organization_id,ev.workspace_id,ev.environment_id)=(d.organization_id,d.workspace_id,d.environment_id) AND d.body->>'trigger_kind'='runtime_decision' AND ev.decision='block' AND ev.classification->>'outcome'=d.body->>'trigger_source' AND ev.occurred_at>=clock_timestamp()-interval '5 minutes' AND ev.occurred_at<=clock_timestamp() AND public.zasp_valid_product_id(ev.classification->>'session_id')
    AND credential.revoked_at IS NULL AND credential.expires_at>clock_timestamp()
    AND credential.id=(SELECT c.id FROM public.zasp_gateway_credentials c WHERE (c.organization_id,c.workspace_id,c.environment_id,c.device_id)=(d.organization_id,d.workspace_id,d.environment_id,ev.device_id) AND c.revoked_at IS NULL AND c.expires_at>clock_timestamp() ORDER BY c.issued_at DESC,c.id DESC LIMIT 1)
    AND ev.event_id=(SELECT newest.event_id FROM public.zasp_runtime_gateway_events newest WHERE (newest.organization_id,newest.workspace_id,newest.environment_id,newest.classification->>'session_id',newest.decision,newest.classification->>'outcome')=(d.organization_id,d.workspace_id,d.environment_id,ev.classification->>'session_id','block',d.body->>'trigger_source') AND newest.occurred_at<=clock_timestamp() ORDER BY newest.occurred_at DESC,newest.sequence DESC,newest.event_id DESC LIMIT 1)
  ) x
  WHERE false AND d.deleted_at IS NULL AND d.activation IN('supervised','autonomous') AND d.body->'enabled'='true'::jsonb AND d.body ? 'existing_test'
   AND zasp_temporal70.body04(d.organization_id,d.workspace_id,d.environment_id,d.body,d.activation)
   AND zasp_temporal73.active_count(d.organization_id,d.workspace_id,d.environment_id,d.definition_id)<(d.body->>'concurrency_limit')::integer
   AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.trigger_id,tr.trigger_version)=(d.organization_id,d.workspace_id,d.environment_id,d.definition_id,x.id,x.version))
  -- Scan work is capped independently of successful admissions. A refused
  -- candidate must not consume the entire caller's successful-work allowance.
  ORDER BY d.organization_id,d.workspace_id,d.environment_id,d.definition_id,x.id,x.version DESC LIMIT least(100,limit_value*4)
 LOOP
  EXIT WHEN created_value>=limit_value;
  BEGIN
   -- Skip contended organizations before entering the blocking shared core.
   CONTINUE WHEN NOT pg_try_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||candidate.o,0));
   run_value:=public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_run',concat_ws(chr(31),candidate.d,candidate.v,candidate.k,candidate.t,candidate.tv));
   result_value:=zasp_temporal73.admit(candidate.o,candidate.w,candidate.e,candidate.d,candidate.v,candidate.k,candidate.t,candidate.tv,run_value,worker_value,public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_audit',run_value),public.zasp_discovery_canonical_id(candidate.o,candidate.w,candidate.e,'security_agent_correlation',run_value),true);
   IF (result_value->>'created')::boolean THEN
    created_value:=created_value+1;
    admissions_value:=admissions_value||jsonb_build_array(jsonb_build_object('o',candidate.o,'w',candidate.w,'e',candidate.e,'d',candidate.d,'v',candidate.v,'r',run_value));
   END IF;
  EXCEPTION WHEN SQLSTATE '40001' OR SQLSTATE '42501' OR SQLSTATE '55000' OR SQLSTATE '23505' THEN
   -- A stale candidate rolls back its whole subtransaction, including receipts.
   CONTINUE;
  END;
 END LOOP;
 IF created_value<limit_value THEN
  prior_count:=(public.zasp_security_agent_schedule_triggers_v33(worker_value,limit_value-created_value)->>'created')::integer;
  IF prior_count IS NULL OR prior_count<0 OR prior_count>limit_value-created_value THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test scheduler bound violated';END IF;
  created_value:=created_value+prior_count;
 END IF;
 IF NOT zasp_temporal70.guard01(expected_checksum,expected_fingerprint) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='existing test admission release unavailable';END IF;
 -- Later candidates and the delegated legacy scheduler can block after an
 -- earlier test admission. Revalidate every new test run at the commit edge.
 FOR admitted_value IN SELECT value FROM jsonb_array_elements(admissions_value) LOOP
  PERFORM zasp_temporal70.body15(admitted_value->>'o',admitted_value->>'w',admitted_value->>'e',admitted_value->>'d',(admitted_value->>'v')::bigint);
  IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_trigger_receipts tr JOIN public.zasp_security_agent_definitions d ON (d.organization_id,d.workspace_id,d.environment_id,d.definition_id)=(tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id)
   WHERE (tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.run_id)=(admitted_value->>'o',admitted_value->>'w',admitted_value->>'e',admitted_value->>'d',admitted_value->>'r')
    AND public.zasp_production_security_agent_existing_tests_trigger(tr.organization_id,tr.workspace_id,tr.environment_id,tr.trigger_kind,tr.trigger_id,d.body->>'trigger_source',tr.trigger_version)=jsonb_build_object('version',tr.trigger_version,'digest',encode(tr.trigger_digest,'hex'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test scheduled admission changed before commit';END IF;
 END LOOP;
 RETURN jsonb_build_object('created',created_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal77.admit_occurrence(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ref jsonb:=q->'ref';o text:=ref->>'organization_id';w text:=ref->>'workspace_id';e text:=ref->>'environment_id';d text:=ref->>'definition_id';id_value text:=q->>'event_id';
 def public.zasp_security_agent_definitions%ROWTYPE;s zasp_temporal77.source_events%ROWTYPE;prior zasp_temporal77.occurrences%ROWTYPE;legacy public.zasp_security_agent_trigger_receipts%ROWTYPE;
 grant_value jsonb;matched jsonb;until_value timestamptz;now_value timestamptz;disposition_value text;run_value text;result_value jsonb;
BEGIN
 PERFORM zasp_temporal77.require_executor();
 IF NOT COALESCE(zasp_sa_multistep_prior.closed(q,ARRAY['ref','revision','event_id']) AND zasp_sa_multistep_prior.closed(ref,ARRAY['organization_id','workspace_id','environment_id','definition_id'])
 AND public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(d) AND public.zasp_valid_product_id(id_value)
 AND jsonb_typeof(q->'revision')='number' AND q->>'revision'~'^[1-9][0-9]{0,6}$' AND (q->>'revision')::bigint<=1000000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic occurrence scope rejected';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('test-selector75-configuration',0));
 IF NOT EXISTS(SELECT 1 FROM zasp_temporal75.configuration WHERE revision=(q->>'revision')::bigint AND enabled AND revision=(SELECT max(revision) FROM zasp_temporal75.configuration)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic selector configuration changed';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO def FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic definition scope denied';END IF;
 IF def.deleted_at IS NOT NULL OR def.activation NOT IN('supervised','autonomous') OR def.body->>'autonomy' IS DISTINCT FROM def.activation OR def.body->'enabled' IS DISTINCT FROM 'true'::jsonb
 OR def.body->'trigger_rules'->>'mode' IS DISTINCT FROM 'automatic' THEN RETURN jsonb_build_object('disposition','ignored');END IF;
 IF NOT zasp_temporal77.rules_valid(def.body) OR NOT zasp_temporal77.rules_capable(def.body) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic adapter unavailable';END IF;
 grant_value:=zasp_temporal74.authorize(o,w,e,d,def.version);
 SELECT * INTO s FROM zasp_temporal77.source_events WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,id_value);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic source scope denied';END IF;
 SELECT * INTO prior FROM zasp_temporal77.occurrences WHERE(organization_id,workspace_id,environment_id,definition_id,event_id)=(o,w,e,d,id_value);
 IF FOUND THEN RETURN jsonb_strip_nulls(jsonb_build_object('disposition','replayed','run_id',prior.run_id,'original_disposition',prior.disposition));END IF;
 -- Registered finding/path writers lock their parent before replacing children.
 IF s.source_kind='finding' THEN PERFORM 1 FROM public.zasp_risk_findings WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,s.source_id) FOR SHARE;
 ELSIF s.source_kind='attack_path' THEN PERFORM 1 FROM public.zasp_risk_attack_paths WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,s.source_id) FOR SHARE;
 ELSE RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime automatic adapter unavailable';END IF;
 now_value:=clock_timestamp();matched:=zasp_temporal77.source_match(o,w,e,id_value,def.body,now_value);
 IF matched IS NULL THEN RETURN jsonb_build_object('disposition','ignored');END IF;
 -- Pre77 receipts permanently consumed the same scoped source occurrence.
 -- Never send these through75's same-definition-version replay branch.
 SELECT tr.* INTO legacy FROM public.zasp_security_agent_trigger_receipts tr JOIN public.zasp_security_agent_runs r ON(r.organization_id,r.workspace_id,r.environment_id,r.run_id,r.definition_id)=(tr.organization_id,tr.workspace_id,tr.environment_id,tr.run_id,tr.definition_id)
 WHERE(tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.trigger_id,tr.trigger_version,tr.trigger_kind)=(o,w,e,d,s.source_id,s.source_version,s.source_kind) FOR SHARE OF tr,r;
 IF FOUND THEN disposition_value:='consumed';run_value:=legacy.run_id;
 ELSE
  SELECT admitted_until INTO until_value FROM zasp_temporal77.cooldowns WHERE(organization_id,workspace_id,environment_id,definition_id,pattern_key)=(o,w,e,d,decode(matched->>'cooldown_key','hex'));
  IF until_value IS NOT NULL AND now_value<until_value THEN disposition_value:='cooldown';
  ELSE
   disposition_value:='admitted';
   run_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',concat_ws(chr(31),d,def.version,s.source_kind,s.source_id,s.source_version));
  END IF;
 END IF;
 INSERT INTO zasp_temporal77.occurrences(organization_id,workspace_id,environment_id,definition_id,event_id,definition_version,definition_digest,disposition,run_id,snapshot,snapshot_digest)
 VALUES(o,w,e,d,id_value,def.version,digest(convert_to(def.body::text,'UTF8'),'sha256'),disposition_value,run_value,matched->'evidence',decode(matched->>'digest','hex'));
 IF disposition_value='admitted' THEN
  result_value:=zasp_temporal75.admit_body(o,w,e,d,def.version,s.source_kind,s.source_id,s.source_version,run_value,grant_value->>'principal_id',public.zasp_discovery_canonical_id(o,w,e,'security_agent_audit',run_value),public.zasp_discovery_canonical_id(o,w,e,'security_agent_correlation',run_value),true);
  IF result_value->'created' IS DISTINCT FROM 'true'::jsonb OR result_value->>'id' IS DISTINCT FROM run_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='automatic admission changed';END IF;
  INSERT INTO zasp_temporal77.cooldowns VALUES(o,w,e,d,decode(matched->>'cooldown_key','hex'),now_value,now_value+make_interval(secs=>(def.body->'trigger_rules'->>'cooldown_seconds')::integer))
   ON CONFLICT(organization_id,workspace_id,environment_id,definition_id,pattern_key) DO UPDATE SET admitted_at=EXCLUDED.admitted_at,admitted_until=EXCLUDED.admitted_until;
 END IF;
 PERFORM zasp_temporal74.authorize(o,w,e,d,def.version);
 IF zasp_temporal77.source_match(o,w,e,id_value,def.body,clock_timestamp()) IS DISTINCT FROM matched THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='automatic source changed after admission';END IF;
 RETURN jsonb_strip_nulls(jsonb_build_object('disposition',disposition_value,'run_id',run_value));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.catchup_definition(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ref jsonb:=q->'ref';o text:=ref->>'organization_id';w text:=ref->>'workspace_id';e text:=ref->>'environment_id';d text:=ref->>'definition_id';after_value text:=q->>'after';
 def public.zasp_security_agent_definitions%ROWTYPE;configuration_value zasp_temporal75.configuration%ROWTYPE;item record;result_value jsonb;table_value text;event_value text;
 scanned_value integer:=0;admitted_value integer:=0;retry_value boolean:=false;
BEGIN
 PERFORM zasp_temporal77.require_executor();
 IF NOT COALESCE(zasp_sa_multistep_prior.closed(q,ARRAY['ref','revision','after']) AND zasp_sa_multistep_prior.closed(ref,ARRAY['organization_id','workspace_id','environment_id','definition_id'])
 AND public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(d)
 AND jsonb_typeof(q->'after')='string' AND (after_value='' OR public.zasp_valid_product_id(after_value))
 AND jsonb_typeof(q->'revision')='number' AND q->>'revision'~'^[1-9][0-9]{0,6}$' AND (q->>'revision')::bigint<=1000000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic catch-up page rejected';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('test-selector75-configuration',0));
 SELECT * INTO configuration_value FROM zasp_temporal75.configuration ORDER BY revision DESC LIMIT 1;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='automatic catch-up configuration missing';END IF;
 SELECT * INTO def FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic catch-up definition scope denied';END IF;
 IF NOT configuration_value.enabled OR configuration_value.revision<>(q->>'revision')::bigint OR def.deleted_at IS NOT NULL OR def.activation NOT IN('supervised','autonomous')
 OR def.body->'enabled' IS DISTINCT FROM 'true'::jsonb OR def.body->'trigger_rules'->>'mode' IS DISTINCT FROM 'automatic' THEN
  RETURN jsonb_build_object('after',after_value,'more',false,'retry',false,'scanned',0,'admitted',0);
 END IF;
 IF NOT zasp_temporal77.rules_valid(def.body) OR NOT zasp_temporal77.rules_capable(def.body) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic catch-up adapter unavailable';END IF;
 table_value:=CASE def.body->>'trigger_kind' WHEN 'finding' THEN 'zasp_risk_findings' WHEN 'attack_path' THEN 'zasp_risk_attack_paths' END;
 IF table_value IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic catch-up source adapter unavailable';END IF;
 FOR item IN EXECUTE format('SELECT id,version,updated_at FROM public.%I WHERE(organization_id,workspace_id,environment_id)=($1,$2,$3) AND id>$4 ORDER BY id LIMIT 5',table_value) USING o,w,e,after_value LOOP
  scanned_value:=scanned_value+1;after_value:=item.id;
  PERFORM zasp_temporal77.put_source(o,w,e,def.body->>'trigger_kind',item.id,item.version,item.updated_at);
  event_value:=public.zasp_discovery_canonical_id(o,w,e,'automatic_source_v1',concat_ws(chr(31),def.body->>'trigger_kind',item.id,item.version));
  BEGIN
   result_value:=zasp_temporal77.admit_occurrence(jsonb_build_object('ref',ref,'revision',configuration_value.revision,'event_id',event_value));
   IF result_value->>'disposition'='admitted' THEN admitted_value:=admitted_value+1;END IF;
  EXCEPTION
   WHEN SQLSTATE '40001' OR SQLSTATE '55P03' THEN retry_value:=true;
   WHEN SQLSTATE '42501' THEN NULL;
  END;
 END LOOP;
 RETURN jsonb_build_object('after',after_value,'more',scanned_value=5,'retry',retry_value,'scanned',scanned_value,'admitted',admitted_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.desired(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;body_value jsonb;BEGIN
 PERFORM zasp_temporal77.require_executor();
 result_value:=zasp_temporal75.desired(q);
 SELECT body INTO body_value FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id,definition_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'definition_id');
 IF body_value ? 'trigger_rules' THEN
  result_value:=result_value||jsonb_build_object('automatic',true,'enabled',(result_value->>'enabled')::boolean AND body_value->'trigger_rules'->>'mode'='automatic' AND zasp_temporal77.rules_valid(body_value) AND zasp_temporal77.rules_capable(body_value));
 END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal77.dispatch_page(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';event_value text:=q->>'event_id';after_value text:=q->>'after';
 source_value zasp_temporal77.source_events%ROWTYPE;configuration_value zasp_temporal75.configuration%ROWTYPE;item record;result_value jsonb;
 scanned_value integer:=0;admitted_value integer:=0;retry_value boolean:=false;
BEGIN
 PERFORM zasp_temporal77.require_executor();
 IF NOT COALESCE(zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','event_id','after'])
 AND public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(event_value)
 AND jsonb_typeof(q->'after')='string' AND (after_value='' OR public.zasp_valid_product_id(after_value)),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic definition page rejected';END IF;
 SELECT * INTO source_value FROM zasp_temporal77.source_events WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,event_value);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic page source scope denied';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('test-selector75-configuration',0));
 SELECT * INTO configuration_value FROM zasp_temporal75.configuration ORDER BY revision DESC LIMIT 1;
 IF NOT FOUND OR NOT configuration_value.enabled THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='automatic dispatcher paused';END IF;
 FOR item IN SELECT definition_id FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id)=(o,w,e)
  AND definition_id>after_value AND body ? 'trigger_rules' AND body->>'trigger_kind'=source_value.source_kind ORDER BY definition_id LIMIT 5 LOOP
  scanned_value:=scanned_value+1;after_value:=item.definition_id;
  BEGIN
   result_value:=zasp_temporal77.admit_occurrence(jsonb_build_object('ref',jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'definition_id',item.definition_id),'revision',configuration_value.revision,'event_id',event_value));
   IF result_value->>'disposition'='admitted' THEN admitted_value:=admitted_value+1;END IF;
  EXCEPTION
   WHEN SQLSTATE '40001' OR SQLSTATE '55P03' THEN retry_value:=true;
   -- Current grant/definition revocation fails closed without consuming an
   -- occurrence. Later activation is handled by current-source catch-up.
   WHEN SQLSTATE '42501' THEN NULL;
  END;
 END LOOP;
 RETURN jsonb_build_object('after',after_value,'more',scanned_value=5,'retry',retry_value,'scanned',scanned_value,'admitted',admitted_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_authorization79.capture()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE prior text;next_org text;org text;old_value jsonb;new_value jsonb;columns text[];
BEGIN
 old_value:=CASE WHEN TG_OP<>'INSERT' THEN to_jsonb(OLD) END;new_value:=CASE WHEN TG_OP<>'DELETE' THEN to_jsonb(NEW) END;
 -- Ignore unrelated payload/status updates. Every permission-affecting column
 -- is listed in the trigger installation below, including raw SQL write paths.
 columns:=string_to_array(TG_ARGV[1],',');
 IF TG_OP='UPDATE' AND (SELECT jsonb_object_agg(k,old_value->k) FROM unnest(columns) k) IS NOT DISTINCT FROM (SELECT jsonb_object_agg(k,new_value->k) FROM unnest(columns) k) THEN RETURN NEW;END IF;
 prior:=old_value->>TG_ARGV[0];next_org:=new_value->>TG_ARGV[0];
 FOR org IN SELECT DISTINCT x FROM unnest(ARRAY[prior,next_org]) x WHERE x IS NOT NULL ORDER BY x LOOP PERFORM zasp_authorization79.touch(org);END LOOP;
 -- Row triggers do not precede PostgreSQL tuple locks. A lock inversion must
 -- abort the whole caller transaction; callers restart at a fresh Check.
 IF TG_OP='DELETE' THEN RETURN OLD;END IF;RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_execution_record_public_mutation(organization_value text, workspace_value text, environment_value text, principal_value text, operation_value text, idempotency_value text, intent_value jsonb, body_value jsonb, resource_kind_value text, resource_value text, version_value bigint, audit_value text, correlation_value text, receipt_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE response jsonb;
BEGIN
 IF operation_value NOT IN('syncIntegration','putIntegrationSchedule','deleteIntegrationSchedule') OR resource_kind_value NOT IN('integration_sync','integration_schedule')
    OR NOT zasp_valid_product_id(principal_value) OR NOT zasp_valid_product_id(resource_value) OR NOT zasp_valid_product_id(audit_value)
    OR NOT zasp_valid_product_id(correlation_value) OR (receipt_value<>'' AND NOT zasp_valid_product_id(receipt_value)) OR length(idempotency_value) NOT BETWEEN 16 AND 128
    OR jsonb_typeof(intent_value)<>'object' OR jsonb_typeof(body_value)<>'object' OR version_value<1 THEN
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid public execution mutation';
 END IF;
 response:=jsonb_build_object('body',body_value,'version',version_value,'audit_id',audit_value,'correlation_id',correlation_value,'receipt_id',receipt_value,'replayed',false);
 INSERT INTO zasp_workflow_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,principal_id,operation,resource_kind,resource_id,resource_version)
 VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,principal_value,operation_value,resource_kind_value,resource_value,version_value);
 INSERT INTO zasp_workflow_idempotency(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,request_digest,response)
 VALUES(organization_value,workspace_value,environment_value,principal_value,operation_value,idempotency_value,digest(convert_to(intent_value::text,'UTF8'),'sha256'),response-'replayed');
 IF receipt_value<>'' THEN
   INSERT INTO zasp_workflow_receipts(organization_id,workspace_id,environment_id,principal_id,receipt_id,operation,idempotency_key,intent,result,resource_kind,resource_id,resource_version,audit_id,correlation_id)
   VALUES(organization_value,workspace_value,environment_value,principal_value,receipt_value,operation_value,idempotency_value,intent_value,body_value,resource_kind_value,resource_value,version_value,audit_value,correlation_value);
 END IF;
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.api(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;actor text;op text;k text;keys text[];d public.zasp_security_agent_definitions%ROWTYPE;
 prior public.zasp_security_agent_request_receipts%ROWTYPE;r text;a text;receipt_id text;evidence jsonb;result_value jsonb;audit_body jsonb;items jsonb:='[]';item record;next_value text;
 inner_q jsonb;inner_result jsonb;resource_value jsonb;was_replay boolean;approval_row public.zasp_security_agent_approvals%ROWTYPE;run_row public.zasp_security_agent_runs%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='public ordered requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 PERFORM 1 FROM zasp_ordered_public62.registration FOR SHARE;
 IF NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered principal rejected';END IF;
 IF NOT COALESCE(zasp_ordered_public62.ready(c,f),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public ordered release unavailable';END IF;
 IF q IS NULL OR octet_length(q::text)>16384 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered request rejected';END IF;
 IF q->>'operation'='deployment_ready' THEN
  IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['operation']) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered deployment request rejected';END IF;
  IF NOT COALESCE(zasp_ordered_public62.ready(c,f),false) OR NOT COALESCE(public.zasp_security_agent_principal_ready('zasp_security_agent_api'),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='public ordered deployment unavailable';END IF;
  RETURN jsonb_build_object('contract_version',62,'ready',true);
 END IF;
 op:=q->>'operation';keys:=ARRAY['organization_id','workspace_id','environment_id','actor_id','operation'];
 CASE op WHEN 'ready' THEN NULL; WHEN 'activate' THEN keys:=keys||ARRAY['definition_id','definition_version'];
 WHEN 'resource_activation' THEN keys:=keys||ARRAY['definition_id'];
 WHEN 'classify_mutation' THEN keys:=keys||ARRAY['mutation_kind','definition_id','idempotency_key'];IF q->>'mutation_kind'='trigger' THEN keys:=keys||ARRAY['trigger'];END IF;
 WHEN 'classify_trigger_key' THEN keys:=keys||ARRAY['definition_id','idempotency_key'];
 WHEN 'activate_resource' THEN keys:=keys||ARRAY['definition_id','definition_version','activation','idempotency_key'];
 WHEN 'trigger_resource' THEN keys:=keys||ARRAY['definition_id','definition_version','trigger_id','trigger_version','trigger_kind','trigger_source','idempotency_key'];
 WHEN 'resource_run' THEN keys:=keys||ARRAY['run_id'];
 WHEN 'resource_approval' THEN keys:=keys||ARRAY['approval_id'];
 WHEN 'decide_resource' THEN keys:=keys||ARRAY['approval_id','approval_version','decision','fresh_auth_at','idempotency_key'];
 WHEN 'trigger' THEN keys:=keys||ARRAY['definition_id','definition_version','trigger_id','trigger_version','idempotency_key'];
 WHEN 'decide' THEN keys:=keys||ARRAY['run_id','run_version','approval_id','approval_version','decision','fresh_auth_at','idempotency_key'];
 WHEN 'cancel' THEN keys:=keys||ARRAY['run_id','run_version','idempotency_key'];
 WHEN 'detail' THEN keys:=keys||ARRAY['run_id'];
 WHEN 'classify' THEN keys:=keys||ARRAY['resource_kind','resource_id'];
 WHEN 'list' THEN keys:=keys||ARRAY['limit','after_run_id'];
 WHEN 'run_candidates','approval_candidates' THEN keys:=keys||ARRAY['resource_filter','state_filter','limit','before_created_at','before_id'];
 ELSE RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered operation rejected';END CASE;
 IF NOT zasp_sa_multistep_prior.closed(q,keys) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','actor_id','definition_id','trigger_id','run_id','approval_id','resource_id'] LOOP
  IF q ? k AND (jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered identity rejected';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['definition_version','trigger_version','run_version','approval_version'] LOOP
  IF q ? k AND (jsonb_typeof(q->k) IS DISTINCT FROM 'number' OR (q->>k)!~'^([1-9][0-9]{0,5}|1000000)$') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered version rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';actor:=q->>'actor_id';
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 PERFORM zasp_ordered_public62.authorize(o,w,e,actor,op IN('activate','trigger','decide','cancel','activate_resource','trigger_resource','decide_resource'));
 IF op='ready' THEN result_value:=jsonb_build_object('contract_version',62,'ready',true);
 ELSIF op IN('run_candidates','approval_candidates') THEN result_value:=zasp_ordered_public62.candidates(q);
 ELSIF op='resource_activation' THEN
  IF zasp_ordered_public62.classify(o,w,e,'definition',q->>'definition_id')<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO d FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,q->>'definition_id');
  result_value:=jsonb_build_object('contract_version',62,'id',d.definition_id,'activation',d.activation,'enabled',d.body->'enabled','version',d.version);
 ELSIF op='classify_trigger_key' THEN
  IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered trigger classification rejected';END IF;
  result_value:=jsonb_build_object('contract_version',62,'definition_id',q->>'definition_id','idempotency_key',q->>'idempotency_key','family',zasp_ordered_public62.classify_trigger_key(o,w,e,actor,q->>'definition_id',q->>'idempotency_key'));
 ELSIF op='classify_mutation' THEN
  IF jsonb_typeof(q->'mutation_kind') IS DISTINCT FROM 'string' OR q->>'mutation_kind' NOT IN('activate','trigger') OR jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]{15,127}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation classification rejected';END IF;
  IF q->>'mutation_kind'='trigger' THEN
   IF NOT zasp_sa_multistep_prior.closed(q->'trigger',ARRAY['trigger_id','trigger_version']) OR jsonb_typeof(q->'trigger'->'trigger_id') IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->'trigger'->>'trigger_id'),false) OR jsonb_typeof(q->'trigger'->'trigger_version') IS DISTINCT FROM 'number' OR NOT COALESCE(q->'trigger'->>'trigger_version'~'^([1-9][0-9]{0,5}|1000000)$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation trigger identity rejected';END IF;
  END IF;
  result_value:=jsonb_build_object('contract_version',62,'mutation_kind',q->>'mutation_kind','definition_id',q->>'definition_id','idempotency_key',q->>'idempotency_key','trigger',q->'trigger','family',zasp_ordered_public62.classify_mutation(o,w,e,actor,q->>'mutation_kind',q->>'definition_id',q->>'idempotency_key',q->'trigger'->>'trigger_id',(q->'trigger'->>'trigger_version')::bigint));
 ELSIF op='activate_resource' THEN
  IF zasp_ordered_public62.classify_mutation(o,w,e,actor,'activate',q->>'definition_id',q->>'idempotency_key',NULL,NULL)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  result_value:=zasp_ordered_public62.activate_resource(c,f,q);
 ELSIF op='resource_run' THEN result_value:=zasp_ordered_public62.resource_run(o,w,e,q->>'run_id');
 ELSIF op='resource_approval' THEN
  IF zasp_ordered_public62.classify(o,w,e,'approval',q->>'approval_id')<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO approval_row FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,approval_id)=(o,w,e,q->>'approval_id');
  result_value:=zasp_ordered_public62.resource_run(o,w,e,approval_row.run_id);
 ELSIF op='trigger_resource' THEN
  IF zasp_ordered_public62.classify_mutation(o,w,e,actor,'trigger',q->>'definition_id',q->>'idempotency_key',q->>'trigger_id',(q->>'trigger_version')::bigint)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key') FOR SHARE;
  was_replay:=FOUND;
  SELECT definition INTO evidence FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint) FOR SHARE;
  IF jsonb_typeof(q->'trigger_kind') IS DISTINCT FROM 'string' OR jsonb_typeof(q->'trigger_source') IS DISTINCT FROM 'string' OR q->'trigger_kind' IS DISTINCT FROM evidence->'trigger_kind' OR q->'trigger_source' IS DISTINCT FROM evidence->'trigger_source' THEN
   IF was_replay THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
   RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered trigger rejected';END IF;
  inner_q:=(q-'trigger_kind'-'trigger_source')||jsonb_build_object('operation','trigger');
  inner_result:=zasp_ordered_public62.api(c,f,inner_q);r:=inner_result->>'run_id';
  IF zasp_ordered_public62.classify(o,w,e,'run',r)<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger unavailable';END IF;
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key');
  result_value:=jsonb_build_object('contract_version',62,'id',r,'agent_id',inner_result->>'definition_id','definition_version',inner_result->'definition_version','state',inner_result->>'state','version',inner_result->'version','evidence_ids',jsonb_build_array(q->>'trigger_id'),'audit_id',prior.audit_id,'correlation_id',prior.correlation_id,'receipt_id',prior.receipt_id,'replayed',was_replay);
 ELSIF op='decide_resource' THEN
  IF zasp_ordered_public62.classify(o,w,e,'approval',q->>'approval_id')<>'ordered_release61' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
  SELECT * INTO approval_row FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,approval_id)=(o,w,e,q->>'approval_id');
  SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,approval_row.run_id);
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'decideSecurityAgentApproval',q->>'idempotency_key') FOR SHARE;
  inner_q:=q||jsonb_build_object('operation','decide','run_id',approval_row.run_id,'run_version',CASE WHEN prior.receipt_id IS NULL THEN run_row.version ELSE prior.expected_version END);
  inner_result:=zasp_ordered_public62.api(c,f,inner_q);
  result_value:=jsonb_build_object('mutation',inner_result,'resource',zasp_ordered_public62.resource_run(o,w,e,approval_row.run_id));
 ELSIF op='classify' THEN
  IF jsonb_typeof(q->'resource_kind') IS DISTINCT FROM 'string' OR q->>'resource_kind' NOT IN('definition','run','approval') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered resource kind rejected';END IF;
  result_value:=jsonb_build_object('contract_version',62,'resource_kind',q->>'resource_kind','resource_id',q->>'resource_id','family',zasp_ordered_public62.classify(o,w,e,q->>'resource_kind',q->>'resource_id'));
 ELSIF op IN('decide','cancel') THEN result_value:=zasp_ordered_public62.mutate(c,f,q);
 ELSIF op='detail' THEN result_value:=zasp_ordered_public62.project(o,w,e,q->>'run_id');
 ELSIF op='list' THEN
  IF jsonb_typeof(q->'limit') IS DISTINCT FROM 'number' OR (q->>'limit')!~'^([1-9]|10)$' OR jsonb_typeof(q->'after_run_id') IS DISTINCT FROM 'string'
   OR q->>'after_run_id'<>'' AND NOT COALESCE(public.zasp_valid_product_id(q->>'after_run_id'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered page rejected';END IF;
  FOR item IN SELECT x.run_id FROM public.zasp_security_agent_runs x JOIN public.zasp_security_agent_definitions definition_item USING(organization_id,workspace_id,environment_id,definition_id)
   LEFT JOIN public.zasp_security_agent_definition_versions historical ON (historical.organization_id,historical.workspace_id,historical.environment_id,historical.definition_id,historical.version)=(x.organization_id,x.workspace_id,x.environment_id,x.definition_id,x.definition_version)
   WHERE (x.organization_id,x.workspace_id,x.environment_id)=(o,w,e) AND x.run_id>q->>'after_run_id' AND (definition_item.body->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb OR historical.definition->'allowed_actions'='["create_temporary_policy","run_test"]'::jsonb
    OR EXISTS(SELECT 1 FROM public.zasp_security_agent_audit a WHERE (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.event_kind)=(o,w,e,x.run_id,'ordered_public_triggered'))) ORDER BY x.run_id LIMIT (q->>'limit')::integer+1 LOOP
   PERFORM zasp_ordered_public62.history(o,w,e,item.run_id);
   IF jsonb_array_length(items)=(q->>'limit')::integer THEN next_value:=items->-1->>'run_id';EXIT;END IF;
   items:=items||jsonb_build_array(zasp_ordered_public62.project(o,w,e,item.run_id));
  END LOOP;
  result_value:=jsonb_build_object('contract_version',62,'items',items,'next_after_run_id',next_value);
 ELSIF op='activate' THEN
  PERFORM 1 FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,q->>'definition_id') FOR UPDATE;
  d:=zasp_ordered_public62.definition(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint,false);
  IF d.version>=1000000 OR NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered activation changed';END IF;
  UPDATE public.zasp_security_agent_definitions SET activation='supervised',version=version+1,body=body||jsonb_build_object('enabled',true),updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d.definition_id) RETURNING * INTO d;
  INSERT INTO public.zasp_security_agent_definition_versions(organization_id,workspace_id,environment_id,definition_id,version,activation,definition,definition_digest,actor_id) VALUES(o,w,e,d.definition_id,d.version,'supervised',d.body,digest(convert_to(d.body::text,'UTF8'),'sha256'),actor);
  result_value:=jsonb_build_object('contract_version',62,'definition_id',d.definition_id,'definition_version',d.version,'activation','supervised');
  a:=public.zasp_discovery_canonical_id(o,w,e,'public62_activation',d.definition_id||chr(31)||d.version::text);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,a,a,actor,'ordered_public_activated',digest(convert_to(result_value::text,'UTF8'),'sha256'),result_value);
 ELSE
  IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR length(q->>'idempotency_key') NOT BETWEEN 16 AND 128 OR (q->>'idempotency_key')!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered idempotency rejected';END IF;
  SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key') FOR SHARE;
  IF FOUND THEN
   IF prior.intent IS DISTINCT FROM q OR prior.intent_digest IS DISTINCT FROM digest(convert_to(q::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
   IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,requested_by)=(o,w,e,prior.resource_id,q->>'definition_id',(q->>'definition_version')::bigint,actor)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered replay unavailable';END IF;
   r:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',(q->>'definition_id')||chr(31)||(q->>'trigger_id')||chr(31)||(q->>'trigger_version'));
   result_value:=jsonb_build_object('contract_version',62,'run_id',r,'definition_id',q->>'definition_id','definition_version',(q->>'definition_version')::bigint,'state','queued','version',1);
   IF prior.resource_id IS DISTINCT FROM r OR prior.expected_version IS DISTINCT FROM (q->>'definition_version')::bigint OR prior.response IS DISTINCT FROM result_value
    OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_audit history JOIN public.zasp_security_agent_trigger_receipts tr USING(organization_id,workspace_id,environment_id,run_id)
     JOIN public.zasp_security_agent_definition_versions versioned ON (versioned.organization_id,versioned.workspace_id,versioned.environment_id,versioned.definition_id,versioned.version)=(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint)
     WHERE (history.organization_id,history.workspace_id,history.environment_id,history.run_id,history.actor_id,history.event_kind)=(o,w,e,r,actor,'ordered_public_triggered')
      AND history.audit_id=prior.audit_id AND history.body->'request'=q AND history.body->'response'=result_value AND history.event_digest=digest(convert_to(history.body::text,'UTF8'),'sha256')
      AND history.body->'trigger_digest'=to_jsonb(encode(tr.trigger_digest,'hex')) AND tr.trigger_version=(q->>'trigger_version')::bigint AND tr.trigger_id=q->>'trigger_id'
      AND history.body->'existing_test'=versioned.definition->'existing_test' AND versioned.definition_digest=digest(convert_to(versioned.definition::text,'UTF8'),'sha256')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered replay authority changed';END IF;
  ELSE
   d:=zasp_ordered_public62.definition(o,w,e,q->>'definition_id',(q->>'definition_version')::bigint,true);
   IF d.body->>'trigger_kind'='finding' THEN SELECT to_jsonb(x) INTO evidence FROM public.zasp_risk_findings x WHERE (organization_id,workspace_id,environment_id,id,version,status,rule)=(o,w,e,q->>'trigger_id',(q->>'trigger_version')::bigint,'open',d.body->>'trigger_source') FOR SHARE;
   ELSE SELECT to_jsonb(x) INTO evidence FROM public.zasp_risk_attack_paths x WHERE (organization_id,workspace_id,environment_id,id,version,state)=(o,w,e,q->>'trigger_id',(q->>'trigger_version')::bigint,d.body->>'trigger_source') AND state IN('observed','verified') AND public.zasp_risk_attack_path_valid(x) FOR SHARE;END IF;
   IF evidence IS NULL OR octet_length(evidence::text)>65536 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
   r:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',d.definition_id||chr(31)||(q->>'trigger_id')||chr(31)||(q->>'trigger_version'));
   a:=public.zasp_discovery_canonical_id(o,w,e,'public62_trigger',r);receipt_id:=public.zasp_discovery_canonical_id(o,w,e,'public62_receipt',actor||chr(31)||(q->>'idempotency_key'));
   IF NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered trigger changed';END IF;
   INSERT INTO public.zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(o,w,e,r,d.definition_id,d.version,q->>'trigger_id',actor,'queued');
   INSERT INTO public.zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(o,w,e,d.definition_id,q->>'trigger_id',d.body->>'trigger_kind',(q->>'trigger_version')::bigint,digest(convert_to(evidence::text,'UTF8'),'sha256'),r);
   PERFORM zasp_sa_multistep_prior.context(o,w,e,r);
   result_value:=jsonb_build_object('contract_version',62,'run_id',r,'definition_id',d.definition_id,'definition_version',d.version,'state','queued','version',1);
   audit_body:=jsonb_build_object('request',q,'response',result_value,'trigger_digest',encode(digest(convert_to(evidence::text,'UTF8'),'sha256'),'hex'),'existing_test',d.body->'existing_test','definition_digest',encode(digest(convert_to(d.body::text,'UTF8'),'sha256'),'hex'));
   INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,a,a,r,actor,'ordered_public_triggered',digest(convert_to(audit_body::text,'UTF8'),'sha256'),audit_body);
   INSERT INTO public.zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(o,w,e,actor,'runSecurityAgent',q->>'idempotency_key',r,d.version,q,digest(convert_to(q::text,'UTF8'),'sha256'),result_value,a,a,receipt_id);
  END IF;
 END IF;
 IF op='trigger' THEN PERFORM zasp_ordered_public62.history(o,w,e,r);END IF;
 IF result_value IS NULL OR octet_length(result_value::text)>65536 OR NOT zasp_ordered_public62.ready(c,f) OR NOT public.zasp_security_agent_principal_ready('zasp_security_agent_api') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered authority changed';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_ordered_public62.mutate(c text, f text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';actor text:=q->>'actor_id';r text:=q->>'run_id';op text:=q->>'operation';
 operation_value text;fresh timestamptz;rr public.zasp_security_agent_runs%ROWTYPE;s public.zasp_security_agent_steps%ROWTYPE;approval public.zasp_security_agent_approvals%ROWTYPE;
 prior public.zasp_security_agent_request_receipts%ROWTYPE;audit_row public.zasp_security_agent_audit%ROWTYPE;transition_row public.zasp_security_agent_audit%ROWTYPE;decision_row public.zasp_security_agent_audit%ROWTYPE;
 audit_id_value text;receipt_id_value text;transition_id text;transition_q jsonb;transition_result jsonb;result_value jsonb;body_value jsonb;projection jsonb;
 admitted boolean;cleanup_value boolean;replayed boolean:=false;keys text[];expected_step_version bigint;phase_value text;expected_phase text;decision_id text;
BEGIN
 IF jsonb_typeof(q->'idempotency_key') IS DISTINCT FROM 'string' OR length(q->>'idempotency_key') NOT BETWEEN 16 AND 128 OR q->>'idempotency_key'!~'^[A-Za-z0-9][A-Za-z0-9._:-]*$'
  OR (q->>'run_version')::bigint>=1000000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered mutation rejected';END IF;
 IF op='decide' THEN
  IF jsonb_typeof(q->'decision') IS DISTINCT FROM 'string' OR q->>'decision' NOT IN('approved','rejected') OR jsonb_typeof(q->'fresh_auth_at') IS DISTINCT FROM 'string'
   OR length(q->>'fresh_auth_at') NOT BETWEEN 20 AND 35 OR q->>'fresh_auth_at'!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}(\.[0-9]{1,9})?Z$' OR (q->>'approval_version')::bigint>=1000000 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='public ordered decision rejected';END IF;
  fresh:=(q->>'fresh_auth_at')::timestamptz;
  IF fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds' THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered decision unavailable';END IF;
 END IF;
 operation_value:=CASE op WHEN 'decide' THEN 'decideSecurityAgentApproval' ELSE 'cancelSecurityAgentRun' END;
 -- Organization admission precedes budget/run, exactly as the private worker.
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 PERFORM 1 FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='public ordered object unavailable';END IF;
 admitted:=EXISTS(SELECT 1 FROM public.zasp_sa_multistep_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r));
 IF admitted THEN PERFORM zasp_sa_multistep_prior.cleanup_lock(o,w,e,r);END IF;
 IF admitted AND op='cancel' THEN
  -- Cancellation must remain possible after gateway revocation or expiry.
  -- Validate retained authority here; validate terminal cleanup evidence after
  -- the reviewed transition creates its blocking audit, never live permission.
  PERFORM zasp_sa_multistep_prior.transition_current(o,w,e,r,false);
  PERFORM zasp_ordered_public62.history(o,w,e,r);
 ELSE projection:=zasp_ordered_public62.project(o,w,e,r);END IF;
 audit_id_value:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_audit',actor||chr(31)||op||chr(31)||(q->>'idempotency_key'));
 receipt_id_value:=public.zasp_discovery_canonical_id(o,w,e,'public62_mutation_receipt',actor||chr(31)||op||chr(31)||(q->>'idempotency_key'));
 SELECT * INTO prior FROM public.zasp_security_agent_request_receipts WHERE (organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key)=(o,w,e,actor,operation_value,q->>'idempotency_key') FOR SHARE;
 IF FOUND THEN
  IF prior.intent IS DISTINCT FROM q OR prior.intent_digest IS DISTINCT FROM digest(convert_to(q::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='public ordered replay conflict';END IF;
  SELECT * INTO audit_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,audit_id_value) FOR SHARE;
  result_value:=prior.response;body_value:=audit_row.body;transition_id:=body_value->>'transition_audit_id';
  IF (prior.resource_id,prior.expected_version,prior.audit_id,prior.correlation_id,prior.receipt_id) IS DISTINCT FROM (r,(q->>'run_version')::bigint,audit_id_value,audit_id_value,receipt_id_value)
   OR (audit_row.run_id,audit_row.actor_id,audit_row.event_kind,audit_row.correlation_id) IS DISTINCT FROM (r,actor,'ordered_public_'||op,audit_id_value)
   OR NOT zasp_sa_multistep_prior.closed(body_value||jsonb_build_object('transition_audit_id',COALESCE(transition_id,''),'transition_digest',COALESCE(body_value->>'transition_digest','')),ARRAY['request','response','transition_audit_id','transition_digest']) OR NOT body_value ?& ARRAY['transition_audit_id','transition_digest'] OR body_value->'request' IS DISTINCT FROM q OR body_value->'response' IS DISTINCT FROM result_value
   OR audit_row.event_digest IS DISTINCT FROM digest(convert_to(body_value::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation history unavailable';END IF;
  replayed:=true;
 ELSE
  IF rr.version<>(q->>'run_version')::bigint OR rr.completed_at IS NOT NULL OR rr.state NOT IN('queued','planning','waiting_approval','running','verifying') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation state changed';END IF;
  IF op='decide' THEN
   IF NOT admitted OR rr.state<>'waiting_approval' OR actor=rr.requested_by THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,state)=(o,w,e,r,'waiting_approval') ORDER BY step_index LIMIT 1;
   SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
   IF approval.approval_id IS DISTINCT FROM q->>'approval_id' OR approval.state IS DISTINCT FROM 'pending' OR approval.version IS DISTINCT FROM (q->>'approval_version')::bigint OR s.version>=1000000
    OR approval.approver_id IS NOT NULL OR approval.decided_at IS NOT NULL OR approval.fresh_auth_at IS NOT NULL OR approval.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered approval unavailable';END IF;
  ELSIF admitted THEN
   -- Before the application receipt step zero owns cancellation. Once it is
   -- complete the canonical successor owns it, including the between-step gap.
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) AND step_index=CASE WHEN EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_index,state)=(o,w,e,r,0,'succeeded')) THEN 1 ELSE 0 END;
  END IF;
  PERFORM zasp_ordered_public62.history(o,w,e,r);
  IF NOT zasp_ordered_public62.ready(c,f) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation authority changed';END IF;
  IF admitted THEN
   IF s.step_id IS NULL OR s.version>=1000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered current step unavailable';END IF;
   IF op='cancel' THEN SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);END IF;
   phase_value:=CASE s.state WHEN 'queued' THEN 'queued' WHEN 'waiting_approval' THEN 'pending-approval' WHEN 'authorized' THEN 'authorized' WHEN 'executing' THEN 'executing' END;
   -- The immutable cancel request retains positive pre-transition approval
   -- authority: pending=1, previously approved=2, no approval=1. Never infer
   -- a pending phase merely from missing prior decision evidence.
   transition_q:=jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'actor_id',actor,'run_id',r,'step_id',s.step_id,'operation',CASE WHEN op='cancel' THEN 'cancel' WHEN q->>'decision'='approved' THEN 'approve' ELSE 'reject' END,'run_version',rr.version,'approval_version',COALESCE(approval.version,1),'fresh_auth_at',CASE WHEN op='decide' THEN q->>'fresh_auth_at' ELSE to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END);
   transition_result:=zasp_temporal67.api_transition('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',transition_q);
   transition_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||CASE WHEN op='cancel' THEN 'ordered_run_cancelled' ELSE 'ordered_approval_decided' END);
   SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
  ELSE
   IF op<>'cancel' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered admission absent';END IF;
   phase_value:='before-admission';
   -- Preserve all planner/provider accounting evidence. needs_human remains
   -- eligible for release61 expired-lease recovery; cancelled would strand it.
   PERFORM 1 FROM zasp_sa_multistep_prior.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
   UPDATE public.zasp_security_agent_runs SET state=CASE WHEN state='queued' THEN 'cancelled' ELSE 'needs_human' END,version=version+1,completed_at=clock_timestamp(),updated_at=clock_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_error_code='public_cancel_requested' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  END IF;
  SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  cleanup_value:=EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,action_key)=(o,w,e,r,'create_temporary_policy') AND state<>'cleaned');
  result_value:=jsonb_build_object('contract_version',62,'organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'run_state',rr.state,'run_version',rr.version,'step_id',s.step_id,'step_state',s.state,'step_version',COALESCE(s.version,0),'audit_id',audit_id_value,'receipt_id',receipt_id_value,'replayed',false);
  IF op='decide' THEN result_value:=result_value||jsonb_build_object('approval_id',approval.approval_id,'approval_version',approval.version+1,'decision',q->>'decision','outcome',CASE WHEN q->>'decision'='approved' THEN 'approved' ELSE 'blocked' END);
  ELSE result_value:=result_value||jsonb_build_object('cleanup_required',cleanup_value,'cancellation_phase',phase_value,'outcome','cancelled-request');END IF;
  SELECT * INTO transition_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,transition_id);
  body_value:=jsonb_build_object('request',q,'response',result_value,'transition_audit_id',transition_id,'transition_digest',CASE WHEN transition_id IS NOT NULL THEN encode(digest(convert_to(transition_row.body::text,'UTF8'),'sha256'),'hex') END);
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,approval_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_id_value,audit_id_value,r,s.step_id,approval.approval_id,actor,'ordered_public_'||op,digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
  INSERT INTO public.zasp_security_agent_request_receipts(organization_id,workspace_id,environment_id,principal_id,operation,idempotency_key,resource_id,expected_version,intent,intent_digest,response,audit_id,correlation_id,receipt_id) VALUES(o,w,e,actor,operation_value,q->>'idempotency_key',r,(q->>'run_version')::bigint,q,digest(convert_to(q::text,'UTF8'),'sha256'),result_value,audit_id_value,audit_id_value,receipt_id_value);
 END IF;
 keys:=ARRAY['contract_version','organization_id','workspace_id','environment_id','run_id','run_state','run_version','step_id','step_state','step_version','audit_id','receipt_id','replayed','outcome'];
 IF op='decide' THEN keys:=keys||ARRAY['approval_id','approval_version','decision'];ELSE keys:=keys||ARRAY['cleanup_required','cancellation_phase'];END IF;
 IF NOT zasp_sa_multistep_prior.closed(CASE WHEN admitted THEN result_value ELSE result_value||jsonb_build_object('step_id','','step_state','') END,keys) OR NOT result_value ?& keys OR octet_length(result_value::text)>4096
  OR result_value->'contract_version' IS DISTINCT FROM '62'::jsonb OR result_value->>'organization_id' IS DISTINCT FROM o OR result_value->>'workspace_id' IS DISTINCT FROM w OR result_value->>'environment_id' IS DISTINCT FROM e OR result_value->>'run_id' IS DISTINCT FROM r
  OR result_value->'run_version' IS DISTINCT FROM to_jsonb((q->>'run_version')::bigint+1) OR result_value->>'audit_id' IS DISTINCT FROM audit_id_value OR result_value->>'receipt_id' IS DISTINCT FROM receipt_id_value OR result_value->'replayed' IS DISTINCT FROM 'false'::jsonb
  OR op='decide' AND (result_value->>'decision' IS DISTINCT FROM q->>'decision' OR result_value->>'approval_id' IS DISTINCT FROM q->>'approval_id' OR result_value->'approval_version' IS DISTINCT FROM to_jsonb((q->>'approval_version')::bigint+1)
   OR result_value->>'run_state' IS DISTINCT FROM CASE WHEN q->>'decision'='approved' THEN 'running' ELSE 'needs_human' END OR result_value->>'step_state' IS DISTINCT FROM CASE WHEN q->>'decision'='approved' THEN 'authorized' ELSE 'cancelled' END OR result_value->>'outcome' IS DISTINCT FROM CASE WHEN q->>'decision'='approved' THEN 'approved' ELSE 'blocked' END)
  OR op='cancel' AND (result_value->>'outcome' IS DISTINCT FROM 'cancelled-request' OR result_value->>'run_state' NOT IN('cancelled','needs_human') OR jsonb_typeof(result_value->'cleanup_required') IS DISTINCT FROM 'boolean'
   OR result_value->'cleanup_required' IS DISTINCT FROM to_jsonb(EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,action_key)=(o,w,e,r,'create_temporary_policy')))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation result unavailable';END IF;
 IF transition_id IS NOT NULL THEN
  SELECT * INTO transition_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,transition_id) FOR SHARE;
  SELECT * INTO s FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,result_value->>'step_id');
  -- Derive cancellation phase from immutable private transition evidence.
  -- Approval state alone cannot distinguish pending from prior authorization.
  SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s.step_id);
  IF op='decide' THEN expected_step_version:=s.step_index+2;
  ELSE
   decision_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||'ordered_approval_decided');
   SELECT * INTO decision_row FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,audit_id)=(o,w,e,decision_id) FOR SHARE;
   IF FOUND THEN
    IF (decision_row.run_id,decision_row.step_id,decision_row.event_kind,decision_row.correlation_id) IS DISTINCT FROM (r,s.step_id,'ordered_approval_decided',decision_id)
     OR NOT zasp_sa_multistep_prior.closed(decision_row.body,ARRAY['contract_version','request','response']) OR decision_row.body->'contract_version' IS DISTINCT FROM '61'::jsonb
     OR NOT zasp_sa_multistep_prior.closed(decision_row.body->'request',ARRAY['organization_id','workspace_id','environment_id','actor_id','run_id','step_id','operation','run_version','approval_version','fresh_auth_at'])
     OR NOT zasp_sa_multistep_prior.closed(decision_row.body->'response',ARRAY['contract_version','organization_id','workspace_id','environment_id','run_id','step_id','outcome','run_state','run_version','step_state','approval_id','approval_version'])
     OR decision_row.event_digest IS DISTINCT FROM digest(convert_to((decision_row.body->'request')::text,'UTF8'),'sha256')
     OR (decision_row.body->'request'->>'organization_id',decision_row.body->'request'->>'workspace_id',decision_row.body->'request'->>'environment_id',decision_row.body->'request'->>'run_id',decision_row.body->'request'->>'step_id',decision_row.body->'request'->>'actor_id',decision_row.body->'request'->>'operation') IS DISTINCT FROM (o,w,e,r,s.step_id,decision_row.actor_id,'approve')
     OR decision_row.body->'request'->'approval_version' IS DISTINCT FROM '1'::jsonb OR jsonb_typeof(decision_row.body->'request'->'run_version') IS DISTINCT FROM 'number' OR decision_row.body->'request'->>'run_version'!~'^[1-9][0-9]{0,5}$'
     OR (decision_row.body->'response'->>'organization_id',decision_row.body->'response'->>'workspace_id',decision_row.body->'response'->>'environment_id',decision_row.body->'response'->>'run_id',decision_row.body->'response'->>'step_id',decision_row.body->'response'->>'outcome',decision_row.body->'response'->>'run_state',decision_row.body->'response'->>'step_state') IS DISTINCT FROM (o,w,e,r,s.step_id,'approved','running','authorized')
     OR decision_row.body->'response'->'contract_version' IS DISTINCT FROM '61'::jsonb OR decision_row.body->'response'->'run_version' IS DISTINCT FROM to_jsonb((decision_row.body->'request'->>'run_version')::bigint+1)
     OR decision_row.body->'response'->>'approval_id' IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_approval',r||chr(31)||s.step_id) OR decision_row.body->'response'->'approval_version' IS DISTINCT FROM '2'::jsonb
     OR decision_row.body->'response'->'approval_id' IS DISTINCT FROM transition_row.body->'response'->'approval_id' OR decision_row.body->'response'->'approval_version' IS DISTINCT FROM transition_row.body->'response'->'approval_version'
     OR approval.approval_id IS DISTINCT FROM decision_row.body->'response'->>'approval_id' OR approval.state IS DISTINCT FROM 'approved' OR approval.version IS DISTINCT FROM 2 OR approval.approver_id IS DISTINCT FROM decision_row.actor_id OR approval.fresh_auth_at IS DISTINCT FROM (decision_row.body->'request'->>'fresh_auth_at')::timestamptz
     OR approval.decided_at IS NULL OR approval.approver_id=rr.requested_by OR NOT COALESCE(public.zasp_valid_product_id(decision_row.actor_id),false)
     OR (decision_row.body->'response'->>'run_version')::bigint>(q->>'run_version')::bigint THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cancellation decision evidence unavailable';END IF;
   END IF;
   IF transition_row.body->'response'->>'step_state'='executing' AND transition_row.body->'request'->'approval_version'='2'::jsonb AND decision_row.audit_id IS NOT NULL THEN expected_phase:='executing';expected_step_version:=s.step_index+3;
   ELSIF transition_row.body->'response'->>'step_state'='cancelled' THEN
    IF s.step_index=1 AND transition_row.body->'request'->'approval_version'='1'::jsonb AND decision_row.audit_id IS NULL AND approval.approval_id IS NULL AND transition_row.body->'response'->>'approval_id'='' AND transition_row.body->'response'->'approval_version'='0'::jsonb THEN expected_phase:='queued';expected_step_version:=2;
    ELSIF transition_row.body->'response'->>'approval_id'=approval.approval_id AND approval.version=2 AND transition_row.body->'response'->'approval_version'='2'::jsonb THEN
     IF transition_row.body->'request'->'approval_version'='2'::jsonb AND decision_row.audit_id IS NOT NULL THEN expected_phase:='authorized';expected_step_version:=s.step_index+3;
     ELSIF transition_row.body->'request'->'approval_version'='1'::jsonb AND decision_row.audit_id IS NULL AND approval.state='cancelled' THEN expected_phase:='pending-approval';expected_step_version:=s.step_index+2;END IF;
    END IF;
   END IF;
   IF expected_phase IS NULL OR result_value->'cancellation_phase' IS DISTINCT FROM to_jsonb(expected_phase) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cancellation phase unavailable';END IF;
  END IF;
  IF s.step_id IS NULL OR jsonb_typeof(result_value->'step_version') IS DISTINCT FROM 'number' OR result_value->>'step_version'!~'^([1-9][0-9]{0,5}|1000000)$' OR (result_value->>'step_version')::bigint>s.version
   OR expected_step_version IS NULL OR result_value->'step_version' IS DISTINCT FROM to_jsonb(expected_step_version)
   OR transition_id IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_transition',r||chr(31)||s.step_id||chr(31)||CASE WHEN op='cancel' THEN 'ordered_run_cancelled' ELSE 'ordered_approval_decided' END)
   OR body_value->>'transition_digest' IS DISTINCT FROM encode(digest(convert_to(transition_row.body::text,'UTF8'),'sha256'),'hex')
   OR transition_row.event_digest IS DISTINCT FROM digest(convert_to((transition_row.body->'request')::text,'UTF8'),'sha256')
   OR transition_row.body->'request'->>'actor_id' IS DISTINCT FROM actor OR transition_row.body->'request'->>'run_id' IS DISTINCT FROM r OR transition_row.body->'request'->>'step_id' IS DISTINCT FROM s.step_id
   OR transition_row.body->'request'->>'operation' IS DISTINCT FROM (CASE WHEN op='cancel' THEN 'cancel' WHEN q->>'decision'='approved' THEN 'approve' ELSE 'reject' END)
   OR transition_row.body->'request'->'run_version' IS DISTINCT FROM q->'run_version'
   OR transition_row.body->'response'->'run_version' IS DISTINCT FROM result_value->'run_version' OR transition_row.body->'response'->'run_state' IS DISTINCT FROM result_value->'run_state' OR transition_row.body->'response'->'step_state' IS DISTINCT FROM result_value->'step_state'
   OR op='decide' AND (transition_row.body->'request'->'approval_version' IS DISTINCT FROM q->'approval_version' OR transition_row.body->'request'->'fresh_auth_at' IS DISTINCT FROM q->'fresh_auth_at' OR transition_row.body->'response'->'approval_id' IS DISTINCT FROM q->'approval_id' OR transition_row.body->'response'->'approval_version' IS DISTINCT FROM result_value->'approval_version') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered transition history unavailable';END IF;
 ELSE
  IF result_value->>'run_state' IS DISTINCT FROM (CASE WHEN (q->>'run_version')::bigint=1 THEN 'cancelled' ELSE 'needs_human' END) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered pre-admission state unavailable';END IF;
  IF admitted OR op<>'cancel' OR result_value->>'cancellation_phase' IS DISTINCT FROM 'before-admission' OR result_value->'step_id' IS DISTINCT FROM 'null'::jsonb OR result_value->'step_state' IS DISTINCT FROM 'null'::jsonb OR result_value->'step_version' IS DISTINCT FROM '0'::jsonb OR result_value->'cleanup_required' IS DISTINCT FROM 'false'::jsonb OR body_value->'transition_digest' IS DISTINCT FROM 'null'::jsonb THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered cancellation history unavailable';END IF;
 END IF;
 IF op='decide' THEN
  SELECT * INTO approval FROM public.zasp_security_agent_approvals WHERE (organization_id,workspace_id,environment_id,run_id,step_id,approval_id)=(o,w,e,r,result_value->>'step_id',q->>'approval_id');
  IF (approval.state,approval.version,approval.approver_id,approval.fresh_auth_at) IS DISTINCT FROM (q->>'decision',(q->>'approval_version')::bigint+1,actor,fresh)
   OR approval.requester_id=actor OR approval.decided_at IS NULL OR approval.expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered decision evidence changed';END IF;
 END IF;
 PERFORM zasp_ordered_public62.history(o,w,e,r);
 IF op='cancel' THEN PERFORM zasp_ordered_public62.project(o,w,e,r);END IF;
 IF NOT zasp_ordered_public62.ready(c,f) OR op='decide' AND (fresh<clock_timestamp()-interval '5 minutes' OR fresh>clock_timestamp()+interval '5 seconds') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='public ordered mutation expired';END IF;
 RETURN result_value||jsonb_build_object('replayed',replayed);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_policy_deployment_store_temporary_source(organization_value text, workspace_value text, environment_value text, run_value text, step_value text, phase_value text, worker_value text, lease_token_value text, device_value text, credential_value text, sequence_value bigint, policy_version_value bigint, key_value text, issued_value timestamp with time zone, expires_value timestamp with time zone, failure_mode_value text, payload_digest_value bytea, policies_value jsonb, signature_value bytea, envelope_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE budget_stop_value jsonb;target_row zasp_security_agent_temporary_policy_targets%ROWTYPE;ttl_seconds integer;session_value text;generation_value bigint;
BEGIN
  PERFORM zasp_sa_multistep_prior.legacy_action_fence(organization_value,workspace_value,environment_value,run_value);
 IF phase_value='apply' THEN PERFORM zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,false);END IF;
  IF NOT zasp_security_agent_action_principal_ready() OR phase_value NOT IN('apply','cleanup') OR octet_length(payload_digest_value)<>32 OR octet_length(signature_value)<>64 OR octet_length(envelope_digest_value)<>32 OR jsonb_typeof(policies_value)<>'array' OR jsonb_array_length(policies_value)>100 OR phase_value='cleanup' AND policies_value<>'[]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='policy source target rejected';END IF;
  SELECT * INTO target_row FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id,target.credential_id,target.sequence,target.policy_version)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value,credential_value,sequence_value,policy_version_value) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='policy source target missing';END IF;
  PERFORM 1 FROM zasp_security_agent_effects effect WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,effect.state,effect.lease_owner,effect.lease_token)=(organization_value,workspace_value,environment_value,run_value,step_value,target_row.action_key,'leased',worker_value,lease_token_value) AND effect.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy source lease lost';END IF;
  SELECT (plan.plan->'steps'->0->>'ttl_seconds')::integer,plan.plan->'steps'->0->>'session_id' INTO STRICT ttl_seconds,session_value FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(organization_value,workspace_value,environment_value,run_value);
  IF ttl_seconds NOT BETWEEN 60 AND 3600 OR failure_mode_value<>'closed' OR phase_value='apply' AND expires_value<>issued_value+make_interval(secs=>ttl_seconds) OR phase_value='cleanup' AND expires_value<>issued_value+interval '5 minutes' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='policy source target rejected';END IF;
  IF target_row.action_key='isolate_session' AND phase_value='apply' AND (NOT zasp_valid_product_id(session_value) OR jsonb_array_length(policies_value)<>2 OR EXISTS(SELECT 1 FROM jsonb_array_elements(policies_value) policy WHERE policy->>'action'<>'block' OR NOT policy->'conditions' @> jsonb_build_array(jsonb_build_object('field','session_id','operator','equals','value',session_value)))) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session isolation policy rejected';END IF;
  IF phase_value='apply' AND (NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,target_row.action_key,true))) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='policy source execution disabled';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_gateway_devices device WHERE (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(organization_value,workspace_value,environment_value,device_value,'active')) OR credential_value IS DISTINCT FROM (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(organization_value,workspace_value,environment_value,device_value) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy source credential changed';END IF;

  IF phase_value='apply' AND (target_row.state='planned' OR target_row.desired_generation IS NULL) THEN
   -- Existing gateway source triggers create these rows. Missing or busy work
   -- is a retry conflict, never permission to enqueue before checking budget.
   BEGIN
    PERFORM 1 FROM zasp_policy_deployment_fairness WHERE organization_id=organization_value FOR UPDATE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy deployment authority missing';END IF;
    PERFORM 1 FROM zasp_policy_deployment_work WHERE (organization_id,workspace_id,environment_id,device_id)=(organization_value,workspace_value,environment_value,device_value) FOR UPDATE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy deployment authority missing';END IF;
   EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy deployment authority busy';END;
   budget_stop_value:=zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,true);
   IF budget_stop_value IS NOT NULL THEN RETURN jsonb_build_object('budget_action_stop',budget_stop_value||jsonb_build_object('phase',phase_value,'device_id',device_value,'credential_id',credential_value,'sequence',sequence_value,'policy_version',policy_version_value));END IF;
  END IF;
  IF target_row.state<>'planned' THEN
    IF (target_row.key_id,target_row.issued_at,target_row.expires_at,target_row.failure_mode,target_row.payload_digest,target_row.policies,target_row.signature,target_row.envelope_digest) IS DISTINCT FROM (key_value,issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='policy source target replay conflict';END IF;
    generation_value:=target_row.desired_generation;
  ELSE
    UPDATE zasp_security_agent_temporary_policy_targets target SET state='stored',key_id=key_value,issued_at=issued_value,expires_at=expires_value,failure_mode=failure_mode_value,payload_digest=payload_digest_value,policies=policies_value,signature=signature_value,envelope_digest=envelope_digest_value,stored_at=transaction_timestamp() WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value);
  END IF;
  IF generation_value IS NULL THEN
    generation_value:=zasp_policy_deployment_enqueue_device(organization_value,workspace_value,environment_value,device_value);
    UPDATE zasp_security_agent_temporary_policy_targets target SET desired_generation=generation_value WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value);
  END IF;
  RETURN jsonb_build_object('device_id',device_value,'phase',phase_value,'sequence',sequence_value,'policy_version',policy_version_value,'envelope_digest','sha256:'||encode(envelope_digest_value,'hex'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_authenticate_gateway_enrollment(locator_value bytea, secret_value bytea, audience_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE locator_hash bytea;candidate_scope record;token_row zasp_gateway_enrollment_tokens%ROWTYPE;device_row zasp_gateway_devices%ROWTYPE;computed_hash bytea;
BEGIN
 IF NOT zasp_runtime_principal_ready('zasp_gateway_control') OR octet_length(locator_value)<>16 OR octet_length(secret_value)<>32 OR audience_value<>'runtime-gateway-enroll' THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='gateway authentication rejected';END IF;
 locator_hash:=digest(locator_value,'sha256');
 SELECT token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.device_id INTO candidate_scope FROM zasp_gateway_enrollment_tokens token_value WHERE token_value.locator_digest=locator_hash;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='gateway authentication rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate_scope.organization_id,candidate_scope.workspace_id,candidate_scope.environment_id,candidate_scope.device_id),0));
 SELECT token_value.* INTO token_row FROM zasp_gateway_enrollment_tokens token_value WHERE token_value.locator_digest=locator_hash FOR UPDATE;
 SELECT device_value.* INTO device_row FROM zasp_gateway_devices device_value WHERE (device_value.organization_id,device_value.workspace_id,device_value.environment_id,device_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.device_id) FOR UPDATE;
 computed_hash:=zasp_runtime_gateway_enrollment_secret_hash(audience_value,token_row.id,token_row.token_generation,token_row.salt,secret_value);
 IF token_row.format_version<>1 OR token_row.audience<>audience_value OR token_row.revoked_at IS NOT NULL OR token_row.expires_at<=transaction_timestamp() OR device_row.state NOT IN('pending','active') OR digest(token_row.token_hash||computed_hash,'sha256')<>digest(token_row.token_hash||token_row.token_hash,'sha256') OR EXISTS(SELECT 1 FROM zasp_gateway_enrollment_tokens newer WHERE (newer.organization_id,newer.workspace_id,newer.environment_id,newer.device_id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.device_id) AND newer.token_generation>token_row.token_generation) THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='gateway authentication rejected';END IF;
 RETURN jsonb_build_object('organization_id',token_row.organization_id,'workspace_id',token_row.workspace_id,'environment_id',token_row.environment_id,'device_id',token_row.device_id,'device_version',device_row.version,'enrollment_id',token_row.id,'token_generation',token_row.token_generation,'consumed',token_row.consumed_at IS NOT NULL,'audience',token_row.audience);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_gateway_advance_replay(credential_value text, expected_floor_value bigint, next_floor_value bigint, request_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;organization_value text;workspace_value text;environment_value text;device_value text;prior_digest bytea;
BEGIN
 IF expected_floor_value<0 OR next_floor_value<=expected_floor_value OR octet_length(request_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway replay rejected';END IF;
 authority_value:=zasp_runtime_gateway_credential_authority(credential_value,'runtime-gateway');organization_value:=authority_value->>'organization_id';workspace_value:=authority_value->>'workspace_id';environment_value:=authority_value->>'environment_id';device_value:=authority_value->>'device_id';
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,device_value),0));
 SELECT receipt.request_digest INTO prior_digest FROM zasp_runtime_gateway_replay_receipts receipt WHERE (receipt.organization_id,receipt.workspace_id,receipt.environment_id,receipt.device_id,receipt.next_floor)=(organization_value,workspace_value,environment_value,device_value,next_floor_value);
 IF FOUND THEN IF prior_digest<>request_digest_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='gateway replay rejected';END IF;RETURN jsonb_build_object('credential_id',credential_value,'replay_floor',next_floor_value,'replayed',true);END IF;
 UPDATE zasp_gateway_devices device_row SET replay_floor=next_floor_value,version=device_row.version+1,updated_at=transaction_timestamp() WHERE (device_row.organization_id,device_row.workspace_id,device_row.environment_id,device_row.id,device_row.replay_floor)=(organization_value,workspace_value,environment_value,device_value,expected_floor_value);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='gateway replay rejected';END IF;
 INSERT INTO zasp_runtime_gateway_replay_receipts(organization_id,workspace_id,environment_id,device_id,credential_id,next_floor,request_digest) VALUES(organization_value,workspace_value,environment_value,device_value,credential_value,next_floor_value,request_digest_value);
 RETURN jsonb_build_object('credential_id',credential_value,'replay_floor',next_floor_value,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_gateway_record_event(credential_value text, event_value text, expected_floor_value bigint, next_floor_value bigint, request_digest_value bytea, policy_version_value bigint, decision_value text, action_kind_value text, classification_value jsonb, occurred_value timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;organization_value text;workspace_value text;environment_value text;device_value text;existing_value zasp_runtime_gateway_events%ROWTYPE;canonical_digest bytea;result_value jsonb;
BEGIN
 IF NOT zasp_valid_product_id(event_value) OR expected_floor_value<0 OR next_floor_value<=expected_floor_value OR octet_length(request_digest_value)<>32 OR policy_version_value<1 OR decision_value NOT IN('allow','monitor','block') OR action_kind_value NOT IN('http','mcp') OR jsonb_typeof(classification_value)<>'object'
  OR NOT classification_value ?& ARRAY['category','route_class','resource_class','outcome'] OR classification_value-ARRAY['category','route_class','resource_class','outcome','session_id','agent_id','target_id','capability_category','capability_outcome']<>'{}'::jsonb
  OR octet_length(convert_to(classification_value::text,'UTF8'))>16384 OR EXISTS(SELECT 1 FROM jsonb_each_text(classification_value) item WHERE length(item.value) NOT BETWEEN 1 AND 128 OR item.value<>btrim(item.value) OR item.value!~'^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$')
  OR classification_value ? 'session_id' AND NOT zasp_valid_product_id(classification_value->>'session_id')
  OR classification_value ?| ARRAY['agent_id','target_id','capability_category','capability_outcome'] AND (decision_value<>'block' OR NOT classification_value ?& ARRAY['agent_id','target_id','capability_category','capability_outcome'] OR NOT zasp_valid_product_id(classification_value->>'agent_id') OR NOT zasp_valid_product_id(classification_value->>'target_id') OR (classification_value->>'capability_category',classification_value->>'capability_outcome') NOT IN(('data_read','read'),('data_write','write'),('action_execute','execute'),('identity_assume','assume'),('network_egress','connect'),('administration','administer')))
  OR occurred_value IS NULL OR occurred_value>transaction_timestamp()+interval '30 seconds' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway event rejected';END IF;
 authority_value:=zasp_runtime_gateway_credential_authority(credential_value,'runtime-gateway');organization_value:=authority_value->>'organization_id';workspace_value:=authority_value->>'workspace_id';environment_value:=authority_value->>'environment_id';device_value:=authority_value->>'device_id';
 canonical_digest:=digest(convert_to(jsonb_build_object('credential_id',credential_value,'device_id',device_value,'event_id',event_value,'expected_floor',expected_floor_value,'next_floor',next_floor_value,'policy_version',policy_version_value,'decision',decision_value,'action_kind',action_kind_value,'classification',classification_value,'occurred_at',to_char(occurred_value AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'))::text,'UTF8'),'sha256');
 IF canonical_digest<>request_digest_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway event rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,device_value),0));
 SELECT * INTO existing_value FROM zasp_runtime_gateway_events event_row WHERE (event_row.organization_id,event_row.workspace_id,event_row.environment_id,event_row.event_id)=(organization_value,workspace_value,environment_value,event_value);
 IF FOUND THEN
  IF (existing_value.device_id,existing_value.credential_id,existing_value.sequence,existing_value.request_digest,existing_value.policy_version,existing_value.decision,existing_value.action_kind,existing_value.classification,existing_value.occurred_at) IS DISTINCT FROM (device_value,credential_value,next_floor_value,request_digest_value,policy_version_value,decision_value,action_kind_value,classification_value,occurred_value) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='gateway event rejected';END IF;
  UPDATE zasp_runtime_gateway_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;RETURN jsonb_build_object('event_id',event_value,'device_id',device_value,'sequence',next_floor_value,'recorded_at',existing_value.recorded_at,'replayed',true);
 END IF;
 IF occurred_value<transaction_timestamp()-interval '24 hours' THEN UPDATE zasp_runtime_gateway_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;RETURN jsonb_build_object('event_id',event_value,'outcome','record_window_expired');END IF;
 IF classification_value ? 'agent_id' THEN PERFORM zasp_inventory_record_capability_evidence(organization_value,workspace_value,environment_value,classification_value->>'agent_id',classification_value->>'target_id',classification_value->>'capability_category',classification_value->>'capability_outcome','runtime_policy',event_value,occurred_value);END IF;
 PERFORM zasp_runtime_gateway_advance_replay(credential_value,expected_floor_value,next_floor_value,request_digest_value);
 INSERT INTO zasp_runtime_gateway_events(organization_id,workspace_id,environment_id,device_id,credential_id,event_id,sequence,request_digest,policy_version,decision,action_kind,classification,occurred_at) VALUES(organization_value,workspace_value,environment_value,device_value,credential_value,event_value,next_floor_value,request_digest_value,policy_version_value,decision_value,action_kind_value,classification_value,occurred_value) RETURNING jsonb_build_object('event_id',event_id,'device_id',device_id,'sequence',sequence,'recorded_at',recorded_at,'replayed',false) INTO result_value;
 UPDATE zasp_runtime_gateway_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;RETURN result_value;
END
$function$

