 INSERT INTO zasp_runtime_gateway_events(organization_id,workspace_id,environment_id,device_id,credential_id,event_id,sequence,request_digest,policy_version,decision,action_kind,classification,policy_ids,occurred_at) VALUES(organization_value,workspace_value,environment_value,device_value,credential_value,event_value,next_floor_value,request_digest_value,policy_version_value,decision_value,action_kind_value,classification_value,policy_ids_value,occurred_value) RETURNING jsonb_build_object('event_id',event_id,'device_id',device_id,'sequence',sequence,'recorded_at',recorded_at,'replayed',false) INTO result_value;
 UPDATE zasp_runtime_gateway_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;RETURN result_value;
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_issue_gateway_enrollment(organization_value text, workspace_value text, environment_value text, enrollment_value text, device_value text, generation_value bigint, device_version_value bigint, locator_digest_value bytea, salt_value bytea, token_hash_value bytea, expires_value timestamp with time zone)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result_value jsonb;expected_generation bigint;existing_value zasp_gateway_enrollment_tokens%ROWTYPE;
BEGIN
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(enrollment_value) OR NOT zasp_valid_product_id(device_value) OR generation_value<1 OR device_version_value<1 OR octet_length(locator_digest_value)<>32 OR octet_length(salt_value)<>32 OR octet_length(token_hash_value)<>32 OR expires_value<=transaction_timestamp() OR expires_value>transaction_timestamp()+interval '24 hours' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway enrollment rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,device_value),0));
 SELECT * INTO existing_value FROM zasp_gateway_enrollment_tokens token_row WHERE (token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.id)=(organization_value,workspace_value,environment_value,enrollment_value);
 IF FOUND THEN
  IF (existing_value.device_id,existing_value.format_version,existing_value.token_generation,existing_value.device_version_at_issue,existing_value.locator_digest,existing_value.salt,existing_value.token_hash,existing_value.expires_at) IS DISTINCT FROM (device_value,1,generation_value,device_version_value,locator_digest_value,salt_value,token_hash_value,expires_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='gateway enrollment conflict';END IF;
  RETURN jsonb_build_object('id',existing_value.id,'device_id',existing_value.device_id,'audience',existing_value.audience,'generation',existing_value.token_generation,'device_version',existing_value.device_version_at_issue,'issued_at',existing_value.issued_at,'expires_at',existing_value.expires_at,'replayed',true);
 END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_gateway_devices device_row WHERE (device_row.organization_id,device_row.workspace_id,device_row.environment_id,device_row.id,device_row.version)=(organization_value,workspace_value,environment_value,device_value,device_version_value) AND device_row.state IN('pending','active')) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='gateway enrollment rejected';END IF;
 SELECT COALESCE(max(token_row.token_generation),0)+1 INTO expected_generation FROM zasp_gateway_enrollment_tokens token_row WHERE (token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.device_id)=(organization_value,workspace_value,environment_value,device_value) AND token_row.token_generation IS NOT NULL;
 IF generation_value<>expected_generation OR EXISTS(SELECT 1 FROM zasp_gateway_enrollment_tokens token_row WHERE (token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.device_id)=(organization_value,workspace_value,environment_value,device_value) AND token_row.format_version=1 AND token_row.consumed_at IS NULL AND token_row.revoked_at IS NULL) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='gateway enrollment conflict';END IF;
 INSERT INTO zasp_gateway_enrollment_tokens(organization_id,workspace_id,environment_id,id,device_id,audience,salt,token_hash,expires_at,format_version,locator_digest,token_generation,device_version_at_issue,v15_issued_at)
 VALUES(organization_value,workspace_value,environment_value,enrollment_value,device_value,'runtime-gateway-enroll',salt_value,token_hash_value,expires_value,1,locator_digest_value,generation_value,device_version_value,transaction_timestamp())
 RETURNING jsonb_build_object('id',id,'device_id',device_id,'audience',audience,'generation',token_generation,'device_version',device_version_at_issue,'issued_at',issued_at,'expires_at',expires_at,'replayed',false) INTO result_value;
 PERFORM zasp_runtime_mark_used();
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_revoke_gateway_enrollment(organization_value text, workspace_value text, environment_value text, device_value text, enrollment_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE revoked_value timestamptz;
BEGIN
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(device_value) OR NOT zasp_valid_product_id(enrollment_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='gateway enrollment rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),organization_value,workspace_value,environment_value,device_value),0));
 UPDATE zasp_gateway_enrollment_tokens token_row SET revoked_at=COALESCE(token_row.revoked_at,transaction_timestamp()) WHERE (token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.device_id,token_row.id)=(organization_value,workspace_value,environment_value,device_value,enrollment_value) AND token_row.format_version=1 RETURNING token_row.revoked_at INTO revoked_value;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='gateway enrollment rejected';END IF;
 PERFORM zasp_runtime_mark_used();
 RETURN jsonb_build_object('id',enrollment_value,'revoked_at',revoked_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_sa_multistep_prior.application(checksum_value text, fingerprint_value text, request_value jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
<<action_body>>
DECLARE o text;w text;e text;r text;s text;op text;worker text;token text;key text;envelope jsonb;request_digest bytea;audit_id text;outcome_id text;control_id text;deployment_id text;
 rr public.zasp_security_agent_runs%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;fx public.zasp_security_agent_effects%ROWTYPE;
 old_audit public.zasp_security_agent_audit%ROWTYPE;target public.zasp_security_agent_temporary_policy_targets%ROWTYPE;device record;
 result_value jsonb;targets jsonb;result_hash bytea;deployment_hash bytea;ttl integer;lease_until timestamptz;expires timestamptz;applied timestamptz;prior_lease timestamptz;replay boolean;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered application requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_sa_multistep_prior.closed(request_value,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','operation','worker_id','lease_token','run_version','effect_version','lease_seconds','envelope']) OR octet_length(request_value::text)>32768 THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered application input rejected';END IF;
 FOREACH key IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id','step_id'] LOOP
  IF jsonb_typeof(request_value->key) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(request_value->>key),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered application identity rejected';END IF;
 END LOOP;
 FOREACH key IN ARRAY ARRAY['worker_id','lease_token'] LOOP
  IF jsonb_typeof(request_value->key) IS DISTINCT FROM 'string' OR length(btrim(request_value->>key)) NOT BETWEEN 1 AND 128 OR (request_value->>key)~'[[:cntrl:]]' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered application lease rejected';END IF;
 END LOOP;
 FOREACH key IN ARRAY ARRAY['run_version','effect_version','lease_seconds'] LOOP
  IF jsonb_typeof(request_value->key) IS DISTINCT FROM 'number' OR (request_value->>key)!~'^(0|[1-9][0-9]{0,5})$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered application version rejected';END IF;
 END LOOP;
 o:=request_value->>'organization_id';w:=request_value->>'workspace_id';e:=request_value->>'environment_id';r:=request_value->>'run_id';s:=request_value->>'step_id';op:=request_value->>'operation';worker:=request_value->>'worker_id';token:=request_value->>'lease_token';envelope:=request_value->'envelope';
 IF NOT COALESCE(op IN('claim','heartbeat','store','complete'),false) OR (request_value->>'run_version')::integer<1 OR length(token)<16 OR (request_value->>'lease_seconds')::integer NOT BETWEEN 30 AND 300 OR jsonb_typeof(envelope) IS DISTINCT FROM 'object' OR op<>'store' AND envelope<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered application operation rejected';END IF;
 IF NOT COALESCE(public.zasp_security_agent_action_principal_ready(),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered application principal rejected';END IF;
 IF NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered application release unavailable';END IF;
 PERFORM zasp_sa_multistep_prior.application_lock(o,w,e,r);
 PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO st FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO fx FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy');
 SELECT (plan->'steps'->0->>'ttl_seconds')::integer INTO ttl FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 request_digest:=digest(convert_to(request_value::text,'UTF8'),'sha256');
 audit_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_application',r||chr(31)||s||chr(31)||encode(request_digest,'hex'));
 control_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_control',r||chr(31)||s);
 outcome_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_effect',r||chr(31)||s||chr(31)||'apply');
 SELECT a.* INTO old_audit FROM public.zasp_security_agent_audit a WHERE a.organization_id=o AND a.audit_id=action_body.audit_id FOR SHARE;
 replay:=FOUND;
 IF replay THEN
  result_value:=old_audit.body->'response';
  IF old_audit.event_digest IS DISTINCT FROM request_digest OR old_audit.body->'request' IS DISTINCT FROM request_value-'lease_token'
   OR result_value->'run_version' IS DISTINCT FROM to_jsonb(rr.version) OR result_value->'step_version' IS DISTINCT FROM to_jsonb(st.version)
   OR result_value->'effect_version' IS DISTINCT FROM to_jsonb(fx.version) OR result_value->>'effect_state' IS DISTINCT FROM fx.state
   OR result_value->'targets' IS DISTINCT FROM zasp_sa_multistep_prior.application_targets(o,w,e,r,s)
   OR (old_audit.body->>'lease_expires_at')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered application replay changed';END IF;
  IF op='complete' THEN
   IF NOT zasp_sa_multistep_prior.application_ready(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered receipt missing';END IF;
  ELSIF fx.state<>'leased' OR fx.lease_owner IS DISTINCT FROM worker OR fx.lease_token IS DISTINCT FROM token OR fx.lease_expires_at IS NULL OR fx.lease_expires_at<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered application replay lease lost';END IF;
 ELSE
  IF rr.version<>(request_value->>'run_version')::bigint OR COALESCE(fx.version,0)<>(request_value->>'effect_version')::bigint THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered application version changed';END IF;
  IF op='claim' THEN
   IF fx.run_id IS NULL THEN
    IF st.state<>'authorized' OR EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered claim is not ready';END IF;
    SELECT COALESCE(jsonb_agg(jsonb_build_object('id',d.id,'credential_id',g.id) ORDER BY d.id),'[]'::jsonb) INTO targets FROM public.zasp_gateway_devices d JOIN LATERAL(SELECT id FROM public.zasp_gateway_credentials WHERE (organization_id,workspace_id,environment_id,device_id)=(o,w,e,d.id) AND revoked_at IS NULL AND expires_at>clock_timestamp() ORDER BY issued_at DESC,id DESC LIMIT 1) g ON true WHERE (d.organization_id,d.workspace_id,d.environment_id,d.state)=(o,w,e,'active');
    IF jsonb_array_length(targets) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered claim target bound rejected';END IF;
    INSERT INTO public.zasp_security_agent_effects(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state,lease_owner,lease_token,lease_expires_at,attempt)
     VALUES(o,w,e,r,s,'create_temporary_policy',st.input_digest,'leased',worker,token,clock_timestamp()+make_interval(secs=>(request_value->>'lease_seconds')::integer),1);
    FOR device IN SELECT * FROM jsonb_to_recordset(targets) AS t(id text,credential_id text) LOOP
     INSERT INTO public.zasp_security_agent_temporary_policy_targets(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id,credential_id,sequence,policy_version) VALUES(o,w,e,r,s,'apply',device.id,device.credential_id,1,1);
    END LOOP;
    IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered claim has no gateway';END IF;
    INSERT INTO public.zasp_security_agent_step_reservations(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest) VALUES(o,w,e,r,s,'create_temporary_policy',st.input_digest);
    UPDATE public.zasp_security_agent_steps SET state='executing',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
   ELSE
    IF st.state<>'executing' OR fx.state<>'leased' OR fx.lease_expires_at IS NULL OR fx.lease_expires_at>clock_timestamp() OR fx.lease_token=token OR fx.attempt>=100
     OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,s,'create_temporary_policy',st.input_digest)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered claim lease unavailable';END IF;
    -- Stored sources survive recovery. Neither a receipt nor verification is
    -- inferred from lease expiry or an uncertain external worker outcome.
    UPDATE public.zasp_security_agent_effects SET lease_owner=worker,lease_token=token,lease_expires_at=clock_timestamp()+make_interval(secs=>(request_value->>'lease_seconds')::integer),attempt=attempt+1,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy');
   END IF;
   UPDATE public.zasp_security_agent_runs SET version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  ELSE
   IF st.state<>'executing' OR fx.state IS DISTINCT FROM 'leased' OR fx.lease_owner IS DISTINCT FROM worker OR fx.lease_token IS DISTINCT FROM token OR fx.lease_expires_at IS NULL OR fx.lease_expires_at<=clock_timestamp()
    OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,s,'create_temporary_policy',st.input_digest)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered application lease lost';END IF;
   prior_lease:=fx.lease_expires_at;
   IF op='heartbeat' THEN
    UPDATE public.zasp_security_agent_effects SET lease_expires_at=GREATEST(lease_expires_at,clock_timestamp()+make_interval(secs=>(request_value->>'lease_seconds')::integer)),version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy');
   ELSIF op='store' THEN
    IF NOT zasp_sa_multistep_prior.closed(envelope,ARRAY['device_id','credential_id','sequence','policy_version','key_id','issued_at','expires_at','failure_mode','payload_digest','policies','signature','envelope_digest'])
     OR envelope->'policies' IS DISTINCT FROM zasp_sa_multistep_prior.application_policies()
     OR envelope->>'failure_mode' IS DISTINCT FROM 'closed' OR (envelope->>'issued_at')::timestamptz>clock_timestamp()+interval '5 seconds'
     OR (envelope->>'expires_at')::timestamptz<=clock_timestamp() OR (envelope->>'payload_digest')!~'^sha256:[a-f0-9]{64}$' OR (envelope->>'envelope_digest')!~'^sha256:[a-f0-9]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered source envelope rejected';END IF;
    PERFORM zasp_sa_multistep_prior.application_source(o,w,e,r,s,'apply',worker,token,envelope->>'device_id',envelope->>'credential_id',(envelope->>'sequence')::bigint,(envelope->>'policy_version')::bigint,envelope->>'key_id',(envelope->>'issued_at')::timestamptz,(envelope->>'expires_at')::timestamptz,envelope->>'failure_mode',decode(substring(envelope->>'payload_digest' FROM 8),'hex'),envelope->'policies',decode(envelope->>'signature','base64'),decode(substring(envelope->>'envelope_digest' FROM 8),'hex'));
    UPDATE public.zasp_security_agent_effects SET version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy');
   ELSE
    PERFORM zasp_sa_multistep_prior.deployment_verified(o,w,e,r,s);
    IF NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply'))
     OR EXISTS(SELECT 1 FROM public.zasp_security_agent_temporary_policy_targets t WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id)=(o,w,e,r,s)
      AND (t.phase<>'apply' OR t.state<>'stored' OR NOT EXISTS(SELECT 1 FROM public.zasp_policy_deployment_work d JOIN public.zasp_runtime_gateway_policy_bundles bundle ON (bundle.organization_id,bundle.workspace_id,bundle.environment_id,bundle.device_id,bundle.envelope_digest)=(d.organization_id,d.workspace_id,d.environment_id,d.device_id,d.applied_envelope_digest)
       WHERE (d.organization_id,d.workspace_id,d.environment_id,d.device_id,d.desired_generation,d.applied_generation)=(o,w,e,t.device_id,t.desired_generation,t.desired_generation)
        AND bundle.credential_id=t.credential_id AND bundle.expires_at>=t.expires_at AND bundle.expires_at>clock_timestamp() AND bundle.failure_mode='closed' AND bundle.policies @> t.policies))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered deployment is not verified';END IF;
    UPDATE public.zasp_security_agent_temporary_policy_targets SET state='verified',verified_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply');
    SELECT digest(st.input_digest||decode(string_agg(encode(envelope_digest,'hex'),'' ORDER BY device_id),'hex'),'sha256'),digest(convert_to(jsonb_agg(jsonb_build_array(device_id,credential_id,sequence,policy_version,desired_generation,encode(envelope_digest,'hex')) ORDER BY device_id)::text,'UTF8'),'sha256'),min(expires_at),max(verified_at) INTO result_hash,deployment_hash,expires,applied FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply');
    deployment_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_deployment',r||chr(31)||s||chr(31)||encode(deployment_hash,'hex'));
    INSERT INTO public.zasp_security_agent_controls(organization_id,workspace_id,environment_id,control_id,run_id,step_id,action_key,target_id,state,expires_at) VALUES(o,w,e,control_id,r,s,'create_temporary_policy',e,'active',expires);
    UPDATE public.zasp_security_agent_effects SET state='cleanup_pending',outcome_id=action_body.outcome_id,result_digest=result_hash,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=version+1,updated_at=expires WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy');
    UPDATE public.zasp_security_agent_steps SET state='succeeded',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
    UPDATE public.zasp_security_agent_runs SET version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
    INSERT INTO public.zasp_sa_multistep_receipts(organization_id,workspace_id,environment_id,run_id,plan_hash,step_id,action_key,input_digest,result_digest,receipt_kind,receipt_version,body)
     VALUES(o,w,e,r,rr.plan_hash,s,'create_temporary_policy',st.input_digest,result_hash,'temporary_policy_applied.v1',1,jsonb_build_object('deployment_id',deployment_id,'control_id',control_id,'control_version',1,'outcome_id',outcome_id,'applied_at',to_char(applied AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'expires_at',to_char(expires AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"')));
   END IF;
  END IF;
  SELECT * INTO fx FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy');
  SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
  SELECT * INTO st FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  lease_until:=COALESCE(fx.lease_expires_at,prior_lease);
  targets:=zasp_sa_multistep_prior.application_targets(o,w,e,r,s);
  result_value:=jsonb_build_object('contract_version',61,'organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'step_id',s,'operation',op,'run_version',rr.version,'step_version',st.version,'effect_version',fx.version,'effect_state',fx.state,'attempt',fx.attempt,'reservation_id',public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_reservation',r||chr(31)||s),'plan_hash','sha256:'||encode(rr.plan_hash,'hex'),'input_digest','sha256:'||encode(st.input_digest,'hex'),'ttl_seconds',ttl,'lease_expires_at',to_char(lease_until AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'targets',targets,'control_id',CASE WHEN op='complete' THEN control_id ELSE '' END,'deployment_id',COALESCE(deployment_id,''),'result_digest',COALESCE('sha256:'||encode(result_hash,'hex'),''));
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body)
   VALUES(o,w,e,audit_id,audit_id,r,s,worker,'ordered_application_'||op,request_digest,jsonb_build_object('contract_version',61,'request',request_value-'lease_token','lease_expires_at',to_char(lease_until AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'response',result_value));
 END IF;
 -- FK, sequence, target, control, receipt and audit writes can wait. All
 -- provisional changes abort when current authority or the issuing lease died.
 PERFORM zasp_sa_multistep_prior.application_current(o,w,e,r,s);
 IF NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) OR NOT COALESCE(public.zasp_security_agent_action_principal_ready(),false)
  OR prior_lease IS NOT NULL AND prior_lease<=clock_timestamp() OR (result_value->>'lease_expires_at')::timestamptz<=clock_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered application expired after wait';END IF;
 IF op='complete' THEN
  PERFORM zasp_sa_multistep_prior.deployment_verified(o,w,e,r,s);
  IF NOT zasp_sa_multistep_prior.application_ready(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered application receipt changed';END IF;
 END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_sa_multistep_prior.application_source(organization_value text, workspace_value text, environment_value text, run_value text, step_value text, phase_value text, worker_value text, lease_token_value text, device_value text, credential_value text, sequence_value bigint, policy_version_value bigint, key_value text, issued_value timestamp with time zone, expires_value timestamp with time zone, failure_mode_value text, payload_digest_value bytea, policies_value jsonb, signature_value bytea, envelope_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE budget_stop_value jsonb;target_row zasp_security_agent_temporary_policy_targets%ROWTYPE;ttl_seconds integer;session_value text;generation_value bigint;
BEGIN
 IF phase_value='apply' THEN PERFORM zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,false);END IF;
  IF NOT zasp_security_agent_action_principal_ready() OR phase_value NOT IN('apply','cleanup') OR octet_length(payload_digest_value)<>32 OR octet_length(signature_value)<>64 OR octet_length(envelope_digest_value)<>32 OR jsonb_typeof(policies_value)<>'array' OR jsonb_array_length(policies_value)>100 OR phase_value='cleanup' AND policies_value<>'[]'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='policy source target rejected';END IF;
  SELECT * INTO target_row FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id,target.credential_id,target.sequence,target.policy_version)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value,credential_value,sequence_value,policy_version_value) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='policy source target missing';END IF;
  PERFORM 1 FROM zasp_security_agent_effects effect WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,effect.state,effect.lease_owner,effect.lease_token)=(organization_value,workspace_value,environment_value,run_value,step_value,target_row.action_key,'leased',worker_value,lease_token_value) AND effect.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy source lease lost';END IF;
  SELECT (plan.plan->'steps'->0->>'ttl_seconds')::integer,plan.plan->'steps'->0->>'session_id' INTO STRICT ttl_seconds,session_value FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(organization_value,workspace_value,environment_value,run_value);
  IF ttl_seconds NOT BETWEEN 60 AND 3600 OR failure_mode_value<>'closed' OR phase_value='apply' AND expires_value<>issued_value+make_interval(secs=>ttl_seconds) OR phase_value='cleanup' AND expires_value<>issued_value+interval '5 minutes' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='policy source target rejected';END IF;
  IF target_row.action_key='isolate_session' AND phase_value='apply' AND (NOT zasp_valid_product_id(session_value) OR jsonb_array_length(policies_value)<>2 OR EXISTS(SELECT 1 FROM jsonb_array_elements(policies_value) policy WHERE policy->>'action'<>'block' OR NOT policy->'conditions' @> jsonb_build_array(jsonb_build_object('field','session_id','operator','equals','value',session_value)))) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session isolation policy rejected';END IF;
  IF phase_value='apply' AND (NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,target_row.action_key,true))) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='policy source execution disabled';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_gateway_devices device WHERE (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(organization_value,workspace_value,environment_value,device_value,'active')) OR credential_value IS DISTINCT FROM (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(organization_value,workspace_value,environment_value,device_value) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy source credential changed';END IF;

  IF phase_value='apply' AND (target_row.state='planned' OR target_row.desired_generation IS NULL) THEN
   -- Existing gateway source triggers create these rows. Missing or busy work
   -- is a retry conflict, never permission to enqueue before checking budget.
   BEGIN
    PERFORM 1 FROM zasp_policy_deployment_fairness WHERE organization_id=organization_value FOR UPDATE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy deployment authority missing';END IF;
    PERFORM 1 FROM zasp_policy_deployment_work WHERE (organization_id,workspace_id,environment_id,device_id)=(organization_value,workspace_value,environment_value,device_value) FOR UPDATE NOWAIT;
    IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy deployment authority missing';END IF;
   EXCEPTION WHEN lock_not_available THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='policy deployment authority busy';END;
   budget_stop_value:=zasp_security_agent_budget_action_gate(organization_value,workspace_value,environment_value,run_value,step_value,worker_value,lease_token_value,true);
   IF budget_stop_value IS NOT NULL THEN RETURN jsonb_build_object('budget_action_stop',budget_stop_value||jsonb_build_object('phase',phase_value,'device_id',device_value,'credential_id',credential_value,'sequence',sequence_value,'policy_version',policy_version_value));END IF;
  END IF;
  IF target_row.state<>'planned' THEN
    IF (target_row.key_id,target_row.issued_at,target_row.expires_at,target_row.failure_mode,target_row.payload_digest,target_row.policies,target_row.signature,target_row.envelope_digest) IS DISTINCT FROM (key_value,issued_value,expires_value,failure_mode_value,payload_digest_value,policies_value,signature_value,envelope_digest_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='policy source target replay conflict';END IF;
    generation_value:=target_row.desired_generation;
  ELSE
    UPDATE zasp_security_agent_temporary_policy_targets target SET state='stored',key_id=key_value,issued_at=issued_value,expires_at=expires_value,failure_mode=failure_mode_value,payload_digest=payload_digest_value,policies=policies_value,signature=signature_value,envelope_digest=envelope_digest_value,stored_at=transaction_timestamp() WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value);
  END IF;
  IF generation_value IS NULL THEN
    generation_value:=zasp_policy_deployment_enqueue_device(organization_value,workspace_value,environment_value,device_value);
    UPDATE zasp_security_agent_temporary_policy_targets target SET desired_generation=generation_value WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.device_id)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,device_value);
  END IF;
  RETURN jsonb_build_object('device_id',device_value,'phase',phase_value,'sequence',sequence_value,'policy_version',policy_version_value,'envelope_digest','sha256:'||encode(envelope_digest_value,'hex'));
END
$function$

CREATE OR REPLACE FUNCTION zasp_sa_multistep_prior.cleanup(checksum_value text, fingerprint_value text, q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
<<cleanup_body>>
DECLARE o text;w text;e text;r text;s text;op text;k text;worker text;token text;rv bigint;ev bigint;cv bigint;
 rr public.zasp_security_agent_runs%ROWTYPE;fx public.zasp_security_agent_effects%ROWTYPE;c zasp_sa_multistep_prior.cleanups%ROWTYPE;
snapshot_value jsonb;response jsonb;old_audit public.zasp_security_agent_audit%ROWTYPE;request_hash bytea;audit_id text;deadline timestamptz;original_deadline timestamptz;marker_deadline timestamptz;env jsonb;target record;receipt_body jsonb;receipt_digest bytea;acks jsonb;next_state text;ack_count integer;target_count integer;recovery_evidence jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='ordered cleanup requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','operation','worker_id','lease_token','run_version','effect_version','version','lease_seconds','envelope']) OR NOT zasp_sa_multistep_prior.cleanup_wire(q,'request') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered cleanup input rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id','step_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered cleanup identity rejected';END IF;
 END LOOP;
 FOREACH k IN ARRAY ARRAY['run_version','effect_version','version','lease_seconds'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'number' OR NOT COALESCE(q->>k~'^(0|[1-9][0-9]{0,5})$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered cleanup version rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';op:=q->>'operation';worker:=q->>'worker_id';token:=q->>'lease_token';rv:=(q->>'run_version')::bigint;ev:=(q->>'effect_version')::bigint;cv:=(q->>'version')::bigint;
 IF NOT COALESCE(op IN('claim','heartbeat','store','complete','reconcile') AND rv BETWEEN 1 AND 999998 AND ev BETWEEN 1 AND 999998 AND cv<999999 AND (q->>'lease_seconds')::integer BETWEEN 30 AND 300 AND jsonb_typeof(q->'worker_id')='string' AND length(btrim(worker)) BETWEEN 1 AND 128 AND worker!~'[[:cntrl:]]' AND jsonb_typeof(q->'lease_token')='string' AND length(token) BETWEEN 16 AND 128 AND token!~'[[:cntrl:]]' AND jsonb_typeof(q->'envelope')='object' AND (op='store' OR q->'envelope'='{}'::jsonb),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered cleanup operation rejected';END IF;
 IF NOT COALESCE(public.zasp_security_agent_action_principal_ready(),false) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='ordered cleanup principal rejected';END IF;
 IF NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='ordered cleanup release unavailable';END IF;
 PERFORM zasp_sa_multistep_prior.cleanup_lock(o,w,e,r);
 snapshot_value:=zasp_sa_multistep_prior.cleanup_snapshot(o,w,e,r,s);
 IF octet_length(snapshot_value::text)>262144 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup snapshot budget exceeded';END IF;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO fx FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy');
 SELECT * INTO c FROM zasp_sa_multistep_prior.cleanups WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 original_deadline:=c.lease_expires_at;
 IF c.run_id IS NOT NULL THEN
  IF c.snapshot IS DISTINCT FROM snapshot_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup retained authority changed';END IF;
  PERFORM zasp_sa_multistep_prior.cleanup_targets(o,w,e,r,s);
 END IF;
 request_hash:=digest(convert_to(q::text,'UTF8'),'sha256');audit_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_cleanup_operation',r||chr(31)||s||chr(31)||encode(request_hash,'hex'));
 SELECT * INTO old_audit FROM public.zasp_security_agent_audit a WHERE a.organization_id=o AND a.audit_id=cleanup_body.audit_id;
 IF FOUND THEN
  response:=old_audit.body->'response';
  IF old_audit.event_digest IS DISTINCT FROM request_hash OR old_audit.body->'request' IS DISTINCT FROM q-'lease_token' OR old_audit.body->'owner' IS DISTINCT FROM to_jsonb(c)-'lease_token' OR response->'run_version' IS DISTINCT FROM to_jsonb(rr.version) OR response->>'run_state' IS DISTINCT FROM rr.state OR response->'effect_version' IS DISTINCT FROM to_jsonb(fx.version) OR response->>'effect_state' IS DISTINCT FROM fx.state OR response->'targets' IS DISTINCT FROM zasp_sa_multistep_prior.cleanup_targets(o,w,e,r,s)
   OR op NOT IN('complete','reconcile') AND (c.state<>'leased' OR c.lease_owner IS DISTINCT FROM worker OR c.lease_token IS DISTINCT FROM token OR c.lease_expires_at<=clock_timestamp())
   OR op='reconcile' AND (c.state<>'retryable' OR fx.state<>'cleanup_failed' OR EXISTS(SELECT 1 FROM zasp_sa_multistep_prior.cleanup_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup replay changed';END IF;
  IF op='complete' THEN
   SELECT body,digest INTO receipt_body,receipt_digest FROM zasp_sa_multistep_prior.cleanup_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
   IF c.state<>'cleaned' OR fx.state<>'cleaned' OR receipt_body IS DISTINCT FROM response->'receipt' OR receipt_digest IS DISTINCT FROM digest(convert_to(zasp_sa_multistep_prior.deployment_json(receipt_body),'UTF8'),'sha256') OR c.snapshot->>'kind' IS DISTINCT FROM 'partial' AND NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_controls WHERE (organization_id,workspace_id,environment_id,run_id,step_id,control_id,state)=(o,w,e,r,s,c.control_id,'disabled')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleaned evidence changed';END IF;
  END IF;
 ELSE
  IF rr.version<>rv OR fx.version<>ev OR COALESCE(c.version,0)<>cv OR rr.state NOT IN('contained','needs_human','cancelled','failed','inconclusive') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup version unavailable';END IF;
  deadline:=clock_timestamp()+make_interval(secs=>(q->>'lease_seconds')::integer);
  IF op='claim' THEN
   IF c.run_id IS NOT NULL THEN
    IF c.state<>'retryable' OR fx.state<>'cleanup_failed' OR c.attempt>=100 OR EXISTS(SELECT 1 FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'cleanup') AND state<>'planned' AND expires_at<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup recovery unavailable';END IF;
    UPDATE zasp_sa_multistep_prior.cleanups SET state='leased',version=version+1,attempt=attempt+1,lease_owner=worker,lease_token=token,lease_expires_at=deadline,reason='none' WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) RETURNING * INTO c;
   ELSE
   IF snapshot_value->>'kind'='partial' THEN
    IF fx.state<>'leased' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered partial cleanup claim unavailable';END IF;
    -- Cancellation has fenced application writes. Do not replace any active
    -- deployment owner; its exact expired outcome must remain recoverable.
    IF EXISTS(SELECT 1 FROM public.zasp_policy_deployment_work d JOIN public.zasp_security_agent_temporary_policy_targets t USING(organization_id,workspace_id,environment_id,device_id) WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id,t.phase)=(o,w,e,r,s,'apply') AND d.state='leased' AND d.lease_expires_at>clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered partial deployment still owned';END IF;
    PERFORM zasp_sa_multistep_prior.cleanup_partial_handoff(o,w,e,r,s,worker);
    snapshot_value:=zasp_sa_multistep_prior.cleanup_partial_snapshot(o,w,e,r,s);
   ELSIF fx.state<>'cleanup_pending' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup claim unavailable';END IF;
   -- Source-sequence admission is locked by application_lock. Prove the next
   -- trigger-assigned value fits the closed wire before reserving cleanup.
   IF EXISTS(SELECT 1 FROM public.zasp_security_agent_temporary_policy_targets a WHERE (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.step_id,a.phase)=(o,w,e,r,s,'apply') AND (EXISTS(SELECT 1 FROM public.zasp_security_agent_temporary_policy_targets x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.device_id)=(o,w,e,a.device_id) AND x.sequence>=999999999) OR EXISTS(SELECT 1 FROM public.zasp_runtime_gateway_policy_bundles x WHERE (x.organization_id,x.workspace_id,x.environment_id,x.device_id)=(o,w,e,a.device_id) AND x.sequence>=999999999))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup source sequence exhausted';END IF;
  INSERT INTO zasp_sa_multistep_prior.cleanups(organization_id,workspace_id,environment_id,run_id,step_id,cleanup_id,control_id,reservation_id,snapshot,state,version,attempt,lease_owner,lease_token,lease_expires_at,started_at,reason)
   VALUES(o,w,e,r,s,public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_cleanup',r||chr(31)||s),snapshot_value->'control'->>'control_id',public.zasp_discovery_canonical_id(o,w,e,'security_agent_ordered_cleanup_reservation',r||chr(31)||s),snapshot_value,'leased',1,1,worker,token,deadline,clock_timestamp(),'none') RETURNING * INTO c;
   FOR target IN SELECT device_id,credential_id FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'apply') AND state IN('stored','verified') ORDER BY device_id LOOP
    INSERT INTO public.zasp_security_agent_temporary_policy_targets(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id,credential_id,sequence,policy_version) VALUES(o,w,e,r,s,'cleanup',target.device_id,target.credential_id,1,1);
   END LOOP;
   END IF;
  ELSIF op='reconcile' THEN
   IF c.state IS DISTINCT FROM 'leased' OR c.lease_expires_at IS NULL OR c.lease_expires_at>clock_timestamp() OR fx.state<>'leased' OR fx.lease_expires_at IS DISTINCT FROM c.lease_expires_at OR fx.lease_owner IS DISTINCT FROM c.lease_owner OR fx.lease_token IS DISTINCT FROM c.lease_token
    OR EXISTS(SELECT 1 FROM public.zasp_policy_deployment_work x JOIN public.zasp_security_agent_temporary_policy_targets t ON(t.organization_id,t.workspace_id,t.environment_id,t.device_id,t.desired_generation)=(x.organization_id,x.workspace_id,x.environment_id,x.device_id,x.leased_generation) WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id,t.phase)=(o,w,e,r,s,'cleanup') AND x.state='leased' AND x.lease_expires_at>clock_timestamp())
    OR EXISTS(SELECT 1 FROM zasp_sa_multistep_prior.cleanup_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup expiry not ready';END IF;
   SELECT count(*),count(*) FILTER(WHERE EXISTS(SELECT 1 FROM public.zasp_security_agent_audit a WHERE (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.step_id,a.event_kind)=(o,w,e,r,s,'ordered_cleanup_delivery_finish') AND a.body->'request'->>'device_id'=t.device_id AND a.body->'request'->>'source_digest'='sha256:'||encode(t.envelope_digest,'hex'))) INTO target_count,ack_count FROM public.zasp_security_agent_temporary_policy_targets t WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'cleanup');
   IF target_count NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup recovery target set absent';END IF;
   c.reason:=CASE WHEN ack_count=target_count THEN 'complete_unsettled' WHEN ack_count>0 THEN 'partial_acknowledgement' WHEN EXISTS(SELECT 1 FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,step_id,event_kind)=(o,w,e,r,s,'ordered_cleanup_delivery_store')) THEN 'unknown_call' ELSE 'no_external_call' END;
   recovery_evidence:=jsonb_build_object('reason',c.reason,'acknowledged',ack_count,'targets',target_count,'snapshot_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value),'UTF8'),'sha256'),'hex'),'deployment_state',(SELECT jsonb_agg(jsonb_build_object('device_id',t.device_id,'target_digest',encode(digest(convert_to(to_jsonb(t)::text,'UTF8'),'sha256'),'hex'),'work_digest',encode(digest(convert_to((to_jsonb(x)-'lease_token')::text,'UTF8'),'sha256'),'hex')) ORDER BY t.device_id) FROM public.zasp_security_agent_temporary_policy_targets t LEFT JOIN public.zasp_policy_deployment_work x USING(organization_id,workspace_id,environment_id,device_id) WHERE (t.organization_id,t.workspace_id,t.environment_id,t.run_id,t.step_id,t.phase)=(o,w,e,r,s,'cleanup')));
   UPDATE zasp_sa_multistep_prior.cleanups SET state='retryable',version=version+1,reason=c.reason,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) RETURNING * INTO c;
   UPDATE public.zasp_security_agent_runs SET state=CASE WHEN state='cancelled' THEN 'cancelled' ELSE 'needs_human' END,version=version+1,updated_at=clock_timestamp(),completed_at=COALESCE(completed_at,clock_timestamp()),last_error_code=CASE WHEN state='cancelled' THEN last_error_code ELSE 'cleanup_incomplete' END WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO rr;
  ELSE
   PERFORM zasp_sa_multistep_prior.cleanup_current(o,w,e,r,s);
   IF c.lease_owner IS DISTINCT FROM worker OR c.lease_token IS DISTINCT FROM token OR fx.lease_owner IS DISTINCT FROM worker OR fx.lease_token IS DISTINCT FROM token THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup lease changed';END IF;
   deadline:=c.lease_expires_at;
   IF op='heartbeat' THEN deadline:=clock_timestamp()+make_interval(secs=>(q->>'lease_seconds')::integer);
   ELSIF op='store' THEN
    env:=q->'envelope';
    IF NOT zasp_sa_multistep_prior.closed(env,ARRAY['device_id','credential_id','sequence','policy_version','key_id','issued_at','expires_at','failure_mode','payload_digest','policies','signature','envelope_digest']) OR env->'policies' IS DISTINCT FROM '[]'::jsonb OR env->>'failure_mode' IS DISTINCT FROM 'closed' OR NOT COALESCE(env->>'payload_digest'~'^sha256:[a-f0-9]{64}$' AND env->>'envelope_digest'~'^sha256:[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered cleanup source rejected';END IF;
    PERFORM zasp_sa_multistep_prior.application_source(o,w,e,r,s,'cleanup',worker,token,env->>'device_id',env->>'credential_id',(env->>'sequence')::bigint,(env->>'policy_version')::bigint,env->>'key_id',(env->>'issued_at')::timestamptz,(env->>'expires_at')::timestamptz,env->>'failure_mode',decode(substr(env->>'payload_digest',8),'hex'),env->'policies',decode(env->>'signature','base64'),decode(substr(env->>'envelope_digest',8),'hex'));
   ELSE
    -- First completion still consumes the signed execution markers. Save the
    -- earliest deadline before mutation; durable replay uses its saved proof.
    SELECT min(expires_at) INTO marker_deadline FROM public.zasp_security_agent_temporary_policy_targets WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'cleanup');
    acks:=zasp_sa_multistep_prior.cleanup_acknowledgements(o,w,e,r,s);
    UPDATE public.zasp_security_agent_temporary_policy_targets SET state='verified',verified_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,phase)=(o,w,e,r,s,'cleanup') AND state='stored';
    next_state:=CASE WHEN rr.state='cancelled' THEN 'cancelled' WHEN rr.state='contained' AND zasp_sa_multistep_prior.cleanup_remediation_ready(o,w,e,r,snapshot_value) THEN 'remediated' ELSE 'needs_human' END;
    receipt_body:=jsonb_build_object('cleanup_id',c.cleanup_id,'control_id',c.control_id,'control_version',(snapshot_value->'control'->>'version')::bigint+1,'effect_id',snapshot_value->'effect'->>'outcome_id','application_receipt_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'application'),'UTF8'),'sha256'),'hex'),'test_evidence_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'test'),'UTF8'),'sha256'),'hex'),'removed_source_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'targets'),'UTF8'),'sha256'),'hex'),'cleanup_deployment_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(acks),'UTF8'),'sha256'),'hex'),'targets',acks,'started_at',to_char(c.started_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'completed_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'attempts',c.attempt,'outcome','cleaned');
    IF snapshot_value->>'kind'='partial' THEN
     receipt_body:=(receipt_body-ARRAY['control_id','control_version','effect_id','application_receipt_digest','test_evidence_digest'])||jsonb_build_object('partial_application_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'application'),'UTF8'),'sha256'),'hex'),'cancellation_evidence_digest',encode(digest(convert_to(zasp_sa_multistep_prior.deployment_json(snapshot_value->'test'),'UTF8'),'sha256'),'hex'));
    END IF;
    IF NOT zasp_sa_multistep_prior.cleanup_wire(receipt_body,'receipt') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup evidence budget exceeded';END IF;
    receipt_digest:=digest(convert_to(zasp_sa_multistep_prior.deployment_json(receipt_body),'UTF8'),'sha256');
    INSERT INTO zasp_sa_multistep_prior.cleanup_receipts VALUES(o,w,e,r,s,CASE WHEN snapshot_value->>'kind'='partial' THEN 'temporary_policy_partial_cleaned.v1' ELSE 'temporary_policy_cleaned.v1' END,receipt_body,receipt_digest);
    UPDATE public.zasp_security_agent_controls SET state='disabled',version=version+1,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL WHERE (organization_id,workspace_id,environment_id,control_id,state)=(o,w,e,c.control_id,'active');
    UPDATE public.zasp_security_agent_runs SET state=next_state,version=version+1,updated_at=clock_timestamp(),completed_at=COALESCE(completed_at,clock_timestamp()),last_error_code=CASE WHEN next_state='needs_human' THEN COALESCE(last_error_code,'cleanup_requires_review') ELSE last_error_code END WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO rr;
   END IF;
   UPDATE zasp_sa_multistep_prior.cleanups SET version=version+1,state=CASE WHEN op='complete' THEN 'cleaned' ELSE 'leased' END,lease_owner=CASE WHEN op<>'complete' THEN worker END,lease_token=CASE WHEN op<>'complete' THEN token END,lease_expires_at=CASE WHEN op<>'complete' THEN deadline END,completed_at=CASE WHEN op='complete' THEN (receipt_body->>'completed_at')::timestamptz END WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) RETURNING * INTO c;
  END IF;
  UPDATE public.zasp_security_agent_effects SET state=CASE WHEN op='complete' THEN 'cleaned' WHEN op='reconcile' THEN 'cleanup_failed' ELSE 'leased' END,lease_owner=CASE WHEN op NOT IN('complete','reconcile') THEN worker END,lease_token=CASE WHEN op NOT IN('complete','reconcile') THEN token END,lease_expires_at=CASE WHEN op NOT IN('complete','reconcile') THEN deadline END,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key)=(o,w,e,r,s,'create_temporary_policy') RETURNING * INTO fx;
  response:=jsonb_build_object('contract_version',61,'organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'step_id',s,'operation',op,'cleanup_id',c.cleanup_id,'reservation_id',c.reservation_id,'control_id',c.control_id,'state',c.state,'version',c.version,'attempt',c.attempt,'run_version',rr.version,'run_state',rr.state,'effect_version',fx.version,'effect_state',fx.state,'lease_expires_at',COALESCE(to_char(c.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),''),'reason',c.reason,'targets',zasp_sa_multistep_prior.cleanup_targets(o,w,e,r,s),'receipt_kind',CASE WHEN op='complete' THEN 'temporary_policy_cleaned.v1' ELSE '' END,'receipt',COALESCE(receipt_body,'{}'::jsonb),'receipt_digest',COALESCE('sha256:'||encode(receipt_digest,'hex'),''));
  IF op='complete' AND snapshot_value->>'kind'='partial' THEN response:=jsonb_set(response,'{receipt_kind}','"temporary_policy_partial_cleaned.v1"');END IF;
  IF NOT zasp_sa_multistep_prior.cleanup_wire(response,'response') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup response budget exceeded';END IF;
  INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_id,audit_id,r,s,worker,'ordered_cleanup_'||op,request_hash,jsonb_build_object('request',q-'lease_token','owner',to_jsonb(c)-'lease_token','recovery_evidence',recovery_evidence,'response',response));
 END IF;
 IF NOT zasp_sa_multistep_prior.cleanup_wire(response,'response') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup replay budget exceeded';END IF;
 IF op IN('heartbeat','store') THEN PERFORM zasp_sa_multistep_prior.cleanup_current(o,w,e,r,s);END IF;
 IF op='heartbeat' AND (original_deadline IS NULL OR original_deadline<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup heartbeat original lease expired after wait';END IF;
 IF op='complete' AND (receipt_body->'targets' IS DISTINCT FROM zasp_sa_multistep_prior.cleanup_acknowledgements(o,w,e,r,s) OR response->>'run_state'='remediated' AND NOT zasp_sa_multistep_prior.cleanup_remediation_ready(o,w,e,r,snapshot_value)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup completion authority changed after wait';END IF;
 IF snapshot_value IS DISTINCT FROM zasp_sa_multistep_prior.cleanup_snapshot(o,w,e,r,s) OR op NOT IN('complete','reconcile') AND (COALESCE(deadline,c.lease_expires_at)>='infinity'::timestamptz OR COALESCE(deadline,c.lease_expires_at)<=clock_timestamp()) OR op='complete' AND deadline<=clock_timestamp() OR NOT COALESCE(public.zasp_security_agent_action_principal_ready(),false) OR NOT COALESCE(public.zasp_sa_multistep_readiness(checksum_value,fingerprint_value),false) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup authority changed after wait';END IF;
 IF op='complete' AND old_audit.audit_id IS NULL AND (marker_deadline IS NULL OR marker_deadline<=clock_timestamp()) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered cleanup execution marker expired after wait';END IF;
 RETURN response;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_claim_session_policy_effects(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item record;device_row record;target_row record;items jsonb:='[]'::jsonb;targets jsonb;phase_value text;ttl_seconds integer;sequence_value bigint;policy_version_value bigint;session_value text;target_device_value text;no_target_result bytea;no_target_outcome text;no_target_audit text;no_target_correlation text;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_seconds NOT BETWEEN 30 AND 300 OR claim_limit NOT BETWEEN 1 AND 25 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy claim rejected';END IF;
  UPDATE zasp_security_agent_effects effect SET state=CASE WHEN zasp_security_agent_budget_stopped(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id) OR EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase,target.state)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,'apply',target.state) AND (target.state='verified' OR target.state='stored' AND zasp_security_agent_budget_stopped(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id))) THEN 'cleanup_pending' ELSE 'pending' END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp()
  WHERE effect.action_key IN('create_temporary_policy','isolate_session') AND (effect.state='leased' AND effect.lease_expires_at<=transaction_timestamp() OR effect.state='pending' AND zasp_security_agent_budget_stopped(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id));
  FOR item IN SELECT effect.* FROM zasp_security_agent_effects effect WHERE effect.action_key IN('create_temporary_policy','isolate_session') AND effect.state='cleanup_pending' AND effect.updated_at<=transaction_timestamp()
    AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets applied JOIN zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(applied.organization_id,applied.workspace_id,applied.environment_id,applied.device_id,'active') JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(device.organization_id,device.workspace_id,device.environment_id,device.id) WHERE (applied.organization_id,applied.workspace_id,applied.environment_id,applied.run_id,applied.step_id,applied.action_key,applied.phase,applied.state)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,'apply',applied.state) AND (applied.state='verified' OR applied.state='stored' AND zasp_security_agent_budget_stopped(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id)) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp())
    ORDER BY effect.updated_at,effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id LIMIT claim_limit FOR UPDATE SKIP LOCKED
  LOOP
    no_target_result:=digest(item.input_digest,'sha256');no_target_outcome:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_effect',item.run_id||chr(31)||item.step_id||chr(31)||'cleanup');no_target_audit:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_audit',item.run_id||chr(31)||item.step_id||chr(31)||'cleanup-no-active-target');no_target_correlation:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_correlation',item.run_id||chr(31)||item.step_id||chr(31)||'cleanup-no-active-target');
    UPDATE zasp_security_agent_effects effect SET state='cleaned',outcome_id=no_target_outcome,result_digest=no_target_result,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=effect.version+1,updated_at=transaction_timestamp() WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,effect.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,item.action_key,'cleanup_pending');
    UPDATE zasp_security_agent_runs run SET state='remediated',version=run.version+1,updated_at=transaction_timestamp(),completed_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id,run.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,'contained');
    INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(item.organization_id,item.workspace_id,item.environment_id,no_target_audit,no_target_correlation,item.run_id,item.step_id,worker_value,'effect_cleaned',no_target_result,jsonb_build_object('run_id',item.run_id,'step_id',item.step_id,'action',item.action_key,'phase','cleanup','outcome_id',no_target_outcome,'result_digest','sha256:'||encode(no_target_result,'hex'),'reason','no_active_gateway_target')) ON CONFLICT DO NOTHING;
  END LOOP;
  FOR item IN
    WITH selected AS (
      SELECT effect.ctid,effect.state prior_state FROM zasp_security_agent_effects effect
      WHERE effect.action_key IN('create_temporary_policy','isolate_session') AND (effect.state='pending' OR effect.state='cleanup_pending' AND effect.updated_at<=transaction_timestamp())
        AND (effect.state='cleanup_pending' OR EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(effect.organization_id,effect.workspace_id,effect.environment_id,'*',true)) AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.action_key,true)))
        AND EXISTS(SELECT 1 FROM zasp_gateway_devices device JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(device.organization_id,device.workspace_id,device.environment_id,device.id) JOIN zasp_security_agent_plans plan ON (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id) WHERE (device.organization_id,device.workspace_id,device.environment_id,device.state)=(effect.organization_id,effect.workspace_id,effect.environment_id,'active') AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() AND (effect.action_key='create_temporary_policy' OR device.id=plan.plan->'steps'->0->>'device_id'))
      ORDER BY effect.updated_at,effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id LIMIT claim_limit FOR UPDATE SKIP LOCKED
    ), claimed AS (
      UPDATE zasp_security_agent_effects effect SET state='leased',lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),attempt=effect.attempt+1,version=effect.version+1,updated_at=transaction_timestamp() FROM selected WHERE effect.ctid=selected.ctid RETURNING effect.*,selected.prior_state
    ) SELECT * FROM claimed
  LOOP
    phase_value:=CASE item.prior_state WHEN 'cleanup_pending' THEN 'cleanup' ELSE 'apply' END;
    SELECT COALESCE((plan.plan->'steps'->0->>'ttl_seconds')::integer,300),CASE item.action_key WHEN 'isolate_session' THEN plan.plan->'steps'->0->>'session_id' ELSE NULL END,CASE item.action_key WHEN 'isolate_session' THEN plan.plan->'steps'->0->>'device_id' ELSE NULL END INTO ttl_seconds,session_value,target_device_value FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id);
    IF ttl_seconds NOT BETWEEN 60 AND 3600 OR item.action_key='isolate_session' AND (NOT zasp_valid_product_id(session_value) OR NOT zasp_valid_product_id(target_device_value)) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy plan rejected';END IF;
    FOR device_row IN SELECT device.id device_id,credential.id credential_id FROM zasp_gateway_devices device JOIN LATERAL (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(device.organization_id,device.workspace_id,device.environment_id,device.id) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1) credential ON true WHERE (device.organization_id,device.workspace_id,device.environment_id,device.state)=(item.organization_id,item.workspace_id,item.environment_id,'active') AND (item.action_key='create_temporary_policy' OR device.id=target_device_value) AND (phase_value='apply' OR EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets applied WHERE (applied.organization_id,applied.workspace_id,applied.environment_id,applied.run_id,applied.step_id,applied.action_key,applied.phase,applied.device_id,applied.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,item.action_key,'apply',device.id,applied.state) AND (applied.state='verified' OR applied.state='stored' AND zasp_security_agent_budget_stopped(item.organization_id,item.workspace_id,item.environment_id,item.run_id)))) ORDER BY device.id
    LOOP
      PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),item.organization_id,item.workspace_id,item.environment_id,device_row.device_id,'temporary-policy-sequence'),0));
      SELECT COALESCE(max(bundle.sequence)+1,1),COALESCE(max(bundle.policy_version)+1,1) INTO sequence_value,policy_version_value FROM zasp_runtime_gateway_policy_bundles bundle WHERE (bundle.organization_id,bundle.workspace_id,bundle.environment_id,bundle.device_id)=(item.organization_id,item.workspace_id,item.environment_id,device_row.device_id);
      INSERT INTO zasp_security_agent_temporary_policy_targets(organization_id,workspace_id,environment_id,run_id,step_id,action_key,phase,device_id,credential_id,sequence,policy_version) VALUES(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,item.action_key,phase_value,device_row.device_id,device_row.credential_id,sequence_value,policy_version_value)
      ON CONFLICT(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id) DO UPDATE SET action_key=excluded.action_key,credential_id=excluded.credential_id,sequence=excluded.sequence,policy_version=excluded.policy_version,state='planned',key_id=NULL,issued_at=NULL,expires_at=NULL,failure_mode=NULL,payload_digest=NULL,policies=NULL,signature=NULL,envelope_digest=NULL,stored_at=NULL,verified_at=NULL WHERE zasp_security_agent_temporary_policy_targets.state='planned' OR zasp_security_agent_temporary_policy_targets.credential_id<>excluded.credential_id;
    END LOOP;
    targets:='[]'::jsonb;
    FOR target_row IN SELECT * FROM zasp_security_agent_temporary_policy_targets value WHERE (value.organization_id,value.workspace_id,value.environment_id,value.run_id,value.step_id,value.action_key,value.phase)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,item.action_key,phase_value) ORDER BY value.device_id LOOP targets:=targets||jsonb_build_array(jsonb_build_object('device_id',target_row.device_id,'credential_id',target_row.credential_id,'sequence',target_row.sequence,'policy_version',target_row.policy_version));END LOOP;
    items:=items||jsonb_build_array(jsonb_build_object('organization_id',item.organization_id,'workspace_id',item.workspace_id,'environment_id',item.environment_id,'run_id',item.run_id,'step_id',item.step_id,'action_key',item.action_key,'session_id',session_value,'phase',phase_value,'input_digest','sha256:'||encode(item.input_digest,'hex'),'ttl_seconds',ttl_seconds,'lease_expires_at',to_char(item.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'targets',targets));
  END LOOP;
  RETURN jsonb_build_object('items',items);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_claim_temporary_policy_effects(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE item record;device_row record;target_row record;items jsonb:='[]'::jsonb;targets jsonb;phase_value text;ttl_seconds integer;sequence_value bigint;policy_version_value bigint;no_target_result bytea;no_target_outcome text;no_target_audit text;no_target_correlation text;
BEGIN
  IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='legacy action claim requires read committed';END IF;
  PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
  IF NOT zasp_security_agent_action_principal_ready() OR length(worker_value) NOT BETWEEN 1 AND 128 OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_seconds NOT BETWEEN 30 AND 300 OR claim_limit NOT BETWEEN 1 AND 25 THEN
    RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='temporary policy claim rejected';
  END IF;
  UPDATE zasp_security_agent_effects effect SET state=CASE WHEN zasp_security_agent_budget_stopped(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id) OR EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.state)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,'apply',target.state) AND (target.state='verified' OR target.state='stored' AND zasp_security_agent_budget_stopped(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id))) THEN 'cleanup_pending' ELSE 'pending' END,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,updated_at=transaction_timestamp()
  WHERE effect.action_key='create_temporary_policy' AND NOT zasp_sa_multistep_prior.ordered_action_run(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id) AND (effect.state='leased' AND effect.lease_expires_at<=transaction_timestamp() OR effect.state='pending' AND zasp_security_agent_budget_stopped(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id));
  FOR item IN SELECT effect.* FROM zasp_security_agent_effects effect WHERE effect.action_key='create_temporary_policy' AND NOT zasp_sa_multistep_prior.ordered_action_run(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id) AND effect.state='cleanup_pending' AND effect.updated_at<=transaction_timestamp()
    AND NOT EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets applied JOIN zasp_gateway_devices device ON (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(applied.organization_id,applied.workspace_id,applied.environment_id,applied.device_id,'active') JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(device.organization_id,device.workspace_id,device.environment_id,device.id)
      WHERE (applied.organization_id,applied.workspace_id,applied.environment_id,applied.run_id,applied.step_id,applied.phase,applied.state)=(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,'apply',applied.state) AND (applied.state='verified' OR applied.state='stored' AND zasp_security_agent_budget_stopped(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id)) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp())
    ORDER BY effect.updated_at,effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id LIMIT claim_limit FOR UPDATE SKIP LOCKED
  LOOP
    no_target_result:=digest(item.input_digest,'sha256');
    no_target_outcome:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_effect',item.run_id||chr(31)||item.step_id||chr(31)||'cleanup');
    no_target_audit:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_audit',item.run_id||chr(31)||item.step_id||chr(31)||'cleanup-no-active-target');
    no_target_correlation:=zasp_discovery_canonical_id(item.organization_id,item.workspace_id,item.environment_id,'security_agent_correlation',item.run_id||chr(31)||item.step_id||chr(31)||'cleanup-no-active-target');
    UPDATE zasp_security_agent_effects effect SET state='cleaned',outcome_id=no_target_outcome,result_digest=no_target_result,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=effect.version+1,updated_at=transaction_timestamp() WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,effect.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,'create_temporary_policy','cleanup_pending');
    UPDATE zasp_security_agent_runs run SET state='remediated',version=run.version+1,updated_at=transaction_timestamp(),completed_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id,run.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,'contained');
    INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(item.organization_id,item.workspace_id,item.environment_id,no_target_audit,no_target_correlation,item.run_id,item.step_id,worker_value,'effect_cleaned',no_target_result,jsonb_build_object('run_id',item.run_id,'step_id',item.step_id,'action','create_temporary_policy','phase','cleanup','outcome_id',no_target_outcome,'result_digest','sha256:'||encode(no_target_result,'hex'),'reason','no_active_gateway_target')) ON CONFLICT DO NOTHING;
  END LOOP;
  FOR item IN
    WITH selected AS (
      SELECT effect.ctid,effect.state AS prior_state FROM zasp_security_agent_effects effect
      WHERE effect.action_key='create_temporary_policy' AND NOT zasp_sa_multistep_prior.ordered_action_run(effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id) AND (effect.state='pending' OR effect.state='cleanup_pending' AND effect.updated_at<=transaction_timestamp())
        AND (effect.state='cleanup_pending' OR (
          EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch WHERE (switch.organization_id,switch.workspace_id,switch.environment_id,switch.action_key,switch.execution_enabled)=('*','*','*','*',true))
          AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch WHERE (switch.organization_id,switch.workspace_id,switch.environment_id,switch.action_key,switch.execution_enabled)=(effect.organization_id,effect.workspace_id,effect.environment_id,'*',true))
          AND EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches switch WHERE (switch.organization_id,switch.workspace_id,switch.environment_id,switch.action_key,switch.execution_enabled)=(effect.organization_id,effect.workspace_id,effect.environment_id,'create_temporary_policy',true))))
        AND EXISTS(SELECT 1 FROM zasp_gateway_devices device JOIN zasp_gateway_credentials credential ON (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(device.organization_id,device.workspace_id,device.environment_id,device.id)
          WHERE (device.organization_id,device.workspace_id,device.environment_id,device.state)=(effect.organization_id,effect.workspace_id,effect.environment_id,'active') AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp())
      ORDER BY effect.updated_at,effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id LIMIT claim_limit FOR UPDATE SKIP LOCKED
    ), claimed AS (
      UPDATE zasp_security_agent_effects effect SET state='leased',lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),attempt=effect.attempt+1,version=effect.version+1,updated_at=transaction_timestamp()
      FROM selected WHERE effect.ctid=selected.ctid RETURNING effect.*,selected.prior_state
    ) SELECT * FROM claimed
  LOOP
    phase_value:=CASE item.prior_state WHEN 'cleanup_pending' THEN 'cleanup' ELSE 'apply' END;
    SELECT COALESCE((plan.plan->'steps'->0->>'ttl_seconds')::integer,300) INTO ttl_seconds FROM zasp_security_agent_plans plan WHERE (plan.organization_id,plan.workspace_id,plan.environment_id,plan.run_id)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id);
    IF ttl_seconds NOT BETWEEN 60 AND 3600 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='temporary policy ttl rejected';END IF;
    FOR device_row IN
      SELECT device.id AS device_id,credential.id AS credential_id
      FROM zasp_gateway_devices device JOIN LATERAL (
        SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(device.organization_id,device.workspace_id,device.environment_id,device.id) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1
      ) credential ON true
      WHERE (device.organization_id,device.workspace_id,device.environment_id,device.state)=(item.organization_id,item.workspace_id,item.environment_id,'active')
        AND (phase_value='apply' OR EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets applied WHERE (applied.organization_id,applied.workspace_id,applied.environment_id,applied.run_id,applied.step_id,applied.phase,applied.device_id,applied.state)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,'apply',device.id,applied.state) AND (applied.state='verified' OR applied.state='stored' AND zasp_security_agent_budget_stopped(item.organization_id,item.workspace_id,item.environment_id,item.run_id))))
      ORDER BY device.id
    LOOP
      PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),item.organization_id,item.workspace_id,item.environment_id,device_row.device_id,'temporary-policy-sequence'),0));
      SELECT COALESCE(max(bundle.sequence)+1,1),COALESCE(max(bundle.policy_version)+1,1) INTO sequence_value,policy_version_value FROM zasp_runtime_gateway_policy_bundles bundle WHERE (bundle.organization_id,bundle.workspace_id,bundle.environment_id,bundle.device_id)=(item.organization_id,item.workspace_id,item.environment_id,device_row.device_id);
      INSERT INTO zasp_security_agent_temporary_policy_targets(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id,credential_id,sequence,policy_version)
      VALUES(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,phase_value,device_row.device_id,device_row.credential_id,sequence_value,policy_version_value)
      ON CONFLICT(organization_id,workspace_id,environment_id,run_id,step_id,phase,device_id) DO UPDATE
      SET credential_id=excluded.credential_id,sequence=excluded.sequence,policy_version=excluded.policy_version,state='planned',key_id=NULL,issued_at=NULL,expires_at=NULL,failure_mode=NULL,payload_digest=NULL,policies=NULL,signature=NULL,envelope_digest=NULL,stored_at=NULL,verified_at=NULL
      WHERE zasp_security_agent_temporary_policy_targets.state='planned' OR zasp_security_agent_temporary_policy_targets.credential_id<>excluded.credential_id;
    END LOOP;
    targets:='[]'::jsonb;
    FOR target_row IN SELECT * FROM zasp_security_agent_temporary_policy_targets value WHERE (value.organization_id,value.workspace_id,value.environment_id,value.run_id,value.step_id,value.phase)=(item.organization_id,item.workspace_id,item.environment_id,item.run_id,item.step_id,phase_value) ORDER BY value.device_id LOOP
      targets:=targets||jsonb_build_array(jsonb_build_object('device_id',target_row.device_id,'credential_id',target_row.credential_id,'sequence',target_row.sequence,'policy_version',target_row.policy_version));
    END LOOP;
    items:=items||jsonb_build_array(jsonb_build_object('organization_id',item.organization_id,'workspace_id',item.workspace_id,'environment_id',item.environment_id,'run_id',item.run_id,'step_id',item.step_id,'phase',phase_value,'input_digest','sha256:'||encode(item.input_digest,'hex'),'ttl_seconds',ttl_seconds,'lease_expires_at',to_char(item.lease_expires_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'targets',targets));
  END LOOP;
  RETURN jsonb_build_object('items',items);
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_finish_session_policy_effect(organization_value text, workspace_value text, environment_value text, run_value text, step_value text, phase_value text, worker_value text, lease_token_value text, result_digest_value bytea, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE effect_row zasp_security_agent_effects%ROWTYPE;outcome_value text;expires_value timestamptz;expected_digest bytea;
BEGIN
  IF NOT zasp_security_agent_action_principal_ready() OR phase_value NOT IN('apply','cleanup') OR octet_length(result_digest_value)<>32 OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy finish rejected';END IF;
  SELECT * INTO effect_row FROM zasp_security_agent_effects effect WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.state,effect.lease_owner,effect.lease_token)=(organization_value,workspace_value,environment_value,run_value,step_value,'leased',worker_value,lease_token_value) AND effect.action_key IN('create_temporary_policy','isolate_session') AND effect.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session policy lease lost';END IF;
  IF phase_value='apply' AND (NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true)) OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,effect_row.action_key,true))) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session policy execution disabled';END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value)) OR EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value) AND target.state<>'stored') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='session policy verification incomplete';END IF;
  IF EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value) AND (NOT EXISTS(SELECT 1 FROM zasp_gateway_devices device WHERE (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(target.organization_id,target.workspace_id,target.environment_id,target.device_id,'active')) OR target.credential_id IS DISTINCT FROM (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(target.organization_id,target.workspace_id,target.environment_id,target.device_id) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='session policy credential changed';END IF;
  SELECT digest(effect_row.input_digest||decode(string_agg(encode(target.envelope_digest,'hex'),'' ORDER BY target.device_id),'hex'),'sha256') INTO STRICT expected_digest FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase,target.state)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value,'stored');
  IF expected_digest IS DISTINCT FROM result_digest_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='session policy result rejected';END IF;
  UPDATE zasp_security_agent_temporary_policy_targets target SET state='verified',verified_at=transaction_timestamp() WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,phase_value);
  outcome_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'security_agent_effect',run_value||chr(31)||step_value||chr(31)||phase_value);
  IF phase_value='apply' THEN
    SELECT max(target.expires_at) INTO STRICT expires_value FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.action_key,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key,'apply');
    UPDATE zasp_security_agent_effects effect SET state='cleanup_pending',outcome_id=outcome_value,result_digest=result_digest_value,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=effect.version+1,updated_at=expires_value WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key);
    UPDATE zasp_security_agent_steps step SET state='succeeded',version=step.version+1,updated_at=transaction_timestamp() WHERE (step.organization_id,step.workspace_id,step.environment_id,step.run_id,step.step_id)=(organization_value,workspace_value,environment_value,run_value,step_value);
    UPDATE zasp_security_agent_runs run SET state='contained',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=run.version+1,updated_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  ELSE
    UPDATE zasp_security_agent_effects effect SET state='cleaned',outcome_id=outcome_value,result_digest=result_digest_value,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=effect.version+1,updated_at=transaction_timestamp() WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key)=(organization_value,workspace_value,environment_value,run_value,step_value,effect_row.action_key);
    UPDATE zasp_security_agent_runs run SET state='remediated',version=run.version+1,updated_at=transaction_timestamp(),completed_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  END IF;
  INSERT INTO zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(organization_value,workspace_value,environment_value,audit_value,correlation_value,run_value,step_value,worker_value,CASE phase_value WHEN 'apply' THEN 'effect_verified' ELSE 'effect_cleaned' END,result_digest_value,jsonb_build_object('run_id',run_value,'step_id',step_value,'action',effect_row.action_key,'phase',phase_value,'outcome_id',outcome_value,'result_digest','sha256:'||encode(result_digest_value,'hex')));
  RETURN jsonb_build_object('run_id',run_value,'step_id',step_value,'phase',phase_value,'effect_state',CASE phase_value WHEN 'apply' THEN 'cleanup_pending' ELSE 'cleaned' END,'outcome_id',outcome_value,'result_digest','sha256:'||encode(result_digest_value,'hex'));
END
$function$

CREATE OR REPLACE FUNCTION public.zasp_security_agent_finish_temporary_policy_effect(organization_value text, workspace_value text, environment_value text, run_value text, step_value text, phase_value text, worker_value text, lease_token_value text, result_digest_value bytea, audit_value text, correlation_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE effect_row zasp_security_agent_effects%ROWTYPE;outcome_value text;expires_value timestamptz;expected_digest bytea;
BEGIN
  PERFORM zasp_sa_multistep_prior.legacy_action_fence(organization_value,workspace_value,environment_value,run_value);
  IF NOT zasp_security_agent_action_principal_ready() OR phase_value NOT IN('apply','cleanup') OR octet_length(result_digest_value)<>32 OR NOT zasp_valid_product_id(audit_value) OR NOT zasp_valid_product_id(correlation_value) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='temporary policy finish rejected';END IF;
  SELECT * INTO effect_row FROM zasp_security_agent_effects effect WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key,effect.state,effect.lease_owner,effect.lease_token)=(organization_value,workspace_value,environment_value,run_value,step_value,'create_temporary_policy','leased',worker_value,lease_token_value) AND effect.lease_expires_at>transaction_timestamp() FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='temporary policy lease lost';END IF;
  IF phase_value='apply' AND (NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=('*','*','*','*',true))
     OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'*',true))
     OR NOT EXISTS(SELECT 1 FROM zasp_security_agent_kill_switches WHERE (organization_id,workspace_id,environment_id,action_key,execution_enabled)=(organization_value,workspace_value,environment_value,'create_temporary_policy',true))) THEN
    RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='temporary policy execution disabled';
  END IF;
  IF NOT EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value))
     OR EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value) AND target.state<>'stored') THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='temporary policy verification incomplete';END IF;
  IF EXISTS(SELECT 1 FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value)
    AND (NOT EXISTS(SELECT 1 FROM zasp_gateway_devices device WHERE (device.organization_id,device.workspace_id,device.environment_id,device.id,device.state)=(target.organization_id,target.workspace_id,target.environment_id,target.device_id,'active'))
      OR target.credential_id IS DISTINCT FROM (SELECT credential.id FROM zasp_gateway_credentials credential WHERE (credential.organization_id,credential.workspace_id,credential.environment_id,credential.device_id)=(target.organization_id,target.workspace_id,target.environment_id,target.device_id) AND credential.revoked_at IS NULL AND credential.expires_at>transaction_timestamp() ORDER BY credential.issued_at DESC,credential.id DESC LIMIT 1))) THEN
    RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='temporary policy credential changed';
  END IF;
  SELECT digest(effect_row.input_digest||decode(string_agg(encode(target.envelope_digest,'hex'),'' ORDER BY target.device_id),'hex'),'sha256') INTO STRICT expected_digest FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase,target.state)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value,'stored');
  IF expected_digest IS DISTINCT FROM result_digest_value THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='temporary policy result rejected';END IF;
  UPDATE zasp_security_agent_temporary_policy_targets target SET state='verified',verified_at=transaction_timestamp() WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,phase_value);
  outcome_value:=zasp_discovery_canonical_id(organization_value,workspace_value,environment_value,'security_agent_effect',run_value||chr(31)||step_value||chr(31)||phase_value);
  IF phase_value='apply' THEN
    SELECT max(target.expires_at) INTO STRICT expires_value FROM zasp_security_agent_temporary_policy_targets target WHERE (target.organization_id,target.workspace_id,target.environment_id,target.run_id,target.step_id,target.phase)=(organization_value,workspace_value,environment_value,run_value,step_value,'apply');
    UPDATE zasp_security_agent_effects effect SET state='cleanup_pending',outcome_id=outcome_value,result_digest=result_digest_value,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=effect.version+1,updated_at=expires_value WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key)=(organization_value,workspace_value,environment_value,run_value,step_value,'create_temporary_policy');
    UPDATE zasp_security_agent_steps step SET state='succeeded',version=step.version+1,updated_at=transaction_timestamp() WHERE (step.organization_id,step.workspace_id,step.environment_id,step.run_id,step.step_id)=(organization_value,workspace_value,environment_value,run_value,step_value);
    UPDATE zasp_security_agent_runs run SET state='contained',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=run.version+1,updated_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  ELSE
    UPDATE zasp_security_agent_effects effect SET state='cleaned',outcome_id=outcome_value,result_digest=result_digest_value,lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,version=effect.version+1,updated_at=transaction_timestamp() WHERE (effect.organization_id,effect.workspace_id,effect.environment_id,effect.run_id,effect.step_id,effect.action_key)=(organization_value,workspace_value,environment_value,run_value,step_value,'create_temporary_policy');
    UPDATE zasp_security_agent_runs run SET state='remediated',version=run.version+1,updated_at=transaction_timestamp(),completed_at=transaction_timestamp() WHERE (run.organization_id,run.workspace_id,run.environment_id,run.run_id)=(organization_value,workspace_value,environment_value,run_value);
  END IF;
