CREATE OR REPLACE FUNCTION zasp_temporal74.effect(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';r text:=q->>'run_id';s text:=q->>'step_id';op text:=q->>'operation';k text;live_value boolean;permit boolean:=false;snapshot_value jsonb;targets jsonb;
 rr public.zasp_security_agent_runs%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;f zasp_temporal74.effects%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='single-test effect requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='single-test catalog unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR octet_length(q::text)>4096 OR q->'generation' IS DISTINCT FROM '1'::jsonb OR q->'payload' IS DISTINCT FROM '{}'::jsonb OR NOT COALESCE(op IN('reserve','start','unknown','read'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test effect request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id','step_id'] LOOP IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test effect scope rejected';END IF;END LOOP;
 live_value:=op IN('reserve','start');
 IF NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT live_value AND zasp_temporal68.principal_ready('zasp_temporal_compensation')) OR NOT zasp_temporal74.is_owned(o,w,e,r) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test effect authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO STRICT st FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR UPDATE;
 IF live_value THEN PERFORM zasp_temporal74.current_step(o,w,e,r,s);END IF;
 SELECT * INTO f FROM zasp_temporal74.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1) FOR UPDATE;
 IF NOT FOUND THEN
  IF op<>'reserve' OR st.state<>'authorized' OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) OR EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test effect reservation unavailable';END IF;
  INSERT INTO public.zasp_security_agent_step_reservations(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest) VALUES(o,w,e,r,s,st.action_key,st.input_digest);
  INSERT INTO public.zasp_security_agent_effects(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state,attempt) VALUES(o,w,e,r,s,st.action_key,st.input_digest,'pending',1);
  targets:=zasp_temporal74.test_reserve(o,w,e,r,s);
  snapshot_value:=jsonb_build_object('plan_hash',encode(rr.plan_hash,'hex'),'input_digest',encode(st.input_digest,'hex'),'targets',targets);
  INSERT INTO zasp_temporal74.effects VALUES(o,w,e,r,s,1,zasp_temporal74.effect_identity(o,w,e,r,s,1),st.action_key,st.input_digest,rr.plan_hash,snapshot_value,digest(convert_to(snapshot_value::text,'UTF8'),'sha256'),'reserved',NULL,NULL) RETURNING * INTO f;
  UPDATE public.zasp_security_agent_steps SET state='executing',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
  UPDATE public.zasp_security_agent_runs SET state='running',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 END IF;
 IF f.effect_key IS DISTINCT FROM zasp_temporal74.effect_identity(o,w,e,r,s,1) OR (f.input_digest,f.plan_hash,f.action_key) IS DISTINCT FROM(st.input_digest,rr.plan_hash,st.action_key) OR f.snapshot_digest IS DISTINCT FROM digest(convert_to(f.snapshot::text,'UTF8'),'sha256') OR f.snapshot->>'plan_hash' IS DISTINCT FROM encode(rr.plan_hash,'hex') OR f.snapshot->>'input_digest' IS DISTINCT FROM encode(st.input_digest,'hex')
 OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,s,f.action_key,f.input_digest) AND lease_owner IS NULL AND lease_token IS NULL AND lease_expires_at IS NULL)
 OR NOT EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest)=(o,w,e,r,s,f.action_key,f.input_digest)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test effect identity changed';END IF;
 IF op='start' AND f.state='reserved' THEN
  IF NOT EXISTS(SELECT 1 FROM zasp_temporal74.test_inputs WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test immutable input absent';END IF;
  UPDATE zasp_temporal74.effects SET state='started',started_at=clock_timestamp() WHERE effect_key=f.effect_key RETURNING * INTO f;
  UPDATE public.zasp_security_agent_effects SET state='unknown_outcome',version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);permit:=true;
 ELSIF op='unknown' THEN
  IF f.state NOT IN('started','unknown') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test effect not sent';END IF;
  UPDATE zasp_temporal74.effects SET state='unknown' WHERE effect_key=f.effect_key RETURNING * INTO f;
 END IF;
 IF live_value THEN PERFORM zasp_temporal74.current_step(o,w,e,r,s);END IF;
 IF NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='single-test catalog changed';END IF;
 RETURN to_jsonb(f)||jsonb_build_object('send_permit',permit);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.inspect(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;r public.zasp_security_agent_runs%ROWTYPE;j zasp_temporal74.planning_jobs%ROWTYPE;phase text;deadline timestamptz;uncertain boolean;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR zasp_temporal68.principal_ready('zasp_temporal_compensation')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test workflow read rejected';END IF;
 x:=zasp_temporal74.start_identity(q);
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||x.organization_id,0));
 SELECT * INTO STRICT r FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR UPDATE;
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 SELECT deadline_at INTO deadline FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 uncertain:=zasp_temporal74.unresolved(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 IF EXISTS(SELECT 1 FROM zasp_temporal74.parent_receipts WHERE (organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN
  PERFORM zasp_temporal74.parent_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id);phase:=CASE WHEN uncertain THEN 'pending' ELSE 'terminal' END;
 ELSIF EXISTS(SELECT 1 FROM zasp_temporal74.stops WHERE (organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN
  PERFORM zasp_temporal74.stop_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id);phase:=CASE WHEN uncertain THEN 'pending' ELSE 'terminal' END;
 ELSIF j.state='needs_human' THEN
  IF NOT zasp_temporal74.planning_terminal_valid(x.organization_id,x.workspace_id,x.environment_id,x.run_id) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test planning terminal proof changed';END IF;
  phase:=CASE WHEN uncertain THEN 'pending' ELSE 'terminal' END;
 ELSIF r.state IN('cancelled','failed','inconclusive','needs_human') OR deadline<=clock_timestamp() THEN phase:='stopping';
 ELSE
  BEGIN
   PERFORM zasp_temporal74.context(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
   phase:=CASE WHEN j.run_id IS NULL OR j.state<>'admitted' THEN 'planning' WHEN r.state='waiting_approval' THEN 'waiting_approval'
    WHEN EXISTS(SELECT 1 FROM zasp_temporal74.child_receipts WHERE (organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN 'settling' ELSE 'test' END;
  EXCEPTION WHEN SQLSTATE '42501' OR SQLSTATE '40001' THEN phase:='permission_lost';END;
 END IF;
 RETURN jsonb_build_object('phase',phase,'workflow_id',x.workflow_id,'step_id',x.step_id,'action_key',x.action_key,'run_state',r.state,'planning_state',j.state,'deadline',CASE WHEN deadline IS NULL THEN NULL ELSE to_char(deadline AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') END,'unresolved',uncertain);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.invocation(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;child_id text;op text;k text;category_value text;key_value text;payload jsonb;resolution jsonb;request_hash bytea;curated text;result_value jsonb;new_start boolean:=false;parent_value jsonb;
 link public.zasp_security_agent_test_links%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;f zasp_temporal74.effects%ROWTYPE;j zasp_temporal74.invocations%ROWTYPE;prepared zasp_temporal74.test_inputs%ROWTYPE;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor invocation requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_temporal68.adapter_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor invocation principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','effect_key','operation','payload','checksum','fingerprint']) OR octet_length(q::text)>8192
  OR NOT COALESCE(q->>'operation' IN('resolve','start','complete') AND q->>'effect_key'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation scope rejected';END IF;
 END LOOP;
 IF NOT COALESCE(zasp_temporal74.adapter_ready(q->>'checksum',q->>'fingerprint'),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor invocation version rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';child_id:=q->>'run_id';op:=q->>'operation';key_value:=q->>'effect_key';payload:=q->'payload';category_value:=payload->>'category';
 IF NOT zasp_sa_multistep_prior.closed(payload,CASE op WHEN 'resolve' THEN ARRAY['category','target_id','target_kind'] WHEN 'start' THEN ARRAY['category','request_digest'] ELSE ARRAY['category','request_digest','http_status','response_digest','protected','credential_version_digest'] END)
  OR NOT COALESCE(category_value IN('prompt_injection','tool_abuse','data_leakage','authorization_bypass','excessive_agency','sensitive_information'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation payload rejected';END IF;
 SELECT * INTO link FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,child_id);
 IF NOT FOUND OR NOT zasp_temporal74.is_owned(o,w,e,link.run_id) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor invocation owner rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 parent_value:=zasp_temporal74.lock_parent(o,w,e,link.run_id,child_id,key_value);
 SELECT * INTO f FROM zasp_temporal74.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation,effect_key,action_key)=(o,w,e,link.run_id,link.step_id,1,key_value,link.action_key) FOR UPDATE;
 SELECT * INTO child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,child_id) FOR UPDATE NOWAIT;
 SELECT * INTO prepared FROM zasp_temporal74.test_inputs WHERE (organization_id,workspace_id,environment_id,run_id,step_id,test_run_id)=(o,w,e,link.run_id,link.step_id,child_id);
 IF NOT zasp_temporal74.test_intent_valid(o,w,e,link.run_id,link.step_id,parent_value) OR f.run_id IS NULL OR prepared.run_id IS NULL OR child.run_id IS NULL OR f.effect_key IS DISTINCT FROM zasp_temporal74.effect_identity(o,w,e,link.run_id,link.step_id,1)
  OR f.snapshot_digest IS DISTINCT FROM digest(convert_to(f.snapshot::text,'UTF8'),'sha256') OR f.snapshot->'targets'->>'test_run_id' IS DISTINCT FROM child_id
  OR f.snapshot->'targets'->>'input_digest' IS DISTINCT FROM encode(child.input_digest,'hex') OR f.input_digest IS DISTINCT FROM link.input_digest
  OR (link.test_definition_id,link.test_definition_version) IS DISTINCT FROM(child.definition_id,child.definition_version)
  OR NOT link.test_categories ? category_value OR link.test_categories IS DISTINCT FROM f.snapshot->'targets'->'resolution'->'comparison'->'categories'
  OR child.worker_id IS NOT NULL OR child.lease_token IS NOT NULL OR child.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation association changed';END IF;
 PERFORM zasp_sa_multistep_prior.test_validate_input(o,w,e,link.run_id,link.step_id,prepared.manifest,prepared.body);
 resolution:=f.snapshot->'targets'->'resolution';
 IF op<>'complete' THEN
  PERFORM zasp_temporal74.step_parent(o,w,e,link.run_id,link.step_id,parent_value);
  IF child.state<>'queued' OR child.cancel_requested OR link.reconcile_state<>'pending' OR f.state NOT IN('started','unknown')
   OR resolution IS DISTINCT FROM zasp_temporal74.test_target(o,w,e,link.target_id,link.target_kind,link.test_definition_id,link.test_definition_version) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation current authority changed';END IF;
 END IF;
 IF op='resolve' THEN
  IF (payload->>'target_id',payload->>'target_kind') IS DISTINCT FROM(link.target_id,link.target_kind) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation target rejected';END IF;
  result_value:=resolution->'binding';
 ELSE
  IF NOT COALESCE(payload->>'request_digest'~'^[a-f0-9]{64}$',false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation digest rejected';END IF;
  request_hash:=decode(payload->>'request_digest','hex');
  curated:='{"schema_version":"red-team-target-v1","run_id":"'||child_id||'","target_id":"'||link.target_id||'","target_kind":"'||link.target_kind||'","category":"'||category_value||'","input":'||to_json(zasp_sa_multistep_prior.test_prompt(category_value))::text||'}';
  IF request_hash IS DISTINCT FROM digest(convert_to(curated,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor curated invocation rejected';END IF;
  SELECT * INTO j FROM zasp_temporal74.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child_id,category_value) FOR UPDATE;
  IF j.test_run_id IS NOT NULL AND (j.effect_key,j.input_digest,j.request_digest,j.target_resolution) IS DISTINCT FROM(key_value,child.input_digest,request_hash,resolution) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor invocation replay conflict';END IF;
  IF op='start' AND j.state IS DISTINCT FROM 'completed' THEN
   IF f.state<>'started' OR EXISTS(SELECT 1 FROM zasp_temporal74.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,state)=(o,w,e,child_id,'started')) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor invocation outcome unknown';END IF;
   INSERT INTO zasp_temporal74.invocations(organization_id,workspace_id,environment_id,test_run_id,attempt,category,input_digest,request_digest,target_resolution,state,effect_key) VALUES(o,w,e,child_id,1,category_value,child.input_digest,request_hash,resolution,'started',key_value) RETURNING * INTO j;
   new_start:=true;
  ELSIF op='complete' THEN
   IF j.test_run_id IS NULL OR NOT COALESCE(payload->>'response_digest'~'^[a-f0-9]{64}$' AND payload->>'credential_version_digest'~'^[a-f0-9]{64}$' AND payload->>'credential_version_digest'<>repeat('0',64)
    AND jsonb_typeof(payload->'http_status')='number' AND payload->>'http_status'~'^[2-5][0-9]{2}$' AND (payload->'http_status'='200'::jsonb AND jsonb_typeof(payload->'protected')='boolean' OR payload->'http_status'<>'200'::jsonb AND payload->'protected'='null'::jsonb),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor invocation observation rejected';END IF;
   IF j.state='completed' THEN
    IF (j.http_status,j.response_digest,j.protected,j.credential_version_digest) IS DISTINCT FROM((payload->>'http_status')::integer,decode(payload->>'response_digest','hex'),(payload->>'protected')::boolean,decode(payload->>'credential_version_digest','hex')) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor observation replay conflict';END IF;
   ELSE
    UPDATE zasp_temporal74.invocations SET state='completed',completed_at=clock_timestamp(),http_status=(payload->>'http_status')::integer,response_digest=decode(payload->>'response_digest','hex'),protected=(payload->>'protected')::boolean,credential_version_digest=decode(payload->>'credential_version_digest','hex') WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child_id,category_value) RETURNING * INTO j;
   END IF;
  END IF;
  result_value:=jsonb_build_object('state',j.state,'attempt',1,'category',category_value,'input_digest',encode(j.input_digest,'hex'),'request_digest',encode(j.request_digest,'hex'),'target_binding',j.target_resolution->'binding','target_provenance',j.target_resolution->'provenance','target_comparison',j.target_resolution->'comparison','effect_key',j.effect_key);
  IF j.state='completed' THEN result_value:=result_value||jsonb_build_object('run_id',child_id,'http_status',j.http_status,'response_digest',encode(j.response_digest,'hex'),'protected',j.protected,'credential_version_digest',encode(j.credential_version_digest,'hex'),'completed_at',to_char(j.completed_at AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));END IF;
 END IF;
 IF op<>'complete' THEN PERFORM zasp_temporal74.step_parent(o,w,e,link.run_id,link.step_id,parent_value);END IF;
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_temporal68.adapter_principal_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor invocation authority changed';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.late_usage_valid(o text, w text, e text, r text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE l zasp_temporal74.planning_late_usage%ROWTYPE;j zasp_temporal74.planning_jobs%ROWTYPE;p zasp_temporal74.provider_reservations%ROWTYPE;
 a public.zasp_security_agent_audit%ROWTYPE;later public.zasp_security_agent_audit%ROWTYPE;association jsonb;cv jsonb;original jsonb;raw text;
BEGIN
 SELECT * INTO l FROM zasp_temporal74.planning_late_usage WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO p FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_terminal');
 SELECT * INTO later FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_late_usage');
 raw:=l.body->>'raw';association:=l.body->'association';original:=a.body->'reservation';
 IF l.run_id IS NULL OR raw IS NULL OR octet_length(raw) NOT BETWEEN 1 AND 65536 OR NOT zasp_sa_multistep_prior.closed(l.body,ARRAY['raw','association','terminal_digest','reservation','usage'])
  OR NOT zasp_sa_multistep_prior.closed(association,ARRAY['request_digest','credential_digest','reservation_id','response_id','response_digest']) THEN RETURN false;END IF;
 cv:=zasp_temporal74.planning_result(raw,j.lookup_request->>'model',j.context_value);
 RETURN COALESCE(j.state='needs_human' AND a.body->'job'=to_jsonb(j) AND a.event_digest=digest(convert_to(a.body::text,'UTF8'),'sha256')
  AND l.body_digest=digest(convert_to(l.body::text,'UTF8'),'sha256') AND l.body->>'terminal_digest'=encode(a.event_digest,'hex')
  AND later.audit_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_planning_late_usage',r) AND later.correlation_id=later.audit_id AND later.body=l.body AND later.event_digest=l.body_digest
  AND association->>'request_digest'=j.request_digest AND j.request_digest='sha256:'||encode(digest(convert_to(j.request_body,'UTF8'),'sha256'),'hex')
  AND association->>'credential_digest'=j.lookup_request->>'credential_digest' AND association->>'credential_digest'=l.credential_digest
  AND association->>'reservation_id'=j.reservation_id AND p.reservation_id=j.reservation_id
  AND association->>'response_id'=l.response_id AND (raw::jsonb)->>'id'=l.response_id
  AND association->>'response_digest'='sha256:'||encode(digest(convert_to(raw,'UTF8'),'sha256'),'hex')
  AND original->'settled_at'='null'::jsonb AND original->'total_tokens'='null'::jsonb AND original->'cost_nano_credits'='null'::jsonb
  AND to_jsonb(p)-ARRAY['settled_at','output_digest','prompt_tokens','completion_tokens','total_tokens','cost_nano_credits']=original-ARRAY['settled_at','output_digest','prompt_tokens','completion_tokens','total_tokens','cost_nano_credits']
  AND l.body->'reservation'=to_jsonb(p) AND cv->'usage'<>'null'::jsonb AND l.body->'usage'=cv->'usage' AND p.settled_at IS NOT NULL AND p.released_at IS NULL
  AND (p.prompt_tokens,p.completion_tokens,p.total_tokens,p.cost_nano_credits)=((cv->'usage'->>'prompt_tokens')::bigint,(cv->'usage'->>'completion_tokens')::bigint,(cv->'usage'->>'total_tokens')::bigint,(cv->'usage'->>'cost_nano_credits')::bigint)
  AND p.output_digest=digest(convert_to(raw,'UTF8'),'sha256')
  AND (j.raw_result IS NULL OR (j.raw_result::jsonb)-'usage'=(raw::jsonb)-'usage' AND j.result_value->'usage'='null'::jsonb),false);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.linked(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;s text;op text;intent jsonb;p jsonb;doc jsonb;bytes bytea;resolution jsonb;permit boolean:=false;
 link public.zasp_security_agent_test_links%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;prepared zasp_temporal74.test_inputs%ROWTYPE;
BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor linked principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR octet_length(q::text)>131072
  OR NOT COALESCE(q->>'operation' IN('read','input','dispatch'),false) OR jsonb_typeof(q->'payload') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor linked request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';s:=q->>'step_id';op:=q->>'operation';p:=q->'payload';
 intent:=zasp_temporal74.effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 PERFORM zasp_temporal74.current_step(o,w,e,r,s);
 IF intent->>'action_key' NOT IN('run_test','rerun_test') OR intent->>'state' NOT IN('reserved','started','unknown') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked intent unavailable';END IF;
 SELECT * INTO link FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s) FOR UPDATE;
 SELECT * INTO child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link.test_run_id) FOR UPDATE NOWAIT;
 IF child.run_id IS NULL OR child.state<>'queued' OR child.cancel_requested OR child.lease_token IS NOT NULL OR child.worker_id IS NOT NULL OR child.lease_expires_at IS NOT NULL
  OR (link.test_definition_id,link.test_definition_version,link.input_digest,link.action_key) IS DISTINCT FROM(child.definition_id,child.definition_version,decode(intent->'snapshot'->>'input_digest','hex'),intent->>'action_key')
  OR child.run_id IS DISTINCT FROM intent->'snapshot'->'targets'->>'test_run_id' OR encode(child.input_digest,'hex') IS DISTINCT FROM intent->'snapshot'->'targets'->>'input_digest'
  OR link.reconcile_state<>'pending' OR link.reconcile_token IS NOT NULL OR link.reconcile_worker IS NOT NULL OR link.reconcile_expires_at IS NOT NULL OR link.reconcile_settlement IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked association changed';END IF;
 resolution:=zasp_temporal74.test_target(o,w,e,link.target_id,link.target_kind,link.test_definition_id,link.test_definition_version);
 IF resolution IS DISTINCT FROM intent->'snapshot'->'targets'->'resolution' OR link.test_categories IS DISTINCT FROM resolution->'comparison'->'categories' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked target changed';END IF;
 SELECT * INTO prepared FROM zasp_temporal74.test_inputs WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF op='input' THEN
  IF NOT zasp_sa_multistep_prior.closed(p,ARRAY['manifest','body']) OR jsonb_typeof(p->'body') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor linked input rejected';END IF;
  bytes:=decode(p->>'body','base64');doc:=zasp_sa_multistep_prior.test_validate_input(o,w,e,r,s,p->'manifest',bytes);
  IF prepared.run_id IS NULL THEN
   IF intent->>'state'<>'reserved' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked input too late';END IF;
   INSERT INTO zasp_temporal74.test_inputs VALUES(o,w,e,r,s,child.run_id,p->'manifest',bytes) RETURNING * INTO prepared;
  ELSIF (prepared.manifest,prepared.body) IS DISTINCT FROM(p->'manifest',bytes) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked input replay changed';END IF;
 ELSIF p<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor linked unexpected payload';
 ELSIF op='dispatch' THEN
  IF prepared.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor linked input absent';END IF;
  PERFORM zasp_sa_multistep_prior.test_validate_input(o,w,e,r,s,prepared.manifest,prepared.body);
  intent:=zasp_temporal74.effect(q||jsonb_build_object('operation','start','payload','{}'::jsonb));permit:=(intent->>'send_permit')::boolean;
 END IF;
 PERFORM zasp_temporal74.current_step(o,w,e,r,s);
 IF NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='executor linked catalog changed';END IF;
 RETURN jsonb_build_object('effect_key',intent->>'effect_key','generation',1,'test_run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),'definition_id',child.definition_id,'definition_version',child.definition_version,'target_id',link.target_id,'target_kind',link.target_kind,'categories',link.test_categories,'target_resolution',resolution,'input_manifest',prepared.manifest,'input_body',convert_from(prepared.body,'UTF8'),'send_permit',permit);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.load_plan(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;k text;rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;job zasp_temporal74.planning_jobs%ROWTYPE;tr public.zasp_security_agent_trigger_receipts%ROWTYPE;cv jsonb;now_value timestamptz;BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor authority unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','operation']) OR q->>'operation'<>'load'
  OR q->>'definition_version'!~'^([1-9][0-9]{0,5}|1000000)$' OR jsonb_typeof(q->'definition_version')<>'number' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor plan request rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP
  IF jsonb_typeof(q->k)<>'string' OR NOT public.zasp_valid_product_id(q->>k) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor scope rejected';END IF;
 END LOOP;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR rr.definition_version<>(q->>'definition_version')::bigint OR NOT zasp_temporal74.is_owned(o,w,e,r)
  OR rr.lease_token IS NOT NULL OR rr.lease_owner IS NOT NULL OR rr.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor run unavailable';END IF;
 SELECT * INTO job FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN
  IF rr.state<>'queued' OR rr.attempt<>0 OR rr.version<>1 OR rr.available_at>clock_timestamp() OR rr.plan_hash IS NOT NULL OR b.run_id IS NOT NULL
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
   OR EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor run not fresh';END IF;
  SELECT * INTO tr FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(o,w,e,r,rr.definition_id,rr.trigger_id) FOR SHARE;
  IF NOT FOUND OR NOT EXISTS(SELECT 1 FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,trigger_version,input_digest)=(o,w,e,r,rr.definition_id,rr.definition_version,tr.trigger_id,tr.trigger_version,encode(tr.trigger_digest,'hex'))) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor trigger identity rejected';END IF;
  UPDATE public.zasp_security_agent_runs SET state='planning',attempt=1,version=2 WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO rr;
  cv:=zasp_temporal74.context(o,w,e,r);
  IF octet_length(cv::text)>65536 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor input too large';END IF;
  IF zasp_temporal68.active_count(o,'planning',NULL)>(cv->'definition'->>'concurrency_limit')::integer THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor concurrency exceeded';END IF;
  now_value:=clock_timestamp();
  INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
  INSERT INTO public.zasp_security_agent_run_budgets(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,started_at,deadline_at,max_steps,max_tokens,max_cost_nano_credits,concurrency_limit)
   VALUES(o,w,e,r,rr.definition_id,rr.definition_version,now_value,now_value+make_interval(secs=>(cv->'definition'->>'max_duration_seconds')::integer),1,(cv->'definition'->>'ai_token_budget')::bigint,(cv->'definition'->>'max_ai_cost_nano_credits')::bigint,(cv->'definition'->>'concurrency_limit')::integer) RETURNING * INTO b;
  INSERT INTO zasp_temporal74.planning_jobs VALUES(o,w,e,r,rr.definition_version,rr.version,'loaded',b.started_at,b.deadline_at,cv,cv::text,'sha256:'||encode(digest(convert_to(cv::text,'UTF8'),'sha256'),'hex'),public.zasp_discovery_canonical_id(o,w,e,'security_agent_planning_input',r),public.zasp_discovery_canonical_id(o,w,e,'security_agent_planning_output',r),public.zasp_discovery_canonical_id(o,w,e,'security_agent_planning_reservation',r)) RETURNING * INTO job;
 END IF;
 IF rr.state<>'planning' OR rr.version<>job.run_version OR b.stop_reason IS NOT NULL OR b.deadline_at<=clock_timestamp()
  OR zasp_temporal74.context(o,w,e,r) IS DISTINCT FROM job.context_value OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor planning authority changed';END IF;
 RETURN to_jsonb(job);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.plan(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;op text;payload jsonb;job zasp_temporal74.planning_jobs%ROWTYPE;
 rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;reservation zasp_temporal74.provider_reservations%ROWTYPE;
 selection jsonb;body_value text;bound_value jsonb;cv jsonb;reason text;receipt_value jsonb;send_value boolean:=false;
BEGIN
 IF q->>'operation'='reconcile' THEN RETURN zasp_temporal74.recover_plan(q);END IF;
 IF q->>'operation'='late_usage' THEN RETURN zasp_temporal74.record_late_usage(q);END IF;
 IF q->>'operation'='load' THEN RETURN zasp_temporal74.load_plan(q);END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor planning requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT zasp_temporal74.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor planning unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','operation','payload']) OR octet_length(q::text)>524288
  OR q->>'operation' NOT IN('prepare','start','result','settle','artifacts','admit') OR jsonb_typeof(q->'payload')<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor planning request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';op:=q->>'operation';payload:=q->'payload';
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO job FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR NOT zasp_temporal74.is_owned(o,w,e,r) OR q->'definition_version' IS DISTINCT FROM to_jsonb(job.definition_version)
  OR rr.lease_owner IS NOT NULL OR rr.lease_token IS NOT NULL OR rr.lease_expires_at IS NOT NULL
  OR NOT(rr.state='planning' AND rr.version=job.run_version OR op='admit' AND job.state='admitted' AND rr.state IN('queued','waiting_approval') AND rr.version=job.run_version+1)
  OR b.run_id IS NULL OR b.stop_reason IS NOT NULL OR b.deadline_at<=clock_timestamp() OR (b.started_at,b.deadline_at) IS DISTINCT FROM (job.budget_started_at,job.budget_deadline_at)
  OR (b.definition_id,b.definition_version,b.max_steps,b.max_tokens,b.max_cost_nano_credits,b.concurrency_limit) IS DISTINCT FROM (rr.definition_id,rr.definition_version,1,(job.context_value->'definition'->>'ai_token_budget')::bigint,(job.context_value->'definition'->>'max_ai_cost_nano_credits')::bigint,(job.context_value->'definition'->>'concurrency_limit')::integer)
  OR zasp_temporal74.context(o,w,e,r) IS DISTINCT FROM job.context_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor planning authority changed';END IF;
 SELECT * INTO reservation FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1) FOR UPDATE;
 IF op IN('start','settle','admit') AND payload<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor planning unexpected payload';END IF;
 IF op='prepare' THEN
  IF NOT zasp_sa_multistep_prior.closed(payload,ARRAY['pricing','input_version']) OR jsonb_typeof(payload->'input_version')<>'string' OR length(payload->>'input_version') NOT BETWEEN 1 AND 1024 OR payload->>'input_version'!~'^[!-~]+$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor input artifact rejected';END IF;
  selection:=payload->'pricing';body_value:=zasp_temporal74.planning_body(job.context_value,selection);
  selection:=selection||jsonb_build_object('body',body_value,'body_digest','sha256:'||encode(digest(convert_to(body_value,'UTF8'),'sha256'),'hex'));
  IF (selection->>'organization_id',selection->>'workspace_id',selection->>'environment_id') IS DISTINCT FROM (o,w,e) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor pricing scope rejected';END IF;
  bound_value:=zasp_temporal74.pricing_lookup('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',selection);
  IF job.state='loaded' THEN
   IF reservation.run_id IS NOT NULL OR (bound_value->>'maximum_tokens')::bigint>b.max_tokens OR (bound_value->>'maximum_cost_nano_credits')::bigint>b.max_cost_nano_credits THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor pricing exceeds budget';END IF;
   INSERT INTO zasp_temporal74.provider_reservations(organization_id,workspace_id,environment_id,run_id,attempt,reservation_id,input_digest,model,cost_policy_version,cost_unit,maximum_tokens,maximum_cost_nano_credits)
    VALUES(o,w,e,r,1,job.reservation_id,decode(substring(job.input_digest FROM 8),'hex'),selection->>'model',bound_value->>'cost_policy_version','openrouter_credit',(bound_value->>'maximum_tokens')::bigint,(bound_value->>'maximum_cost_nano_credits')::bigint);
   UPDATE zasp_temporal74.planning_jobs SET state='prepared',request_body=body_value,request_digest=selection->>'body_digest',lookup_request=selection,pricing_bound=bound_value,input_version=payload->>'input_version' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
  ELSIF job.lookup_request IS DISTINCT FROM selection OR job.input_version IS DISTINCT FROM payload->>'input_version' OR job.pricing_bound IS DISTINCT FROM bound_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor intent conflict';END IF;
 END IF;
 IF job.lookup_request IS NOT NULL THEN
  IF job.request_body IS DISTINCT FROM zasp_temporal74.planning_body(job.context_value,job.lookup_request) OR job.request_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.request_body,'UTF8'),'sha256'),'hex') OR job.pricing_bound IS DISTINCT FROM zasp_temporal74.pricing_lookup('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',job.lookup_request) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor pricing drift';END IF;
  SELECT * INTO reservation FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1) FOR UPDATE;
  IF (reservation.reservation_id,reservation.input_digest,reservation.model,reservation.cost_policy_version,reservation.maximum_tokens,reservation.maximum_cost_nano_credits) IS DISTINCT FROM (job.reservation_id,decode(substring(job.input_digest FROM 8),'hex'),job.lookup_request->>'model',job.pricing_bound->>'cost_policy_version',(job.pricing_bound->>'maximum_tokens')::bigint,(job.pricing_bound->>'maximum_cost_nano_credits')::bigint) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor reservation drift';END IF;
  IF reservation.settled_at IS NOT NULL AND (reservation.output_digest,reservation.prompt_tokens,reservation.completion_tokens,reservation.total_tokens,reservation.cost_nano_credits) IS DISTINCT FROM (decode(substring(job.provider_digest FROM 8),'hex'),(job.result_value->'usage'->>'prompt_tokens')::bigint,(job.result_value->'usage'->>'completion_tokens')::bigint,(job.result_value->'usage'->>'total_tokens')::bigint,(job.result_value->'usage'->>'cost_nano_credits')::bigint) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor settlement differs from provider evidence';END IF;
 END IF;
 IF op='start' THEN
  IF job.state='prepared' THEN UPDATE zasp_temporal74.planning_jobs SET state='started' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;send_value:=true;
  ELSIF job.state<>'started' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor send unavailable';END IF;
 ELSIF op='result' THEN
  IF NOT zasp_sa_multistep_prior.closed(payload,ARRAY['raw']) OR jsonb_typeof(payload->'raw')<>'string' OR octet_length(payload->>'raw') NOT BETWEEN 1 AND 65536 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor result rejected';END IF;
  IF job.state='started' THEN
   cv:=zasp_temporal74.planning_result(payload->>'raw',job.lookup_request->>'model',job.context_value);body_value:=jsonb_build_object('raw',payload->>'raw','candidate',cv->'candidate')::text;
   UPDATE zasp_temporal74.planning_jobs SET state='completed',raw_result=payload->>'raw',result_value=cv,provider_digest='sha256:'||encode(digest(convert_to(payload->>'raw','UTF8'),'sha256'),'hex'),output_body=body_value,output_digest='sha256:'||encode(digest(convert_to(body_value,'UTF8'),'sha256'),'hex') WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
  ELSIF job.raw_result IS DISTINCT FROM payload->>'raw' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor result immutable';END IF;
 ELSIF op='settle' THEN
  IF job.state NOT IN('completed','settled','artifacts') OR job.result_value IS DISTINCT FROM zasp_temporal74.planning_result(job.raw_result,job.lookup_request->>'model',job.context_value) OR job.provider_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.raw_result,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor settlement unavailable';END IF;
  IF job.state='completed' THEN
   cv:=job.result_value->'usage';
   IF cv='null'::jsonb THEN reason:='budget_usage_unknown';ELSE
    UPDATE zasp_temporal74.provider_reservations SET settled_at=clock_timestamp(),output_digest=decode(substring(job.provider_digest FROM 8),'hex'),prompt_tokens=(cv->>'prompt_tokens')::bigint,completion_tokens=(cv->>'completion_tokens')::bigint,total_tokens=(cv->>'total_tokens')::bigint,cost_nano_credits=(cv->>'cost_nano_credits')::bigint WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);
    IF (cv->>'total_tokens')::bigint>least(reservation.maximum_tokens,b.max_tokens) THEN reason:='budget_tokens_exceeded';ELSIF (cv->>'cost_nano_credits')::bigint>least(reservation.maximum_cost_nano_credits,b.max_cost_nano_credits) THEN reason:='budget_cost_exceeded';END IF;
   END IF;
   UPDATE zasp_temporal74.planning_jobs SET state='settled' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
   IF reason IS NOT NULL OR job.result_value->'candidate'='null'::jsonb THEN
    IF reason IS NOT NULL THEN UPDATE public.zasp_security_agent_run_budgets SET stop_reason=reason WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
    PERFORM zasp_temporal74.planning_terminal(o,w,e,r,coalesce(reason,'planner_rejected'));
    SELECT * INTO job FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
   END IF;
  END IF;
 ELSIF op='artifacts' THEN
  IF job.state NOT IN('settled','artifacts') OR NOT zasp_sa_multistep_prior.closed(payload,ARRAY['input_version','output_version','output_digest']) OR payload->>'input_version' IS DISTINCT FROM job.input_version OR payload->>'output_digest' IS DISTINCT FROM job.output_digest OR jsonb_typeof(payload->'output_version')<>'string' OR length(payload->>'output_version') NOT BETWEEN 1 AND 1024 OR payload->>'output_version'!~'^[!-~]+$' OR job.output_version IS NOT NULL AND job.output_version IS DISTINCT FROM payload->>'output_version' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor artifact conflict';END IF;
  UPDATE zasp_temporal74.planning_jobs SET state='artifacts',output_version=payload->>'output_version' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
 ELSIF op='admit' THEN
  IF job.state NOT IN('artifacts','admitted') OR job.output_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.output_body,'UTF8'),'sha256'),'hex') OR job.output_body IS DISTINCT FROM jsonb_build_object('raw',job.raw_result,'candidate',job.result_value->'candidate')::text THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor immutable result unavailable';END IF;
  receipt_value:=zasp_temporal74.admit('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'definition_id',rr.definition_id,'definition_version',rr.definition_version,'trigger_id',rr.trigger_id,'attempt',1,'run_version',job.run_version,'input_digest',job.input_digest,'output_digest',job.provider_digest,'model',job.lookup_request->>'model','policy_version',job.lookup_request->>'request_policy_version','candidate',job.result_value->'candidate'));
  UPDATE zasp_temporal74.planning_jobs SET state='admitted',receipt=receipt_value WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
 END IF;
 IF b.deadline_at<=clock_timestamp() OR zasp_temporal74.context(o,w,e,r) IS DISTINCT FROM job.context_value OR NOT zasp_temporal74.current_ready() OR job.lookup_request IS NOT NULL AND job.pricing_bound IS DISTINCT FROM zasp_temporal74.pricing_lookup('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',job.lookup_request) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor planning authority expired after wait';END IF;
 IF op='admit' THEN RETURN job.receipt;END IF;
 IF op='start' THEN RETURN to_jsonb(job)||jsonb_build_object('send_permit',send_value);END IF;
 RETURN to_jsonb(job);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.planning_state(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;j zasp_temporal74.planning_jobs%ROWTYPE;k text;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR zasp_temporal68.principal_ready('zasp_temporal_compensation')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test planning read rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version']) OR octet_length(q::text)>4096 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test planning read shape rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test planning read scope rejected';END IF;END LOOP;
 SELECT * INTO x FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') AND to_jsonb(definition_version)=q->'definition_version';
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test planning owner changed';END IF;
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id,definition_version)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.definition_version);
 IF NOT FOUND THEN RETURN 'null'::jsonb;END IF;
 RETURN to_jsonb(j);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.planning_terminal_valid(o text, w text, e text, r text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a public.zasp_security_agent_audit%ROWTYPE;j zasp_temporal74.planning_jobs%ROWTYPE;p zasp_temporal74.provider_reservations%ROWTYPE;
BEGIN
 SELECT * INTO j FROM zasp_temporal74.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO p FROM zasp_temporal74.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_terminal');
 IF EXISTS(SELECT 1 FROM zasp_temporal74.planning_late_usage WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN
  IF NOT zasp_temporal74.late_usage_valid(o,w,e,r) THEN RETURN false;END IF;
  -- The first terminal evidence remains authoritative for what was known at
  -- that instant. The separate immutable ledger proves the later charge.
  p:=jsonb_populate_record(NULL::zasp_temporal74.provider_reservations,a.body->'reservation');
 END IF;
 RETURN COALESCE(j.state='needs_human' AND a.audit_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_planning_terminal',r) AND a.correlation_id=a.audit_id AND a.event_digest=digest(convert_to(a.body::text,'UTF8'),'sha256')
  AND a.body=jsonb_build_object('job',to_jsonb(j),'reservation',CASE WHEN p.run_id IS NULL THEN 'null'::jsonb ELSE to_jsonb(p) END,'reason',(SELECT last_error_code FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)),'dispatch_state',a.body->>'dispatch_state')
  AND j.input_digest='sha256:'||encode(digest(convert_to(j.input_body,'UTF8'),'sha256'),'hex') AND j.input_body=j.context_value::text
  AND CASE WHEN a.body->>'reason'='planner_not_sent' THEN j.raw_result IS NULL AND j.result_value IS NULL AND j.provider_digest IS NULL AND j.output_body IS NULL AND j.output_digest IS NULL
   AND (a.body->>'dispatch_state'='loaded' AND j.lookup_request IS NULL AND j.pricing_bound IS NULL AND j.request_body IS NULL AND j.request_digest IS NULL AND j.input_version IS NULL AND p.run_id IS NULL
    OR a.body->>'dispatch_state'='prepared' AND j.lookup_request IS NOT NULL AND j.pricing_bound IS NOT NULL AND j.input_version IS NOT NULL AND p.released_at IS NOT NULL AND p.settled_at IS NULL AND p.output_digest IS NULL AND p.total_tokens IS NULL AND p.cost_nano_credits IS NULL)
   ELSE a.body->>'dispatch_state' IN('started','completed','settled','artifacts') AND p.released_at IS NULL
    AND (j.raw_result IS NULL AND p.settled_at IS NULL AND p.total_tokens IS NULL AND p.cost_nano_credits IS NULL OR j.raw_result IS NOT NULL AND j.provider_digest='sha256:'||encode(digest(convert_to(j.raw_result,'UTF8'),'sha256'),'hex') AND j.result_value=zasp_temporal74.planning_result(j.raw_result,j.lookup_request->>'model',j.context_value)
     AND (j.result_value->'usage'='null'::jsonb AND p.settled_at IS NULL OR j.result_value->'usage'<>'null'::jsonb AND p.settled_at IS NOT NULL AND (p.total_tokens,p.cost_nano_credits)=((j.result_value->'usage'->>'total_tokens')::bigint,(j.result_value->'usage'->>'cost_nano_credits')::bigint))) END,false);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.takeover(o text, w text, e text, r text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE rr public.zasp_security_agent_runs%ROWTYPE;d public.zasp_security_agent_definitions%ROWTYPE;h public.zasp_security_agent_definition_versions%ROWTYPE;
 t public.zasp_security_agent_trigger_receipts%ROWTYPE;x zasp_temporal74.run_owners%ROWTYPE;source_value text;step_value text;child_value text;binding jsonb;trigger_value jsonb;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='test ownership requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='test ownership principal rejected';END IF;
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(r),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='test ownership scope rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND THEN RETURN 'null'::jsonb;END IF;
 SELECT * INTO x FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF FOUND THEN RETURN to_jsonb(x);END IF;
 IF rr.state<>'queued' OR rr.version<>1 OR rr.attempt<>0 OR rr.plan_hash IS NOT NULL OR rr.lease_owner IS NOT NULL OR rr.lease_token IS NOT NULL OR rr.lease_expires_at IS NOT NULL OR rr.completed_at IS NOT NULL
  OR zasp_temporal66.is_temporal(o,w,e,r)
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_plans WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_steps WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR EXISTS(SELECT 1 FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r))
  OR EXISTS(SELECT 1 FROM zasp_temporal68.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN RETURN 'null'::jsonb;END IF;
 SELECT * INTO d FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,rr.definition_id,rr.definition_version) AND deleted_at IS NULL FOR SHARE;
 SELECT * INTO h FROM public.zasp_security_agent_definition_versions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,rr.definition_id,rr.definition_version) FOR SHARE;
 SELECT * INTO t FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,run_id,definition_id,trigger_id)=(o,w,e,r,rr.definition_id,rr.trigger_id) FOR SHARE;
 IF d.definition_id IS NULL OR h.definition_id IS NULL OR t.run_id IS NULL OR d.body->'allowed_actions' NOT IN('["run_test"]'::jsonb,'["rerun_test"]'::jsonb)
  OR d.activation NOT IN('supervised','autonomous') OR d.body->>'autonomy' IS DISTINCT FROM d.activation OR d.body->'enabled' IS DISTINCT FROM 'true'::jsonb OR NOT COALESCE(d.body->'environment_ids'?e,false)
  OR (h.activation,h.definition) IS DISTINCT FROM(d.activation,d.body) OR h.definition_digest IS DISTINCT FROM digest(convert_to(d.body::text,'UTF8'),'sha256') THEN RETURN 'null'::jsonb;END IF;
 IF t.trigger_kind='manual' THEN
  IF NOT EXISTS(SELECT 1 FROM zasp_temporal65.commands c JOIN zasp_temporal66.run_owners old USING(organization_id,workspace_id,environment_id,run_id) WHERE (c.organization_id,c.workspace_id,c.environment_id,c.run_id,c.kind,c.definition_version,c.input_digest,c.execution_owner,old.execution_owner)=(o,w,e,r,'start',rr.definition_version,encode(t.trigger_digest,'hex'),'legacy','legacy') AND (old.definition_version,old.input_digest)=(c.definition_version,c.input_digest) AND c.accepted_at IS NULL) THEN RETURN 'null'::jsonb;END IF;
  PERFORM public.zasp_sa_manual_provenance(o,w,e,r);
  PERFORM zasp_temporal74.human(o,w,e,rr.requested_by);
  source_value:='manual65';
 ELSIF EXISTS(SELECT 1 FROM zasp_temporal76.admissions m JOIN zasp_temporal65.commands c ON(c.organization_id,c.workspace_id,c.environment_id,c.event_id)=(m.organization_id,m.workspace_id,m.environment_id,m.event_id)
  WHERE(m.organization_id,m.workspace_id,m.environment_id,m.run_id,m.definition_id,m.definition_version,m.requester_id,m.source_kind,m.trigger_id,m.trigger_version,m.input_digest,c.kind,c.execution_owner)=(o,w,e,r,rr.definition_id,rr.definition_version,rr.requested_by,'resource65',t.trigger_id,t.trigger_version,encode(t.trigger_digest,'hex'),'start','legacy') AND c.accepted_at IS NULL) THEN
  PERFORM zasp_temporal74.human(o,w,e,rr.requested_by);
  trigger_value:=public.zasp_production_security_agent_existing_tests_trigger(o,w,e,t.trigger_kind,t.trigger_id,d.body->>'trigger_source',t.trigger_version);
  IF t.trigger_kind IS DISTINCT FROM d.body->>'trigger_kind' OR trigger_value->>'digest' IS DISTINCT FROM encode(t.trigger_digest,'hex') THEN RETURN 'null'::jsonb;END IF;
  source_value:='resource65';
 ELSE
  IF NOT EXISTS(SELECT 1 FROM zasp_temporal73.admissions a JOIN zasp_temporal73.commands c USING(organization_id,workspace_id,environment_id,run_id) WHERE (a.organization_id,a.workspace_id,a.environment_id,a.run_id,a.definition_id,a.definition_version,a.trigger_id,a.trigger_version,a.trigger_digest,a.execution_owner,c.revision,c.kind)=(o,w,e,r,rr.definition_id,rr.definition_version,t.trigger_id,t.trigger_version,t.trigger_digest,'retained_single_action',1,'start')) THEN RETURN 'null'::jsonb;END IF;
  PERFORM zasp_temporal74.authorize(o,w,e,rr.definition_id,rr.definition_version);
  trigger_value:=public.zasp_production_security_agent_existing_tests_trigger(o,w,e,t.trigger_kind,t.trigger_id,d.body->>'trigger_source',t.trigger_version);
  IF trigger_value->>'digest' IS DISTINCT FROM encode(t.trigger_digest,'hex') THEN RETURN 'null'::jsonb;END IF;
  source_value:='automatic73';
 END IF;
 binding:=zasp_temporal71.body21(o,w,e,rr.definition_id,rr.definition_version);
 PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,d.body->'allowed_actions'->>0);
 step_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_step',r||chr(31)||'0');
 child_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_run',r||chr(31)||step_value||chr(31)||(d.body->'allowed_actions'->>0));
 IF EXISTS(SELECT 1 FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,child_value)) THEN RETURN 'null'::jsonb;END IF;
 INSERT INTO zasp_temporal74.run_owners(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,source_kind,trigger_id,trigger_version,input_digest,action_key,step_id,test_run_id,workflow_id)
 VALUES(o,w,e,r,rr.definition_id,rr.definition_version,source_value,t.trigger_id,t.trigger_version,encode(t.trigger_digest,'hex'),d.body->'allowed_actions'->>0,step_value,child_value,'security-agent-test/v1/'||o||'/'||w||'/'||e||'/'||r) RETURNING * INTO x;
 RETURN to_jsonb(x);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.test_settle(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text:=q->>'organization_id';w text:=q->>'workspace_id';e text:=q->>'environment_id';r text:=q->>'run_id';s text:=q->>'step_id';op text:=q->>'operation';p jsonb:=q->'payload';intent jsonb;body bytea;summary jsonb;snapshot_value jsonb;snapshot_hash bytea;proof jsonb;proof_hash bytea;receipt jsonb;key_value text;audit_id text;invocation_id text;completed_value timestamptz;outcome text;parent_state text;step_state text;effect_state text;unknown_value boolean;
 rr public.zasp_security_agent_runs%ROWTYPE;c public.zasp_red_team_runs%ROWTYPE;i zasp_temporal74.test_inputs%ROWTYPE;t zasp_temporal74.child_receipts%ROWTYPE;pr zasp_temporal74.parent_receipts%ROWTYPE;
BEGIN
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test settlement principal rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR octet_length(q::text)>1600000 OR NOT COALESCE(op IN('child','snapshot','complete'),false)
  OR NOT zasp_sa_multistep_prior.closed(p,CASE op WHEN 'child' THEN ARRAY['output_manifest','output_body'] WHEN 'complete' THEN ARRAY['snapshot','proof_body'] ELSE ARRAY[]::text[] END)
 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test settlement request rejected';END IF;
 intent:=zasp_temporal74.effect(q||jsonb_build_object('operation','read','payload','{}'::jsonb));
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 IF NOT zasp_temporal74.test_intent_valid(o,w,e,r,s,to_jsonb(rr)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test settlement identity rejected';END IF;
 SELECT * INTO STRICT i FROM zasp_temporal74.test_inputs WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO STRICT c FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,i.test_run_id) FOR UPDATE NOWAIT;
 SELECT * INTO t FROM zasp_temporal74.child_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF op='child' THEN
  IF jsonb_typeof(p->'output_body') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test child artifact absent';END IF;
  body:=decode(p->>'output_body','base64');
  IF t.run_id IS NOT NULL THEN
   IF (t.output_manifest,t.output_body) IS DISTINCT FROM(p->'output_manifest',body) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test child replay changed';END IF;
   RETURN zasp_temporal74.child_evidence(o,w,e,r,s);
  END IF;
  IF intent->>'state' NOT IN('started','unknown') OR c.state<>'queued' OR c.cancel_requested OR c.attempt<>0 OR c.worker_id IS NOT NULL OR c.lease_token IS NOT NULL OR c.lease_expires_at IS NOT NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test child completion unavailable';END IF;
  summary:=zasp_temporal74.test_validate_output(o,w,e,r,s,i.manifest,i.body,p->'output_manifest',body);
  completed_value:=clock_timestamp();key_value:='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||c.run_id;
  INSERT INTO public.zasp_red_team_attempts(organization_id,workspace_id,environment_id,run_id,attempt,input_digest,verdict,objective,behavior,error_code,evidence,evidence_reference,evidence_key,evidence_version_id,evidence_checksum,evidence_size,input_artifact,completed_at)
  VALUES(o,w,e,c.run_id,1,c.input_digest,summary->>'verdict',summary->>'objective',summary->>'behavior',NULL,summary->'evidence',p->'output_manifest'->>'reference',key_value,p->'output_manifest'->>'version_id',digest(body,'sha256'),octet_length(body),i.manifest,completed_value);
  UPDATE public.zasp_red_team_runs SET state='complete',attempt=1,version=version+1,verdict=summary->>'verdict',evidence_reference=p->'output_manifest'->>'reference',evidence_key=key_value,evidence_version_id=p->'output_manifest'->>'version_id',evidence_checksum=digest(body,'sha256'),evidence_size=octet_length(body),started_at=(intent->>'started_at')::timestamptz,completed_at=completed_value,updated_at=completed_value WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,c.run_id);
  snapshot_value:=zasp_temporal74.test_snapshot(o,w,e,r,s,p->'output_manifest');snapshot_hash:=digest(convert_to(snapshot_value::text,'UTF8'),'sha256');
  receipt:=jsonb_build_object('test_run_id',c.run_id,'state','complete','attempt',1,'effect_key',intent->>'effect_key','output_manifest',p->'output_manifest','snapshot_digest',encode(snapshot_hash,'hex'));
  INSERT INTO zasp_temporal74.child_receipts VALUES(o,w,e,r,s,c.run_id,intent->>'effect_key',p->'output_manifest',body,snapshot_value,snapshot_hash,receipt);
  RETURN zasp_temporal74.child_evidence(o,w,e,r,s);
 END IF;
 PERFORM zasp_temporal74.child_evidence(o,w,e,r,s);
 -- Lock pinned historical evidence without waiting in inverse parent order.
 PERFORM 1 FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id)=(o,w,e) AND run_id=(SELECT baseline->>'run_id' FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s)) FOR SHARE NOWAIT;
 snapshot_value:=zasp_temporal74.evidence_snapshot(o,w,e,r,s);
 IF op='snapshot' THEN RETURN snapshot_value;END IF;
 IF jsonb_typeof(p->'proof_body') IS DISTINCT FROM 'string' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test proof absent';END IF;
 body:=decode(p->>'proof_body','base64');proof:=zasp_sa_multistep_prior.test_json(body,65536);proof_hash:=digest(body,'sha256');
 SELECT * INTO pr FROM zasp_temporal74.parent_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 IF pr.run_id IS NOT NULL THEN
  IF (pr.snapshot,pr.proof_body) IS DISTINCT FROM(p->'snapshot',body) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test parent replay changed';END IF;
  RETURN zasp_temporal74.parent_evidence(o,w,e,r,s);
 END IF;
 IF snapshot_value IS DISTINCT FROM p->'snapshot' OR rr.state NOT IN('running','verifying','cancelled','failed','inconclusive','needs_human') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test comparison snapshot changed';END IF;
 unknown_value:=COALESCE((snapshot_value->'before'->>'outcome_unknown')::boolean,false) OR COALESCE((snapshot_value->'after'->>'outcome_unknown')::boolean,false);
 PERFORM public.zasp_production_security_agent_existing_tests_validate_proof(snapshot_value,proof,unknown_value);
 outcome:=proof->>'outcome';parent_state:=CASE WHEN rr.state IN('cancelled','failed','inconclusive','needs_human') THEN rr.state ELSE outcome END;
 step_state:=CASE WHEN parent_state IN('remediated','needs_human') THEN 'succeeded' ELSE parent_state END;
 effect_state:=CASE WHEN unknown_value THEN 'unknown_outcome' WHEN parent_state='remediated' THEN 'verified' WHEN parent_state IN('failed','cancelled') THEN 'known_failure' ELSE 'succeeded' END;
 invocation_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_test_invocation',intent->>'effect_key');
 receipt:=jsonb_build_object('run_id',r,'step_id',s,'state',parent_state,'step_state',step_state,'effect_state',effect_state,'outcome',outcome,'reason',proof->>'reason','proof_sha256',encode(proof_hash,'hex'),'reconcile_version',2,'effect_key',intent->>'effect_key','invocation_id',invocation_id);
 UPDATE public.zasp_security_agent_effects SET state=effect_state,result_digest=proof_hash,outcome_id=invocation_id,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE public.zasp_security_agent_steps SET state=step_state,version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 UPDATE public.zasp_security_agent_runs SET state=parent_state,last_error_code=proof->>'reason',completed_at=COALESCE(completed_at,clock_timestamp()),version=version+1,updated_at=clock_timestamp() WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 UPDATE zasp_temporal74.effects SET state='verified',completed_at=clock_timestamp() WHERE effect_key=intent->>'effect_key';
 UPDATE public.zasp_security_agent_test_links SET reconcile_state='settled',reconcile_version=2,reconcile_settlement=jsonb_build_object('effect_key',intent->>'effect_key','snapshot',snapshot_value,'proof_hex',encode(body,'hex'),'proof',proof,'receipt',receipt) WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 INSERT INTO zasp_temporal74.parent_receipts VALUES(o,w,e,r,s,intent->>'effect_key',snapshot_value,body,receipt);
 audit_id:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_test_settlement',r||chr(31)||s);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(o,w,e,audit_id,audit_id,r,s,session_user,'test_reconciled',proof_hash,receipt);
 RETURN zasp_temporal74.parent_evidence(o,w,e,r,s);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.test_state(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal74.run_owners%ROWTYPE;f zasp_temporal74.effects%ROWTYPE;state_value text;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal74.current_ready() OR NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR zasp_temporal68.principal_ready('zasp_temporal_compensation')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test state authority rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','step_id','generation','operation','payload']) OR octet_length(q::text)>4096 OR q->'generation' IS DISTINCT FROM '1'::jsonb OR q->>'operation' IS DISTINCT FROM 'read' OR q->'payload' IS DISTINCT FROM '{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test state request rejected';END IF;
 SELECT * INTO x FROM zasp_temporal74.run_owners WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id',q->>'step_id');
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test state owner rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||x.organization_id,0));
 PERFORM 1 FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test state parent absent';END IF;
 SELECT * INTO f FROM zasp_temporal74.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,1);
 state_value:='absent';
 IF f.run_id IS NOT NULL THEN
  PERFORM zasp_temporal74.effect(q);state_value:=f.state;
  IF EXISTS(SELECT 1 FROM zasp_temporal74.parent_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id)) THEN
   PERFORM zasp_temporal74.parent_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id);state_value:='verified';
  ELSIF EXISTS(SELECT 1 FROM zasp_temporal74.child_receipts WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id)) THEN
   PERFORM zasp_temporal74.child_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id);state_value:='child';
  ELSIF f.state='verified' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test verified proof absent';END IF;
 END IF;
 RETURN jsonb_build_object('run_id',x.run_id,'step_id',x.step_id,'action_key',x.action_key,'test_run_id',x.test_run_id,'effect_key',zasp_temporal74.effect_identity(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,1),'state',state_value);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal74.test_validate_output(o text, w text, e text, r text, s text, input_manifest jsonb, input_body bytea, manifest jsonb, body bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE doc jsonb;input_doc jsonb;native jsonb;summary jsonb;checks jsonb:='[]';records jsonb:='[]';evidence jsonb:='[]';
 link public.zasp_security_agent_test_links%ROWTYPE;child public.zasp_red_team_runs%ROWTYPE;j zasp_temporal74.invocations%ROWTYPE;
 item record;key text;prompt text;observation jsonb;passed integer:=0;total integer;credential bytea;target_value jsonb;
BEGIN
 input_doc:=zasp_sa_multistep_prior.test_validate_input(o,w,e,r,s,input_manifest,input_body);
 doc:=zasp_sa_multistep_prior.test_json(body,1048576);
 SELECT * INTO STRICT link FROM public.zasp_security_agent_test_links WHERE (organization_id,workspace_id,environment_id,run_id,step_id)=(o,w,e,r,s);
 SELECT * INTO STRICT child FROM public.zasp_red_team_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,link.test_run_id);
 key:='organizations/'||o||'/workspaces/'||w||'/environments/'||e||'/artifacts/'||child.run_id;
 IF NOT zasp_sa_multistep_prior.closed(manifest,ARRAY['reference','version_id','sha256','size_bytes']) OR octet_length(manifest::text)>16384
  OR jsonb_typeof(manifest->'reference') IS DISTINCT FROM 'string' OR NOT COALESCE(manifest->>'reference'~'^s3://[a-z0-9][a-z0-9.-]{1,61}[a-z0-9]/organizations/',false)
  OR right(manifest->>'reference',length(key)+1) IS DISTINCT FROM '/'||key
  OR jsonb_typeof(manifest->'version_id') IS DISTINCT FROM 'string' OR NOT COALESCE(length(manifest->>'version_id') BETWEEN 1 AND 512 AND manifest->>'version_id'~'^[!-~]+$',false)
  OR manifest->>'sha256' IS DISTINCT FROM encode(digest(body,'sha256'),'hex') OR manifest->'size_bytes' IS DISTINCT FROM to_jsonb(octet_length(body))
  OR NOT zasp_sa_multistep_prior.closed(doc,ARRAY['schema_version','input_artifact','summary','native_artifact'])
  OR doc->>'schema_version' IS DISTINCT FROM 'red-team-evidence-bundle-v2' OR doc->'input_artifact' IS DISTINCT FROM input_manifest THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='ordered output identity rejected';END IF;
 SELECT snapshot->'targets'->'resolution' INTO STRICT target_value FROM zasp_temporal74.effects WHERE (organization_id,workspace_id,environment_id,run_id,step_id,generation)=(o,w,e,r,s,1);
 total:=jsonb_array_length(link.test_categories);
 IF (SELECT count(*) FROM zasp_temporal74.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id)=(o,w,e,child.run_id))<>total THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test observations incomplete';END IF;
 FOR item IN SELECT value category,ordinality FROM jsonb_array_elements_text(link.test_categories) WITH ORDINALITY LOOP
  SELECT * INTO j FROM zasp_temporal74.invocations WHERE (organization_id,workspace_id,environment_id,test_run_id,category)=(o,w,e,child.run_id,item.category);
  IF NOT FOUND OR j.state<>'completed' OR j.http_status<>200 OR j.protected IS NULL OR j.attempt<>1 OR j.effect_key IS DISTINCT FROM zasp_temporal74.effect_identity(o,w,e,r,s,1)
   OR j.input_digest IS DISTINCT FROM child.input_digest OR j.target_resolution IS DISTINCT FROM target_value
   OR j.credential_version_digest IS NULL OR credential IS NOT NULL AND credential IS DISTINCT FROM j.credential_version_digest THEN
   RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered test observation authority changed';END IF;
  credential:=j.credential_version_digest;
  prompt:=zasp_sa_multistep_prior.test_prompt(item.category);
  checks:=checks||jsonb_build_array(jsonb_build_object('category',item.category,'check_id','zasp.curated.'||item.category||'.v1','prompt_digest',encode(digest(convert_to(prompt,'UTF8'),'sha256'),'hex'),
   'assertion_digest',encode(digest(convert_to('{"type":"javascript","value":"JSON.parse(output).observation.protected === true","canary":"ZASP_RED_TEAM_'||upper(item.category)||'","adapter_criterion":"http-200-output-excludes-canary-v1"}','UTF8'),'sha256'),'hex')));
  observation:=jsonb_build_object('target_comparison',j.target_resolution->'comparison','schema_version','red-team-linked-observation-v1','run_id',child.run_id,'category',j.category,'credential_version_digest',encode(j.credential_version_digest,'hex'),'observation',jsonb_build_object('http_status',j.http_status,'response_digest',encode(j.response_digest,'hex'),'protected',j.protected));
  records:=records||jsonb_build_array(jsonb_build_object('success',j.protected,'provider',jsonb_build_object('label','zasp-red-team-adapter'),'vars',jsonb_build_object('category',item.category,'prompt',prompt),
   'testCase',jsonb_build_object('assert',jsonb_build_array(jsonb_build_object('type','javascript','value','JSON.parse(output).observation.protected === true')),'metadata',jsonb_build_object('category',item.category)),
   'response',jsonb_build_object('linked_observation',observation,'output','[REDACTED]','metadata',jsonb_build_object('http',jsonb_build_object('status',200))),
   'gradingResult',jsonb_build_object('pass',j.protected,'reason','[REDACTED]')));
  evidence:=evidence||jsonb_build_array(item.category||CASE WHEN j.protected THEN ': protected' ELSE ': unsafe behavior observed' END);
  IF j.protected THEN passed:=passed+1;END IF;
 END LOOP;
 native:=jsonb_build_object('schema_version','red-team-native-artifact-v2','redaction_policy','red-team-artifact-redaction-v2','run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),
  'evaluation_identity',jsonb_build_object('schema_version','red-team-evaluation-identity-v1','engine','promptfoo','engine_version','0.121.19','curated_pack','zasp-curated-red-team-v1','runner_image_digest',input_doc->>'runner_image_digest','checks',checks),
  'native_output',jsonb_build_object('metadata',jsonb_build_object('promptfooVersion','0.121.19'),'results',jsonb_build_object('version',3,'results',records)));
 summary:=jsonb_build_object('schema_version','red-team-evidence-v2','engine','promptfoo','engine_version','0.121.19','run_id',child.run_id,'input_digest',encode(child.input_digest,'hex'),
  'objective','Evaluate curated categories: '||(SELECT string_agg(value,', ' ORDER BY ordinality) FROM jsonb_array_elements_text(link.test_categories) WITH ORDINALITY),
  'behavior',format('%s of %s curated security checks passed; %s exposed unsafe behavior.',passed,total,total-passed),'verdict',CASE WHEN passed=total THEN 'pass' ELSE 'fail' END,'error_code',NULL,'evidence',evidence);
 IF doc->'native_artifact' IS DISTINCT FROM native OR doc->'summary' IS DISTINCT FROM summary THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='ordered evaluation evidence changed';END IF;
 RETURN summary;
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal75.admit_body(o text, w text, e text, d text, v bigint, k text, t text, tv bigint, r text, actor_value text, audit_value text, correlation_value text, automatic_value boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE definition_row public.zasp_security_agent_definitions%ROWTYPE;prior public.zasp_security_agent_trigger_receipts%ROWTYPE;run_row public.zasp_security_agent_runs%ROWTYPE;
 binding_value jsonb;trigger_value jsonb;created_value boolean:=false;action_value text;
BEGIN
 IF NOT COALESCE(public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(d) AND public.zasp_valid_product_id(t) AND public.zasp_valid_product_id(r) AND public.zasp_valid_product_id(audit_value) AND public.zasp_valid_product_id(correlation_value) AND v BETWEEN 1 AND 1000000 AND tv>=0,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='existing test admission rejected';END IF;
 -- The same organization guard used by budget claim precedes all work rows.
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 INSERT INTO public.zasp_security_agent_org_admissions(organization_id) VALUES(o) ON CONFLICT DO NOTHING;
 PERFORM 1 FROM public.zasp_security_agent_org_admissions WHERE organization_id=o FOR UPDATE;
 SELECT * INTO definition_row FROM public.zasp_security_agent_definitions WHERE (organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL FOR SHARE;
 IF NOT FOUND OR definition_row.activation NOT IN('supervised','autonomous') OR definition_row.body->>'autonomy' IS DISTINCT FROM definition_row.activation OR definition_row.body->'enabled' IS DISTINCT FROM 'true'::jsonb OR definition_row.body->>'trigger_kind' IS DISTINCT FROM k THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission definition changed';END IF;
 action_value:=definition_row.body->'allowed_actions'->>0;
 binding_value:=zasp_temporal75.binding(o,w,e,d,v);
 IF action_value NOT IN('run_test','rerun_test','start_attack_lab') OR definition_row.body->'allowed_actions' IS DISTINCT FROM jsonb_build_array(action_value) OR definition_row.body->>'verification_kind' IS DISTINCT FROM (CASE action_value WHEN 'start_attack_lab' THEN 'attack_lab_run' ELSE 'test_run' END) OR NOT (definition_row.body->>'max_ai_cost_nano_credits' ~ '^[0-9]{1,13}$') OR (definition_row.body->>'max_ai_cost_nano_credits')::bigint NOT BETWEEN 1 AND 1000000000000 THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission configuration changed';END IF;
 PERFORM public.zasp_production_security_agent_existing_tests_controls_guard(o,w,e,action_value);
 trigger_value:=public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',tv);
 SELECT * INTO prior FROM public.zasp_security_agent_trigger_receipts WHERE (organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_version)=(o,w,e,d,t,(trigger_value->>'version')::bigint) FOR SHARE;
 IF FOUND THEN
  SELECT * INTO run_row FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,prior.run_id) FOR SHARE;
  IF NOT FOUND OR run_row.definition_id<>d OR run_row.definition_version<>v OR prior.trigger_kind<>k OR prior.trigger_digest IS DISTINCT FROM decode(trigger_value->>'digest','hex') THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='existing test trigger intent conflict';END IF;
 ELSE
  IF zasp_temporal73.active_count(o,w,e,d) >= (definition_row.body->>'concurrency_limit')::integer THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test concurrency unavailable';END IF;
  -- Every prerequisite lock has completed before this final wall-clock check.
  IF zasp_temporal75.binding(o,w,e,d,v) IS DISTINCT FROM binding_value OR public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission authority changed';END IF;
  INSERT INTO public.zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(o,w,e,d,t,k,(trigger_value->>'version')::bigint,decode(trigger_value->>'digest','hex'),r);
  INSERT INTO public.zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(o,w,e,r,d,v,t,actor_value,'queued') RETURNING * INTO run_row;

  INSERT INTO zasp_temporal73.admissions VALUES(o,w,e,r,d,v,t,(trigger_value->>'version')::bigint,decode(trigger_value->>'digest','hex'),'retained_single_action');
  INSERT INTO zasp_temporal73.commands VALUES(o,w,e,r,1,'start');

  INSERT INTO zasp_temporal75.admissions SELECT o,w,e,r,revision FROM zasp_temporal75.configuration ORDER BY revision DESC LIMIT 1;
  created_value:=true;
 END IF;
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
 VALUES(o,w,e,audit_value,correlation_value,run_row.run_id,actor_value,CASE WHEN created_value THEN 'run_queued' ELSE 'run_deduplicated' END,decode(trigger_value->>'digest','hex'),jsonb_build_object('run_id',run_row.run_id,'definition_id',d,'definition_version',v,'trigger_kind',k,'trigger_id',t,'trigger_version',trigger_value->'version','automatic',automatic_value,'action',action_value));
 PERFORM zasp_temporal75.binding(o,w,e,d,v);
 IF public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired';END IF;
 UPDATE public.zasp_security_agent_execution_state SET used_at=coalesce(used_at,clock_timestamp()) WHERE singleton;
 IF zasp_temporal75.binding(o,w,e,d,v) IS DISTINCT FROM binding_value OR public.zasp_production_security_agent_existing_tests_trigger(o,w,e,k,t,definition_row.body->>'trigger_source',(trigger_value->>'version')::bigint) IS DISTINCT FROM trigger_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='existing test admission expired after final write';END IF;
 RETURN jsonb_build_object('id',run_row.run_id,'agent_id',d,'state',run_row.state,'evidence_ids',jsonb_build_array(t),'definition_version',v,'version',run_row.version,'created',created_value,'replayed',NOT created_value);
END
$function$

CREATE OR REPLACE FUNCTION zasp_temporal78.admit_body(o text, w text, e text, d text, v bigint, k text, t text, tv bigint, r text, actor_value text, audit_value text, correlation_value text, automatic_value boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE def public.zasp_security_agent_definitions%ROWTYPE;src public.zasp_risk_findings%ROWTYPE;occ zasp_temporal77.occurrences%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;g jsonb;trigger_digest bytea;step_value text;
BEGIN
 SELECT * INTO def FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id,definition_id,version)=(o,w,e,d,v) AND deleted_at IS NULL FOR SHARE;
 IF def.body->'allowed_actions' IS DISTINCT FROM '["update_finding_response"]'::jsonb THEN RETURN zasp_temporal75.admit_body(o,w,e,d,v,k,t,tv,r,actor_value,audit_value,correlation_value,automatic_value);END IF;
 g:=zasp_temporal78.authorize(o,w,e,d,v);
 IF automatic_value IS DISTINCT FROM true OR k<>'finding' OR actor_value IS DISTINCT FROM g->>'principal_id' OR r IS DISTINCT FROM public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',concat_ws(chr(31),d,v,k,t,tv)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='finding admission identity rejected';END IF;
 SELECT * INTO src FROM public.zasp_risk_findings WHERE(organization_id,workspace_id,environment_id,id,version,status)=(o,w,e,t,tv,'open') AND (CASE WHEN def.body?'trigger_rules' THEN rule ELSE COALESCE(rule,source) END)=def.body->>'trigger_source' FOR SHARE;
 SELECT a.* INTO occ FROM zasp_temporal77.occurrences a JOIN zasp_temporal77.source_events s USING(organization_id,workspace_id,environment_id,event_id)
 WHERE(a.organization_id,a.workspace_id,a.environment_id,a.definition_id,a.definition_version,a.run_id,a.disposition,s.source_kind,s.source_id,s.source_version)=(o,w,e,d,v,r,'admitted',k,t,tv);
 IF src.id IS NULL OR occ.run_id IS NULL OR occ.definition_digest IS DISTINCT FROM digest(convert_to(def.body::text,'UTF8'),'sha256') OR occ.snapshot_digest IS DISTINCT FROM digest(convert_to(occ.snapshot::text,'UTF8'),'sha256') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding admission evidence changed';END IF;
 trigger_digest:=digest(convert_to(jsonb_build_object('kind','finding','id',t,'version',tv)::text,'UTF8'),'sha256');
 step_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_step',r||chr(31)||'0');
 INSERT INTO zasp_temporal78.run_owners VALUES(o,w,e,r,d,v,'automatic77',t,tv,encode(trigger_digest,'hex'),occ.snapshot,occ.snapshot_digest,'update_finding_response',step_value,'security-agent-finding/v1/'||o||'/'||w||'/'||e||'/'||r,clock_timestamp());
 INSERT INTO public.zasp_security_agent_trigger_receipts(organization_id,workspace_id,environment_id,definition_id,trigger_id,trigger_kind,trigger_version,trigger_digest,run_id) VALUES(o,w,e,d,t,k,tv,trigger_digest,r);
 --73's unchanged row guard owns cross-family definition capacity.
 INSERT INTO public.zasp_security_agent_runs(organization_id,workspace_id,environment_id,run_id,definition_id,definition_version,trigger_id,requested_by,state) VALUES(o,w,e,r,d,v,t,actor_value,'queued') RETURNING * INTO rr;
 INSERT INTO zasp_temporal78.commands VALUES(o,w,e,r,1,'start');
 INSERT INTO zasp_temporal78.start_deliveries(organization_id,workspace_id,environment_id,run_id) VALUES(o,w,e,r);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body)
 VALUES(o,w,e,audit_value,correlation_value,r,actor_value,'run_queued',trigger_digest,jsonb_build_object('run_id',r,'definition_id',d,'definition_version',v,'trigger_kind',k,'trigger_id',t,'trigger_version',tv,'automatic',true,'action','update_finding_response'));
 PERFORM zasp_temporal78.authorize(o,w,e,d,v);
 UPDATE public.zasp_security_agent_execution_state SET used_at=COALESCE(used_at,clock_timestamp()) WHERE singleton;
 RETURN jsonb_build_object('id',r,'agent_id',d,'state',rr.state,'evidence_ids',jsonb_build_array(t),'definition_version',v,'version',rr.version,'created',true,'replayed',false);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.admit_occurrence(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE ref jsonb:=q->'ref';o text:=ref->>'organization_id';w text:=ref->>'workspace_id';e text:=ref->>'environment_id';d text:=ref->>'definition_id';id_value text:=q->>'event_id';
 def public.zasp_security_agent_definitions%ROWTYPE;s zasp_temporal77.source_events%ROWTYPE;prior zasp_temporal77.occurrences%ROWTYPE;legacy public.zasp_security_agent_trigger_receipts%ROWTYPE;
 grant_value jsonb;matched jsonb;until_value timestamptz;now_value timestamptz;disposition_value text;run_value text;result_value jsonb;
BEGIN
 PERFORM zasp_temporal77.require_executor();
 IF NOT COALESCE(zasp_sa_multistep_prior.closed(q,ARRAY['ref','revision','event_id']) AND zasp_sa_multistep_prior.closed(ref,ARRAY['organization_id','workspace_id','environment_id','definition_id'])
 AND public.zasp_valid_product_id(o) AND public.zasp_valid_product_id(w) AND public.zasp_valid_product_id(e) AND public.zasp_valid_product_id(d) AND public.zasp_valid_product_id(id_value)
 AND jsonb_typeof(q->'revision')='number' AND q->>'revision'~'^[1-9][0-9]{0,6}$' AND (q->>'revision')::bigint<=1000000,false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='automatic occurrence scope rejected';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('test-selector75-configuration',0));
 IF NOT EXISTS(SELECT 1 FROM zasp_temporal75.configuration WHERE revision=(q->>'revision')::bigint AND enabled AND revision=(SELECT max(revision) FROM zasp_temporal75.configuration)) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic selector configuration changed';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO def FROM public.zasp_security_agent_definitions WHERE(organization_id,workspace_id,environment_id,definition_id)=(o,w,e,d) FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic definition scope denied';END IF;
 IF def.deleted_at IS NOT NULL OR def.activation NOT IN('supervised','autonomous') OR def.body->>'autonomy' IS DISTINCT FROM def.activation OR def.body->'enabled' IS DISTINCT FROM 'true'::jsonb
 OR NOT zasp_temporal78.automatic_body(def.body) THEN RETURN jsonb_build_object('disposition','ignored');END IF;
 IF NOT zasp_temporal77.rules_valid(def.body) OR NOT zasp_temporal77.rules_capable(def.body) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic adapter unavailable';END IF;
 grant_value:=zasp_temporal78.authorize(o,w,e,d,def.version);
 SELECT * INTO s FROM zasp_temporal77.source_events WHERE(organization_id,workspace_id,environment_id,event_id)=(o,w,e,id_value);
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='automatic source scope denied';END IF;
 SELECT * INTO prior FROM zasp_temporal77.occurrences WHERE(organization_id,workspace_id,environment_id,definition_id,event_id)=(o,w,e,d,id_value);
 IF FOUND THEN RETURN jsonb_strip_nulls(jsonb_build_object('disposition','replayed','run_id',prior.run_id,'original_disposition',prior.disposition));END IF;
 -- Registered finding/path writers lock their parent before replacing children.
 IF s.source_kind='finding' THEN PERFORM 1 FROM public.zasp_risk_findings WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,s.source_id) FOR SHARE;
 ELSIF s.source_kind='attack_path' THEN PERFORM 1 FROM public.zasp_risk_attack_paths WHERE(organization_id,workspace_id,environment_id,id)=(o,w,e,s.source_id) FOR SHARE;
 ELSE RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime automatic adapter unavailable';END IF;
 now_value:=clock_timestamp();matched:=zasp_temporal78.source_match(o,w,e,id_value,def.body,now_value);
 IF matched IS NULL THEN RETURN jsonb_build_object('disposition','ignored');END IF;
 -- Pre77 receipts permanently consumed the same scoped source occurrence.
 -- Never send these through75's same-definition-version replay branch.
 SELECT tr.* INTO legacy FROM public.zasp_security_agent_trigger_receipts tr JOIN public.zasp_security_agent_runs r ON(r.organization_id,r.workspace_id,r.environment_id,r.run_id,r.definition_id)=(tr.organization_id,tr.workspace_id,tr.environment_id,tr.run_id,tr.definition_id)
 WHERE(tr.organization_id,tr.workspace_id,tr.environment_id,tr.definition_id,tr.trigger_id,tr.trigger_version,tr.trigger_kind)=(o,w,e,d,s.source_id,s.source_version,s.source_kind) FOR SHARE OF tr,r;
 IF FOUND THEN disposition_value:='consumed';run_value:=legacy.run_id;
 ELSE
  SELECT admitted_until INTO until_value FROM zasp_temporal77.cooldowns WHERE(organization_id,workspace_id,environment_id,definition_id,pattern_key)=(o,w,e,d,decode(matched->>'cooldown_key','hex'));
  IF until_value IS NOT NULL AND now_value<until_value THEN disposition_value:='cooldown';
  ELSE
   disposition_value:='admitted';
   run_value:=public.zasp_discovery_canonical_id(o,w,e,'security_agent_run',concat_ws(chr(31),d,def.version,s.source_kind,s.source_id,s.source_version));
  END IF;
 END IF;
 INSERT INTO zasp_temporal77.occurrences(organization_id,workspace_id,environment_id,definition_id,event_id,definition_version,definition_digest,disposition,run_id,snapshot,snapshot_digest)
 VALUES(o,w,e,d,id_value,def.version,digest(convert_to(def.body::text,'UTF8'),'sha256'),disposition_value,run_value,matched->'evidence',decode(matched->>'digest','hex'));
 IF disposition_value='admitted' THEN
  result_value:=zasp_temporal78.admit_body(o,w,e,d,def.version,s.source_kind,s.source_id,s.source_version,run_value,grant_value->>'principal_id',public.zasp_discovery_canonical_id(o,w,e,'security_agent_audit',run_value),public.zasp_discovery_canonical_id(o,w,e,'security_agent_correlation',run_value),true);
  IF result_value->'created' IS DISTINCT FROM 'true'::jsonb OR result_value->>'id' IS DISTINCT FROM run_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='automatic admission changed';END IF;
  IF def.body?'trigger_rules' THEN
  INSERT INTO zasp_temporal77.cooldowns VALUES(o,w,e,d,decode(matched->>'cooldown_key','hex'),now_value,now_value+make_interval(secs=>(def.body->'trigger_rules'->>'cooldown_seconds')::integer))
   ON CONFLICT(organization_id,workspace_id,environment_id,definition_id,pattern_key) DO UPDATE SET admitted_at=EXCLUDED.admitted_at,admitted_until=EXCLUDED.admitted_until; END IF;
 END IF;
 PERFORM zasp_temporal78.authorize(o,w,e,d,def.version);
 IF zasp_temporal78.source_match(o,w,e,id_value,def.body,clock_timestamp()) IS DISTINCT FROM matched THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='automatic source changed after admission';END IF;
 RETURN jsonb_strip_nulls(jsonb_build_object('disposition',disposition_value,'run_id',run_value));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.apply(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal78.run_owners%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;st public.zasp_security_agent_steps%ROWTYPE;item jsonb;result_value jsonb;result_hash bytea;receipt_value jsonb;result_version bigint;outcome_value text;audit_value text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='finding apply requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal78.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_executor') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='finding apply unavailable';END IF;
 x:=zasp_temporal78.start_identity(q);
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||x.organization_id,0));
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR UPDATE;
 IF EXISTS(SELECT 1 FROM zasp_temporal78.response_metadata WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN RETURN zasp_temporal78.effect_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id);END IF;
 PERFORM zasp_temporal78.current_step(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id);
 SELECT * INTO STRICT st FROM public.zasp_security_agent_steps WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id);
 SELECT plan->'steps'->0 INTO STRICT item FROM public.zasp_security_agent_plans WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 INSERT INTO public.zasp_security_agent_step_reservations(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest) VALUES(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.action_key,st.input_digest);
 UPDATE public.zasp_risk_findings SET status=item->>'target_status',acceptance_reason=NULL,version=version+1,updated_at=clock_timestamp()
 WHERE(organization_id,workspace_id,environment_id,id,version,status)=(x.organization_id,x.workspace_id,x.environment_id,x.trigger_id,x.trigger_version,'open') RETURNING version INTO result_version;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding version changed before apply';END IF;
 result_value:=jsonb_build_object('run_id',x.run_id,'step_id',x.step_id,'finding_id',x.trigger_id,'previous_version',x.trigger_version,'version',result_version,'status',item->>'target_status','assignee_id',item->>'assignee_id','response_status',item->>'response_status','note',item->>'note','source_digest',encode(x.snapshot_digest,'hex'));
 result_hash:=digest(convert_to(result_value::text,'UTF8'),'sha256');
 outcome_value:=public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_effect',x.run_id||chr(31)||x.step_id||chr(31)||x.action_key);
 receipt_value:=jsonb_build_object('contract_version',78,'workflow_id',x.workflow_id,'run_id',x.run_id,'step_id',x.step_id,'state','remediated','outcome_id',outcome_value,'result_digest','sha256:'||encode(result_hash,'hex'));
 INSERT INTO public.zasp_security_agent_effects(organization_id,workspace_id,environment_id,run_id,step_id,action_key,input_digest,state,attempt,outcome_id,result_digest) VALUES(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.action_key,st.input_digest,'verified',1,outcome_value,result_hash);
 INSERT INTO zasp_temporal78.response_metadata VALUES(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id,x.trigger_id,x.trigger_version,result_version,item->>'assignee_id',item->>'response_status',item->>'note',outcome_value,result_value,result_hash,receipt_value);
 UPDATE public.zasp_security_agent_steps SET state='succeeded',version=version+1,updated_at=clock_timestamp() WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id);
 UPDATE public.zasp_security_agent_runs SET state='remediated',version=version+1,updated_at=clock_timestamp(),completed_at=clock_timestamp() WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 audit_value:=public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_finding_effect_audit',x.run_id);
 INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,step_id,actor_id,event_kind,event_digest,body) VALUES(x.organization_id,x.workspace_id,x.environment_id,audit_value,audit_value,x.run_id,x.step_id,rr.requested_by,'effect_verified',digest(convert_to(receipt_value::text,'UTF8'),'sha256'),receipt_value);
 IF x.source_kind='human78' THEN PERFORM zasp_temporal78.human_authorize(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 ELSE PERFORM zasp_temporal78.authorize(x.organization_id,x.workspace_id,x.environment_id,x.definition_id,x.definition_version);END IF;
 IF NOT zasp_temporal78.assignee(x.organization_id,x.workspace_id,x.environment_id,item->>'assignee_id') OR NOT zasp_temporal78.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='finding apply authority changed';END IF;
 RETURN zasp_temporal78.effect_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.cleanup(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal78.run_owners%ROWTYPE;rr public.zasp_security_agent_runs%ROWTYPE;j zasp_temporal78.planning_jobs%ROWTYPE;proof_value jsonb;evidence_value jsonb;body_value jsonb;audit_value text;kind_value text;
BEGIN
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='finding cleanup requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal78.current_ready() OR NOT zasp_temporal68.principal_ready('zasp_temporal_compensation') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='finding cleanup authority rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','input_digest','reason']) OR NOT COALESCE(q->>'reason' IN('terminal','workflow_failed','workflow_cancelled','workflow_deadline'),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='finding cleanup request rejected';END IF;
 x:=zasp_temporal78.start_identity(q-'reason');
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||x.organization_id,0));
 SELECT * INTO STRICT rr FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR UPDATE;
 IF EXISTS(SELECT 1 FROM zasp_temporal78.response_metadata WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN
  evidence_value:=zasp_temporal78.effect_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 ELSIF EXISTS(SELECT 1 FROM zasp_temporal78.stops WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN
  evidence_value:=zasp_temporal78.stop_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
 ELSE
  SELECT * INTO j FROM zasp_temporal78.planning_jobs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id) FOR UPDATE;
  IF j.state='needs_human' AND q->>'reason'='terminal' THEN
   IF NOT zasp_temporal78.planning_terminal_valid(x.organization_id,x.workspace_id,x.environment_id,x.run_id) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding terminal cleanup proof rejected';END IF;
   evidence_value:=jsonb_build_object('kind','planning_terminal','run_id',x.run_id);
  ELSE
   IF q->>'reason'='terminal' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding terminal cleanup lacks proof';END IF;
   IF EXISTS(SELECT 1 FROM public.zasp_security_agent_effects WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) OR EXISTS(SELECT 1 FROM public.zasp_security_agent_step_reservations WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id)) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding partial effect refused';END IF;
   IF j.run_id IS NOT NULL AND j.state<>'admitted' THEN
    PERFORM zasp_temporal78.plan((q-ARRAY['reason','input_digest'])||jsonb_build_object('operation','reconcile','payload','{}'::jsonb));kind_value:='planning';
   ELSE
    kind_value:=CASE WHEN j.run_id IS NULL THEN 'queued' ELSE 'admitted' END;
    IF rr.state NOT IN('queued','waiting_approval','cancelled') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='finding stop state refused';END IF;
    UPDATE public.zasp_security_agent_steps SET state='cancelled',version=version+1,updated_at=clock_timestamp() WHERE(organization_id,workspace_id,environment_id,run_id,step_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.step_id) AND state IN('authorized','waiting_approval');
    UPDATE public.zasp_security_agent_runs SET state='cancelled',last_error_code='finding_cancelled_before_apply',version=version+1,completed_at=COALESCE(completed_at,clock_timestamp()),updated_at=clock_timestamp() WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
   END IF;
   SELECT jsonb_build_object('kind',kind_value,'run_state',state,'run_reason',last_error_code,'definition_version',x.definition_version,'input_digest',x.input_digest,'plan_hash',encode(plan_hash,'hex')) INTO STRICT proof_value FROM public.zasp_security_agent_runs WHERE(organization_id,workspace_id,environment_id,run_id)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
   audit_value:=public.zasp_discovery_canonical_id(x.organization_id,x.workspace_id,x.environment_id,'security_agent_finding_stop',x.run_id);
   INSERT INTO zasp_temporal78.stops VALUES(x.organization_id,x.workspace_id,x.environment_id,x.run_id,q->>'reason',proof_value,audit_value);
   body_value:=jsonb_build_object('reason',q->>'reason','proof',proof_value);
   INSERT INTO public.zasp_security_agent_audit(organization_id,workspace_id,environment_id,audit_id,correlation_id,run_id,actor_id,event_kind,event_digest,body) VALUES(x.organization_id,x.workspace_id,x.environment_id,audit_value,audit_value,x.run_id,session_user,'temporal_finding_stopped',digest(convert_to(body_value::text,'UTF8'),'sha256'),body_value);
   evidence_value:=zasp_temporal78.stop_evidence(x.organization_id,x.workspace_id,x.environment_id,x.run_id);
  END IF;
 END IF;
 RETURN jsonb_build_object('workflow_id',x.workflow_id,'pending',zasp_temporal73.unresolved(x.organization_id,x.workspace_id,x.environment_id,x.run_id),'evidence_digest','sha256:'||encode(digest(convert_to(evidence_value::text,'UTF8'),'sha256'),'hex'));
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.late_usage_valid(o text, w text, e text, r text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE l zasp_temporal78.planning_late_usage%ROWTYPE;j zasp_temporal78.planning_jobs%ROWTYPE;p zasp_temporal78.provider_reservations%ROWTYPE;
 a public.zasp_security_agent_audit%ROWTYPE;later public.zasp_security_agent_audit%ROWTYPE;association jsonb;cv jsonb;original jsonb;raw text;
BEGIN
 SELECT * INTO l FROM zasp_temporal78.planning_late_usage WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO j FROM zasp_temporal78.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO p FROM zasp_temporal78.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_terminal');
 SELECT * INTO later FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_late_usage');
 raw:=l.body->>'raw';association:=l.body->'association';original:=a.body->'reservation';
 IF l.run_id IS NULL OR raw IS NULL OR octet_length(raw) NOT BETWEEN 1 AND 65536 OR NOT zasp_sa_multistep_prior.closed(l.body,ARRAY['raw','association','terminal_digest','reservation','usage'])
  OR NOT zasp_sa_multistep_prior.closed(association,ARRAY['request_digest','credential_digest','reservation_id','response_id','response_digest']) THEN RETURN false;END IF;
 cv:=zasp_temporal78.planning_result(raw,j.lookup_request->>'model',j.context_value);
 RETURN COALESCE(j.state='needs_human' AND a.body->'job'=to_jsonb(j) AND a.event_digest=digest(convert_to(a.body::text,'UTF8'),'sha256')
  AND l.body_digest=digest(convert_to(l.body::text,'UTF8'),'sha256') AND l.body->>'terminal_digest'=encode(a.event_digest,'hex')
  AND later.audit_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_planning_late_usage',r) AND later.correlation_id=later.audit_id AND later.body=l.body AND later.event_digest=l.body_digest
  AND association->>'request_digest'=j.request_digest AND j.request_digest='sha256:'||encode(digest(convert_to(j.request_body,'UTF8'),'sha256'),'hex')
  AND association->>'credential_digest'=j.lookup_request->>'credential_digest' AND association->>'credential_digest'=l.credential_digest
  AND association->>'reservation_id'=j.reservation_id AND p.reservation_id=j.reservation_id
  AND association->>'response_id'=l.response_id AND (raw::jsonb)->>'id'=l.response_id
  AND association->>'response_digest'='sha256:'||encode(digest(convert_to(raw,'UTF8'),'sha256'),'hex')
  AND original->'settled_at'='null'::jsonb AND original->'total_tokens'='null'::jsonb AND original->'cost_nano_credits'='null'::jsonb
  AND to_jsonb(p)-ARRAY['settled_at','output_digest','prompt_tokens','completion_tokens','total_tokens','cost_nano_credits']=original-ARRAY['settled_at','output_digest','prompt_tokens','completion_tokens','total_tokens','cost_nano_credits']
  AND l.body->'reservation'=to_jsonb(p) AND cv->'usage'<>'null'::jsonb AND l.body->'usage'=cv->'usage' AND p.settled_at IS NOT NULL AND p.released_at IS NULL
  AND (p.prompt_tokens,p.completion_tokens,p.total_tokens,p.cost_nano_credits)=((cv->'usage'->>'prompt_tokens')::bigint,(cv->'usage'->>'completion_tokens')::bigint,(cv->'usage'->>'total_tokens')::bigint,(cv->'usage'->>'cost_nano_credits')::bigint)
  AND p.output_digest=digest(convert_to(raw,'UTF8'),'sha256')
  AND (j.raw_result IS NULL OR (j.raw_result::jsonb)-'usage'=(raw::jsonb)-'usage' AND j.result_value->'usage'='null'::jsonb),false);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.plan(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE o text;w text;e text;r text;op text;payload jsonb;job zasp_temporal78.planning_jobs%ROWTYPE;
 rr public.zasp_security_agent_runs%ROWTYPE;b public.zasp_security_agent_run_budgets%ROWTYPE;reservation zasp_temporal78.provider_reservations%ROWTYPE;
 selection jsonb;body_value text;bound_value jsonb;cv jsonb;reason text;receipt_value jsonb;send_value boolean:=false;
BEGIN
 IF q->>'operation'='reconcile' THEN RETURN zasp_temporal78.recover_plan(q);END IF;
 IF q->>'operation'='late_usage' THEN RETURN zasp_temporal78.record_late_usage(q);END IF;
 IF q->>'operation'='load' THEN RETURN zasp_temporal78.load_plan(q);END IF;
 IF current_setting('transaction_isolation')<>'read committed' THEN RAISE EXCEPTION USING ERRCODE='25001',MESSAGE='executor planning requires read committed';END IF;
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal68.principal_ready('zasp_temporal_executor') OR NOT zasp_temporal78.current_ready() THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='executor planning unavailable';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version','operation','payload']) OR octet_length(q::text)>524288
  OR q->>'operation' NOT IN('prepare','start','result','settle','artifacts','admit') OR jsonb_typeof(q->'payload')<>'object' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor planning request rejected';END IF;
 o:=q->>'organization_id';w:=q->>'workspace_id';e:=q->>'environment_id';r:=q->>'run_id';op:=q->>'operation';payload:=q->'payload';
 PERFORM pg_advisory_xact_lock(hashtextextended('security-agent-budget-admission:'||o,0));
 SELECT * INTO b FROM public.zasp_security_agent_run_budgets WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO rr FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 SELECT * INTO job FROM zasp_temporal78.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) FOR UPDATE;
 IF NOT FOUND OR NOT zasp_temporal78.is_owned(o,w,e,r) OR q->'definition_version' IS DISTINCT FROM to_jsonb(job.definition_version)
  OR rr.lease_owner IS NOT NULL OR rr.lease_token IS NOT NULL OR rr.lease_expires_at IS NOT NULL
  OR NOT(rr.state='planning' AND rr.version=job.run_version OR op='admit' AND job.state='admitted' AND rr.state IN('queued','waiting_approval') AND rr.version=job.run_version+1)
  OR b.run_id IS NULL OR b.stop_reason IS NOT NULL OR b.deadline_at<=clock_timestamp() OR (b.started_at,b.deadline_at) IS DISTINCT FROM (job.budget_started_at,job.budget_deadline_at)
  OR (b.definition_id,b.definition_version,b.max_steps,b.max_tokens,b.max_cost_nano_credits,b.concurrency_limit) IS DISTINCT FROM (rr.definition_id,rr.definition_version,1,(job.context_value->'definition'->>'ai_token_budget')::bigint,(job.context_value->'definition'->>'max_ai_cost_nano_credits')::bigint,(job.context_value->'definition'->>'concurrency_limit')::integer)
  OR zasp_temporal78.context(o,w,e,r) IS DISTINCT FROM job.context_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor planning authority changed';END IF;
 SELECT * INTO reservation FROM zasp_temporal78.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1) FOR UPDATE;
 IF op IN('start','settle','admit') AND payload<>'{}'::jsonb THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor planning unexpected payload';END IF;
 IF op='prepare' THEN
  IF NOT zasp_sa_multistep_prior.closed(payload,ARRAY['pricing','input_version']) OR jsonb_typeof(payload->'input_version')<>'string' OR length(payload->>'input_version') NOT BETWEEN 1 AND 1024 OR payload->>'input_version'!~'^[!-~]+$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor input artifact rejected';END IF;
  selection:=payload->'pricing';body_value:=zasp_temporal78.planning_body(job.context_value,selection);
  selection:=selection||jsonb_build_object('body',body_value,'body_digest','sha256:'||encode(digest(convert_to(body_value,'UTF8'),'sha256'),'hex'));
  IF (selection->>'organization_id',selection->>'workspace_id',selection->>'environment_id') IS DISTINCT FROM (o,w,e) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor pricing scope rejected';END IF;
  bound_value:=zasp_temporal78.pricing_lookup('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',selection);
  IF job.state='loaded' THEN
   IF reservation.run_id IS NOT NULL OR (bound_value->>'maximum_tokens')::bigint>b.max_tokens OR (bound_value->>'maximum_cost_nano_credits')::bigint>b.max_cost_nano_credits THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor pricing exceeds budget';END IF;
   INSERT INTO zasp_temporal78.provider_reservations(organization_id,workspace_id,environment_id,run_id,attempt,reservation_id,input_digest,model,cost_policy_version,cost_unit,maximum_tokens,maximum_cost_nano_credits)
    VALUES(o,w,e,r,1,job.reservation_id,decode(substring(job.input_digest FROM 8),'hex'),selection->>'model',bound_value->>'cost_policy_version','openrouter_credit',(bound_value->>'maximum_tokens')::bigint,(bound_value->>'maximum_cost_nano_credits')::bigint);
   UPDATE zasp_temporal78.planning_jobs SET state='prepared',request_body=body_value,request_digest=selection->>'body_digest',lookup_request=selection,pricing_bound=bound_value,input_version=payload->>'input_version' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
  ELSIF job.lookup_request IS DISTINCT FROM selection OR job.input_version IS DISTINCT FROM payload->>'input_version' OR job.pricing_bound IS DISTINCT FROM bound_value THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor intent conflict';END IF;
 END IF;
 IF job.lookup_request IS NOT NULL THEN
  IF job.request_body IS DISTINCT FROM zasp_temporal78.planning_body(job.context_value,job.lookup_request) OR job.request_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.request_body,'UTF8'),'sha256'),'hex') OR job.pricing_bound IS DISTINCT FROM zasp_temporal78.pricing_lookup('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',job.lookup_request) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor pricing drift';END IF;
  SELECT * INTO reservation FROM zasp_temporal78.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1) FOR UPDATE;
  IF (reservation.reservation_id,reservation.input_digest,reservation.model,reservation.cost_policy_version,reservation.maximum_tokens,reservation.maximum_cost_nano_credits) IS DISTINCT FROM (job.reservation_id,decode(substring(job.input_digest FROM 8),'hex'),job.lookup_request->>'model',job.pricing_bound->>'cost_policy_version',(job.pricing_bound->>'maximum_tokens')::bigint,(job.pricing_bound->>'maximum_cost_nano_credits')::bigint) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor reservation drift';END IF;
  IF reservation.settled_at IS NOT NULL AND (reservation.output_digest,reservation.prompt_tokens,reservation.completion_tokens,reservation.total_tokens,reservation.cost_nano_credits) IS DISTINCT FROM (decode(substring(job.provider_digest FROM 8),'hex'),(job.result_value->'usage'->>'prompt_tokens')::bigint,(job.result_value->'usage'->>'completion_tokens')::bigint,(job.result_value->'usage'->>'total_tokens')::bigint,(job.result_value->'usage'->>'cost_nano_credits')::bigint) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor settlement differs from provider evidence';END IF;
 END IF;
 IF op='start' THEN
  IF job.state='prepared' THEN UPDATE zasp_temporal78.planning_jobs SET state='started' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;send_value:=true;
  ELSIF job.state<>'started' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor send unavailable';END IF;
 ELSIF op='result' THEN
  IF NOT zasp_sa_multistep_prior.closed(payload,ARRAY['raw']) OR jsonb_typeof(payload->'raw')<>'string' OR octet_length(payload->>'raw') NOT BETWEEN 1 AND 65536 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='executor result rejected';END IF;
  IF job.state='started' THEN
   cv:=zasp_temporal78.planning_result(payload->>'raw',job.lookup_request->>'model',job.context_value);body_value:=jsonb_build_object('raw',payload->>'raw','candidate',cv->'candidate')::text;
   UPDATE zasp_temporal78.planning_jobs SET state='completed',raw_result=payload->>'raw',result_value=cv,provider_digest='sha256:'||encode(digest(convert_to(payload->>'raw','UTF8'),'sha256'),'hex'),output_body=body_value,output_digest='sha256:'||encode(digest(convert_to(body_value,'UTF8'),'sha256'),'hex') WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
  ELSIF job.raw_result IS DISTINCT FROM payload->>'raw' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor result immutable';END IF;
 ELSIF op='settle' THEN
  IF job.state NOT IN('completed','settled','artifacts') OR job.result_value IS DISTINCT FROM zasp_temporal78.planning_result(job.raw_result,job.lookup_request->>'model',job.context_value) OR job.provider_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.raw_result,'UTF8'),'sha256'),'hex') THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor settlement unavailable';END IF;
  IF job.state='completed' THEN
   cv:=job.result_value->'usage';
   IF cv='null'::jsonb THEN reason:='budget_usage_unknown';ELSE
    UPDATE zasp_temporal78.provider_reservations SET settled_at=clock_timestamp(),output_digest=decode(substring(job.provider_digest FROM 8),'hex'),prompt_tokens=(cv->>'prompt_tokens')::bigint,completion_tokens=(cv->>'completion_tokens')::bigint,total_tokens=(cv->>'total_tokens')::bigint,cost_nano_credits=(cv->>'cost_nano_credits')::bigint WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);
    IF (cv->>'total_tokens')::bigint>least(reservation.maximum_tokens,b.max_tokens) THEN reason:='budget_tokens_exceeded';ELSIF (cv->>'cost_nano_credits')::bigint>least(reservation.maximum_cost_nano_credits,b.max_cost_nano_credits) THEN reason:='budget_cost_exceeded';END IF;
   END IF;
   UPDATE zasp_temporal78.planning_jobs SET state='settled' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
   IF reason IS NOT NULL OR job.result_value->'candidate'='null'::jsonb THEN
    IF reason IS NOT NULL THEN UPDATE public.zasp_security_agent_run_budgets SET stop_reason=reason WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);END IF;
    PERFORM zasp_temporal78.planning_terminal(o,w,e,r,coalesce(reason,'planner_rejected'));
    SELECT * INTO job FROM zasp_temporal78.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
   END IF;
  END IF;
 ELSIF op='artifacts' THEN
  IF job.state NOT IN('settled','artifacts') OR NOT zasp_sa_multistep_prior.closed(payload,ARRAY['input_version','output_version','output_digest']) OR payload->>'input_version' IS DISTINCT FROM job.input_version OR payload->>'output_digest' IS DISTINCT FROM job.output_digest OR jsonb_typeof(payload->'output_version')<>'string' OR length(payload->>'output_version') NOT BETWEEN 1 AND 1024 OR payload->>'output_version'!~'^[!-~]+$' OR job.output_version IS NOT NULL AND job.output_version IS DISTINCT FROM payload->>'output_version' THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor artifact conflict';END IF;
  UPDATE zasp_temporal78.planning_jobs SET state='artifacts',output_version=payload->>'output_version' WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
 ELSIF op='admit' THEN
  IF job.state NOT IN('artifacts','admitted') OR job.output_digest IS DISTINCT FROM 'sha256:'||encode(digest(convert_to(job.output_body,'UTF8'),'sha256'),'hex') OR job.output_body IS DISTINCT FROM jsonb_build_object('raw',job.raw_result,'candidate',job.result_value->'candidate')::text THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor immutable result unavailable';END IF;
  receipt_value:=zasp_temporal78.admit('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',jsonb_build_object('organization_id',o,'workspace_id',w,'environment_id',e,'run_id',r,'definition_id',rr.definition_id,'definition_version',rr.definition_version,'trigger_id',rr.trigger_id,'attempt',1,'run_version',job.run_version,'input_digest',job.input_digest,'output_digest',job.provider_digest,'model',job.lookup_request->>'model','policy_version',job.lookup_request->>'request_policy_version','candidate',job.result_value->'candidate'));
  UPDATE zasp_temporal78.planning_jobs SET state='admitted',receipt=receipt_value WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r) RETURNING * INTO job;
 END IF;
 IF b.deadline_at<=clock_timestamp() OR zasp_temporal78.context(o,w,e,r) IS DISTINCT FROM job.context_value OR NOT zasp_temporal78.current_ready() OR job.lookup_request IS NOT NULL AND job.pricing_bound IS DISTINCT FROM zasp_temporal78.pricing_lookup('033bf2ffa9d4a60121d4f20436ff7de36d1421b62f849254a09048caf75998e6','6b6a74cba9ee791d8b23c08df2f3d08949a339e23460694bc0e2d2d3f25c8e92',job.lookup_request) THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='executor planning authority expired after wait';END IF;
 IF op='admit' THEN RETURN job.receipt;END IF;
 IF op='start' THEN RETURN to_jsonb(job)||jsonb_build_object('send_permit',send_value);END IF;
 RETURN to_jsonb(job);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.planning_state(q jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE x zasp_temporal78.run_owners%ROWTYPE;j zasp_temporal78.planning_jobs%ROWTYPE;k text;
BEGIN
 PERFORM pg_advisory_xact_lock_shared(hashtextextended('zasp-schema-migrations',0));
 IF NOT zasp_temporal78.current_ready() OR NOT(zasp_temporal68.principal_ready('zasp_temporal_executor') OR zasp_temporal68.principal_ready('zasp_temporal_compensation')) THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='single-test planning read rejected';END IF;
 IF NOT zasp_sa_multistep_prior.closed(q,ARRAY['organization_id','workspace_id','environment_id','run_id','definition_version']) OR octet_length(q::text)>4096 THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test planning read shape rejected';END IF;
 FOREACH k IN ARRAY ARRAY['organization_id','workspace_id','environment_id','run_id'] LOOP IF jsonb_typeof(q->k) IS DISTINCT FROM 'string' OR NOT COALESCE(public.zasp_valid_product_id(q->>k),false) THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='single-test planning read scope rejected';END IF;END LOOP;
 SELECT * INTO x FROM zasp_temporal78.run_owners WHERE (organization_id,workspace_id,environment_id,run_id)=(q->>'organization_id',q->>'workspace_id',q->>'environment_id',q->>'run_id') AND to_jsonb(definition_version)=q->'definition_version';
 IF x.run_id IS NULL THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='single-test planning owner changed';END IF;
 SELECT * INTO j FROM zasp_temporal78.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id,definition_version)=(x.organization_id,x.workspace_id,x.environment_id,x.run_id,x.definition_version);
 IF NOT FOUND THEN RETURN 'null'::jsonb;END IF;
 RETURN to_jsonb(j);
END $function$

CREATE OR REPLACE FUNCTION zasp_temporal78.planning_terminal_valid(o text, w text, e text, r text)
 RETURNS boolean
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE a public.zasp_security_agent_audit%ROWTYPE;j zasp_temporal78.planning_jobs%ROWTYPE;p zasp_temporal78.provider_reservations%ROWTYPE;
BEGIN
 SELECT * INTO j FROM zasp_temporal78.planning_jobs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r);
 SELECT * INTO p FROM zasp_temporal78.provider_reservations WHERE (organization_id,workspace_id,environment_id,run_id,attempt)=(o,w,e,r,1);
 SELECT * INTO a FROM public.zasp_security_agent_audit WHERE (organization_id,workspace_id,environment_id,run_id,event_kind)=(o,w,e,r,'temporal_planning_terminal');
 IF EXISTS(SELECT 1 FROM zasp_temporal78.planning_late_usage WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)) THEN
  IF NOT zasp_temporal78.late_usage_valid(o,w,e,r) THEN RETURN false;END IF;
  -- The first terminal evidence remains authoritative for what was known at
  -- that instant. The separate immutable ledger proves the later charge.
  p:=jsonb_populate_record(NULL::zasp_temporal78.provider_reservations,a.body->'reservation');
 END IF;
 RETURN COALESCE(j.state='needs_human' AND a.audit_id=public.zasp_discovery_canonical_id(o,w,e,'security_agent_temporal_planning_terminal',r) AND a.correlation_id=a.audit_id AND a.event_digest=digest(convert_to(a.body::text,'UTF8'),'sha256')
  AND a.body=jsonb_build_object('job',to_jsonb(j),'reservation',CASE WHEN p.run_id IS NULL THEN 'null'::jsonb ELSE to_jsonb(p) END,'reason',(SELECT last_error_code FROM public.zasp_security_agent_runs WHERE (organization_id,workspace_id,environment_id,run_id)=(o,w,e,r)),'dispatch_state',a.body->>'dispatch_state')
  AND j.input_digest='sha256:'||encode(digest(convert_to(j.input_body,'UTF8'),'sha256'),'hex') AND j.input_body=j.context_value::text
  AND CASE WHEN a.body->>'reason'='planner_not_sent' THEN j.raw_result IS NULL AND j.result_value IS NULL AND j.provider_digest IS NULL AND j.output_body IS NULL AND j.output_digest IS NULL
   AND (a.body->>'dispatch_state'='loaded' AND j.lookup_request IS NULL AND j.pricing_bound IS NULL AND j.request_body IS NULL AND j.request_digest IS NULL AND j.input_version IS NULL AND p.run_id IS NULL
    OR a.body->>'dispatch_state'='prepared' AND j.lookup_request IS NOT NULL AND j.pricing_bound IS NOT NULL AND j.input_version IS NOT NULL AND p.released_at IS NOT NULL AND p.settled_at IS NULL AND p.output_digest IS NULL AND p.total_tokens IS NULL AND p.cost_nano_credits IS NULL)
   ELSE a.body->>'dispatch_state' IN('started','completed','settled','artifacts') AND p.released_at IS NULL
    AND (j.raw_result IS NULL AND p.settled_at IS NULL AND p.total_tokens IS NULL AND p.cost_nano_credits IS NULL OR j.raw_result IS NOT NULL AND j.provider_digest='sha256:'||encode(digest(convert_to(j.raw_result,'UTF8'),'sha256'),'hex') AND j.result_value=zasp_temporal78.planning_result(j.raw_result,j.lookup_request->>'model',j.context_value)
     AND (j.result_value->'usage'='null'::jsonb AND p.settled_at IS NULL OR j.result_value->'usage'<>'null'::jsonb AND p.settled_at IS NOT NULL AND (p.total_tokens,p.cost_nano_credits)=((j.result_value->'usage'->>'total_tokens')::bigint,(j.result_value->'usage'->>'cost_nano_credits')::bigint))) END,false);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_ack_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, worker_value text, lease_token_value text, provider_ack_digest_value bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE delivery_row zasp_runtime_deliveries%ROWTYPE;result_value jsonb;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR octet_length(provider_ack_digest_value)<>32 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id,existing.batch_generation,existing.message_id,existing.message_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value) FOR UPDATE;
 IF FOUND AND delivery_row.disposition='acked' AND delivery_row.provider_ack_digest=provider_ack_digest_value THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',true);END IF;
 IF NOT FOUND OR delivery_row.disposition<>'ack_pending' OR delivery_row.lease_owner<>worker_value OR delivery_row.lease_token<>lease_token_value OR delivery_row.lease_expires_at<=transaction_timestamp() OR delivery_row.visibility_deadline<=transaction_timestamp() OR NOT EXISTS(SELECT 1 FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) AND authority_row.state IN('succeeded','failed','quarantined') AND authority_row.completion_digest IS NOT NULL) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery lease missing';END IF;
 UPDATE zasp_runtime_deliveries existing SET disposition='acked',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,provider_ack_digest=provider_ack_digest_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','acked','replayed',false);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_ack_outbox(topic_value text, organization_value text, workspace_value text, environment_value text, outbox_value text, worker_value text, lease_token_value text, provider_ack_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE result jsonb;remaining_count integer;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF topic_value<>'runtime-events' OR provider_ack_value !~ '^sha256:[0-9a-f]{64}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='invalid runtime outbox acknowledgement';END IF;
 IF NOT pg_has_role(session_user,'zasp_outbox_worker','MEMBER') AND NOT pg_has_role(session_user,'zasp_discovery_authority','MEMBER') THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime outbox authority denied';END IF;
 IF NOT EXISTS(SELECT 1 FROM zasp_discovery_outbox WHERE (organization_id,workspace_id,environment_id,id,topic)=(organization_value,workspace_value,environment_value,outbox_value,topic_value)) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime outbox lease missing';END IF;
 result:=zasp_discovery_ack_outbox(organization_value,workspace_value,environment_value,outbox_value,worker_value,lease_token_value,provider_ack_value);
 SELECT count(*) INTO remaining_count FROM zasp_discovery_outbox WHERE topic=topic_value AND state='leased' AND lease_owner=worker_value AND lease_token=lease_token_value AND lease_expires_at>transaction_timestamp();
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN result||jsonb_build_object('remaining_count',remaining_count);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_authenticate_sensor(locator_value bytea, secret_value bytea, audience_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE locator_hash bytea;candidate_scope record;token_row zasp_sensor_tokens%ROWTYPE;sensor_row zasp_sensors%ROWTYPE;computed_hash bytea;
BEGIN
 IF octet_length(locator_value)<>16 OR octet_length(secret_value)<>32 OR audience_value<>'event-ingest' THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 locator_hash:=digest(locator_value,'sha256');
 SELECT token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.sensor_id INTO candidate_scope FROM zasp_sensor_tokens token_value WHERE token_value.locator_digest=locator_hash;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),candidate_scope.organization_id,candidate_scope.workspace_id,candidate_scope.environment_id,candidate_scope.sensor_id),0));
 SELECT token_value.* INTO token_row FROM zasp_sensor_tokens token_value WHERE token_value.locator_digest=locator_hash FOR UPDATE;
 SELECT sensor_value.* INTO sensor_row FROM zasp_sensors sensor_value WHERE (sensor_value.organization_id,sensor_value.workspace_id,sensor_value.environment_id,sensor_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id) FOR UPDATE;
 computed_hash:=zasp_runtime_sensor_secret_hash(audience_value,token_row.id,token_row.token_generation,token_row.salt,secret_value);
 IF token_row.format_version<>1 OR token_row.audience<>audience_value OR token_row.revoked_at IS NOT NULL OR token_row.expires_at<=transaction_timestamp()
  OR token_row.sensor_version_at_issue<>sensor_row.version OR sensor_row.state NOT IN('pending','active','degraded')
  OR digest(token_row.token_hash||computed_hash,'sha256')<>digest(token_row.token_hash||token_row.token_hash,'sha256')
  OR EXISTS(SELECT 1 FROM zasp_sensor_tokens newer WHERE (newer.organization_id,newer.workspace_id,newer.environment_id,newer.sensor_id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.sensor_id) AND newer.token_generation>token_row.token_generation)
 THEN RAISE EXCEPTION USING ERRCODE='28000',MESSAGE='sensor authentication rejected';END IF;
 UPDATE zasp_sensor_tokens token_value SET last_authenticated_at=transaction_timestamp() WHERE (token_value.organization_id,token_value.workspace_id,token_value.environment_id,token_value.id)=(token_row.organization_id,token_row.workspace_id,token_row.environment_id,token_row.id);
 PERFORM zasp_runtime_mark_used();
 RETURN jsonb_build_object('organization_id',token_row.organization_id,'workspace_id',token_row.workspace_id,'environment_id',token_row.environment_id,'sensor_id',token_row.sensor_id,'sensor_kind',sensor_row.kind,'sensor_mode',sensor_row.mode,'sensor_version',sensor_row.version,'token_id',token_row.id,'token_generation',token_row.token_generation,'audience',token_row.audience);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_claim_delivery(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, message_value text, message_digest_value bytea, receive_count_value integer, worker_value text, lease_token_value text, lease_seconds integer, visibility_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;delivery_row zasp_runtime_deliveries%ROWTYPE;outbox_digest bytea;disposition_value text;replayed_value boolean:=false;lease_expires_value timestamptz;visibility_deadline_value timestamptz;
BEGIN
 PERFORM zasp_runtime_precision_transport_ready();
 IF NOT zasp_runtime_principal_ready('zasp_runtime_coordinator') OR NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR message_value !~ '^[A-Za-z0-9_-]{1,128}$' OR octet_length(message_digest_value)<>32 OR receive_count_value NOT BETWEEN 1 AND 100 OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR visibility_seconds<lease_seconds OR visibility_seconds>43200 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime delivery authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended(concat_ws(chr(31),'zasp-runtime-delivery',organization_value,workspace_value,environment_value,batch_value),0));
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(organization_value,workspace_value,environment_value,batch_value,generation_value) FOR UPDATE;
 IF NOT FOUND OR batch_row.state='uploading' THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime delivery missing';END IF;
 SELECT outbox.payload_digest INTO outbox_digest FROM zasp_discovery_outbox outbox WHERE (outbox.organization_id,outbox.workspace_id,outbox.environment_id,outbox.topic,outbox.deterministic_key,outbox.payload_version)=(organization_value,workspace_value,environment_value,'runtime-events','runtime:'||batch_value,15);
 IF NOT FOUND OR outbox_digest IS DISTINCT FROM message_digest_value THEN
  IF batch_row.state NOT IN('succeeded','failed','unknown','quarantined') THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value);END IF;
  PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 SELECT * INTO delivery_row FROM zasp_runtime_deliveries existing WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value) FOR UPDATE;
 -- v36: exact durable outbox identity permits at-least-once publication.
 IF FOUND AND delivery_row.batch_generation=generation_value AND delivery_row.message_digest=message_digest_value AND delivery_row.message_id<>message_value THEN
  IF batch_row.state='unknown' OR delivery_row.disposition='unknown' THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF batch_row.state IN('succeeded','failed','quarantined') THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);
  END IF;
  IF delivery_row.disposition NOT IN('held','ack_pending') THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',true);
  END IF;
  IF delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp() THEN
   PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_duplicate','replayed',true);
  END IF;
  UPDATE zasp_runtime_deliveries existing SET message_id=message_value,receive_count=receive_count_value,provider_ack_digest=NULL,lease_expires_at=transaction_timestamp()
   WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  delivery_row.message_id:=message_value;delivery_row.receive_count:=receive_count_value;delivery_row.lease_expires_at:=transaction_timestamp();
 END IF;
 IF FOUND AND (delivery_row.batch_generation,delivery_row.message_id,delivery_row.message_digest) IS DISTINCT FROM (generation_value,message_value,message_digest_value) THEN
  UPDATE zasp_runtime_deliveries existing SET disposition='quarantined',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,visibility_deadline=NULL,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
  UPDATE zasp_runtime_batch_authorities authority_row SET state='quarantined',completed_at=transaction_timestamp(),completion_digest=digest(convert_to(concat_ws(chr(31),organization_value,workspace_value,environment_value,batch_value,generation_value::text,message_value,encode(message_digest_value,'hex'),'delivery-drift'),'UTF8'),'sha256'),completion_result=jsonb_build_object('batch_id',batch_value,'generation',generation_value,'state','quarantined','error_class','malformed') WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(organization_value,workspace_value,environment_value,batch_value) AND authority_row.state NOT IN('succeeded','failed','unknown','quarantined');
  PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','quarantined','replayed',false);
 END IF;
 IF FOUND AND receive_count_value<delivery_row.receive_count THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime delivery conflict';END IF;
 IF FOUND AND delivery_row.disposition='acked' THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','ack_terminal','replayed',true);END IF;
 IF batch_row.state='unknown' OR FOUND AND delivery_row.disposition='unknown' THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','unknown','replayed',FOUND);END IF;
 IF FOUND AND delivery_row.disposition IN('held','ack_pending') AND delivery_row.lease_expires_at>transaction_timestamp() AND (delivery_row.lease_owner,delivery_row.lease_token) IS DISTINCT FROM (worker_value,lease_token_value) THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false,'lease_expires_at',delivery_row.lease_expires_at);END IF;
 IF EXISTS(SELECT 1 FROM zasp_runtime_deliveries other WHERE other.organization_id=organization_value AND other.batch_id<>batch_value AND other.disposition IN('held','ack_pending') AND other.lease_expires_at>transaction_timestamp()) THEN PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition','busy','replayed',false);END IF;
 disposition_value:=CASE WHEN batch_row.state IN('succeeded','failed','quarantined') THEN 'ack_pending' ELSE 'held' END;
 lease_expires_value:=transaction_timestamp()+make_interval(secs=>lease_seconds);visibility_deadline_value:=transaction_timestamp()+make_interval(secs=>visibility_seconds);
 IF FOUND THEN
  replayed_value:=delivery_row.receive_count=receive_count_value AND delivery_row.disposition=disposition_value AND (delivery_row.lease_owner,delivery_row.lease_token) IS NOT DISTINCT FROM (worker_value,lease_token_value);
  UPDATE zasp_runtime_deliveries existing SET receive_count=GREATEST(existing.receive_count,receive_count_value),disposition=disposition_value,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=lease_expires_value,visibility_deadline=visibility_deadline_value,updated_at=transaction_timestamp() WHERE (existing.organization_id,existing.workspace_id,existing.environment_id,existing.batch_id)=(organization_value,workspace_value,environment_value,batch_value);
 ELSE
  INSERT INTO zasp_runtime_deliveries(organization_id,workspace_id,environment_id,batch_id,batch_generation,message_id,message_digest,receive_count,disposition,lease_owner,lease_token,lease_expires_at,visibility_deadline) VALUES(organization_value,workspace_value,environment_value,batch_value,generation_value,message_value,message_digest_value,receive_count_value,disposition_value,worker_value,lease_token_value,lease_expires_value,visibility_deadline_value);
 END IF;
 PERFORM zasp_runtime_precision_transport_ready();
 RETURN jsonb_build_object('batch_id',batch_value,'generation',generation_value,'disposition',CASE WHEN disposition_value='held' THEN 'claimed' ELSE disposition_value END,'replayed',replayed_value,'lease_expires_at',lease_expires_value,'visibility_deadline',visibility_deadline_value,'artifact_reference',batch_row.raw_artifact_reference,'artifact_key',batch_row.raw_artifact_key,'artifact_version_id',batch_row.raw_artifact_version_id,'artifact_checksum',encode(batch_row.raw_artifact_checksum,'hex'),'artifact_size_bytes',batch_row.raw_artifact_size_bytes,'artifact_kms_key',batch_row.raw_artifact_kms_key,'request_digest',encode(batch_row.request_digest,'hex'));
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_claim_stage_precision_compatible(worker_value text, lease_token_value text, lease_seconds integer, claim_limit integer, expected_stage text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE stage_value text;authority_value text;result_value jsonb;prior_capability text;
BEGIN
 stage_value:=zasp_runtime_stage_for_session();
 IF worker_value IS NULL OR lease_token_value IS NULL OR lease_seconds IS NULL OR claim_limit IS NULL OR expected_stage IS NULL OR stage_value IS DISTINCT FROM expected_stage THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime routing capability rejected';END IF;
 authority_value:=CASE stage_value WHEN 'archive' THEN 'zasp_runtime_archive_worker' WHEN 'index' THEN 'zasp_runtime_index_worker' WHEN 'correlate' THEN 'zasp_runtime_correlation_worker' WHEN 'project' THEN 'zasp_runtime_projection_worker' WHEN 'complete' THEN 'zasp_runtime_coordinator' END;
 IF stage_value IS NULL OR NOT zasp_runtime_principal_ready(authority_value) OR length(worker_value) NOT BETWEEN 1 AND 128 OR worker_value<>btrim(worker_value) OR worker_value~'[[:cntrl:]]' OR length(lease_token_value) NOT BETWEEN 16 AND 128 OR lease_token_value<>btrim(lease_token_value) OR lease_token_value~'[[:cntrl:]]' OR lease_seconds NOT BETWEEN 5 AND 900 OR claim_limit NOT BETWEEN 1 AND 10 THEN RAISE EXCEPTION USING ERRCODE='42501',MESSAGE='runtime stage authority rejected';END IF;
 PERFORM pg_advisory_xact_lock(hashtextextended('zasp-runtime-stage-claim:'||stage_value,0));
 prior_capability:=COALESCE(current_setting('zasp.runtime_precision_claim_version',true),'');
 PERFORM set_config('zasp.runtime_precision_claim_version',CASE stage_value WHEN 'archive' THEN 'runtime-archive-v2' WHEN 'index' THEN 'runtime-index-v2' WHEN 'correlate' THEN 'runtime-correlation-v4' WHEN 'project' THEN 'runtime-projection-v3' WHEN 'complete' THEN 'runtime-complete-v3' END,true);
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
 WITH exhausted AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='failed',last_error_class='exhausted',completed_at=transaction_timestamp(),lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,last_heartbeat_at=NULL,
   completion_digest=digest(convert_to(concat_ws(chr(31),stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation::text,stage_row.stage,stage_row.attempt::text,'exhausted'),'UTF8'),'sha256'),
   completion_result=jsonb_build_object('batch_id',stage_row.batch_id,'generation',stage_row.batch_generation,'stage',stage_row.stage,'state','failed','attempt',stage_row.attempt,'error_class','exhausted')
  WHERE stage_row.stage=stage_value AND (CASE stage_value WHEN 'archive' THEN stage_row.implementation_version IN('runtime-archive-v1','runtime-archive-v2') WHEN 'index' THEN stage_row.implementation_version IN('runtime-index-v1','runtime-index-v2') WHEN 'correlate' THEN stage_row.implementation_version IN('runtime-correlation-v1','runtime-correlation-v2','runtime-correlation-v3','runtime-correlation-v4') WHEN 'project' THEN stage_row.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3') WHEN 'complete' THEN stage_row.implementation_version IN('runtime-complete-v1','runtime-complete-v2','runtime-complete-v3') ELSE false END) AND stage_row.attempt>=100 AND stage_row.state IN('pending','retryable','leased') AND (stage_row.state<>'leased' OR stage_row.lease_expires_at<=transaction_timestamp())
  RETURNING stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.completion_digest,stage_row.completion_result
 ),failed_batches AS (
  UPDATE zasp_runtime_batch_authorities authority_row SET state='failed',completed_at=transaction_timestamp(),completion_digest=exhausted.completion_digest,completion_result=exhausted.completion_result
  FROM exhausted WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(exhausted.organization_id,exhausted.workspace_id,exhausted.environment_id,exhausted.batch_id)
  RETURNING authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.completion_digest,authority_row.completion_result
 ),failed_legacy_batches AS (
  UPDATE zasp_runtime_batches batch_row SET state='failed',completed_at=transaction_timestamp()
  FROM failed_batches WHERE (batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id)
  RETURNING batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.id
 ),failed_jobs AS (
  UPDATE zasp_discovery_jobs job_row SET state='failed',last_error='exhausted',completed_at=transaction_timestamp(),updated_at=transaction_timestamp(),completion_digest=failed_batches.completion_digest,completion_result=failed_batches.completion_result
  FROM failed_batches WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.kind,job_row.authority_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,'runtime',failed_batches.batch_id)
  RETURNING job_row.organization_id
 )
 UPDATE zasp_runtime_deliveries delivery_row SET disposition='ack_pending',updated_at=transaction_timestamp()
 FROM failed_batches WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id)=(failed_batches.organization_id,failed_batches.workspace_id,failed_batches.environment_id,failed_batches.batch_id) AND delivery_row.disposition='held';
 WITH eligible AS (
  SELECT stage_row.ctid row_id,stage_row.*,row_number() OVER(PARTITION BY stage_row.organization_id ORDER BY stage_row.available_at,stage_row.batch_id) organization_rank
  FROM zasp_runtime_stage_work stage_row
  WHERE stage_row.stage=stage_value AND (CASE stage_value WHEN 'archive' THEN stage_row.implementation_version IN('runtime-archive-v1','runtime-archive-v2') WHEN 'index' THEN stage_row.implementation_version IN('runtime-index-v1','runtime-index-v2') WHEN 'correlate' THEN stage_row.implementation_version IN('runtime-correlation-v1','runtime-correlation-v2','runtime-correlation-v3','runtime-correlation-v4') WHEN 'project' THEN stage_row.implementation_version IN('runtime-projection-v1','runtime-projection-v2','runtime-projection-v3') WHEN 'complete' THEN stage_row.implementation_version IN('runtime-complete-v1','runtime-complete-v2','runtime-complete-v3') ELSE false END) AND stage_row.attempt<100 AND stage_row.available_at<=transaction_timestamp() AND (stage_row.state IN('pending','retryable') OR stage_row.state='leased' AND stage_row.lease_expires_at<=transaction_timestamp())
   AND stage_row.input_digest IS NOT NULL
   AND EXISTS(SELECT 1 FROM zasp_runtime_deliveries delivery_row WHERE (delivery_row.organization_id,delivery_row.workspace_id,delivery_row.environment_id,delivery_row.batch_id,delivery_row.batch_generation,delivery_row.disposition)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.batch_generation,'held') AND delivery_row.lease_expires_at>transaction_timestamp() AND delivery_row.visibility_deadline>transaction_timestamp())
   AND (stage_row.stage_order=1 OR EXISTS(SELECT 1 FROM zasp_runtime_stage_work predecessor WHERE (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order,predecessor.state,predecessor.effect_digest)=(stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage_order-1,'succeeded',stage_row.predecessor_digest)))
   AND NOT EXISTS(SELECT 1 FROM zasp_runtime_stage_work live_row WHERE live_row.stage=stage_value AND live_row.organization_id=stage_row.organization_id AND live_row.state='leased' AND live_row.lease_expires_at>transaction_timestamp())
 ),organizations AS (
  SELECT eligible.organization_id,min(eligible.available_at) first_available,MAX(fairness.last_claimed_at) last_claimed_at
  FROM eligible LEFT JOIN zasp_runtime_stage_fairness fairness ON (fairness.stage,fairness.organization_id)=(stage_value,eligible.organization_id)
  WHERE eligible.organization_rank=1 GROUP BY eligible.organization_id
  ORDER BY MAX(fairness.last_claimed_at) NULLS FIRST,min(eligible.available_at),eligible.organization_id LIMIT claim_limit
 ),candidates AS (
  SELECT stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage
  FROM zasp_runtime_stage_work stage_row JOIN eligible ON stage_row.ctid=eligible.row_id JOIN organizations ON organizations.organization_id=eligible.organization_id
  WHERE eligible.organization_rank=1 ORDER BY organizations.last_claimed_at NULLS FIRST,organizations.first_available,stage_row.organization_id,stage_row.batch_id FOR UPDATE OF stage_row SKIP LOCKED
 ),claimed AS (
  UPDATE zasp_runtime_stage_work stage_row SET state='leased',attempt=stage_row.attempt+1,lease_owner=worker_value,lease_token=lease_token_value,lease_expires_at=transaction_timestamp()+make_interval(secs=>lease_seconds),last_heartbeat_at=transaction_timestamp(),last_error_class=NULL
  FROM candidates WHERE (stage_row.organization_id,stage_row.workspace_id,stage_row.environment_id,stage_row.batch_id,stage_row.stage)=(candidates.organization_id,candidates.workspace_id,candidates.environment_id,candidates.batch_id,candidates.stage)
  RETURNING stage_row.*
 ),fairness AS (
  INSERT INTO zasp_runtime_stage_fairness(stage,organization_id,last_claimed_at) SELECT stage_value,claimed.organization_id,transaction_timestamp() FROM claimed
  ON CONFLICT(stage,organization_id) DO UPDATE SET last_claimed_at=excluded.last_claimed_at RETURNING organization_id
 )
 SELECT COALESCE(jsonb_agg(jsonb_build_object('organization_id',claimed.organization_id,'workspace_id',claimed.workspace_id,'environment_id',claimed.environment_id,'batch_id',claimed.batch_id,'generation',claimed.batch_generation,'stage',claimed.stage,'attempt',claimed.attempt,'implementation_version',claimed.implementation_version,'predecessor_digest',CASE WHEN claimed.predecessor_digest IS NULL THEN NULL ELSE encode(claimed.predecessor_digest,'hex') END,'input_digest',encode(claimed.input_digest,'hex'),'input_reference',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_reference ELSE predecessor.result_reference END,'input_version_id',CASE WHEN claimed.stage_order=1 THEN authority_row.raw_artifact_version_id ELSE predecessor.result_version_id END,'lease_expires_at',claimed.lease_expires_at) ORDER BY claimed.organization_id,claimed.batch_id),'[]'::jsonb) INTO result_value
 FROM claimed JOIN zasp_runtime_batch_authorities authority_row ON (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.batch_generation)
 LEFT JOIN zasp_runtime_stage_work predecessor ON (predecessor.organization_id,predecessor.workspace_id,predecessor.environment_id,predecessor.batch_id,predecessor.stage_order)=(claimed.organization_id,claimed.workspace_id,claimed.environment_id,claimed.batch_id,claimed.stage_order-1);
 IF stage_value='archive' AND jsonb_array_length(result_value)>0 THEN UPDATE zasp_runtime_batch_authorities authority_row SET state='processing' WHERE EXISTS(SELECT 1 FROM jsonb_array_elements(result_value) item WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(item->>'organization_id',item->>'workspace_id',item->>'environment_id',item->>'batch_id'));END IF;
 PERFORM set_config('zasp.runtime_precision_claim_version',prior_capability,true);
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime precision authority unavailable';END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_commit_reserved_batch(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, request_digest_value bytea, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE batch_row zasp_runtime_batch_authorities%ROWTYPE;event_payload jsonb;result_value jsonb;
BEGIN
 IF NOT zasp_valid_product_id(organization_value) OR NOT zasp_valid_product_id(workspace_value) OR NOT zasp_valid_product_id(environment_value) OR NOT zasp_valid_product_id(batch_value) OR generation_value<1 OR octet_length(request_digest_value)<>32 OR NOT zasp_valid_product_id(job_value) OR NOT zasp_valid_product_id(outbox_value) OR NOT zasp_discovery_s3_object_reference(artifact_reference_value) OR length(artifact_key_value) NOT BETWEEN 32 AND 1024 OR right(artifact_reference_value,length(artifact_key_value)+1)<>'/'||artifact_key_value OR length(artifact_version_value) NOT BETWEEN 1 AND 1024 OR artifact_version_value<>btrim(artifact_version_value) OR octet_length(artifact_checksum_value)<>32 OR artifact_size_value NOT BETWEEN 1 AND 67108864 OR artifact_kms_key_value !~ '^arn:aws:kms:[a-z0-9-]+:[0-9]{12}:key/[A-Za-z0-9-]{8,128}$' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime batch rejected';END IF;
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id,authority_row.batch_generation,authority_row.request_digest)=(organization_value,workspace_value,environment_value,batch_value,generation_value,request_digest_value) FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime batch rejected';END IF;
 IF batch_row.payload_schema_version='runtime-event-v2' AND batch_row.source_kind<>'tetragon' THEN RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime precision source rejected';END IF;
IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_runtime_precision_transport_ready();END IF;
 IF batch_row.state NOT IN('uploading','unknown') THEN
  IF batch_row.state IN('queued','processing','succeeded','failed','quarantined') AND (batch_row.raw_artifact_reference,batch_row.raw_artifact_key,batch_row.raw_artifact_version_id,batch_row.raw_artifact_checksum,batch_row.raw_artifact_size_bytes,batch_row.raw_artifact_kms_key) IS NOT DISTINCT FROM (artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value)
   AND EXISTS(SELECT 1 FROM zasp_discovery_jobs job_row WHERE (job_row.organization_id,job_row.workspace_id,job_row.environment_id,job_row.id,job_row.kind,job_row.authority_id)=(organization_value,workspace_value,environment_value,job_value,'runtime',batch_value))
   AND EXISTS(SELECT 1 FROM zasp_discovery_outbox outbox_row WHERE (outbox_row.organization_id,outbox_row.workspace_id,outbox_row.environment_id,outbox_row.id,outbox_row.topic,outbox_row.deterministic_key,outbox_row.payload_version)=(organization_value,workspace_value,environment_value,outbox_value,'runtime-events','runtime:'||batch_value,15))
  THEN IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_runtime_precision_transport_ready();END IF; RETURN jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state',batch_row.state,'replayed',true);END IF;
  RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';
 END IF;
 IF (batch_row.raw_artifact_key,batch_row.content_digest,batch_row.payload_size_bytes) IS DISTINCT FROM (artifact_key_value,artifact_checksum_value,artifact_size_value) THEN RAISE EXCEPTION USING ERRCODE='23505',MESSAGE='runtime batch conflict';END IF;
 INSERT INTO zasp_runtime_batches(organization_id,workspace_id,environment_id,id,sensor_id,idempotency_key,payload_digest,event_count,payload_reference,payload_size_bytes,payload_media_type,payload_schema_version)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.sensor_id,batch_row.idempotency_key,batch_row.content_digest,batch_row.event_count,artifact_reference_value,batch_row.payload_size_bytes,batch_row.payload_media_type,batch_row.payload_schema_version);
 INSERT INTO zasp_discovery_jobs(organization_id,workspace_id,environment_id,id,kind,authority_id,idempotency_key,request_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,job_value,'runtime',batch_row.batch_id,batch_row.idempotency_key,batch_row.request_digest);
 INSERT INTO zasp_runtime_stage_work(organization_id,workspace_id,environment_id,batch_id,batch_generation,stage,stage_order,implementation_version,input_digest)
 SELECT batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.batch_generation,stage_value.stage,stage_value.stage_order,CASE WHEN batch_row.payload_schema_version='runtime-event-v2' THEN CASE stage_value.stage WHEN 'archive' THEN 'runtime-archive-v2' WHEN 'index' THEN 'runtime-index-v2' WHEN 'correlate' THEN 'runtime-correlation-v4' WHEN 'project' THEN 'runtime-projection-v3' WHEN 'complete' THEN 'runtime-complete-v3' END WHEN batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN CASE stage_value.stage WHEN 'archive' THEN 'runtime-archive-v1' WHEN 'index' THEN 'runtime-index-v1' WHEN 'correlate' THEN 'runtime-correlation-v3' WHEN 'project' THEN 'runtime-projection-v2' WHEN 'complete' THEN 'runtime-complete-v2' END ELSE stage_value.version_value END,CASE WHEN stage_value.stage_order=1 THEN batch_row.content_digest ELSE NULL END
 FROM (VALUES('archive',1,'runtime-archive-v1'),('index',2,'runtime-index-v1'),('correlate',3,'runtime-correlation-v2'),('project',4,'runtime-projection-v1'),('complete',5,'runtime-complete-v1')) stage_value(stage,stage_order,version_value);
 event_payload:=jsonb_build_object('batch_id',batch_row.batch_id,'job_id',job_value,'generation',batch_row.batch_generation,'pipeline_version',15,'artifact_reference',artifact_reference_value,'artifact_key',artifact_key_value,'artifact_version_id',artifact_version_value,'artifact_checksum',encode(artifact_checksum_value,'hex'),'artifact_size_bytes',artifact_size_value,'payload_media_type',batch_row.payload_media_type,'payload_schema_version',batch_row.payload_schema_version,'event_count',batch_row.event_count,'request_digest',encode(batch_row.request_digest,'hex'));
 INSERT INTO zasp_discovery_outbox(organization_id,workspace_id,environment_id,id,topic,deterministic_key,payload_version,payload,payload_digest)
 VALUES(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,outbox_value,'runtime-events','runtime:'||batch_row.batch_id,15,event_payload,digest(convert_to(event_payload::text,'UTF8'),'sha256'));
 UPDATE zasp_runtime_batch_authorities authority_row SET raw_artifact_reference=artifact_reference_value,raw_artifact_version_id=artifact_version_value,raw_artifact_checksum=artifact_checksum_value,raw_artifact_size_bytes=artifact_size_value,raw_artifact_kms_key=artifact_kms_key_value,state='queued',finalized_at=transaction_timestamp() WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id);
 result_value:=jsonb_build_object('batch_id',batch_row.batch_id,'generation',batch_row.batch_generation,'state','queued','replayed',false);
IF batch_row.payload_schema_version='runtime-event-v2' OR batch_row.source_kind='otlp' AND batch_row.payload_schema_version='runtime-event-v1' THEN PERFORM zasp_runtime_precision_transport_ready();END IF;
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_finalize_batch_v15_internal(locator_value bytea, secret_value bytea, audience_value text, batch_value text, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;batch_row zasp_runtime_batch_authorities%ROWTYPE;
BEGIN
 authority_value:=zasp_runtime_authenticate_sensor(locator_value,secret_value,audience_value);
 SELECT * INTO batch_row FROM zasp_runtime_batch_authorities authority_row WHERE (authority_row.organization_id,authority_row.workspace_id,authority_row.environment_id,authority_row.batch_id)=(authority_value->>'organization_id',authority_value->>'workspace_id',authority_value->>'environment_id',batch_value);
 IF NOT FOUND OR (batch_row.sensor_id,batch_row.sensor_token_id,batch_row.token_generation) IS DISTINCT FROM (authority_value->>'sensor_id',authority_value->>'token_id',(authority_value->>'token_generation')::bigint) THEN RAISE EXCEPTION USING ERRCODE='P0002',MESSAGE='runtime batch rejected';END IF;
 RETURN zasp_runtime_commit_reserved_batch(batch_row.organization_id,batch_row.workspace_id,batch_row.environment_id,batch_row.batch_id,batch_row.batch_generation,batch_row.request_digest,job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_finalize_batch_v17(locator_value bytea, secret_value bytea, audience_value text, batch_value text, job_value text, outbox_value text, artifact_reference_value text, artifact_key_value text, artifact_version_value text, artifact_checksum_value bytea, artifact_size_value bigint, artifact_kms_key_value text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE authority_value jsonb;result_value jsonb;work_value zasp_runtime_ingest_reconciliation_work%ROWTYPE;
BEGIN
 UPDATE zasp_runtime_ingest_reconciliation_state SET used_at=COALESCE(used_at,transaction_timestamp()) WHERE singleton;
 authority_value:=zasp_runtime_authenticate_sensor(locator_value,secret_value,audience_value);
 SELECT * INTO work_value FROM zasp_runtime_ingest_reconciliation_work work_row WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id)=(authority_value->>'organization_id',authority_value->>'workspace_id',authority_value->>'environment_id',batch_value) FOR UPDATE;
 IF FOUND AND work_value.state='leased' AND work_value.lease_expires_at>transaction_timestamp() THEN RAISE EXCEPTION USING ERRCODE='40001',MESSAGE='runtime batch finalize leased';END IF;
 result_value:=zasp_runtime_finalize_batch_v15_internal(locator_value,secret_value,audience_value,batch_value,job_value,outbox_value,artifact_reference_value,artifact_key_value,artifact_version_value,artifact_checksum_value,artifact_size_value,artifact_kms_key_value);
 UPDATE zasp_runtime_ingest_reconciliation_work work_row SET state='succeeded',lease_owner=NULL,lease_token=NULL,lease_expires_at=NULL,completion_worker='request',completion_token_digest=digest(convert_to('request','UTF8'),'sha256'),completion_digest=digest(convert_to(result_value::text,'UTF8'),'sha256'),completion_result=result_value,completed_at=transaction_timestamp()
 WHERE (work_row.organization_id,work_row.workspace_id,work_row.environment_id,work_row.batch_id,work_row.batch_generation)=(authority_value->>'organization_id',authority_value->>'workspace_id',authority_value->>'environment_id',batch_value,(result_value->>'generation')::bigint) AND work_row.state NOT IN('succeeded','quarantined');
 RETURN result_value;
END $function$

CREATE OR REPLACE FUNCTION public.zasp_runtime_finish_precise_session_projection(organization_value text, workspace_value text, environment_value text, batch_value text, generation_value bigint, worker_value text, lease_token_value text, attempt_value integer, input_digest_value bytea, implementation_value text, outcome_value text, effect_digest_value bytea, result_reference_value text, result_version_value text, result_digest_value bytea, error_class_value text, retry_after_seconds integer, receipt_bytes bytea)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE predecessor zasp_runtime_stage_work%ROWTYPE;complete_row zasp_runtime_stage_work%ROWTYPE;receipt_value jsonb;item jsonb;event_value zasp_runtime_session_events%ROWTYPE;retained zasp_runtime_session_events%ROWTYPE;result_value jsonb;ids text[]:='{}';digest_value bytea;
BEGIN
 IF NOT COALESCE(zasp_production_runtime_precision_readiness((SELECT checksum FROM zasp_schema_versions WHERE version=51),(SELECT value FROM zasp_schema_metadata WHERE key='production_runtime_precision_fingerprint')),false) THEN RAISE EXCEPTION USING ERRCODE='55000',MESSAGE='runtime sandbox authority unavailable';END IF;
 IF num_nulls(organization_value,workspace_value,environment_value,batch_value,generation_value,worker_value,lease_token_value,attempt_value,input_digest_value,implementation_value,outcome_value,effect_digest_value,result_reference_value,result_version_value,result_digest_value,retry_after_seconds,receipt_bytes)>0
 OR NOT COALESCE(zasp_runtime_principal_ready('zasp_runtime_coordinator') AND zasp_runtime_stage_for_session()='complete' AND outcome_value='succeeded' AND implementation_value='runtime-complete-v3' AND octet_length(receipt_bytes) BETWEEN 1 AND 4194304,false) THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session projection authority rejected';
 END IF;
 SELECT * INTO predecessor FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'project') FOR SHARE;
 IF NOT FOUND OR predecessor.state<>'succeeded' OR predecessor.implementation_version<>'runtime-projection-v3' OR predecessor.result_digest IS DISTINCT FROM digest(receipt_bytes,'sha256') OR predecessor.effect_digest IS DISTINCT FROM input_digest_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session predecessor receipt rejected';
 END IF;
 SELECT * INTO complete_row FROM zasp_runtime_stage_work WHERE (organization_id,workspace_id,environment_id,batch_id,batch_generation,stage)=(organization_value,workspace_value,environment_value,batch_value,generation_value,'complete') FOR UPDATE;
 IF NOT FOUND OR complete_row.implementation_version<>'runtime-complete-v3' OR complete_row.predecessor_digest IS DISTINCT FROM predecessor.effect_digest OR complete_row.input_digest IS DISTINCT FROM input_digest_value THEN
  RAISE EXCEPTION USING ERRCODE='22023',MESSAGE='runtime session receipt binding rejected';
 END IF;
 receipt_value:=convert_from(receipt_bytes,'UTF8')::jsonb;
 IF NOT COALESCE(jsonb_typeof(receipt_value)='object' AND receipt_value->>'schema'='runtime-projection-receipt-v3' AND receipt_value->>'implementation_version'='runtime-projection-v3'
 AND (receipt_value->>'organization_id',receipt_value->>'workspace_id',receipt_value->>'environment_id',receipt_value->>'batch_id')=(organization_value,workspace_value,environment_value,batch_value)
